import type { Question } from "@/types/question";

export const questions = [{"id":"2024-36-001","examYear":"2024","examRound":"36","questionNumber":1,"category":"人間の尊厳と自立","questionText":"Ａさん（76歳、女性、要支援1）は、一人暮らしである。週1回介護予防通所リハビリテーションを利用しながら、近所の友人たちとの麻雀｛まーじゃん｝を楽しみに生活している。最近、膝に痛みを感じ、変形性膝関節症（knee osteoarthritis）と診断された。同時期に友人が入院し、楽しみにしていた麻雀｛まーじゃん｝ができなくなった。Ａさんは徐々に今後の生活に不安を感じるようになった。ある日、「自宅で暮らし続けたいけど、心配なの…」と介護福祉職に話した。\nＡさんに対する介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"要介護認定の申請を勧める。"},{"id":"2","text":"友人のお見舞いを勧める。"},{"id":"3","text":"膝の精密検査を勧める。"},{"id":"4","text":"別の趣味活動の希望を聞く。"},{"id":"5","text":"生活に対する思いを聞く。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、「自宅で暮らし続けたいけど、心配なの…」と不安を話しているね。まずは、Ａさんの生活に対する思いをじっくり聞いて、受け止めることが大切なんだ。1、3は、まだ判断するのが早いよ。2、4は、Ａさんの不安の根っこに向き合わずに、別の話へ進めてしまっているね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-002","examYear":"2024","examRound":"36","questionNumber":2,"category":"人間の尊厳と自立","questionText":"次の記述のうち、介護を必要とする人の自立についての考え方として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自立は、他者の支援を受けないことである。"},{"id":"2","text":"精神的自立は、生活の目標をもち、自らが主体となって物事を進めていくことである。"},{"id":"3","text":"社会的自立は、社会的な役割から離れて自由になることである。"},{"id":"4","text":"身体的自立は、介護者の身体的負担を軽減することである。"},{"id":"5","text":"経済的自立は、経済活動や社会活動に参加せずに、生活を営むことである。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！精神的自立は、生活の目標をもって、自分が主体になって物事を進めていくことなんだ。1は、支援を受けても、自立はできる。3の社会的自立は、社会の中で役割をもつこと。4の身体的自立は、自分で身体を動かすこと。5の経済的自立は、経済活動や社会活動に参加して生活することだよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-003","examYear":"2024","examRound":"36","questionNumber":3,"category":"人間関係とコミュニケーション","questionText":"Ｕ介護老人福祉施設では、利用者の介護計画を担当の介護福祉職が作成している。このため、利用者の個別の介護目標を、介護福祉職のチーム全員で共有することが課題になっている。\nこの課題を解決するための取り組みとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"管理職がチーム全体に注意喚起して、集団規範を形成する。"},{"id":"2","text":"現場経験の長い介護福祉職の意見を優先して、同調行動を促す。"},{"id":"3","text":"チームメンバーの懇談会を実施して、内集団バイアスを強化する。"},{"id":"4","text":"チームメンバー間の集団圧力を利用して、多数派の意見に統一する。"},{"id":"5","text":"担当以外のチームメンバーもカンファレンス（conference）に参加して、集団凝集性を高める。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！担当以外のメンバーもカンファレンスに参加すると、目標を共有できて、チームのまとまり（集団凝集性）が高まるんだ。1は、上から注意しても、納得は得られない。2、4は、意見を押しつけることになる。3は、内集団バイアスは、仲間びいきで、偏りが強まってしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-004","examYear":"2024","examRound":"36","questionNumber":4,"category":"人間関係とコミュニケーション","questionText":"Ｂさん（90歳、女性、要介護3）は、介護老人福祉施設に入所している。入浴日に、担当の介護福祉職が居室を訪問し、「Ｂさん、今日はお風呂の日です。時間は午後3時からです」と伝えた。しかし、Ｂさんは言っていることがわからなかったようで、「はい、何ですか」と困った様子で言った。\nこのときの、介護福祉職の準言語を活用した対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"強い口調で伝えた。"},{"id":"2","text":"抑揚をつけずに伝えた。"},{"id":"3","text":"大きな声でゆっくり伝えた。"},{"id":"4","text":"急かすように伝えた。"},{"id":"5","text":"早口で伝えた。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！準言語は、声の大きさ、速さ、抑揚など、言葉以外の声の特徴のことなんだ。Ｂさんは伝わらずに困っているから、大きな声で、ゆっくり伝えるのがよいよ。1、4は威圧的、2は抑揚がなく伝わりにくい、5は早口で聞き取りにくいので、Ｂさんの助けにならないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-005","examYear":"2024","examRound":"36","questionNumber":5,"category":"人間関係とコミュニケーション","questionText":"Ｖ介護老人福祉施設では、感染症が流行したために、緊急的な介護体制で事業を継続することになった。さらに労務管理を担当する職員からは、介護福祉職の精神的健康を守ることを目的とした組織的なマネジメントに取り組む必要性について提案があった。\n次の記述のうち、このマネジメントに該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"感染防止対策を強化する。"},{"id":"2","text":"多職種チームでの連携を強化する。"},{"id":"3","text":"利用者のストレスをコントロールする。"},{"id":"4","text":"介護福祉職の燃え尽き症候群（バーンアウト（burnout））を防止する。"},{"id":"5","text":"利用者家族の面会方法を見直す。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！介護福祉職の精神的健康を守るための、組織的なマネジメントは、燃え尽き症候群（バーンアウト）を防ぐことなんだ。1、2は感染対策や連携で、3は利用者のストレス、5は面会方法の見直しで、どれも介護福祉職の精神的健康を守ることが目的ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-006","examYear":"2024","examRound":"36","questionNumber":6,"category":"人間関係とコミュニケーション","questionText":"次のうち、介護老人福祉施設における全体の指揮命令系統を把握するために必要なものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"組織図"},{"id":"2","text":"勤務表"},{"id":"3","text":"経営理念"},{"id":"4","text":"施設の歴史"},{"id":"5","text":"資格保有者数"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！組織図は、施設の部署や役職の関係、つまり指揮命令系統を、一目でわかるように示したものなんだ。2の勤務表は、勤務の割り振り、3の経営理念は、施設の考え方、4の歴史は、成り立ち、5の資格保有者数は、人材の状況で、指揮命令系統を把握するものではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-007","examYear":"2024","examRound":"36","questionNumber":7,"category":"社会の理解","questionText":"次のうち、セルフヘルプグループ（self-help group）の活動に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"断酒会"},{"id":"2","text":"施設の社会貢献活動"},{"id":"3","text":"子ども食堂の運営"},{"id":"4","text":"傾聴ボランティア"},{"id":"5","text":"地域の町内会"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！セルフヘルプグループは、同じ悩みや問題をもつ当事者が集まって、体験を語り合い、支え合う活動なんだ。断酒会は、アルコール依存症の当事者による、代表的な例だね。2は施設の活動、3は地域の取り組み、4はボランティア、5は地域組織で、当事者同士の活動ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-008","examYear":"2024","examRound":"36","questionNumber":8,"category":"社会の理解","questionText":"特定非営利活動法人（ＮＰＯ法人）に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"社会福祉法に基づいて設置される。"},{"id":"2","text":"市町村が認証する。"},{"id":"3","text":"保健、医療又は福祉の増進を図る活動が最も多い。"},{"id":"4","text":"収益活動は禁じられている。"},{"id":"5","text":"宗教活動を主たる目的とする団体もある。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ＮＰＯ法人の活動分野では、保健、医療、福祉の増進を図る活動が最も多いんだ。1は、特定非営利活動促進法にもとづくよ。2は、認証は都道府県や指定都市が行う。4は、収益活動も行える。5は、宗教活動を主たる目的とする団体は認められないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-009","examYear":"2024","examRound":"36","questionNumber":9,"category":"社会の理解","questionText":"地域福祉において、19世紀後半に始まった、貧困地域に住み込んで実態調査を行いながら住民への教育や生活上の援助を行ったものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"世界保健機関（ＷＨＯ）"},{"id":"2","text":"福祉事務所"},{"id":"3","text":"地域包括支援センター"},{"id":"4","text":"生活協同組合"},{"id":"5","text":"セツルメント"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！セツルメントは、19世紀後半のイギリスで始まった、貧困地域に住み込んで、実態調査や、教育や生活上の援助を行う活動なんだ。トインビー・ホールが有名だよ。1のＷＨＯは国際機関、2の福祉事務所や3の地域包括支援センターは、行政の機関、4の生活協同組合は、共同購入などの組織だね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-010","examYear":"2024","examRound":"36","questionNumber":10,"category":"社会の理解","questionText":"社会福祉基礎構造改革に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"社会福祉法が社会福祉事業法に改正された。"},{"id":"2","text":"利用契約制度から措置制度に変更された。"},{"id":"3","text":"サービス提供事業者は、社会福祉法人に限定された。"},{"id":"4","text":"障害福祉分野での制度改正は見送られた。"},{"id":"5","text":"判断能力が不十分な者に対する地域福祉権利擁護事業が創設された。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！社会福祉基礎構造改革で、判断能力が不十分な人を支える、地域福祉権利擁護事業（現在の日常生活自立支援事業）が創設されたんだ。1は、社会福祉事業法が社会福祉法に改正された。2は、措置制度から利用契約制度に変わった。3は、事業者の参入が広がった。4は、障害福祉分野でも改革が行われたよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-011","examYear":"2024","examRound":"36","questionNumber":11,"category":"社会の理解","questionText":"Ｃさん（77歳、男性）は、60歳で公務員を定年退職し、年金生活をしている。持病や障害はなく、退職後も趣味のゴルフを楽しみながら健康に過ごしている。ある日、Ｃさんはゴルフ中にけがをして医療機関を受診した。\nこのとき、Ｃさんに適用される公的医療制度として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"国民健康保険"},{"id":"2","text":"後期高齢者医療制度"},{"id":"3","text":"共済組合保険"},{"id":"4","text":"育成医療"},{"id":"5","text":"更生医療"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｃさんは77歳で、75歳以上なので、後期高齢者医療制度が適用されるんだ。1の国民健康保険や3の共済組合保険は、75歳未満の人が対象になる。4の育成医療は、18歳未満の子ども、5の更生医療は、身体障害のある18歳以上の人への医療費の助成だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-012","examYear":"2024","examRound":"36","questionNumber":12,"category":"社会の理解","questionText":"次のうち、介護保険法に基づき、都道府県・指定都市・中核市が指定（許可）、監督を行うサービスとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"地域密着型介護サービス"},{"id":"2","text":"居宅介護支援"},{"id":"3","text":"施設サービス"},{"id":"4","text":"夜間対応型訪問介護"},{"id":"5","text":"介護予防支援"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！施設サービスは、都道府県、指定都市、中核市が、指定（許可）や監督を行うんだ。1、4の地域密着型サービスと、2の居宅介護支援、5の介護予防支援は、市町村が指定や監督を行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-013","examYear":"2024","examRound":"36","questionNumber":13,"category":"社会の理解","questionText":"「障害者差別解消法」に関する次の記述のうち、適切なものを1つ選びなさい。\n（注）  「障害者差別解消法」とは、「障害を理由とする差別の解消の推進に関する法律」のことである。","choices":[{"id":"1","text":"法の対象者は、身体障害者手帳を交付された者に限定されている。"},{"id":"2","text":"合理的配慮は、実施するときの負担の大小に関係なく提供する。"},{"id":"3","text":"個人による差別行為への罰則規定がある。"},{"id":"4","text":"雇用分野での、障害を理由とした使用者による虐待の禁止が目的である。"},{"id":"5","text":"障害者基本法の基本的な理念を具体的に実施するために制定された。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害者差別解消法は、障害者基本法の、差別の禁止という基本的な理念を、具体的に実施するために制定された法律なんだ。1は、手帳がなくても、対象になる。2は、合理的配慮は、負担が重すぎない範囲で行う。3は、個人への罰則規定はない。4は、雇用分野での虐待防止は、別の法律だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-014","examYear":"2024","examRound":"36","questionNumber":14,"category":"社会の理解","questionText":"「障害者総合支援法」に規定された移動に関する支援の説明として、最も適切なものを1つ選びなさい。\n（注）  「障害者総合支援法」とは、「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。","choices":[{"id":"1","text":"移動支援については、介護給付費が支給される。"},{"id":"2","text":"行動援護は、周囲の状況把握ができない視覚障害者が利用する。"},{"id":"3","text":"同行援護は、危険を回避できない知的障害者が利用する。"},{"id":"4","text":"重度訪問介護は、重度障害者の外出支援も行う。"},{"id":"5","text":"共同生活援助（グループホーム）は、地域で生活する障害者の外出支援を行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！重度訪問介護は、重度の障害がある人の、自宅での介護のほか、外出の支援も行うんだ。1は、移動支援は、地域生活支援事業だよ。2の行動援護は、知的障害や精神障害のある人向けで、3の同行援護は、視覚障害のある人向け。5は、グループホームは、住まいでの支援が中心だね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-015","examYear":"2024","examRound":"36","questionNumber":15,"category":"社会の理解","questionText":"Ｄさん（80歳、男性、要介護2）は、認知症（dementia）がある。訪問介護（ホームヘルプサービス）を利用しながら一人暮らしをしている。\nある日、訪問介護員（ホームヘルパー）がＤさんの自宅を訪問すると、近所に住むＤさんの長女から、「父が、高額な投資信託の電話勧誘を受けて、契約しようかどうか悩んでいるようで心配だ」と相談された。\n訪問介護員（ホームヘルパー）が長女に助言する相談先として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"公正取引委員会"},{"id":"2","text":"都道府県障害者権利擁護センター"},{"id":"3","text":"運営適正化委員会"},{"id":"4","text":"消費生活センター"},{"id":"5","text":"市町村保健センター"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！悪質な勧誘や、契約のトラブルなどは、消費生活センターで、相談できるんだ。1の公正取引委員会は、独占禁止法を運用する機関。2の障害者権利擁護センターは、障害者虐待の窓口、3の運営適正化委員会は、福祉サービスの苦情の解決、5の市町村保健センターは、保健事業を行う機関だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-016","examYear":"2024","examRound":"36","questionNumber":16,"category":"社会の理解","questionText":"災害時の福祉避難所に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護老人福祉施設の入所者は、原則として福祉避難所の対象外である。"},{"id":"2","text":"介護保険法に基づいて指定される避難所である。"},{"id":"3","text":"医療的ケアを必要とする者は対象にならない。"},{"id":"4","text":"訪問介護員（ホームヘルパー）が、災害対策基本法に基づいて派遣される。"},{"id":"5","text":"同行援護のヘルパーが、災害救助法に基づいて派遣される。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！福祉避難所は、一般の避難所での生活が難しい、要配慮者を受け入れる避難所なんだ。介護老人福祉施設の入所者は、施設で生活を続けるため、原則として対象外だよ。2は、災害対策基本法にもとづく。3は、医療的ケアが必要な人も対象。4と5は、派遣の根拠が、それぞれ別の制度だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-017","examYear":"2024","examRound":"36","questionNumber":17,"category":"社会の理解","questionText":"「感染症法」に基づいて、結核（tuberculosis）を発症した在宅の高齢者に、医療費の公費負担の申請業務や家庭訪問指導などを行う機関として、適切なものを1つ選びなさい。\n（注）  「感染症法」とは、「感染症の予防及び感染症の患者に対する医療に関する法律」のことである。","choices":[{"id":"1","text":"基幹相談支援センター"},{"id":"2","text":"地域活動支援センター"},{"id":"3","text":"保健所"},{"id":"4","text":"老人福祉センター"},{"id":"5","text":"医療保護施設"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！保健所は、感染症法にもとづいて、結核の医療費の公費負担の申請の受付や、家庭訪問での指導などを行う機関なんだ。1は、障害者の相談窓口、2は、障害者の創作活動などの場、4は、高齢者の相談や交流の場、5は、生活保護法の医療扶助を行う施設だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-018","examYear":"2024","examRound":"36","questionNumber":18,"category":"社会の理解","questionText":"Ｅさん（55歳、女性、障害の有無は不明）は、ひきこもりの状態にあり、就労していない。父親の年金で父親とアパートで暮らしていたが、父親が亡くなり、一人暮らしになった。遠方に住む弟は、姉が家賃を滞納していて、生活に困っているようだと、家主から連絡を受けた。\n心配した弟が相談する機関として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"地域包括支援センター"},{"id":"2","text":"福祉事務所"},{"id":"3","text":"精神保健福祉センター"},{"id":"4","text":"公共職業安定所（ハローワーク）"},{"id":"5","text":"年金事務所"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｅさんは、家賃を滞納して、生活に困っているよね。福祉事務所は、生活困窮者の相談に応じて、生活保護や、生活困窮者自立支援制度につなげてくれるんだ。1は、高齢者の相談機関、3は、精神保健の相談機関、4は、就職の相談、5は、年金の手続きの機関だから、生活困窮全体の相談先としては、福祉事務所がぴったりだよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-019","examYear":"2024","examRound":"36","questionNumber":19,"category":"こころとからだのしくみ","questionText":"次のうち、マズロー（Maslow, A.H.）の欲求階層説で成長欲求に該当するものとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"承認欲求"},{"id":"2","text":"安全欲求"},{"id":"3","text":"自己実現欲求"},{"id":"4","text":"生理的欲求"},{"id":"5","text":"所属・愛情欲求"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！マズローの欲求階層説で、成長欲求は、自己実現欲求なんだ。1の承認欲求、2の安全欲求、4の生理的欲求、5の所属・愛情欲求は、不足を満たそうとする欠乏欲求だよ。欠乏欲求と成長欲求のちがいを、押さえておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-020","examYear":"2024","examRound":"36","questionNumber":20,"category":"こころとからだのしくみ","questionText":"次のうち、交感神経の作用に該当するものとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"血管収縮"},{"id":"2","text":"心拍数減少"},{"id":"3","text":"気道収縮"},{"id":"4","text":"消化促進"},{"id":"5","text":"瞳孔収縮"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！交感神経は、体を活動的にする働きがあって、血管を収縮させて、血圧を上げるんだ。2の心拍数の減少、3の気道収縮、4の消化促進、5の瞳孔収縮は、副交感神経の作用だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-021","examYear":"2024","examRound":"36","questionNumber":21,"category":"こころとからだのしくみ","questionText":"Ｆさん（82歳、女性）は、健康診断で骨粗鬆症｛こつそしょうしょう｝（osteoporosis）と診断され、内服治療が開始された。杖歩行｛つえほこう｝で時々ふらつくが、ゆっくりと自立歩行することができる。昼間は自室にこもり、ベッドで横になっていることが多い。リハビリテーションとして週3日歩行訓練を行い、食事は普通食を毎食8割以上摂取している。\nＦさんの骨粗鬆症｛こつそしょうしょう｝（osteoporosis）の進行を予防するための支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"リハビリテーションを週1日に変更する。"},{"id":"2","text":"繊維質の多い食事を勧める。"},{"id":"3","text":"日光浴を日課に取り入れる。"},{"id":"4","text":"車いすでの移動に変更する。"},{"id":"5","text":"ビタミンＡ（vitamin A）の摂取を勧める。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！日光浴をすると、皮膚でビタミンＤがつくられて、カルシウムの吸収が進み、骨粗鬆症の進行の予防につながるんだ。1は、運動は骨を強くするので、減らさない。2は、繊維質は、カルシウムの吸収を助けない。4は、歩行を減らすと、骨が弱くなる。5は、ビタミンＡの摂りすぎは、骨折のリスクになるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-022","examYear":"2024","examRound":"36","questionNumber":22,"category":"こころとからだのしくみ","questionText":"中耳にある耳小骨として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"ツチ骨"},{"id":"2","text":"蝶形骨｛ちょうけいこつ｝"},{"id":"3","text":"前頭骨"},{"id":"4","text":"頬骨｛きょうこつ｝"},{"id":"5","text":"上顎骨"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！中耳にある耳小骨は、ツチ骨、キヌタ骨、アブミ骨の3つなんだ。2の蝶形骨、3の前頭骨、4の頬骨、5の上顎骨は、頭や顔の骨で、耳小骨ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-023","examYear":"2024","examRound":"36","questionNumber":23,"category":"こころとからだのしくみ","questionText":"成人の爪に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"主成分はタンパク質である。"},{"id":"2","text":"1日に1mm程度伸びる。"},{"id":"3","text":"爪の外表面には爪床がある。"},{"id":"4","text":"正常な爪は全体が白色である。"},{"id":"5","text":"爪半月は角質化が進んでいる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！爪の主成分は、ケラチンというタンパク質なんだ。2は、爪が伸びるのは、1日に約0.1mm。3は、爪の下にあるのが爪床で、外表面ではない。4は、正常な爪は、血流でピンク色に見える。5は、爪半月は、角質化が進んでいない部分だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-024","examYear":"2024","examRound":"36","questionNumber":24,"category":"こころとからだのしくみ","questionText":"食物が入り誤嚥｛ごえん｝が生じる部位として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"扁桃｛へんとう｝"},{"id":"2","text":"食道"},{"id":"3","text":"耳管"},{"id":"4","text":"気管"},{"id":"5","text":"咽頭"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！誤嚥は、食物や唾液が、食道ではなく、気管に入ってしまうことなんだ。1の扁桃、5の咽頭は、食べ物が通る部分、2の食道は、胃へ運ぶ道、3の耳管は、中耳とつながる管で、誤嚥が生じる部位ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-025","examYear":"2024","examRound":"36","questionNumber":25,"category":"こころとからだのしくみ","questionText":"Ｇさん（79歳、男性）は、介護老人保健施設に入所している。Ｇさんは普段から食べ物をかきこむように食べる様子がみられ、最近はむせることが多くなった。義歯は使用していない。食事は普通食を摂取している。ある日の昼食時、唐揚げを口の中に入れたあと、喉をつかむようなしぐさをし、苦しそうな表情になった。\nＧさんに起きていることとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"心筋梗塞（myocardial infarction）"},{"id":"2","text":"蕁麻疹｛じんましん｝（urticaria）"},{"id":"3","text":"誤嚥性肺炎｛ごえんせいはいえん｝（aspiration pneumonia）"},{"id":"4","text":"食中毒（foodborne disease）"},{"id":"5","text":"窒息（choking）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｇさんは、唐揚げを口に入れたあと、喉をつかむしぐさをして、苦しそうにしているんだね。これは、窒息のサイン（チョークサイン）だよ。1、2、3、4は、このような突然の症状の説明にならないんだ。すぐに、異物を取り除く対応が必要だね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-026","examYear":"2024","examRound":"36","questionNumber":26,"category":"こころとからだのしくみ","questionText":"Ｈさん（60歳、男性）は、身長170cm、体重120kgである。Ｈさんは浴槽で入浴しているときに毎回、「お風呂につかると、からだが軽く感じて楽になります」と話す。胸が苦しいなど、ほかの訴えはない。\nＨさんが話している内容に関連する入浴の作用として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"静水圧作用"},{"id":"2","text":"温熱作用"},{"id":"3","text":"清潔作用"},{"id":"4","text":"浮力作用"},{"id":"5","text":"代謝作用"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！湯につかると、浮力で体重が軽くなって、体が軽く感じられるんだ。これは、浮力作用だよ。1の静水圧作用は、水圧が体にかかり、血液の循環を促す作用。2の温熱作用は、体が温まる、3の清潔作用は、汚れを落とす、5の代謝作用は、新陳代謝が促される作用だね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-027","examYear":"2024","examRound":"36","questionNumber":27,"category":"こころとからだのしくみ","questionText":"男性に比べて女性に尿路感染症（urinary tract infection）が起こりやすい要因として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"子宮の圧迫がある。"},{"id":"2","text":"尿道が短く直線的である。"},{"id":"3","text":"腹部の筋力が弱い。"},{"id":"4","text":"女性ホルモンの作用がある。"},{"id":"5","text":"尿道括約筋が弛緩｛しかん｝している。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！女性は、尿道が短く、直線的で、外から細菌が膀胱に届きやすいので、尿路感染症が起こりやすいんだ。1の子宮の圧迫、3の腹部の筋力の弱さ、4の女性ホルモンの作用、5の尿道括約筋の弛緩は、この要因としては、最も適切とはいえないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-028","examYear":"2024","examRound":"36","questionNumber":28,"category":"こころとからだのしくみ","questionText":"次のうち、眠りが浅くなる原因として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"抗不安薬"},{"id":"2","text":"就寝前の飲酒"},{"id":"3","text":"抗アレルギー薬"},{"id":"4","text":"抗うつ薬"},{"id":"5","text":"足浴"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！就寝前の飲酒は、寝つきはよくても、眠りが浅くなって、夜中に目が覚めやすくなるんだ。1の抗不安薬と、4の抗うつ薬は、睡眠を助けることがあり、3の抗アレルギー薬は、眠気を起こすことがある。5の足浴は、体を温めて、眠りを促すよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-029","examYear":"2024","examRound":"36","questionNumber":29,"category":"こころとからだのしくみ","questionText":"概日リズム睡眠障害（circadian rhythm sleep disorder）に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"早朝に目が覚める。"},{"id":"2","text":"睡眠中に下肢が勝手にピクピクと動いてしまう。"},{"id":"3","text":"睡眠中に呼吸が止まる。"},{"id":"4","text":"睡眠中に突然大声を出したり身体を動かしたりする。"},{"id":"5","text":"夕方に強い眠気を感じて就寝し、深夜に覚醒してしまう。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！概日リズム睡眠障害は、体内時計のずれによって、眠る時間帯がずれる病気なんだ。夕方に強い眠気で寝てしまい、深夜に目が覚めるのは、その例だね。1は、うつ病などの早朝覚醒。2は、周期性四肢運動障害。3は、睡眠時無呼吸症候群。4は、レム睡眠行動障害だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-030","examYear":"2024","examRound":"36","questionNumber":30,"category":"こころとからだのしくみ","questionText":"鎮痛薬としてモルヒネを使用している利用者に、医療職と連携した介護を実践するときに留意すべき観察点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"不眠"},{"id":"2","text":"下痢"},{"id":"3","text":"脈拍"},{"id":"4","text":"呼吸"},{"id":"5","text":"体温"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！モルヒネは、痛みをやわらげる薬だけど、副作用として、呼吸が抑えられることがあるんだ。だから、呼吸の状態を観察することが大切だよ。1の不眠、2の下痢、3の脈拍、5の体温は、モルヒネの副作用としては、優先して観察する項目ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-031","examYear":"2024","examRound":"36","questionNumber":31,"category":"発達と老化の理解","questionText":"スキャモン（Scammon, R.E.）の発達曲線に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"神経系の組織は、4歳ごろから急速に発達する。"},{"id":"2","text":"筋骨格系の組織は、4歳ごろから急速に発達する。"},{"id":"3","text":"生殖器系の組織は、12歳ごろから急速に発達する。"},{"id":"4","text":"循環器系の組織は、20歳ごろから急速に発達する。"},{"id":"5","text":"リンパ系の組織は、20歳ごろから急速に発達する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！スキャモンの発達曲線では、生殖器系は、12歳ごろから急速に発達するんだ。1は、神経系は、乳幼児期に急速に発達して、6歳ごろに約90％に達する。2は、筋骨格系は、乳幼児期と思春期に発達する。4は、循環器系は、一般型に含まれる。5は、リンパ系は、12〜13歳ごろにピークに達して、その後低下するよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-032","examYear":"2024","examRound":"36","questionNumber":32,"category":"発達と老化の理解","questionText":"幼稚園児のＪさん（6歳、男性）には、広汎性発達障害（pervasive developmental disorder）がある。砂場で砂だんごを作り、きれいに並べることが好きで、毎日、一人で砂だんごを作り続けている。\nある日、園児が帰宅した後に、担任が台風に備えて砂場に青いシートをかけておいた。翌朝、登園したＪさんが、いつものように砂場に行くと、青いシートがかかっていた。Ｊさんはパニックになり、その場で泣き続け、なかなか落ち着くことができなかった。\n担任は、Ｊさんにどのように対応すればよかったのか、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"前日に、「あしたは、台風が来るよ」と伝える。"},{"id":"2","text":"前日に、「あしたは、台風が来るので砂場は使えないよ」と伝える。"},{"id":"3","text":"前日に、「あしたは、おだんご屋さんは閉店です」と伝える。"},{"id":"4","text":"その場で、「今日は、砂場は使えないよ」と伝える。"},{"id":"5","text":"その場で、「今日は、おだんご屋さんは閉店です」と伝える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！広汎性発達障害（自閉症スペクトラム）のある子は、急な変化が苦手なんだ。前日に、「あしたは台風が来るので、砂場は使えないよ」と、具体的に見通しを伝えておくと、混乱を防げるよ。1は、台風が来ることだけでは、砂場が使えないことが伝わらない。3、5は、たとえで、伝わりにくい。4は、その場で伝えても、パニックを防げないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-033","examYear":"2024","examRound":"36","questionNumber":33,"category":"発達と老化の理解","questionText":"生理的老化に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"環境によって起こる現象である。"},{"id":"2","text":"訓練によって回復できる現象である。"},{"id":"3","text":"個体の生命活動に有利にはたらく現象である。"},{"id":"4","text":"人間固有の現象である。"},{"id":"5","text":"遺伝的にプログラムされた現象である。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！生理的老化は、だれにでも起こって、遺伝的にプログラムされていて、後戻りできない、避けられない現象なんだ。1は、環境の影響とは限らない。2は、訓練で回復できない。3は、生命活動に不利にはたらく。4は、人間だけでなく、生物全般に起こるよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-034","examYear":"2024","examRound":"36","questionNumber":34,"category":"発達と老化の理解","questionText":"エイジズム（ageism）に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高齢を理由にして、偏見をもったり差別したりすることである。"},{"id":"2","text":"高齢になっても生産的な活動を行うことである。"},{"id":"3","text":"高齢になることを嫌悪する心理のことである。"},{"id":"4","text":"加齢に抵抗して、健康的に生きようとすることである。"},{"id":"5","text":"加齢を受容して、活動的に生きようとすることである。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！エイジズムは、高齢であることを理由にして、偏見をもったり、差別をしたりすることなんだ。2は、プロダクティブ・エイジング、4は、アンチエイジング、5は、サクセスフル・エイジングなどの考え方で、3は、老いへの嫌悪ではなく、偏見や差別が本来の意味だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-035","examYear":"2024","examRound":"36","questionNumber":35,"category":"発達と老化の理解","questionText":"Ｋさん（80歳、男性）は、40歳ごろから職場の健康診査で高血圧と高コレステロール血症（hypercholesterolemia）を指摘されていた。最近、階段を上るときに胸の痛みを感じていたが、しばらく休むと軽快していた。喉の違和感や嚥下痛｛えんげつう｝はない。今朝、朝食後から冷や汗を伴う激しい胸痛が起こり、30分しても軽快しないので、救急車を呼んだ。\nＫさんに考えられる状況として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"喘息｛ぜんそく｝（bronchial asthma）"},{"id":"2","text":"肺炎（pneumonia）"},{"id":"3","text":"脳梗塞（cerebral infarction）"},{"id":"4","text":"心筋梗塞（myocardial infarction）"},{"id":"5","text":"逆流性食道炎（reflux esophagitis）"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｋさんは、高血圧や高コレステロール血症があり、階段で胸が痛んで、今朝は冷や汗を伴う激しい胸痛が30分以上続いているんだね。これは、心筋梗塞の典型的な症状なんだ。狭心症では、休むと軽快するけれど、心筋梗塞では、軽快しないよ。すぐに救急要請が必要だね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-036","examYear":"2024","examRound":"36","questionNumber":36,"category":"発達と老化の理解","questionText":"次のうち、健康寿命の説明として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"0歳児の平均余命"},{"id":"2","text":"65歳時の平均余命"},{"id":"3","text":"65歳時の平均余命から介護期間を差し引いたもの"},{"id":"4","text":"介護状態に至らずに死亡する人の平均寿命"},{"id":"5","text":"健康上の問題で日常生活が制限されることなく生活できる期間"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！健康寿命は、健康上の問題で、日常生活が制限されることなく、生活できる期間のことなんだ。1は、平均寿命、2は、65歳時の平均余命の説明だよ。3、4は、健康寿命の定義ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-037","examYear":"2024","examRound":"36","questionNumber":37,"category":"発達と老化の理解","questionText":"次のうち、前立腺肥大症（prostatic hypertrophy）に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"抗利尿ホルモンが関与している。"},{"id":"2","text":"症状が進むと無尿になる。"},{"id":"3","text":"初期には頻尿が出現する。"},{"id":"4","text":"進行すると透析の対象になる。"},{"id":"5","text":"骨盤底筋訓練で回復が期待できる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！前立腺肥大症は、前立腺が大きくなって、尿道を圧迫する病気で、初期には、頻尿（特に夜間）が出るんだ。1は、抗利尿ホルモンは関与しない。2は、尿が出なくなる無尿にはならない（尿閉になることはある）。4は、透析の対象にはならない。5は、骨盤底筋訓練で回復が期待できるのは、腹圧性尿失禁だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-038","examYear":"2024","examRound":"36","questionNumber":38,"category":"発達と老化の理解","questionText":"次のうち、高齢期に多い筋骨格系の疾患に関する記述として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"骨粗鬆症｛こつそしょうしょう｝（osteoporosis）は男性に多い。"},{"id":"2","text":"変形性膝関節症（knee osteoarthritis）ではＸ脚に変形する。"},{"id":"3","text":"関節リウマチ（rheumatoid arthritis）は軟骨の老化によって起こる。"},{"id":"4","text":"腰部脊柱管狭窄症｛ようぶせきちゅうかんきょうさくしょう｝（lumbar spinal canal stenosis）では下肢のしびれがみられる。"},{"id":"5","text":"サルコペニア（sarcopenia）は骨量の低下が特徴である。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！腰部脊柱管狭窄症は、神経が圧迫されて、下肢のしびれや痛みが出て、間欠性跛行がみられるんだ。1は、骨粗鬆症は、閉経後の女性に多い。2は、変形性膝関節症は、Ｏ脚になることが多い。3は、関節リウマチは、自己免疫の病気。5は、サルコペニアは、筋肉量の低下が特徴だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-039","examYear":"2024","examRound":"36","questionNumber":39,"category":"認知症の理解","questionText":"高齢者の自動車運転免許に関する次の記述のうち、正しいものを1つ選びなさい。\n（注）  「サポートカー限定免許」とは、道路交通法第91条の2の規定に基づく条件が付された免許のことである。","choices":[{"id":"1","text":"75歳から免許更新時の認知機能検査が義務づけられている。"},{"id":"2","text":"80歳から免許更新時の運転技能検査が義務づけられている。"},{"id":"3","text":"軽度認知障害（mild cognitive impairment）と診断された人は運転免許取消しになる。"},{"id":"4","text":"認知症（dementia）の人はサポートカー限定免許であれば運転が可能である。"},{"id":"5","text":"認知症（dementia）による運転免許取消しの後、運転経歴証明書が交付される。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！75歳以上の人は、免許の更新のときに、認知機能検査を受けることが義務づけられているんだ。2は、運転技能検査は、75歳以上で、一定の違反歴がある人が対象。3は、軽度認知障害は、直ちに取消しではない。4は、認知症と診断された場合は、免許の停止や取消しになる。5は、運転経歴証明書は、申請により交付されるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-040","examYear":"2024","examRound":"36","questionNumber":40,"category":"認知症の理解","questionText":"認知症（dementia）の行動・心理症状（ＢＰＳＤ）であるアパシー（apathy）に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"感情の起伏がみられない。"},{"id":"2","text":"将来に希望がもてない。"},{"id":"3","text":"気持ちが落ち込む。"},{"id":"4","text":"理想どおりにいかず悩む。"},{"id":"5","text":"自分を責める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！アパシーは、意欲や関心が低下して、感情の起伏がみられなくなる状態なんだ。2の将来に希望がもてない、3の気持ちが落ち込む、4の理想どおりにいかず悩む、5の自分を責めるのは、抑うつの症状で、アパシーとは、ちがうんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-041","examYear":"2024","examRound":"36","questionNumber":41,"category":"認知症の理解","questionText":"認知症（dementia）の人にみられる、せん妄に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ゆっくりと発症する。"},{"id":"2","text":"意識は清明である。"},{"id":"3","text":"注意機能は保たれる。"},{"id":"4","text":"体調の変化が誘因になる。"},{"id":"5","text":"日中に多くみられる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！せん妄は、体調の変化、脱水、感染、薬などが誘因となって起こるんだ。1は、急に発症する。2は、意識が混濁する。3は、注意機能が低下する。5は、夜間に多くみられるよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-042","examYear":"2024","examRound":"36","questionNumber":42,"category":"認知症の理解","questionText":"レビー小体型認知症（dementia with Lewy bodies）にみられる歩行障害として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"しばらく歩くと足に痛みを感じて、休みながら歩く。"},{"id":"2","text":"最初の一歩が踏み出しにくく、小刻みに歩く。"},{"id":"3","text":"動きがぎこちなく、酔っぱらったように歩く。"},{"id":"4","text":"下肢は伸展し、つま先を引きずるように歩く。"},{"id":"5","text":"歩くごとに骨盤が傾き、腰を左右に振って歩く。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！レビー小体型認知症では、パーキンソン症状がみられて、最初の一歩が出にくく、小刻みに歩くんだ。1は、間欠性跛行、3は、失調性歩行、4は、痙性歩行、5は、トレンデレンブルグ歩行（動揺性歩行）の特徴だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-043","examYear":"2024","examRound":"36","questionNumber":43,"category":"認知症の理解","questionText":"次の記述のうち、若年性認知症（dementia with early onset）の特徴として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高齢の認知症（dementia）に比べて、症状の進行速度は緩やかなことが多い。"},{"id":"2","text":"男性よりも女性の発症者が多い。"},{"id":"3","text":"50歳代よりも30歳代の有病率が高い。"},{"id":"4","text":"特定健康診査で発見されることが多い。"},{"id":"5","text":"高齢の認知症（dementia）に比べて、就労支援が必要になることが多い。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！若年性認知症は、働き盛りで発症するので、仕事を続けることが難しくなったり、経済面の問題が起こったりして、就労支援が必要になることが多いんだ。1は、進行が速いことが多い。2は、男性のほうが多い。3は、年齢が高いほど有病率が高い。4は、特定健康診査では、見つけにくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-044","examYear":"2024","examRound":"36","questionNumber":44,"category":"認知症の理解","questionText":"Ｌさん（78歳、女性、要介護1）は、3年前にアルツハイマー型認知症（dementia of the Alzheimer’s type）と診断された。訪問介護（ホームヘルプサービス）を利用し、夫の介護を受けながら二人で暮らしている。ある日、訪問介護員（ホームヘルパー）が訪問すると夫から、「用事で外出しようとすると『外で女性に会っている』と言って興奮することが増えて困っている」と相談を受けた。\nＬさんの症状に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"誤認"},{"id":"2","text":"観念失行"},{"id":"3","text":"嫉妬妄想"},{"id":"4","text":"視覚失認"},{"id":"5","text":"幻視"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｌさんは、夫が外出するときに、「外で女性に会っている」と言って興奮するんだね。これは、配偶者の浮気を疑う、嫉妬妄想だよ。1の誤認は、人や物を取り違える、2の観念失行は、道具の使い方がわからない、4の視覚失認は、見えているものが何かわからない、5の幻視は、ないものが見える症状だね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-045","examYear":"2024","examRound":"36","questionNumber":45,"category":"認知症の理解","questionText":"認知機能障害による生活への影響に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"遂行機能障害により、自宅がわからない。"},{"id":"2","text":"記憶障害により、出された食事を食べない。"},{"id":"3","text":"相貌失認により、目の前の家族がわからない。"},{"id":"4","text":"視空間認知障害により、今日の日付がわからない。"},{"id":"5","text":"病識低下により、うつ状態になりやすい。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！相貌失認は、目の前の人の顔を見ても、だれかがわからなくなる症状なんだ。だから、家族がわからなくなるよ。1は、自宅がわからないのは、見当識障害。2は、食べないのは、失認や失行などの影響。4は、日付がわからないのは、見当識障害。5は、病識低下は、うつ状態にはなりにくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-046","examYear":"2024","examRound":"36","questionNumber":46,"category":"認知症の理解","questionText":"バリデーション（validation）に基づく、認知症（dementia）の人の動きや感情に合わせるコミュニケーション技法として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"センタリング（centering）"},{"id":"2","text":"リフレージング（rephrasing）"},{"id":"3","text":"レミニシング（reminiscing）"},{"id":"4","text":"ミラーリング（mirroring）"},{"id":"5","text":"カリブレーション（calibration）"}],"correctChoice":"4,5","correctChoices":["4","5"],"explanation":"この問題は、4と5がどちらも正解として扱われているよ。ミラーリングは、相手の動きに合わせて、鏡のように動く技法。カリブレーションは、相手の感情や状態を観察して、呼吸や動きを合わせる技法で、どちらも「動きや感情に合わせる」技法にあたるため、公式に複数正解になったんだ。1のセンタリングは自分を落ち着ける、2のリフレージングは言葉の言い換え、3のレミニシングは思い出を語ってもらう技法で、これらとはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-047","examYear":"2024","examRound":"36","questionNumber":47,"category":"認知症の理解","questionText":"Ｍさん（80歳、女性、要介護1）は、アルツハイマー型認知症（dementia of the Alzheimer’s type）であり、3日前に認知症対応型共同生活介護（認知症高齢者グループホーム）に入居した。主治医から向精神薬が処方されている。居室では穏やかに過ごしていた。夕食後、表情が険しくなり、「こんなところにはいられません。私は家に帰ります」と大声を上げ、ほかの利用者にも、「あなたも一緒に帰りましょう」と声をかけて皆が落ち着かなくなることがあった。\nＭさんの介護を検討するときに優先することとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｍさんが訴えている内容"},{"id":"2","text":"Ｍさんの日中の過ごし方"},{"id":"3","text":"ほかの利用者が落ち着かなくなったこと"},{"id":"4","text":"対応に困ったこと"},{"id":"5","text":"薬が効かなかったこと"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｍさんが大声で訴えている「家に帰りたい」という言葉には、不安や、居場所を求める気持ちがあるんだ。だから、介護を検討するときは、まずＭさんが訴えている内容を、優先して考えるんだよ。2の日中の過ごし方も大事だけど、まず本人の思いが最優先。3、4、5は、職員や周囲の側の視点だね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-048","examYear":"2024","examRound":"36","questionNumber":48,"category":"認知症の理解","questionText":"Ａさん（80歳、男性、要介護1）は、認知症（dementia）で、妻の介護を受けながら二人で暮らしている。「夫は昼夜逆転がある。在宅介護を続けたいが、私が体調を崩し数日間の入院が必要になった」と言う妻に提案する、Ａさんへの介護サービスとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"認知症対応型通所介護（認知症対応型デイサービス）"},{"id":"2","text":"短期入所生活介護（ショートステイ）"},{"id":"3","text":"認知症対応型共同生活介護（認知症高齢者グループホーム）"},{"id":"4","text":"特定施設入居者生活介護"},{"id":"5","text":"介護老人福祉施設"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！妻の入院で、数日間、Ａさんを介護する人がいなくなるから、短期間、施設に泊まれる短期入所生活介護（ショートステイ）がぴったりなんだ。1のデイサービスは、日中だけ。3、4、5は、長期の入居や入所を前提としたサービスで、数日間の対応には合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-049","examYear":"2024","examRound":"36","questionNumber":49,"category":"障害の理解","questionText":"次のうち、ノーマライゼーション（normalization）の原理を盛り込んだ法律（いわゆる「1959年法」）を制定した最初の国として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"デンマーク"},{"id":"2","text":"イギリス"},{"id":"3","text":"アメリカ"},{"id":"4","text":"スウェーデン"},{"id":"5","text":"ノルウェー"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ノーマライゼーションの原理を盛り込んだ、1959年法は、デンマークで制定されたんだ。バンク-ミケルセンが、その考え方の生みの親だよ。2のイギリス、3のアメリカ、4のスウェーデン、5のノルウェーでは、最初ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-050","examYear":"2024","examRound":"36","questionNumber":50,"category":"障害の理解","questionText":"法定後見制度において、成年後見人等を選任する機関等として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"法務局"},{"id":"2","text":"家庭裁判所"},{"id":"3","text":"都道府県知事"},{"id":"4","text":"市町村長"},{"id":"5","text":"福祉事務所"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！法定後見制度で、成年後見人等を選任するのは、家庭裁判所なんだ。1の法務局は、後見登記、3の都道府県知事と、5の福祉事務所は、選任する機関ではないよ。4の市町村長は、申立てはできるけれど、選任はしないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-051","examYear":"2024","examRound":"36","questionNumber":51,"category":"障害の理解","questionText":"次の記述のうち、障害を受容した心理的段階にみられる言動として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害があるという自覚がない。"},{"id":"2","text":"周囲に不満をぶつける。"},{"id":"3","text":"自分が悪いと悲観する。"},{"id":"4","text":"価値観が転換し始める。"},{"id":"5","text":"できることに目を向けて行動する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害を受容した段階では、できることに目を向けて、前向きに行動するようになるんだ。1は、否認の段階、2は、怒りの段階、3は、抑うつの段階、4は、価値観が転換し始める、受容への途中の段階だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-052","examYear":"2024","examRound":"36","questionNumber":52,"category":"障害の理解","questionText":"統合失調症（schizophrenia）の特徴的な症状として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"振戦せん妄"},{"id":"2","text":"妄想"},{"id":"3","text":"強迫性障害"},{"id":"4","text":"抑うつ気分"},{"id":"5","text":"健忘"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！統合失調症の特徴的な症状は、幻覚や妄想などの陽性症状なんだ。1の振戦せん妄は、アルコール依存症の離脱症状、3の強迫性障害は、不安障害の一つ、4の抑うつ気分は、うつ病、5の健忘は、記憶障害で、統合失調症の特徴的な症状ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-053","examYear":"2024","examRound":"36","questionNumber":53,"category":"障害の理解","questionText":"Ｂさん（60歳、男性）は、一人暮らしをしている。糖尿病性網膜症（diabetic retinopathy）による視覚障害（身体障害者手帳1級）があり、末梢神経障害｛まっしょうしんけいしょうがい｝の症状がでている。Ｂさんの日常生活において、介護福祉職が留意すべき点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"水晶体の白濁"},{"id":"2","text":"口腔粘膜｛こうくうねんまく｝や外陰部の潰瘍"},{"id":"3","text":"振戦や筋固縮"},{"id":"4","text":"足先の傷や壊疽｛えそ｝などの病変"},{"id":"5","text":"感音性の難聴"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！糖尿病は、末梢神経障害によって、足先の感覚が鈍くなり、傷に気づきにくくて、悪化すると壊疽になることがあるんだ。Ｂさんは視覚障害もあるので、足の観察が大切だよ。1は白内障、2はベーチェット病、3はパーキンソン病、5は感音性難聴で、糖尿病の合併症としては、優先度が低いよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-054","examYear":"2024","examRound":"36","questionNumber":54,"category":"障害の理解","questionText":"Ｃさん（55歳、男性）は、5年前に筋萎縮性側索硬化症（amyotrophic lateral sclerosis：ＡＬＳ）と診断された。現在は症状が進行して、日常生活動作に介護が必要で、自宅では電動車いすと特殊寝台を使用している。\n次の記述のうち、Ｃさんの現在の状態として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"誤嚥｛ごえん｝せずに食事することが可能である。"},{"id":"2","text":"明瞭に話すことができる。"},{"id":"3","text":"身体の痛みがわかる。"},{"id":"4","text":"自力で痰｛たん｝を排出できる。"},{"id":"5","text":"箸を上手に使える。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ＡＬＳは、運動神経が障害されるけれど、感覚神経は、保たれるので、身体の痛みはわかるんだ。1は、進行すると、嚥下が難しくなる。2は、構音障害で、明瞭に話しにくい。4は、呼吸筋が弱り、痰を出しにくい。5は、手の動きが難しく、箸は使いにくいよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-055","examYear":"2024","examRound":"36","questionNumber":55,"category":"障害の理解","questionText":"Ｄさん（36歳、女性、療育手帳所持）は、一人暮らしをしながら地域の作業所に通っている。身の回りのことはほとんど自分でできるが、お金の計算、特に計画的にお金を使うのが苦手だった。そこで、社会福祉協議会の生活支援員と一緒に銀行へ行って、1週間ごとにお金をおろして生活するようになった。小遣い帳に記録をするようにアドバイスを受けて、お金を計画的に使うことができるようになった。\n次のうち、Ｄさんが活用した支援を実施する事業として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害者相談支援事業"},{"id":"2","text":"自立生活援助事業"},{"id":"3","text":"日常生活自立支援事業"},{"id":"4","text":"成年後見制度利用支援事業"},{"id":"5","text":"日常生活用具給付等事業"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！日常生活自立支援事業は、社会福祉協議会が実施していて、判断能力が不十分な人に、金銭管理などを支援するんだ。生活支援員と一緒に、銀行でお金をおろす支援は、その例だね。1は、障害者相談支援事業は、相談や情報提供。2は、自立生活援助事業は、一人暮らしの見守り。4は、成年後見制度の利用の費用の助成。5は、日常生活用具の給付だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-056","examYear":"2024","examRound":"36","questionNumber":56,"category":"障害の理解","questionText":"次のうち、障害の特性に応じた休憩時間の調整など、柔軟に対応することで障害者の権利を確保する考え方を示すものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"全人間的復権"},{"id":"2","text":"合理的配慮"},{"id":"3","text":"自立生活運動"},{"id":"4","text":"意思決定支援"},{"id":"5","text":"共同生活援助"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！合理的配慮は、障害のある人が、ほかの人と平等に生活できるように、一人ひとりの特性に応じて、負担が重すぎない範囲で、調整や変更をすることなんだ。休憩時間の調整は、その例だよ。1は、リハビリテーションの理念、3は、自立生活運動、4は、意思決定支援、5は、障害福祉サービスの一つだね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-057","examYear":"2024","examRound":"36","questionNumber":57,"category":"障害の理解","questionText":"「障害者総合支援法」において、障害福祉サービスを利用する人の意向のもとにサービス等利用計画案を作成する事業所に置かなければならない専門職として、最も適切なものを1つ選びなさい。\n（注）  「障害者総合支援法」とは、「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。","choices":[{"id":"1","text":"介護支援専門員（ケアマネジャー）"},{"id":"2","text":"社会福祉士"},{"id":"3","text":"介護福祉士"},{"id":"4","text":"民生委員"},{"id":"5","text":"相談支援専門員"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！サービス等利用計画案を作成する、指定特定相談支援事業所には、相談支援専門員を置かなければならないんだ。1の介護支援専門員は、介護保険のケアプランを作成する。2の社会福祉士と、3の介護福祉士は、資格で、配置は必須ではない。4の民生委員は、地域の相談役だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-058","examYear":"2024","examRound":"36","questionNumber":58,"category":"障害の理解","questionText":"家族の介護力をアセスメントするときの視点に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害者個人のニーズを重視する。"},{"id":"2","text":"家族のニーズを重視する。"},{"id":"3","text":"家族構成員の主観の共通部分を重視する。"},{"id":"4","text":"家族を構成する個人と家族全体の生活を見る。"},{"id":"5","text":"支援者の視点や価値観を基準にする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！家族の介護力のアセスメントでは、家族を構成する一人ひとりと、家族全体の生活の両方を見ることが大切なんだ。1は、障害者個人だけを重視するのではなく、2の家族のニーズだけでもいけない。3は、主観の共通部分だけではなく、5は、支援者の価値観を基準にしてはダメだよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-059","examYear":"2024","examRound":"36","questionNumber":59,"category":"医療的ケア","questionText":"次の記述のうち、喀痰吸引等｛かくたんきゅういんとう｝を実施する訪問介護事業所として登録するときに、事業所が行うべき事項として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"登録研修機関になる。"},{"id":"2","text":"医師が設置する安全委員会に参加する。"},{"id":"3","text":"喀痰吸引等計画書｛かくたんきゅういんとうけいかくしょ｝の作成を看護師に依頼する。"},{"id":"4","text":"介護支援専門員（ケアマネジャー）の文書による指示を受ける。"},{"id":"5","text":"医療関係者との連携体制を確保する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！喀痰吸引等を行う事業所として登録するには、医療関係者との連携体制を確保することが必要なんだ。1は、登録研修機関になる必要はない。2は、安全委員会は、事業所などが設置する。3は、計画書は、事業所が作成する。4は、指示は、医師の指示書だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-060","examYear":"2024","examRound":"36","questionNumber":60,"category":"医療的ケア","questionText":"次のうち、呼吸器官の部位の説明に関する記述として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"鼻腔｛びくう｝は、上葉・中葉・下葉に分かれている。"},{"id":"2","text":"咽頭は、左右に分岐している。"},{"id":"3","text":"喉頭は、食べ物の通り道である。"},{"id":"4","text":"気管は、空気の通り道である。"},{"id":"5","text":"肺は、腹腔内｛ふくくうない｝にある。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！気管は、空気の通り道で、喉頭から肺へとつながっているんだ。1は、上葉・中葉・下葉に分かれているのは、肺。2は、左右に分かれるのは、気管支。3は、喉頭は、空気の通り道で、食べ物は通らない。5は、肺は、胸腔内にあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-061","examYear":"2024","examRound":"36","questionNumber":61,"category":"医療的ケア","questionText":"次のうち、痰｛たん｝の吸引の準備に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"吸引器は、陰圧になることを確認する。"},{"id":"2","text":"吸引びんは、滅菌したものを用意する。"},{"id":"3","text":"吸引チューブのサイズは、痰｛たん｝の量に応じたものにする。"},{"id":"4","text":"洗浄水は、決められた消毒薬を入れておく。"},{"id":"5","text":"清浄綿は、次亜塩素酸ナトリウムに浸しておく。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！痰の吸引を準備するときは、吸引器のスイッチを入れて、陰圧になることを確認するんだ。2は、吸引びんは、滅菌でなくてよい。3は、チューブのサイズは、利用者の状態や口腔内の状況で決める。4は、洗浄水は、水道水や滅菌水を使う。5は、清浄綿は、アルコール綿を使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-062","examYear":"2024","examRound":"36","questionNumber":62,"category":"医療的ケア","questionText":"次のうち、経管栄養で起こるトラブルに関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"チューブの誤挿入は、下痢を起こす可能性がある。"},{"id":"2","text":"注入速度が速いときは、嘔吐｛おうと｝を起こす可能性がある。"},{"id":"3","text":"注入物の温度の調整不良は、脱水を起こす可能性がある。"},{"id":"4","text":"注入物の濃度の間違いは、感染を起こす可能性がある。"},{"id":"5","text":"注入中の姿勢の不良は、便秘を起こす可能性がある。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！経管栄養で、注入速度が速いと、嘔吐や下痢を起こすことがあるんだ。1は、チューブの誤挿入は、誤嚥や肺炎などを起こす。3は、温度の調整不良は、下痢などを起こす。4は、濃度の間違いは、下痢や脱水を起こす。5は、姿勢の不良は、逆流や誤嚥を起こすんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-063","examYear":"2024","examRound":"36","questionNumber":63,"category":"医療的ケア","questionText":"Ｅさん（75歳、女性）は、介護老人福祉施設に入所している。脳梗塞（cerebral infarction）の後遺症があり、介護福祉士が胃ろうによる経管栄養を行っている。\nある日、半座位で栄養剤の注入を開始し、半分程度を順調に注入したところで、体調に変わりがないかを聞くと、「少しお腹が張ってきたような気がする」とＥさんは答えた。意識レベルや顔色に変化はなく、腹痛や嘔気｛おうき｝はない。\n次のうち、介護福祉士が看護職員に相談する前に行う対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"嘔吐｛おうと｝していないので、そのまま様子をみる。"},{"id":"2","text":"仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）にする。"},{"id":"3","text":"腹部が圧迫されていないかを確認する。"},{"id":"4","text":"注入速度を速める。"},{"id":"5","text":"栄養剤の注入を終了する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｅさんは、少しお腹が張ってきたと話していて、腹部の圧迫が、原因の場合があるんだ。まずは、腹部が圧迫されていないか、確認するのがよいよ。1は、様子を見るだけでは不十分、2は、仰臥位は、逆流しやすい。4は、速めるのは、危険。5は、判断は、看護職員と相談してから行うんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_am_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-064","examYear":"2024","examRound":"36","questionNumber":64,"category":"介護の基本","questionText":"介護を取り巻く状況に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ダブルケアとは、夫婦が助け合って子育てをすることである。"},{"id":"2","text":"要介護・要支援の認定者数は、介護保険制度の導入時から年々減少している。"},{"id":"3","text":"家族介護を支えていた家制度は、地域包括ケアシステムによって廃止された。"},{"id":"4","text":"要介護・要支援の認定者のいる三世代世帯の構成割合は、介護保険制度の導入時から年々増加している。"},{"id":"5","text":"家族が担っていた介護の役割は、家族機能の低下によって社会で代替する必要が生じた。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！家族の機能が弱まって、家族が担っていた介護の役割を、社会で代わりに担う必要が生じたんだ。それが、介護の社会化なんだよ。1のダブルケアは、育児と介護を同時に担うこと。2は、認定者数は、増えている。3は、地域包括ケアシステムで、家制度が廃止されたのではない。4は、三世代世帯の割合は、減少しているよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-065","examYear":"2024","examRound":"36","questionNumber":65,"category":"介護の基本","questionText":"介護福祉士に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"傷病者に対する療養上の世話又は診療の補助を業とする。"},{"id":"2","text":"喀痰吸引｛かくたんきゅういん｝を行うときは市町村の窓口に申請する。"},{"id":"3","text":"業務独占の資格である。"},{"id":"4","text":"資格を更新するために5年ごとに研修を受講する。"},{"id":"5","text":"信用を傷つけるような行為は禁止されている。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護福祉士は、社会福祉士及び介護福祉士法で、信用失墜行為の禁止が、定められているんだ。1は、療養上の世話や診療の補助は、看護師の業務。2は、喀痰吸引を行うには、都道府県への登録が必要。3は、介護福祉士は、名称独占の資格。4は、更新研修の義務はないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-066","examYear":"2024","examRound":"36","questionNumber":66,"category":"介護の基本","questionText":"施設利用者の個人情報の保護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"職員がすべての個人情報を自由に閲覧できるように、パスワードを共有する。"},{"id":"2","text":"個人情報を記載した書類は、そのまま新聞紙と一緒に捨てる。"},{"id":"3","text":"個人情報保護に関する研修会を定期的に開催し、意識の向上を図る。"},{"id":"4","text":"職員への守秘義務の提示は、採用時ではなく退職時に書面で行う。"},{"id":"5","text":"利用者の音声情報は、同意を得ずに使用できる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！個人情報を守るために、研修会を定期的に開いて、職員の意識を高めることが大切なんだ。1は、パスワードの共有は、危険。2は、個人情報を記載した書類は、シュレッダーなどで、処分する。4は、守秘義務は、採用時に示す。5は、音声情報も、同意を得てから使うんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-067","examYear":"2024","examRound":"36","questionNumber":67,"category":"介護の基本","questionText":"個別性や多様性を踏まえた介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"その人らしさは、障害特性から判断する。"},{"id":"2","text":"生活習慣は、生活してきた環境から理解する。"},{"id":"3","text":"生活歴は、成人期以降の情報から収集する。"},{"id":"4","text":"生活様式は、同居する家族と同一にする。"},{"id":"5","text":"衣服は、施設の方針によって統一する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！生活習慣は、その人が生活してきた環境から、理解すると、個別性に合った介護ができるんだ。1は、障害特性だけで、判断してはいけない。3は、生活歴は、幼少期からの情報を集める。4は、同居する家族と、同じにするとは限らない。5は、衣服は、その人の好みを尊重するよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-068","examYear":"2024","examRound":"36","questionNumber":68,"category":"介護の基本","questionText":"Ａさん（48歳、女性、要介護1）は、若年性認知症（dementia with early onset）で、夫、長女（高校1年生）と同居している。Ａさんは家族と過ごすことを希望し、小規模多機能型居宅介護で通いを中心に利用を始めた。Ａさんのことが心配な長女は、部活動を諦めて学校が終わるとすぐに帰宅していた。\nある日、夫が、「長女が、学校の先生たちにも相談しているが、今の状況をわかってくれる人がいないと涙を流すことがある」と介護福祉職に相談をした。\n夫の話を聞いた介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"長女に、掃除や洗濯の方法を教える。"},{"id":"2","text":"家族でもっと頑張るように、夫を励ます。"},{"id":"3","text":"同じような体験をしている人と交流できる場について情報を提供する。"},{"id":"4","text":"介護老人福祉施設への入所の申込みを勧める。"},{"id":"5","text":"介護支援専門員（ケアマネジャー）に介護サービスの変更を提案する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！長女は、ひとりで悩みを抱えているよね。同じような体験をしている人と交流できる場（家族会や、若年性認知症の人の家族の集まりなど）の情報を提供すると、気持ちを共有できて、支えになるんだ。1は、家事を教えるのは、負担を増やす。2は、励ますだけでは、解決しない。4、5は、家族の希望を、反映していないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-069","examYear":"2024","examRound":"36","questionNumber":69,"category":"介護の基本","questionText":"Ｂさん（61歳、男性、要介護3）は、脳梗塞（cerebral infarction）による左片麻痺｛ひだりかたまひ｝がある。週2回訪問介護（ホームヘルプサービス）を利用し、妻（58歳）と二人暮らしである。自宅での入浴が好きで、妻の介助を受けながら、毎日入浴している。サービス提供責任者に、Ｂさんから、「浴槽から立ち上がるのがつらくなってきた。何かいい方法はないですか」と相談があった。\nＢさんへのサービス提供責任者の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｂさんがひとりで入浴できるように、自立生活援助の利用を勧める。"},{"id":"2","text":"浴室を広くするために、居宅介護住宅改修費を利用した改築を勧める。"},{"id":"3","text":"妻の入浴介助の負担が軽くなるように、行動援護の利用を勧める。"},{"id":"4","text":"入浴補助用具で本人の力を生かせるように、特定福祉用具販売の利用を勧める。"},{"id":"5","text":"Ｂさんが入浴を継続できるように、通所介護（デイサービス）の利用を勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｂさんは、浴槽から立ち上がるのがつらいので、入浴補助用具を特定福祉用具販売で購入して、本人の力を生かす方法が適切なんだ。1の自立生活援助は、一人暮らしの支援、2の住宅改修で、浴室を広くする改築は、対象外、3の行動援護は、外出の支援、5のデイサービスは、自宅での入浴を続けたい希望に合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-070","examYear":"2024","examRound":"36","questionNumber":70,"category":"介護の基本","questionText":"社会奉仕の精神をもって、住民の立場に立って相談に応じ、必要な援助を行い、社会福祉の増進に努める者として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"民生委員"},{"id":"2","text":"生活相談員"},{"id":"3","text":"訪問介護員（ホームヘルパー）"},{"id":"4","text":"通所介護職員"},{"id":"5","text":"介護支援専門員（ケアマネジャー）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！民生委員は、社会奉仕の精神をもって、住民の立場に立って、相談に応じ、必要な援助を行い、社会福祉の増進に努める人で、民生委員法にもとづいて、厚生労働大臣が委嘱するんだ。2〜5は、それぞれ職場や制度に位置づけられた職種で、この説明とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-071","examYear":"2024","examRound":"36","questionNumber":71,"category":"介護の基本","questionText":"3階建て介護老人福祉施設がある住宅地に、洪水・内水氾濫の図記号マークに関連した警戒レベル3が発令された。介護福祉職がとるべき行動として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"玄関のドアを開けたままにする。"},{"id":"2","text":"消火器で、初期消火する。"},{"id":"3","text":"垂直避難誘導をする。"},{"id":"4","text":"利用者家族に安否情報を連絡する。"},{"id":"5","text":"転倒の危険性があるものを固定する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！警戒レベル3は、高齢者等避難で、避難に時間がかかる人は、避難を始める段階なんだ。3階建ての施設なら、上の階に移動する、垂直避難の誘導が適切だよ。1のドアを開けておく、2の初期消火、4の安否連絡、5の固定は、洪水への対応としては、優先度が低いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-072","examYear":"2024","examRound":"36","questionNumber":72,"category":"介護の基本","questionText":"次の記述のうち、介護における感染症対策として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"手洗いは、液体石鹸｛えきたいせっけん｝よりも固形石鹸｛こけいせっけん｝を使用する。"},{"id":"2","text":"配膳時にくしゃみが出たときは、口元をおさえた手でそのまま行う。"},{"id":"3","text":"嘔吐物｛おうとぶつ｝の処理は、素手で行う。"},{"id":"4","text":"排泄｛はいせつ｝の介護は、利用者ごとに手袋を交換する。"},{"id":"5","text":"うがい用のコップは、共用にする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！排泄の介護は、感染を広げないように、利用者ごとに手袋を交換するんだ。1は、液体石鹸のほうが衛生的。2は、くしゃみのあとは、手を洗う。3は、嘔吐物の処理は、手袋やマスクを着けて行う。5は、うがい用のコップは、共用しないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-073","examYear":"2024","examRound":"36","questionNumber":73,"category":"介護の基本","questionText":"介護福祉士が行う服薬の介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"服薬時間は、食後に統一する。"},{"id":"2","text":"服用できずに残った薬は、介護福祉士の判断で処分する。"},{"id":"3","text":"多種類の薬を処方された場合は、介護福祉士が一包化する。"},{"id":"4","text":"内服薬の用量は、利用者のその日の体調で決める。"},{"id":"5","text":"副作用の知識をもって、服薬の介護を行う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！服薬の介護では、薬の副作用の知識をもって、利用者の様子を観察することが大切なんだ。1は、服薬時間は、薬ごとに決められている。2は、残った薬は、医師や薬剤師に相談する。3は、一包化は、薬剤師が行う。4は、用量は、医師の指示によるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-074","examYear":"2024","examRound":"36","questionNumber":74,"category":"コミュニケーション技術","questionText":"Ｃさん（85歳、女性、要介護3）は、介護老人保健施設に入所しており、軽度の難聴がある。数日前から、職員は感染症対策として日常的にマスクを着用して勤務することになった。\nある日、Ｄ介護福祉職がＣさんの居室を訪問すると、「孫が絵を描いて送ってくれたの」と笑いながら絵を見せてくれた。Ｄ介護福祉職はＣさんの言動に共感的理解を示すために、意図的に非言語コミュニケーションを用いて対応した。\nこのときのＤ介護福祉職のＣさんへの対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「よかったですね」と紙に書いて渡した。"},{"id":"2","text":"目元を意識した笑顔を作り、大きくうなずいた。"},{"id":"3","text":"「お孫さんの絵が届いて、うれしかったですね」と耳元で話した。"},{"id":"4","text":"「私もうれしいです」と、ゆっくり話した。"},{"id":"5","text":"「えがとてもじょうずです」と五十音表を用いて伝えた。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！マスクをしていても、目元を意識した笑顔と、大きなうなずきで、共感をしっかり伝えられるんだ。これは、非言語コミュニケーションだよ。1と5は、文字などを使う方法、3と4は、話し言葉を使う、言語的なコミュニケーションだね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-075","examYear":"2024","examRound":"36","questionNumber":75,"category":"コミュニケーション技術","questionText":"利用者の家族との信頼関係の構築を目的としたコミュニケーションとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族に介護技術を教える。"},{"id":"2","text":"家族に介護をしている当事者の会に参加することを提案する。"},{"id":"3","text":"家族から介護の体験を共感的に聴く。"},{"id":"4","text":"家族に介護を続ける強い気持ちがあるかを質問する。"},{"id":"5","text":"家族に介護保険が使える範囲を説明する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！家族との信頼関係をつくるには、まず介護の体験を共感的に聴いて、気持ちを受け止めることが大切なんだ。1の技術指導、2の当事者の会の提案、4の質問、5の制度の説明は、信頼関係ができてからのほうが、効果的だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-076","examYear":"2024","examRound":"36","questionNumber":76,"category":"コミュニケーション技術","questionText":"Ｅさん（70歳、女性）は、脳梗塞（cerebral infarction）の後遺症で言語に障害がある。発語はできるが、話したいことをうまく言葉に言い表せない。聴覚機能に問題はなく、日常会話で使用する単語はだいたい理解できるが、単語がつながる文章になるとうまく理解できない。ある日、Ｅさんに介護福祉職が、「お風呂は、今日ではなくあしたですよ」と伝えると、Ｅさんはしばらく黙って考え、理解できない様子だった。\nこのとき、Ｅさんへの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「何がわからないのか教えてください」と質問する。"},{"id":"2","text":"「お風呂、あした」と短い言葉で伝える。"},{"id":"3","text":"「今日、お風呂に入りたいのですね」と確かめる。"},{"id":"4","text":"「あしたがお風呂の日で、今日は違いますよ」と言い換える。"},{"id":"5","text":"「お・ふ・ろ・は・あ・し・た」と1音ずつ言葉を区切って伝える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｅさんは、単語はだいたい理解できるけれど、文章になると理解しにくい状態なんだ。だから、「お風呂、あした」と、短い言葉で伝えるのがよいよ。1は、うまく言葉にできないので、答えにくい。3は、Ａさんの意図と、ちがうことを確認している。4は、長い文で、わかりにくい。5は、1音ずつ区切っても、効果は少ないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-077","examYear":"2024","examRound":"36","questionNumber":77,"category":"コミュニケーション技術","questionText":"Ｆさん（70歳、女性）は、最近、抑うつ状態（depressive state）にあり、ベッドに寝ていることが多く、「もう死んでしまいたい」とつぶやいていた。\nＦさんの発言に対する、介護福祉職の言葉かけとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「落ちこんだらだめですよ」"},{"id":"2","text":"「とてもつらいのですね」"},{"id":"3","text":"「どうしてそんなに寝てばかりいるのですか」"},{"id":"4","text":"「食堂へおしゃべりに行きましょう」"},{"id":"5","text":"「元気を出して、頑張ってください」"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｆさんは、抑うつ状態で、「もう死んでしまいたい」と話しているね。まずは、「とてもつらいのですね」と、気持ちを受け止める、共感的な言葉かけがよいんだ。1、5は、励ましやしかりで、追い詰めてしまう。3は、責めるような言い方、4は、気持ちを受け止めずに、誘っているよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-078","examYear":"2024","examRound":"36","questionNumber":78,"category":"コミュニケーション技術","questionText":"Ｇさん（70歳、女性、要介護1）は、有料老人ホームに入居していて、網膜色素変性症（retinitis pigmentosa）による夜盲がある。ある日の夕方、Ｇさんがうす暗い廊下を歩いているのをＨ介護福祉職が発見し、「Ｈです。大丈夫ですか」と声をかけた。Ｇさんは、「びっくりした。見えにくくて、わからなかった…」と暗い表情で返事をした。\nこのときのＧさんに対するＨ介護福祉職の受容的な対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「驚かせてしまいましたね。一緒に歩きましょうか」"},{"id":"2","text":"「明るいところを歩きましょう。電気をつけたほうがいいですよ」"},{"id":"3","text":"「見えにくくなってきたのですね。一緒に点字の練習を始めましょう」"},{"id":"4","text":"「白杖｛はくじょう｝があるかを確認しておきます。白杖｛はくじょう｝を使うようにしましょう」"},{"id":"5","text":"「暗い顔をしないでください。頑張りましょう」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｇさんは、夜盲で、見えにくいために、驚いて暗い表情になっているんだね。「驚かせてしまいましたね」と気持ちを受け止めて、「一緒に歩きましょうか」と寄り添うのが、受容的な対応だよ。2、4は、指示をしていて、3は、点字の練習は、ふさわしくない。5は、気持ちを否定しているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-079","examYear":"2024","examRound":"36","questionNumber":79,"category":"コミュニケーション技術","questionText":"事例検討の目的に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族に介護計画を説明し、同意を得る。"},{"id":"2","text":"上司に利用者への対応の結果を報告し、了解を得る。"},{"id":"3","text":"介護計画の検討をとおして、チームの交流を深める。"},{"id":"4","text":"チームで事例の課題を共有し、解決策を見いだす。"},{"id":"5","text":"各職種の日頃の悩みを共有する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！事例検討の目的は、チームで事例の課題を共有して、解決策を見つけることなんだ。1は、家族への説明、2は、上司への報告、3は、チームの交流、5は、悩みの共有で、事例検討の目的とは、ちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-080","examYear":"2024","examRound":"36","questionNumber":80,"category":"生活支援技術","questionText":"介護老人福祉施設における、レクリエーション活動に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者全員が参加することを重視する。"},{"id":"2","text":"毎回、異なるプログラムを企画する。"},{"id":"3","text":"プログラムに買い物や調理も取り入れる。"},{"id":"4","text":"利用者の過去の趣味を、プログラムに取り入れることは避ける。"},{"id":"5","text":"地域のボランティアの参加は、遠慮してもらう。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！レクリエーション活動に、買い物や調理を取り入れると、生活の中の楽しみや、できることを生かせるんだ。1は、全員参加を義務にはしない。2は、なじみのあるプログラムも、大切にする。4は、過去の趣味を、積極的に取り入れる。5は、ボランティアの参加は、歓迎するよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-081","examYear":"2024","examRound":"36","questionNumber":81,"category":"生活支援技術","questionText":"関節リウマチ（rheumatoid arthritis）で、関節の変形や痛みがある人への住まいに関する介護福祉職の助言として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"手すりは、握らずに利用できる平手すりを勧める。"},{"id":"2","text":"いすの座面の高さは、低いものを勧める。"},{"id":"3","text":"ベッドよりも、床に布団を敷いて寝るように勧める。"},{"id":"4","text":"部屋のドアは、開き戸を勧める。"},{"id":"5","text":"2階建ての家の場合、居室は2階にすることを勧める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！関節リウマチで、関節の変形や痛みがあるときは、手すりを握らなくても、前腕や手のひらで支えられる、平手すりが使いやすいんだ。2は、座面は、立ち上がりやすい高さにする。3は、床に布団は、関節への負担が大きい。4は、引き戸のほうが、開けやすい。5は、居室は1階にするよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-082","examYear":"2024","examRound":"36","questionNumber":82,"category":"生活支援技術","questionText":"心身機能が低下した高齢者の住環境の改善に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"玄関から道路までは、コンクリートから砂利敷きにする。"},{"id":"2","text":"扉の取っ手は、レバーハンドルから丸いドアノブにする。"},{"id":"3","text":"階段の足が乗る板と板の先端部分は、反対色から同系色にする。"},{"id":"4","text":"車いすを使用する居室の床は、畳から板製床材（フローリング）にする。"},{"id":"5","text":"浴槽は、和洋折衷式から洋式にする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！車いすを使う居室では、畳よりも、板製床材（フローリング）のほうが、車いすが動かしやすいんだ。1は、砂利敷きは、車いすで、通りにくい。2は、丸いドアノブより、レバーハンドルのほうが、握りやすい。3は、階段は、踏み板の先端を、反対色にして、見やすくする。5は、洋式の浴槽は、深くて、出入りしにくいこともあるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-083","examYear":"2024","examRound":"36","questionNumber":83,"category":"生活支援技術","questionText":"仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）から半座位（ファーラー位）にするとき、ギャッチベッドの背上げを行う前の介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"背部の圧抜きを行う。"},{"id":"2","text":"臀部｛でんぶ｝をベッド中央部の曲がる部分に合わせる。"},{"id":"3","text":"ベッドの高さを最も低い高さにする。"},{"id":"4","text":"利用者の足がフットボードに付くまで水平移動する。"},{"id":"5","text":"利用者のからだをベッドに対して斜めにする。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ギャッチアップする前は、臀部を、ベッドの曲がる部分（中央部）に合わせて、体のずれを防ぐんだ。1の背部の圧抜きは、背上げの後に行う。3は、ベッドの高さは、介護しやすい高さに調整する。4は、足がフットボードにつくまで動かす必要はない。5は、斜めにすると、体がねじれるよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-084","examYear":"2024","examRound":"36","questionNumber":84,"category":"生活支援技術","questionText":"回復期にある左片麻痺｛ひだりかたまひ｝の利用者が、ベッドで端座位から立位になるときの基本的な介護方法に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の右側に立つ。"},{"id":"2","text":"利用者に、ベッドに深く座るように促す。"},{"id":"3","text":"利用者に、背すじを伸ばして真上に立ち上がるように促す。"},{"id":"4","text":"利用者の左側に荷重がかかるように支える。"},{"id":"5","text":"利用者の左の膝頭に手を当てて保持し、膝折れを防ぐ。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！左片麻痺の人が立つときは、麻痺のある左膝が折れないように、左の膝頭に手を当てて、支えるのが基本なんだ。1は、麻痺のある左側に立って支える。2は、浅めに座って、足を引く。3は、前傾姿勢で、前方に立ち上がるように促す。4は、健側の右側に、荷重がかかるようにするよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-085","examYear":"2024","examRound":"36","questionNumber":85,"category":"生活支援技術","questionText":"標準型車いすを用いた移動の介護に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"急な上り坂は、すばやく進む。"},{"id":"2","text":"急な下り坂は、前向きで進む。"},{"id":"3","text":"踏切を渡るときは、駆動輪を上げて進む。"},{"id":"4","text":"エレベーターに乗るときは、正面からまっすぐに進む。"},{"id":"5","text":"段差を降りるときは、前輪から下りる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！エレベーターに乗るときは、正面からまっすぐ進んで、乗り込むんだ。1は、上り坂は、ゆっくり進む。2は、下り坂は、後ろ向きで下りる。3は、踏切は、前輪（キャスター）を上げて、進む。5は、段差を降りるときは、後ろ向きで、後輪から下りるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-086","examYear":"2024","examRound":"36","questionNumber":86,"category":"生活支援技術","questionText":"医学的管理の必要がない高齢者の爪の手入れに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"爪は、入浴の前に切る。"},{"id":"2","text":"爪の先の白い部分は、残らないように切る。"},{"id":"3","text":"爪は、一度にまっすぐ横に切る。"},{"id":"4","text":"爪の両端は、切らずに残す。"},{"id":"5","text":"爪切り後は、やすりをかけて滑らかにする。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！爪を切ったあとは、やすりをかけて、滑らかに整えると、引っかかりや傷を防げるんだ。1は、入浴後の、爪がやわらかいときに切る。2は、爪の先の白い部分は、1mmくらい残す。3は、一度にではなく、少しずつ切る。4は、両端も、切りすぎないように整えるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-087","examYear":"2024","examRound":"36","questionNumber":87,"category":"生活支援技術","questionText":"左片麻痺｛ひだりかたまひ｝の利用者が、端座位でズボンを着脱するときの介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"最初に、左側の腰を少し上げて脱ぐように促す。"},{"id":"2","text":"右膝を高く上げて、脱ぐように促す。"},{"id":"3","text":"左足を右の大腿｛だいたい｝の上にのせて、ズボンを通すように促す。"},{"id":"4","text":"立ち上がる前に、ズボンを膝下まで上げるように促す。"},{"id":"5","text":"介護福祉職は右側に立って、ズボンを上げるように促す。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！左片麻痺の人が、ズボンをはくときは、麻痺のある左足を、右の大腿の上にのせて、ズボンを通すと、はきやすくなるんだ（脱健着患）。1は、脱ぐときは、健側の右側から先に脱ぐ。2は、右膝を高く上げる必要はない。4は、立つ前に、膝下までではなく、大腿まで上げる。5は、介護福祉職は、麻痺のある左側に立つよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-088","examYear":"2024","examRound":"36","questionNumber":88,"category":"生活支援技術","questionText":"次のうち、嚥下機能｛えんげきのう｝の低下している利用者に提供するおやつとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"クッキー"},{"id":"2","text":"カステラ"},{"id":"3","text":"もなか"},{"id":"4","text":"餅"},{"id":"5","text":"プリン"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！プリンは、なめらかで、飲み込みやすいから、嚥下機能が低下した人に向いているんだ。1のクッキー、2のカステラ、3のもなかは、パサパサしたり、口の中でまとまらなかったりして、むせやすい。4の餅は、粘りが強くて、窒息の危険があるよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-089","examYear":"2024","examRound":"36","questionNumber":89,"category":"生活支援技術","questionText":"介護老人福祉施設の介護福祉職が、管理栄養士と連携することが必要な利用者の状態として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の食べ残しが目立つ。"},{"id":"2","text":"経管栄養をしている利用者が嘔吐｛おうと｝する。"},{"id":"3","text":"利用者の食事中の姿勢が不安定である。"},{"id":"4","text":"利用者の義歯がぐらついている。"},{"id":"5","text":"利用者の摂食・嚥下｛えんげ｝の機能訓練が必要である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！食べ残しが目立つ利用者は、栄養が足りなくなる可能性があるので、管理栄養士と連携して、食事量や内容を見直すんだ。2の嘔吐は、看護職員や医師、3の姿勢は、リハビリ職や介護福祉職、4の義歯は、歯科医師、5の機能訓練は、言語聴覚士などと連携するよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-090","examYear":"2024","examRound":"36","questionNumber":90,"category":"生活支援技術","questionText":"次の記述のうち、血液透析を受けている利用者への食事の介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"塩分の多い食品をとるように勧める。"},{"id":"2","text":"ゆでこぼした野菜をとるように勧める。"},{"id":"3","text":"乳製品を多くとるように勧める。"},{"id":"4","text":"水分を多くとるように勧める。"},{"id":"5","text":"魚や肉を使った料理を多くとるように勧める。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！血液透析を受けている人は、カリウムを制限する必要があるんだ。野菜をゆでこぼすと、カリウムが減らせるよ。1は、塩分は控える。3は、乳製品は、リンやカリウムが多い。4は、水分は、制限が必要。5は、魚や肉は、タンパク質やリンが多く、食べすぎに注意が必要なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-091","examYear":"2024","examRound":"36","questionNumber":91,"category":"生活支援技術","questionText":"介護老人福祉施設の一般浴（個浴）で、右片麻痺｛みぎかたまひ｝の利用者が移乗台に座っている。その状態から安全に入浴をするための介護福祉職の助言として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「浴槽に入るときは、右足から入りましょう」"},{"id":"2","text":"「湯につかるときは、左膝に手をついてゆっくり入りましょう」"},{"id":"3","text":"「浴槽内では、足で浴槽の壁を押すようにして姿勢を安定させましょう」"},{"id":"4","text":"「浴槽内では、後ろの壁に寄りかかり足を伸ばしましょう」"},{"id":"5","text":"「浴槽から出るときは、真上方向に立ち上がりましょう」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！浴槽の中では、足で浴槽の壁を押すようにして、姿勢を安定させると、体が動いたり、沈んだりするのを防げるんだ。1は、入るときは、健側の左足から入る。2は、右片麻痺なので、左膝ではなく、健側の手を支えにするのが基本。4は、後ろに寄りかかると、安定しない。5は、立ち上がるときは、前傾姿勢で、前に体重を移すんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-092","examYear":"2024","examRound":"36","questionNumber":92,"category":"生活支援技術","questionText":"次の記述のうち、椅座位で足浴を行う介護方法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ズボンを脱いだ状態で行う。"},{"id":"2","text":"湯温の確認は、介護福祉職より先に利用者にしてもらう。"},{"id":"3","text":"足底は、足浴用容器の底面に付いていることを確認する。"},{"id":"4","text":"足に付いた石鹸｛せっけん｝の泡は、洗い流さずに拭き取る。"},{"id":"5","text":"足浴用容器から足を上げた後は、自然乾燥させる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！椅座位の足浴では、足底が、足浴用容器の底面についていることを確認すると、姿勢が安定して、安全に行えるんだ。1は、ズボンは、ひざ下まで、たくし上げる。2は、湯温は、介護福祉職が先に確認する。4は、泡は、洗い流す。5は、足を上げたあとは、タオルで、水分をしっかり拭き取るんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-093","examYear":"2024","examRound":"36","questionNumber":93,"category":"生活支援技術","questionText":"身体機能が低下している高齢者が、ストレッチャータイプの特殊浴槽を利用するときの入浴介護の留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職2名で、洗髪と洗身を同時に行う。"},{"id":"2","text":"背部を洗うときは、側臥位｛そくがい｝にして行う。"},{"id":"3","text":"浴槽に入るときは、両腕の上から固定ベルトを装着する。"},{"id":"4","text":"浴槽では、首までつかるようにする。"},{"id":"5","text":"浴槽につかる時間は、20分程度とする。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ストレッチャータイプの特殊浴槽では、背部を洗うときは、側臥位にして行うんだ。1は、洗髪と洗身は、順番に行うほうが、安全。3は、固定ベルトは、腕の下を通して、装着する。4は、首までつかると、心臓に負担がかかる。5は、つかる時間は、5〜10分程度が目安だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-094","examYear":"2024","examRound":"36","questionNumber":94,"category":"生活支援技術","questionText":"Ｊさん（84歳、女性、要介護3）は、認知症（dementia）があり、夫（86歳、要支援1）と二人暮らしである。Ｊさんは尿意はあるが、夫の介護負担を軽減するため終日おむつを使用しており、尿路感染症（urinary tract infection）を繰り返していた。夫が体調不良になったので、Ｊさんは介護老人福祉施設に入所した。\nＪさんの尿路感染症（urinary tract infection）を予防する介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"尿の性状を観察する。"},{"id":"2","text":"体温の変化を観察する。"},{"id":"3","text":"陰部洗浄の回数を検討する。"},{"id":"4","text":"おむつを使わないで、トイレに誘導する。"},{"id":"5","text":"膀胱留置｛ぼうこうりゅうち｝カテーテルの使用を提案する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｊさんは、尿意があるのに、終日おむつを使っていて、尿路感染症を繰り返していたんだね。おむつを使わずに、トイレに誘導すれば、尿路感染症の予防にもなるし、自立にもつながるよ。1と2は、観察で、予防にはならない。3は、洗浄の回数を増やすだけでは、不十分。5は、カテーテルは、感染のリスクが高いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-095","examYear":"2024","examRound":"36","questionNumber":95,"category":"生活支援技術","questionText":"夜間、自宅のトイレでの排泄｛はいせつ｝が間に合わずに失敗してしまう高齢者への介護福祉職の助言として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"水分摂取量を減らすように勧める。"},{"id":"2","text":"終日、リハビリパンツを使用するように勧める。"},{"id":"3","text":"睡眠薬を服用するように勧める。"},{"id":"4","text":"泌尿器科を受診するように勧める。"},{"id":"5","text":"夜間は、ポータブルトイレを使用するように勧める。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！夜間にトイレが間に合わない人には、居室にポータブルトイレを置くと、移動の負担が減って、失敗を防げるんだ。1は、水分を減らすのは、脱水や、尿路感染症の原因になる。2は、終日のリハビリパンツは、自立を妨げる。3は、睡眠薬は、転倒のリスクが高い。4は、受診の助言は、介護福祉職の判断が先行しすぎるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-096","examYear":"2024","examRound":"36","questionNumber":96,"category":"生活支援技術","questionText":"介護福祉職が行うことができる、市販のディスポーザブルグリセリン浣腸器｛かんちょうき｝を用いた排便の介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"浣腸液｛かんちょうえき｝は、39℃～40℃に温める。"},{"id":"2","text":"浣腸液｛かんちょうえき｝を注入するときは、立位をとるように声をかける。"},{"id":"3","text":"浣腸液｛かんちょうえき｝は、すばやく注入する。"},{"id":"4","text":"浣腸液｛かんちょうえき｝を注入したら、すぐに排便するように声をかける。"},{"id":"5","text":"排便がない場合は、新しい浣腸液｛かんちょうえき｝を再注入する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！グリセリン浣腸液は、直腸を刺激しないように、39℃〜40℃くらいに温めて使うんだ。2は、左側臥位で行う。3は、ゆっくり注入する。4は、少し我慢してから排便してもらう（3分程度）。5は、再注入は、介護福祉職ではなく、医療職が判断するよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-097","examYear":"2024","examRound":"36","questionNumber":97,"category":"生活支援技術","questionText":"訪問介護員（ホームヘルパー）が行う見守り的援助として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ゴミの分別ができるように声をかける。"},{"id":"2","text":"利用者がテレビを見ている間に洗濯物を干す。"},{"id":"3","text":"着られなくなった服を作り直す。"},{"id":"4","text":"調理したものを盛り付け、食事を提供する。"},{"id":"5","text":"冷蔵庫の中を整理し、賞味期限が切れた食品を捨てておく。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！見守り的援助は、利用者が自分でできるように、声をかけて見守る援助なんだ。ゴミの分別ができるように声をかけるのは、その例だよ。2、5は、利用者ができることを代わりに行っている。3の服の作り直しと、4の食事の提供は、見守り的援助ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-098","examYear":"2024","examRound":"36","questionNumber":98,"category":"生活支援技術","questionText":"高齢者が靴下・靴を選ぶときの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"靴下は、指つきのきついものを勧める。"},{"id":"2","text":"靴下は、足底に滑り止めがあるものを勧める。"},{"id":"3","text":"靴は、床面からつま先までの高さが小さいものを勧める。"},{"id":"4","text":"靴は、踵｛かかと｝のない脱ぎやすいものを勧める。"},{"id":"5","text":"靴は、先端部に0.5～1cmの余裕があるものを勧める。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！靴は、先端部に0.5〜1cmくらいの余裕があると、指が圧迫されず、歩きやすいんだ。1は、指つきのきついものは、血行が悪くなる。2は、滑り止めが強いと、すり足で引っかかりやすい。3は、つま先の高さが小さいと、つまずきやすい。4は、かかとのない靴は、脱げやすくて、転倒しやすいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-099","examYear":"2024","examRound":"36","questionNumber":99,"category":"生活支援技術","questionText":"Ｋさん（77歳、女性、要支援2）は、もの忘れが目立ちはじめ、訪問介護（ホームヘルプサービス）を利用しながら夫と二人で生活している。訪問時、Ｋさん夫婦から、「Ｋさんがテレビショッピングで購入した健康食品が毎月届いてしまい、高額の支払いが発生して困っている」と相談があった。\nＫさん夫婦に対する訪問介護員（ホームヘルパー）の発言として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「健康食品は処分しましょう」"},{"id":"2","text":"「クーリング・オフをしましょう」"},{"id":"3","text":"「買い物は夫がするようにしましょう」"},{"id":"4","text":"「契約内容を一緒に確認しましょう」"},{"id":"5","text":"「テレビショッピングでの買い物はやめましょう」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｋさん夫婦が困っているから、まずは、契約内容を一緒に確認して、状況を整理するのがよいんだ。1は、勝手に処分してはダメ。2は、クーリング・オフは、期間や条件があり、まず状況の確認が必要。3、5は、Ｋさんの自由を、制限してしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-100","examYear":"2024","examRound":"36","questionNumber":100,"category":"生活支援技術","questionText":"消化管ストーマを造設した利用者への睡眠の介護に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"寝る前にストーマから出血がある場合は、軟膏｛なんこう｝を塗布する。"},{"id":"2","text":"寝る前に、パウチに便がたまっていたら捨てる。"},{"id":"3","text":"寝る前に、ストーマ装具を新しいものに交換する。"},{"id":"4","text":"便の漏れが心配な場合は、パウチの上からおむつを強く巻く。"},{"id":"5","text":"睡眠を妨げないように、パウチの観察は控える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ストーマがある人は、寝る前に、パウチにたまった便を捨てておくと、寝ている間に、便が漏れたり、パウチが外れたりするのを防げるんだ。1は、出血があるときは、医療職に報告する。3は、装具は、決められた間隔で交換する。4は、パウチの上から、おむつを強く巻かない。5は、観察は、必要だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-101","examYear":"2024","examRound":"36","questionNumber":101,"category":"生活支援技術","questionText":"Ｌさん（79歳、男性、要介護2）は、介護老人保健施設に入所して1か月が経過した。睡眠中に大きないびきをかいていることが多く、いびきの音が途切れることもある。夜間に目を覚ましていたり、起床時にだるそうにしている様子もしばしば見られている。\n介護福祉職がＬさんについて収集すべき情報として、最も優先度の高いものを1つ選びなさい。","choices":[{"id":"1","text":"枕の高さ"},{"id":"2","text":"マットレスの硬さ"},{"id":"3","text":"掛け布団の重さ"},{"id":"4","text":"睡眠中の足の動き"},{"id":"5","text":"睡眠中の呼吸状態"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｌさんは、大きないびきで、いびきの音が途切れることがあり、夜間に目を覚まして、起床時にだるそうだね。睡眠時無呼吸症候群が疑われるので、睡眠中の呼吸状態の情報が、最も優先度が高いんだ。1、2、3は、寝具の情報で、4の足の動きは、周期性四肢運動障害の観察だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-102","examYear":"2024","examRound":"36","questionNumber":102,"category":"生活支援技術","questionText":"Ｍさん（98歳、男性、要介護5）は、介護老人福祉施設に入所している。誤嚥性肺炎｛ごえんせいはいえん｝（aspiration pneumonia）で入退院を繰り返し、医師からは終末期が近い状態であるといわれている。\n介護福祉職が確認すべきこととして、最も優先度の高いものを1つ選びなさい。","choices":[{"id":"1","text":"主治医の今後の見通し"},{"id":"2","text":"誤嚥性肺炎｛ごえんせいはいえん｝（aspiration pneumonia）の発症時の入院先"},{"id":"3","text":"経口摂取に対する本人の意向"},{"id":"4","text":"経口摂取に対する家族の意向"},{"id":"5","text":"延命治療に対する家族の希望"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！終末期が近いＭさんの支援では、本人の意向を、最も大切にするんだ。だから、まず、経口摂取に対する本人の意向を確認することが、最優先だよ。1の主治医の見通し、2の入院先、4と5の家族の意向も大切だけど、本人の意思が第一なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-103","examYear":"2024","examRound":"36","questionNumber":103,"category":"生活支援技術","questionText":"デスカンファレンス（death conference）の目的に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"一般的な死の受容過程を学習する。"},{"id":"2","text":"終末期を迎えている利用者の介護について検討する。"},{"id":"3","text":"利用者の家族に対して、死が近づいたときの身体の変化を説明する。"},{"id":"4","text":"亡くなった利用者の事例を振り返り、今後の介護に活用する。"},{"id":"5","text":"終末期の介護に必要な死生観を統一する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！デスカンファレンスは、亡くなった利用者の事例を、チームで振り返って、今後の介護に生かすための話し合いなんだ。1は、学習、2は、終末期の利用者の介護の検討、3は、家族への説明、5は、死生観を統一することで、デスカンファレンスの目的ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-104","examYear":"2024","examRound":"36","questionNumber":104,"category":"生活支援技術","questionText":"福祉用具を活用するときの基本的な考え方として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"福祉用具が活用できれば、住宅改修は検討しない。"},{"id":"2","text":"複数の福祉用具を使用するときは、状況に合わせた組合せを考える。"},{"id":"3","text":"福祉用具の選択に迷うときは、社会福祉士に選択を依頼する。"},{"id":"4","text":"家族介護者の負担軽減を最優先して選ぶ。"},{"id":"5","text":"福祉用具の利用状況のモニタリング（monitoring）は不要である。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！福祉用具を複数使うときは、利用者の状況に合わせて、組合せを考えることが大切なんだ。1は、住宅改修も、あわせて検討する。3は、選択は、福祉用具専門相談員や、多職種と検討する。4は、利用者本人の状態や希望が、まず大切。5は、利用状況のモニタリングは、必要だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-105","examYear":"2024","examRound":"36","questionNumber":105,"category":"生活支援技術","questionText":"次のうち、握力の低下がある利用者が使用する杖｛つえ｝として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"T字杖"},{"id":"2","text":"オフセット杖"},{"id":"3","text":"ロフストランド・クラッチ"},{"id":"4","text":"多点杖"},{"id":"5","text":"サイドケイン"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ロフストランド・クラッチは、前腕で体重を支えられるから、握力が低下している人にも使いやすい杖なんだ。1のT字杖、2のオフセット杖、4の多点杖、5のサイドケインは、握力が必要な杖だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-106","examYear":"2024","examRound":"36","questionNumber":106,"category":"介護過程","questionText":"介護福祉職が、初回の面談で情報を収集するときの留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"用意した項目を次から次に質問する。"},{"id":"2","text":"目的を意識しながら話を聴く。"},{"id":"3","text":"ほかの利用者が同席する状況で質問する。"},{"id":"4","text":"最初に経済状態に関する質問をする。"},{"id":"5","text":"家族の要望を中心に話を聴く。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！初回の面談では、情報を集める目的を意識しながら、相手の話を聴くことが大切なんだ。1は、次から次へと質問すると、緊張させてしまう。3は、ほかの利用者が同席する状況は、プライバシーの面で不適切。4は、経済状態は、最初に聞く質問ではない。5は、利用者本人の話を、中心に聴くんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-107","examYear":"2024","examRound":"36","questionNumber":107,"category":"介護過程","questionText":"介護過程の評価に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"生活状況が変化しても、介護計画で設定した日に評価する。"},{"id":"2","text":"サービス担当者会議で評価する。"},{"id":"3","text":"相談支援専門員が中心になって評価する。"},{"id":"4","text":"利用者の満足度を踏まえて評価する。"},{"id":"5","text":"介護計画の実施中に評価基準を設定する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！介護過程の評価では、利用者の満足度も踏まえて、目標が達成できたかを判断するんだ。1は、生活状況が変化したときは、評価日を待たず、見直す。2は、サービス担当者会議は、評価の場とは限らない。3は、相談支援専門員は、障害福祉の職種。5は、評価の基準は、計画を立てるときに設定するよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-108","examYear":"2024","examRound":"36","questionNumber":108,"category":"介護過程","questionText":"次の記述のうち、介護老人保健施設で多職種連携によるチームアプローチ（team approach）を実践するとき、介護福祉職が担う役割として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の生活状況の変化に関する情報を提供する。"},{"id":"2","text":"総合的な支援の方向性を決める。"},{"id":"3","text":"サービス担当者会議を開催する。"},{"id":"4","text":"必要な検査を指示する。"},{"id":"5","text":"ほかの職種が担う貢献度を評価する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！介護福祉職は、利用者の日常生活に、最も近い立場にいるから、生活状況の変化に関する情報を、チームに提供する役割が大切なんだ。2は、支援の方向性を決めるのは、チーム全体。3は、サービス担当者会議は、介護支援専門員などが開催する。4は、検査の指示は、医師の役割。5は、ほかの職種の貢献度を、評価する役割はないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-109","examYear":"2024","examRound":"36","questionNumber":109,"category":"介護過程","questionText":"次の事例を読んで、問題109、問題110について答えなさい。\n〔事  例〕\nＡさん（75歳、女性）は、一人暮らしで、身体機能に問題はない。70歳まで地域の子どもたちに大正琴を教えていた。認知症（dementia）の進行が疑われて、心配した友人が地域包括支援センターに相談した結果、Ａさんは介護老人福祉施設に入所することになった。入所時のＡさんの要介護度は3であった。\n入所後、短期目標を、「施設に慣れ、安心して生活する（3か月）」と設定し、計画は順調に進んでいた。Ａさんは施設の大正琴クラブに自ら進んで参加し、演奏したり、ほかの利用者に大正琴を笑顔で教えたりしていた。ある日、クラブの終了後に、Ａさんは部屋に戻らずに、エレベーターの前で立ち止まっていた。介護職員が声をかけると、Ａさんが、「あの子たちが待っているの」と強い口調で言った。\n大正琴クラブが終わった後のＡさんの行動を解釈するために必要な情報として、最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"介護職員の声かけのタイミング"},{"id":"2","text":"Ａさんが演奏した時間"},{"id":"3","text":"「あの子たちが待っているの」という発言"},{"id":"4","text":"クラブに参加した利用者の人数"},{"id":"5","text":"居室とエレベーターの位置関係"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ａさんは、「あの子たちが待っているの」と話していて、大正琴を教えていた子どもたちのことを思っていると考えられるんだ。だから、行動の意味を理解するためには、その発言が、最も優先すべき情報だよ。1、2、4、5は、行動の意味を解釈するための、手がかりにはなりにくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-110","examYear":"2024","examRound":"36","questionNumber":110,"category":"介護過程","questionText":"次の事例を読んで、問題109、問題110について答えなさい。\n〔事  例〕\nＡさん（75歳、女性）は、一人暮らしで、身体機能に問題はない。70歳まで地域の子どもたちに大正琴を教えていた。認知症（dementia）の進行が疑われて、心配した友人が地域包括支援センターに相談した結果、Ａさんは介護老人福祉施設に入所することになった。入所時のＡさんの要介護度は3であった。\n入所後、短期目標を、「施設に慣れ、安心して生活する（3か月）」と設定し、計画は順調に進んでいた。Ａさんは施設の大正琴クラブに自ら進んで参加し、演奏したり、ほかの利用者に大正琴を笑顔で教えたりしていた。ある日、クラブの終了後に、Ａさんは部屋に戻らずに、エレベーターの前で立ち止まっていた。介護職員が声をかけると、Ａさんが、「あの子たちが待っているの」と強い口調で言った。\nＡさんの状況から支援を見直すことになった。\n次の記述のうち、新たな支援の方向性として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護職員との関係を改善する。"},{"id":"2","text":"身体機能を改善する。"},{"id":"3","text":"演奏できる自信を取り戻す。"},{"id":"4","text":"エレベーターの前に座れる環境を整える。"},{"id":"5","text":"大正琴を教える役割をもつ。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、大正琴を教えていた経験があって、施設のクラブでも、ほかの利用者に笑顔で教えていたよね。大正琴を教える役割をもつことが、Ａさんの意欲や、生きがいを支える方向性として、ぴったりなんだ。1、2は、問題の中心ではないよ。3は、すでに演奏できている。4は、エレベーター前の待機を、認めるだけになってしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-111","examYear":"2024","examRound":"36","questionNumber":111,"category":"介護過程","questionText":"次の事例を読んで、問題111、問題112について答えなさい。\n〔事  例〕\nＢさん（50歳、男性、障害支援区分3）は、49歳のときに脳梗塞（cerebral infarction）を発症し、左片麻痺｛ひだりかたまひ｝で高次脳機能障害（higher brain dysfunction）と診断された。以前は大工で、手先が器用だったと言っている。\n現在は就労継続支援Ｂ型事業所に通っている。短期目標を、「右手を使い、作業を自分ひとりで行える（3か月）」と設定し、製品を箱に入れる単純作業を任されていた。ほかの利用者との人間関係も良好で、左片麻痺｛ひだりかたまひ｝に合わせた作業台で、毎日の作業目標を達成していた。生活支援員には、「将来は手先を使う仕事に就きたい」と希望を話していた。\n将来に向けて、生活支援員が新たに製品の組立て作業を提案すると、Ｂさんも喜んで受け入れた。初日に、「ひとりで頑張る」と始めたが、途中で何度も手が止まり、完成品に不備が見られた。生活支援員が声をかけると、「こんなの、できない」と大声を出した。\n生活支援員の声かけに対し、Ｂさんが大声を出した理由を解釈する視点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ほかの利用者との人間関係"},{"id":"2","text":"生活支援員に話した将来の希望"},{"id":"3","text":"製品を箱に入れる毎日の作業量"},{"id":"4","text":"製品の組立て作業の状況"},{"id":"5","text":"左片麻痺｛ひだりかたまひ｝に合わせた作業台"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｂさんは、これまでの単純作業は順調だったけれど、初めての組立て作業で、途中で手が止まり、不備が出て、大声を出したんだね。だから、大声を出した理由は、製品の組立て作業の状況（難しさ）を、まず考えるのがよいよ。1、3、5は、これまで順調だった内容。2は、将来の希望は、意欲につながっているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-112","examYear":"2024","examRound":"36","questionNumber":112,"category":"介護過程","questionText":"次の事例を読んで、問題111、問題112について答えなさい。\n〔事  例〕\nＢさん（50歳、男性、障害支援区分3）は、49歳のときに脳梗塞（cerebral infarction）を発症し、左片麻痺｛ひだりかたまひ｝で高次脳機能障害（higher brain dysfunction）と診断された。以前は大工で、手先が器用だったと言っている。\n現在は就労継続支援Ｂ型事業所に通っている。短期目標を、「右手を使い、作業を自分ひとりで行える（3か月）」と設定し、製品を箱に入れる単純作業を任されていた。ほかの利用者との人間関係も良好で、左片麻痺｛ひだりかたまひ｝に合わせた作業台で、毎日の作業目標を達成していた。生活支援員には、「将来は手先を使う仕事に就きたい」と希望を話していた。\n将来に向けて、生活支援員が新たに製品の組立て作業を提案すると、Ｂさんも喜んで受け入れた。初日に、「ひとりで頑張る」と始めたが、途中で何度も手が止まり、完成品に不備が見られた。生活支援員が声をかけると、「こんなの、できない」と大声を出した。\nＢさんに対するカンファレンス（conference）が開催され、短期目標を達成するための具体的な支援について見直すことになった。\n次の記述のうち、見直した支援内容として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"完成品の不備を出すことへの反省を促す。"},{"id":"2","text":"左側に部品を置いて作業するように促す。"},{"id":"3","text":"完成までの手順を理解しやすいように示す。"},{"id":"4","text":"生活支援員が横に座り続けて作業内容を指示する。"},{"id":"5","text":"製品を箱に入れる単純作業も同時に行うように調整する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｂさんは、高次脳機能障害があって、組立ての手順がわかりにくくて、手が止まった可能性があるんだ。完成までの手順を、理解しやすいように示すことが、短期目標の達成につながるよ。1は、反省を促すだけで、支援にならない。2は、右手を使う目標に合わない。4は、自分ひとりで行う目標に合わない。5は、負担が増えてしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-113","examYear":"2024","examRound":"36","questionNumber":113,"category":"介護過程","questionText":"事例研究を行うときに、遵守すべき倫理的配慮として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"研究内容を説明して、事例対象者の同意を得る。"},{"id":"2","text":"個人が特定できるように、氏名を記載する。"},{"id":"3","text":"得られたデータは、研究終了後すぐに破棄する。"},{"id":"4","text":"論文の一部であれば、引用元を明示せずに利用できる。"},{"id":"5","text":"研究成果を得るために、事実を拡大解釈する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！事例研究では、研究の内容を説明して、事例の対象者から同意を得ることが、大切な倫理的配慮なんだ。2は、個人が特定できないように、匿名化する。3は、データは、決められた期間、適切に保管する。4は、引用するときは、引用元を明示する。5は、事実を、拡大解釈してはダメだよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-114","examYear":"2024","examRound":"36","questionNumber":114,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＣさん（59歳、男性）は、妻（55歳）と二人暮らしであり、専業農家である。Ｃさんはおとなしい性格であったが、最近怒りやすくなったと妻は感じていた。Ｃさんは毎日同じ時間に同じコースを散歩している。ある日、散歩コースの途中にあり、昔からよく行く八百屋から、「Ｃさんが代金を支払わずに商品を持っていった。今回で2回目になる。お金を支払いにきてもらえないか」と妻に連絡があった。妻がＣさんに確認したところ、悪いことをした認識がなかった。心配になった妻がＣさんと病院に行くと、前頭側頭型認知症（frontotemporal dementia）と診断を受けた。妻は今後同じようなことが起きないように、Ｃさんの行動を常に見守り、外出を制限したが、疲労がたまり、今後の生活に不安を感じた。そこで、地域包括支援センターに相談し、要介護認定の申請を行い、訪問介護（ホームヘルプサービス）を利用することになった。\nＣさんが八百屋でとった行動から考えられる状態として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"脱抑制"},{"id":"2","text":"記憶障害"},{"id":"3","text":"感情失禁"},{"id":"4","text":"見当識障害"},{"id":"5","text":"遂行機能障害"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｃさんは、前頭側頭型認知症で、代金を支払わずに商品を持っていっても、悪いことをした認識がないんだね。これは、社会のルールを守る抑えが効かなくなる、脱抑制の症状なんだ。2の記憶障害や、4の見当識障害は、アルツハイマー型で目立つ。3の感情失禁は、感情のコントロールがきかない、5の遂行機能障害は、手順を組み立てる障害だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-115","examYear":"2024","examRound":"36","questionNumber":115,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＣさん（59歳、男性）は、妻（55歳）と二人暮らしであり、専業農家である。Ｃさんはおとなしい性格であったが、最近怒りやすくなったと妻は感じていた。Ｃさんは毎日同じ時間に同じコースを散歩している。ある日、散歩コースの途中にあり、昔からよく行く八百屋から、「Ｃさんが代金を支払わずに商品を持っていった。今回で2回目になる。お金を支払いにきてもらえないか」と妻に連絡があった。妻がＣさんに確認したところ、悪いことをした認識がなかった。心配になった妻がＣさんと病院に行くと、前頭側頭型認知症（frontotemporal dementia）と診断を受けた。妻は今後同じようなことが起きないように、Ｃさんの行動を常に見守り、外出を制限したが、疲労がたまり、今後の生活に不安を感じた。そこで、地域包括支援センターに相談し、要介護認定の申請を行い、訪問介護（ホームヘルプサービス）を利用することになった。\nＣさんの介護保険制度の利用に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護保険サービスの利用者負担割合は1割である。"},{"id":"2","text":"介護保険料は特別徴収によって納付する。"},{"id":"3","text":"要介護認定の結果が出る前に介護保険サービスを利用することはできない。"},{"id":"4","text":"要介護認定の利用者負担割合は2割である。"},{"id":"5","text":"介護保険サービスの費用はサービスの利用回数に関わらず定額である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｃさんは、59歳で、第2号被保険者だよ。第2号被保険者の利用者負担は、所得にかかわらず、1割なんだ。2は、保険料は、医療保険料と一緒に納める。3は、認定前でも、申請すれば、暫定ケアプランで、サービスを利用できる。4は、2割ではなく、1割。5は、費用は、利用したサービスの量に応じて、変わるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-116","examYear":"2024","examRound":"36","questionNumber":116,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＣさん（59歳、男性）は、妻（55歳）と二人暮らしであり、専業農家である。Ｃさんはおとなしい性格であったが、最近怒りやすくなったと妻は感じていた。Ｃさんは毎日同じ時間に同じコースを散歩している。ある日、散歩コースの途中にあり、昔からよく行く八百屋から、「Ｃさんが代金を支払わずに商品を持っていった。今回で2回目になる。お金を支払いにきてもらえないか」と妻に連絡があった。妻がＣさんに確認したところ、悪いことをした認識がなかった。心配になった妻がＣさんと病院に行くと、前頭側頭型認知症（frontotemporal dementia）と診断を受けた。妻は今後同じようなことが起きないように、Ｃさんの行動を常に見守り、外出を制限したが、疲労がたまり、今後の生活に不安を感じた。そこで、地域包括支援センターに相談し、要介護認定の申請を行い、訪問介護（ホームヘルプサービス）を利用することになった。\nその後、妻に外出を制限されたＣさんは不穏となった。困った妻が訪問介護員（ホームヘルパー）に相談したところ、「八百屋に事情を話して事前にお金を渡して、Ｃさんが品物を持ち去ったときは、渡したお金から商品代金を支払うようにお願いしてはどうか」とアドバイスを受けた。\n訪問介護員（ホームヘルパー）が意図したＣさんへの関わりをＩＣＦ（International Classification of Functioning, Disability and Health：国際生活機能分類）に当てはめた記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"個人因子への影響を意図して、健康状態に働きかける。"},{"id":"2","text":"健康状態への影響を意図して、心身機能に働きかける。"},{"id":"3","text":"活動への影響を意図して、身体構造に働きかける。"},{"id":"4","text":"参加への影響を意図して、環境因子に働きかける。"},{"id":"5","text":"環境因子への影響を意図して、個人因子に働きかける。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！訪問介護員は、八百屋に事情を話して、事前にお金を渡すという、環境因子に働きかけたんだね。これによって、Ｃさんが、散歩や買い物を続けられるという、参加への影響を意図しているよ。1、2、3、5は、ＩＣＦの要素の、働きかけの向きや、組合せが、ちがっているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-117","examYear":"2024","examRound":"36","questionNumber":117,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＤさん（70歳、男性）は、自宅で妻と二人暮らしで、年金収入で生活している。ある日、車を運転中に事故に遭い救急搬送された。医師からは、第4胸髄節まで機能が残存している脊髄損傷（spinal cord injury）と説明を受けた。Ｄさんは、入院中に要介護3の認定を受けた。\nＤさんは、退院後は自宅で生活することを望んでいた。妻は一緒に暮らしたいと思うが、Ｄさんの身体状況を考えると不安を感じていた。介護支援専門員（ケアマネジャー）は、「退院後は、在宅復帰を目的に、一定の期間、リハビリテーション専門職がいる施設で生活してはどうか」とＤさんに提案した。Ｄさんは妻と退院後の生活について話し合った結果、一定期間施設に入所して、その間に、自宅の住宅改修を行うことにして、介護支援専門員（ケアマネジャー）に居宅介護住宅改修費について相談した。\n次のうち、Ｄさんが提案を受けた施設として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"養護老人ホーム"},{"id":"2","text":"軽費老人ホーム"},{"id":"3","text":"介護老人福祉施設"},{"id":"4","text":"介護老人保健施設"},{"id":"5","text":"介護医療院"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｄさんは、在宅復帰を目的に、リハビリテーション専門職がいる施設で、一定期間生活するので、介護老人保健施設がぴったりなんだ。1の養護老人ホームと、2の軽費老人ホームは、生活の場。3の介護老人福祉施設は、終の棲家として、長期の生活が中心。5の介護医療院は、長期療養と生活の場だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-118","examYear":"2024","examRound":"36","questionNumber":118,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＤさん（70歳、男性）は、自宅で妻と二人暮らしで、年金収入で生活している。ある日、車を運転中に事故に遭い救急搬送された。医師からは、第4胸髄節まで機能が残存している脊髄損傷（spinal cord injury）と説明を受けた。Ｄさんは、入院中に要介護3の認定を受けた。\nＤさんは、退院後は自宅で生活することを望んでいた。妻は一緒に暮らしたいと思うが、Ｄさんの身体状況を考えると不安を感じていた。介護支援専門員（ケアマネジャー）は、「退院後は、在宅復帰を目的に、一定の期間、リハビリテーション専門職がいる施設で生活してはどうか」とＤさんに提案した。Ｄさんは妻と退院後の生活について話し合った結果、一定期間施設に入所して、その間に、自宅の住宅改修を行うことにして、介護支援専門員（ケアマネジャー）に居宅介護住宅改修費について相談した。\n次のうち、介護支援専門員（ケアマネジャー）がＤさんに説明する居宅介護住宅改修費の支給限度基準額として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"10万円"},{"id":"2","text":"15万円"},{"id":"3","text":"20万円"},{"id":"4","text":"25万円"},{"id":"5","text":"30万円"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！居宅介護住宅改修費の支給限度基準額は、原則として、1人につき20万円で、そのうち、自己負担を除いた額が、支給されるんだ。手すりの取り付けや、段差の解消などが、対象になるよ。この金額は、しっかり覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-119","examYear":"2024","examRound":"36","questionNumber":119,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＤさん（70歳、男性）は、自宅で妻と二人暮らしで、年金収入で生活している。ある日、車を運転中に事故に遭い救急搬送された。医師からは、第4胸髄節まで機能が残存している脊髄損傷（spinal cord injury）と説明を受けた。Ｄさんは、入院中に要介護3の認定を受けた。\nＤさんは、退院後は自宅で生活することを望んでいた。妻は一緒に暮らしたいと思うが、Ｄさんの身体状況を考えると不安を感じていた。介護支援専門員（ケアマネジャー）は、「退院後は、在宅復帰を目的に、一定の期間、リハビリテーション専門職がいる施設で生活してはどうか」とＤさんに提案した。Ｄさんは妻と退院後の生活について話し合った結果、一定期間施設に入所して、その間に、自宅の住宅改修を行うことにして、介護支援専門員（ケアマネジャー）に居宅介護住宅改修費について相談した。\nＤさんが施設入所してから3か月後、住宅改修を終えた自宅に戻ることになった。Ｄさんは自宅での生活を楽しみにしている。その一方で、不安も抱えていたため、担当の介護福祉士は、理学療法士と作業療法士に相談して、生活上の留意点を記載した冊子を作成して、Ｄさんに手渡した。\n次の記述のうち、冊子の内容として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食事では、スプーンを自助具で手に固定する。"},{"id":"2","text":"移動には、リクライニング式車いすを使用する。"},{"id":"3","text":"寝具は、エアーマットを使用する。"},{"id":"4","text":"更衣は、ボタンエイドを使用する。"},{"id":"5","text":"外出するときには、事前に多機能トイレの場所を確認する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！第4胸髄まで機能が残っているＤさんは、上肢の機能は、保たれているけれど、下半身の麻痺があり、排泄の障害もあるんだ。外出するときには、多機能トイレの場所を、事前に確認しておくことが大切だよ。1、2、4は、上肢の機能が、大きく低下している人向けの用具や、方法だね。3も、褥瘡の予防で大切だけど、冊子で優先して伝える内容は、外出時の備えなんだ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-120","examYear":"2024","examRound":"36","questionNumber":120,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＥさん（34歳、女性、障害支援区分3）は、特別支援学校の高等部を卒業後、週2回、生活介護を利用しながら自宅で生活している。Ｅさんはアテトーゼ型（athetosis）の脳性麻痺｛のうせいまひ｝（cerebral palsy）で不随意運動があり、首を振る動作が見られる。\n食事は首の動きに合わせて、自助具を使って食べている。食事中は不随意運動が強く、食事が終わると、「首が痛い、しびれる」と言ってベッドに横になるときがある。\nまた、お茶を飲むときは取っ手つきのコップで飲んでいるが、コップを口元に運ぶまでにお茶がこぼれるようになってきた。日頃から自分のことは自分でやりたいと考えていて、お茶が上手に飲めなくなってきたことを気にしている。\nＥさんは、生活介護事業所で油絵を描くことを楽しみにしている。以前から隣町の油絵教室に通い技術を高めたいと話していた。そこでＥさんは、「自宅から油絵教室に通うときの介助をお願いするにはどうしたらよいか」と介護福祉職に相談した。\nＥさんの食事の様子から、今後、引き起こされる可能性が高いと考えられる二次障害として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"変形性股関節症（coxarthrosis）"},{"id":"2","text":"廃用症候群（disuse syndrome）"},{"id":"3","text":"起立性低血圧（orthostatic hypotension）"},{"id":"4","text":"脊柱側弯症｛せきちゅうそくわんしょう｝（scoliosis）"},{"id":"5","text":"頚椎症性脊髄症｛けいついしょうせいせきずいしょう｝（cervical spondylotic myelopathy）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！アテトーゼ型の脳性麻痺では、首の不随意運動が長く続くと、頸椎に負担がかかって、頚椎症性脊髄症などの二次障害が起こりやすいんだ。Ｅさんの、「首が痛い、しびれる」という訴えが、そのサインだね。1、2、3、4は、Ｅさんの状態から、まず起こる可能性が高い二次障害とはいえないよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-121","examYear":"2024","examRound":"36","questionNumber":121,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＥさん（34歳、女性、障害支援区分3）は、特別支援学校の高等部を卒業後、週2回、生活介護を利用しながら自宅で生活している。Ｅさんはアテトーゼ型（athetosis）の脳性麻痺｛のうせいまひ｝（cerebral palsy）で不随意運動があり、首を振る動作が見られる。\n食事は首の動きに合わせて、自助具を使って食べている。食事中は不随意運動が強く、食事が終わると、「首が痛い、しびれる」と言ってベッドに横になるときがある。\nまた、お茶を飲むときは取っ手つきのコップで飲んでいるが、コップを口元に運ぶまでにお茶がこぼれるようになってきた。日頃から自分のことは自分でやりたいと考えていて、お茶が上手に飲めなくなってきたことを気にしている。\nＥさんは、生活介護事業所で油絵を描くことを楽しみにしている。以前から隣町の油絵教室に通い技術を高めたいと話していた。そこでＥさんは、「自宅から油絵教室に通うときの介助をお願いするにはどうしたらよいか」と介護福祉職に相談した。\nＥさんがお茶を飲むときの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"吸い飲みに変更する。"},{"id":"2","text":"ストローつきコップに変更する。"},{"id":"3","text":"重いコップに変更する。"},{"id":"4","text":"コップを両手で持つように伝える。"},{"id":"5","text":"全介助を行う。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｅさんは、不随意運動があって、コップを口元に運ぶまでに、お茶がこぼれるんだね。ストローつきコップなら、口元に運ぶ動作が少なくて、自分で飲む機会を保ちやすいんだ。1は、吸い飲みは、介助が必要になりやすい。3は、重いコップは、負担が大きい。4は、両手で持つのは、不随意運動で難しい。5は、自分でやりたい気持ちを、奪ってしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-122","examYear":"2024","examRound":"36","questionNumber":122,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＥさん（34歳、女性、障害支援区分3）は、特別支援学校の高等部を卒業後、週2回、生活介護を利用しながら自宅で生活している。Ｅさんはアテトーゼ型（athetosis）の脳性麻痺｛のうせいまひ｝（cerebral palsy）で不随意運動があり、首を振る動作が見られる。\n食事は首の動きに合わせて、自助具を使って食べている。食事中は不随意運動が強く、食事が終わると、「首が痛い、しびれる」と言ってベッドに横になるときがある。\nまた、お茶を飲むときは取っ手つきのコップで飲んでいるが、コップを口元に運ぶまでにお茶がこぼれるようになってきた。日頃から自分のことは自分でやりたいと考えていて、お茶が上手に飲めなくなってきたことを気にしている。\nＥさんは、生活介護事業所で油絵を描くことを楽しみにしている。以前から隣町の油絵教室に通い技術を高めたいと話していた。そこでＥさんは、「自宅から油絵教室に通うときの介助をお願いするにはどうしたらよいか」と介護福祉職に相談した。\n介護福祉職は、Ｅさんが隣町の油絵教室に通うことができるようにサービスを提案したいと考えている。\n次のうち、Ｅさんが利用するサービスとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自立生活援助"},{"id":"2","text":"療養介護"},{"id":"3","text":"移動支援"},{"id":"4","text":"自立訓練"},{"id":"5","text":"同行援護"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！移動支援は、市町村の地域生活支援事業で、外出が難しい人が、余暇活動や社会参加のために、外出するときの支援を行うんだ。油絵教室に通うのは、その例だよ。1は、一人暮らしの支援。2は、医療と介護が必要な人向け。4は、生活能力を高める訓練。5の同行援護は、視覚障害のある人向けだね。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-123","examYear":"2024","examRound":"36","questionNumber":123,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＦさん（20歳、男性）は、自閉症スペクトラム障害（autism spectrum disorder）と重度の知的障害があり、自宅で母親（50歳）、姉（25歳）と3人で暮らしている。\nＦさんは生活介護事業所を利用している。事業所では比較的落ち着いているが、自宅に帰ってくると母親に対してかみつきや頭突きをすることがあった。また、自分で頭をたたくなどの自傷行為もたびたび見られる。\n仕事をしている母親に代わり、小さい頃から食事や排泄｛はいせつ｝の介護をしている姉は、これまでＦさんの行動を止めることができていたが、最近ではからだが大きくなり力も強くなって、母親と協力しても止めることが難しくなっていた。\n家族で今後のことを考えた結果、Ｆさんは障害者支援施設に入所することになった。\n次のうち、Ｆさんが自宅に帰ってきたときの状態に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"学習障害"},{"id":"2","text":"注意欠陥多動性障害"},{"id":"3","text":"高次脳機能障害"},{"id":"4","text":"強度行動障害"},{"id":"5","text":"気分障害"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！自閉症スペクトラム障害と重度の知的障害があって、かみつきや頭突き、自傷行為が、頻繁にみられるのは、強度行動障害の状態なんだ。1は読み書きなどの障害、2は不注意や多動などの障害、3は事故や病気による脳の障害、5は、うつ病などの気分の障害で、事例とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-124","examYear":"2024","examRound":"36","questionNumber":124,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＦさん（20歳、男性）は、自閉症スペクトラム障害（autism spectrum disorder）と重度の知的障害があり、自宅で母親（50歳）、姉（25歳）と3人で暮らしている。\nＦさんは生活介護事業所を利用している。事業所では比較的落ち着いているが、自宅に帰ってくると母親に対してかみつきや頭突きをすることがあった。また、自分で頭をたたくなどの自傷行為もたびたび見られる。\n仕事をしている母親に代わり、小さい頃から食事や排泄｛はいせつ｝の介護をしている姉は、これまでＦさんの行動を止めることができていたが、最近ではからだが大きくなり力も強くなって、母親と協力しても止めることが難しくなっていた。\n家族で今後のことを考えた結果、Ｆさんは障害者支援施設に入所することになった。\nＦさんが入所してからも月1、2回は、姉が施設を訪ね、Ｆさんの世話をしている。\nある日、担当の介護福祉職が姉に声をかけると、「小学生の頃から、学校が終わると友だちと遊ばずにまっすぐ家に帰り、母親に代わって、弟の世話をしてきた。今は、弟を見捨てたようで、申し訳ない」などと話す。\n介護福祉職の姉への対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「これからもＦさんのお世話をしっかり行ってください」"},{"id":"2","text":"「Ｆさんは落ち着いていて、自傷他害行為があるようには見えませんね」"},{"id":"3","text":"「お姉さんは、小さい頃からお母さんの代わりをしてきたのですね」"},{"id":"4","text":"「訪問回数を減らしてはどうですか」"},{"id":"5","text":"「施設入所を後悔しているのですね。もう一度在宅ケアを考えましょう」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！姉は、小さい頃からＦさんの世話をしてきた思いを話しているね。「小さい頃からお母さんの代わりをしてきたのですね」と、姉の気持ちを受け止めて、共感することが、大切な対応なんだ。1は、負担を押しつけている。2は、姉の気持ちに触れていない。4は、訪問を減らす話ではない。5は、決めつけて、方針を戻そうとしているよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2024-36-125","examYear":"2024","examRound":"36","questionNumber":125,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＦさん（20歳、男性）は、自閉症スペクトラム障害（autism spectrum disorder）と重度の知的障害があり、自宅で母親（50歳）、姉（25歳）と3人で暮らしている。\nＦさんは生活介護事業所を利用している。事業所では比較的落ち着いているが、自宅に帰ってくると母親に対してかみつきや頭突きをすることがあった。また、自分で頭をたたくなどの自傷行為もたびたび見られる。\n仕事をしている母親に代わり、小さい頃から食事や排泄｛はいせつ｝の介護をしている姉は、これまでＦさんの行動を止めることができていたが、最近ではからだが大きくなり力も強くなって、母親と協力しても止めることが難しくなっていた。\n家族で今後のことを考えた結果、Ｆさんは障害者支援施設に入所することになった。\nＦさんが施設に入所して1年が経った。介護福祉職は、Ｆさん、母親、姉と共にこれまでの生活と支援を振り返り、当面、施設で安定した生活が送れるように検討した。\n次のうち、Ｆさんの支援を修正するときに利用するサービスとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"地域定着支援"},{"id":"2","text":"計画相談支援"},{"id":"3","text":"地域移行支援"},{"id":"4","text":"基幹相談支援"},{"id":"5","text":"基本相談支援"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！計画相談支援は、サービス等利用計画の作成と、その後のモニタリングを行うサービスで、支援を修正するときに、利用するんだ。1の地域定着支援と、3の地域移行支援は、地域生活への移行や、定着のための支援。4の基幹相談支援は、地域の相談支援の中核的な機能。5の基本相談支援は、相談や情報提供などの基本的な相談だよ。","source":"公益財団法人 社会福祉振興・試験センター 第36回（令和5年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/listen_k_pm_36.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no36/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-001","examYear":"2025","examRound":"37","questionNumber":1,"category":"人間の尊厳と自立","questionText":"次の記述のうち、介護福祉職がアドボカシー（advocacy）の視点から行う対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護を行う前には、利用者に十分な説明をして同意を得る。"},{"id":"2","text":"利用者の介護計画を作成するときに、他職種に専門的な助言を求める。"},{"id":"3","text":"利用者個人の趣味を生かして、レクリエーション活動を行う。"},{"id":"4","text":"希望を言い出しにくい利用者の意思をくみ取り、その実現に向けて働きかける。"},{"id":"5","text":"視覚障害者が必要とする情報を、利用しやすいようにする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！アドボカシーは、自分の思いを言い出しにくい人の気持ちをくみ取って、その実現に向けて働きかける「権利擁護」のことなんだ。1は説明と同意、2は他職種との連携、3は趣味を生かした活動、5は情報を利用しやすくする配慮だね。どれも大切な対応だけど、代弁して権利を守る視点ではないから、ちがうよ！","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-002","examYear":"2025","examRound":"37","questionNumber":2,"category":"人間の尊厳と自立","questionText":"Ａさん（83歳、女性、要介護3）は、脳梗塞（cerebral infarction）の後遺症で左片麻痺｛まひ｝があり、介護老人福祉施設で生活している。家族から、「できることは自分で行ってほしい」と希望があり、Ａさんは自室から食堂まで車いすで自走することを日課としている。\n1週間前から、介護福祉士養成施設の学生がＡさんのフロアで実習を開始した。数日前からＡさんは実習生に、「今日は腕が痛いので、食堂まで車いすを押してください」と依頼するようになった。悩んだ実習生は、実習指導者に相談をした。\n実習生に対する実習指導者の最初の助言として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「Ａさんの腕は痛くないので、気にしないでください」"},{"id":"2","text":"「どのようなときも、Ａさん自身で行ってもらうことが必要です」"},{"id":"3","text":"「ご家族から自分で行うように、言われています」"},{"id":"4","text":"「それは自立につながらないので、車いすを押さないでください」"},{"id":"5","text":"「Ａさんが依頼する理由を、まず考えてみることが大切です」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんが「押してほしい」と言う裏には、本当に腕が痛い、話をしたいなど、何か理由があるかもしれないよね。だから最初の助言は、まず理由を考えてみること。1は痛みを決めつけているし、2と4は自立を一方的に求めているし、3は家族の希望を理由にしているよ。どれもＡさんの思いを受け止められていないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-003","examYear":"2025","examRound":"37","questionNumber":3,"category":"人間関係とコミュニケーション","questionText":"人間関係と心理に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自己愛とは、自分という存在を、他人と区別して意識することである。"},{"id":"2","text":"自己同一性の確立とは、自分とは何かという認識をもつことである。"},{"id":"3","text":"自我とは、日常行動に影響を与える、表面化していない意識のことである。"},{"id":"4","text":"自己覚知とは、コミュニケーションにおいて自分について話すことである。"},{"id":"5","text":"自己中心性とは、自分の意思で自分の行動をコントロールすることである。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！自己同一性（アイデンティティ）は、「自分とは何者か」という一貫した認識のこと。自分らしさの土台になるんだ。1は自己愛ではなく自己意識の説明。3は無意識の説明で、自我は行動を調整する主体だよ。4の自己覚知は自分の傾向に気づくこと。5は自己統制の説明で、自己中心性は他者の視点に立てないことだね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-004","examYear":"2025","examRound":"37","questionNumber":4,"category":"人間関係とコミュニケーション","questionText":"Ａさん（80歳、男性）は、有料老人ホームに入所することになった。一人暮らしが長かったＡさんは、入所当日、担当の介護福祉職と話すことに戸惑っている様子で、なかなか自分のことを話そうとはしなかった。介護福祉職は、一方的な働きかけにならないように、Ａさんとコミュニケーションをとるとき、あいづちを打ちながらＡさんの発話を引き出すように心がけた。\nこのときの、介護福祉職の対応の意図に当てはまるものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"互いの自己開示"},{"id":"2","text":"コミュニケーション能力の評価"},{"id":"3","text":"感覚機能の低下への配慮"},{"id":"4","text":"認知機能の改善"},{"id":"5","text":"双方向のやり取り"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！あいづちを打って相手の話を引き出すのは、一方通行にならず、お互いに働きかけ合う「双方向のやり取り」をつくるためなんだ。会話はキャッチボールだね。1は職員も自分のことを話す場合、2は能力を評価すること、3は感覚機能の低下への配慮、4は認知機能を改善することで、この場面の意図とは合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-005","examYear":"2025","examRound":"37","questionNumber":5,"category":"人間関係とコミュニケーション","questionText":"次の記述のうち、介護福祉職のキャリアパスに関するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護計画を作成するときのポイントを明確にする。"},{"id":"2","text":"介護福祉職の業務マニュアルを具体化する。"},{"id":"3","text":"利用サービスに応じて求められる関係書類を検討する。"},{"id":"4","text":"介護施設に必要な設備基準について確認する。"},{"id":"5","text":"介護福祉職として必要な能力や経験を明確にする。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！キャリアパスは、目指す職位や役割にたどり着くまでの道筋のこと。そのために必要な能力や経験をはっきりさせることが当てはまるんだ。将来の地図づくりみたいだね。1は介護計画、2はマニュアル、3は関係書類、4は施設の設備基準の話で、どれも業務や施設運営のことだから、個人の成長の道筋とは別なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-006","examYear":"2025","examRound":"37","questionNumber":6,"category":"人間関係とコミュニケーション","questionText":"Ｂ介護老人福祉施設に、学校を卒業したばかりの元気なＣ介護福祉職が加わった。2か月後、ユニットリーダーが、「最近、Ｃ介護福祉職に笑顔が少ない。いつもとちがう様子だ」と、フォロワーであるＤ介護福祉職に話した。Ｄ介護福祉職はチームの一員として何ができるのかを考えた。\nＤ介護福祉職が最初に行うフォロワーシップとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｃ介護福祉職に対して、元気を出すように励ます。"},{"id":"2","text":"ユニットリーダーが気になっていることを詳しく聞く。"},{"id":"3","text":"Ｃ介護福祉職の状況をユニット内のほかのメンバーと速やかに共有する。"},{"id":"4","text":"施設長に対して、何か指示を出すようにお願いする。"},{"id":"5","text":"Ｃ介護福祉職に対して、介助方法について教える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！フォロワーは、リーダーを支えながらチームに貢献する存在。まずは、リーダーが気になった様子を詳しく聞いて、状況を正しく知ることが最初の一歩なんだ。1は根拠のない励まし、3は本人の同意なしに情報を広めてしまうよ。4は施設長への丸投げ、5は原因を確かめずに指導していて、どれも早すぎる対応だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-007","examYear":"2025","examRound":"37","questionNumber":7,"category":"社会の理解","questionText":"社会福祉法に基づく社会福祉法人に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"収益事業は禁止されている。"},{"id":"2","text":"所轄庁は内閣府である。"},{"id":"3","text":"設立時に所轄庁の認可は不要である。"},{"id":"4","text":"評議員会を置く必要がある。"},{"id":"5","text":"解散は禁止されている。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！社会福祉法人には、意思決定の機関として評議員会を必ず置くんだ。1は、社会福祉事業に充てる収益事業なら行えるよ。2は、所轄庁は原則として都道府県知事や市長などだね。3は、設立には所轄庁の認可が必要。5は、解散の規定があって、禁止されてはいないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-008","examYear":"2025","examRound":"37","questionNumber":8,"category":"社会の理解","questionText":"次の記述のうち、定期巡回・随時対応型訪問介護看護の説明として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"利用定員は、9人以下と定められている。"},{"id":"2","text":"日中・夜間を通じて、提供するサービスである。"},{"id":"3","text":"認知症対応型共同生活介護（認知症高齢者グループホーム）に入居する利用者に対して、機能訓練を行うサービスである。"},{"id":"4","text":"通い、泊まり、看護の3種類の組合せによるサービスである。"},{"id":"5","text":"都道府県が事業者の指定、指導、監督を行うサービスである。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！定期巡回・随時対応型訪問介護看護は、日中も夜間も通して、定期的な巡回と、通報に応じた随時対応を組み合わせたサービスなんだ。1の定員9人以下はグループホームなど別のサービス。3は機能訓練ではなく、4は小規模多機能型の説明だね。5は、事業者を指定するのは市町村（地域密着型サービス）だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-009","examYear":"2025","examRound":"37","questionNumber":9,"category":"社会の理解","questionText":"Ａさん（48歳、会社員）は、うつ症状から体調不良が続き、仕事を休むことが増えたため、自主的に退職した。その後、体調は回復したが、再就職先がなかなか見つからなかった。しばらく貯金で生活していたが、数か月後、生活を営むことができなくなってしまった。頼れる親族はなく、生活保護を受給することにした。\nこの事例において、日本国憲法に基づいてＡさんに保障された権利として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"団体交渉権"},{"id":"2","text":"平等権"},{"id":"3","text":"財産権"},{"id":"4","text":"思想の自由"},{"id":"5","text":"生存権"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！日本国憲法第25条は、「健康で文化的な最低限度の生活」を営む権利、つまり生存権を保障していて、生活保護制度のもとになっているんだ。1の団体交渉権は労働者の権利、2は平等権、3は財産権、4は思想の自由で、どれも大切だけど、生活に困ったＡさんを支える根拠にはならないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-010","examYear":"2025","examRound":"37","questionNumber":10,"category":"社会の理解","questionText":"次の記述のうち、保健所に関するものとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"保健師助産師看護師法に基づいて設置されている。"},{"id":"2","text":"すべての市町村に設置の義務がある。"},{"id":"3","text":"業務には精神保健に関する事項が含まれている。"},{"id":"4","text":"歯科衛生士を置かなくてはならない。"},{"id":"5","text":"児童の一時保護を行う。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！保健所は地域保健法に基づいて設置されていて、精神保健、感染症対策、難病対策などの業務を行うんだ。1は保健師助産師看護師法ではないよ。2は、設置主体は都道府県や政令市などで、すべての市町村にはないんだ。4は歯科衛生士の必置義務はなし。5の一時保護は児童相談所の仕事だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-011","examYear":"2025","examRound":"37","questionNumber":11,"category":"社会の理解","questionText":"地域包括支援センターの業務に関する記述として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"地域ケア会議の開催"},{"id":"2","text":"施設サービスのケアプランの作成"},{"id":"3","text":"成年後見制度の申請"},{"id":"4","text":"介護認定審査会の設置"},{"id":"5","text":"地域密着型サービスの事業者の指導・監督"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！地域包括支援センターは、地域ケア会議の開催や総合相談など、地域の高齢者を支える拠点なんだ。2の施設サービスのケアプラン作成は施設の介護支援専門員、3の成年後見の申立ては本人や親族、市町村長など、4の介護認定審査会は市町村が設置、5の事業者の指導監督は指定した自治体の仕事だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-012","examYear":"2025","examRound":"37","questionNumber":12,"category":"社会の理解","questionText":"Ｂさん（85歳、男性、要支援1）は、自宅で一人暮らしをしている。最近、物忘れが多くなり、1か月前から地域支援事業の訪問型サービスを利用するようになった。ある日、Ｂさんが、「これからも自宅で生活したいが、日中、話し相手がいなくて寂しい」と介護福祉職に話した。\n次のうち、Ｂさんに介護福祉職が勧めるサービスとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"認知症対応型共同生活介護（認知症高齢者グループホーム）"},{"id":"2","text":"介護老人福祉施設"},{"id":"3","text":"第一号通所事業（通所型サービス）"},{"id":"4","text":"夜間対応型訪問介護"},{"id":"5","text":"居宅療養管理指導"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｂさんは要支援1で、自宅で暮らしたいけれど話し相手がいなくて寂しいんだね。通所型サービスなら、日中に人と交流できて、在宅生活も続けられるよ。1と2は入居や入所で希望とちがうし、介護老人福祉施設は原則要介護3以上だね。4は夜間の対応、5は医師などの指導で、寂しさの解消には合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-013","examYear":"2025","examRound":"37","questionNumber":13,"category":"社会の理解","questionText":"介護保険制度に関する記述として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"第1号被保険者の保険料は、都道府県が徴収する。"},{"id":"2","text":"第1号被保険者の保険料は、全国一律である。"},{"id":"3","text":"第2号被保険者の保険料は、年金保険の保険料と合わせて徴収される。"},{"id":"4","text":"財源には、第1号被保険者の保険料と第2号被保険者の保険料が含まれる。"},{"id":"5","text":"介護保険サービスの利用者負担割合は、一律、1割である。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！介護保険の財源は、公費と、第1号被保険者・第2号被保険者の保険料でまかなわれているんだ。1は、第1号の保険料を徴収するのは市町村。2は、市町村ごとに基準額がちがうよ。3は、第2号の保険料は年金ではなく、医療保険の保険料と合わせて徴収されるんだ。5は、利用者負担は所得に応じて1〜3割だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-014","examYear":"2025","examRound":"37","questionNumber":14,"category":"社会の理解","questionText":"障害者の雇用の促進等に関する法律に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"2024年度（令和6年度）の民間企業の法定雇用率は、2.5％である。"},{"id":"2","text":"精神障害者は、法定雇用率の対象から除外されている。"},{"id":"3","text":"2024年度（令和6年度）に、障害者の雇用義務が生じるのは、従業員101人以上の事業主である。"},{"id":"4","text":"週所定労働時間が10時間以上20時間未満の労働は認められていない。"},{"id":"5","text":"2024年度（令和6年度）の事業主支援（助成金）は、2023年度（令和5年度）以前と同じである。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！2024年度（令和6年度）の民間企業の法定雇用率は2.5％なんだ。2は、精神障害者も対象に含まれているよ。3は、雇用義務が生じるのは従業員40人以上の事業主に広がったんだ。4は、週10時間以上20時間未満の労働も、雇用率に算定できるようになったよ。5は、助成金の内容は見直されて変わっているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-015","examYear":"2025","examRound":"37","questionNumber":15,"category":"社会の理解","questionText":"「障害者総合支援法」のサービスに関する次の記述のうち、適切なものを1つ選びなさい。\n（注）  「障害者総合支援法」とは、「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。","choices":[{"id":"1","text":"介護給付費の支給を受けるときに、障害支援区分の認定は不要である。"},{"id":"2","text":"短期入所は介護給付の1つである。"},{"id":"3","text":"地域生活支援事業は、国が実施主体である。"},{"id":"4","text":"自立支援給付は応益負担である。"},{"id":"5","text":"行動援護は訓練等給付の1つである。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！短期入所（ショートステイ）は、介護給付の1つなんだ。1は、介護給付を受けるには障害支援区分の認定が必要だよ。3は、地域生活支援事業の実施主体は市町村や都道府県だね。4は、自立支援給付は所得に応じた負担（応能負担）なんだ。5の行動援護は、訓練等給付ではなく介護給付だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-016","examYear":"2025","examRound":"37","questionNumber":16,"category":"社会の理解","questionText":"障害児支援に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"サービスを受けるには、療育手帳の取得が必要である。"},{"id":"2","text":"放課後等デイサービスは、子ども・子育て支援法に基づく支援である。"},{"id":"3","text":"障害児通所支援の利用には、障害児支援利用計画の作成は不要である。"},{"id":"4","text":"障害児入所支援は、すべての市町村が実施主体である。"},{"id":"5","text":"保育所等訪問支援は、保育所等を訪問し、障害のある児童が集団生活に適応できるように専門的な支援を行う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！保育所等訪問支援は、保育所などを訪問して、障害のある子どもが集団生活に適応できるよう専門的な支援をするサービスなんだ。1は、療育手帳がなくてもサービスは使えるよ。2の放課後等デイサービスは児童福祉法に基づくんだ。3は計画の作成が必要、4は障害児入所支援の実施主体は都道府県だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-017","examYear":"2025","examRound":"37","questionNumber":17,"category":"社会の理解","questionText":"次の記述のうち、サービス付き高齢者向け住宅に関するものとして、正しいものを1つ選びなさい。\n（注）  「高齢者住まい法」とは、「高齢者の居住の安定確保に関する法律」のことである。","choices":[{"id":"1","text":"「高齢者住まい法」に基づく、高齢者のための住まいである。"},{"id":"2","text":"65歳以上の者が、市町村の措置によって入居する。"},{"id":"3","text":"認知症高齢者を対象とした、共同生活の住居である。"},{"id":"4","text":"食事サービスの提供が義務づけられている。"},{"id":"5","text":"介護サービスの提供が義務づけられている。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！サービス付き高齢者向け住宅は、「高齢者住まい法」に基づいて登録される、高齢者のための賃貸住宅なんだ。2は、市町村の措置ではなく、契約で入居するよ。3は、認知症高齢者専用の住居ではないんだ。4と5は、義務なのは安否確認と生活相談で、食事や介護サービスの提供は義務ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-018","examYear":"2025","examRound":"37","questionNumber":18,"category":"社会の理解","questionText":"Ｃさん（60歳、男性）は、休日に自宅で趣味の家庭菜園の作業中に脳出血（cerebral hemorrhage）を起こして救急搬送された。特に麻痺｛まひ｝はなく、その後、リハビリテーション病院に転院した。現在は、高次脳機能障害（higher brain dysfunction）の治療とリハビリテーションに専念している。\n医療費を支払うときにＣさんが利用する制度として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護保険制度"},{"id":"2","text":"労働者災害補償保険制度"},{"id":"3","text":"雇用保険制度"},{"id":"4","text":"医療保険制度"},{"id":"5","text":"年金制度"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｃさんは休日の趣味の最中に発症していて、仕事が原因ではないので、労災保険は使えないんだ。病院での治療やリハビリの医療費を支払うときは、医療保険制度を使うよ。1の介護保険は介護サービスの費用、3の雇用保険は失業や育児休業などの給付、5の年金は所得保障のための制度だから、医療費の支払いとはちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-019","examYear":"2025","examRound":"37","questionNumber":19,"category":"こころとからだのしくみ","questionText":"次のうち、恐怖や不安、喜びなどの情動に関わる脳の機能局在の部位として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"扁桃体｛へんとうたい｝"},{"id":"2","text":"小脳"},{"id":"3","text":"下垂体"},{"id":"4","text":"海馬"},{"id":"5","text":"視床下部"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！扁桃体は、恐怖や不安、喜びなどの情動にかかわる脳の部位なんだ。2の小脳は運動の調節、3の下垂体はホルモンの分泌、4の海馬は記憶、5の視床下部は自律神経や体温の調節にかかわるよ。どこが何を担当しているのか、セットで覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-020","examYear":"2025","examRound":"37","questionNumber":20,"category":"こころとからだのしくみ","questionText":"次のうち、顔の感覚に関与する脳神経として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"嗅神経"},{"id":"2","text":"三叉神経｛さんさしんけい｝"},{"id":"3","text":"顔面神経"},{"id":"4","text":"迷走神経"},{"id":"5","text":"舌下神経"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！三叉神経は、顔の感覚と、かむ筋肉の運動をつかさどる脳神経なんだ。1の嗅神経は嗅覚、3の顔面神経は表情筋の運動や味覚、4の迷走神経は内臓の運動や感覚、5の舌下神経は舌の運動を担当しているよ。名前と役割を結びつけて覚えよう！","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-021","examYear":"2025","examRound":"37","questionNumber":21,"category":"こころとからだのしくみ","questionText":"次の記述のうち、鼻の構造と機能として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"鼻腔｛びくう｝は前鼻道・中鼻道・後鼻道に分かれる。"},{"id":"2","text":"鼻毛は塵｛ちり｝や埃｛ほこり｝を除去する。"},{"id":"3","text":"鼻腔｛びくう｝の奥は喉頭に直接つながっている。"},{"id":"4","text":"鼻腔｛びくう｝には毛細血管は少ない。"},{"id":"5","text":"嗅細胞は外鼻孔にある。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！鼻毛は、空気といっしょに入ってくる塵や埃をフィルターのように取り除くんだ。1は、鼻腔は上・中・下鼻道に分かれるよ。3は、鼻腔の奥は咽頭につながるんだね。4は、鼻腔には毛細血管が多くて、空気を温めているよ。5は、嗅細胞は外鼻孔ではなく、鼻腔の上部の粘膜にあるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-022","examYear":"2025","examRound":"37","questionNumber":22,"category":"こころとからだのしくみ","questionText":"次のうち、歯周病（periodontal disease）の症状として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"歯のくぼみの形成"},{"id":"2","text":"歯の硬組織の軟化"},{"id":"3","text":"歯髄の炎症・疼痛｛とうつう｝"},{"id":"4","text":"歯のエナメル質の侵蝕｛しんしょく｝"},{"id":"5","text":"歯周ポケットの形成"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！歯周病は、歯ぐきや歯を支える骨などに炎症が起きて、歯と歯ぐきのすき間が深くなる歯周ポケットができるんだ。1、2、4は、むし歯（う蝕）やその進行の様子で、3の歯髄の炎症・疼痛は、むし歯が深く進んだときの症状だね。歯周病と、むし歯の症状はちがうんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-023","examYear":"2025","examRound":"37","questionNumber":23,"category":"こころとからだのしくみ","questionText":"Ａさん（78歳、女性）は、友人から口臭を指摘されて悩んでいる。また、食事をするときに、「水分と一緒に食べないと飲み込みにくい」とも話している。Ａさんに歯の欠損、麻痺｛まひ｝はなく、ストレスの訴えもない。\n次のうち、Ａさんのからだの中で、機能低下が考えられるものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"咀嚼｛そしゃく｝"},{"id":"2","text":"蠕動運動｛ぜんどううんどう｝"},{"id":"3","text":"嗅覚"},{"id":"4","text":"唾液分泌"},{"id":"5","text":"胃液分泌"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！口臭があって、水分と一緒でないと飲み込みにくいのは、口の中が乾く（口腔乾燥）サイン。つまり唾液分泌の低下が考えられるんだ。歯の欠損や麻痺がないので、1の咀嚼は問題なさそうだね。ストレスの訴えもなく、2の蠕動運動、3の嗅覚、5の胃液分泌の低下では、この症状は説明できないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-024","examYear":"2025","examRound":"37","questionNumber":24,"category":"こころとからだのしくみ","questionText":"皮膚の構造に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"表皮の厚さは平均2.0mmである。"},{"id":"2","text":"真皮には角質層がある。"},{"id":"3","text":"外界と接する組織は表皮である。"},{"id":"4","text":"皮脂腺は皮下組織にある。"},{"id":"5","text":"表皮の最表面は基底層である。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！皮膚は外側から表皮・真皮・皮下組織の順になっていて、外界と接しているのは表皮なんだ。1は、表皮の厚さは平均0.2mm程度だよ。2は、角質層は表皮にあるね。4は、皮脂腺は真皮にあるんだ。5は、表皮の最表面は角質層で、基底層は最も深い層だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-025","examYear":"2025","examRound":"37","questionNumber":25,"category":"こころとからだのしくみ","questionText":"次のうち、高齢者が嗜好｛しこう｝や温度覚の低下によって高温浴を希望した場合に、説明すべき高温浴の特徴として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"血圧の上昇"},{"id":"2","text":"腸蠕動｛ちょうぜんどう｝の促進"},{"id":"3","text":"腎機能の促進"},{"id":"4","text":"副交感神経の亢進｛こうしん｝"},{"id":"5","text":"心機能の抑制"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！熱い湯（42℃以上の高温浴）は、交感神経が優位になって、血圧が上がり、心臓にも負担がかかるんだ。だから、高齢者には特に注意が必要だよ。2は腸の動きが抑えられ、3と5は逆の作用、4は副交感神経が高まるのは、ぬるめの湯（38〜40℃）のときだね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-026","examYear":"2025","examRound":"37","questionNumber":26,"category":"こころとからだのしくみ","questionText":"次のうち、食物の栄養素の大部分を吸収する部位として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"胃"},{"id":"2","text":"小腸"},{"id":"3","text":"直腸"},{"id":"4","text":"横行結腸"},{"id":"5","text":"Ｓ状結腸"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！小腸は、食べ物の栄養素の大部分を吸収する場所なんだ。表面にひだや絨毛がたくさんあって、表面積が広いんだね。1の胃は消化が中心で、3の直腸、4の横行結腸、5のＳ状結腸は大腸の一部。大腸では、主に水分が吸収されるよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-027","examYear":"2025","examRound":"37","questionNumber":27,"category":"こころとからだのしくみ","questionText":"次の記述のうち、レム睡眠に関するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"記憶を整理し、定着させる。"},{"id":"2","text":"脳を休息させる。"},{"id":"3","text":"入眠初期に出現する。"},{"id":"4","text":"成長ホルモンの分泌を促す。"},{"id":"5","text":"深い眠りの状態である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！レム睡眠は、からだは休んでいるけれど脳は活発に働いている眠り。夢を見たり、記憶を整理して定着させたりするんだ。2の脳の休息、4の成長ホルモンの分泌、5の深い眠りは、ノンレム睡眠の特徴だね。3は、入眠初期に出るのもノンレム睡眠なんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-028","examYear":"2025","examRound":"37","questionNumber":28,"category":"こころとからだのしくみ","questionText":"Ｂさん（76歳、男性）は、この数週間、日中に、「眠い」と訴えている。Ｂさんは毎日15時にコーヒー1杯を飲み、たばこを1本吸い、21時に就寝する。夜間の睡眠状態を数日間観察すると、睡眠中にぴくぴくと下肢が動いていることがたびたびあった。起床後、手足に異常を感じるかをＢさんに確認したが、「特にない」とのことだった。\n次のうち、Ｂさんの睡眠障害の原因として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ニコチン摂取"},{"id":"2","text":"レム睡眠行動障害"},{"id":"3","text":"レストレスレッグス症候群"},{"id":"4","text":"カフェイン摂取"},{"id":"5","text":"周期性四肢運動障害"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！睡眠中に足がぴくぴく動くのは周期性四肢運動障害の特徴で、本人は気づかず、日中に眠気が出ることがあるんだ。3のレストレスレッグス症候群は、起きているときに脚の不快な感覚があるけれど、Ｂさんは「異常はない」と話しているよ。カフェインやたばこの影響は、15時のコーヒー1杯と1本ではおそらく少ないね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-029","examYear":"2025","examRound":"37","questionNumber":29,"category":"こころとからだのしくみ","questionText":"次のうち、呼吸中枢がある部位として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"大脳"},{"id":"2","text":"中脳"},{"id":"3","text":"小脳"},{"id":"4","text":"延髄"},{"id":"5","text":"脊髄"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！呼吸中枢は、脳幹の延髄にあって、呼吸のリズムを調節しているんだ。だから、延髄がダメージを受けると、命に関わることがあるよ。1の大脳は思考や運動、2の中脳は眼球運動など、3の小脳は運動の調節、5の脊髄は脳と全身をつなぐ神経の通り道だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-030","examYear":"2025","examRound":"37","questionNumber":30,"category":"こころとからだのしくみ","questionText":"次のうち、脳の機能停止を示す徴候に該当するものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"呼吸不全"},{"id":"2","text":"溢流性尿失禁｛いつりゅうせいにょうしっきん｝"},{"id":"3","text":"心停止"},{"id":"4","text":"蠕動運動｛ぜんどううんどう｝の減弱"},{"id":"5","text":"瞳孔散大・対光反射消失"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！瞳孔が開いて（散大）、光を当てても縮まない（対光反射消失）のは、脳幹の機能が止まっているサインで、脳死判定でも確認する項目なんだ。1の呼吸不全、3の心停止、4の蠕動運動の減弱は、脳以外の原因でも起きるよ。2の溢流性尿失禁は、排尿障害の一種だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-031","examYear":"2025","examRound":"37","questionNumber":31,"category":"発達と老化の理解","questionText":"次の記述のうち、子どもの標準的な成長として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"1歳半から2歳ごろに、ハイハイをして移動できるようになる。"},{"id":"2","text":"生後9か月から1歳ごろに、指をさして自分の関心や欲求を他者に伝えられるようになる。"},{"id":"3","text":"子どもが使う言葉が急に増える語彙爆発は、5歳を過ぎたころに生じる。"},{"id":"4","text":"人見知りの反応は、2歳を過ぎたころに生じる。"},{"id":"5","text":"イヤイヤをしてすぐに泣く行動は、第二反抗期に生じる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！生後9か月〜1歳ごろになると、指をさして、自分の関心や欲求を伝えられるようになるんだ。1は、ハイハイは生後7〜9か月ごろ。3は、語彙爆発は1歳半〜2歳ごろだよ。4は、人見知りは生後6〜8か月ごろから。5は、イヤイヤは第一反抗期（2歳前後）で、第二反抗期は思春期だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-032","examYear":"2025","examRound":"37","questionNumber":32,"category":"発達と老化の理解","questionText":"次の記述のうち、神経性無食欲症（anorexia nervosa）に関するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"活動性が高まる。"},{"id":"2","text":"学童期に最も生じやすい。"},{"id":"3","text":"太ることへの恐怖はみられない。"},{"id":"4","text":"低体重の深刻さを理解している。"},{"id":"5","text":"多くが男性である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！神経性無食欲症は、やせていても活動性が高まって、じっとしていられないことが多いんだ。2は、思春期から青年期の女性に多いよ。3は、太ることへの強い恐怖があるんだ。4は、低体重の深刻さを理解できていないのが特徴。5は、患者の多くは女性だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-033","examYear":"2025","examRound":"37","questionNumber":33,"category":"発達と老化の理解","questionText":"Ａさん（73歳、男性）は、会社の役員として勤めていたが、3年前に退職した。地域の老人クラブへの入会を勧められたが拒否している。毎年、敬老の日に記念品が配布されても、不快感を示して受け取らない。退職後も会社の状況を気にしていて、後輩とときどき連絡をとっている。Ａさんは、身体が衰えることに強い不安を感じて、筋力トレーニングを毎日行っている。会社の後輩から、「いつも若々しいですね」と言われることに喜びを感じている。\nライチャード（Reichard, S.）による、引退後の男性の5つの適応タイプのうち、Ａさんに相当するものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"外罰（憤慨）型"},{"id":"2","text":"内罰（自責）型"},{"id":"3","text":"円熟（成熟）型"},{"id":"4","text":"自己防衛（装甲）型"},{"id":"5","text":"ロッキングチェアー（安楽椅子）型"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ライチャードの自己防衛（装甲）型は、老化への不安を抑えるため、活動的にふるまい続けるタイプなんだ。Ａさんは、身体の衰えへの強い不安から毎日筋トレをして、若々しいと言われて喜んでいるよ。1は他人や社会を責め、2は自分を責める。3は老いを受け入れる。5は安楽さを求めるタイプだね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-034","examYear":"2025","examRound":"37","questionNumber":34,"category":"発達と老化の理解","questionText":"次の記述のうち、結晶性知能に関する説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"感覚や運動に基づく知能である。"},{"id":"2","text":"過去に得た知識を活用して問題を解決する能力である。"},{"id":"3","text":"40～50歳で急激に低下する。"},{"id":"4","text":"知識や文化の影響よりも、生理的な老化の影響を受けやすい。"},{"id":"5","text":"その場で新しい問題を解決する能力である。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！結晶性知能は、過去の経験や学習で得た知識を活用して問題を解決する力で、高齢になっても保たれやすいんだ。1、4、5は、新しい場面で問題を解決する力（流動性知能）の説明だよ。3は、結晶性知能は急には低下せず、むしろ高齢期まで維持や向上がみられるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-035","examYear":"2025","examRound":"37","questionNumber":35,"category":"発達と老化の理解","questionText":"次の記述のうち、加齢に伴う感覚機能の変化として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"皮膚感覚が敏感になる。"},{"id":"2","text":"高音域の聴力が高まる。"},{"id":"3","text":"暗順応の時間が延長する。"},{"id":"4","text":"味覚が敏感になる。"},{"id":"5","text":"嗅覚が敏感になる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！加齢とともに、暗い場所に目が慣れる暗順応の時間が長くなるんだ。夜間の歩行などで、転倒に気をつけたいね。1は皮膚感覚が鈍くなり、2は高音域の聴力が低下し、4は味覚、5は嗅覚が、それぞれ鈍くなるんだ。「敏感になる」は、どれもまちがいだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-036","examYear":"2025","examRound":"37","questionNumber":36,"category":"発達と老化の理解","questionText":"Ｂさん（74歳、女性）は、地方で一人暮らしをしている。持病はなく、認知機能の異常もない。ダンスサークルに通い、近所との付き合いも良好で、今の暮らしに満足している。最近、白髪が増え、友人との死別もあり、年をとったと感じている。ある日、一人息子（50歳、未婚）から、東京で一緒に住むことを提案された。Ｂさんは、「ここには知り合いがいるが、東京には誰もいない。ここが一番いい」と言った。すると息子は、Ｂさんに、「年をとると頑固になる。あと数年したら認知症（dementia）になるかもしれないので、自分と一緒に暮らすべきだ」と言った。\n次のうち、Ｂさんに関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｂさんには、老性自覚はみられない。"},{"id":"2","text":"Ｂさんには、友人との死別による悲嘆がみられる。"},{"id":"3","text":"Ｂさんは、今、住んでいる環境や生活に適応できていない。"},{"id":"4","text":"Ｂさんには、エイジズム（ageism）の考え方がみられる。"},{"id":"5","text":"Ｂさんには、住み慣れた環境や仲間を喪失することへの不安がみられる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｂさんは、「ここには知り合いがいるが、東京には誰もいない」と話していて、住み慣れた環境や仲間を失うことへの不安がうかがえるんだ。1は、白髪や友人との死別で、年をとったと感じているので老性自覚がある。2は悲嘆の場面ではなく、3は生活に満足して適応している。4のエイジズムは、Ｂさんではなく息子の言動だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-037","examYear":"2025","examRound":"37","questionNumber":37,"category":"発達と老化の理解","questionText":"次の記述のうち、サクセスフル・エイジング（successful aging）として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"長生きすることが、最大の目的である。"},{"id":"2","text":"一人暮らしで、周囲の人と交流をしないようにしている。"},{"id":"3","text":"膝に痛みがあるので、一日中ベッド上で過ごすようにしている。"},{"id":"4","text":"難聴があるので、補聴器をつけてパソコン教室に通い始めた。"},{"id":"5","text":"歌を上手に歌えなくなったので、カラオケに誘われても行かないようにしている。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！サクセスフル・エイジングは、加齢による変化があっても、工夫や補いで、自分らしく満足して生活すること。補聴器を使って新しいことに挑戦する4がぴったりなんだ。1は長生きだけが目的ではなく、2、3、5は交流や活動を避けていて、社会参加や活動の機会を自ら減らしているね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-038","examYear":"2025","examRound":"37","questionNumber":38,"category":"発達と老化の理解","questionText":"次のうち、老年症候群に直接関わる疾患として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高血圧症（hypertension）"},{"id":"2","text":"糖尿病（diabetes mellitus）"},{"id":"3","text":"骨粗鬆症｛こつそしょうしょう｝（osteoporosis）"},{"id":"4","text":"心筋梗塞（myocardial infarction）"},{"id":"5","text":"脂質異常症（dyslipidemia）"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！老年症候群は、加齢に伴って高齢者に多くみられる、転倒、骨折、認知機能低下、失禁などの症状の集まりなんだ。骨粗鬆症は、骨折や転倒と結びついて、直接かかわるんだよ。1、2、4、5は、生活習慣病や、その合併症で、老年症候群そのものではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-039","examYear":"2025","examRound":"37","questionNumber":39,"category":"認知症の理解","questionText":"次の記述のうち、2019年（令和元年）の認知症施策推進大綱に関する説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「共生」と「予防」を車の両輪として施策を推進していく。"},{"id":"2","text":"「予防」とは、「認知症（dementia）にならない」という意味である。"},{"id":"3","text":"「認知症高齢者等にやさしい地域づくり」を推進する7つの柱が示された。"},{"id":"4","text":"「普及啓発・本人発信支援」として、家族が積極的に本人の意思を代弁することが示された。"},{"id":"5","text":"策定後は、毎年施策の進捗を確認することが示された。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！2019年の認知症施策推進大綱は、「共生」と「予防」を車の両輪として進めるんだ。2は、「予防」は認知症にならないという意味ではなく、なるのを遅らせ、進行を緩やかにするという意味だよ。3は、柱は5つ。4は、本人発信の支援が中心で、家族の代弁が中心ではないんだ。5は、毎年の確認とは示されていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-040","examYear":"2025","examRound":"37","questionNumber":40,"category":"認知症の理解","questionText":"Ａさん（84歳、女性、要介護3）は、アルツハイマー型認知症（dementia of the Alzheimer’s type）で、介護老人福祉施設に入所している。赤ちゃんの人形を持っていて、「はなちゃん」と呼んで話しかけている。\n昼食のため、介護福祉職が居室を訪問すると、Ａさんは不安そうな顔で、「はなちゃんがいなくなった。どこへ連れて行ったの？返して」と大声を出した。人形はＡさんのロッカーの上に置かれていた。\nＡさんに対する介護福祉職の最初の声かけとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「私を疑っているんですか」"},{"id":"2","text":"「置いた場所を忘れたんですか」"},{"id":"3","text":"「心配ですね、一緒に探しませんか」"},{"id":"4","text":"「ご飯を食べてから探してはどうですか」"},{"id":"5","text":"「ロッカーの上にあるのが見えないんですか」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ａさんは、大切な「はなちゃん」がいなくなったと思って、不安で大声を出しているんだね。まずは「心配ですね」と気持ちを受け止めて、一緒に探そうと寄り添う声かけがよいよ。1は問い詰め、2は責め、4は後回しにして、5は事実を突きつけるので、不安をさらに強めてしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-041","examYear":"2025","examRound":"37","questionNumber":41,"category":"認知症の理解","questionText":"認知症（dementia）の高齢者にみられる、せん妄に関する記述として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"覚醒レベルが重度に低下した状態である。"},{"id":"2","text":"症状の変動が少ないことが特徴である。"},{"id":"3","text":"夜間よりも日中に生じやすいことが特徴である。"},{"id":"4","text":"認知機能障害がみられることはまれである。"},{"id":"5","text":"関与する因子を特定することが重要である。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！せん妄は、脱水、感染、薬などが原因で急に起きる意識の障害なんだ。だから原因となる要因を見つけて取り除くことが大切だよ。1は、覚醒レベルの低下は重度ではなく軽度。2は、症状が変動しやすい。3は、夜間に出やすい。4は、認知機能の障害が現れることが多いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-042","examYear":"2025","examRound":"37","questionNumber":42,"category":"認知症の理解","questionText":"次の記述のうち、アルツハイマー型認知症（dementia of the Alzheimer’s type）の特徴として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"近時記憶（新しい記憶）の障害は、初期から始まる。"},{"id":"2","text":"特徴的な症状として幻視がある。"},{"id":"3","text":"脳にアミロイドβが沈着し始めると、すぐに発症する。"},{"id":"4","text":"歩行障害が多く現れるのは、初期の段階である。"},{"id":"5","text":"嚥下障害｛えんげしょうがい｝が多く現れるのは、初期の段階である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！アルツハイマー型認知症は、初期から、新しいことを覚えられない近時記憶の障害が現れるんだ。2の幻視はレビー小体型認知症の特徴だね。3は、アミロイドβの沈着は発症の10年以上前から始まるんだ。4の歩行障害や5の嚥下障害は、病気が進んだ段階で多く現れるよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-043","examYear":"2025","examRound":"37","questionNumber":43,"category":"認知症の理解","questionText":"次のうち、認知症（dementia）のリスクを高める要因として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"身体活動"},{"id":"2","text":"不飽和脂肪酸の摂取"},{"id":"3","text":"歯がなくなることによる咀嚼機能｛そしゃくきのう｝の低下"},{"id":"4","text":"難聴による補聴器の使用"},{"id":"5","text":"ボランティア活動"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！歯を失って咀嚼機能が落ちると、脳への刺激が減ったり、栄養状態が悪くなったりして、認知症のリスクが高まるといわれているんだ。1の身体活動、2の不飽和脂肪酸の摂取、4の補聴器の使用、5のボランティア活動は、どれもリスクを下げる（予防に役立つ）行動だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-044","examYear":"2025","examRound":"37","questionNumber":44,"category":"認知症の理解","questionText":"次のうち、全般的な認知機能を評価する尺度であり、30点満点で20点以下を認知症の目安とするものとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"バーセルインデックス（Barthel Index）"},{"id":"2","text":"改訂長谷川式認知症スケール（HDS-R）"},{"id":"3","text":"ＦＡＳＴ（Functional Assessment Staging）"},{"id":"4","text":"認知症高齢者の日常生活自立度判定基準"},{"id":"5","text":"臨床的認知症尺度（ＣＤＲ：Clinical Dementia Rating）"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！改訂長谷川式認知症スケール（HDS-R）は、30点満点で、20点以下だと認知症の疑いがあると判断する検査なんだ。1のバーセルインデックスは日常生活動作の評価。3のFASTはアルツハイマー型認知症の重症度、4は日常生活自立度、5のCDRは認知症の重症度を評価するもので、30点満点ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-045","examYear":"2025","examRound":"37","questionNumber":45,"category":"認知症の理解","questionText":"次の記述のうち、「認知症（dementia）の人の日常生活・社会生活における意思決定支援ガイドライン」（2018年（平成30年）（厚生労働省））で示されている、意思決定支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"認知症（dementia）の人の家族の意思を支援することである。"},{"id":"2","text":"意思決定支援者は特定の職種に限定される。"},{"id":"3","text":"一度、意思決定したら、最後まで同じ内容で支援する。"},{"id":"4","text":"看取りの場面になってから支援を開始する。"},{"id":"5","text":"身振りや表情の変化も意思表示として読み取る努力を最大限に行う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！このガイドラインは、認知症の人が自分の意思で決められるよう、身振りや表情の変化など、言葉以外の意思表示も最大限に読み取る努力をするよう示しているんだ。1は本人の意思の支援が対象、2は特定の職種に限定されない、3は意思は変わることがあるのでそのつど支援する、4は早い段階から始めるものだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-046","examYear":"2025","examRound":"37","questionNumber":46,"category":"認知症の理解","questionText":"次の記述のうち、回想法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"肩や背中から優しくゆっくりと触れる。"},{"id":"2","text":"共感を通して、認知症（dementia）の人が体験している現実を受け入れる。"},{"id":"3","text":"見当識を高めるために、時間や場所、現在の状況を説明する。"},{"id":"4","text":"昔の写真や音楽を活用して、記憶を活性化する。"},{"id":"5","text":"残存能力を活用し、共同作業を通して仲間をつくる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！回想法は、昔の写真や音楽、道具などを使って、思い出を語り合い、記憶や気持ちを活性化させる関わりなんだ。1はタクティールケア、2はバリデーション、3は現実見当識訓練（リアリティ・オリエンテーション）、5は作業療法的な集団活動のことだね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-047","examYear":"2025","examRound":"37","questionNumber":47,"category":"認知症の理解","questionText":"次の記述のうち、認知症疾患医療センターの説明として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"事業の実施主体は、市町村である。"},{"id":"2","text":"都道府県ごとに、1か所の設置が義務づけられている。"},{"id":"3","text":"認知症（dementia）の鑑別診断を行う。"},{"id":"4","text":"主に認知症（dementia）が進行した人の入院治療を行う。"},{"id":"5","text":"介護保険法に定められている。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！認知症疾患医療センターは、認知症の鑑別診断、初期対応、専門医療相談などを行う専門医療機関なんだ。1は、実施主体は都道府県と政令指定都市。2は、設置は義務づけではなく、整備を進めているよ。4は、進行した人の入院治療が主な役割ではないんだ。5は、介護保険法ではなく、国の事業要綱にもとづいているよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-048","examYear":"2025","examRound":"37","questionNumber":48,"category":"認知症の理解","questionText":"Ｂさん（87歳、男性）は、一人暮らしである。玄関前で、脱水で倒れているところを発見され、救急搬送された。入院中、認知症（dementia）の疑いがある行動が見られた。Ｂさんは、「自宅で暮らしたい」と強く希望していた。退院後、Ｂさんは外出して自宅に戻れなくなることがあった。近所の人たちが、Ｂさんの生活を心配して、地域包括支援センターに相談した結果、認知症初期集中支援チームが編成された。\n次の記述のうち、Ｂさんに対して認知症初期集中支援チームが行う支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"金銭管理を行う。"},{"id":"2","text":"支援方針を検討する。"},{"id":"3","text":"居宅サービス計画書を作成する。"},{"id":"4","text":"介護保険サービスを契約する。"},{"id":"5","text":"法定後見を行う。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！認知症初期集中支援チームは、専門職がチームで、認知症が疑われる人の自宅を訪問して、初期の支援を集中的に行い、支援方針を検討するんだ。1の金銭管理、4の契約、5の法定後見は、チームの仕事ではないよ。3のケアプラン作成は、介護支援専門員の役割だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-049","examYear":"2025","examRound":"37","questionNumber":49,"category":"障害の理解","questionText":"次のうち、ＩＣＦ（International Classification of Functioning, Disability and Health：国際生活機能分類）の社会（人生）レベルに該当するものとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"心身機能・身体構造"},{"id":"2","text":"活動"},{"id":"3","text":"参加"},{"id":"4","text":"機能障害"},{"id":"5","text":"活動制限"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ICF（国際生活機能分類）で、社会（人生）レベルにあたるのは「参加」なんだ。家庭や社会の中で役割を果たしたり、人生の場面にかかわったりすることだよ。1は生物（生命）レベル、2は生活（個人）レベルの「活動」。4の機能障害は、1に関する問題、5の活動制限は、2に関する問題なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-050","examYear":"2025","examRound":"37","questionNumber":50,"category":"障害の理解","questionText":"次の記述のうち、障害者のエンパワメントに関するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害のある人が障害のない人と同等に生活し、活動する社会を目指す。"},{"id":"2","text":"専門職が主導し、障害がある人は受動的に支援を受ける。"},{"id":"3","text":"障害のある人が自らの能力や長所に気づき、課題に対応する。"},{"id":"4","text":"障害のある人が、主体性や人権が守られないことに耐える。"},{"id":"5","text":"障害のある人が、医学的リハビリテーションを受ける。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！エンパワメントは、障害のある人が、自分の能力や長所に気づいて、自ら課題に対応していく力を高めることなんだ。1はノーマライゼーション、2は専門職主導なので、本人の力を引き出す考え方とは逆だよ。4は権利が守られないことに耐えるので当てはまらず、5は医学的リハビリテーションのことだね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-051","examYear":"2025","examRound":"37","questionNumber":51,"category":"障害の理解","questionText":"次のうち、クローン病（Crohn disease）にみられる特徴的な症状として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"視力低下"},{"id":"2","text":"栄養障害"},{"id":"3","text":"咳嗽｛がいそう｝"},{"id":"4","text":"運動失調"},{"id":"5","text":"関節痛"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！クローン病は、口から肛門までの消化管に炎症が起きる病気で、腹痛や下痢、体重減少が特徴なんだ。腸で栄養がうまく吸収できず、栄養障害を起こしやすいよ。1の視力低下、3の咳、4の運動失調は、特徴的な症状とはいえないね。5の関節痛は合併症でみられることもあるけれど、最も特徴的なのは栄養障害だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-052","examYear":"2025","examRound":"37","questionNumber":52,"category":"障害の理解","questionText":"次の記述のうち、遂行機能障害の特徴として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"些細｛ささい｝なことですぐに興奮して怒鳴る。"},{"id":"2","text":"新しい知識を覚えることが困難である。"},{"id":"3","text":"ぼんやりして周囲に注意を向け続けることが困難である。"},{"id":"4","text":"行動を計画して実行することが困難である。"},{"id":"5","text":"言葉の表出や理解が困難である。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！遂行機能障害は、目的に向けて行動を計画し、順序立てて実行することが難しくなる障害なんだ。1は感情のコントロールが難しい状態、2は記憶障害、3は注意障害、5は失語症の説明だね。どれも高次脳機能障害の症状だけど、ちがう障害なんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-053","examYear":"2025","examRound":"37","questionNumber":53,"category":"障害の理解","questionText":"視覚障害の特徴と視覚障害者の生活支援に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ロービジョンは、視覚情報をまったく得られない状態である。"},{"id":"2","text":"中途視覚障害者は、先天性の障害に比べて障害を受容しやすい。"},{"id":"3","text":"白杖｛はくじょう｝には、視覚に障害があることを周囲に知らせる役目がある。"},{"id":"4","text":"視覚障害を補うために、ペットの犬と一緒に外出する。"},{"id":"5","text":"視覚障害者は、ガイドヘルパーの利用はできない。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！白杖は、路面の様子を確かめるだけでなく、視覚に障害があることを周囲に知らせる役目もあるんだ。1は、ロービジョンは見えにくいけれど、まったく見えない状態ではないよ。2は、中途失明では、障害受容が難しいことが多いね。4のペットの犬ではなく、盲導犬が必要で、5は、ガイドヘルパー（同行援護）を使えるよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-054","examYear":"2025","examRound":"37","questionNumber":54,"category":"障害の理解","questionText":"Ａさん（76歳、女性）は、パーキンソン病（Parkinson disease）と診断され、日常生活動作（Activities of Daily Living：ＡＤＬ）は、車いすやベッド上で全介助である。最近、食事に時間がかかって嫌がるようになり、かすれ声が目立つようになった。\n次のうち、現在のＡさんに対して介護福祉職が留意すべきこととして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"安静時振戦"},{"id":"2","text":"筋固縮"},{"id":"3","text":"仮面様顔貌"},{"id":"4","text":"誤嚥｛ごえん｝"},{"id":"5","text":"便秘"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんは、食事に時間がかかり、かすれ声も出ているので、嚥下機能が落ちている可能性があるんだ。誤嚥から肺炎につながるので、いちばん気をつけたいね。1の安静時振戦、2の筋固縮、3の仮面様顔貌、5の便秘は、パーキンソン病でよくある症状だけど、今の様子からは誤嚥への留意が優先だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-055","examYear":"2025","examRound":"37","questionNumber":55,"category":"障害の理解","questionText":"聴覚障害者の特徴や支援の方法に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"要約筆記によって意思疎通を補う。"},{"id":"2","text":"軽度の聴覚障害を「ろう」という。"},{"id":"3","text":"フラッシュベルは周囲の音を増幅させて伝える。"},{"id":"4","text":"手話は意思の伝達に役立たない。"},{"id":"5","text":"両耳の聴力レベルが40dBで身体障害者手帳が交付される。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！要約筆記は、話の内容を文字にして伝える方法で、聴覚障害者の意思疎通を助けるんだ。2は、「ろう」は重度の聴覚障害を指すよ。3のフラッシュベルは、音を光で知らせる機器。4は、手話は有効なコミュニケーション手段。5は、身体障害者手帳は、両耳の聴力レベルが70dB以上が基準だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-056","examYear":"2025","examRound":"37","questionNumber":56,"category":"障害の理解","questionText":"Ｂさん（24歳、男性）は、母親と二人暮らしで、小学生のときに注意欠陥多動性障害と疑われていた。Ｂさんは、最近になって昼夜を問わずゲームを続け、朝起きられずにアルバイトを無断で休むことが増えた。\n次のうち、Ｂさんの母親が相談する機関として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ハローワーク（公共職業安定所）"},{"id":"2","text":"難病情報センター"},{"id":"3","text":"認知症カフェ"},{"id":"4","text":"放課後等デイサービス"},{"id":"5","text":"発達障害者支援センター"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｂさんは、子どものころに注意欠陥多動性障害が疑われていて、生活リズムの乱れや無断欠勤があるので、発達障害の可能性があるよ。発達障害者支援センターは、本人や家族の相談に応じてくれる専門機関なんだ。1は就職の支援、2は難病、3は認知症、4は障害のある児童向けだから、合わないね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-057","examYear":"2025","examRound":"37","questionNumber":57,"category":"障害の理解","questionText":"次の記述のうち、「障害者差別解消法」の合理的配慮に沿った対応として、最も適切なものを1つ選びなさい。\n（注）  「障害者差別解消法」とは、「障害を理由とする差別の解消の推進に関する法律」のことである。","choices":[{"id":"1","text":"車いすの身体障害者から、陳列棚にある商品を見せてほしいと言われたが、口頭で商品を説明した。"},{"id":"2","text":"聴覚障害者の手話による注文がわからなかったので、最も人気のあるメニューを出した。"},{"id":"3","text":"盲導犬を連れた視覚障害者が来店したが、動物嫌いの客から苦情を言われると思い、犬は店の中に入れないように頼んだ。"},{"id":"4","text":"役所に相談に来た精神障害者から、多くの人の中だと不安になると言われたため、帰宅してもらった。"},{"id":"5","text":"知的障害者から申し出があったので、会議に参加するための資料をわかりやすい言葉に直して、事前に口頭で説明した。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！合理的配慮は、障害のある人の求めに応じて、負担が重すぎない範囲で、必要な調整をすること。知的障害のある人に、資料をわかりやすい言葉にして説明するのがぴったりだね。1は、商品を見せてほしい要望に応えていない。2は、確認せず決めつけ。3は、盲導犬の受け入れ拒否は差別にあたり、4も、相談を受けずに帰宅は不適切だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-058","examYear":"2025","examRound":"37","questionNumber":58,"category":"障害の理解","questionText":"レスパイトケアの望ましいあり方に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害者はサービスを利用せずに生活するべきである。"},{"id":"2","text":"利用中、家族は自宅で休まなくてはならない。"},{"id":"3","text":"家族が障害者を預けて旅行に行くことは認められない。"},{"id":"4","text":"家族の休息が目的なので、障害者の施設利用は宿泊に限定される。"},{"id":"5","text":"家族が休息している間も、障害者が自分らしく過ごせるようにする。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！レスパイトケアは、介護する家族が休息できるように、一時的に介護を代わるサービスなんだ。大切なのは、家族が休んでいる間も、障害のある人が自分らしく安心して過ごせること。1は、サービスを利用しないことを求め、2、3、4は、家族の過ごし方や利用の形を限定していて、まちがいだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-059","examYear":"2025","examRound":"37","questionNumber":59,"category":"医療的ケア","questionText":"次の記述のうち、成人に対する救急蘇生法｛きゅうきゅうそせいほう｝での胸骨圧迫の方法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"呼吸が確認できない場合は、すぐに圧迫を始める。"},{"id":"2","text":"圧迫する部位は、胸骨の左側である。"},{"id":"3","text":"実施者の両手を重ねて、指先で圧迫する。"},{"id":"4","text":"圧迫の深さは、胸が10cm沈むようにする。"},{"id":"5","text":"1分間に60回を目安に圧迫する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！呼吸が確認できない（または普段どおりでない）ときは、心停止とみなして、すぐに胸骨圧迫を始めるんだ。2は、胸骨の下半分（胸の真ん中）を押す。3は、手のひらの付け根で押すよ。4は、深さは約5cm。5は、テンポは1分間に100〜120回が目安だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-060","examYear":"2025","examRound":"37","questionNumber":60,"category":"医療的ケア","questionText":"次の記述のうち、痰｛たん｝を喀出｛かくしゅつ｝する仕組みに関するものとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"呼吸器官の内部は乾燥した状態になっている。"},{"id":"2","text":"気管の内部の表面には絨毛｛じゅうもう｝があり、分泌物の侵入を防いでいる。"},{"id":"3","text":"分泌物は、咽頭で吸収される。"},{"id":"4","text":"痰｛たん｝は、咳｛せき｝や咳払｛せきばら｝いによって排出される。"},{"id":"5","text":"咳｛せき｝は、下垂体にある咳中枢｛せきちゅうすう｝によっておこる反射運動である。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！気道にたまった痰は、咳や咳払いの力で外に出すんだ。1は、呼吸器の内部は粘液で湿っているよ。2は、気管の内側の線毛が、異物や分泌物を口のほうへ押し出す。3は、分泌物を吸収する働きはないよ。5は、咳中枢があるのは、下垂体ではなく延髄なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-061","examYear":"2025","examRound":"37","questionNumber":61,"category":"医療的ケア","questionText":"次の記述のうち、介護福祉士が行う口腔内｛こうくうない｝の喀痰吸引｛かくたんきゅういん｝の方法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"吸引圧は、利用者の体調によって介護福祉士が決める。"},{"id":"2","text":"吸引圧をかけた状態で、吸引チューブを挿入する。"},{"id":"3","text":"口蓋垂まで吸引チューブを挿入する。"},{"id":"4","text":"吸引チューブを回転させながら痰｛たん｝を吸引する。"},{"id":"5","text":"吸引後は洗浄水を吸引し、清浄綿でチューブを拭く。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！吸引チューブは、静かに、少しずつ回転させながら動かすと、粘膜に張りつくのを防いで、効率よく痰を集められるんだ。1は、吸引圧は、医師や看護師の指示にもとづいて決める。2は、圧をかけずに挿入する。3は、口蓋垂までは入れず、届く範囲までにとどめる。5は、後始末の説明ではあるけれど、吸引の操作方法としては、最も適切とはいえないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-062","examYear":"2025","examRound":"37","questionNumber":62,"category":"医療的ケア","questionText":"次の記述のうち、消化器症状の説明として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"腹部膨満感は、腹部が張る感覚のことである。"},{"id":"2","text":"しゃっくり（吃逆｛きつぎゃく｝）は、胸膜の刺激で起こる現象である。"},{"id":"3","text":"胸やけは、飲食物による食道の熱傷のことである。"},{"id":"4","text":"げっぷ（噯気）は、咽頭にたまった空気が排出されることである。"},{"id":"5","text":"嘔気｛おうき｝は、胃や腸の内容物が、食道を逆流して口外に吐き出されることである。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！腹部膨満感は、おなかが張って苦しい感覚のことなんだ。2のしゃっくりは、横隔膜のけいれんで起きる。3の胸やけは、胃酸が逆流して胸が熱く感じることだよ。4のげっぷは、胃にたまった空気が出ること。5の説明は、嘔吐のことで、嘔気は吐きたいという不快な感じのことだね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-063","examYear":"2025","examRound":"37","questionNumber":63,"category":"医療的ケア","questionText":"Ａさん（80歳、女性）は、脳梗塞（cerebral infarction）の後遺症で左片麻痺｛ひだりかたまひ｝があり、介護老人保健施設に入所して在宅復帰に向けた訓練をしている。嚥下障害｛えんげしょうがい｝もあるため、経鼻経管栄養による栄養摂取をしているが、経口摂取できないことでイライラしてチューブを抜去したことがある。医師からは一時的な治療であると説明を受けて同意していた。\n経管栄養中に介護福祉士が訪室すると、チューブを触りながら、「自分の口から食べたいから、このチューブを抜いてほしい。見た目も良くない」と訴えがあった。看護師に連絡し、チューブが抜けていないことを確認してもらった。\nこのときのＡさんへの介護福祉士の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"チューブを抜かないようにＡさんの右手を固定する。"},{"id":"2","text":"経管栄養が早く終わるように滴下速度を調節する。"},{"id":"3","text":"医師や看護師にＡさんの思いを伝える。"},{"id":"4","text":"Ａさんに胃ろうの造設を提案する。"},{"id":"5","text":"Ａさんに経口摂取を提案する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ａさんは、口から食べたいという思いと、見た目が気になる気持ちを訴えているんだね。まずは、その思いを受け止めて、医師や看護師に伝え、専門職で検討してもらうことが大切なんだ。1は身体拘束にあたるよ。2は、速度を勝手に変えるのは危険。4や5は、介護福祉士が提案する内容ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_am_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-064","examYear":"2025","examRound":"37","questionNumber":64,"category":"介護の基本","questionText":"介護福祉に関連する法律に関する次の記述のうち、適切なものを1つ選びなさい。\n（注）1  「高齢者虐待防止法」とは、「高齢者虐待の防止、高齢者の養護者に対する支援等に関する法律」のことである。\n2  「障害者総合支援法」とは、「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。","choices":[{"id":"1","text":"「高齢者虐待防止法」は、福祉六法の1つである。"},{"id":"2","text":"「障害者総合支援法」は、障害者基本計画の策定を義務づけている。"},{"id":"3","text":"社会福祉法によって、社会福祉士の定義が規定されている。"},{"id":"4","text":"介護保険法は、国民の共同連帯の理念に基づいて介護保険制度を設けている。"},{"id":"5","text":"医師法によって、介護福祉の業務の一部として医行為が認められている。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！介護保険法は、国民の共同連帯の理念にもとづいて、介護保険制度を設けているんだ。1は、福祉六法にはふくまれないよ。2は、障害者基本計画は障害者基本法にもとづくものだね。3は、社会福祉士の定義は、社会福祉士及び介護福祉士法に定められているんだ。5は、医行為は、一定の条件のもとで認められているんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-065","examYear":"2025","examRound":"37","questionNumber":65,"category":"介護の基本","questionText":"社会福祉士及び介護福祉士法に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"資質向上のために、5年に1回、資格更新研修を受けなければならない。"},{"id":"2","text":"社会福祉士の業務を介護福祉士が行うことは禁じられている。"},{"id":"3","text":"介護福祉士の信用を傷つける行為をしてはならない。"},{"id":"4","text":"介護福祉士は、その業を辞した後は秘密保持義務が解除される。"},{"id":"5","text":"介護福祉士国家試験に合格した日から、介護福祉士を名乗ることができる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！社会福祉士及び介護福祉士法には、介護福祉士は、その信用を傷つける行為をしてはならないという信用失墜行為の禁止が定められているんだ。1は、更新研修の義務はないよ。2は、業務を行うことは禁じられていないね。4は、辞めたあとも秘密保持義務は続く。5は、名乗れるのは、登録を受けてからなんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-066","examYear":"2025","examRound":"37","questionNumber":66,"category":"介護の基本","questionText":"Ａさん（75歳、女性）は、3か月前に、血管性認知症（vascular dementia）を発症し、軽度の左片麻痺｛ひだりかたまひ｝で杖歩行｛つえほこう｝となり、要介護3と認定された。Ａさんは、料理が大好きで、娘と一緒に食事を作ることを楽しみに生活していた。1か月前から認知症（dementia）が進行し、ユニット型介護老人福祉施設に入所した。Ａさんは夕方になると、「ご飯の支度をしないといけないから帰ります」と言いながら、興奮して歩き回る様子がみられるようになった。\nＡさんへの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"居室に鍵をかけて、自室で過ごしてもらう。"},{"id":"2","text":"介護福祉職と一緒に、夕食の準備をしてもらう。"},{"id":"3","text":"杖｛つえ｝を預かり、低めの丸椅子に座ってもらう。"},{"id":"4","text":"介護福祉職の判断で、向精神薬を服用してもらう。"},{"id":"5","text":"ここがＡさんの自宅であることを、理解してもらう。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ａさんは、夕方に「ご飯の支度をしないと」と落ち着かなくなるんだね。料理が大好きな気持ちに寄り添って、一緒に夕食の準備をしてもらうと、役割を感じて安心できるんだ。1は閉じ込めで身体拘束にあたり、3は歩く力を奪ってしまうよ。4は勝手な服薬の判断、5は事実の押しつけで、不安が強まるね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-067","examYear":"2025","examRound":"37","questionNumber":67,"category":"介護の基本","questionText":"ＩＣＦ（International Classification of Functioning, Disability and Health：国際生活機能分類）における「参加」と「活動」の2つが関連した、認知症の人の支援に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"若年性アルツハイマー型認知症（dementia of the Alzheimer’s type with early onset）があり、治療している。"},{"id":"2","text":"認知症カフェに通い、体操をしている。"},{"id":"3","text":"近所に住む長男が、買物を代行している。"},{"id":"4","text":"自宅にある広い庭を、バリアフリー化している。"},{"id":"5","text":"見当識障害があり、ＧＰＳ装置を身に着けている。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！認知症カフェに通う（参加）ことと、そこで体操をする（活動）ことの2つが、関連しているんだ。1は健康状態、3は環境因子としての家族の支援、4は環境因子である住環境の整備、5は心身機能（見当識障害）と、環境因子の支援機器の話で、参加と活動の組み合わせではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-068","examYear":"2025","examRound":"37","questionNumber":68,"category":"介護の基本","questionText":"次の記述のうち、介護保険制度における訪問介護員（ホームヘルパー）が行うサービス内容として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者が大切にしている庭の植木に、水やりをする。"},{"id":"2","text":"利用者が長年飼っている猫のペットフードを、購入してくる。"},{"id":"3","text":"掃き掃除をする習慣のある利用者と一緒に、寝室をほうきで掃除する。"},{"id":"4","text":"利用者と一緒に、近所のラーメン屋に行く。"},{"id":"5","text":"利用者のクレジットカードを預かって、買物を代行する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！掃き掃除の習慣がある利用者と一緒に行うのは、利用者の自立を支える生活援助にあたるんだ。1の庭の植木の水やり、2のペットフードの購入は、日常生活の援助の範囲外。4は、一緒に外食に行くのはサービスに含まれないよ。5は、クレジットカードを預かるのは、トラブルのもとになるから、してはいけないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-069","examYear":"2025","examRound":"37","questionNumber":69,"category":"介護の基本","questionText":"次の記述のうち、介護従事者を守る法制度として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"労働安全衛生法では、年に1回以上の健康診断を行うことを義務づけている。"},{"id":"2","text":"労働者災害補償保険法では、労働時間、賃金、休暇などの労働条件を定めている。"},{"id":"3","text":"環境基本法では、快適な職場環境の形成の促進を定めている。"},{"id":"4","text":"介護休業は、対象家族1名につき、毎年93日間を取得できる。"},{"id":"5","text":"出生時育児休業は、子の出生後から8週間取得できる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！労働安全衛生法では、事業者は、労働者に対して年1回以上の健康診断を行う義務があるんだ。2は、労働時間や賃金などを定めているのは労働基準法。3は、環境基本法は職場環境ではなく、環境全般の法律だよ。4は、介護休業は、対象家族1人につき通算93日まで。5は、出生時育児休業は、子の出生後8週間以内に、4週間まで取得するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-070","examYear":"2025","examRound":"37","questionNumber":70,"category":"介護の基本","questionText":"Ｂさん（68歳、女性、要介護1）は、ヨーロッパで生まれ育ち、50歳のときに日本人と結婚した。65歳で夫と共に日本で暮らすようになったが、日本語は十分に理解できない。半年前に、脳梗塞（cerebral infarction）を起こし、利き手に麻痺｛まひ｝があり、立ち上がりも不安定である。現在は、介護老人保健施設に入所し、在宅復帰へ向けたリハビリテーションを行っている。Ｂさんはこれまでの生活様式を守り、自宅で自分のペースで食事ができるようになりたいと希望している。\n次の記述のうち、Ｂさんへの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"入所中は母語を使わずに、日本語を話すように伝える。"},{"id":"2","text":"居室の床に布団を敷いて、寝起きができるようにする。"},{"id":"3","text":"自分で食事ができるように、自助具の使用状況を確認する。"},{"id":"4","text":"ほかの利用者と同じ時間に食べ終えるように伝える。"},{"id":"5","text":"日本の生活に合わせるように、余暇活動の内容は介護福祉職が判断する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｂさんは、自分のペースで食事ができるようになりたいと希望しているんだね。利き手に麻痺があるので、自助具を使えているか確認して、自分で食べられるように支援するのがよいよ。1は母語を制限し、2はリハビリ中の転倒リスクがあり、4は食べるペースの強制、5は本人の希望を無視しているから、不適切なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-071","examYear":"2025","examRound":"37","questionNumber":71,"category":"介護の基本","questionText":"次の記述のうち、チームアプローチに関するものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職が利用者のところに行って、相談、支援を行う。"},{"id":"2","text":"障害者が、地域の資源を活用して、共生社会の実現を目指す。"},{"id":"3","text":"複数の専門職が共通の目標に向かって協働し、課題解決に取り組む。"},{"id":"4","text":"利用者に代わって、専門職がサービスを決定する。"},{"id":"5","text":"当事者が集まって体験談を話し、共に支えあう。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！チームアプローチは、複数の専門職が共通の目標に向かって、協力して課題解決に取り組むことなんだ。1はアウトリーチ、2は地域を活用した共生社会をめざす考え方、4は利用者の自己決定を奪っている、5はピアサポートやセルフヘルプグループの説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-072","examYear":"2025","examRound":"37","questionNumber":72,"category":"介護の基本","questionText":"介護保険施設における防災対策に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉士は、災害派遣福祉チームで活動することが義務づけられている。"},{"id":"2","text":"介護福祉士は、防災スキル向上のために、防災士の資格取得が義務づけられている。"},{"id":"3","text":"災害対策基本法に基づき、個別避難計画の作成が施設長に義務づけられている。"},{"id":"4","text":"一般的に、飲料水と非常食は1日分の備蓄が義務づけられている。"},{"id":"5","text":"災害時等に備えて、業務継続計画（ＢＣＰ：Business Continuity Plan）の策定が義務づけられている。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護保険施設などでは、災害時にもサービスを続けるための業務継続計画（ＢＣＰ）を作ることが義務づけられているんだ。1の災害派遣福祉チームへの参加や、2の防災士の取得は、義務ではないよ。3の個別避難計画は、市町村の努力義務。4の備蓄は、義務ではなく、目安として3日分程度が望ましいとされているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-073","examYear":"2025","examRound":"37","questionNumber":73,"category":"介護の基本","questionText":"次のうち、結核（tuberculosis）の予防対策に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"便座のアルコール消毒"},{"id":"2","text":"肺炎球菌ワクチンの接種"},{"id":"3","text":"紫外線を避けた生活"},{"id":"4","text":"年に1回の胸部Ｘ線検査"},{"id":"5","text":"50℃以上の温水によるリネン類の洗濯"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！結核は、早期発見が大切で、年に1回の胸部Ｘ線検査などで、感染や発病を早く見つけることが、予防対策になるんだ。1のアルコール消毒は、主に接触感染の対策。2の肺炎球菌ワクチンは、肺炎の予防だね。3の紫外線を避けることは、関係ないよ。5の50℃の温水洗濯は、あまり効果がなく、結核は空気感染だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-074","examYear":"2025","examRound":"37","questionNumber":74,"category":"コミュニケーション技術","questionText":"次の記述のうち、利用者とのコミュニケーションの場面で用いる要約の技法として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"開かれた質問をして、利用者の気持ちを明らかにした。"},{"id":"2","text":"共感しながら話を聞き、利用者の気持ちを受け止めた。"},{"id":"3","text":"話の途中でうなずき、利用者の気持ちに同意した。"},{"id":"4","text":"話の内容を総合的にまとめて返し、利用者の気持ちを整理した。"},{"id":"5","text":"自己覚知を図り、利用者との人間関係の形成に努めた。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！要約は、利用者の話した内容を、まとめて返すことで、話の整理を助けたり、理解を確かめたりする技法なんだ。1は開かれた質問、2は共感、3はうなずきによる受容、5は自己覚知の説明で、要約の技法とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-075","examYear":"2025","examRound":"37","questionNumber":75,"category":"コミュニケーション技術","questionText":"次の記述のうち、利用者と家族の意向が異なるとき、家族とのコミュニケーションにおいて介護福祉職が留意すべき点として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族に支援方針を決めてもらう。"},{"id":"2","text":"家族を通して利用者の意向を聴き取る。"},{"id":"3","text":"家族と話す機会を別に設ける。"},{"id":"4","text":"家族にカウンセリングを行うことを意識する。"},{"id":"5","text":"家族を説得する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！利用者と家族の意向がちがうときは、それぞれの本音を聞けるように、家族と話す機会を別に設けるのがよいんだ。1は、支援方針を決めるのは本人が中心。2は、本人から直接、意向を聴くことが大切だよ。4のカウンセリングは、介護福祉職の役割ではなく、5の説得は、押しつけになってしまうね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-076","examYear":"2025","examRound":"37","questionNumber":76,"category":"コミュニケーション技術","questionText":"Ａさん（80歳、男性、要介護3）は、介護老人福祉施設に入所している。アルツハイマー型認知症（dementia of the Alzheimer’s type）が進行している。ある日の昼食時、介護福祉職がＡさんに配膳すると、「お金はこれしかありません。足りますか」と小さくたたまれたティッシュペーパーを渡してきた。\nこのときのＡさんに対する介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ティッシュペーパーは、口の周りが汚れたら拭くものだと伝える。"},{"id":"2","text":"ティッシュペーパーが不足しているサインとして受け止める。"},{"id":"3","text":"飲食店での会計の場面であると認識して対応する。"},{"id":"4","text":"食事に集中するように促す。"},{"id":"5","text":"小遣いの増額を家族に相談する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ａさんは、認知症が進んで、食事の場面を飲食店での会計と思っているんだね。その世界に合わせて対応することで、Ａさんの不安を防いで、安心して食事ができるんだ。1は、ティッシュの使い方を教えるだけで、状況に合っていないよ。2、4、5は、Ａさんが伝えたいことを受け止めていないね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-077","examYear":"2025","examRound":"37","questionNumber":77,"category":"コミュニケーション技術","questionText":"構音障害のあるＢさんは、現在発語訓練を実施中である。ある日、介護福祉職に対して、「おあんで、あつがおごれた」と訴えた。介護福祉職は、Ｂさんの発語をうまく聞き取れず、「もう一度、言ってください」と伝えた。Ｂさんは、自身の発語で会話を続けようとしているが、介護福祉職には、その内容を十分に理解することができなかった。\nこのときの、Ｂさんに対する介護福祉職の判断として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｂさんは言葉の意味の理解に支障があるため、会話の継続は困難である。"},{"id":"2","text":"発音が苦手なため、短い言葉でゆっくり話してもらう必要がある。"},{"id":"3","text":"話す意欲があるため、開かれた質問が有効である。"},{"id":"4","text":"発語訓練の効果がみられないため、訓練を中止する必要がある。"},{"id":"5","text":"Ｂさんの言葉が聞き取れないため、会話を中断する必要がある。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！構音障害は、言葉の意味の理解はできるけれど、うまく発音できない障害なんだ。だから、短い言葉で、ゆっくり話してもらうと、伝わりやすくなるよ。1は、理解には問題がない。3は、開かれた質問は答えにくいので、「はい・いいえ」で答えられる質問が有効だね。4と5は、意欲を奪ってしまう対応だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-078","examYear":"2025","examRound":"37","questionNumber":78,"category":"コミュニケーション技術","questionText":"Ｃさん（55歳、男性）は、知的障害がある。3か月前に、施設から居宅での一人暮らしに移行し、現在は、居宅介護（ホームヘルプサービス）を利用しながら生活している。ある日、Ｃさんが、「ゴミ、分けて捨てるの、難しいよ」と言うので、室内に分別収集の説明書を貼って、カレンダーに収集日を書くことにした。そして、介護福祉職は、「この説明書とカレンダーを見て、捨てるといいですよ」とＣさんに伝えた。その後、Ｃさんは努力していたが、分別できなかったゴミが少しずつ増えていった。\n次のうち、Ｃさんにかける介護福祉職の最初の言葉として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「ゴミでいっぱいになる前に、適切に捨てられるようになりましょう」"},{"id":"2","text":"「説明書とカレンダーをよく見てください」"},{"id":"3","text":"「ゴミが増えてきて、気持ち悪いですね」"},{"id":"4","text":"「がんばっていれば、上手にできるようになりますよ」"},{"id":"5","text":"「ゴミ捨ては難しいですよね。できることをいっしょに考えましょう」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｃさんは、頑張っているのに、うまく分別できなかったんだね。まずは、「難しいですよね」と気持ちを受け止めて、できることを一緒に考える姿勢がよいんだ。1、2、4は、できないのを本人の努力不足にするような言い方で、3は否定的な感情を押しつけているから、Ｃさんが傷ついてしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-079","examYear":"2025","examRound":"37","questionNumber":79,"category":"コミュニケーション技術","questionText":"介護保険サービスにおける記録に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"記録に含まれないものとして食事チェック表がある。"},{"id":"2","text":"介護記録は介護福祉職の意見を中心に記録する。"},{"id":"3","text":"調査・研究目的で記録を利用することは避ける。"},{"id":"4","text":"主観的情報と客観的事実は区別しないで記録する。"},{"id":"5","text":"利用者は記録の閲覧を請求することができる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！利用者は、自分の介護に関する記録の閲覧を請求することができるんだ。1は、食事チェック表も記録にふくまれるよ。2は、事実にもとづいて記録するのが基本。3は、匿名化するなど配慮すれば、研究に使えることもあるんだ。4は、主観的情報と客観的事実は、区別して書くのが原則だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-080","examYear":"2025","examRound":"37","questionNumber":80,"category":"生活支援技術","questionText":"高齢者に配慮した居室環境に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"夏は高齢者が発汗してから冷房を使用する。"},{"id":"2","text":"暖房を使用するときは除湿機を併用する。"},{"id":"3","text":"冷房を使用するときは換気を控える。"},{"id":"4","text":"温度は介護福祉職の感覚で調整する。"},{"id":"5","text":"冬はトイレの温度を居室の温度に近づける。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！冬は、暖かい居室から寒いトイレに行くと、急な血圧の変化で危険なんだ（ヒートショック）。だから、トイレの温度を居室に近づけるのが大切だよ。1は、汗をかく前に冷房を使う。2は、湿度のコントロールとして、暖房時は加湿が必要。3は、冷房中も換気は必要。4は、温度は利用者の感覚に合わせて調整するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-081","examYear":"2025","examRound":"37","questionNumber":81,"category":"生活支援技術","questionText":"次の記述のうち、介護の現場において、レクリエーション活動で実施するアイスブレーキングの効果として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"参加者の緊張感を軽減することができる。"},{"id":"2","text":"活動内容を毎回固定して実施することができる。"},{"id":"3","text":"介護福祉職の負担を軽減することができる。"},{"id":"4","text":"利用者の参加を義務づけることができる。"},{"id":"5","text":"勝敗を楽しむことができる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！アイスブレーキングは、初対面や緊張しているときに、場をなごませて、参加者の緊張をほぐすための簡単なゲームや会話のことなんだ。2は、毎回同じ内容にする目的ではなく、3は、介護福祉職の負担を減らす目的ではないよ。4は、参加は自由意思なので、義務づけはしないね。5は、勝敗を楽しむことが目的ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-082","examYear":"2025","examRound":"37","questionNumber":82,"category":"生活支援技術","questionText":"次の記述のうち、介護福祉職が行う身じたく・整容の介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ベッド上で行う口腔｛こうくう｝ケアは、ガーグルベースンを用いる。"},{"id":"2","text":"総義歯の洗浄は、歯みがき剤を用いる。"},{"id":"3","text":"耳垢｛じこう｝の除去は、ピンセットを用いる。"},{"id":"4","text":"ベッド上で行う洗顔は、冷水に浸して絞ったタオルを用いる。"},{"id":"5","text":"浴室で行う洗髪は、ドライシャンプーを用いる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ベッド上で口腔ケアをするときは、うがいの水を受けるガーグルベースンを使うんだ。2は、総義歯の洗浄は、専用の義歯ブラシと流水などで行い、研磨剤入りの歯みがき剤は傷つけるよ。3は、耳垢は、ピンセットを使わず、綿棒などで取る。4は、洗顔は温かいタオル。5は、浴室では通常のシャンプーを使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-083","examYear":"2025","examRound":"37","questionNumber":83,"category":"生活支援技術","questionText":"次の記述のうち、障害のある人への事故防止の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"パーキンソン病（Parkinson disease）の人には、低めのベッドを用意する。"},{"id":"2","text":"認知症（dementia）の人には、ガスコンロを用意する。"},{"id":"3","text":"在宅酸素療法中の人のそばでは、喫煙しない。"},{"id":"4","text":"視覚障害のある人には、洗体用に頭受け台を用意する。"},{"id":"5","text":"聴覚障害のある人には、補高便座を用意する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！在宅酸素療法中は、酸素は燃えやすくするので、火気厳禁。そばでの喫煙はしないように注意が必要なんだ。1は、パーキンソン病の人には、立ち上がりやすい高さのベッドがよいよ。2は、認知症の人には、火を使わない調理器具のほうが安全。4は、視覚障害のある人のためではなく、5は、補高便座は、立ち座りが難しい人に使うものだね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-084","examYear":"2025","examRound":"37","questionNumber":84,"category":"生活支援技術","questionText":"次のうち、右片麻痺｛みぎかたまひ｝の利用者が多点杖｛たてんづえ｝を使用して3動作歩行を開始するときに、介護福祉職が行う説明として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「杖｛つえ｝、右足、左足の順で歩きましょう」"},{"id":"2","text":"「杖｛つえ｝、左足、右足の順で歩きましょう」"},{"id":"3","text":"「右足、左足、杖｛つえ｝の順で歩きましょう」"},{"id":"4","text":"「左足、杖｛つえ｝、右足の順で歩きましょう」"},{"id":"5","text":"「左足、右足、杖｛つえ｝の順で歩きましょう」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！3動作歩行は、杖、麻痺のある足（患側）、健康な足（健側）の順に出すんだ。右片麻痺の人は、患側が右足なので、「杖、右足、左足」の順になるよ。2は、順序が逆で、3、4、5は、杖を先に出さないので、バランスがくずれやすくて、危ないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-085","examYear":"2025","examRound":"37","questionNumber":85,"category":"生活支援技術","questionText":"ノーリフティングケアに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）の利用者を抱え上げて、端座位にする。"},{"id":"2","text":"仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）の利用者を手前に引きよせて、ストレッチャーに移乗する。"},{"id":"3","text":"端座位の利用者の体幹を抱きかかえて、車いすに移乗する。"},{"id":"4","text":"端座位の利用者にスライディングボードを使用して、車いすに移乗する。"},{"id":"5","text":"立位が困難な端座位の利用者に回転移動盤を使用して、車いすに移乗する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ノーリフティングケアは、利用者を持ち上げず、福祉用具を使って、介護者と利用者の負担を減らすケアなんだ。端座位の人には、スライディングボードで車いすに乗り移ってもらうよ。1と3は抱え上げ、2は引きよせるので、いずれも負担が大きくなるんだ。5は、回転移動盤は、立位がとれる人に使う用具だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-086","examYear":"2025","examRound":"37","questionNumber":86,"category":"生活支援技術","questionText":"次の記述のうち、左片麻痺｛ひだりかたまひ｝の利用者を右側臥位｛みぎそくがい｝から端座位にするときの介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者に左手でベッド柵をつかむように伝える。"},{"id":"2","text":"利用者に右肘を支点にして上体を起こしてもらう。"},{"id":"3","text":"利用者の右脚をベッドから下ろす。"},{"id":"4","text":"利用者の頸部｛けいぶ｝を支えて上体を起こす。"},{"id":"5","text":"端座位の利用者の右側に立って上体を支える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！左片麻痺の人を、右側臥位から起こすときは、健側の右肘を支点にして、上体を起こしてもらうんだ。自分の力を生かせるから、自立支援にもつながるよ。1は、左手（麻痺側）ではつかめないね。3は、脚を先に下ろすのは、上体を起こすのと同時ではないよ。4は、頸部だけを支えるのは危険。5は、麻痺のある左側に立つのが基本だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-087","examYear":"2025","examRound":"37","questionNumber":87,"category":"生活支援技術","questionText":"口腔｛こうくう｝ケアに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"うがいは、顔貌を整える。"},{"id":"2","text":"歯みがきは、感染予防になる。"},{"id":"3","text":"口腔内｛こうくうない｝の乾燥は、口臭を予防する。"},{"id":"4","text":"唾液腺マッサージは、唾液の分泌を抑える。"},{"id":"5","text":"咀嚼機能｛そしゃくきのう｝の向上のために、タッピングを行う。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！歯みがきは、歯垢や食べかすを取って、口の中を清潔にするから、むし歯や歯周病、誤嚥性肺炎などの感染予防になるんだ。1は、うがいは、口の中の汚れを流すのが目的。3は、口腔内の乾燥は、口臭の原因になるよ。4は、唾液腺マッサージは、唾液の分泌を促す。5は、タッピングではなく、咀嚼を助けるのは運動や食事の工夫だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-088","examYear":"2025","examRound":"37","questionNumber":88,"category":"生活支援技術","questionText":"次の記述のうち、口腔｛こうくう｝ケアを実施するときの留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"実施中は、利用者に顎を上げた姿勢をとってもらう。"},{"id":"2","text":"総義歯は、上顎から下顎の順に外してもらう。"},{"id":"3","text":"歯みがきの前に、うがいを行ってもらう。"},{"id":"4","text":"歯ブラシは、大きく動かして磨いてもらう。"},{"id":"5","text":"舌ブラシは、舌先から咽頭に向かって動かしてもらう。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！歯みがきの前にうがいをして、口の中の食べかすを取り除いておくと、みがきやすくなるんだ。1は、顎を上げると誤嚥しやすい。2は、義歯は外す順序より、傷つけないよう丁寧に扱うことが大切だよ。4は、歯ブラシは小刻みに動かす。5は、舌ブラシは奥から手前に動かすんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-089","examYear":"2025","examRound":"37","questionNumber":89,"category":"生活支援技術","questionText":"次の記述のうち、介護が必要な人への熱中症対策のために、介護福祉職が行う水分補給の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"のどが渇いてから、水分を取るように伝える。"},{"id":"2","text":"水でむせるときは、ゼリーの提供を控える。"},{"id":"3","text":"起床時は、水分摂取を控えるように伝える。"},{"id":"4","text":"食事のときの水分は、一日の水分摂取量から除く。"},{"id":"5","text":"汗の量が多いときは、塩分を含んだ飲み物を勧める。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！汗を多くかいたときは、水分だけでなく、塩分も失われるので、塩分を含んだ飲み物を勧めるとよいんだ。1は、のどが渇く前に、こまめに水分をとることが大切。2は、むせるときは、ゼリーなどで、水分をとれるようにする。3は、起床時も水分が必要。4は、食事の水分も、摂取量にふくめるよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-090","examYear":"2025","examRound":"37","questionNumber":90,"category":"生活支援技術","questionText":"Ａさん（75歳、男性）は、1年前に前頭側頭型認知症（frontotemporal dementia）と診断され、現在は、認知症対応型共同生活介護（認知症高齢者グループホーム）に入居している。若い頃から食べることが好きである。現在、咀嚼｛そしゃく｝や嚥下機能｛えんげきのう｝の低下はなく、スプーンを使い、自分で食べている。最近、飲み込む前に次々と食べ物を口に入れることが増えた。\n次の記述のうち、Ａさんの現在の状態に合わせた食事の介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"取っ手つきのコップを準備する。"},{"id":"2","text":"食器に少量ずつ盛りつけて提供する。"},{"id":"3","text":"すべての料理をテーブルの上に並べる。"},{"id":"4","text":"大きなスプーンに変更する。"},{"id":"5","text":"手で持って食べられる物を準備する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！前頭側頭型認知症では、食べ物を次々と口に詰め込む行動がみられることがあるんだ。器に少量ずつ盛りつけて、ゆっくり食べられるようにすると、誤嚥や窒息を防げるよ。1のコップは、飲む動作の話だね。3は、目の前に全部あると、詰め込みが増える。4の大きなスプーンは、1回量が増えて危険で、5は、手づかみは、今の状態に合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-091","examYear":"2025","examRound":"37","questionNumber":91,"category":"生活支援技術","questionText":"次の記述のうち、パーキンソン病（Parkinson disease）で上肢の震えはあるが、自力摂取が可能な利用者の食事の介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食事後に口腔内｛こうくうない｝のアイスマッサージを行う。"},{"id":"2","text":"片側の縁が高くなっている皿を準備する。"},{"id":"3","text":"上半身を後ろに20度程度倒すように伝える。"},{"id":"4","text":"食器の置いてある位置を説明する。"},{"id":"5","text":"踵｛かかと｝を床から浮かすように伝える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！パーキンソン病で、手の震えがあるときは、片側の縁が高くなっている皿だと、食べ物をスプーンですくいやすいんだ。1は、食事の前にアイスマッサージを行うのが目的。3は、上半身を後ろに倒すと、誤嚥しやすい。4は、視覚障害のある人に対する配慮だよ。5は、かかとは床につけて、姿勢を安定させるよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-092","examYear":"2025","examRound":"37","questionNumber":92,"category":"生活支援技術","questionText":"次の記述のうち、入浴の作用を生かした、高齢者への入浴の介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食事は、入浴直前に摂取する。"},{"id":"2","text":"高血圧の人には、42℃以上の湯につかってもらう。"},{"id":"3","text":"浴槽の中では、関節運動を促す。"},{"id":"4","text":"心疾患（heart disease）のある人には、肩まで湯につかってもらう。"},{"id":"5","text":"個浴の浴槽内では、足を浮かせてもらう。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！お湯につかると、浮力で体が軽くなるので、関節運動を促して、リハビリのような効果もあるんだ。1は、食事の直前や直後の入浴は、消化に負担がかかるので避けるよ。2は、高血圧の人は、熱いお湯は危険。4は、心疾患の人は、肩までつかると、心臓に負担がかかるね。5は、足を浮かせると、姿勢が不安定になるので、足底をつけるよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-093","examYear":"2025","examRound":"37","questionNumber":93,"category":"生活支援技術","questionText":"次の記述のうち、下肢筋力が低下して介護を必要とする人の入浴に適した環境として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"浴室の入口は開き戸にする。"},{"id":"2","text":"床から浴槽の縁までの高さは20cmにする。"},{"id":"3","text":"縦に長く、浅めの洋式の浴槽にする。"},{"id":"4","text":"浴槽の縁の幅は20cmにする。"},{"id":"5","text":"浴槽への出入りのために、水平および垂直の手すりを設置する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！下肢の筋力が低下している人には、水平と垂直の手すりが、浴槽の出入りや立ち座りを助けてくれるんだ。1は、入口は引き戸のほうが安全で、2は、浴槽の縁の高さは、40〜45cm程度がよいよ。3は、洋式の浅い浴槽は、立ち上がりにくくなる。4は、縁の幅は、腰かけられるように、広めにするんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-094","examYear":"2025","examRound":"37","questionNumber":94,"category":"生活支援技術","questionText":"次の記述のうち、体調不良で入浴できない片麻痺｛かたまひ｝の利用者に対して、ベッド上で行う全身清拭の方法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"清拭時は、窓を開けて行う。"},{"id":"2","text":"洗面器には、40℃程度のお湯を準備する。"},{"id":"3","text":"最初に、腹部から清拭する。"},{"id":"4","text":"背部は、患側を下にした側臥位｛そくがい｝にして拭く。"},{"id":"5","text":"蒸しタオルで拭いた後は、乾いたタオルで水分を拭き取る。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！蒸しタオルで拭いたあとは、乾いたタオルで水分を拭き取って、体が冷えないようにするんだ。1は、窓を開けると寒いので、室温を整えて閉める。2は、湯の温度は50〜55℃くらいが適温。3は、清拭は、顔から手足、胸腹部、背部の順に行うよ。4は、背部は、健側を下にした側臥位で拭くんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-095","examYear":"2025","examRound":"37","questionNumber":95,"category":"生活支援技術","questionText":"次のうち、同居の高齢者におむつを使用する家族介護者に対する、介護福祉職の説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「使用する本人の羞恥心に気を配りましょう」"},{"id":"2","text":"「尿失禁を防ぐことができます」"},{"id":"3","text":"「尿量を気にせずに、1日中同じおむつを使うことができます」"},{"id":"4","text":"「おむつを着けると、安心して排泄｛はいせつ｝ができます」"},{"id":"5","text":"「家族の都合に合わせて、おむつを使いましょう」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！おむつの使用は、本人の羞恥心や自尊心に配慮することが、いちばん大切なんだ。2は、おむつは、尿失禁を防ぐものではなく、漏れを吸収するものだよ。3は、長時間つけたままだと、皮膚トラブルの原因になる。4は、安心して排泄できるとは限らず、5は、家族の都合ではなく、本人の状態や意思に合わせるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-096","examYear":"2025","examRound":"37","questionNumber":96,"category":"生活支援技術","questionText":"次の記述のうち、ポータブルトイレを使用するときの排泄｛はいせつ｝の介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ポータブルトイレの下に新聞紙を敷く。"},{"id":"2","text":"ベッドで臥床｛がしょう｝している状態で、ズボンや下着をおろす。"},{"id":"3","text":"ポータブルトイレには、前かがみになって座ってもらう。"},{"id":"4","text":"排泄｛はいせつ｝が終わるまで、ポータブルトイレの後ろに立って待つ。"},{"id":"5","text":"排泄後｛はいせつご｝の陰部の清拭は、ベッドの上で行う。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ポータブルトイレでは、前かがみ（前傾姿勢）になると、腹圧がかけやすくて、排泄しやすいんだ。1は、新聞紙ではなく、防水シートなどを敷くよ。2は、ズボンや下着は、座る前に、立位や座位のときに下ろす。4は、後ろではなく、プライバシーに配慮して、少し離れて待つ。5は、清拭は、状況に応じて行うので、限定はされないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-097","examYear":"2025","examRound":"37","questionNumber":97,"category":"生活支援技術","questionText":"次の記述のうち、介護福祉職が行うことのできる、坐薬｛ざやく｝（座薬）を用いた介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"膣｛ちつ｝から挿入する坐薬｛ざやく｝（座薬）が扱える。"},{"id":"2","text":"坐薬｛ざやく｝（座薬）は、あたたかな場所で保管する。"},{"id":"3","text":"坐薬｛ざやく｝（座薬）は、とがっていない方から挿入する。"},{"id":"4","text":"腹部に力を入れるよう促しながら、坐薬｛ざやく｝（座薬）を挿入する。"},{"id":"5","text":"下剤以外の坐薬｛ざやく｝（座薬）挿入は、先に排泄｛はいせつ｝を済ませてから行う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！下剤以外の坐薬は、便がたまっていると効きにくく、薬が出てしまうことがあるので、先に排泄を済ませてから挿入するんだ。1は、膣からの挿入は、扱えない。2は、坐薬は冷所で保管する。3は、とがった方から挿入する。4は、力を入れずに、口呼吸で力を抜いてもらうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-098","examYear":"2025","examRound":"37","questionNumber":98,"category":"生活支援技術","questionText":"次の記述のうち、調理における基本調味料の効果や使い方として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"砂糖は、塩より先に入れると、食物に甘みが浸透しやすくなる。"},{"id":"2","text":"塩は、食物のうま味を増し、照りを出す。"},{"id":"3","text":"酢は、食物の水分を引き出し、保存性を高める。"},{"id":"4","text":"しょうゆは、食物のくさみを抜き、肉を柔らかくする。"},{"id":"5","text":"みそは、味付けの最初に入れると、特有の香りが逃げない。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！砂糖は、塩より先に入れると、甘みが食材に浸透しやすくなるんだ。「さ・し・す・せ・そ」の順序は、料理の基本だね。2は、塩は、水分を引き出して、味を引き締めるよ。3は、酢は、殺菌作用があり、保存性を高めるけれど、水分を引き出すのは塩。4は、くさみを抜いて肉を柔らかくするのは、酒など。5は、みそは、香りが逃げないよう、最後に入れるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-099","examYear":"2025","examRound":"37","questionNumber":99,"category":"生活支援技術","questionText":"食品の保存に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"賞味期限の切れた未開封の缶詰は、すぐに廃棄する。"},{"id":"2","text":"ウインナーには、消費期限が記載されている。"},{"id":"3","text":"前日調理して常温保存した肉入りカレーは、再加熱する。"},{"id":"4","text":"りんごを冷蔵庫で保存するときは、ビニール袋に入れて密封する。"},{"id":"5","text":"冷凍食品は、一度解凍しても再冷凍すれば長期間の保存が可能である。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！りんごは、ビニール袋に入れて、密封して冷蔵庫で保存すると、乾燥や、においうつりを防げるんだ。1は、賞味期限が切れても、すぐに食べられなくなるわけではなく、状態を確認するよ。2は、ウインナーは、賞味期限の表示だね。3は、常温保存は不適当で、冷蔵が必要。5は、一度解凍した食品を再冷凍すると、品質が落ちて、衛生的にも危険だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-100","examYear":"2025","examRound":"37","questionNumber":100,"category":"生活支援技術","questionText":"次の記述のうち、衣類の保管方法として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"衣装ケースで保管するときは、たたんだ衣類の下に防虫剤を入れる。"},{"id":"2","text":"ドライクリーニング後の衣類は、ビニールを外さずに保管する。"},{"id":"3","text":"汚れのひどい衣類は、介護福祉職の判断で廃棄する。"},{"id":"4","text":"湿気を含んだ衣類は、たたんで引き出しに保管する。"},{"id":"5","text":"絹製品は、タンスの上部に保管する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！絹製品は、湿気に弱いので、湿気が少ないタンスの上部に保管するのがよいんだ。1は、防虫剤の成分は空気より重くて、下に広がるので、衣類の上に置くよ。2は、ドライクリーニング後は、ビニールを外して、溶剤を飛ばしてから保管する。3は、廃棄は、本人の意思確認が必要。4は、湿気を含んだ衣類は、乾かしてからしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-101","examYear":"2025","examRound":"37","questionNumber":101,"category":"生活支援技術","questionText":"次の記述のうち、介護の現場で行うベッドメイキングとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"居室の窓は、閉めて行う。"},{"id":"2","text":"キャスターのあるベッドは、ストッパーを外す。"},{"id":"3","text":"シーツの中心線を、マットレスの端に合わせる。"},{"id":"4","text":"シーツをマットレスの下に入れるときは、手掌を下にする。"},{"id":"5","text":"シーツ交換は、両膝を伸ばしたままで行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！シーツをマットレスの下に入れるときは、手掌を下にして入れると、手を痛めにくく、きれいに整えられるんだ。1は、ホコリを出すために、窓は開けて換気する。2は、キャスターのストッパーは、かけて固定するよ。3は、中心線は、マットレスの中央に合わせる。5は、腰への負担を減らすため、膝を曲げて、重心を低くするんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-102","examYear":"2025","examRound":"37","questionNumber":102,"category":"生活支援技術","questionText":"Ｂさん（90歳、女性、要介護3）は、アルツハイマー型認知症（dementia of the Alzheimer’s type）があり、介護老人福祉施設に入所している。テレビを見ることが好きで、日中はお茶を飲みながら、テレビを見て過ごすことが日課である。1週間前からＢさんは、夜中に目が覚めたり、3時ごろに起きたりと、不眠が続いている。2時間ほどしか寝ていない日もある。ある日、Ｂさんは、「昼間、眠くてしかたがない。からだがだるい」と介護福祉職に話した。\n次の記述のうち、Ｂさんに安眠を促すための介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"午前中、太陽の光を浴びることを勧める。"},{"id":"2","text":"昼間眠いときは、1時間以上の昼寝を勧める。"},{"id":"3","text":"夕食後、すぐに寝ることを勧める。"},{"id":"4","text":"寝る前に、介護福祉職の判断で睡眠薬を勧める。"},{"id":"5","text":"夜眠れないときは、居室でテレビを見ることを勧める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！午前中に太陽の光を浴びると、体内時計が整って、夜の自然な眠りにつながるんだ。2は、長い昼寝は、夜の眠りを妨げてしまうよ。3は、夕食後すぐの就寝は、早すぎて、夜中に目が覚める原因になる。4は、睡眠薬は、医師の指示が必要で、介護福祉職が勧めるものではないね。5は、テレビの光や音は、脳を覚醒させてしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-103","examYear":"2025","examRound":"37","questionNumber":103,"category":"生活支援技術","questionText":"終末期の介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"決まった時間に食事を提供する。"},{"id":"2","text":"部屋の換気は控えるようにする。"},{"id":"3","text":"無反応のときは無言で静かに介護を行う。"},{"id":"4","text":"呼吸困難時は、顎を下げて頭部を前屈させた仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）にする。"},{"id":"5","text":"せん妄によって話のつじつまが合わないときは、否定せずに受け止める。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！終末期のせん妄で、話のつじつまが合わなくなっても、否定せずに、本人の話を受け止めることが大切なんだ。1は、食事は、本人の状態や希望に合わせて提供するよ。2は、換気は、においや空気の入れ替えのために必要。3は、無反応でも、声かけを続けるよ。4は、呼吸困難のときは、上体を起こす姿勢が楽になるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-104","examYear":"2025","examRound":"37","questionNumber":104,"category":"生活支援技術","questionText":"次のうち、キューブラー・ロス（Kubler-Ross, E.）が提唱した終末期にある人の死の受容過程のうち、「死は避けられないと知り、さまざまな喪失感を抱く段階」に該当するものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"否認"},{"id":"2","text":"怒り"},{"id":"3","text":"取り引き"},{"id":"4","text":"抑うつ"},{"id":"5","text":"受容"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！キューブラー・ロスの死の受容過程は、否認、怒り、取り引き、抑うつ、受容の5段階なんだ。死は避けられないと知って、さまざまな喪失感を抱くのが、「抑うつ」の段階だよ。1は、事実を受け入れられない段階。2は、なぜ自分がと怒る段階。3は、回復を望んで、交渉する段階。5は、死を受け入れる段階だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-105","examYear":"2025","examRound":"37","questionNumber":105,"category":"生活支援技術","questionText":"Ｃさん（58歳、男性）は、アテトーゼ型（athetosis）の脳性麻痺｛のうせいまひ｝（cerebral palsy）がある。腕、脚、体幹の筋肉は不随意的にゆっくりと動くことが多く、手指を細かく動かすことは難しい。言葉をはっきり発音することが困難であるが、音の聞き取りはできる。\n次のうち、Ｃさんが使用している情報・意思疎通支援用具として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"福祉電話"},{"id":"2","text":"携帯用会話補助装置"},{"id":"3","text":"人工喉頭"},{"id":"4","text":"助聴器"},{"id":"5","text":"点字器"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｃさんは、言葉をはっきり発音するのが難しいけれど、音の聞き取りはできるんだね。携帯用会話補助装置は、文字や音声で意思を伝えられるから、Ｃさんにぴったりなんだ。1の福祉電話は聴覚や音声の障害向け、3の人工喉頭は喉頭を摘出した人向け、4の助聴器は聴覚障害向け、5の点字器は視覚障害向けだよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-106","examYear":"2025","examRound":"37","questionNumber":106,"category":"介護過程","questionText":"次の記述のうち、介護過程を展開する目的として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族が抱える生活課題の解決"},{"id":"2","text":"個別ケアに基づく利用者の自立支援"},{"id":"3","text":"介護福祉職の職業倫理の向上"},{"id":"4","text":"利用者と家族の信頼関係の構築"},{"id":"5","text":"介護福祉職と他職種の連携の促進"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護過程は、利用者の生活課題を明らかにして、その人らしい生活を支えるために、個別ケアにもとづいて、自立を支援することが目的なんだ。1は、家族の課題ではなく、利用者が対象。3、4、5は、介護過程を展開した結果として期待される効果にはなるけれど、目的そのものではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-107","examYear":"2025","examRound":"37","questionNumber":107,"category":"介護過程","questionText":"生活課題に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族の立場から検討する。"},{"id":"2","text":"利用者のニーズを判断の基盤にする。"},{"id":"3","text":"利用者の要望を1つに集約する。"},{"id":"4","text":"介護福祉職の主観を尊重する。"},{"id":"5","text":"生命の危機よりも利用者の意向を優先する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！生活課題は、利用者のニーズ（その人が必要としていること）を基盤にして、検討するんだ。1は、家族の立場ではなく、利用者の立場。3は、要望を1つにまとめるのではなく、複数の課題を整理する。4は、介護福祉職の主観ではなく、客観的な根拠が必要。5は、生命の危機がある場合は、意向より安全を優先するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-108","examYear":"2025","examRound":"37","questionNumber":108,"category":"介護過程","questionText":"次の記述のうち、介護過程の展開における評価の説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"他の利用者と比較して評価する。"},{"id":"2","text":"短期目標の評価によって、介護過程の展開を終了する。"},{"id":"3","text":"目標の達成状況を評価する。"},{"id":"4","text":"介護計画の実施後に評価日を検討する。"},{"id":"5","text":"介護計画を修正した場合は、評価を省略する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！評価では、立てた目標が、どのくらい達成できたかを確認して、次の支援につなげるんだ。1は、他の利用者ではなく、その人自身の目標との比較が大切。2は、短期目標の評価後も、展開は続く。4は、評価日は、計画を立てるときにあらかじめ決めるよ。5は、計画を修正した場合も、評価は必要なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-109","examYear":"2025","examRound":"37","questionNumber":109,"category":"介護過程","questionText":"次のうち、介護保険制度のサービス担当者会議におけるサービス提供責任者の役割として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"会議の主催"},{"id":"2","text":"居宅サービス計画の原案の説明"},{"id":"3","text":"他職種が実施したサービス内容の評価"},{"id":"4","text":"訪問介護計画の作成に要した時間の報告"},{"id":"5","text":"訪問介護計画の作成に必要な情報の確認"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！サービス提供責任者は、訪問介護計画を作るのに必要な、利用者の状況や、他職種のサービス内容などの情報を、会議で確認するんだ。1と2は、会議を主催し、居宅サービス計画の原案を説明するのは、介護支援専門員の役割だよ。3は、他職種の評価はしないし、4は、作成にかかった時間の報告は、必要ないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-110","examYear":"2025","examRound":"37","questionNumber":110,"category":"介護過程","questionText":"次の事例を読んで、問題110、問題111について答えなさい。\n〔事  例〕\nＡさん（78歳、男性、要介護1）は、一人暮らしで、脳梗塞（cerebral infarction）を発症し入院した。その後、リハビリテーションを経て、自宅に戻った。利き手の右手に麻痺｛まひ｝が残ったため、左手を使った調理の自立を目的に、訪問介護（ホームヘルプサービス）を利用することになった。サービス利用時は、訪問介護員（ホームヘルパー）の協力を得ながら、孫からプレゼントされた包丁を使って、調理に取り組んでいた。\nある日、好物の牛肉をうまく押さえることができず、切ることができなかった。すると、Ａさんは包丁を置き、部屋で横になってしまった。心配した訪問介護員（ホームヘルパー）が声をかけ、バイタルサインを確認したところ変化はなかった。Ａさんは、「右手が思うように動いてくれない。悔しい。でも、もう一度ひとりで作れるようになりたい」と話した。\n次の日、Ａさんは、「今日も手伝って」と訪問介護員（ホームヘルパー）に話した。\n調理中にＡさんが包丁を置き、部屋で横になってしまった行動に対する解釈として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"体調不良による休憩"},{"id":"2","text":"食材に対する不満"},{"id":"3","text":"調理に対する興味の喪失"},{"id":"4","text":"包丁に対する不満"},{"id":"5","text":"調理がうまくできないことに対する苛立｛いらだ｝ち"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、バイタルサインに変化がなく、「悔しい。でも、もう一度ひとりで作れるようになりたい」と話しているんだね。だから、うまく切れなくて苛立ち、包丁を置いたと考えられるよ。1は体調不良を示さず、2、3、4は、Ａさんの言葉から、不満や興味の喪失は読み取れないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-111","examYear":"2025","examRound":"37","questionNumber":111,"category":"介護過程","questionText":"次の事例を読んで、問題110、問題111について答えなさい。\n〔事  例〕\nＡさん（78歳、男性、要介護1）は、一人暮らしで、脳梗塞（cerebral infarction）を発症し入院した。その後、リハビリテーションを経て、自宅に戻った。利き手の右手に麻痺｛まひ｝が残ったため、左手を使った調理の自立を目的に、訪問介護（ホームヘルプサービス）を利用することになった。サービス利用時は、訪問介護員（ホームヘルパー）の協力を得ながら、孫からプレゼントされた包丁を使って、調理に取り組んでいた。\nある日、好物の牛肉をうまく押さえることができず、切ることができなかった。すると、Ａさんは包丁を置き、部屋で横になってしまった。心配した訪問介護員（ホームヘルパー）が声をかけ、バイタルサインを確認したところ変化はなかった。Ａさんは、「右手が思うように動いてくれない。悔しい。でも、もう一度ひとりで作れるようになりたい」と話した。\n次の日、Ａさんは、「今日も手伝って」と訪問介護員（ホームヘルパー）に話した。\n訪問介護計画の修正を目的としたカンファレンスで、訪問介護員（ホームヘルパー）が提案する内容として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"訪問介護員（ホームヘルパー）による調理の代行"},{"id":"2","text":"担当する訪問介護員（ホームヘルパー）の交代"},{"id":"3","text":"配食サービスの利用"},{"id":"4","text":"調理に関する福祉用具の活用"},{"id":"5","text":"訪問回数の削減"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんは、もう一度ひとりで作りたいと願っているので、片手で食材を押さえられる福祉用具を活用するのが、いちばん自立につながるんだ。1の調理の代行や、3の配食サービスは、Ａさんの意欲を生かせないね。2の訪問介護員の交代や、5の回数削減は、課題の解決にならないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-112","examYear":"2025","examRound":"37","questionNumber":112,"category":"介護過程","questionText":"次の事例を読んで、問題112、問題113について答えなさい。\n〔事  例〕\nＢさん（42歳、女性、障害支援区分3）は、知的障害があり、母親と二人暮らしである。日中は生活介護事業所に通っている。日常生活動作の一部に見守りが必要である。個別支援計画の短期目標を、「見守りのもと、トイレで排泄｛はいせつ｝ができる」としている。\nしかし、最近、排泄｛はいせつ｝のときに下着やズボンを汚してしまい、それをほかの利用者にからかわれ、しばらく一人でいる様子があったと生活支援員から申し送りがあった。\nある日、事業所長が話しかけると、Ｂさんは、「トイレで失敗したら恥ずかしい」と元気なく話した。母親からも電話で、「これからは紙おむつを使うように勧めているのだけど、使いたくないとＢは話している」とサービス管理責任者に連絡があった。\n次のうち、Ｂさんがしばらく一人でいた様子を理解するために必要な情報として、最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"サービス管理責任者との関係"},{"id":"2","text":"生活支援員との関係"},{"id":"3","text":"事業所長との関係"},{"id":"4","text":"ほかの利用者との関係"},{"id":"5","text":"母親との関係"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｂさんが一人でいたのは、ほかの利用者にからかわれたことがきっかけなんだ。だから、いちばん優先して知りたいのは、ほかの利用者との関係なんだよ。1、2、3の職員との関係や、5の母親との関係は、事実として、きっかけになっていないので、優先度は低いね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-113","examYear":"2025","examRound":"37","questionNumber":113,"category":"介護過程","questionText":"次の事例を読んで、問題112、問題113について答えなさい。\n〔事  例〕\nＢさん（42歳、女性、障害支援区分3）は、知的障害があり、母親と二人暮らしである。日中は生活介護事業所に通っている。日常生活動作の一部に見守りが必要である。個別支援計画の短期目標を、「見守りのもと、トイレで排泄｛はいせつ｝ができる」としている。\nしかし、最近、排泄｛はいせつ｝のときに下着やズボンを汚してしまい、それをほかの利用者にからかわれ、しばらく一人でいる様子があったと生活支援員から申し送りがあった。\nある日、事業所長が話しかけると、Ｂさんは、「トイレで失敗したら恥ずかしい」と元気なく話した。母親からも電話で、「これからは紙おむつを使うように勧めているのだけど、使いたくないとＢは話している」とサービス管理責任者に連絡があった。\nＢさんについて、個別支援会議が開催され、短期目標を、「排泄｛はいせつ｝の自立（下着を汚さずに排泄｛はいせつ｝する）（3か月）」とした。次の記述のうち、Ｂさんの短期目標を実現するために生活支援員がとる対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"定期的に、手順を理解できているか一緒に確認する。"},{"id":"2","text":"自宅で排泄｛はいせつ｝を済ませ、事業所で排泄｛はいせつ｝しないように助言する。"},{"id":"3","text":"母親の要望であると伝え、紙おむつを使うように助言する。"},{"id":"4","text":"ポータブルトイレを設置し、そこで排泄｛はいせつ｝をするように誘導する。"},{"id":"5","text":"排泄｛はいせつ｝に関する行為を、全介助にする。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｂさんの短期目標は、下着を汚さずに排泄する自立をめざすこと。手順を理解できているか、定期的に一緒に確認する支援が、目標の達成につながるんだ。2は、事業所での排泄を避けさせるので、自立の機会を奪うよ。3のおむつは、本人が望んでいない。4は、目標に合わず、5の全介助は、自立とは逆だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-114","examYear":"2025","examRound":"37","questionNumber":114,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＡさん（70歳、男性）は、妻と二人で暮らしている。旅行や釣りが趣味で、会社員として勤務していたころは、活動的な生活を送っていた。66歳のときにパーキンソン病（Parkinson disease）と診断されたが、内服治療が開始され、症状はあまり気にならなかった。1年前から顔の表情が乏しくなり、歩行開始時に、はじめの一歩が出にくくなった。3か月前からは、歩き始めると方向転換が難しく、急に止まることができないことがある。\nＡさんは、今後の生活について相談するために、地域包括支援センターに行った。センターで対応してくれたＢ主任介護支援専門員は、介護福祉士としての実務経験が豊富だった。Ａさんは信頼して、気になっていたことをすべて話すことができた。Ａさんは、要介護認定を申請することを勧められ、後日、市役所に行き、要介護認定の申請を行った。\n現在のＡさんの症状に該当するホーエン・ヤール重症度分類として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ステージⅠ"},{"id":"2","text":"ステージⅡ"},{"id":"3","text":"ステージⅢ"},{"id":"4","text":"ステージⅣ"},{"id":"5","text":"ステージⅤ"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ホーエン・ヤール重症度分類のステージ3は、姿勢反射障害（方向転換が難しい、急に止まれない）が現れて、歩行は自立していても、日常生活に支障が出る段階なんだ。Ａさんの症状が、これに合うよ。ステージ1、2は、症状が軽くて、姿勢反射障害はなく、4は介助が必要、5は車いすやベッドで生活する段階だね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-115","examYear":"2025","examRound":"37","questionNumber":115,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＡさん（70歳、男性）は、妻と二人で暮らしている。旅行や釣りが趣味で、会社員として勤務していたころは、活動的な生活を送っていた。66歳のときにパーキンソン病（Parkinson disease）と診断されたが、内服治療が開始され、症状はあまり気にならなかった。1年前から顔の表情が乏しくなり、歩行開始時に、はじめの一歩が出にくくなった。3か月前からは、歩き始めると方向転換が難しく、急に止まることができないことがある。\nＡさんは、今後の生活について相談するために、地域包括支援センターに行った。センターで対応してくれたＢ主任介護支援専門員は、介護福祉士としての実務経験が豊富だった。Ａさんは信頼して、気になっていたことをすべて話すことができた。Ａさんは、要介護認定を申請することを勧められ、後日、市役所に行き、要介護認定の申請を行った。\n要介護認定を申請してから2週間が経過した。Ａさんは要介護認定の認定結果が届かないことが気になった。そこで、以前に対応してくれたＢ主任介護支援専門員に電話で相談した。\n次のうち、Ｂ主任介護支援専門員の応答として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「次の受診時に主治医に相談しましょう」"},{"id":"2","text":"「通常1か月程度かかるので、あと2週間くらい待ってみましょう」"},{"id":"3","text":"「以前に自宅に来てくれた認定調査員に相談しましょう」"},{"id":"4","text":"「念のためにもう一度要介護認定を申請してください」"},{"id":"5","text":"「通常であれば認定結果は出ていると思います」"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！要介護認定の結果は、申請から原則30日以内に通知されるんだ。2週間なら、まだ結果が出なくてもふつうだから、あと2週間ほど待つよう伝えるのが適切だね。1は、主治医に相談する内容ではないし、3は、認定調査員に問い合わせる必要はないよ。4は、再申請は不要で、5は、事実とちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-116","examYear":"2025","examRound":"37","questionNumber":116,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＡさん（70歳、男性）は、妻と二人で暮らしている。旅行や釣りが趣味で、会社員として勤務していたころは、活動的な生活を送っていた。66歳のときにパーキンソン病（Parkinson disease）と診断されたが、内服治療が開始され、症状はあまり気にならなかった。1年前から顔の表情が乏しくなり、歩行開始時に、はじめの一歩が出にくくなった。3か月前からは、歩き始めると方向転換が難しく、急に止まることができないことがある。\nＡさんは、今後の生活について相談するために、地域包括支援センターに行った。センターで対応してくれたＢ主任介護支援専門員は、介護福祉士としての実務経験が豊富だった。Ａさんは信頼して、気になっていたことをすべて話すことができた。Ａさんは、要介護認定を申請することを勧められ、後日、市役所に行き、要介護認定の申請を行った。\n最近、Ａさんは急に体の動きが悪くなる時間帯があり、不安を感じた。そこでＡさんは、週に2回利用している訪問介護員（ホームヘルパー）に相談した。相談を受けた訪問介護員（ホームヘルパー）はＡさんに、日々の症状の変化とその時間、さらにもう一点をメモして、医師に伝えるようにと助言した。\n日々の症状の変化とその時間に加えて、Ａさんが医師に伝える内容として、最も優先度の高いものを1つ選びなさい。","choices":[{"id":"1","text":"服薬の時間"},{"id":"2","text":"起床の時間"},{"id":"3","text":"食事の時間"},{"id":"4","text":"排便の時間"},{"id":"5","text":"入浴の時間"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！パーキンソン病では、薬の効果が切れると、急に動きが悪くなるウェアリング・オフ現象が起こることがあるんだ。だから、症状の変化と一緒に、服薬の時間を医師に伝えることが、いちばん重要なんだよ。2、3、4、5も生活の記録にはなるけれど、優先度は、服薬時間より低いね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-117","examYear":"2025","examRound":"37","questionNumber":117,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＣさん（90歳、女性）は、動物好きで長年ペットのオウムを飼っている。5年前に夫が亡くなったときも、ペットが大きな心の支えになった。2年前、身体の衰えから買物や調理などの家事が難しくなり、一人暮らしが困難になったので、ペットと入所できる健康型有料老人ホームに入所した。\n最近Ｃさんは、毎週楽しみにしていたレクリエーションがある曜日や時間を忘れてしまう、トイレの場所がわからず失禁するなどの症状が繰り返し生じるようになってきた。心配した娘がＣさんと病院を受診したところ、アルツハイマー型認知症（dementia of the Alzheimer’s type）と診断を受けた。\n健康型有料老人ホームでは対応が困難になってきたため、心配した娘はＣさんが入所できる施設に移ることを検討し始めた。\n次のうち、最近のＣさんの症状に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"妄想"},{"id":"2","text":"見当識障害"},{"id":"3","text":"失語"},{"id":"4","text":"遂行機能障害"},{"id":"5","text":"観念失行"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！レクリエーションの曜日や時間を忘れる、トイレの場所がわからないのは、時間や場所がわからなくなる見当識障害の症状なんだ。1は、ありもしないことを信じる症状、3は、言葉が出にくくなる症状、4は、段取りよく行動できない症状、5は、道具の使い方がわからなくなる症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-118","examYear":"2025","examRound":"37","questionNumber":118,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＣさん（90歳、女性）は、動物好きで長年ペットのオウムを飼っている。5年前に夫が亡くなったときも、ペットが大きな心の支えになった。2年前、身体の衰えから買物や調理などの家事が難しくなり、一人暮らしが困難になったので、ペットと入所できる健康型有料老人ホームに入所した。\n最近Ｃさんは、毎週楽しみにしていたレクリエーションがある曜日や時間を忘れてしまう、トイレの場所がわからず失禁するなどの症状が繰り返し生じるようになってきた。心配した娘がＣさんと病院を受診したところ、アルツハイマー型認知症（dementia of the Alzheimer’s type）と診断を受けた。\n健康型有料老人ホームでは対応が困難になってきたため、心配した娘はＣさんが入所できる施設に移ることを検討し始めた。\n娘はＣさんの病状を心配して、「お父さんが残してくれた貯金があるから、もっとお母さんのお世話をしてくれる施設に移ろう」と提案した。Ｃさんは、「ペットと一緒に暮らせなくなるのは嫌だ」とつぶやき、うつむいた。困った娘は健康型有料老人ホームの介護福祉士に相談した。\n次のうち、娘への介護福祉士の応答として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「Ｃさんがペットを大事にしている意思を尊重してはいかがですか」"},{"id":"2","text":"「Ｃさんが新しい施設に行くことが最優先です」"},{"id":"3","text":"「あなたの意向を優先してはいかがですか」"},{"id":"4","text":"「Ｃさんがペットを飼うことは優先度の高いニーズとは言えません」"},{"id":"5","text":"「Ｃさんが新しい施設に行くことを受け入れるように説得してください」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｃさんは、「ペットと一緒に暮らせなくなるのは嫌だ」と話しているよね。ペットは、夫を亡くしたときの心の支えでもあったので、その意思を尊重することが、いちばん大切なんだ。2、3、5は、本人の意向を後回しにしているよ。4は、大切なニーズを軽く見てしまっているね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-119","examYear":"2025","examRound":"37","questionNumber":119,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＣさん（90歳、女性）は、動物好きで長年ペットのオウムを飼っている。5年前に夫が亡くなったときも、ペットが大きな心の支えになった。2年前、身体の衰えから買物や調理などの家事が難しくなり、一人暮らしが困難になったので、ペットと入所できる健康型有料老人ホームに入所した。\n最近Ｃさんは、毎週楽しみにしていたレクリエーションがある曜日や時間を忘れてしまう、トイレの場所がわからず失禁するなどの症状が繰り返し生じるようになってきた。心配した娘がＣさんと病院を受診したところ、アルツハイマー型認知症（dementia of the Alzheimer’s type）と診断を受けた。\n健康型有料老人ホームでは対応が困難になってきたため、心配した娘はＣさんが入所できる施設に移ることを検討し始めた。\nＣさんと娘は介護福祉士と相談し、希望に沿った施設を見つけることができた。\n次のうち、Ｃさんが入所する施設として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"経過的軽費老人ホーム（Ｂ型）"},{"id":"2","text":"介護医療院"},{"id":"3","text":"介護老人保健施設"},{"id":"4","text":"養護老人ホーム"},{"id":"5","text":"介護付有料老人ホーム"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｃさんは、認知症で介護が必要になり、ペットと一緒に暮らしたいと希望しているんだね。ペットと暮らせる介護付有料老人ホームが、希望に合う施設だよ。1の軽費老人ホームは、自立が前提だし、2の介護医療院と、3の介護老人保健施設は、医療やリハビリが中心の施設。4の養護老人ホームは、経済的な理由などで入所するので、合わないね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-120","examYear":"2025","examRound":"37","questionNumber":120,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＤさん（男性、障害支援区分4）は、ベッカー型筋ジストロフィー（Becker muscular dystrophy）である。自宅で家族と生活をしている。Ｄさんは、食事は自立しているが、排泄｛はいせつ｝、入浴に介護が必要である。歩行はできず、移動は電動車いすを使用している。絵を描くことが趣味であり、日中は創作活動に取り組んでいる。\nこれまでＤさんは自宅で家族の介護を受けながら生活してきたが、Ｄさんの身体機能の低下に伴い、家族の介護負担が増えたため、居宅介護を利用することになった。\nＤさんの疾患で生じる病態として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"筋線維の変性"},{"id":"2","text":"運動神経の変性"},{"id":"3","text":"網膜の変性"},{"id":"4","text":"自己免疫の低下"},{"id":"5","text":"脳細胞の変性"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！筋ジストロフィーは、筋肉の細胞（筋線維）が壊れていく（変性する）遺伝性の病気なんだ。だから、筋力がだんだん低下していくよ。2は、運動神経が変性するのは、筋萎縮性側索硬化症（ＡＬＳ）だね。3は、網膜の変性、4は、免疫の病気、5は、脳細胞の変性で、別の病気だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-121","examYear":"2025","examRound":"37","questionNumber":121,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＤさん（男性、障害支援区分4）は、ベッカー型筋ジストロフィー（Becker muscular dystrophy）である。自宅で家族と生活をしている。Ｄさんは、食事は自立しているが、排泄｛はいせつ｝、入浴に介護が必要である。歩行はできず、移動は電動車いすを使用している。絵を描くことが趣味であり、日中は創作活動に取り組んでいる。\nこれまでＤさんは自宅で家族の介護を受けながら生活してきたが、Ｄさんの身体機能の低下に伴い、家族の介護負担が増えたため、居宅介護を利用することになった。\nこの問題は、視覚素材問題です。\nDさんのジェノグラムが示されています。\nジェノグラムに示されていることを説明します。\nDさん男性は、結婚し息子と３人で暮らしている。\nDさんの兄は独身である。\nDさんは、母親と一緒に暮らしていない。\nDさんの父親は、死亡している。\nDさんの妻は一人娘で、両親は生存している。\n問題  E居宅介護事業所に勤務するF介護福祉職は、Dさん宅を初回訪問するにあたりフェイスシートのジェノグラムを確認した。\n以下のジェノグラムからF介護福祉職が把握した内容として、適切なものを１つ選びなさい。","choices":[{"id":"1","text":"Dさんは、Dさんの母親と同居している。"},{"id":"2","text":"Dさんには息子がいる。"},{"id":"3","text":"Dさんの兄は結婚している。"},{"id":"4","text":"Dさんの父親は生存している。"},{"id":"5","text":"Dさんの妻には兄弟姉妹がいる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ジェノグラムの説明から、Ｄさんには結婚して、息子がいることがわかるんだ。1は、Ｄさんは、母親と一緒に暮らしていないよ。3は、兄は、独身だね。4は、父親は、死亡しているよ。5は、Ｄさんの妻は、一人娘だから、きょうだいはいないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-122","examYear":"2025","examRound":"37","questionNumber":122,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＤさん（男性、障害支援区分4）は、ベッカー型筋ジストロフィー（Becker muscular dystrophy）である。自宅で家族と生活をしている。Ｄさんは、食事は自立しているが、排泄｛はいせつ｝、入浴に介護が必要である。歩行はできず、移動は電動車いすを使用している。絵を描くことが趣味であり、日中は創作活動に取り組んでいる。\nこれまでＤさんは自宅で家族の介護を受けながら生活してきたが、Ｄさんの身体機能の低下に伴い、家族の介護負担が増えたため、居宅介護を利用することになった。\nＤさんが居宅介護を利用してから数年が経過し、Ｄさんの身体機能は徐々に低下して、着替えに時間がかかるようになった。Ｄさんは自分のことはできるだけ自分で行いたいという思いがあり、時間がかかっても自分で着替えをしていた。\nある日、ＤさんはＦ介護福祉職に、「着替えをすると疲れてしまい、絵を描くことができない」とつぶやいた。Ｆ介護福祉職は、「着替えは私たちや家族の介護を利用して、Ｄさんは好きな絵を描いたらいいのではないですか」と伝えた。その後、Ｄさんは介護福祉職と家族の介護を利用して、短時間で着替えを済ませ、絵を描くことに専念できるようになった。\nＦ介護福祉職が発言した自立観を示した人物として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ヴィクトール・フランクル（Frankl, V.）"},{"id":"2","text":"バンク－ミケルセン（Bank-Mikkelsen, N.）"},{"id":"3","text":"エド・ロバーツ（Roberts, E.）"},{"id":"4","text":"フェリックス・バイステック（Biestek, F.）"},{"id":"5","text":"ミルトン・メイヤロフ（Mayeroff, M.）"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｆ介護福祉職は、着替えは介護に任せて、好きな絵を描くことに力を使ってはどうかと伝えたよね。これは、自分で決めて、その人らしく生きることを重視する、自立生活運動の考え方で、エド・ロバーツが示した自立観なんだ。1は生きる意味、2はノーマライゼーション、4は援助の原則、5は「ケアの本質」で有名だよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-123","examYear":"2025","examRound":"37","questionNumber":123,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＧさん（38歳、女性）は、母親（65歳）と暮らしていた。両側性感音難聴（sensorineural hearing loss）があり、雑音がある場所では話を聞き取りにくい。相手の口の動きや表情から会話の内容を理解することはできる。Ｇさんは、脳梗塞（cerebral infarction）を発症し、左片麻痺｛ひだりかたまひ｝で車いすの生活となり、障害支援区分4と認定された。母親による介護が難しくなったため、障害者支援施設に入所することになった。\nＧさんは、写真を撮ることが好きで、施設で近くの公園に出かけたときに、介護福祉職に手伝ってもらいながら好きな風景を撮影している。Ｇさんは、その写真をアルバムにして、母親にプレゼントしたいと考えている。\nある日、Ｇさんから、「アルバムを作りたい。飾りの付け方やメッセージの書き方を教えてほしい」と相談があった。介護福祉職は、Ｇさんとアルバムを作ることにした。\n次のうち、Ｇさんが施設入所支援と同時に利用している障害福祉サービスとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自立生活援助"},{"id":"2","text":"療養介護"},{"id":"3","text":"短期入所"},{"id":"4","text":"生活介護"},{"id":"5","text":"居宅介護"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｇさんは、障害支援区分4で、障害者支援施設に入所しているんだね。施設入所支援を受ける人は、日中の活動として、生活介護を同時に利用するのが一般的なんだ。1の自立生活援助は、一人暮らしの人向け、2の療養介護は医療的ケアが必要な人向け、3の短期入所は、一時的な利用、5の居宅介護は、自宅での介護だから、入所中には使えないよ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-124","examYear":"2025","examRound":"37","questionNumber":124,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＧさん（38歳、女性）は、母親（65歳）と暮らしていた。両側性感音難聴（sensorineural hearing loss）があり、雑音がある場所では話を聞き取りにくい。相手の口の動きや表情から会話の内容を理解することはできる。Ｇさんは、脳梗塞（cerebral infarction）を発症し、左片麻痺｛ひだりかたまひ｝で車いすの生活となり、障害支援区分4と認定された。母親による介護が難しくなったため、障害者支援施設に入所することになった。\nＧさんは、写真を撮ることが好きで、施設で近くの公園に出かけたときに、介護福祉職に手伝ってもらいながら好きな風景を撮影している。Ｇさんは、その写真をアルバムにして、母親にプレゼントしたいと考えている。\nある日、Ｇさんから、「アルバムを作りたい。飾りの付け方やメッセージの書き方を教えてほしい」と相談があった。介護福祉職は、Ｇさんとアルバムを作ることにした。\n次のうち、Ｇさんの難聴の原因となっている損傷部位に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"内耳から聴神経"},{"id":"2","text":"外耳道から中耳"},{"id":"3","text":"耳介から中耳"},{"id":"4","text":"耳介から外耳道"},{"id":"5","text":"耳介"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！感音難聴は、音を感じる内耳から、脳へ伝える聴神経までの部分の損傷が原因なんだ。2、3、4、5の耳介や外耳道、中耳は、音を伝える部分で、この部分の損傷は伝音難聴の原因になるよ。感音難聴と伝音難聴のちがいを、セットで覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2025-37-125","examYear":"2025","examRound":"37","questionNumber":125,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＧさん（38歳、女性）は、母親（65歳）と暮らしていた。両側性感音難聴（sensorineural hearing loss）があり、雑音がある場所では話を聞き取りにくい。相手の口の動きや表情から会話の内容を理解することはできる。Ｇさんは、脳梗塞（cerebral infarction）を発症し、左片麻痺｛ひだりかたまひ｝で車いすの生活となり、障害支援区分4と認定された。母親による介護が難しくなったため、障害者支援施設に入所することになった。\nＧさんは、写真を撮ることが好きで、施設で近くの公園に出かけたときに、介護福祉職に手伝ってもらいながら好きな風景を撮影している。Ｇさんは、その写真をアルバムにして、母親にプレゼントしたいと考えている。\nある日、Ｇさんから、「アルバムを作りたい。飾りの付け方やメッセージの書き方を教えてほしい」と相談があった。介護福祉職は、Ｇさんとアルバムを作ることにした。\n次の記述のうち、Ｇさんに介護福祉職がアルバムの作り方を説明するときに配慮することとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｇさんの左側に座る。"},{"id":"2","text":"閉じられた質問を用いる。"},{"id":"3","text":"小さな声で話す。"},{"id":"4","text":"Ｇさんの好きな音楽を流す。"},{"id":"5","text":"1対1で向かい合って話す。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｇさんは、雑音があると聞き取りにくいけれど、口の動きや表情から内容を理解できるんだね。だから、1対1で、向かい合って話すと伝わりやすいよ。1は、麻痺のある左側に座るのは不適切。2は、閉じられた質問だと、意向を聞き出しにくい。3は、小さな声では、聞き取れないよ。4は、音楽は、雑音になってしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第37回（令和6年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/listen_k_pm_37.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no37/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-001","examYear":"2026","examRound":"38","questionNumber":1,"category":"人間の尊厳と自立","questionText":"社会福祉の理念を発展させた人物に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"バンク-ミケルセン（Bank-Mikkelsen, N.）は、「ソーシャルロール・バロリゼーション（Social Role Valorization）」を提唱した。"},{"id":"2","text":"ニィリエ（Nirje, B.）は、「ノーマライゼーション（normalization）の8つの原理」を提唱した。"},{"id":"3","text":"ヴォルフェンスベルガー（Wolfensberger, W.）は、「エーデル改革」を提唱した。"},{"id":"4","text":"リッチモンド（Richmond, M.）は、「ケースワークの7原則」を提唱した。"},{"id":"5","text":"エリクソン（Erikson, E.）は、「自立生活運動の理念」を提唱した。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ニィリエは、ノーマライゼーションの8つの原理を示した人物なんだ。1の「ソーシャルロール・バロリゼーション」を提唱したのは、ヴォルフェンスベルガー。3の「エーデル改革」はスウェーデンの高齢者福祉改革で、4の「ケースワークの7原則」を示したのはバイステック。5の自立生活運動の理念は、エド・ロバーツなどが広めたものだよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-002","examYear":"2026","examRound":"38","questionNumber":2,"category":"人間の尊厳と自立","questionText":"Ａさん（62歳、男性、要介護2）は、2年前に筋萎縮性側索硬化症（amyotrophic lateral sclerosis：ＡＬＳ）と診断された。妻と自宅で過ごしたいと希望し、訪問介護（ホームヘルプサービス）と訪問看護を利用している。最近、症状が進行し、サービス担当者会議で、Ａさんは、「人工呼吸器はつけないで、最期まで自宅で生活したい」と言った。\n会議のあと、妻は訪問介護員（ホームヘルパー）に、「夫にはなかなか言えないのですが、一日でも長く一緒にいたいので、私は人工呼吸器をつけてほしいと思っています」と気持ちを伝えた。\n次のうち、Ａさんの妻に対する訪問介護員（ホームヘルパー）の提案として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「会議で話されていたＡさんの意思が大切なので、尊重しませんか」"},{"id":"2","text":"「私にはわからないので、医師に決めてもらってはどうですか」"},{"id":"3","text":"「Ａさんに人工呼吸器をつけてもらったほうがいいですよね」"},{"id":"4","text":"「Ａさんとお互いの気持ちを話し合う時間をつくりませんか」"},{"id":"5","text":"「病院や施設の情報がほしいと介護支援専門員に伝えてはどうですか」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんと妻の意見がちがうときは、どちらかに決めるのではなく、お互いの気持ちを話し合う時間をつくることが大切なんだ。1は妻の思いを退けているし、2は責任を医師に任せてしまっているよ。3は妻の意見に偏っているし、5は問題を先送りして、今の悩みに向き合えていないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-003","examYear":"2026","examRound":"38","questionNumber":3,"category":"介護の基本","questionText":"介護施設における介護ロボットに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"導入した施設は、人員配置基準が撤廃される。"},{"id":"2","text":"使用方法は、職員個人の判断で行う。"},{"id":"3","text":"導入することによって、利用者の自立支援や生活の質の向上が期待される。"},{"id":"4","text":"導入の目的は、職員と利用者とのかかわりを最小限に抑えることである。"},{"id":"5","text":"導入によって、職員の巡回は不要になる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！介護ロボットは、利用者の自立支援や生活の質（ＱＯＬ）の向上、職員の負担軽減が期待できるんだ。1は、導入しても人員配置基準がなくなるわけではないよ。2は、使い方は施設で決めたルールに沿って統一して行うんだ。4は、かかわりを減らすのではなく、質を高めるために使うよ。5は、巡回はやっぱり必要なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-004","examYear":"2026","examRound":"38","questionNumber":4,"category":"介護の基本","questionText":"次の記述のうち、指定避難所での要配慮者に対する生活支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"避難所内の情報提供には、音声やピクトグラム（pictogram）も取り入れる。"},{"id":"2","text":"避難所内では、二次避難に備えて土足で過ごしてもらう。"},{"id":"3","text":"食事は、被災者の平等性、公平性の観点から同じものを提供する。"},{"id":"4","text":"トイレは、感染予防のために和式便器が望ましい。"},{"id":"5","text":"生活範囲は、区画されたスペースに限定する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！避難所では、視覚や聴覚に障害のある人や、外国人などにも伝わるように、音声やピクトグラム（絵記号）など、いろいろな方法で情報を提供するんだ。2は、土足では衛生面が心配だよ。3は、食事は食べやすさや、アレルギーなど、一人ひとりに配慮する。4は、和式は使いにくいので、洋式が望ましいね。5は、生活範囲を限定するのは望ましくないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-005","examYear":"2026","examRound":"38","questionNumber":5,"category":"介護の基本","questionText":"ユニバーサルデザイン（universal design）の7原則に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"安全で使いやすいデザインにする。"},{"id":"2","text":"要介護高齢者を対象とする。"},{"id":"3","text":"個別対応より標準化を優先する。"},{"id":"4","text":"介護福祉職にとって操作しやすいことを優先する。"},{"id":"5","text":"デザインの美しさを優先する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ユニバーサルデザインの7原則には、「安全に使える（誤使用の危険を減らす）」など、だれもが使いやすいデザインという考え方が含まれているんだ。2は、要介護高齢者だけでなく、すべての人が対象だよ。3は、個人差に対応できる柔軟性が大切。4は、介護者だけを優先せず、5は、美しさよりも使いやすさが大切なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-006","examYear":"2026","examRound":"38","questionNumber":6,"category":"介護の基本","questionText":"Ａさん（51歳、男性、障害支援区分5）は、知的障害がある。共同生活援助（グループホーム）で生活をしている。日中は、生活介護を利用して軽作業を行っている。Ａさんは、タオルに強いこだわりを持っていて、なじみの店で自分が選んだタオルしか使用しない。これまでタオルは、両親と買いに行っていたが、両親が高齢になり行けなくなった。Ａさんの両親から、サービス管理責任者に、「強いこだわりがあるので、いつも行く店で本人にタオルを選ばせてほしい。何か良いサービスはありませんか」と相談があった。\n次の記述のうち、サービス管理責任者の助言として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"店までの移動に不安があるため、同行援護を勧める。"},{"id":"2","text":"身体機能の維持・向上のために、自立訓練（機能訓練）を勧める。"},{"id":"3","text":"一人で外出できるように、自発的活動支援を勧める。"},{"id":"4","text":"自立した日常生活が送れるように、自立生活援助を勧める。"},{"id":"5","text":"本人が買物に行けるように、行動援護を勧める。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！行動援護は、知的障害や精神障害で行動上の困難があり、常に介護が必要な人の外出などを支援するサービスなんだ。Ａさんは知的障害があり、障害支援区分5で、買物という外出への支援が必要だからぴったりだね。1の同行援護は視覚障害のある人向け、2は身体機能の訓練、3は該当しない、4は一人暮らしを支える支援で、Ａさんは、グループホームで生活しているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-007","examYear":"2026","examRound":"38","questionNumber":7,"category":"介護の基本","questionText":"次の記述のうち、介護保険制度における一人暮らしの要支援者を支えるサービスの内容として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"夜間を安心して過ごすために、夜間対応型訪問介護を利用する。"},{"id":"2","text":"自宅で安全に移動するために、介護予防住宅改修を利用する。"},{"id":"3","text":"趣味のカラオケに行くために、小規模多機能型居宅介護を利用する。"},{"id":"4","text":"身元保証や死後の財産処分のために、高齢者等終身サポート事業を利用する。"},{"id":"5","text":"金銭管理のために、日常生活自立支援事業を利用する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！要支援の人は、介護予防住宅改修で、手すりの取り付けなど、自宅内での安全な移動を支える改修ができるんだ。1の夜間対応型訪問介護は要介護者向けのサービス。3の小規模多機能型居宅介護は、カラオケなど趣味の外出のためではないよ。4は、介護保険のサービスではないし、5の日常生活自立支援事業も、介護保険制度のサービスではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-008","examYear":"2026","examRound":"38","questionNumber":8,"category":"介護の基本","questionText":"Ａさん（91歳、女性、要支援2）は、長年診療所の医師として地域医療に貢献してきた。婚姻歴はなく、診療所敷地内の自宅で3匹の猫と暮らしている。85歳で医師を引退した後も、近隣にはＡさんを慕う地域住民が多く、定期的に、「先生、元気にしてますか」とＡさんの自宅を訪ねている。\nＡさんは昨年から歩行の不安を訴え、現在は地域住民の見守りのほか、訪問型サービスを週2回利用している。人の世話になることに慣れていない様子もあるが、最期まで自宅で暮らすことを望んでいる。\n次の記述のうち、Ａさんの生活史を尊重した訪問介護員（ホームヘルパー）の声かけとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「3匹の猫は、今後は地域の皆さんに預けましょう」"},{"id":"2","text":"「近所の方の力も借りて、この地域で暮らしていけるように考えていきましょう」"},{"id":"3","text":"「介護を受けることにも、今後は慣れてください」"},{"id":"4","text":"「医師であったことは忘れて、私たちを頼ってください」"},{"id":"5","text":"「一人暮らしで自宅で最期を迎えるのは、不安がありますよね」"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ａさんは、人の世話になることに慣れていないけれど、最期まで自宅で暮らしたいと望んでいるよね。地域の人に慕われてきた生活史を生かして、近所の力も借りながら暮らす方法を一緒に考えるのがぴったりだよ。1は猫との暮らしを奪い、3と4は、Ａさんの誇りを軽んじているんだ。5は、不安をあおってしまうから、避けたいね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-009","examYear":"2026","examRound":"38","questionNumber":9,"category":"介護の基本","questionText":"次の記述のうち、介護老人保健施設における在宅復帰に向けたカンファレンスで、介護福祉士が連携する職種の役割として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"歯科衛生士が、義歯を作成する。"},{"id":"2","text":"看護師が、車いすを貸与する。"},{"id":"3","text":"介護支援専門員（ケアマネジャー）が、訪問介護計画を作成する。"},{"id":"4","text":"福祉用具専門相談員が、下肢の機能訓練をする。"},{"id":"5","text":"作業療法士が、自宅の玄関の段差を確認する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！作業療法士は、日常生活に必要な動作の訓練や、自宅環境の確認、助言などを行う専門職なんだ。玄関の段差を確認するのは、その役割にあたるよ。1の義歯の作成は歯科医師、2の車いすの貸与は福祉用具貸与事業者の仕事だね。3の訪問介護計画はサービス提供責任者、4の福祉用具専門相談員は、機能訓練はしないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-010","examYear":"2026","examRound":"38","questionNumber":10,"category":"介護の基本","questionText":"次の記述のうち、介護老人福祉施設におけるリスクマネジメントとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"安全対策担当者を置き、事故発生予防のための委員会を定期的に開催する。"},{"id":"2","text":"家族からの苦情は、介護福祉職が、その場で解決する。"},{"id":"3","text":"利用者の私物を壊したときは、介護福祉職の自己判断で弁償する。"},{"id":"4","text":"入浴介助時のインシデントの報告は、職員間の口頭による伝達に統一する。"},{"id":"5","text":"事故防止のため、地域のお祭りへの参加は控える。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！リスクマネジメントでは、安全対策の担当者を置き、事故防止のための委員会を定期的に開いて、組織的に取り組むことが大切なんだ。2は、苦情は個人ではなく組織で対応するよ。3は、弁償は、施設の判断で行う。4は、インシデントの報告は記録に残すのが原則。5は、リスクを避けるために社会参加を制限するのは望ましくないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-011","examYear":"2026","examRound":"38","questionNumber":11,"category":"介護の基本","questionText":"次の記述のうち、介護現場におけるレジオネラ菌の感染対策として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"感染者の衣類は、熱湯で煮沸消毒する。"},{"id":"2","text":"提供する食品は、加熱調理を徹底する。"},{"id":"3","text":"循環式浴槽は、塩素系薬剤を使用して消毒する。"},{"id":"4","text":"ドアノブは、次亜塩素酸ナトリウム液で消毒する。"},{"id":"5","text":"家庭用加湿器のタンクの水は、常に貯めておく。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！レジオネラ菌は、循環式浴槽の湯や配管の中、加湿器などの水の中で増えやすいんだ。循環式浴槽は、塩素系薬剤で消毒するのが有効だよ。1と2は、レジオネラ属菌は人から人へうつらないので、ふさわしくない。4は、ドアノブの消毒は、接触感染の対策だね。5は、加湿器の水をためておくと、菌が増える原因になるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-012","examYear":"2026","examRound":"38","questionNumber":12,"category":"介護の基本","questionText":"介護福祉職が受けるストレスチェック制度に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"3年に1回の実施が義務づけられている。"},{"id":"2","text":"労働者数が常時100名の事業場は受検が免除される。"},{"id":"3","text":"結果は労務管理を行う介護主任へ提供され、面接指導に活用する。"},{"id":"4","text":"心理的な負担の程度を把握するためのものである。"},{"id":"5","text":"高ストレスと判定された場合は、産業医による治療が必須である。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ストレスチェック制度は、働く人の心理的な負担の程度を調べて、本人に気づいてもらい、メンタルヘルス不調を防ぐための制度なんだ。1は、年1回の実施が義務。2は、常時50人以上の事業場は実施が義務だよ。3は、結果は本人の同意なしに事業者に提供されないんだ。5は、高ストレスでも、医師の面接指導は本人が希望したときに行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-013","examYear":"2026","examRound":"38","questionNumber":13,"category":"社会の理解","questionText":"民法の親族に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"三親等内の血族を家族と規定している。"},{"id":"2","text":"六親等内の姻族を親族と規定している。"},{"id":"3","text":"いとこは互いに扶養する義務があると規定している。"},{"id":"4","text":"同居する親族は互いに扶｛たす｝け合わなければならないと規定している。"},{"id":"5","text":"養子と養親の間には、親族関係は生じない。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！民法には、直系血族と同居の親族は、互いに助け合わなければならないと定められているんだ。1は、家族についての規定はなく、親族は、6親等内の血族、配偶者、3親等内の姻族のことだね。2は、姻族は3親等まで。3は、いとこの間には、扶養の義務はないよ。5は、養子と養親の間には、法律上の親族関係が生じるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-014","examYear":"2026","examRound":"38","questionNumber":14,"category":"社会の理解","questionText":"次の記述のうち、「令和4（2022）年  国民生活基礎調査」（厚生労働省）における、高齢者に関する調査結果として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"65歳以上の者のいる世帯の世帯構造で最も多いのは、親と未婚の子のみの世帯である。"},{"id":"2","text":"高齢者世帯は5割以上を占めている。"},{"id":"3","text":"要介護者等と同居の主な介護者の年齢の組合せでは、65歳以上同士が約6割を占めている。"},{"id":"4","text":"介護が必要となった理由の第1位は、骨折・転倒である。"},{"id":"5","text":"1世帯当たりの平均所得金額では、高齢者世帯では600万円を超えている。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！令和4年の国民生活基礎調査では、要介護者等と同居の主な介護者の年齢の組合せで、65歳以上同士が約6割を占めているんだ。1は、65歳以上の者のいる世帯では、夫婦のみの世帯がいちばん多いよ。2は、高齢者世帯は約3割。4は、介護が必要になった理由の第1位は、認知症だね。5は、高齢者世帯の平均所得は300万円台だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-015","examYear":"2026","examRound":"38","questionNumber":15,"category":"社会の理解","questionText":"Ａさん（78歳、女性）は、一人暮らしである。家事や買物は、時間はかかるが、できるだけ自分で取り組んでいる。近くに頼れる親族がいないため、緊急時にすぐに通報できる公共サービスを利用している。Ａさんは、定期的に市の窓口や地域包括支援センターに今後の生活支援について相談している。近所には、毎日散歩を一緒にしている友人グループがいて、散歩に来ない仲間がいると訪問して声をかけあっている。\n次のうち、Ａさんの生活を支える自助に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ａさんが身辺のことを、時間をかけてもやること"},{"id":"2","text":"緊急時にすぐに通報できる公共サービスを利用していること"},{"id":"3","text":"市の窓口の職員が相談に応じること"},{"id":"4","text":"地域包括支援センターの職員が相談に応じること"},{"id":"5","text":"散歩仲間が声をかけあっていること"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！自助は、自分自身で行う努力のこと。Ａさんが身辺のことを、時間をかけても自分でやるのは、自助にあたるんだ。2の公共サービスと、3と4の相談窓口は、公助（公的な支援）。5の散歩仲間の声かけは、互助（地域の人同士の助け合い）だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-016","examYear":"2026","examRound":"38","questionNumber":16,"category":"社会の理解","questionText":"介護保険制度における介護サービス利用に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"65歳未満の者は、保険給付の対象外である。"},{"id":"2","text":"保険給付には、支給限度額がある。"},{"id":"3","text":"要介護認定の有効期限は、原則として3か月である。"},{"id":"4","text":"保険給付による福祉用具の貸与は、要介護3以上の者が対象である。"},{"id":"5","text":"地域包括支援センターに相談する前に、要介護認定を受ける必要がある。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護保険の保険給付には、要介護度ごとに、サービスの利用の上限である支給限度額があるんだ。1は、65歳未満でも、特定疾病で要介護認定を受ければ、給付の対象。3は、有効期間は原則6か月以上（新規は原則6か月）。4は、福祉用具の貸与は、要支援や要介護1でも、一部の品目は対象だよ。5は、相談は認定の前でもできるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-017","examYear":"2026","examRound":"38","questionNumber":17,"category":"社会の理解","questionText":"次の記述のうち、障害者福祉の歴史的展開として、最も適切なものを1つ選びなさい。\n（注）  「精神薄弱者福祉法」とは、現在の知的障害者福祉法のことである。","choices":[{"id":"1","text":"国際連合の障害者の権利に関する条約の影響を受け、障害者基本法に「社会的障壁の除去」が規定された。"},{"id":"2","text":"第二次世界大戦後5年以内に、優生保護法が廃止された。"},{"id":"3","text":"「精神薄弱者福祉法」の制定によって、知的障害者の入所施設からの地域移行が推進された。"},{"id":"4","text":"社会福祉基礎構造改革によって、高齢者より先に障害者の福祉制度が利用契約制度となった。"},{"id":"5","text":"身体障害、知的障害、精神障害のうち、福祉に関する法律の制定が最も早かったのは知的障害である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！障害者権利条約の批准に向けた国内法の整備の中で、障害者基本法が改正され、「社会的障壁の除去」が規定されたんだ。2は、優生保護法が廃止されたのは、1996年。3は、精神薄弱者福祉法が制定されたのは1960年で、まだ入所施設が中心だったよ。4は、利用契約制度は、高齢者（介護保険）のほうが先。5は、知的障害の法律は身体障害より遅いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-018","examYear":"2026","examRound":"38","questionNumber":18,"category":"社会の理解","questionText":"次の記述のうち、障害者福祉に関係する機関やシステムとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"地域活動支援センターは、補装具の判定を行う。"},{"id":"2","text":"基幹相談支援センターには、介護福祉士の配置が義務となっている。"},{"id":"3","text":"都道府県は、身体障害者更生相談所を設置しなければならない。"},{"id":"4","text":"都道府県は、障害支援区分の認定を行う。"},{"id":"5","text":"利用者負担の額は、市町村障害福祉計画によって決められる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！身体障害者更生相談所は、身体障害者福祉法にもとづいて、都道府県に設置が義務づけられているんだ。1は、補装具の判定は、更生相談所などが行う。2は、基幹相談支援センターに介護福祉士の配置義務はないよ。4は、障害支援区分の認定は市町村。5は、利用者負担の額は、政令などで決まっているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-019","examYear":"2026","examRound":"38","questionNumber":19,"category":"社会の理解","questionText":"障害者虐待防止に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"養護者による虐待が疑われる障害者を発見した場合、都道府県へ通報する義務がある。"},{"id":"2","text":"著しく拒絶的な対応は身体的虐待に当てはまる。"},{"id":"3","text":"使用者による障害者虐待は含まれない。"},{"id":"4","text":"行政職員が障害者福祉施設等に、立ち入り調査を行うことは許されていない。"},{"id":"5","text":"虐待を発見した障害者福祉施設従事者が通報した場合、業務上の守秘義務違反にはならない。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害者福祉施設の従事者が、虐待を通報しても、守秘義務違反にはならないんだ。通報した人が不利益な扱いを受けないよう、守られているよ。1は、養護者による虐待の通報先は、市町村。2は、著しい拒絶的な対応は、ネグレクトなどの心理的虐待にあたる。3は、使用者による虐待も含まれるんだ。4は、行政職員の立ち入り調査も認められているよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-020","examYear":"2026","examRound":"38","questionNumber":20,"category":"社会の理解","questionText":"Ａさん（82歳、女性、要介護1）は、自宅で一人暮らしをしている。外出機会が少ないＡさんを心配して、民生委員が定期的に見守りを行っている。ある日、民生委員から地域包括支援センターに、「Ａさんのように、家に閉じこもりがちな要介護者が増えている。民生委員だけでは十分な見守りができない」と相談があった。\n次の記述のうち、地域包括支援センターの職員の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高齢者本人による相談が原則のため、Ａさん自身が相談に来るように促す。"},{"id":"2","text":"介護サービスを利用するため、Ａさんのケアプランを作成する。"},{"id":"3","text":"フォーマルな社会資源の活用を優先し、民生委員のかかわりを制限する。"},{"id":"4","text":"地域ケア会議において、関係者と地域課題について話し合う。"},{"id":"5","text":"要介護者の実態を把握するために、介護保険審査会を設置する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！民生委員だけでは見守りが十分でないという、地域全体の課題は、地域ケア会議で、関係者と話し合って解決していくのが、地域包括支援センターの役割なんだ。1は、本人が来るのを待たなくても、相談は受けつけるよ。2のケアプランは、Ａさんは要介護1で、居宅介護支援事業所の担当。3は、民生委員の力も活用するよ。5の介護保険審査会は、都道府県が設置するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-021","examYear":"2026","examRound":"38","questionNumber":21,"category":"社会の理解","questionText":"法定後見制度に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"65歳未満の者は利用することができない。"},{"id":"2","text":"判断能力が十分ある者には、後見人をつけることができない。"},{"id":"3","text":"市町村長は、後見開始の審判を請求することができない。"},{"id":"4","text":"法人を後見人に選任することはできない。"},{"id":"5","text":"後見人は財産管理を行うことはできない。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！法定後見制度は、判断能力が不十分になった人を支える制度だから、判断能力が十分ある人には、後見人をつけられないんだ。1は、年齢の制限はないよ。3は、市町村長も申立てができる。4は、法人も後見人になれる（法人後見）。5は、後見人は財産管理を行うのが主な役割だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-022","examYear":"2026","examRound":"38","questionNumber":22,"category":"社会の理解","questionText":"有料老人ホームに関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"入居する高齢者に、介護、食事の提供、家事、健康管理のうち1つ以上のサービスを提供する。"},{"id":"2","text":"状況把握サービスと生活相談サービスの提供が義務づけられている。"},{"id":"3","text":"自立した高齢者は、入居の対象外である。"},{"id":"4","text":"共生型サービスとして、指定を受けることができる。"},{"id":"5","text":"介護保険制度の指定対象外である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！有料老人ホームは、高齢者を入居させて、介護、食事の提供、家事、健康管理のうち、いずれか1つ以上のサービスを提供する施設なんだ。2は、状況把握と生活相談が義務なのは、サービス付き高齢者向け住宅だよ。3は、自立した高齢者も入居できる。4は、共生型サービスの対象ではない。5は、介護付き有料老人ホームは、介護保険の特定施設入居者生活介護の指定を受けられるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-023","examYear":"2026","examRound":"38","questionNumber":23,"category":"社会の理解","questionText":"生活困窮者自立支援法に関する記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害者は対象から除外されている。"},{"id":"2","text":"生活困窮者自立相談支援事業は、社会福祉法人へ委託できない。"},{"id":"3","text":"生活困窮者自立相談支援事業は、市にとって任意事業である。"},{"id":"4","text":"生活困窮者住居確保給付金の支給は、市にとって必須事業である。"},{"id":"5","text":"都道府県の責務は規定されていない。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！生活困窮者住居確保給付金の支給は、自治体（市など）にとって、実施が義務の必須事業なんだ。1は、障害者も対象になるよ。2は、自立相談支援事業は、社会福祉法人などに委託できる。3は、自立相談支援事業も必須事業だよ。5は、都道府県の責務も規定されているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-024","examYear":"2026","examRound":"38","questionNumber":24,"category":"社会の理解","questionText":"次の記述のうち、生活保護制度における補足性の原理として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"申請に基づいて保護を行う。"},{"id":"2","text":"国の定める基準によって測定された需要をもとに保護を行う。"},{"id":"3","text":"個人の必要に応じてできるだけ早く保護を行う。"},{"id":"4","text":"資産・能力を活用した上で保護を行う。"},{"id":"5","text":"世帯を単位として保護を行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！補足性の原理は、資産や能力などを活用したうえで、それでも足りない部分を、保護で補うという考え方なんだ。1は申請保護の原則、2は基準及び程度の原則、3は必要即応の原則、5は世帯単位の原則だよ。生活保護の4つの原理と4つの原則は、セットで覚えよう。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-025","examYear":"2026","examRound":"38","questionNumber":25,"category":"人間関係とコミュニケーション","questionText":"新人職員のＡさん（20歳）は、子どもの頃からの夢だった介護福祉職になり、がんばって働いていた。ただ、介護の技術をもっと学ぶ必要があるといつも感じていた。ある日、利用者Ｂさんに、「Ａさんじゃダメだ、別の人を呼んで」と言われて、ショックを受けた。悩むうちに利用者とかかわりたくないと感じるようになり、眠れなくなってしまった。\n次の記述のうち、このような状況にあるＡさんが、ストレスを取り除くためにまず行うべき対処方法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"つらさから逃げず、学びが足りないことを自覚する。"},{"id":"2","text":"介護の技術がうまくなるために、全力で取り組む。"},{"id":"3","text":"眠れるように、毎晩飲酒する。"},{"id":"4","text":"上司や同僚などに悩みを話して、助言を受ける。"},{"id":"5","text":"介護福祉職には向かないと判断して、転職する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ストレスを感じたときは、ひとりで抱え込まず、上司や同僚に悩みを話して、助言を受けることが、まず行うべき対処なんだ。1は自分を責めるだけで、2はさらに追い詰めてしまうよ。3の飲酒は、睡眠の質を下げる。5は、まだ判断するのが早すぎるね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-026","examYear":"2026","examRound":"38","questionNumber":26,"category":"人間関係とコミュニケーション","questionText":"Ａさんは有料老人ホームに入所したばかりである。ある日、廊下を行ったり来たりしているＡさんに、Ｂ介護福祉職が声をかけた。Ａさんは、「私の部屋はどこですか」と困った様子で答えた。Ｂ介護福祉職が、「ここから2つ隣の部屋です」と伝えると、Ａさんは、「どこですか」と不安そうな表情で聞いた。Ｂ介護福祉職は非言語的コミュニケーションを用いて伝えることにした。\n次の記述のうち、Ｂ介護福祉職が用いた非言語的コミュニケーションとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ゆっくり話した。"},{"id":"2","text":"大きな声で伝えた。"},{"id":"3","text":"Ａさんの部屋の番号を紙に書いて渡した。"},{"id":"4","text":"Ａさんに近づいた。"},{"id":"5","text":"Ａさんの部屋のドアを指差した。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！非言語的コミュニケーションは、言葉以外の表情、しぐさ、視線、距離などで伝える方法なんだ。部屋のドアを指差すのは、しぐさで伝える方法だね。1のゆっくり話すことと、2の大きな声は、言語的コミュニケーションの工夫。3の紙に書くのは、文字を使うので言語的だよ。4の近づく行動は、距離を使うけれど、部屋の場所を伝えることにはつながらないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-027","examYear":"2026","examRound":"38","questionNumber":27,"category":"人間関係とコミュニケーション","questionText":"次のうち、介護福祉施設におけるコンプライアンスの意味として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"法令を遵守すること"},{"id":"2","text":"給与を引き上げること"},{"id":"3","text":"連携を促進すること"},{"id":"4","text":"介護技術の向上に努めること"},{"id":"5","text":"管理体制を強化すること"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！コンプライアンスは、「法令遵守」のこと。法律やルール、社会的なきまりを守ることで、施設が信頼される運営につながるんだ。2は給与、3は連携、4は介護技術の向上、5は管理体制の強化のことで、コンプライアンスの意味とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-028","examYear":"2026","examRound":"38","questionNumber":28,"category":"人間関係とコミュニケーション","questionText":"入社して3か月のＡ介護福祉職は、初めて夜勤を経験したとき、排泄｛はいせつ｝チェック表の記入でミスをしてしまった。起床介助で忙しい時間に記入したために、記載箇所を間違えてしまった。Ａ介護福祉職は自身のミスを受け入れられず、落ち込んでいる。\n次の記述のうち、Ａ介護福祉職に対する支持的スーパービジョンとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"同僚と一緒に排泄｛はいせつ｝チェック表を確認する。"},{"id":"2","text":"施設長から再発防止に向けた対応を指示する。"},{"id":"3","text":"上司がＡ介護福祉職の気持ちの理解に努めつつ、状況を確認する。"},{"id":"4","text":"看護師が利用者のその後の状況を確認する。"},{"id":"5","text":"業務マニュアルを見直して、上司が必要な修正を行う。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！支持的スーパービジョンは、スーパーバイジーの気持ちを受け止めて、心理的に支える関わりなんだ。上司が気持ちの理解に努めながら状況を確認するのが、それにあたるよ。1は教育的、2、5は管理的な要素が強くて、4は利用者の状況の確認で、気持ちを支える関わりではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-029","examYear":"2026","examRound":"38","questionNumber":29,"category":"コミュニケーション技術","questionText":"次のうち、利用者とのコミュニケーション場面で、介護福祉職が行う自己開示の目的として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自己の潜在意識を活用するため"},{"id":"2","text":"利用者との信頼関係を評価するため"},{"id":"3","text":"利用者に自分自身の情報を知らせるため"},{"id":"4","text":"利用者との信頼関係を形成するため"},{"id":"5","text":"自己を深く分析し、客観的に理解するため"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！自己開示は、自分の考えや経験、気持ちなどを、相手に話すことで、相手との距離を縮め、信頼関係を築くために行うんだ。1の潜在意識の活用や、2の信頼関係の評価は、自己開示の目的ではないよ。3は、情報を知らせるだけでは目的として不十分。5は、自己覚知の説明だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-030","examYear":"2026","examRound":"38","questionNumber":30,"category":"コミュニケーション技術","questionText":"Ａ介護福祉職は、認知症（dementia）のあるＢさん（80歳、女性）と会話をしている。Ｂさんは、「私は小さい頃毎年お祭りに行くことが楽しみでね」「なんだか最近ひざが痛いような気がしてね」「今から何をしようかしらね」と、次々に話している。Ａ介護福祉職は、Ｂさんが混乱しないように、「Ｂさん、子どもの頃の思い出や体調のことをお話しくださっているのですね」と返答した。\n次のうち、Ａ介護福祉職が行ったコミュニケーション技術として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"要約"},{"id":"2","text":"承認"},{"id":"3","text":"賞賛"},{"id":"4","text":"共感"},{"id":"5","text":"同意"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ａ介護福祉職は、Ｂさんが話した、子どもの頃の思い出や、体調のことを、まとめて返しているよね。これは、要約というコミュニケーション技術なんだ。2の承認は相手の存在や行動を認める、3の賞賛はほめる、4の共感は相手の気持ちに寄り添う、5の同意は相手の意見に賛成することで、ここでは行っていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-031","examYear":"2026","examRound":"38","questionNumber":31,"category":"コミュニケーション技術","questionText":"次の記述のうち、利用者の家族との関係づくりにおける介護福祉職の基本姿勢として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"お互いの緊張が解けるまでじっと待つ。"},{"id":"2","text":"介護福祉職のペースで話を進める。"},{"id":"3","text":"利用者の意向よりも家族の意向を優先する。"},{"id":"4","text":"家族への連絡は最小限にする。"},{"id":"5","text":"利用者支援で協働するパートナーとして接する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！家族は、利用者を一緒に支えるパートナーなんだ。だから、協力して支援していく姿勢で接することが大切だよ。1は、待つだけでは関係が進まない。2は、介護福祉職の都合で進めてはダメ。3は、利用者の意向を第一に考える。4は、連絡を減らすと、信頼関係が築きにくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-032","examYear":"2026","examRound":"38","questionNumber":32,"category":"コミュニケーション技術","questionText":"Ａさん（80歳、女性、要介護3）は中途障害の全盲である。介護老人福祉施設に入所している。最近、食堂の席の入れ替えがあった。Ａさんは同じテーブルの利用者同士の会話を、自分に向けて話しかけられていると思って、応答した。しかし、誰からも反応はなく、Ａさんは下を向いてしまった。その様子を見たＢ介護福祉職は、Ａさんの状況に対応するために、同じテーブルの利用者にＡさんの事情を話し、協力を求めた。\n次の記述のうち、Ｂ介護福祉職が同じテーブルの利用者に協力を依頼した内容として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ａさんは疲れているので、部屋で休むように伝えてほしい。"},{"id":"2","text":"Ａさんは不安なので、そっと手を握ってほしい。"},{"id":"3","text":"Ａさんにもわかるように、話す相手の名前を呼んでから話しかけてほしい。"},{"id":"4","text":"Ａさんが混乱するので、食堂での会話は控えてほしい。"},{"id":"5","text":"Ａさんは施設の予定がわからないので、これから食事だと教えてほしい。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！全盲のＡさんは、自分に向けた話かどうかを、視覚で判断できないんだね。話しかけるときに、相手の名前を呼んでからにしてもらえば、Ａさんにも、だれに話しているのかがわかるよ。1、2、4、5は、Ａさんの状況に合わないうえに、Ａさんの参加の機会を奪ってしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-033","examYear":"2026","examRound":"38","questionNumber":33,"category":"コミュニケーション技術","questionText":"Ａさん（72歳、男性）は記憶障害があり、介護施設に入居している。ある日、介護福祉職にＡさんが、「あの、ちょっとお願いがあるんです。ええとね、実は、お昼ご飯をほとんど残しちゃいました…。それでね…、あ、あれかな、調理師さんはがっかりしたかな、私はずっと食堂をやっていたんですよ。店はけっこう繁盛していたけど閉めることになってね。あ、ええと何の話だったかな…」と話しかけてきた。\n次のうち、このときのＡさんの発言を促すための介護福祉職の応答として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「Ａさんは、お店を閉めたくなかったのですね」"},{"id":"2","text":"「Ａさんは、どんな料理が得意だったのですか」"},{"id":"3","text":"「調理師さんのことは気にしなくていいですよ」"},{"id":"4","text":"「どこかからだの具合が悪いのではないですか」"},{"id":"5","text":"「何かお願いがあるのではありませんか」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、「お願いがあるんです」と言って話し始めたけれど、話がそれて、何を言おうとしていたのか忘れてしまったんだね。だから、「何かお願いがあるのではありませんか」と、本題に戻る手助けをして、発言を促すのがよいよ。1、2は思い出の話に広げてしまうし、3は打ち消していて、4は決めつけているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-034","examYear":"2026","examRound":"38","questionNumber":34,"category":"コミュニケーション技術","questionText":"次の記述のうち、客観的事実に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者Ａは、楽しかったはずだ。"},{"id":"2","text":"利用者Ａは、朝食のパンを残した。"},{"id":"3","text":"利用者Ａは、何か言いたそうだった。"},{"id":"4","text":"利用者Ａは、不安だったと思う。"},{"id":"5","text":"利用者Ａは、退屈そうにしていた。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！客観的事実は、実際に見たり聞いたりした、確かなことがらなんだ。「朝食のパンを残した」は、観察したままの事実だね。1、3、4、5は、「はずだ」「そうだった」「思う」など、記録する人の推測や解釈が入っているから、客観的事実とはいえないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-035","examYear":"2026","examRound":"38","questionNumber":35,"category":"生活支援技術","questionText":"次の記述のうち、介護福祉職が行う利用者の生活支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者ができないことを代わりに行うことに重点を置く。"},{"id":"2","text":"利用者の全体像をとらえて支援する。"},{"id":"3","text":"利用者がすべてを自分一人でできるようにする。"},{"id":"4","text":"利用者の生活の効率化を図ることを目標にする。"},{"id":"5","text":"利用者に同情する気持ちで寄り添う。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護福祉職の生活支援では、身体面だけでなく、心理面や社会面も含めて、利用者の全体像をとらえて支援するんだ。1は、代わりに行うだけでなく、できることを生かす。3は、すべて一人でできることが目的ではないよ。4は、効率化より、その人らしさが大切。5は、同情ではなく、理解と共感で寄り添うんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-036","examYear":"2026","examRound":"38","questionNumber":36,"category":"生活支援技術","questionText":"介護老人福祉施設における、快適な室内環境に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"風の通り道をつくって、換気を行う。"},{"id":"2","text":"手すりは、壁紙と同じ色を使う。"},{"id":"3","text":"ベッドライトの光源は、利用者の目に直接あたるように調整する。"},{"id":"4","text":"カビの発生を予防するために、湿度は高く保つ。"},{"id":"5","text":"靴音を小さくするために、硬い床材にする。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！風の通り道をつくって換気をすると、空気が入れ替わって、においやこもった熱を防げて、快適な室内環境になるんだ。2は、手すりは壁と色を変えて、見つけやすくする。3は、光源が直接目に入らないようにする。4は、湿度が高いとカビが生えやすいよ。5は、硬い床材は靴音が響くので、吸音性のある床材がよいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-037","examYear":"2026","examRound":"38","questionNumber":37,"category":"生活支援技術","questionText":"パーキンソン病（Parkinson disease）の人の住まいに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"玄関の段差には、スロープを設置する。"},{"id":"2","text":"廊下の床には、歩幅に合わせて目印をつける。"},{"id":"3","text":"リビングの床には、大きさの違うカーペットを重ねて敷く。"},{"id":"4","text":"移動空間が狭くなるように、家具を配置する。"},{"id":"5","text":"リビングは1階、浴室は2階にして、階段で行き来する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！パーキンソン病の人は、歩き出しの一歩が出にくくなる「すくみ足」が起こることがあるんだ。廊下の床に、歩幅に合わせて目印をつけると、それをまたぐようにして足を出しやすくなるよ。1のスロープは、傾斜の勢いで転びやすいことも。3は、段差で転倒しやすく、4は、移動空間を広くする。5は、階段の上り下りは転倒の危険があるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-038","examYear":"2026","examRound":"38","questionNumber":38,"category":"生活支援技術","questionText":"次の記述のうち、歩行が不安定になり、移動の意欲が低下している利用者に対する介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"福祉用具の使用は避けて、自力での歩行を目指すように促す。"},{"id":"2","text":"移動の目的を伝えるよりも、歩行機能の改善を優先する。"},{"id":"3","text":"成功体験を積み重ねることができるように、達成可能な歩行の目標距離を設定する。"},{"id":"4","text":"歩行の不安定さに合わせて、移動範囲を縮小する。"},{"id":"5","text":"本人が希望しなくても、介護福祉職の判断で毎日歩くことを目標にする。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！移動の意欲が下がっている人には、達成できそうな目標を立てて、成功体験を積み重ねることで、自信と意欲を引き出せるんだ。1は、福祉用具は上手に使うほうがよい。2は、移動の目的を伝えることも大切。4は、範囲を縮めると、意欲がさらに落ちる。5は、本人の希望を無視してはダメなんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-039","examYear":"2026","examRound":"38","questionNumber":39,"category":"生活支援技術","questionText":"次の記述のうち、右片麻痺｛みぎかたまひ｝のある利用者に対する、仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）から車いすへの移乗の介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者に右側臥位｛みぎそくがい｝になって起き上がるように促す。"},{"id":"2","text":"端座位になった利用者の左側に立つ。"},{"id":"3","text":"端座位になった利用者の右側に、車いすを置く。"},{"id":"4","text":"車いすのフットサポートは下げておく。"},{"id":"5","text":"移乗するときは、利用者に前傾姿勢をとるように促す。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！移乗するときは、前傾姿勢になってもらうと、お尻が上がって立ち上がりやすくなるんだ。1は、右片麻痺なので、健側の左側臥位になって起き上がるよ。2は、介助するのは、麻痺のある右側に立つ。3は、車いすは健側の左側に置く。4は、移乗するときは、フットサポートを上げておくんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-040","examYear":"2026","examRound":"38","questionNumber":40,"category":"生活支援技術","questionText":"視覚障害者の歩行時の誘導に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職は、利用者の半歩後ろで背中を支えながら歩く。"},{"id":"2","text":"介護福祉職は、白杖｛はくじょう｝に触れながら歩く。"},{"id":"3","text":"狭い通路では、介護福祉職は利用者の後ろを歩く。"},{"id":"4","text":"階段利用時は、介護福祉職は階段の前で声かけして止まる。"},{"id":"5","text":"介護福祉職は、利用者が握っている上肢を振って歩く。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！階段では、上りか下りかを伝えて、階段の前で一度止まってから、声をかけるんだ。これで、利用者が心の準備をして、安全に歩けるよ。1は、半歩前で、利用者に腕や肩をもってもらう。2は、白杖には触らない。3は、狭い通路では、介護福祉職が前に出る。5は、腕は振らずに、固定して歩くんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-041","examYear":"2026","examRound":"38","questionNumber":41,"category":"生活支援技術","questionText":"身じたくの目的に関する次の記述のうち、国際生活機能分類（ＩＣＦ）における「心身機能・身体構造」の観点が考えられるものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"体温を調整する。"},{"id":"2","text":"身体を清潔に保つ。"},{"id":"3","text":"セルフケアを行う。"},{"id":"4","text":"自分を表現する。"},{"id":"5","text":"周囲との人間関係を調整する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ICFの「心身機能・身体構造」は、体の働きや構造のことなんだ。体温の調整は、まさに体の働きだね。2は、清潔は活動、3のセルフケアも活動、4の自己表現は活動や参加、5の周囲との人間関係の調整は参加にあたるよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-042","examYear":"2026","examRound":"38","questionNumber":42,"category":"生活支援技術","questionText":"次の記述のうち、介護が必要な利用者への口腔｛こうくう｝ケアとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）で行う。"},{"id":"2","text":"歯垢｛しこう｝を除去するためにうがいをしてもらう。"},{"id":"3","text":"歯ブラシで歯を1、2本ずつ磨く。"},{"id":"4","text":"スポンジブラシは乾いた状態で使用する。"},{"id":"5","text":"部分床義歯（局部床義歯）はつけたまま行う。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！口腔ケアで歯ブラシを使うときは、歯を1、2本ずつ、小刻みに動かして、丁寧に磨くんだ。1は、仰臥位は誤嚥しやすいので、座位や側臥位で行う。2は、歯垢を取るのは、うがいではなくブラッシング。4は、スポンジブラシは、湿らせて使う。5は、部分床義歯は外して、洗ってから使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-043","examYear":"2026","examRound":"38","questionNumber":43,"category":"生活支援技術","questionText":"次のうち、右片麻痺｛みぎかたまひ｝の利用者が前開きの上着を着脱するときに介護福祉職が行う説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「脱ぐときは、左肩の衣服を下げてから、右側の袖から腕を抜きましょう」"},{"id":"2","text":"「脱ぐときは、右肩の衣服を下げてから、右側の袖から腕を抜きましょう」"},{"id":"3","text":"「襟元を手前にして、腿｛もも｝の上に置きましょう」"},{"id":"4","text":"「着るときは、右袖を肘まで通してから、左袖を通しましょう」"},{"id":"5","text":"「着るときは、右袖を肩まで通してから、左袖を通しましょう」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！着るときは、麻痺のある患側の袖を先に、肩まで通してから、健側の袖を通すんだ（脱健着患）。1と2は、脱ぐときは、健側から先に脱ぐので、右片麻痺なら左側からだよ。3は、襟元の扱いが逆になる。4は、肘まででは足りず、肩まで通さないと、健側の袖が通しにくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-044","examYear":"2026","examRound":"38","questionNumber":44,"category":"生活支援技術","questionText":"次の記述のうち、介護老人福祉施設における食事に関する支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食堂の換気は、不要である。"},{"id":"2","text":"食事中は、会話を控えるようにする。"},{"id":"3","text":"食事が楽しくなるような雰囲気をつくる。"},{"id":"4","text":"食べ終わった利用者の食器は、すぐに下膳する。"},{"id":"5","text":"照明は、明るさを25ルクス（lx）以下にする。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！食事は、栄養をとるだけでなく、楽しみでもあるんだ。食事が楽しくなるような雰囲気づくりが大切だよ。1は、食堂の換気は必要。2は、会話を楽しんでもよい。4は、すぐに下げると、ゆっくり食べている人が急かされるね。5は、25ルクスでは暗すぎて、食事が見えづらいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-045","examYear":"2026","examRound":"38","questionNumber":45,"category":"生活支援技術","questionText":"次の記述のうち、椅子に座って食事をするときに、利用者が食事をしやすい姿勢を確保するための介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"足底を床につけてもらう。"},{"id":"2","text":"テーブルと身体の間は30cm離してもらう。"},{"id":"3","text":"椅子に浅く座ってもらう。"},{"id":"4","text":"体幹を後方に傾けてもらう。"},{"id":"5","text":"顎を上げてもらう。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！足底を床につけると、姿勢が安定して、食べ物を口に運びやすくなり、誤嚥の予防にもなるんだ。2は、テーブルとの間は、こぶし1個分くらい。3は、深く座る。4は、体幹は少し前傾する。5は、顎を上げると誤嚥しやすいので、軽く引くんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-046","examYear":"2026","examRound":"38","questionNumber":46,"category":"生活支援技術","questionText":"咀嚼機能｛そしゃくきのう｝が低下した利用者の食事介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"大きめのスプーンで吸い込むように食べてもらう。"},{"id":"2","text":"一口量は、ティースプーンに軽く一杯を目安にする。"},{"id":"3","text":"食べる順番は、介護福祉職の判断で行う。"},{"id":"4","text":"スプーンは、舌の奥にのせるように入れる。"},{"id":"5","text":"咀嚼｛そしゃく｝が始まったら、すぐに次の食べ物を口に入れる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！咀嚼機能が低下した人には、一口量を少なめ（ティースプーン1杯程度）にして、ゆっくり食べてもらうと、むせや誤嚥を防げるんだ。1は、大きいスプーンは1回量が多くなる。3は、本人の好みや状態に合わせる。4は、舌の中央に入れる。5は、飲み込むのを確認してから次を口に入れるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-047","examYear":"2026","examRound":"38","questionNumber":47,"category":"生活支援技術","questionText":"Ａさん（80歳、女性、要介護3）は、介護老人福祉施設で生活している。食事は見守りのもとでほぼ自力で摂取しているが、嚥下機能｛えんげきのう｝は低下してきている。医師からは、食事摂取に配慮するように指導されている。ある日の昼食中、Ａさんは食事を1/3ほど食べたところで箸を止め、表情がこわばり、呼吸もやや浅くなった。\n次の記述のうち、介護福祉職が医療職に報告すると同時に、最初に行う対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"血圧を測定する。"},{"id":"2","text":"口腔｛こうくう｝の状況を観察する。"},{"id":"3","text":"口すぼめ呼吸を促す。"},{"id":"4","text":"その場で仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）になってもらう。"},{"id":"5","text":"すぐに薬を服用してもらう。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！食事の途中で、表情がこわばって、呼吸が浅くなったのは、誤嚥や窒息の可能性があるサインなんだ。医療職に報告すると同時に、まず口の中に食べ物が残っていないかなど、口腔の状況を観察するよ。1は、血圧測定は急ぎではない。3は、口すぼめ呼吸は、COPDの人の呼吸法。4は、仰臥位は危険。5は、服薬は医療職の指示が必要だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-048","examYear":"2026","examRound":"38","questionNumber":48,"category":"生活支援技術","questionText":"ベッド上で行う陰部洗浄に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"滅菌手袋を使用して行う。"},{"id":"2","text":"上半身はベッドの手前端に移動する。"},{"id":"3","text":"バスタオルで両下肢を包む。"},{"id":"4","text":"洗浄する時は、43℃のお湯を用いる。"},{"id":"5","text":"終了後は、蒸しタオルで水分を拭き取る。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！陰部洗浄では、バスタオルで両下肢を包むと、保温になり、露出を防いで、羞恥心にも配慮できるんだ。1は、滅菌手袋ではなく、使い捨て手袋でよい。2は、ベッドの中央に移動して行う。4は、お湯は38℃程度。5は、水分は、乾いたタオルなどでおさえ拭きするんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-049","examYear":"2026","examRound":"38","questionNumber":49,"category":"生活支援技術","questionText":"この問題は視覚素材問題です。選択肢１から５まで、図で示されている。\n腹部の清拭の方法を図に示す。矢印は拭く方向を表している。次のうち、基本的な清拭の方法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"腹の上部右側から腹の左側斜め下に、そのあとは腹の右側斜め下に、そのあとは腹の左側斜め下、そのあとは腹の右側斜め下に拭く。"},{"id":"2","text":"腹の上部真ん中、から、時計回りの円を描くように、へその上から恥骨部に、そのあとはへその上に、そのあとは恥骨部にと、拭く。"},{"id":"3","text":"腹の上部右側から恥骨部に向けて左斜め下に、その後は腹の上部左斜め上に、その後は腹の下部左斜め下に、その後は腹の上部左斜め上に拭く。"},{"id":"4","text":"腹の上部真ん中から、反時計回りの円を描くように、へその上から恥骨部に、その後はへその上に、その後は恥骨部にと、拭く。"},{"id":"5","text":"腹の下部左側から腹の右側斜め上に、その後は腹の左側斜め上に、その後は腹の右側斜め上に、その後は腹の左斜め上に拭く。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！腹部の清拭は、大腸の走行に沿って、「の」の字を描くように、時計回りで円を描いて拭くのが基本なんだ。これは、腸の動きを助けるためだよ。反時計回りの4や、往復して拭く1、3、5は、基本とは異なるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-050","examYear":"2026","examRound":"38","questionNumber":50,"category":"生活支援技術","questionText":"Ａさん（55歳、男性、会社員）は、20歳のときに交通事故で第5頚髄｛けいずい｝（C5）を損傷した。現在、電動車いすを利用し、自宅で自立した生活を送っている。身体状況は安定しているが、ときどき仙骨部に褥瘡｛じょくそう｝ができることがある。入浴は、居宅介護（ホームヘルプサービス）を利用していて、訪問介護員（ホームヘルパー）が福祉用具を用いて入浴介護をしている。\n次のうち、Ａさんが入浴時に使用している福祉用具として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"移乗台"},{"id":"2","text":"バスボード"},{"id":"3","text":"入浴用リフト"},{"id":"4","text":"浴槽用手すり"},{"id":"5","text":"滑り止めマット"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！第5頸髄（C5）を損傷すると、上肢の運動が限られるため、自力で浴槽に出入りするのは難しく、入浴用リフトを使って介助するのがよいんだ。1の移乗台やバスボードは、上肢の力が残っている人向け。4の手すりや5の滑り止めマットだけでは、安全に入浴できないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-051","examYear":"2026","examRound":"38","questionNumber":51,"category":"生活支援技術","questionText":"Ａさん（85歳、男性、要介護3）は、アルツハイマー型認知症（dementia of the Alzheimer’s type）と診断され、認知症対応型共同生活介護（認知症高齢者グループホーム）で生活をしている。入所時、Ａさんは、尿意や便意はあり、自分でトイレに行って排泄｛はいせつ｝できていた。最近、認知機能の低下によって、トイレ以外の場所で排泄｛はいせつ｝するようになった。\n次の記述のうち、Ａさんの状態に合わせた介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"骨盤底筋訓練を行う。"},{"id":"2","text":"紙おむつを使用する。"},{"id":"3","text":"一日の水分摂取量を減らす。"},{"id":"4","text":"ほかの利用者と同じ時間にトイレへ誘導する。"},{"id":"5","text":"トイレの出入口に「トイレ」と書いた紙を貼る。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、尿意や便意はあるけれど、トイレの場所がわからなくなっているんだね。トイレの出入口に「トイレ」と書いた紙を貼ると、場所がわかりやすくなるよ。1は、尿意や便意はあるので、必要ない。2は、いきなりおむつにするのは、自立を妨げる。3は、水分を減らすのは危険。4は、Ａさんに合った時間で誘導するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-052","examYear":"2026","examRound":"38","questionNumber":52,"category":"生活支援技術","questionText":"次のうち、下痢をしている利用者の水分補給として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"白湯"},{"id":"2","text":"牛乳"},{"id":"3","text":"炭酸水"},{"id":"4","text":"コーヒー"},{"id":"5","text":"冷水"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！下痢をしているときは、腸を刺激しない、常温か温かい白湯が向いているんだ。2の牛乳は、乳糖で下痢が悪化することがあり、3の炭酸水は、刺激が強いよ。4のコーヒーは、カフェインで腸を刺激し、5の冷水も、腸を刺激して下痢を悪化させるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-053","examYear":"2026","examRound":"38","questionNumber":53,"category":"生活支援技術","questionText":"Ａさん（83歳、男性、要介護1）は、一人暮らしで、少額の年金で生活している。Ａさんは軽度の認知症（dementia）と診断を受けている。近所には親しくしている人が複数人いる。ある日、訪問介護員（ホームヘルパー）が訪問すると、近所のスーパーで購入した未開封の健康食品が山積みになっていた。Ａさんが財布を持ってきて、「買いたいものがたくさんあるが、お金が足りない。どうしたらよいか」と訪問介護員（ホームヘルパー）に相談した。\nこのときの訪問介護員（ホームヘルパー）の対応に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「お金は足りているから安心して大丈夫ですよ」と伝える。"},{"id":"2","text":"近所の親しい人に、財布を預かってもらえるか、聞いてみる。"},{"id":"3","text":"鍵付きの引き出しに財布を入れ、訪問介護員（ホームヘルパー）が鍵を管理する。"},{"id":"4","text":"「お金の使い方について、一緒に考えてみませんか」と提案する。"},{"id":"5","text":"健康食品のクーリング・オフを勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんは、「お金が足りない、どうしたらよいか」と相談していて、困っている気持ちがあるんだ。まずは、「一緒に考えてみませんか」と提案して、本人の意思を尊重しながら支援するのがよいよ。1は、事実を伝えていない。2と3は、財布を預かるのは、トラブルのもとになる。5は、訪問介護員が、勝手に決めてはいけないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-054","examYear":"2026","examRound":"38","questionNumber":54,"category":"生活支援技術","questionText":"繊維や衣類の性質と洗濯方法に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"綿の柄物シャツには酸素系漂白剤を使う。"},{"id":"2","text":"ナイロンのレインウエアは脱水時間を長くする。"},{"id":"3","text":"ウールのニットセーターは乾燥機を使う。"},{"id":"4","text":"レーヨンのパジャマはすすぎ時間を長くする。"},{"id":"5","text":"絹のブラウスには弱アルカリ性洗剤を使う。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！綿は酸素系漂白剤が使えるので、柄物のシャツにも、色落ちの心配が少なく、使えるんだ。2は、ナイロンは、脱水を短めにする。3は、ウールの乾燥機は、縮む原因になる。4は、レーヨンは水に弱く、すすぎを短めにして、優しく洗う。5は、絹は中性洗剤で洗うんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-055","examYear":"2026","examRound":"38","questionNumber":55,"category":"生活支援技術","questionText":"Ａさん（82歳、女性、要介護1）は、訪問介護（ホームヘルプサービス）を週1回利用し、生活援助を受けながら、自宅で一人暮らしをしている。調理はＡさん本人が行うなど、できることは自分で行いたいと思っている。ある日、訪問介護員（ホームヘルパー）はＡさんから買物リストを渡されて、近くのスーパーで食材を購入してきた。\n次の記述のうち、Ａさんへの生活援助における訪問介護員（ホームヘルパー）の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"依頼された食材が安かったので、リストに書かれた数より多く購入した。"},{"id":"2","text":"おつりとレシート、購入した食材の確認を、Ａさんにすべて任せた。"},{"id":"3","text":"冷蔵庫を開けたとき、賞味期限切れの食材があったため廃棄した。"},{"id":"4","text":"買物リストは、次から訪問介護員（ホームヘルパー）が書くことを提案した。"},{"id":"5","text":"購入した食材で調理しにくいものがないか、Ａさんに確認した。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、調理を自分で行うので、購入した食材で調理しにくいものがないか、Ａさんに確認するのがよいんだ。自立支援にもつながるよ。1は、リストより多く買うのはNG。2は、おつりやレシートの確認は、Ａさんと一緒に行う。3は、勝手に廃棄せず、本人に確認する。4は、Ａさんができることを奪ってしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-056","examYear":"2026","examRound":"38","questionNumber":56,"category":"生活支援技術","questionText":"次の記述のうち、良質な睡眠のための環境づくりとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"日中は、強度の高い運動を多く取り入れる。"},{"id":"2","text":"夜食は、就寝直前にとる。"},{"id":"3","text":"入浴は、就寝の1～2時間前に行う。"},{"id":"4","text":"眠気がなくても、決まった時間に目を閉じる。"},{"id":"5","text":"寝ている間も、照明は明るくしておく。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！入浴は、就寝の1〜2時間前に済ませると、体温が下がるころに眠気が来て、寝つきがよくなるんだ。1は、強度の高い運動は、夜の睡眠を妨げることも。2は、夜食は就寝直前は避ける。4は、眠くなくても目を閉じると、かえって眠れなくなる。5は、寝ている間は、照明は暗くするんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-057","examYear":"2026","examRound":"38","questionNumber":57,"category":"生活支援技術","questionText":"Ａさん（83歳、女性、要介護3）は、脳梗塞（cerebral infarction）の後遺症で左片麻痺｛ひだりかたまひ｝があり、介護老人福祉施設に入所している。ある日の夜間、仰臥位｛ぎょうがい｝（背臥位｛はいがい｝）で寝ていたＡさんが、「背中が重く感じて、眠れない」と介護福祉職に訴えた。\n次の記述のうち、介護福祉職がＡさんに行う介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ファーラー位にして、左下肢にクッションを入れる。"},{"id":"2","text":"両上肢の下に、クッションを入れる。"},{"id":"3","text":"両膝窩部｛りょうしつかぶ｝に、クッションを入れる。"},{"id":"4","text":"右側臥位｛みぎそくがい｝にして、クッションを抱いてもらう。"},{"id":"5","text":"右下肢の足部に、クッションを入れる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！仰臥位のままだと、背中が圧迫されて重く感じるんだね。健側の右を下にした右側臥位に変えると、圧迫が分散されて、楽になるよ。クッションを抱いてもらうと、姿勢が安定して、身体の負担も少なくなるんだ。1は、ファーラー位は、背中への圧迫がかえって増えることもある。2、3、5は、背中の重さの訴えに、直接応えられていないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-058","examYear":"2026","examRound":"38","questionNumber":58,"category":"生活支援技術","questionText":"次の記述のうち、介護老人福祉施設で、終末期にある利用者とその家族に行う介護福祉職の支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の苦しそうな姿を見せないように、家族には面会を控えてもらう。"},{"id":"2","text":"利用者と家族の関係が良好でない場合は、家族と連絡を取らないようにする。"},{"id":"3","text":"好きなものや食べたいものがある場合は、家族に持ってきてもらう。"},{"id":"4","text":"苦痛を訴える場合は、家族から激励してもらう。"},{"id":"5","text":"家族が不安になるため、体調の変化は伝えないようにする。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！終末期には、本人の好きなものや食べたいものがあれば、家族に持ってきてもらうなど、家族と協力して、その人らしい最期を支えることが大切なんだ。1は、面会を控えてもらうのは、家族の思いを大切にしていない。2は、関係がよくなくても、連絡は取る。4は、家族の激励は、負担になることも。5は、変化は家族にきちんと伝えるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-059","examYear":"2026","examRound":"38","questionNumber":59,"category":"生活支援技術","questionText":"次の記述のうち、施設で亡くなった利用者家族への介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"悲しみの表出があった時点からかかわりを開始する。"},{"id":"2","text":"傾聴よりも励ますことを重視する。"},{"id":"3","text":"悲嘆は特異な反応のため注意する。"},{"id":"4","text":"故人との思い出には触れないようにする。"},{"id":"5","text":"悲嘆が長期化した場合は、専門医等へ相談するように助言する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！悲嘆は、大切な人を失ったときの自然な反応なんだけど、長引いてつらいときは、専門医などに相談するよう助言するんだ。1は、亡くなる前からのかかわりが大切。2は、励ますより、傾聴が大切。3は、悲嘆は自然な反応。4は、故人の思い出を語ってもらうのも、悲嘆の癒しにつながるよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-060","examYear":"2026","examRound":"38","questionNumber":60,"category":"生活支援技術","questionText":"次のうち、固定式歩行器が適した利用者として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"対麻痺｛ついまひ｝で、下肢を交互に出すことができない人"},{"id":"2","text":"片麻痺｛かたまひ｝があって、麻痺側｛まひそく｝の指関節の拘縮がある人"},{"id":"3","text":"両上肢の筋力が弱く、手関節に痛みがある人"},{"id":"4","text":"両手の握力が保たれていて、数秒程度の立位保持ができる人"},{"id":"5","text":"右の足根骨を骨折して、右下肢に体重をかけることができない人"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！固定式歩行器は、両手で持って、持ち上げるようにして前に進めるため、両手の握力が保たれていて、しばらく立っていられる人に向いているんだ。1は、下肢を交互に出せない人には向かず、2は、麻痺側の指に拘縮があると、握れないよ。3は、両上肢の筋力が弱いと持ち上げられない。5は、片足に体重をかけられない人は、別の用具が必要なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_am_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-061","examYear":"2026","examRound":"38","questionNumber":61,"category":"こころとからだのしくみ","questionText":"次のうち、比較的短い時間に限られる大きな感情の動きに該当するものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"条件づけ"},{"id":"2","text":"短期記憶"},{"id":"3","text":"気分"},{"id":"4","text":"思考"},{"id":"5","text":"情動"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！情動は、喜びや怒りなど、急に起こって、短い時間で終わる、大きな感情の動きのことなんだ。3の気分は、もっと長く続く、穏やかな感情の状態だよ。1の条件づけは学習の1つ、2の短期記憶は記憶、4の思考は、考える働きで、感情の動きではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-062","examYear":"2026","examRound":"38","questionNumber":62,"category":"こころとからだのしくみ","questionText":"次の記述のうち、脳のしくみとその働きとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"神経細胞は、神経膠細胞｛しんけいこうさいぼう｝（グリア細胞）を支える。"},{"id":"2","text":"神経膠細胞｛しんけいこうさいぼう｝（グリア細胞）は、情報伝達をつかさどる。"},{"id":"3","text":"セロトニン（serotonin）は、神経伝達物質の1つである。"},{"id":"4","text":"頭頂葉には、運動野が存在する。"},{"id":"5","text":"海馬は、視覚をつかさどる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！セロトニンは、脳の中で、神経細胞の間で情報を伝える、神経伝達物質の1つなんだ。1は、神経膠細胞（グリア細胞）が、神経細胞を支えるのが正しい。2は、情報伝達をつかさどるのは神経細胞。4は、運動野は前頭葉にある。5は、視覚は後頭葉、海馬は記憶をつかさどるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-063","examYear":"2026","examRound":"38","questionNumber":63,"category":"こころとからだのしくみ","questionText":"次の記述のうち、循環器系のしくみとして、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"心臓は体性神経が支配している。"},{"id":"2","text":"肺動脈には静脈血が流れている。"},{"id":"3","text":"左心室から出た血液は大静脈へ流れる。"},{"id":"4","text":"リンパ管には血液が流れている。"},{"id":"5","text":"静脈血とは酸素を多く含む血液である。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！肺動脈には、全身から戻ってきた、酸素の少ない静脈血が流れていて、肺で酸素を受け取るんだ。1は、心臓は自律神経が支配している。3は、左心室から出た血液は、大動脈へ流れる。4は、リンパ管には、リンパ液が流れる。5は、静脈血は、酸素が少なく、二酸化炭素が多い血液のことだよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-064","examYear":"2026","examRound":"38","questionNumber":64,"category":"こころとからだのしくみ","questionText":"次の記述のうち、人の動作時に収縮する筋肉に関する説明として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"立位を保持するときは大殿筋が収縮する。"},{"id":"2","text":"膝の屈曲には大腿四頭筋｛だいたいしとうきん｝が収縮する。"},{"id":"3","text":"肘の屈曲には上腕三頭筋が収縮する。"},{"id":"4","text":"肩関節を内転するときは三角筋が収縮する。"},{"id":"5","text":"足関節の底屈では前脛骨筋｛ぜんけいこつきん｝が収縮する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！立位を保つときは、抗重力筋の大殿筋などが収縮して、体をまっすぐ支えているんだ。2の膝の屈曲は、大腿二頭筋などのハムストリングス、3の肘の屈曲は、上腕二頭筋、4の肩関節の内転は、大胸筋や広背筋、5の足関節の底屈は、腓腹筋やヒラメ筋が働くよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-065","examYear":"2026","examRound":"38","questionNumber":65,"category":"こころとからだのしくみ","questionText":"次のうち、白内障（cataract）で混濁する部位として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"網膜"},{"id":"2","text":"角膜"},{"id":"3","text":"脈絡膜"},{"id":"4","text":"硝子体"},{"id":"5","text":"水晶体"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！白内障は、カメラのレンズにあたる水晶体が、白く濁って、見えにくくなる病気なんだ。1の網膜は、フィルムのように光を受け取る部分、2の角膜は、目の表面の透明な膜、3の脈絡膜は、血管が多い膜、4の硝子体は、眼球の中のゼリー状の部分だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-066","examYear":"2026","examRound":"38","questionNumber":66,"category":"こころとからだのしくみ","questionText":"次の記述のうち、低栄養の高齢者にみられる症状や行動の特徴として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"唾液の分泌が増加する。"},{"id":"2","text":"腸蠕動｛ちょうぜんどう｝が亢進｛こうしん｝する。"},{"id":"3","text":"食べこぼしが減る。"},{"id":"4","text":"偏りのある食べ方をする。"},{"id":"5","text":"体重が増える。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！低栄養になると、食べ物の好き嫌いが強くなったり、偏った食べ方をしたりする行動がみられるんだ。1は、唾液の分泌は減る。2は、腸蠕動は低下する。3は、食べこぼしは増える。5は、体重は減っていくよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-067","examYear":"2026","examRound":"38","questionNumber":67,"category":"こころとからだのしくみ","questionText":"次のうち、バリア機能をもつ表皮の構造として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"汗腺"},{"id":"2","text":"角質層"},{"id":"3","text":"基底層"},{"id":"4","text":"有棘層｛ゆうきょくそう｝"},{"id":"5","text":"顆粒層｛かりゅうそう｝"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！表皮の一番外側にある角質層は、外からの異物や細菌の侵入を防いだり、水分の蒸発を防いだりするバリア機能をもっているんだ。1の汗腺は、汗を出す器官。3の基底層は、新しい細胞をつくる層で、4の有棘層と5の顆粒層は、角質層になる前の細胞がある層だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-068","examYear":"2026","examRound":"38","questionNumber":68,"category":"こころとからだのしくみ","questionText":"Ａさん（98歳、女性）は、認知症（dementia）があるが、食事動作は自立していた。最近、配膳されても食事動作が始まらないことが増えてきた。介護福祉職が献立や食材などの説明をしたところ、Ａさんは食べ始めるようになった。\n次の摂食嚥下｛せっしょくえんげ｝の5期のうち、介護福祉職が支援した期として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"先行期"},{"id":"2","text":"準備期"},{"id":"3","text":"口腔期"},{"id":"4","text":"咽頭期"},{"id":"5","text":"食道期"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！摂食嚥下の5期のうち、先行期は、食べ物を認識する段階なんだ。献立や食材を説明して、食べ物と認識して、食べ始められるようにしたのは、先行期への支援だよ。2の準備期は、口に入れてかみ砕く段階、3の口腔期は、舌で食べ物を送る段階、4の咽頭期は、飲み込む段階、5の食道期は、食道を通って胃へ運ぶ段階だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-069","examYear":"2026","examRound":"38","questionNumber":69,"category":"こころとからだのしくみ","questionText":"次のうち、健康な成人において、横行結腸の次に便が通過する部位として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"盲腸"},{"id":"2","text":"上行結腸"},{"id":"3","text":"下行結腸"},{"id":"4","text":"Ｓ状結腸"},{"id":"5","text":"直腸"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！便は、盲腸、上行結腸、横行結腸、下行結腸、Ｓ状結腸、直腸の順に通っていくんだ。だから、横行結腸の次は、下行結腸だよ。大腸の順番は、この機会にしっかり覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-070","examYear":"2026","examRound":"38","questionNumber":70,"category":"こころとからだのしくみ","questionText":"Ａさん（80歳、男性）は、半年前から急に便秘になり、最近では排便回数が5日に1回程度となった。腹部は膨満していて、便は細く、血液が付着することがあるという。\n次の記述のうち、Ａさんの便秘に対する対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"水分摂取を促す。"},{"id":"2","text":"食物繊維の摂取を促す。"},{"id":"3","text":"散歩などの運動を促す。"},{"id":"4","text":"腹部のマッサージを行う。"},{"id":"5","text":"医療機関の受診を促す。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！半年前から急に便秘になり、便が細くて、血液が付着するのは、大腸がんなどの病気が疑われる危険なサインなんだ。水分摂取（1）、食物繊維（2）、運動（3）、マッサージ（4）よりも、まず医療機関の受診を促すことが最優先だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-071","examYear":"2026","examRound":"38","questionNumber":71,"category":"こころとからだのしくみ","questionText":"次のうち、65歳の人の妥当な睡眠時間として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"約12時間"},{"id":"2","text":"約10時間"},{"id":"3","text":"約8時間"},{"id":"4","text":"約6時間"},{"id":"5","text":"約4時間"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！睡眠時間は、年をとるにつれて短くなる傾向があって、65歳ごろでは、約6時間が目安とされているんだ。睡眠の長さは個人差が大きいけれど、12時間や10時間は長すぎで、4時間は短すぎるよ。ただ、睡眠の質や日中の眠気も、あわせて大切なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-072","examYear":"2026","examRound":"38","questionNumber":72,"category":"こころとからだのしくみ","questionText":"キューブラー・ロス（Kubler-Ross, E.）が示した終末期にある人の死の受容プロセスのうち「抑うつ」の段階として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"第1段階"},{"id":"2","text":"第2段階"},{"id":"3","text":"第3段階"},{"id":"4","text":"第4段階"},{"id":"5","text":"第5段階"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！キューブラー・ロスの死の受容プロセスは、第1段階が否認、第2段階が怒り、第3段階が取り引き、第4段階が抑うつ、第5段階が受容の順なんだ。だから、抑うつは第4段階だよ。順番を覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-073","examYear":"2026","examRound":"38","questionNumber":73,"category":"発達と老化の理解","questionText":"次の記述のうち、ハヴィガースト（Havighurst, R.）の示す中年期の発達課題に該当するものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"良心、道徳心、価値尺度を発達させる。"},{"id":"2","text":"成人としての市民的・社会的責任を達成する。"},{"id":"3","text":"満足できる住宅を確保する。"},{"id":"4","text":"男性あるいは女性の社会的役割を身につける。"},{"id":"5","text":"気心の合う社交集団を見つける。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ハヴィガーストの中年期の発達課題には、成人としての市民的・社会的責任を達成することなどがあるんだ。1は、良心、道徳心、価値尺度の発達は、児童期の課題。3の住宅の確保と、5の社交集団の発見は、壮年期の課題。4は、男性または女性の社会的役割の習得は、児童期の課題だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-074","examYear":"2026","examRound":"38","questionNumber":74,"category":"発達と老化の理解","questionText":"次の記述のうち、自閉症スペクトラム障害（autism spectrum disorder）の特徴として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"文字のつづりがうまく書けず、類似の文字を間違えたりする。"},{"id":"2","text":"同じ動作や行動を繰り返す。"},{"id":"3","text":"注意の持続が難しい。"},{"id":"4","text":"順番を待てずに割り込む。"},{"id":"5","text":"数の大小の比較が難しい。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！自閉症スペクトラム障害は、社会的なコミュニケーションが苦手なことと、同じ動作や行動を繰り返すなど、こだわりが強いことが特徴なんだ。1は、限局性学習症（書字障害）、3と4は、ＡＤＨＤ（注意欠如・多動症）、5は、限局性学習症（算数障害）の特徴だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-075","examYear":"2026","examRound":"38","questionNumber":75,"category":"発達と老化の理解","questionText":"次のうち、健康な状態と心身の機能が低下して介護等が必要な状態の中間を示す用語として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"エイジング（aging）"},{"id":"2","text":"サルコペニア（sarcopenia）"},{"id":"3","text":"ロコモティブシンドローム"},{"id":"4","text":"ホメオスタシス（homeostasis）"},{"id":"5","text":"フレイル（frailty）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！フレイルは、加齢によって、心身の活力が低下して、健康な状態と、介護が必要な状態の中間にある状態のことなんだ。早めに対応すれば、健康な状態に戻れる可能性があるよ。1のエイジングは加齢、2のサルコペニアは筋肉量の減少、3のロコモティブシンドロームは運動器の障害、4のホメオスタシスは体を一定に保つ働きだよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-076","examYear":"2026","examRound":"38","questionNumber":76,"category":"発達と老化の理解","questionText":"高齢者のセクシュアリティ（sexuality）に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高齢になると性への関心がなくなる。"},{"id":"2","text":"男性は、高齢になっても性ホルモンの分泌が維持される。"},{"id":"3","text":"女性は、高齢になると性交痛を感じやすくなる。"},{"id":"4","text":"高齢者は生殖機能の喪失と同時にセクシュアリティ（sexuality）を喪失する。"},{"id":"5","text":"高齢者の性的欲求に、性差はみられない。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！女性は、加齢によって、女性ホルモンが減り、膣の潤いが減って、性交痛を感じやすくなることがあるんだ。1は、高齢になっても、性への関心はなくならない。2は、男性の性ホルモンも減少する。4は、生殖機能を失っても、セクシュアリティは残る。5は、性的欲求には個人差や性差があるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-077","examYear":"2026","examRound":"38","questionNumber":77,"category":"発達と老化の理解","questionText":"Ａさん（22歳、女性）は、施設で介護福祉職として勤務し、食事や睡眠を工夫しながら、一人暮らしをしている。日々の生活や勤務状況に問題はない。職場にＡさんと年齢の近い介護福祉職はおらず、休憩時間や休みの日も一人で過ごしている。Ａさんは、「自分の仕事ぶりを上司に認めてほしいという気持ちはない。それよりも、仕事やそれ以外のことを深く話せる同年代の同僚がほしい」と思っている。\n次のマズロー（Maslow, A.H.）の欲求階層説の各段階のうち、Ａさんの現在の気持ちが当てはまるものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"生理的欲求"},{"id":"2","text":"所属・愛情欲求"},{"id":"3","text":"安全欲求"},{"id":"4","text":"承認欲求"},{"id":"5","text":"自己実現欲求"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ａさんは、生活の基本的な欲求は満たされていて、上司に認められたい気持ちはなく、深く話せる同年代の同僚がほしいと思っているんだね。これは、集団に属したい、人と親しくつながりたいという、所属・愛情欲求にあたるよ。4の承認欲求は、認められたい気持ちで、Ａさんはそれを否定しているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-078","examYear":"2026","examRound":"38","questionNumber":78,"category":"発達と老化の理解","questionText":"次のうち、加齢に伴い階段を上ると息切れしやすくなる現象に関係する恒常性の機能として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"予備力"},{"id":"2","text":"適応力"},{"id":"3","text":"免疫力"},{"id":"4","text":"抵抗力"},{"id":"5","text":"回復力"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！予備力は、ふだんは使っていない、体にたくわえられた余力のことなんだ。加齢によって予備力が低下すると、階段を上るなど、体に負荷がかかると、息切れしやすくなるよ。2の適応力、3の免疫力、4の抵抗力、5の回復力も、恒常性にかかわるけれど、この現象を最もよく説明するのは、予備力だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-079","examYear":"2026","examRound":"38","questionNumber":79,"category":"発達と老化の理解","questionText":"次の記述のうち、高齢者の疾患や症状の特徴として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"典型的な症状を呈する。"},{"id":"2","text":"生活が活発になる。"},{"id":"3","text":"痛みに敏感になる。"},{"id":"4","text":"複数の疾患を持ちやすい。"},{"id":"5","text":"慢性的な疾患は少ない。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！高齢者は、複数の疾患を同時にもっていることが多いんだ。1は、典型的な症状が出ないことが多い。2は、生活が不活発になりやすい。3は、痛みを感じにくくなることがある。5は、慢性的な疾患が多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-080","examYear":"2026","examRound":"38","questionNumber":80,"category":"発達と老化の理解","questionText":"Ａさん（82歳、女性）は、介護老人保健施設に入所している。朝、眠そうな様子であったため、介護福祉職がどうしたのかと尋ねると、Ａさんは、「夜、足や背中がかゆくてあまり眠れなかった」と話した。看護師と共に足や背中を観察すると、皮膚が乾燥していて、引っ掻｛か｝いたような傷があった。そのほかに皮膚の異常はみられなかった。Ａさんは寒さに弱く、今は冬なので常に電気毛布を使用している。昨日は入浴日であった。\n次のうち、Ａさんに生じている可能性がある疾患として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"角化型疥癬｛かくかがたかいせん｝（hyperkeratotic scabies）"},{"id":"2","text":"帯状疱疹｛たいじょうほうしん｝（herpes zoster）"},{"id":"3","text":"褥瘡｛じょくそう｝"},{"id":"4","text":"老人性皮膚掻痒症｛ろうじんせいひふそうようしょう｝（senile pruritus）"},{"id":"5","text":"閉塞性動脈硬化症（arteriosclerosis obliterans）"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんは、冬に電気毛布を使い、皮膚が乾燥して、夜にかゆみが強く、引っ掻いた傷はあっても、そのほかの異常はないよね。これは、老人性皮膚掻痒症の特徴なんだ。1の角化型疥癬は、皮膚に厚い角質ができ、感染力が強い。2の帯状疱疹は、水ぶくれと痛み。3の褥瘡は、圧迫による皮膚の傷。5の閉塞性動脈硬化症は、足の血流の病気だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-081","examYear":"2026","examRound":"38","questionNumber":81,"category":"認知症の理解","questionText":"次の記述のうち、認知症（dementia）のある人にみられる妄想の説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自分でしまい忘れた物が見つからず、誰かが盗んだと思い込むのは、嫉妬妄想である。"},{"id":"2","text":"孫と会って話をしたにもかかわらず、孫にずっと会わせてもらえていないと主張するのは、カプグラ症候群である。"},{"id":"3","text":"介護支援専門員（ケアマネジャー）と妻が話しているのを見て、妻の浮気相手だと思い込むのは、幻の同居人である。"},{"id":"4","text":"家族など身近な人がよく似た偽物と入れ替わっていると主張するのは、被害妄想である。"},{"id":"5","text":"身体的疾患がないにもかかわらず、自分が病気だと思い込むのは、心気妄想である。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！身体的な疾患がないのに、自分が病気だと思い込むのは、心気妄想なんだ。1は、物を盗られたと思い込むのは、物盗られ妄想。2は、孫に会えていないと主張するのは、記憶障害による訴えで、カプグラ症候群ではない。3は、浮気相手だと思い込むのは、嫉妬妄想。4は、身近な人が偽物と入れ替わっていると思い込むのが、カプグラ症候群だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-082","examYear":"2026","examRound":"38","questionNumber":82,"category":"認知症の理解","questionText":"次の記述のうち、認知症（dementia）の人への取り組みとその説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"本人ミーティングでは、当事者たちが語り合い社会に発信も行う。"},{"id":"2","text":"認知症初期集中支援チームは、要介護認定を行う。"},{"id":"3","text":"若年性認知症支援コーディネーターは、認知症（dementia）の診断を行う。"},{"id":"4","text":"認知症疾患医療センターは、地域ケア会議を開催する。"},{"id":"5","text":"認知症カフェは、認知症介護指導者を養成する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！本人ミーティングは、認知症の人たちが集まって、自分たちの思いや希望を語り合い、社会に発信する場なんだ。2は、要介護認定は市町村が行う。3は、若年性認知症支援コーディネーターは、診断ではなく、相談や関係機関との調整を行う。4は、地域ケア会議を開催するのは、地域包括支援センター。5は、認知症カフェは、交流や相談の場で、認知症介護指導者の養成はしないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-083","examYear":"2026","examRound":"38","questionNumber":83,"category":"認知症の理解","questionText":"次の記述のうち、認知症（dementia）の行動・心理症状（ＢＰＳＤ）に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"10分前に施設職員が挨拶しに来たことを、覚えていない。"},{"id":"2","text":"病院にいるのに、自宅にいると思っている。"},{"id":"3","text":"通所介護（デイサービス）を利用中に、出口を探して歩き回る。"},{"id":"4","text":"薬を処方されても、服薬管理ができない。"},{"id":"5","text":"入浴を促すと、湯につかるだけで出てくる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ＢＰＳＤ（行動・心理症状）は、周囲の環境や本人の状態によって起こる、行動や心理面の症状なんだ。出口を探して歩き回るのは、ＢＰＳＤの徘徊にあたるよ。1は記憶障害、2は見当識障害、4は実行機能障害の一種、5は失行の症状で、これらは中核症状だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-084","examYear":"2026","examRound":"38","questionNumber":84,"category":"認知症の理解","questionText":"次の記述のうち、アルツハイマー型認知症（dementia of the Alzheimer’s type）の説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"古い記憶から障害され、徐々に新しい記憶も障害される。"},{"id":"2","text":"認知機能が変動することが特徴的である。"},{"id":"3","text":"ＡＤＬ（Activities of Daily Living：日常生活動作）の障害は、重度期以降に認められる。"},{"id":"4","text":"見当識障害は、中期以降に認められる。"},{"id":"5","text":"記憶障害は、初期から認められる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！アルツハイマー型認知症は、初期から、新しいことを覚えられない記憶障害がみられるんだ。1は、新しい記憶から先に障害される。2は、変動が特徴なのは、レビー小体型認知症。3は、ＡＤＬの障害は、中期ごろから出はじめる。4は、見当識障害は、初期から中期に出現するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-085","examYear":"2026","examRound":"38","questionNumber":85,"category":"認知症の理解","questionText":"次のうち、レビー小体型認知症（dementia with Lewy bodies）の症状として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ノンレム睡眠行動障害による大声"},{"id":"2","text":"自律神経症状による起立性低血圧（orthostatic hypotension）"},{"id":"3","text":"聴覚認知機能の障害による幻聴"},{"id":"4","text":"側頭葉の萎縮による意味性失語"},{"id":"5","text":"嚥下機能｛えんげきのう｝の促進による食欲増加"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！レビー小体型認知症では、自律神経症状として、立ちくらみを起こす起立性低血圧がよくみられるんだ。1は、レム睡眠行動障害で大声が出るので、ノンレムではないよ。3は、幻視が特徴的で、幻聴ではない。4は、意味性失語は、前頭側頭型認知症。5は、嚥下機能は低下して、食欲は増えないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-086","examYear":"2026","examRound":"38","questionNumber":86,"category":"認知症の理解","questionText":"次のうち、認知症（dementia）の人の生活をアセスメントするうえで、身体的要因に含まれる項目として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"性格"},{"id":"2","text":"居住環境"},{"id":"3","text":"人的環境"},{"id":"4","text":"ＩＡＤＬ（Instrumental Activities of Daily Living：手段的日常生活動作）"},{"id":"5","text":"社会とのつながり"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！認知症の人の生活のアセスメントでは、身体的要因として、ＡＤＬやＩＡＤＬなどの生活動作の状況を確認するんだ。1の性格は、心理的な要因。2の居住環境と、3の人的環境は、環境の要因。5の社会とのつながりは、社会的な要因だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-087","examYear":"2026","examRound":"38","questionNumber":87,"category":"認知症の理解","questionText":"認知症（dementia）の人への環境の配慮に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"視覚的認識を容易にするために、廊下の手すりに色をつけて目立つようにする。"},{"id":"2","text":"聴覚に影響を与えるために、ピクトグラム（pictogram）を表示する。"},{"id":"3","text":"音の選択的聴取の力を高めるために、ＢＧＭ（background music）の音量を大きくする。"},{"id":"4","text":"穏やかに生活するために、居室の光の刺激を強くする。"},{"id":"5","text":"落ち着く空間をつくるために、居室を細かい模様の壁紙で統一する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！認知症の人には、手すりの色を目立たせるなど、視覚で、見つけやすくする配慮が有効なんだ。2は、ピクトグラムは、視覚に働きかける。3は、BGMの音量を大きくすると、かえって混乱する。4は、光の刺激が強すぎると落ち着かない。5は、細かい模様の壁紙は、模様が虫などに見えて混乱することがあるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-088","examYear":"2026","examRound":"38","questionNumber":88,"category":"認知症の理解","questionText":"次の記述のうち、認知症（dementia）の人の遂行機能障害の症状として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ご飯を食べたことを忘れて、ご飯をほしいと言う。"},{"id":"2","text":"包丁の使い方を忘れて、うまく使うことができない。"},{"id":"3","text":"食事が配膳されているが、左側のものを残す。"},{"id":"4","text":"調理の手順を順序だてて行うことができない。"},{"id":"5","text":"皿の模様をおかずと間違えて、スプーンですくおうとする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！遂行機能障害は、目的に向けて、手順を考えて、順序立てて行動することが難しくなる障害なんだ。調理の手順を順序立てて行えないのは、その症状だよ。1は記憶障害、2は失行の一種、3は半側空間無視、5は視覚認知の障害（失認）による症状だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-089","examYear":"2026","examRound":"38","questionNumber":89,"category":"認知症の理解","questionText":"Ａさん（75歳、男性）は、認知症（dementia）で、通所介護（デイサービス）を利用している。介護福祉職が、「今日は何月何日でしょうか」と聞くと、Ａさんは、「9月」と答えた。介護福祉職が、「今朝、Ａさんの家の庭にあじさいが咲いていましたね」と言うと、Ｂさんが、「あじさいが咲くのは6月？」と答えた。介護福祉職は、「そうです。今日は6月22日です」と言い、ホワイトボードに日付とあじさいの絵を描いた。介護福祉職が、「6月生まれの方はいますか」と聞くが、返事がない。介護福祉職は、「今日は6月22日ですが、あと3日でＡさんの誕生日ですね」と伝えた。\n次のうち、介護福祉職が実施した技法として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"タッチケア（touch care）"},{"id":"2","text":"アートセラピー（art therapy）"},{"id":"3","text":"リアリティ・オリエンテーション（reality orientation）"},{"id":"4","text":"ライフレビュー（life review）"},{"id":"5","text":"グリーフケア（grief care）"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！日付や季節を伝えたり、ホワイトボードに日付を書いたりして、日時や場所などの見当識を保つのは、リアリティ・オリエンテーション（現実見当識訓練）なんだ。1のタッチケアは触れる技法、2のアートセラピーは芸術を使う療法、4のライフレビューは人生を振り返る方法、5のグリーフケアは悲嘆への支援だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-090","examYear":"2026","examRound":"38","questionNumber":90,"category":"認知症の理解","questionText":"Ａさん（88歳、女性）は、4年前に、認知症（dementia）と診断された。在宅で長男が介護している。Ａさんは、3か月前から、何度もトイレ以外で排泄｛はいせつ｝しようとする様子がみられた。長男が繰り返しトイレの場所を教えているが、状態は変わらない。長男はＡさんに対して、「何回、同じことを言ったら、わかるんだ」と大声でどなってしまい、その後で落ち込むようになった。また、長男は、「認知症（dementia）がいつまで続くのか」「自分に何か問題があったのではないか」と言って、自分を強く責めている。\n次のうち、Ａさんの認知症（dementia）を長男が受け入れる過程と考えた場合、このときの長男の心理的特徴に該当する段階として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ショック期"},{"id":"2","text":"否認期"},{"id":"3","text":"混乱期"},{"id":"4","text":"解決への努力期"},{"id":"5","text":"受容期"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！家族が認知症を受け入れる過程は、ショック期、否認期、混乱期、解決への努力期、受容期と進むんだ。長男は、大声でどなったり、自分を責めたりして、感情が揺れているから、混乱期にあたるよ。1は衝撃を受ける時期、2は認めたくない時期、4は対処を工夫する時期、5は受け入れる時期だね。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-091","examYear":"2026","examRound":"38","questionNumber":91,"category":"障害の理解","questionText":"次のうち、障害福祉におけるソーシャルインクルージョン（social inclusion）の考え方の説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害のある人とない人を統合する社会"},{"id":"2","text":"障害のある人を権利侵害から守る社会"},{"id":"3","text":"障害のある人の意思決定を支援する社会"},{"id":"4","text":"障害のある人の最善の利益を考える社会"},{"id":"5","text":"障害のある人もない人も包摂する社会"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！ソーシャルインクルージョンは、障害のある人もない人も、社会の一員として包み込み、支え合う考え方なんだ。1は、統合する社会という、ノーマライゼーションに近い説明。2は権利擁護、3は意思決定支援、4は最善の利益の考え方だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-092","examYear":"2026","examRound":"38","questionNumber":92,"category":"障害の理解","questionText":"知的障害に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害が発達期にあらわれる。"},{"id":"2","text":"障害の原因は明らかである。"},{"id":"3","text":"一般就労は不可能である。"},{"id":"4","text":"療育手帳の等級は障害支援区分で決める。"},{"id":"5","text":"運動発達の遅れは伴わない。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！知的障害は、発達期（おおむね18歳未満）にあらわれる障害なんだ。2は、原因が明らかでないことも多い。3は、一般就労も可能だよ。4は、療育手帳の等級は、障害支援区分ではなく、知能検査などで決める。5は、運動発達の遅れを伴うこともあるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-093","examYear":"2026","examRound":"38","questionNumber":93,"category":"障害の理解","questionText":"次のうち、後遺症によって片麻痺｛かたまひ｝や言語障害を伴うことがある疾患や病態として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"脳血管障害（cerebrovascular disorder）"},{"id":"2","text":"糖尿病（diabetes mellitus）"},{"id":"3","text":"脊髄損傷（spinal cord injury）"},{"id":"4","text":"慢性閉塞性肺疾患（chronic obstructive pulmonary disease）"},{"id":"5","text":"クローン病（Crohn disease）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！脳血管障害は、脳梗塞や脳出血などで、後遺症として、片麻痺や言語障害が起こることがあるんだ。2の糖尿病は、合併症で、神経障害や網膜症などを起こす。3の脊髄損傷は、対麻痺や四肢麻痺。4のＣＯＰＤは、呼吸の障害。5のクローン病は、消化管の炎症で、片麻痺や言語障害は起きないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-094","examYear":"2026","examRound":"38","questionNumber":94,"category":"障害の理解","questionText":"次の記述のうち、国際障害者年を契機に、日本の障害福祉に起きた変化として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害者を弱者として保護する捉え方が広まった。"},{"id":"2","text":"ノーマライゼーションの理念が徐々に浸透した。"},{"id":"3","text":"身体障害者福祉法の制定につながった。"},{"id":"4","text":"障害種別ごとの福祉サービス給付が始まった。"},{"id":"5","text":"措置制度から自立支援医療制度へ移行した。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！1981年の国際障害者年で、「完全参加と平等」がテーマになり、日本でもノーマライゼーションの理念が、徐々に広まったんだ。1は、弱者として保護する見方は、むしろ見直された。3は、身体障害者福祉法は1949年に制定されている。4と5は、この契機で起きた変化ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-095","examYear":"2026","examRound":"38","questionNumber":95,"category":"障害の理解","questionText":"次のうち、筋萎縮性側索硬化症（amyotrophic lateral sclerosis：ＡＬＳ）によくみられる症状として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"感覚障害"},{"id":"2","text":"失禁"},{"id":"3","text":"嚥下障害｛えんげしょうがい｝"},{"id":"4","text":"視力障害"},{"id":"5","text":"便秘"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ＡＬＳは、運動神経が障害されて、筋力が低下する病気で、進行すると、嚥下障害や呼吸障害が出てくるんだ。1の感覚障害、2の失禁、4の視力障害は、ふつうは起きにくい。5の便秘は、起こることもあるけれど、よくみられる症状として最も適切なのは、嚥下障害だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-096","examYear":"2026","examRound":"38","questionNumber":96,"category":"障害の理解","questionText":"Ａさん（50歳、男性）は、以前は一人暮らしをしていたが、現在は統合失調症（schizophrenia）のため長期入院をしている。症状が軽快して安定したため、医師から間もなく退院できるという説明があった。Ａさんは以前と同じように独居を希望しているが、一人で住居を探すのに不安がある。\n次のうち、Ａさんの希望を実現するために利用する公的な支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"地域定着支援"},{"id":"2","text":"自立生活援助"},{"id":"3","text":"地域移行支援"},{"id":"4","text":"生活介護"},{"id":"5","text":"同行援護"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！地域移行支援は、入院している精神障害者などが、退院して地域で暮らせるように、住居の確保や、外出の同行などを支援するサービスなんだ。Ａさんは、入院中で、一人での住居探しに不安があるから、ぴったりだね。1の地域定着支援は、地域生活が始まってからの支援、2の自立生活援助は、一人暮らしの支援、4と5は、生活介護や外出の支援だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-097","examYear":"2026","examRound":"38","questionNumber":97,"category":"障害の理解","questionText":"Ａさん（45歳、男性）は、1年前、交通事故で頭部外傷を負った。四肢に障害は残らなかったが、高次脳機能障害（higher brain dysfunction）と診断された。\n次の記述のうち、Ａさんの障害特性を理解した支援として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"記憶障害によって同じことを何度も質問するが、一度だけ質問に答える。"},{"id":"2","text":"注意障害によって作業のミスが多いため、その度ごとに強く注意する。"},{"id":"3","text":"遂行機能障害によって指示されないと作業ができないため、自分の判断でやるように促す。"},{"id":"4","text":"社会的行動障害によってすぐに怒りだすことがあるため、感情が落ち着くように場面や話題を変える。"},{"id":"5","text":"病識低下によってできないことを認めないため、できないことを指摘する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！高次脳機能障害の人が、社会的行動障害ですぐ怒りだすときは、場面や話題を変えて、気持ちが落ち着くようにするのが有効なんだ。1は、記憶障害には、何度でも丁寧に答えるか、メモを使う。2は、注意障害には、強く注意せず、環境を整える。3は、遂行機能障害には、手順を示して支援する。5は、できないことを指摘するだけだと、反発を招くんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-098","examYear":"2026","examRound":"38","questionNumber":98,"category":"障害の理解","questionText":"次のうち、「障害者総合支援法」に規定する補装具として、適切なものを1つ選びなさい。\n（注）  「障害者総合支援法」とは、「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。","choices":[{"id":"1","text":"特殊寝台"},{"id":"2","text":"電動車椅子"},{"id":"3","text":"点字器"},{"id":"4","text":"電気式たん吸引器"},{"id":"5","text":"ストーマ装具"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！電動車椅子は、障害者総合支援法の補装具として支給されるものなんだ。1の特殊寝台と、3の点字器、4の電気式たん吸引器は、日常生活用具、5のストーマ装具も、日常生活用具だよ。補装具は、体の一部のように、長く使うもので、日常生活用具とはちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-099","examYear":"2026","examRound":"38","questionNumber":99,"category":"障害の理解","questionText":"次の記述のうち、地域における障害者のサポート体制として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護支援専門員は、サービス等利用計画を作成する。"},{"id":"2","text":"相談支援専門員は、個別支援計画を作成する。"},{"id":"3","text":"基幹相談支援センターは、障害支援区分を決定する。"},{"id":"4","text":"地域包括支援センターは、要介護度を決定する。"},{"id":"5","text":"市町村は、地域生活支援事業を行う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！市町村は、障害者総合支援法にもとづいて、地域生活支援事業を行うんだ。1は、サービス等利用計画を作成するのは、相談支援専門員。2は、個別支援計画を作成するのは、サービス管理責任者。3は、障害支援区分を決定するのは、市町村。4は、要介護度を決めるのは、市町村の介護認定審査会だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-100","examYear":"2026","examRound":"38","questionNumber":100,"category":"障害の理解","questionText":"次のうち、障害があるためスプーンがうまく握れない人に自助具を作成する職種として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"看護師"},{"id":"2","text":"義肢装具士"},{"id":"3","text":"理学療法士"},{"id":"4","text":"作業療法士"},{"id":"5","text":"言語聴覚士"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！作業療法士は、日常生活動作の訓練とあわせて、その人に合った自助具を工夫して作成する専門職なんだ。1の看護師は、医療的なケアや看護、2の義肢装具士は、義肢や装具の製作、3の理学療法士は、基本動作の訓練、5の言語聴覚士は、言語や嚥下の訓練を行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-101","examYear":"2026","examRound":"38","questionNumber":101,"category":"医療的ケア","questionText":"次の記述のうち、バイタルサインを測定するときの留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"非接触型体温計による測定では、環境温度に注意する。"},{"id":"2","text":"脈拍の測定では、橈骨動脈｛とうこつどうみゃく｝に拇指｛ぼし｝で触れる。"},{"id":"3","text":"呼吸の測定では、ゆっくりと息をするように伝えてから行う。"},{"id":"4","text":"血圧測定では、上腕にマンシェットを隙間のないように巻く。"},{"id":"5","text":"意識レベルは、まず身体を揺さぶって反応をみる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！非接触型体温計は、周囲の温度の影響を受けやすいので、環境温度に注意して測るんだ。2は、脈拍は、人差し指、中指、薬指の3本で、橈骨動脈に触れて測る。3は、呼吸は、意識させずに測る。4は、マンシェットは、指が1〜2本入るくらいのゆとりを持たせて巻く。5は、意識レベルは、まず声をかけて反応をみるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-102","examYear":"2026","examRound":"38","questionNumber":102,"category":"医療的ケア","questionText":"気管カニューレの構造等に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"気管カニューレは、咽頭に挿入されている。"},{"id":"2","text":"気管カニューレは、交換の必要がない。"},{"id":"3","text":"カフは、カニューレの上端についている。"},{"id":"4","text":"カフには、滅菌蒸留水が入れてある。"},{"id":"5","text":"サイドチューブから、カフの上部の貯留物を吸引することができる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！気管カニューレのサイドチューブからは、カフの上にたまった唾液などを吸引できるんだ。1は、気管カニューレは気管に挿入されている。2は、定期的な交換が必要。3は、カフは先端側についている。4は、カフの中は空気が入っていて、滅菌蒸留水ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-103","examYear":"2026","examRound":"38","questionNumber":103,"category":"医療的ケア","questionText":"Ａさん（85歳、男性）は、慢性閉塞性肺疾患（chronic obstructive pulmonary disease）で、介護老人福祉施設に入所している。ある日、Ａさんから、「痰｛たん｝がからんでいて、咳｛せき｝をしても出せない」という訴えがあった。介護福祉士が呼吸回数を確認すると、1分間に22回で、ゴロゴロという音がしていた。看護職からは、右肺に痰｛たん｝が貯留しやすいという情報提供があった。口腔内吸引｛こうくうないきゅういん｝をすると、粘性の強い透明な痰｛たん｝が吸引できた。\nこのとき、介護福祉士が喀痰排出｛かくたんはいしゅつ｝を促すためにＡさんに行う対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"居室の湿度を30％に保つ。"},{"id":"2","text":"水分摂取を控えるように伝える。"},{"id":"3","text":"左側を下にした体位を勧める。"},{"id":"4","text":"太い吸引チューブに変える。"},{"id":"5","text":"ベッド上での安静を勧める。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！右肺に痰がたまりやすいときは、痰のある側を上にして、重力で痰を出しやすくするんだ。だから、左側を下にした体位（左側臥位）を勧めるよ。1は、湿度は、痰をやわらかくするために、適度に高めにする。2は、水分は控えず、しっかりとる。4は、太いチューブは、粘膜を傷つけやすい。5は、寝たきりでは痰が出にくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-104","examYear":"2026","examRound":"38","questionNumber":104,"category":"医療的ケア","questionText":"次の記述のうち、胃の構造として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"幽門から始まり噴門で終わる。"},{"id":"2","text":"左上方を胃底部といい、食べ物を一時的にためる。"},{"id":"3","text":"左下方の縁を小弯｛しょうわん｝という。"},{"id":"4","text":"胃には3つの生理的狭窄部｛せいりてききょうさくぶ｝がある。"},{"id":"5","text":"胃に続く小腸は、空腸という。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！胃の左上方のふくらんだ部分は胃底部といい、食べ物を一時的にためるんだ。1は、食道側の入口が噴門で、十二指腸側の出口が幽門。3は、左下方の縁は大弯で、右上方の短い縁が小弯。4は、生理的狭窄部があるのは食道。5は、胃に続く小腸の最初の部分は、十二指腸だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-105","examYear":"2026","examRound":"38","questionNumber":105,"category":"医療的ケア","questionText":"次の記述のうち、ボタン型胃ろうチューブを挿入している利用者に対して、介護福祉士が行うケアとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"胃ろう周囲の皮膚に発赤がある場合は、軟膏｛なんこう｝を塗布する。"},{"id":"2","text":"1日に2、3回、胃ろうチューブを回転させて、癒着を防ぐ。"},{"id":"3","text":"胃ろうチューブの抜去予防のため、歩行は避けるように勧める。"},{"id":"4","text":"胃ろう周囲の皮膚は石けんとぬるま湯で洗浄して、清潔を保つ。"},{"id":"5","text":"栄養剤を注入する前には、胃ろう部を消毒する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！胃ろうの周囲の皮膚は、石けんとぬるま湯で洗って、清潔に保つのが基本なんだ。1は、発赤がある場合は、医療職に報告する。2は、ボタン型は回転させるかどうかは、医療職の指示による。3は、歩行を避ける必要はない。5は、注入前の消毒は不要だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-106","examYear":"2026","examRound":"38","questionNumber":106,"category":"介護過程","questionText":"次のうち、介護過程における生活課題への対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職が望む支援を実現すること"},{"id":"2","text":"利用者が望む暮らしを実現すること"},{"id":"3","text":"他職種が望む連携を実現すること"},{"id":"4","text":"家族が望む経済状況を実現すること"},{"id":"5","text":"施設が望む運営を実現すること"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護過程で、生活課題に対応する目的は、利用者が望む暮らしを実現することなんだ。1は介護福祉職、3は他職種、4は家族、5は施設の望みで、利用者の望みが中心ではないから、ちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-107","examYear":"2026","examRound":"38","questionNumber":107,"category":"介護過程","questionText":"次の記述のうち、短期目標に関する説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職の介護目標を設定する。"},{"id":"2","text":"利用者の1年後の状態を記載する。"},{"id":"3","text":"利用者の家族を主体にして表現する。"},{"id":"4","text":"アセスメントに基づく利用者の具体的な生活課題から検討する。"},{"id":"5","text":"目標達成時の介護福祉職の満足度を記載する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！短期目標は、アセスメントにもとづいた、利用者の具体的な生活課題から検討して、達成できそうな期間で立てるんだ。1は、介護福祉職ではなく利用者を主語にする。2は、1年後は長期目標。3は、家族ではなく利用者を主体にする。5は、職員の満足度は、目標にはならないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-108","examYear":"2026","examRound":"38","questionNumber":108,"category":"介護過程","questionText":"次の記述のうち、介護計画の実施に関するものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の実践状況は評価日にまとめて記録する。"},{"id":"2","text":"介護福祉職が結果に満足できるまで実践を続ける。"},{"id":"3","text":"介護福祉職の実践経験を積むことを目的にする。"},{"id":"4","text":"他職種が立案した介護計画をチームで実践する。"},{"id":"5","text":"利用者に支援内容を説明して同意を得る。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護計画を実施するときは、利用者に支援内容を説明して、同意を得たうえで行うんだ。1は、実施状況は、そのつど記録する。2は、職員の満足ではなく、目標の達成が基準。3は、職員の経験のためではない。4は、介護計画は、介護福祉職が立案し、チームで実践するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-109","examYear":"2026","examRound":"38","questionNumber":109,"category":"介護過程","questionText":"次のうち、サービス担当者会議にサービス管理責任者が出席する目的として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"個別支援計画の取り組みの報告"},{"id":"2","text":"障害支援区分の判定"},{"id":"3","text":"支給が必要かどうかの決定"},{"id":"4","text":"サービス等利用計画の説明"},{"id":"5","text":"相談支援専門員への個別支援計画作成の指示"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！サービス担当者会議では、サービス管理責任者が、個別支援計画にもとづく取り組みの状況を報告して、関係者と情報共有するんだ。2の障害支援区分の判定は、市町村。3の支給決定は、市町村。4のサービス等利用計画は、相談支援専門員が説明し、5は、指示する立場ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-110","examYear":"2026","examRound":"38","questionNumber":110,"category":"介護過程","questionText":"次の事例を読んで、問題110、問題111について答えなさい。\n〔事  例〕\nＡさん（78歳、女性、要介護1）は、軽度の認知症（dementia）があり、通所介護（デイサービス）を利用しながら一人暮らしをしている。一人娘が近くに住んでいる。最近、近所の人から娘に、「決められた日以外にごみを出しているので、そっと片付けているの」と連絡があった。\n翌日、娘がＡさんの自宅に行くと、部屋の中に弁当の空の容器がそのまま残されていた。心配した娘が同居を勧めたが、Ａさんは、「これからもこの家からデイサービスに通いたい」と強い口調で言った。話し合いの結果、娘が夕方に様子を見に行くことになった。\nＡさんは、通所介護（デイサービス）を休むことなく利用していたが、ある日の迎えのとき、担当の介護福祉職に、「今日は行きたくない」と言って利用を拒否した。娘が理由を聞くと、「クイズの時間になると利用者のＢさんに、あなたの答えはいつも間違えていると何度も注意される。情けない・・・」と話した。娘はＡさんの様子を介護福祉職に伝えた。\n次のうち、Ａさんのニーズとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"娘の家で同居すること"},{"id":"2","text":"自宅での生活を続けること"},{"id":"3","text":"通所介護（デイサービス）を休めること"},{"id":"4","text":"弁当のメニューを変更すること"},{"id":"5","text":"ごみ出しを近所の人に任せること"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ａさんは、「これからもこの家からデイサービスに通いたい」と強く言っているよね。だから、Ａさんのニーズは、自宅での生活を続けることなんだ。1は、娘の希望で、3は、Ｂさんとの関係が原因の一時的な気持ちで、4と5は、Ａさんが望んでいる内容ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-111","examYear":"2026","examRound":"38","questionNumber":111,"category":"介護過程","questionText":"次の事例を読んで、問題110、問題111について答えなさい。\n〔事  例〕\nＡさん（78歳、女性、要介護1）は、軽度の認知症（dementia）があり、通所介護（デイサービス）を利用しながら一人暮らしをしている。一人娘が近くに住んでいる。最近、近所の人から娘に、「決められた日以外にごみを出しているので、そっと片付けているの」と連絡があった。\n翌日、娘がＡさんの自宅に行くと、部屋の中に弁当の空の容器がそのまま残されていた。心配した娘が同居を勧めたが、Ａさんは、「これからもこの家からデイサービスに通いたい」と強い口調で言った。話し合いの結果、娘が夕方に様子を見に行くことになった。\nＡさんは、通所介護（デイサービス）を休むことなく利用していたが、ある日の迎えのとき、担当の介護福祉職に、「今日は行きたくない」と言って利用を拒否した。娘が理由を聞くと、「クイズの時間になると利用者のＢさんに、あなたの答えはいつも間違えていると何度も注意される。情けない・・・」と話した。娘はＡさんの様子を介護福祉職に伝えた。\nＡさんの娘から連絡を受けた通所介護（デイサービス）では、介護過程の再アセスメントをすることになった。\n次のうち、Ａさんの再アセスメントで重視すべき情報として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"通所介護（デイサービス）を利用しない日の過ごし方"},{"id":"2","text":"通所介護（デイサービス）での様子"},{"id":"3","text":"通所介護（デイサービス）の利用継続に関する娘の意見"},{"id":"4","text":"通所介護（デイサービス）の迎えを担当した介護福祉職の印象"},{"id":"5","text":"通所介護（デイサービス）以外のサービスを利用することへの意向"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ａさんは、Ｂさんに注意されて、デイサービスに行きたくないと言っているんだ。再アセスメントでは、まずデイサービスでの、Ａさんの様子や、Ｂさんとのかかわりを具体的に確認することが大切だよ。1、3、4、5は、今回の課題の原因を直接つかむ情報ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-112","examYear":"2026","examRound":"38","questionNumber":112,"category":"介護過程","questionText":"次の事例を読んで、問題112、問題113について答えなさい。\n〔事  例〕\nＡさん（50歳、男性、障害支援区分3）は、中度の知的障害がある。身体機能に問題はないが、遂行機能に障害がある。短い言葉での意思表示はできる。両親は亡くなっている。姉が近くに住んでいるが、同居は難しく、共同生活援助（グループホーム）へ入居した。入居時に短期目標を「生活のリズムを整える」と設定し、順調に進んでいた。日中は就労継続支援Ｂ型事業所に通っている。\n共同生活援助（グループホーム）の生活に慣れてきた頃、Ａさんは日中活動を休むようになった。心配した生活支援員が居室を訪ねると、Ａさんが、「昨日も、遊びに来た隣室の友人が、散らかっている部屋を見て笑った。前はきれいにできていたのに」と自信をなくしている様子であった。\n生活支援員がＡさんの居室を確認すると、趣味で集めているアニメグッズや衣服が増えていて、きれいにしていた自室内に散乱していた。\n次のうち、日中活動を休むようになったＡさんの状態を理解するために必要な情報として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ａさんの姉の家族構成"},{"id":"2","text":"隣室の友人がＡさんの部屋に行った時間"},{"id":"3","text":"Ａさんが自信をなくした理由"},{"id":"4","text":"生活支援員がＡさんの部屋を訪ねた心情"},{"id":"5","text":"Ａさんが隣室の友人と遊ぶことになった理由"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ａさんが日中活動を休むようになったのは、部屋を笑われて、自信をなくしたことがきっかけなんだ。だから、Ａさんが自信をなくした理由を知ることが、状態を理解するうえで必要だよ。1の姉の家族構成、2の友人が来た時間、4の生活支援員の心情、5の遊ぶことになった理由は、優先度が低いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-113","examYear":"2026","examRound":"38","questionNumber":113,"category":"介護過程","questionText":"次の事例を読んで、問題112、問題113について答えなさい。\n〔事  例〕\nＡさん（50歳、男性、障害支援区分3）は、中度の知的障害がある。身体機能に問題はないが、遂行機能に障害がある。短い言葉での意思表示はできる。両親は亡くなっている。姉が近くに住んでいるが、同居は難しく、共同生活援助（グループホーム）へ入居した。入居時に短期目標を「生活のリズムを整える」と設定し、順調に進んでいた。日中は就労継続支援Ｂ型事業所に通っている。\n共同生活援助（グループホーム）の生活に慣れてきた頃、Ａさんは日中活動を休むようになった。心配した生活支援員が居室を訪ねると、Ａさんが、「昨日も、遊びに来た隣室の友人が、散らかっている部屋を見て笑った。前はきれいにできていたのに」と自信をなくしている様子であった。\n生活支援員がＡさんの居室を確認すると、趣味で集めているアニメグッズや衣服が増えていて、きれいにしていた自室内に散乱していた。\n後日、カンファレンスが開かれ、短期目標についての見直しが検討された。次の記述のうち、見直された短期目標として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"趣味を変更する。"},{"id":"2","text":"現在の自室の状態を維持する。"},{"id":"3","text":"衣服を部屋の隅に寄せる。"},{"id":"4","text":"日中活動の事業所を変更する。"},{"id":"5","text":"自室を整理整頓する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、「前はきれいにできていたのに」と、片付けたい気持ちがあるんだね。だから、見直した短期目標は、自室を整理整頓することがぴったりだよ。1は、趣味を変えるのは、本人の意思を無視している。2は、散らかったままでよいことになる。3は、その場しのぎで、4は、日中活動の場は、休む原因ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-114","examYear":"2026","examRound":"38","questionNumber":114,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＡさん（66歳、女性）は、一人息子と二人で暮らしている。会社の趣味サークルや地域活動に熱心に参加してきた。半年前に、長年勤めた仕事を定年退職して、継続雇用で週2日の勤務になった。その頃から不眠を訴え、疲れやすく気持ちが落ち込む日が増えてきた。しばらくすると、睡眠中に大声をあげたり、息子の部屋までふらふらと歩いてきたり、自室のカーテンの花柄が動いて怖いと話したりするようになった。近隣の大学病院を受診した結果、手足の震え、小刻みな歩行、顔のこわばりなどがみられ、レビー小体型認知症（dementia with Lewy bodies）の診断を受けた。\nＡさんは、趣味活動や自宅で息子と過ごすことを優先し、これからの生活を楽しみたいと考えて、仕事を辞めた。そして、安全に歩く力を維持するために介護サービスを活用しようと考えた。Ａさんは要支援2の認定を受けて、介護予防通所リハビリテーションの利用を始めた。\nＡさんの手足の震えは、ある体内物質の影響によって生じている。\n次のうち、その体内物質に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"メラトニン（melatonin）"},{"id":"2","text":"ドーパミン（dopamine）"},{"id":"3","text":"アドレナリン（adrenaline）"},{"id":"4","text":"コルチゾール（cortisol）"},{"id":"5","text":"グルカゴン（glucagon）"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！レビー小体型認知症では、脳内のドーパミンが減って、手足の震えや、小刻みな歩行、顔のこわばりなど、パーキンソン症状が出るんだ。1のメラトニンは睡眠のリズム、3のアドレナリンは興奮や緊張、4のコルチゾールはストレスへの対応、5のグルカゴンは血糖値を上げるホルモンだよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-115","examYear":"2026","examRound":"38","questionNumber":115,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＡさん（66歳、女性）は、一人息子と二人で暮らしている。会社の趣味サークルや地域活動に熱心に参加してきた。半年前に、長年勤めた仕事を定年退職して、継続雇用で週2日の勤務になった。その頃から不眠を訴え、疲れやすく気持ちが落ち込む日が増えてきた。しばらくすると、睡眠中に大声をあげたり、息子の部屋までふらふらと歩いてきたり、自室のカーテンの花柄が動いて怖いと話したりするようになった。近隣の大学病院を受診した結果、手足の震え、小刻みな歩行、顔のこわばりなどがみられ、レビー小体型認知症（dementia with Lewy bodies）の診断を受けた。\nＡさんは、趣味活動や自宅で息子と過ごすことを優先し、これからの生活を楽しみたいと考えて、仕事を辞めた。そして、安全に歩く力を維持するために介護サービスを活用しようと考えた。Ａさんは要支援2の認定を受けて、介護予防通所リハビリテーションの利用を始めた。\nある日、送迎のときに、介護予防通所リハビリテーション事業所のＢ介護福祉職は、息子から、日々の症状に変動がある母を自宅で介護をするときにどのようなことに注意すべきか、と聞かれた。Ｂ介護福祉職は事業所で多職種ミーティングを行ってから返答することにした。\n次の記述のうち、Ｂ介護福祉職の息子への助言として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"視覚的環境からの影響を防ぐために、自室のカーテンを無地のものに変更する。"},{"id":"2","text":"下肢筋力を維持するために、毎日決まった時間に同じ運動をする。"},{"id":"3","text":"転倒を防止するために、Ａさんの外出の機会を減らす。"},{"id":"4","text":"夜間は部屋をできるだけ明るく照らすために、直接照明を用いる。"},{"id":"5","text":"着脱をしやすくするために、ボタン止めの衣服を使用する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！レビー小体型認知症では、幻視が特徴で、カーテンの花柄が動いて見えたりするんだ。だから、無地のカーテンに変えると、視覚への影響を防げるよ。2は、症状に変動があるので、その日の状態に合わせる。3は、外出を減らすと、筋力が落ちる。4は、直接照明はまぶしいので、間接照明にする。5は、ボタンは、手の震えで扱いにくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-116","examYear":"2026","examRound":"38","questionNumber":116,"category":"総合問題","questionText":"次の事例を読んで、問題114から問題116までについて答えなさい。\n〔事  例〕\nＡさん（66歳、女性）は、一人息子と二人で暮らしている。会社の趣味サークルや地域活動に熱心に参加してきた。半年前に、長年勤めた仕事を定年退職して、継続雇用で週2日の勤務になった。その頃から不眠を訴え、疲れやすく気持ちが落ち込む日が増えてきた。しばらくすると、睡眠中に大声をあげたり、息子の部屋までふらふらと歩いてきたり、自室のカーテンの花柄が動いて怖いと話したりするようになった。近隣の大学病院を受診した結果、手足の震え、小刻みな歩行、顔のこわばりなどがみられ、レビー小体型認知症（dementia with Lewy bodies）の診断を受けた。\nＡさんは、趣味活動や自宅で息子と過ごすことを優先し、これからの生活を楽しみたいと考えて、仕事を辞めた。そして、安全に歩く力を維持するために介護サービスを活用しようと考えた。Ａさんは要支援2の認定を受けて、介護予防通所リハビリテーションの利用を始めた。\nサービス利用開始から2か月後、担当介護支援専門員（介護福祉士）はモニタリングを行うために、Ａさんの自宅を訪れた。Ａさんは、「もっとほかの人と交流したいが、自宅で生活しながら利用できると安心だ。とにかく息子に心配をかけずに一緒に暮らしていきたい」と語った。\n息子は、「最近仕事が忙しくなり、今後泊まりの出張もあるので、リハビリ以外のサービスもうまく使ってほしい」と語った。\n次のうち、Ａさんに利用を勧めるサービスとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護予防認知症対応型共同生活介護（認知症高齢者グループホーム）"},{"id":"2","text":"日常生活自立支援事業"},{"id":"3","text":"訪問介護（ホームヘルプサービス）"},{"id":"4","text":"介護予防小規模多機能型居宅介護"},{"id":"5","text":"介護予防・生活支援サービス事業の通所型サービス"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんは、自宅で生活しながら利用できるサービスで、人との交流がしたい、息子は泊まりの出張もあるから、リハビリ以外のサービスも使いたいという希望があるんだね。介護予防小規模多機能型居宅介護は、通い、訪問、泊まりを組み合わせられて、ぴったりだよ。1は、自宅を離れる。2は、金銭管理の支援。3は、要支援では制限がある。5は、通所だけで、泊まりに対応できないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-117","examYear":"2026","examRound":"38","questionNumber":117,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＡさん（85歳、女性、要介護1）は、Ｂ住居型有料老人ホームで暮らしている。子どもはなく、親族もいない。Ａさんは現在、外部の事業所から訪問介護サービスを週2回利用している。Ａさんは駐車場を経営していて、毎月その収入がある。\n最近、Ｃ訪問介護員（ホームヘルパー）は、Ａさんの居室内の冷蔵庫の中に同じ食材がたくさん入っていることが多く、気になっていた。ある日、Ｃ訪問介護員（ホームヘルパー）がＡさんに尋ねると、「近所のスーパーに買い物に行くのが楽しみだが、冷蔵庫の中に何があるのか忘れてしまい、同じものばかり買ってしまう」と答えた。また、「今は、毎月振り込まれる駐車場収入の管理ができているが、今後管理できなくなることが不安だ」と話した。その後、Ａさんは、初期のアルツハイマー型認知症（dementia of the Alzheimer’s type）の診断を受けた。\n次のうち、Ａさんが不安に思っている駐車場収入の管理について、訪問介護事業所のサービス提供責任者がＡさんに提案する制度として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"成年後見制度"},{"id":"2","text":"生活保護制度"},{"id":"3","text":"老齢年金制度"},{"id":"4","text":"継続雇用制度"},{"id":"5","text":"後期高齢者医療制度"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ａさんは、初期のアルツハイマー型認知症で、今後、収入の管理ができなくなることを不安に思っているよね。判断能力が十分なうちに備える任意後見など、成年後見制度が、財産管理を支える制度として提案できるよ。2の生活保護、3の老齢年金、4の継続雇用、5の後期高齢者医療は、財産管理の制度ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-118","examYear":"2026","examRound":"38","questionNumber":118,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＡさん（85歳、女性、要介護1）は、Ｂ住居型有料老人ホームで暮らしている。子どもはなく、親族もいない。Ａさんは現在、外部の事業所から訪問介護サービスを週2回利用している。Ａさんは駐車場を経営していて、毎月その収入がある。\n最近、Ｃ訪問介護員（ホームヘルパー）は、Ａさんの居室内の冷蔵庫の中に同じ食材がたくさん入っていることが多く、気になっていた。ある日、Ｃ訪問介護員（ホームヘルパー）がＡさんに尋ねると、「近所のスーパーに買い物に行くのが楽しみだが、冷蔵庫の中に何があるのか忘れてしまい、同じものばかり買ってしまう」と答えた。また、「今は、毎月振り込まれる駐車場収入の管理ができているが、今後管理できなくなることが不安だ」と話した。その後、Ａさんは、初期のアルツハイマー型認知症（dementia of the Alzheimer’s type）の診断を受けた。\nその後、Ａさんは認知症（dementia）が進行することを心配し、介護支援専門員（ケアマネジャー）に相談して、同じ市内のＤ介護付き有料老人ホームに転居することになった。\n転居してから2年後、Ａさんの認知症（dementia）の症状は進行してきた。Ａさんの担当となったＥ介護福祉職はサービス担当者会議で、「現在、Ａさんの、認知症高齢者の日常生活自立度判定基準は、ランクⅢａと考えられる。そこで、このランクに合った介護計画を立案したい」と提案し、他職種の承諾を得た。\n次のうち、Ａさんの介護計画立案時にＥ介護福祉職が意識する、認知症高齢者の日常生活自立度判定基準Ⅲａに該当する状態として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"日常生活が自立している状態"},{"id":"2","text":"見守りがあれば自立できる状態"},{"id":"3","text":"日中を中心に意思疎通の困難さがみられ、介護を必要とする状態"},{"id":"4","text":"意思疎通の困難さが頻繁にみられ、常に介護を必要とする状態"},{"id":"5","text":"専門医療の導入が必要な状態"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！認知症高齢者の日常生活自立度Ⅲａは、日中を中心に、意思疎通の難しさがあり、介護が必要な状態なんだ。1は自立、2はⅡ、4はⅢb（夜間を中心に、または常に）、5はＭ（専門医療を必要とする）に当たるよ。ランクの内容を、まとめて覚えよう。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-119","examYear":"2026","examRound":"38","questionNumber":119,"category":"総合問題","questionText":"次の事例を読んで、問題117から問題119までについて答えなさい。\n〔事  例〕\nＡさん（85歳、女性、要介護1）は、Ｂ住居型有料老人ホームで暮らしている。子どもはなく、親族もいない。Ａさんは現在、外部の事業所から訪問介護サービスを週2回利用している。Ａさんは駐車場を経営していて、毎月その収入がある。\n最近、Ｃ訪問介護員（ホームヘルパー）は、Ａさんの居室内の冷蔵庫の中に同じ食材がたくさん入っていることが多く、気になっていた。ある日、Ｃ訪問介護員（ホームヘルパー）がＡさんに尋ねると、「近所のスーパーに買い物に行くのが楽しみだが、冷蔵庫の中に何があるのか忘れてしまい、同じものばかり買ってしまう」と答えた。また、「今は、毎月振り込まれる駐車場収入の管理ができているが、今後管理できなくなることが不安だ」と話した。その後、Ａさんは、初期のアルツハイマー型認知症（dementia of the Alzheimer’s type）の診断を受けた。\nＤ介護付き有料老人ホームに転居してから3年が経過した。Ａさんの認知症（dementia）の症状は、さらに進行してきた。Ｄ介護付き有料老人ホームでは、施設の方針として、新たにパーソン・センタード・ケアを取り入れることになった。\n次の記述のうち、Ｅ介護福祉職が介護計画を見直すときの方向性として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"認知症（dementia）の人の共通点に着目したケアマニュアルをつくる。"},{"id":"2","text":"認知症（dementia）を治療する。"},{"id":"3","text":"認知症（dementia）の人のその人らしさを支える。"},{"id":"4","text":"認知症（dementia）の人を特別な存在として保護する。"},{"id":"5","text":"行動・心理症状（ＢＰＳＤ）をなくす。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！パーソン・センタード・ケアは、認知症の人を、一人の人として尊重して、その人らしさを支えるケアの考え方なんだ。1は、共通点ではなく、個別性を大切にする。2は、治療は、医療の役割。4は、特別な存在として保護せず、対等に接する。5は、ＢＰＳＤをなくすことだけが目的ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-120","examYear":"2026","examRound":"38","questionNumber":120,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＡさん（42歳、男性）は、知的障害がある。父親（72歳）と二人暮らしをしている。半年前、Ａさんに血便がみられたため病院を受診したところ、大腸がん（colorectal cancer）と診断され、Ｓ状結腸ストーマを造設した。パウチの交換に支援が必要となり、退院後は父親が自宅で介護をしていた。父親の介護負担が大きくなったため、居宅介護（ホームヘルプサービス）を利用することになった。\n次のうち、Ａさんの正常時の便の性状として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"水様から粥状｛じゅくじょう｝"},{"id":"2","text":"流動状から液状"},{"id":"3","text":"半流動から粥状｛じゅくじょう｝"},{"id":"4","text":"泥状から軟便"},{"id":"5","text":"軟便から固形状"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｓ状結腸ストーマは、大腸の終わりに近い部分なので、便は水分が吸収されて、軟便から固形に近い性状なんだ。1は、上行結腸ストーマ（水様から粥状）、2は回腸ストーマ、3は横行結腸ストーマの便に近いよ。ストーマの位置と、便の性状は、セットで覚えよう。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-121","examYear":"2026","examRound":"38","questionNumber":121,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＡさん（42歳、男性）は、知的障害がある。父親（72歳）と二人暮らしをしている。半年前、Ａさんに血便がみられたため病院を受診したところ、大腸がん（colorectal cancer）と診断され、Ｓ状結腸ストーマを造設した。パウチの交換に支援が必要となり、退院後は父親が自宅で介護をしていた。父親の介護負担が大きくなったため、居宅介護（ホームヘルプサービス）を利用することになった。\nある日、訪問介護員（ホームヘルパー）にＡさんから、「今度、父親と温泉に行くことになったが、便のにおいが気になる」と相談があった。\n次のうち、訪問介護員（ホームヘルパー）がＡさんに勧める食品として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"チーズ"},{"id":"2","text":"たまねぎ"},{"id":"3","text":"ヨーグルト"},{"id":"4","text":"にら"},{"id":"5","text":"アスパラガス"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ヨーグルトは、腸内環境を整えて、便のにおいをやわらげる効果があるとされているんだ。1のチーズも発酵食品だけれど、ここでは、においが気になる食品ではないヨーグルトが適切だよ。2のたまねぎ、4のにら、5のアスパラガスは、においが強くなる食品として、注意が必要なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-122","examYear":"2026","examRound":"38","questionNumber":122,"category":"総合問題","questionText":"次の事例を読んで、問題120から問題122までについて答えなさい。\n〔事  例〕\nＡさん（42歳、男性）は、知的障害がある。父親（72歳）と二人暮らしをしている。半年前、Ａさんに血便がみられたため病院を受診したところ、大腸がん（colorectal cancer）と診断され、Ｓ状結腸ストーマを造設した。パウチの交換に支援が必要となり、退院後は父親が自宅で介護をしていた。父親の介護負担が大きくなったため、居宅介護（ホームヘルプサービス）を利用することになった。\nある日、訪問介護員（ホームヘルパー）がＡさんの自宅を訪問したところ、Ａさんの父親から、「地震のニュースを見たら、知的障害があり、ストーマの管理が必要な息子に対する災害時の対応が心配になった」と相談があった。訪問介護員（ホームヘルパー）は、相談支援専門員に状況を報告し、相談支援専門員とともにほかの利用者家族に確認したところ、同様に災害時の不安を感じている親が多く、この地域では個別避難計画の作成が遅れていることがわかった。そこで、訪問介護員（ホームヘルパー）はこの課題を地域の課題としてとらえ、サービス提供責任者や相談支援専門員とともに対応することを確認した。\n次のうち、この地域課題の検討を働きかける場として、最も適切なものを1つ選びなさい。\n（注）  「協議会」とは、障害者の日常生活及び社会生活を総合的に支援するための法律第89条の3第1項に規定するものである。","choices":[{"id":"1","text":"協議会"},{"id":"2","text":"運営適正化委員会"},{"id":"3","text":"介護保険審査会"},{"id":"4","text":"障害者政策委員会"},{"id":"5","text":"地方更生保護委員会"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！協議会は、障害者総合支援法にもとづいて、地域の関係者が集まり、地域の課題を共有して、解決策を話し合う場なんだ。個別避難計画の遅れは、まさに地域課題だね。2の運営適正化委員会は、苦情の解決、3の介護保険審査会は、介護保険の不服申立て、4の障害者政策委員会は国の会議、5の地方更生保護委員会は、仮釈放などを扱う機関だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-123","examYear":"2026","examRound":"38","questionNumber":123,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＡさん（50歳、男性、障害支援区分4）は、1年前の交通事故の後遺症で、右片麻痺｛みぎかたまひ｝、高次脳機能障害（higher brain dysfunction）、失語症（aphasia）となった。現在は障害者支援施設で生活している。日中は、車いすに座って過ごしているが、すぐに右肩が下がり上半身は右へ傾いた姿勢になる。ある日、Ｂ介護福祉職がＡさんに姿勢の傾きを直す方法を伝えようとすると、Ａさんは大声でどなり、物を投げた。Ｂ介護福祉職は、以前からＡさんとのコミュニケーションに悩んでいたため、Ｃ介護主任に相談することにした。Ｃ介護主任の問いかけに答えるなかで、Ｂ介護福祉職は自分自身の言動を振り返ることができ、Ａさんに伝わらない焦りと、子どもに言い聞かせるような口調が、Ａさんの感情を害していたことに気づいた。その後、コミュニケーション方法を工夫し、Ａさんに姿勢の傾きを直す方法を説明し、同意を得ることができた。\n毎週、Ａさんは妻との面会を楽しみにしている。しかし、妻はＡさんの将来に不安を感じて、Ｂ介護福祉職に、「夫の障害について、情報交換や勉強がしたい。そのようなところがあれば紹介してほしい」と相談した。\n次のうち、Ｃ介護主任がＢ介護福祉職への対応に用いた手法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"コンサルテーション（consultation）"},{"id":"2","text":"コーチング（coaching）"},{"id":"3","text":"フォロワーシップ（followership）"},{"id":"4","text":"ティーチング（teaching）"},{"id":"5","text":"メンバーシップ（membership）"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｃ介護主任は、Ｂ介護福祉職に問いかけて、自分自身で振り返り、気づきを得られるようにしたんだね。これは、コーチングという手法だよ。1のコンサルテーションは、専門家に助言を求める、3のフォロワーシップは、リーダーを支える姿勢、4のティーチングは、知識や技術を教える、5のメンバーシップは、組織の一員としての役割だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-124","examYear":"2026","examRound":"38","questionNumber":124,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＡさん（50歳、男性、障害支援区分4）は、1年前の交通事故の後遺症で、右片麻痺｛みぎかたまひ｝、高次脳機能障害（higher brain dysfunction）、失語症（aphasia）となった。現在は障害者支援施設で生活している。日中は、車いすに座って過ごしているが、すぐに右肩が下がり上半身は右へ傾いた姿勢になる。ある日、Ｂ介護福祉職がＡさんに姿勢の傾きを直す方法を伝えようとすると、Ａさんは大声でどなり、物を投げた。Ｂ介護福祉職は、以前からＡさんとのコミュニケーションに悩んでいたため、Ｃ介護主任に相談することにした。Ｃ介護主任の問いかけに答えるなかで、Ｂ介護福祉職は自分自身の言動を振り返ることができ、Ａさんに伝わらない焦りと、子どもに言い聞かせるような口調が、Ａさんの感情を害していたことに気づいた。その後、コミュニケーション方法を工夫し、Ａさんに姿勢の傾きを直す方法を説明し、同意を得ることができた。\n毎週、Ａさんは妻との面会を楽しみにしている。しかし、妻はＡさんの将来に不安を感じて、Ｂ介護福祉職に、「夫の障害について、情報交換や勉強がしたい。そのようなところがあれば紹介してほしい」と相談した。\nＢ介護福祉職は、Ａさんが車いすで良肢位を保つことができるように、クッションを使用することにした。まず、Ｂ介護福祉職はＡさんの上半身を起こし深く座り直してもらった。\n次のうち、Ｂ介護福祉職がクッションを挿入する位置として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"背中とバックサポートの間"},{"id":"2","text":"左大腿部｛ひだりだいたいぶ｝と座面の間"},{"id":"3","text":"両下腿｛りょうかたい｝とレッグサポートの間"},{"id":"4","text":"右大腿部｛みぎだいたいぶ｝と左大腿部｛ひだりだいたいぶ｝の間"},{"id":"5","text":"右上肢と右アームサポートの間"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、右片麻痺で、右肩が下がって右へ傾くよね。右上肢と右アームサポートの間にクッションを入れると、麻痺のある右腕を支えて、姿勢の傾きを防ぎ、良肢位を保てるよ。1は、深く座り直したので、背中の空間はない。2、3、4は、右への傾きを直す位置ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2026-38-125","examYear":"2026","examRound":"38","questionNumber":125,"category":"総合問題","questionText":"次の事例を読んで、問題123から問題125までについて答えなさい。\n〔事  例〕\nＡさん（50歳、男性、障害支援区分4）は、1年前の交通事故の後遺症で、右片麻痺｛みぎかたまひ｝、高次脳機能障害（higher brain dysfunction）、失語症（aphasia）となった。現在は障害者支援施設で生活している。日中は、車いすに座って過ごしているが、すぐに右肩が下がり上半身は右へ傾いた姿勢になる。ある日、Ｂ介護福祉職がＡさんに姿勢の傾きを直す方法を伝えようとすると、Ａさんは大声でどなり、物を投げた。Ｂ介護福祉職は、以前からＡさんとのコミュニケーションに悩んでいたため、Ｃ介護主任に相談することにした。Ｃ介護主任の問いかけに答えるなかで、Ｂ介護福祉職は自分自身の言動を振り返ることができ、Ａさんに伝わらない焦りと、子どもに言い聞かせるような口調が、Ａさんの感情を害していたことに気づいた。その後、コミュニケーション方法を工夫し、Ａさんに姿勢の傾きを直す方法を説明し、同意を得ることができた。\n毎週、Ａさんは妻との面会を楽しみにしている。しかし、妻はＡさんの将来に不安を感じて、Ｂ介護福祉職に、「夫の障害について、情報交換や勉強がしたい。そのようなところがあれば紹介してほしい」と相談した。\n妻の相談を受けたＢ介護福祉職がサービス管理責任者に報告をしたところ、ある社会資源を紹介することになった。\n次のうち、Ｂ介護福祉職が妻に紹介した社会資源として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"福祉事務所"},{"id":"2","text":"公共職業安定所（ハローワーク）"},{"id":"3","text":"家族会"},{"id":"4","text":"地域包括支援センター"},{"id":"5","text":"地域障害者職業センター"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！家族会は、同じ障害のある人の家族が集まって、情報交換をしたり、学び合ったりする場なんだ。妻の希望にぴったりだね。1の福祉事務所は、福祉の手続きの窓口、2のハローワークと、5の地域障害者職業センターは、就労の支援、4の地域包括支援センターは、高齢者の相談機関だよ。","source":"公益財団法人 社会福祉振興・試験センター 第38回（令和7年度）介護福祉士国家試験; 問題: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/listen_k_pm_38.html; 正答: https://www.sssc.or.jp/kaigo/past_exam/pdf/no38/k_kijun_seitou.pdf","keywords":[],"needsLegalReview":true},{"id":"2023-35-001","examYear":"2023","examRound":"35","questionNumber":1,"category":"人間の尊厳と自立","questionText":"利用者の生活の質（ＱＯＬ）を高めるための介護実践に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"日常生活動作の向上を必須とする。"},{"id":"2","text":"利用者の主観的評価では，介護福祉職の意向を重視する。"},{"id":"3","text":"介護実践は，家族のニーズに応じて行う。"},{"id":"4","text":"福祉用具の活用は，利用者と相談しながら進める。"},{"id":"5","text":"価値の基準は，全ての利用者に同じものを用いる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！福祉用具を使うときは、利用者と相談しながら進めて、本人の意向を尊重するのが大切なんだ。1は、日常生活動作の向上が必須ではなく、その人らしい生活が大切。2は、主観的評価は、利用者自身の思いを重視する。3は、家族ではなく、利用者のニーズに応じる。5は、価値観は、人それぞれちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-002","examYear":"2023","examRound":"35","questionNumber":2,"category":"人間の尊厳と自立","questionText":"Ａさん（25歳，男性，障害支援区分3）は，網膜色素変性症（retinitis pigmentosa）で，移動と外出先での排泄時に介助が必要である。同行援護を利用しながら，自宅で母親と暮らしている。音楽が好きなＡさんは合唱サークルに入会していて，月1回の練習に参加している。合唱コンクールが遠方で行われることになった。同行援護を担当する介護福祉職は，Ａさんから，「コンクールに出演したいが，初めての場所に行くことが心配である」と相談を受けた。\n介護福祉職のＡさんへの対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"合唱コンクールへの参加を諦めるように話す。"},{"id":"2","text":"合唱サークルの仲間に移動の支援を依頼するように伝える。"},{"id":"3","text":"一緒に交通経路や会場内の状況を確認する。"},{"id":"4","text":"合唱コンクールに参加するかどうかは，母親に判断してもらうように促す。"},{"id":"5","text":"日常生活自立支援事業の利用を勧める。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ａさんは、コンクールに出たいけれど、初めての場所が心配なんだね。一緒に交通経路や会場内の状況を確認すると、不安が和らいで、参加につながるよ。1は、本人の意欲を奪っている。2は、同行援護の役割を放棄している。4は、本人の意思を尊重していない。5は、日常生活自立支援事業は、今回の相談とは関係ないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-003","examYear":"2023","examRound":"35","questionNumber":3,"category":"人間関係とコミュニケーション","questionText":"ストレス対処行動の一つである問題焦点型コーピングに当てはまる行動として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"趣味の活動をして気分転換する。"},{"id":"2","text":"トラブルの原因に働きかけて解決しようとする。"},{"id":"3","text":"運動して身体を動かしストレスを発散する。"},{"id":"4","text":"好きな音楽を聴いてリラックスする。"},{"id":"5","text":"「トラブルも良い経験だ」と自己の意味づけを変える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！問題焦点型コーピングは、ストレスの原因そのものに働きかけて、解決しようとする方法なんだ。1、3、4は、気分転換やリラックスで、気持ちを整える情動焦点型の方法。5は、自分の受け止め方を変える、認知的な方法で、これも情動焦点型に近いよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-004","examYear":"2023","examRound":"35","questionNumber":4,"category":"人間関係とコミュニケーション","questionText":"Ｂさん（80歳，女性）は，介護老人保健施設に入所が決まった。今日はＢさんが施設に入所する日であり，Ｃ介護福祉職が担当者になった。Ｃ介護福祉職は，初対面のＢさんとの信頼関係の形成に向けて取り組んだ。\nＣ介護福祉職のＢさんへの対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自発的な関わりをもつことを控えた。"},{"id":"2","text":"真正面に座って面談をした。"},{"id":"3","text":"自分から進んで自己紹介をした。"},{"id":"4","text":"終始，手を握りながら話をした。"},{"id":"5","text":"孫のような口調で語りかけた。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！初対面のＢさんとの信頼関係をつくるために、自分から進んで自己紹介をするのが、基本の対応なんだ。1は、関わりを控えると、不安が続く。2は、真正面は、緊張させることがある。4は、終始手を握るのは、不快に感じることもある。5は、孫のような口調は、敬意に欠けるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-005","examYear":"2023","examRound":"35","questionNumber":5,"category":"人間関係とコミュニケーション","questionText":"介護老人福祉施設は，利用者とその家族，地域住民等との交流を目的とした夏祭りを開催した。夏祭りには，予想を超えた来客があり，「違法駐車が邪魔で困る」という苦情が近隣の住民から寄せられた。そこで，次の夏祭りの運営上の改善に向けて職員間で話し合い，対応案を作成した。\n次の対応案のうち，ＰＤＣＡサイクルのアクション（Action）に当たるものとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"近隣への騒音の影響について調べる。"},{"id":"2","text":"苦情を寄せた住民に話を聞きに行く。"},{"id":"3","text":"夏祭りの感想を利用者から聞く。"},{"id":"4","text":"来客者用の駐車スペースを確保する。"},{"id":"5","text":"周辺の交通量を調べる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ＰＤＣＡサイクルのアクション（Action）は、評価をもとにした、改善のための行動なんだ。来客者用の駐車スペースを確保するのは、苦情を受けての、具体的な改善策だね。1、2、3、5は、原因や状況を調べたり、評価したりする、チェック（Check）の段階だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-006","examYear":"2023","examRound":"35","questionNumber":6,"category":"人間関係とコミュニケーション","questionText":"Ｄ介護福祉職は，利用者に対して行っている移乗の介護がうまくできず，技術向上を目的としたＯＪＴを希望している。\n次のうち，Ｄ介護福祉職に対して行うＯＪＴとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"専門書の購入を勧める。"},{"id":"2","text":"外部研修の受講を提案する。"},{"id":"3","text":"先輩職員が移乗の介護に同行して指導する。"},{"id":"4","text":"職場外の専門家に相談するように助言する。"},{"id":"5","text":"苦手な移乗の介護は控えるように指示する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ＯＪＴは、職場で、仕事をしながら行う教育のことなんだ。先輩職員が、移乗の介護に同行して指導するのは、その例だよ。1の専門書、2の外部研修、4の外部の専門家への相談は、職場外で行う学習（Off-JT）や、自己学習だね。5は、苦手を避けるだけでは、技術は向上しないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-007","examYear":"2023","examRound":"35","questionNumber":7,"category":"社会の理解","questionText":"社会福祉法に基づく，都道府県や市町村において地域福祉の推進を図ることを目的とする団体として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"特定非営利活動法人（ＮＰＯ法人）"},{"id":"2","text":"隣保館"},{"id":"3","text":"地域包括支援センター"},{"id":"4","text":"基幹相談支援センター"},{"id":"5","text":"社会福祉協議会"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！社会福祉協議会は、社会福祉法にもとづいて、都道府県や市町村に置かれ、地域福祉の推進を図る団体なんだ。1のＮＰＯ法人は、特定非営利活動促進法、2の隣保館は、地域の福祉の拠点、3は、介護保険法、4は、障害者総合支援法にもとづく機関だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-008","examYear":"2023","examRound":"35","questionNumber":8,"category":"社会の理解","questionText":"近年，人と人，人と社会とがつながり，一人ひとりが生きがいや役割をもち，助け合いながら暮らしていくことのできる，包摂的なコミュニティ，地域や社会を創るという考え方が示されている。\nこの考え方を表すものとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ナショナルミニマム（national minimum）"},{"id":"2","text":"バリアフリー社会"},{"id":"3","text":"介護の社会化"},{"id":"4","text":"生涯現役社会"},{"id":"5","text":"地域共生社会"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！地域共生社会は、人と人、人と社会がつながって、一人ひとりが生きがいや役割をもち、助け合いながら暮らせる社会をめざす考え方なんだ。1のナショナルミニマムは、国が保障する最低限度の生活、2のバリアフリー社会は、障壁のない社会、3の介護の社会化は、介護を社会全体で支えること、4の生涯現役社会は、年齢に関係なく活躍できる社会だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-009","examYear":"2023","examRound":"35","questionNumber":9,"category":"社会の理解","questionText":"我が国の社会保障制度の基本となる，1950年（昭和25年）の社会保障制度審議会による「社会保障制度に関する勧告」の内容として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"生活困窮者自立支援法の制定の提言"},{"id":"2","text":"社会保障制度を，社会保険，国家扶助，公衆衛生及び医療，社会福祉で構成"},{"id":"3","text":"介護保険制度の創設の提言"},{"id":"4","text":"保育所の待機児童ゼロ作戦の提言"},{"id":"5","text":"介護分野におけるＩＣＴ等の活用とビッグデータの整備"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！1950年の勧告は、社会保障制度を、社会保険、国家扶助、公衆衛生及び医療、社会福祉で構成するとしたんだ。1は、生活困窮者自立支援法は2013年。3の介護保険制度の創設は、2000年。4の待機児童ゼロ作戦は、2001年ごろ。5は、近年の介護分野の課題で、この勧告とは関係ないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-010","examYear":"2023","examRound":"35","questionNumber":10,"category":"社会の理解","questionText":"Ｅさん（75歳，女性，要介護2）は，訪問介護（ホームヘルプサービス）を利用している。最近，Ｅさんの認知症（dementia）が進行して，家での介護が困難になり，介護老人福祉施設の申込みをすることにした。家族が訪問介護員（ホームヘルパー）に相談したところ，まだ要介護認定の有効期間が残っていたが，要介護状態区分の変更の申請ができることがわかった。\n家族が区分変更するときの申請先として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"介護保険の保険者"},{"id":"2","text":"後期高齢者医療広域連合"},{"id":"3","text":"介護保険審査会"},{"id":"4","text":"国民健康保険団体連合会"},{"id":"5","text":"運営適正化委員会"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！要介護状態区分の変更の申請は、介護保険の保険者である市町村（特別区を含む）に行うんだ。2は、後期高齢者医療広域連合は、医療保険の運営主体。3は、介護保険審査会は、不服申立てを扱う。4は、国民健康保険団体連合会は、介護報酬の審査などを行う。5は、運営適正化委員会は、苦情を解決する機関だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-011","examYear":"2023","examRound":"35","questionNumber":11,"category":"社会の理解","questionText":"Ｆさん（19歳，女性，身体障害者手帳2級）は，先天性の聴覚障害がある。Ｆさんは大学生で，授業のときは手話通訳者が配置されている。Ｆさんは筆記による定期試験を受けることになり，試験実施に関する配慮を大学に申し出た。\n次の記述のうち，Ｆさんの申し出を踏まえた合理的配慮として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"受験時間を延長する。"},{"id":"2","text":"試験問題の文字を拡大する。"},{"id":"3","text":"テキストの持ち込みを許可する。"},{"id":"4","text":"試験監督者が口頭で説明する内容を書面で渡す。"},{"id":"5","text":"問題を読み上げる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！聴覚障害のあるＦさんには、試験監督者が口頭で説明する内容を、書面で渡すことが、情報を得やすくする合理的配慮なんだ。1の受験時間の延長、2の文字の拡大、3のテキストの持ち込み、5の問題の読み上げは、聴覚障害の特性への配慮としては、ふさわしくないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-012","examYear":"2023","examRound":"35","questionNumber":12,"category":"社会の理解","questionText":"我が国の「障害者権利条約」の批准（2014年（平成26年））に向けて行われた，障害者基本法の改正（2011年（平成23年））で新たに法律上に規定されたものとして，適切なものを1つ選びなさい。\n（注）「障害者権利条約」とは，国際連合の「障害者の権利に関する条約」のことである。","choices":[{"id":"1","text":"自立支援医療（精神通院医療）の開始"},{"id":"2","text":"共同生活援助（グループホーム）の制度化"},{"id":"3","text":"成年後見制度の創設"},{"id":"4","text":"社会的障壁の除去"},{"id":"5","text":"東京2020パラリンピック競技大会の開催"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！2011年の障害者基本法の改正では、障害のある人が日常生活や社会生活で受ける制限をなくすため、「社会的障壁の除去」が、新たに規定されたんだ。1の自立支援医療は2006年、2のグループホームの制度化は、1989年ごろ、3の成年後見制度は、2000年に創設、5のパラリンピックは、2021年に開催されたよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-013","examYear":"2023","examRound":"35","questionNumber":13,"category":"社会の理解","questionText":"次のうち，「障害者総合支援法」の介護給付を利用するときに，利用者が最初に市町村に行う手続きとして，適切なものを1つ選びなさい。\n（注）「障害者総合支援法」とは，「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。","choices":[{"id":"1","text":"支給申請"},{"id":"2","text":"認定調査"},{"id":"3","text":"審査会の開催"},{"id":"4","text":"障害支援区分の認定"},{"id":"5","text":"サービス等利用計画の作成"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！障害者総合支援法の介護給付を利用するときは、最初に、市町村に、支給申請を行うんだ。そのあと、認定調査、審査会の開催、障害支援区分の認定、サービス等利用計画案の作成などの順に進むよ。手続きの流れを、しっかり覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-014","examYear":"2023","examRound":"35","questionNumber":14,"category":"社会の理解","questionText":"「障害者総合支援法」の居宅介護を利用したときの利用者負担の考え方として，最も適切なものを1つ選びなさい。\n（注）「障害者総合支援法」とは，「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。","choices":[{"id":"1","text":"利用したサービスの種類や量に応じて負担する。"},{"id":"2","text":"利用者の負担能力に応じて負担する。"},{"id":"3","text":"利用したサービス費用の一定の割合を負担する。"},{"id":"4","text":"利用したサービス費用の全額を負担する。"},{"id":"5","text":"利用者は負担しない。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！障害者総合支援法のサービスの利用者負担は、所得に応じて、上限額が決まる、応能負担の考え方なんだ。1は、利用したサービスの量に応じて負担する、応益負担のこと。3は、費用の一定割合を負担する定率負担。4は全額負担、5は負担なしで、いずれも居宅介護の考え方とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-015","examYear":"2023","examRound":"35","questionNumber":15,"category":"社会の理解","questionText":"「個人情報保護法」に基づくプライバシー保護に関する次の記述のうち，最も適切なものを1つ選びなさい。\n（注）「個人情報保護法」とは，「個人情報の保護に関する法律」のことである。","choices":[{"id":"1","text":"電磁的記録は，個人情報には含まれない。"},{"id":"2","text":"マイナンバーなどの個人識別符号は，個人情報ではない。"},{"id":"3","text":"施設職員は，実習生に利用者の生活歴などを教えることは一切できない。"},{"id":"4","text":"個人情報を第三者に提供するときは，原則として本人の同意が必要である。"},{"id":"5","text":"自治会長は，本人の同意がなくても個人情報を入手できる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！個人情報を第三者に提供するときは、原則として、本人の同意が必要なんだ。1は、電磁的記録も、個人情報に含まれる。2は、マイナンバーなどの個人識別符号も、個人情報にあたる。3は、実習生には、必要な範囲で、教えることができる。5は、自治会長でも、本人の同意なしには、入手できないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-016","examYear":"2023","examRound":"35","questionNumber":16,"category":"社会の理解","questionText":"「高齢者虐待防止法」に関する次の記述のうち，最も適切なものを1つ選びなさい。\n（注）「高齢者虐待防止法」とは，「高齢者虐待の防止，高齢者の養護者に対する支援等に関する法律」のことである。","choices":[{"id":"1","text":"虐待が起こる場として，家庭，施設，病院の3つが規定されている。"},{"id":"2","text":"対象は，介護保険制度の施設サービス利用者とされている。"},{"id":"3","text":"徘徊しないように車いすに固定することは，身体拘束には当たらない。"},{"id":"4","text":"虐待を発見した養介護施設従事者には，通報する義務がある。"},{"id":"5","text":"虐待の認定は，警察署長が行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！高齢者虐待防止法では、虐待を発見した養介護施設従事者には、通報する義務があるんだ。1は、虐待が起こる場は、家庭（養護者）と、養介護施設などの2つ。2は、対象は、施設サービスの利用者に限らない。3は、車いすに固定するのは、身体拘束にあたる。5は、虐待の認定は、市町村が行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-017","examYear":"2023","examRound":"35","questionNumber":17,"category":"社会の理解","questionText":"発達障害のＧさん（38歳，男性）は，高校生の頃に不登校になり，ずっとアルバイトをしながら，統合失調症（schizophrenia）の母親（65歳，精神保健福祉手帳2級）を介護してきた。母親に認知症（dementia）が疑われるようになったが，これからも二人で暮らし続けたいと考えたＧさんは，相談支援事業所の介護福祉職に相談した。\nＧさんに対する介護福祉職の助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"地域包括支援センターで，介護保険サービスの情報を得ることを勧める。"},{"id":"2","text":"Ｇさんが正規に雇用されるように，ハローワークに相談に行くことを勧める。"},{"id":"3","text":"Ｇさんの発達障害について，クリニックで適切な治療を受けることを勧める。"},{"id":"4","text":"母親に，介護老人福祉施設を紹介する。"},{"id":"5","text":"母親に，精神科病院への入院を勧める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｇさんは、母親と二人で暮らし続けたいと考えているね。母親に認知症が疑われるので、まずは、地域包括支援センターで、介護保険サービスの情報を得ることが、適切だよ。2、3は、Ｇさんの希望に直接つながらない。4は、施設の紹介、5は、入院を勧めるのは、二人で暮らし続けたい、Ｇさんの思いに合わないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-018","examYear":"2023","examRound":"35","questionNumber":18,"category":"社会の理解","questionText":"生活困窮者自立支援法に関する次の記述のうち，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"最低限度の生活が維持できなくなるおそれのある者が対象になる。"},{"id":"2","text":"自立を図るために，就労自立給付金が支給される。"},{"id":"3","text":"疾病がある者には，医療費が支給される。"},{"id":"4","text":"子どもへの学習支援は，必須事業とされている。"},{"id":"5","text":"最終的な，「第3のセーフティーネット」と位置づけられている。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！生活困窮者自立支援法は、最低限度の生活が維持できなくなるおそれのある人を、対象とした法律なんだ。2の就労自立給付金は、生活保護制度にある。3は、医療費の支給は、生活保護の医療扶助。4は、子どもへの学習支援は、任意事業。5は、第3のセーフティネットで、最終的なものは、第3ではなく、生活保護だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-019","examYear":"2023","examRound":"35","questionNumber":19,"category":"こころとからだのしくみ","questionText":"Ｈさん（75歳，男性）は，一人暮らしであるが，隣人と共に社会活動にも積極的に参加し，ゲートボールや詩吟，芸術活動など多くの趣味をもっている。また，多くの友人から，「Ｈさんは，毎日を有意義に生活している」と評価されている。Ｈさん自身も友人関係に満足している。\nライチャード（Reichard, S.）による老齢期の性格類型のうち，Ｈさんに相当するものとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自責型"},{"id":"2","text":"防衛型（装甲型）"},{"id":"3","text":"憤慨型"},{"id":"4","text":"円熟型"},{"id":"5","text":"依存型（安楽いす型）"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ライチャードの円熟型は、老いを受け入れて、現実的に生活し、満足しているタイプなんだ。Ｈさんは、社会活動や趣味に積極的で、友人関係にも満足しているので、この型にあたるよ。1は自責型、2は防衛型、3は憤慨型で、老いを受け入れられない。5は、依存型は、他者に頼ることが多いタイプだよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-020","examYear":"2023","examRound":"35","questionNumber":20,"category":"こころとからだのしくみ","questionText":"大脳の後頭葉にある機能局在として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"視覚野"},{"id":"2","text":"聴覚野"},{"id":"3","text":"運動野"},{"id":"4","text":"体性感覚野"},{"id":"5","text":"感覚性言語野（ウェルニッケ野）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！後頭葉には、視覚野があって、目から入った情報を処理するんだ。2の聴覚野は側頭葉、3の運動野は前頭葉、4の体性感覚野は頭頂葉、5のウェルニッケ野は、側頭葉にあるよ。脳の部位と機能は、セットで覚えよう。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-021","examYear":"2023","examRound":"35","questionNumber":21,"category":"こころとからだのしくみ","questionText":"立位姿勢を維持するための筋肉（抗重力筋）として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"上腕二頭筋"},{"id":"2","text":"大胸筋"},{"id":"3","text":"大腿四頭筋"},{"id":"4","text":"僧帽筋"},{"id":"5","text":"三角筋"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！大腿四頭筋は、立位を保つときに、重力に逆らって働く、抗重力筋のひとつなんだ。1の上腕二頭筋、2の大胸筋、4の僧帽筋、5の三角筋は、上半身にある筋肉で、主に腕や肩を動かす働きをするよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-022","examYear":"2023","examRound":"35","questionNumber":22,"category":"こころとからだのしくみ","questionText":"廃用症候群（disuse syndrome）で起こる可能性があるものとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"うつ状態"},{"id":"2","text":"高血圧"},{"id":"3","text":"関節炎"},{"id":"4","text":"徘徊"},{"id":"5","text":"下痢"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！廃用症候群は、体を使わないことで、心身の機能が低下する状態で、うつ状態が起こることがあるんだ。2の高血圧、3の関節炎、4の徘徊、5の下痢は、廃用症候群の症状ではないよ。起立性低血圧や、筋力低下、関節拘縮などが、代表的な症状だね。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-023","examYear":"2023","examRound":"35","questionNumber":23,"category":"こころとからだのしくみ","questionText":"褥瘡の好発部位として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"側頭部"},{"id":"2","text":"頸部"},{"id":"3","text":"腹部"},{"id":"4","text":"仙骨部"},{"id":"5","text":"足趾部"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！褥瘡は、骨が突出した部分に圧がかかりやすく、仙骨部は、仰臥位で、好発する部位なんだ。1の側頭部、2の頸部、3の腹部、5の足趾部は、褥瘡の好発部位としては、最も適切ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-024","examYear":"2023","examRound":"35","questionNumber":24,"category":"こころとからだのしくみ","questionText":"次のうち，口臭の原因になりやすい状態として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"唾液の増加"},{"id":"2","text":"義歯の装着"},{"id":"3","text":"歯周病（periodontal disease）"},{"id":"4","text":"顎関節症（temporomandibular joint disorder）"},{"id":"5","text":"低栄養状態"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！歯周病は、歯ぐきなどの炎症で、細菌が増えて、口臭の原因になりやすいんだ。1は、唾液が増えると、口の中が清潔になり、口臭は減る。2は、義歯は、汚れがつくと口臭の原因になるけれど、装着自体が原因ではない。4は、顎関節症、5は、低栄養状態は、口臭とは直接関係しないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-025","examYear":"2023","examRound":"35","questionNumber":25,"category":"こころとからだのしくみ","questionText":"Ｊさん（82歳，女性）は，施設に入所している。Ｊさんは車いすで食堂に来て，箸やスプーンを使って，自分で食事をしている。主食は普通食，おかずは刻み食で全量摂取している。最近，車いすからずり落ちる傾向があり，首が後屈した姿勢で食事をし，むせることが多くなった。\nＪさんが誤嚥をしないようにするための最初の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食事回数の調整"},{"id":"2","text":"座位姿勢の調整"},{"id":"3","text":"使用食器の変更"},{"id":"4","text":"食事の量の調整"},{"id":"5","text":"食事場所の変更"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｊさんは、車いすからずり落ちて、首が後ろにそった姿勢で食べていて、むせているね。誤嚥を防ぐために、まず座位姿勢を整えるのが、最初の対応なんだ。1、3、4、5は、姿勢の問題を、解決するものではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-026","examYear":"2023","examRound":"35","questionNumber":26,"category":"こころとからだのしくみ","questionText":"次のうち，誤嚥しやすい高齢者の脱水予防のために確認することとして，最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"義歯の装着状態"},{"id":"2","text":"上肢の関節可動域"},{"id":"3","text":"睡眠時間"},{"id":"4","text":"夜間の咳込みの有無"},{"id":"5","text":"摂取している水分の形状"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！誤嚥しやすい高齢者は、水分でむせやすく、水分摂取が減って、脱水になりやすいんだ。だから、摂取している水分の形状（とろみの有無など）を、確認することが、最も優先されるよ。1、2、3、4は、脱水予防の観点で、優先度が低いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-027","examYear":"2023","examRound":"35","questionNumber":27,"category":"こころとからだのしくみ","questionText":"健康な成人の便の生成で，上行結腸の次に内容物が通過する部位として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"Ｓ状結腸"},{"id":"2","text":"回腸"},{"id":"3","text":"直腸"},{"id":"4","text":"下行結腸"},{"id":"5","text":"横行結腸"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！便の生成では、内容物は、盲腸、上行結腸、横行結腸、下行結腸、Ｓ状結腸、直腸の順に通るんだ。だから、上行結腸の次は、横行結腸だよ。2の回腸は、小腸の一部で、盲腸の手前にあるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-028","examYear":"2023","examRound":"35","questionNumber":28,"category":"こころとからだのしくみ","questionText":"高齢者の睡眠薬の使用に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"依存性は生じにくい。"},{"id":"2","text":"翌朝まで作用が残ることがある。"},{"id":"3","text":"食事後すぐの服用が望ましい。"},{"id":"4","text":"アルコールと一緒に飲んでも効果は変わらない。"},{"id":"5","text":"転倒の原因にはならない。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！高齢者は、薬の代謝が遅く、睡眠薬の作用が、翌朝まで残ることがあって、ふらつきや、転倒に注意が必要なんだ。1は、依存性は、生じることがある。3は、就寝前に服用する。4は、アルコールと一緒に飲むと、作用が強く出て、危険。5は、転倒の原因になるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-029","examYear":"2023","examRound":"35","questionNumber":29,"category":"こころとからだのしくみ","questionText":"大切な人を亡くした後にみられる，寂しさやむなしさ，無力感などの精神的反応や，睡眠障害，食欲不振，疲労感などの身体的反応を表すものとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"認知症（dementia）"},{"id":"2","text":"グリーフ（grief）"},{"id":"3","text":"リビングウィル（living will）"},{"id":"4","text":"スピリチュアル（spiritual）"},{"id":"5","text":"パニック障害（panic disorder）"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！グリーフは、大切な人を亡くした後にみられる、寂しさや、むなしさなどの精神的反応や、睡眠障害、食欲不振などの身体的反応を表す言葉で、悲嘆と訳されるんだ。1は認知症、3のリビングウィルは、生前の意思表示、4のスピリチュアルは、霊的な、または存在に関する苦痛、5のパニック障害は、不安障害の一つだよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-030","examYear":"2023","examRound":"35","questionNumber":30,"category":"こころとからだのしくみ","questionText":"死が近づいているときの身体の変化として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"瞳孔の縮小"},{"id":"2","text":"筋肉の硬直"},{"id":"3","text":"発汗"},{"id":"4","text":"結膜の充血"},{"id":"5","text":"喘鳴"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！死が近づくと、気道に分泌物がたまって、ゴロゴロとした呼吸の音（喘鳴）が出ることがあるんだ。1は、瞳孔は、死が近づくと、散大していく。2の筋肉の硬直は、死後の変化（死後硬直）。3は、発汗ではなく、冷や汗のことはある。4の結膜の充血は、死が近づく変化ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-031","examYear":"2023","examRound":"35","questionNumber":31,"category":"発達と老化の理解","questionText":"今，発達の実験のために，図のようなテーブル（テーブル表面の左半分が格子柄，右半分が透明な板で床の格子柄が透けて見える）の左端に，Ｋさん（1歳1か月）を座らせた。テーブルの反対側には母親が立っている。Ｋさんは，格子柄と透明な板との境目でいったん動くのをやめて，怖がった表情で母親の顔を見た。母親が穏やかにほほ笑むと，Ｋさんは母親の方に近づいていった。\nＫさんの行動を説明する用語として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自己中心性"},{"id":"2","text":"愛着理論"},{"id":"3","text":"向社会的行動"},{"id":"4","text":"社会的参照"},{"id":"5","text":"原始反射"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｋさんは、境目で不安になって、母親の顔を見て、母親の穏やかな表情を手がかりにして、行動を決めているよね。これが、社会的参照なんだ。1の自己中心性は、他者の視点に立てないこと、2の愛着理論は、養育者との絆、3の向社会的行動は、他者を助ける行動、5の原始反射は、乳児期の反射だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-032","examYear":"2023","examRound":"35","questionNumber":32,"category":"発達と老化の理解","questionText":"コールバーグ（Kohlberg, L.）による道徳性判断に関する次の記述のうち，最も高い発達の段階を示すものとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"権威に服従する。"},{"id":"2","text":"罰を回避する。"},{"id":"3","text":"多数意見を重視して判断する。"},{"id":"4","text":"損得で判断する。"},{"id":"5","text":"人間の権利や平等性などの倫理に従って判断する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！コールバーグの道徳性判断で、最も高い段階は、人間の権利や、平等性などの、普遍的な倫理に従って判断する、脱慣習的水準なんだ。1と2は、罰と服従、4は、損得で判断する、前慣習的水準。3は、多数意見を重視する、慣習的水準だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-033","examYear":"2023","examRound":"35","questionNumber":33,"category":"発達と老化の理解","questionText":"標準的な発育をしている子どもの体重が，出生時の約2倍になる時期として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"生後3か月"},{"id":"2","text":"生後6か月"},{"id":"3","text":"生後9か月"},{"id":"4","text":"1歳"},{"id":"5","text":"2歳"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！標準的な発育の子どもの体重は、生後3か月ごろに、出生時の約2倍になるんだ。1歳で約3倍になるよ。乳児期は、体重が、急速に増える時期だね。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-034","examYear":"2023","examRound":"35","questionNumber":34,"category":"発達と老化の理解","questionText":"ストローブ（Stroebe, M.S.）とシュト（Schut, H.）による悲嘆のモデルでは，死別へのコーピングには喪失志向と回復志向の2種類があるとされる。\n喪失志向のコーピングとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"しばらく連絡していなかった旧友との交流を深める。"},{"id":"2","text":"悲しい気持ちを語る。"},{"id":"3","text":"新たにサークル活動に参加を申し込む。"},{"id":"4","text":"ボランティア活動に励む。"},{"id":"5","text":"新しい生活に慣れようとする。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ストローブとシュトの二重過程モデルで、喪失志向のコーピングは、悲しみに向き合う行動で、悲しい気持ちを語ることがあたるんだ。1、3、4、5は、新しい生活や活動に向かう、回復志向のコーピングだよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-035","examYear":"2023","examRound":"35","questionNumber":35,"category":"発達と老化の理解","questionText":"加齢の影響を受けにくい認知機能として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"エピソード記憶"},{"id":"2","text":"作業記憶"},{"id":"3","text":"選択的注意"},{"id":"4","text":"流動性知能"},{"id":"5","text":"意味記憶"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！意味記憶は、言葉の意味や、知識など、一般的な情報の記憶で、加齢の影響を受けにくいんだ。1のエピソード記憶や、2の作業記憶、3の選択的注意、4の流動性知能は、加齢とともに低下しやすいよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-036","examYear":"2023","examRound":"35","questionNumber":36,"category":"発達と老化の理解","questionText":"高齢期の腎・泌尿器系の状態や変化に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"尿路感染症（urinary tract infections）を起こすことは非常に少ない。"},{"id":"2","text":"腎盂腎炎（pyelonephritis）の主な症状は，頭痛である。"},{"id":"3","text":"尿の濃縮力が低下する。"},{"id":"4","text":"前立腺肥大症（prostatic hypertrophy）では，尿道の痛みがある。"},{"id":"5","text":"薬物が排出される時間は，短くなる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！高齢になると、腎臓の働きが低下して、尿を濃縮する力が落ちるんだ。1は、尿路感染症は、起こりやすい。2は、腎盂腎炎の主な症状は、発熱や腰痛。4は、前立腺肥大症では、排尿困難や頻尿が出る。5は、薬物が排出される時間は、長くなるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-037","examYear":"2023","examRound":"35","questionNumber":37,"category":"発達と老化の理解","questionText":"老年期の変形性膝関節症（knee osteoarthritis）に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"外反型の脚の変形を伴うことが多い。"},{"id":"2","text":"女性のほうが男性より罹患率が高い。"},{"id":"3","text":"積極的に患部を冷やすことを勧める。"},{"id":"4","text":"正座の生活習慣を勧める。"},{"id":"5","text":"肥満のある人には積極的に階段を利用するように勧める。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！変形性膝関節症は、女性のほうが、男性より罹患率が高いんだ。1は、Ｏ脚（内反型）の変形が多い。3は、温めるほうが、痛みがやわらぐ。4は、正座は、膝に負担がかかる。5は、肥満のある人は、階段を控えて、体重管理をするんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-038","examYear":"2023","examRound":"35","questionNumber":38,"category":"発達と老化の理解","questionText":"高齢者の脱水に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"若年者よりも口渇感を感じやすい。"},{"id":"2","text":"体内水分量は若年者よりも多い。"},{"id":"3","text":"起立時に血圧が上がりやすくなる。"},{"id":"4","text":"下痢が原因となることはまれである。"},{"id":"5","text":"体重が減ることがある。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！高齢者が脱水になると、体重が減ることがあるんだ。1は、高齢者は、口渇感を感じにくい。2は、体内水分量は、若年者より少ない。3は、起立時に血圧が下がりやすくなる。4は、下痢は、脱水の原因になるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-039","examYear":"2023","examRound":"35","questionNumber":39,"category":"認知症の理解","questionText":"次のうち，2019年（令和元年）の認知症施策推進大綱の5つの柱に示されているものとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"市民後見人の活動推進への体制整備"},{"id":"2","text":"普及啓発・本人発信支援"},{"id":"3","text":"若年性認知症支援ハンドブックの配布"},{"id":"4","text":"認知症初期集中支援チームの設置"},{"id":"5","text":"認知症カフェ等を全市町村に普及"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！認知症施策推進大綱の5つの柱のひとつは、普及啓発・本人発信支援なんだ。ほかの柱は、予防、医療・ケア・介護サービス・介護者への支援、認知症バリアフリーの推進・若年性認知症の人への支援・社会参加支援、研究開発・産業促進・国際展開だよ。1、3、4、5は、柱そのものではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-040","examYear":"2023","examRound":"35","questionNumber":40,"category":"認知症の理解","questionText":"次の記述のうち，見当識障害に関する質問として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「私たちが今いるところはどこですか」"},{"id":"2","text":"「100から7を順番に引いてください」"},{"id":"3","text":"「先ほど覚えてもらった言葉をもう一度言ってみてください」"},{"id":"4","text":"「次の図形を写してください」"},{"id":"5","text":"「この紙を左手で取り，両手で半分に折って，私に返してください」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！見当識障害は、時間、場所、人物がわからなくなる障害なんだ。「私たちが今いるところはどこですか」は、場所の見当識を確認する質問だよ。2は、注意力や計算、3は、記憶、4は、視空間認知（構成）、5は、指示の理解や、実行の力を確かめる質問だね。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-041","examYear":"2023","examRound":"35","questionNumber":41,"category":"認知症の理解","questionText":"アルツハイマー型認知症（dementia of the Alzheimerʼs type）の，もの盗られ妄想に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"説明をすれば自身の考えの誤りに気づくことが多い。"},{"id":"2","text":"本人の不安から生じることが多い。"},{"id":"3","text":"現実に存在しない人が犯人とされる。"},{"id":"4","text":"主に幻視が原因である。"},{"id":"5","text":"症状の予防には抗精神病薬が有効である。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！もの盗られ妄想は、記憶障害のため、ものを置いた場所を忘れて、不安になることから生じることが多いんだ。1は、説明しても、誤りに気づきにくい。3は、犯人は、身近な人が多い。4は、幻視ではなく、記憶障害が主な原因。5は、抗精神病薬は、予防が目的ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-042","examYear":"2023","examRound":"35","questionNumber":42,"category":"認知症の理解","questionText":"慢性硬膜下血腫（chronic subdural hematoma）に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"運動機能障害が起こることは非常に少ない。"},{"id":"2","text":"頭蓋骨骨折を伴い発症する。"},{"id":"3","text":"抗凝固薬の使用はリスクとなる。"},{"id":"4","text":"転倒の後，2〜3日で発症することが多い。"},{"id":"5","text":"保存的治療が第一選択である。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！慢性硬膜下血腫は、抗凝固薬（血液をさらさらにする薬）を使っていると、出血しやすくて、リスクが高まるんだ。1は、運動麻痺などの症状が、起こることがある。2は、頭蓋骨骨折を伴わないことも多い。4は、転倒の後、数週間から数か月で発症することが多い。5は、血腫を取り除く手術が、第一選択だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-043","examYear":"2023","examRound":"35","questionNumber":43,"category":"認知症の理解","questionText":"Ｌさん（83歳，女性，要介護1）は，アルツハイマー型認知症（dementia of the Alzheimerʼs type）である。一人暮らしで，週2回，訪問介護（ホームヘルプサービス）を利用している。ある日，訪問介護員（ホームヘルパー）が訪問すると，息子が来ていて，「最近，母が年金の引き出しや，水道代の支払いを忘れるようだ。日常生活自立支援事業というものがあると聞いたことがあるが，どのような制度なのか」と質問があった。\n訪問介護員（ホームヘルパー）の説明として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「申込みをしたい場合は，家庭裁判所が受付窓口です」"},{"id":"2","text":"「年金の振込口座を，息子さん名義の口座に変更することができます」"},{"id":"3","text":"「Ｌさんが契約内容を理解できない場合は，息子さんが契約できます」"},{"id":"4","text":"「生活支援員が，水道代の支払いをＬさんの代わりに行うことができます」"},{"id":"5","text":"「利用後に苦情がある場合は，国民健康保険団体連合会が受付窓口です」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！日常生活自立支援事業では、生活支援員が、公共料金の支払いなど、日常的な金銭管理を、本人の代わりに行うことができるんだ。1は、窓口は、社会福祉協議会。2は、口座名義の変更は、できない。3は、契約は、本人が理解できる必要がある。5は、苦情は、運営適正化委員会が受け付けるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-044","examYear":"2023","examRound":"35","questionNumber":44,"category":"認知症の理解","questionText":"認知症ケアの技法であるユマニチュードに関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"「見る」とは，離れた位置からさりげなく見守ることである。"},{"id":"2","text":"「話す」とは，意識的に高いトーンの大きな声で話しかけることである。"},{"id":"3","text":"「触れる」とは，指先で軽く触れることである。"},{"id":"4","text":"「立つ」とは，立位をとる機会を作ることである。"},{"id":"5","text":"「オートフィードバック」とは，ケアを評価することである。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ユマニチュードの4つの柱は、「見る」「話す」「触れる」「立つ」なんだ。「立つ」は、立位をとる機会をつくって、体を動かすことだよ。1の見るは、正面から同じ高さで見る。2の話すは、穏やかで低いトーン。3の触れるは、手のひら全体で優しく触れる。5のオートフィードバックは、行っているケアを、言葉にして伝えることだよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-045","examYear":"2023","examRound":"35","questionNumber":45,"category":"認知症の理解","questionText":"現行の認知症サポーターに関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ステップアップ講座を受講した認知症サポーターには，チームオレンジへの参加"},{"id":"2","text":"100万人を目標に養成されている。"},{"id":"3","text":"認知症介護実践者等養成事業の一環である。"},{"id":"4","text":"認知症ケア専門の介護福祉職である。"},{"id":"5","text":"国が実施主体となって養成講座を行っている。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！認知症サポーターのステップアップ講座を受けた人は、チームオレンジに参加して、認知症の人や家族の支援を行うんだ。2は、目標は、1,000万人。3は、認知症介護実践者等養成事業とは別。4は、専門職ではなく、ボランティア。5は、実施主体は、都道府県や市町村などだよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-046","examYear":"2023","examRound":"35","questionNumber":46,"category":"認知症の理解","questionText":"認知症ケアパスに関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"都道府県ごとに作られるものである。"},{"id":"2","text":"介護保険制度の地域密着型サービスの1つである。"},{"id":"3","text":"認知症（dementia）の人の状態に応じた適切なサービス提供の流れをまとめた"},{"id":"4","text":"レスパイトケアとも呼ばれるものである。"},{"id":"5","text":"介護支援専門員（ケアマネジャー）が中心になって作成する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！認知症ケアパスは、認知症の人の状態に応じて、適切な医療や介護サービスを、いつ、どこで受けられるかを、流れとしてまとめたものなんだ。1は、市町村ごとに作られる。2は、介護保険のサービスではない。4は、レスパイトケアは、家族の休息のこと。5は、介護支援専門員が中心とは限らないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-047","examYear":"2023","examRound":"35","questionNumber":47,"category":"認知症の理解","questionText":"認知症ライフサポートモデルに関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"各職種がそれぞれで目標を設定する。"},{"id":"2","text":"終末期に行う介入モデルである。"},{"id":"3","text":"認知症（dementia）の人本人の自己決定を支える。"},{"id":"4","text":"生活を介護サービスに任せるプランを策定する。"},{"id":"5","text":"認知症（dementia）の人に施設入所を促す。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！認知症ライフサポートモデルは、認知症の人の、自己決定を支えるために、本人の生活を、総合的に支援する考え方なんだ。1は、多職種が、共通の目標をもつ。2は、終末期に限らない。4、5は、本人の意思や生活を、サービスに任せてしまい、モデルの考え方に合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-048","examYear":"2023","examRound":"35","questionNumber":48,"category":"認知症の理解","questionText":"Ｍさん（88歳，女性）は，アルツハイマー型認知症（dementia of the Alzheimerʼs type）と診断された。夫と二人暮らしで，訪問介護（ホームヘルプサービス）を利用している。訪問介護員（ホームヘルパー）が訪問したときに夫から，「最近，日中することがなく寝てしまい，夜眠れていないようだ」と相談を受けた。訪問介護員（ホームヘルパー）は，Ｍさんが長年していた裁縫を日中にしてみることを勧めた。早速，裁縫をしてみるとＭさんは，短時間で雑巾を縫うことができた。\nＭさんの裁縫についての記憶として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"作業記憶"},{"id":"2","text":"展望的記憶"},{"id":"3","text":"短期記憶"},{"id":"4","text":"陳述記憶"},{"id":"5","text":"手続き記憶"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！裁縫のように、体で覚えた技能の記憶は、手続き記憶で、認知症になっても、保たれやすいんだ。1の作業記憶は、作業中の一時的な記憶、2の展望的記憶は、未来の予定の記憶、3の短期記憶は、短時間の記憶、4の陳述記憶は、言葉で説明できる記憶だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-049","examYear":"2023","examRound":"35","questionNumber":49,"category":"障害の理解","questionText":"ストレングス（strength）の視点に基づく利用者支援の説明として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"個人の特性や強さを見つけて，それを生かす支援を行うこと。"},{"id":"2","text":"日常生活の条件をできるだけ，障害のない人と同じにすること。"},{"id":"3","text":"全人間的復権を目標とすること。"},{"id":"4","text":"権利を代弁・擁護して，権利の実現を支援すること。"},{"id":"5","text":"抑圧された権利や能力を取り戻して，力をつけること。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ストレングスの視点は、個人の特性や強さを見つけて、それを生かす支援を行う考え方なんだ。2はノーマライゼーション、3はリハビリテーション、4はアドボカシー、5はエンパワメントの説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-050","examYear":"2023","examRound":"35","questionNumber":50,"category":"障害の理解","questionText":"1960年代のアメリカにおける自立生活運動（ＩＬ運動）に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"障害があっても障害のない人々と同じ生活を送る。"},{"id":"2","text":"一度失った地位，名誉，特権などを回復する。"},{"id":"3","text":"自分で意思決定をして生活する。"},{"id":"4","text":"医療職が機能回復訓練を行う。"},{"id":"5","text":"障害者の社会への完全参加と平等を促進する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！自立生活運動（ＩＬ運動）は、障害のある人が、自分で意思決定をして、責任をもって生活することを大切にした運動なんだ。1はノーマライゼーション、2は、リハビリテーション（全人間的復権）の語源的な意味。4は、医学的リハビリテーション。5は、国際障害者年の目標だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-051","examYear":"2023","examRound":"35","questionNumber":51,"category":"障害の理解","questionText":"「障害者虐待防止法」における，障害者に対する著しい暴言が当てはまる障害者虐待の類型として，最も適切なものを1つ選びなさい。\n（注）「障害者虐待防止法」とは，「障害者虐待の防止，障害者の養護者に対する支援等に関する法律」のことである。","choices":[{"id":"1","text":"身体的虐待"},{"id":"2","text":"放棄・放置"},{"id":"3","text":"性的虐待"},{"id":"4","text":"心理的虐待"},{"id":"5","text":"経済的虐待"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！著しい暴言や、拒絶的な対応は、心理的虐待にあたるんだ。1は、暴力などの身体的虐待、2は、世話をしない放棄・放置、3は、性的な行為の強要、5は、財産を不当に使う経済的虐待だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-052","examYear":"2023","examRound":"35","questionNumber":52,"category":"障害の理解","questionText":"上田敏の障害受容のモデルにおける受容期の説明として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"受傷直後である。"},{"id":"2","text":"障害の状態を否認する。"},{"id":"3","text":"リハビリテーションによって機能回復に取り組む。"},{"id":"4","text":"障害のため何もできないと捉える。"},{"id":"5","text":"障害に対する価値観を転換し，積極的な生活態度になる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！上田敏の障害受容のモデルで、受容期は、障害に対する価値観を転換して、積極的な生活態度になる時期なんだ。1はショック期、2は否認期、3は解決への努力期の説明で、4は、混乱期の、何もできないと捉える状態だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-053","examYear":"2023","examRound":"35","questionNumber":53,"category":"障害の理解","questionText":"次のうち，四肢麻痺を伴う疾患や外傷として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"右脳梗塞（right cerebral infarction）"},{"id":"2","text":"左脳梗塞（left cerebral infarction）"},{"id":"3","text":"頸髄損傷（cervical cord injury）"},{"id":"4","text":"腰髄損傷（lumbar spinal cord injury）"},{"id":"5","text":"末梢神経損傷（peripheral nerve injury）"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！頸髄損傷は、首の部分の脊髄が損傷されるので、両腕と両足に麻痺が出る四肢麻痺になるんだ。1と2の脳梗塞は、片麻痺、4の腰髄損傷は、下半身の対麻痺、5の末梢神経損傷は、損傷した部位の麻痺だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-054","examYear":"2023","examRound":"35","questionNumber":54,"category":"障害の理解","questionText":"学習障害の特徴に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"読む・書く・計算するなどの習得に困難がある。"},{"id":"2","text":"注意力が欠如している。"},{"id":"3","text":"じっとしているのが難しい。"},{"id":"4","text":"脳の機能に障害はない。"},{"id":"5","text":"親のしつけ方や愛情不足によるものである。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！学習障害は、全般的な知的な遅れはないのに、読む、書く、計算するなど、特定の能力の習得に困難がある障害なんだ。2と3は、注意欠陥多動性障害の特徴。4は、脳の機能の障害が原因と考えられる。5は、親のしつけや愛情不足が原因ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-055","examYear":"2023","examRound":"35","questionNumber":55,"category":"障害の理解","questionText":"Ａさん（60歳，男性）は，脊髄小脳変性症（spinocerebellar degeneration）のため，物をつかもうとすると手が震え，起立時や歩行時に身体がふらつき，ろれつが回らないため発語が不明瞭である。\n次のうち，Ａさんの現在の症状に該当するものとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"運動麻痺"},{"id":"2","text":"運動失調"},{"id":"3","text":"関節拘縮"},{"id":"4","text":"筋萎縮"},{"id":"5","text":"筋固縮"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！脊髄小脳変性症は、小脳の障害で、運動失調（手の震え、ふらつき、ろれつが回らないなど）が起こるんだ。1の運動麻痺は、動かせなくなる状態。3の関節拘縮は、関節が固まる状態。4の筋萎縮は、筋肉がやせる状態。5の筋固縮は、パーキンソン病の症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-056","examYear":"2023","examRound":"35","questionNumber":56,"category":"障害の理解","questionText":"Ｂさん（21歳，男性）は，統合失調症（schizophrenia）を発症し，継続した内服によって幻覚や妄想などの症状は改善しているが，意欲や自発性が低下して引きこもりがちである。現在，Ｂさんは，外来に通院しながら自宅で生活していて，就労を考えるようになってきた。\n介護福祉職が就労に向けて支援するにあたり留意すべきこととして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"あいまいな言葉で説明する。"},{"id":"2","text":"代理で手続きを進める。"},{"id":"3","text":"介護福祉職が正しいと考える支援を行う。"},{"id":"4","text":"Ｂさんに意欲をもつように強く指示する。"},{"id":"5","text":"Ｂさん自身が物事を決め，実行できるように関わる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！就労に向けた支援では、Ｂさん自身が物事を決めて、実行できるように関わることが大切なんだ。1は、あいまいな言葉は、混乱させる。2は、代理で進めると、自立を妨げる。3は、支援者の価値観を、押しつけてはダメ。4は、強く指示すると、負担になるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-057","examYear":"2023","examRound":"35","questionNumber":57,"category":"障害の理解","questionText":"Ｃさん（3歳）は，24時間の人工呼吸器管理，栄養管理と体温管理が必要であり，母親（32歳）が生活全般を支えている。Ｃさんの母親は，「発達支援やショートステイを活用したいのに，市内に事業所がない。ほかにも困っている家族がいる」とＤ相談支援専門員に伝えた。Ｄ相談支援専門員が，課題の解決に向けて市（自立支援）協議会に働きかけたところ，市内に該当する事業所がないことが明らかになった。\nこの事例で，地域におけるサービスの不足を解決するために，市（自立支援）協議会に期待される機能・役割として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"困難な事例や資源不足についての情報の発信"},{"id":"2","text":"権利擁護に関する取り組みの展開"},{"id":"3","text":"地域の社会資源の開発"},{"id":"4","text":"構成員の資質向上"},{"id":"5","text":"基幹相談支援センターの運営評価"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！市（自立支援）協議会には、地域の課題を共有して、不足している社会資源を、開発する働きが期待されているんだ。市内に必要な事業所がないという課題に対して、地域の社会資源の開発が、最も適切だよ。1、2、4、5は、協議会の役割ではあるけれど、資源の不足を解決する機能とは、ちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-058","examYear":"2023","examRound":"35","questionNumber":58,"category":"障害の理解","questionText":"Ｅさん（38歳，男性）は，脳梗塞（cerebral infarction）を発症し，病院に入院していた。退院時に，右片麻痺と言語障害があったため，身体障害者手帳2級の交付を受けた。現在，Ｅさんと家族の希望によって，自宅で生活しているが，少しずつ生活に支障が出てきている。Ｅさんの今後の生活を支えるために，障害福祉サービスの利用を前提に多職種連携による支援が行われることになった。\nＥさんに関わる関係者が果たす役割として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護支援専門員（ケアマネジャー）が，介護サービス計画を作成する。"},{"id":"2","text":"医師が，要介護認定を受けるための意見書を作成する。"},{"id":"3","text":"基幹相談支援センターの職員が，障害福祉計画を立てる。"},{"id":"4","text":"地域包括支援センターの職員が，認定調査を行う。"},{"id":"5","text":"相談支援専門員が，サービス担当者会議を開催する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害福祉サービスの利用では、相談支援専門員が、サービス等利用計画を作成して、サービス担当者会議を開催するんだ。1は、Ｅさんは38歳で、介護保険の対象ではない。2の要介護認定の意見書も、介護保険。3は、障害福祉計画は、市町村や都道府県が立てる。4の認定調査は、市町村の職員などが行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-059","examYear":"2023","examRound":"35","questionNumber":59,"category":"医療的ケア","questionText":"消毒と滅菌に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"消毒は，すべての微生物を死滅させることである。"},{"id":"2","text":"複数の消毒液を混ぜると効果的である。"},{"id":"3","text":"滅菌物には，有効期限がある。"},{"id":"4","text":"家庭では，熱水で滅菌する。"},{"id":"5","text":"手指消毒は，次亜塩素酸ナトリウムを用いる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！滅菌物には、有効期限があって、期限内に使うことが大切なんだ。1は、すべての微生物を死滅させるのは、滅菌。2は、複数の消毒液を混ぜると、危険。4は、家庭では、熱湯消毒などを行うけれど、滅菌は、できない。5は、手指の消毒は、アルコールなどを用いるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-060","examYear":"2023","examRound":"35","questionNumber":60,"category":"医療的ケア","questionText":"次の記述のうち，成人の正常な呼吸状態として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"胸腹部が一定のリズムで膨らんだり縮んだりしている。"},{"id":"2","text":"ゴロゴロとした音がする。"},{"id":"3","text":"爪の色が紫色になっている。"},{"id":"4","text":"呼吸数が1分間に40回である。"},{"id":"5","text":"下顎を上下させて呼吸している。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！成人の正常な呼吸は、胸腹部が一定のリズムで、膨らんだり縮んだりして、1分間に12〜20回程度なんだ。2のゴロゴロという音は、痰がたまっている、3の紫色の爪は、チアノーゼ、4の呼吸数40回は、頻呼吸、5の下顎を上下させる呼吸は、下顎呼吸で、死が近づいているときにみられるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-061","examYear":"2023","examRound":"35","questionNumber":61,"category":"医療的ケア","questionText":"喀痰吸引を行う前の準備に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"医師の指示書の確認は，初回に一度行う。"},{"id":"2","text":"利用者への吸引の説明は，吸引のたびに行う。"},{"id":"3","text":"腹臥位の姿勢にする。"},{"id":"4","text":"同室の利用者から見える状態にする。"},{"id":"5","text":"利用者に手指消毒をしてもらう。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！喀痰吸引は、利用者の同意と安心のために、吸引のたびに、説明を行うんだ。1は、医師の指示書は、定期的に確認する。3は、腹臥位ではなく、安楽な姿勢にする。4は、プライバシーに配慮して、見えないようにする。5は、手指消毒は、介護福祉士が行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-062","examYear":"2023","examRound":"35","questionNumber":62,"category":"医療的ケア","questionText":"胃ろうによる経管栄養での生活上の留意点の説明として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「日中は，ベッド上で過ごします」"},{"id":"2","text":"「夜寝るときは，上半身を起こした姿勢で寝ます」"},{"id":"3","text":"「便秘の心配はなくなります」"},{"id":"4","text":"「口から食べなくても口腔ケアは必要です」"},{"id":"5","text":"「入浴は清拭に変更します」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！胃ろうで経管栄養を行っていても、口から食べないと、口の中の汚れがたまって、細菌が増えるので、口腔ケアは必要なんだ。1は、日中は、離床を勧める。2は、夜は、逆流を防ぐため、上半身を少し起こすことがあるけれど、常に起こしたまま寝るわけではない。3は、便秘は、起こることがある。5は、入浴もできるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-063","examYear":"2023","examRound":"35","questionNumber":63,"category":"医療的ケア","questionText":"Ｆさん（87歳，女性）は，介護老人福祉施設に入所している。嚥下機能が低下したため，胃ろうによる経管栄養が行われている。担当の介護福祉士は，Ｆさんの経管栄養を開始して，しばらく観察した。その後，15分後に訪室すると，Ｆさんが嘔吐して，意識はあるが苦しそうな表情をしていた。介護福祉士は，すぐに経管栄養を中止して看護職員を呼んだ。\n看護職員が来るまでの介護福祉士の対応として，最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"室内の換気を行った。"},{"id":"2","text":"ベッド上の嘔吐物を片付けた。"},{"id":"3","text":"酸素吸入を行った。"},{"id":"4","text":"心臓マッサージを行った。"},{"id":"5","text":"誤嚥を防ぐために顔を横に向けた。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！嘔吐したときは、吐いたものが気道に入って、誤嚥するのを防ぐことが、最優先なんだ。だから、顔を横に向けるよ。1の換気、2の嘔吐物の片付けは、そのあとに行う。3の酸素吸入は、医療行為で、介護福祉士は行えない。4の心臓マッサージは、意識があるので、必要ないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-064","examYear":"2023","examRound":"35","questionNumber":64,"category":"介護の基本","questionText":"利用者主体の考えに基づいた訪問介護員（ホームヘルパー）の対応に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"トイレの窓は換気が必要であると判断し，開けたままにしておいた。"},{"id":"2","text":"認知症（dementia）の人が包丁を持つのは危険だと判断し，訪問介護員（ホーム"},{"id":"3","text":"煮物を調理するとき，利用者に好みの切り方を確認してもらった。"},{"id":"4","text":"糖尿病（diabetes mellitus）のある利用者には，買い物代行で菓子の購入はし"},{"id":"5","text":"次回の掃除のために，訪問介護員（ホームヘルパー）が使いやすい場所に掃除機を"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！利用者主体は、利用者の意向や好みを、尊重することなんだ。煮物の切り方を、好みで確認してもらうのは、その例だね。1は、勝手に窓を開けておく、2は、危険だと決めつけて包丁を使わせない、4は、菓子を買わないと決める、5は、訪問介護員の都合で決めていて、いずれも、利用者の意向を確認していないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-065","examYear":"2023","examRound":"35","questionNumber":65,"category":"介護の基本","questionText":"「求められる介護福祉士像」で示された内容に関する次の記述のうち，最も適切なものを1つ選びなさい。\n（注）「求められる介護福祉士像」とは，社会保障審議会福祉部会福祉人材確保専門委員会「介護人材に求められる機能の明確化とキャリアパスの実現に向けて」（2017年（平成29年）10月4日）の中で示されたものを指す。","choices":[{"id":"1","text":"地域や社会のニーズにかかわらず，利用者を導く。"},{"id":"2","text":"利用者の身体的な支援よりも，心理的・社会的支援を重視する。"},{"id":"3","text":"施設か在宅かに関係なく，家族が望む生活を支える。"},{"id":"4","text":"専門職として他律的に介護過程を展開する。"},{"id":"5","text":"介護職の中で中核的な役割を担う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！「求められる介護福祉士像」では、介護職の中で、中核的な役割を担うことが、示されているんだ。1は、地域や社会のニーズに応える。2は、身体的な支援も、大切にする。3は、家族の望みではなく、本人の望む生活を支える。4は、他律的ではなく、自律的に介護過程を展開するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-066","examYear":"2023","examRound":"35","questionNumber":66,"category":"介護の基本","questionText":"社会福祉士及び介護福祉士法に規定されている介護福祉士の責務として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"地域生活支援事業その他の支援を総合的に行う。"},{"id":"2","text":"介護等に関する知識及び技能の向上に努める。"},{"id":"3","text":"肢体の不自由な利用者に対して必要な訓練を行う。"},{"id":"4","text":"介護保険事業に要する費用を公平に負担する。"},{"id":"5","text":"常に心身の健康を保持して，社会的活動に参加するように努める。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！社会福祉士及び介護福祉士法には、介護福祉士は、介護等に関する知識や技能の向上に努めなければならないという、責務が規定されているんだ。1は、市町村の事業。3は、理学療法士などの役割。4は、介護保険の被保険者の義務。5は、国民の努力義務に近い内容で、介護福祉士の責務ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-067","examYear":"2023","examRound":"35","questionNumber":67,"category":"介護の基本","questionText":"Ａさん（85歳，女性，要介護1）は夫と二人暮らしで，訪問介護（ホームヘルプサービス）を利用している。Ａさんは認知症（dementia）の進行によって，理解力の低下がみられる。ある日，Ａさんが訪問介護員（ホームヘルパー）に，「受けているサービスをほかのものに変更したい」「夫とは仲が悪いので話したくない」と，不安な様子で話した。\n意思決定支援を意識した訪問介護員（ホームヘルパー）の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ａさんとの話し合いの場に初めから夫に同席してもらった。"},{"id":"2","text":"Ａさんにサービス変更の決断を急ぐように伝えた。"},{"id":"3","text":"Ａさんと話す前に相談内容を夫に話した。"},{"id":"4","text":"サービスを変更したい理由についてＡさんに確認した。"},{"id":"5","text":"訪問介護員（ホームヘルパー）がサービス変更をすることを判断した。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんは、サービスを変えたいと話しているね。意思決定支援では、まずＡさんの思いを、じっくり聞いて、理由を確認することが大切なんだ。1と3は、夫と仲が悪いと話しているのに、夫に話してしまう。2は、決断を急がせる。5は、訪問介護員が、勝手に決めてはいけないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-068","examYear":"2023","examRound":"35","questionNumber":68,"category":"介護の基本","questionText":"すべての人が暮らしやすい社会の実現に向けて，どこでも，だれでも，自由に，使いやすくという考え方を表す用語として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ユニバーサルデザイン（universal design）"},{"id":"2","text":"インフォームドコンセント（informed consent）"},{"id":"3","text":"アドバンス・ケア・プランニング（advance care planning）"},{"id":"4","text":"リビングウィル（living will）"},{"id":"5","text":"エンパワメント（empowerment）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ユニバーサルデザインは、どこでも、だれでも、自由に、使いやすくという考え方で、年齢や障害の有無にかかわらず、すべての人が使いやすいデザインのことなんだ。2のインフォームドコンセントは、説明と同意、3のＡＣＰは、人生の最終段階の話し合い、4のリビングウィルは、生前の意思表示、5のエンパワメントは、力を引き出すことだよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-069","examYear":"2023","examRound":"35","questionNumber":69,"category":"介護の基本","questionText":"Ｂさん（82歳，女性，要介護2）は，若いときに夫を亡くし，家で仕事をしながら子どもを一人で育てた。夫や子どもと過ごした家の手入れは毎日欠かさず行っていた。数年前に，アルツハイマー型認知症（dementia of the Alzheimerʼs type）と診断され，認知症対応型共同生活介護（認知症高齢者グループホーム）に入居した。夕方になると，「私，家に帰らないといけない」と介護福祉職に何度も訴えている。\nＢさんに対する介護福祉職の声かけとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「仕事はないですよ」"},{"id":"2","text":"「ここが家ですよ」"},{"id":"3","text":"「外に散歩に行きますか」"},{"id":"4","text":"「家のことが気になるんですね」"},{"id":"5","text":"「子どもさんが『ここにいてください』と言っていますよ」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｂさんは、夕方に「家に帰らないと」と訴えているね。若いときから、家を守ってきた思いがあるので、「家のことが気になるんですね」と、気持ちを受け止める声かけがよいよ。1、2は、否定していて、3は、話をそらしている。5は、事実とちがうことを言っていて、不安を強めるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-070","examYear":"2023","examRound":"35","questionNumber":70,"category":"介護の基本","questionText":"介護保険施設の駐車場で，下記のマークを付けた車の運転手が困った様子で手助けを求めていた。\n介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"手話や筆談を用いて話しかける。"},{"id":"2","text":"杖を用意する。"},{"id":"3","text":"拡大読書器を使用する。"},{"id":"4","text":"移動用リフトを用意する。"},{"id":"5","text":"携帯用点字器を用意する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！この標識は、聴覚障害者マーク（蝶のマーク）で、聴覚に障害のある人が運転する車につけるものなんだ。そのため、手話や筆談を使って、話しかけるのが適切な対応だよ。2は杖、3は拡大読書器、5は点字器で、視覚障害や肢体不自由の人への支援、4は、移動用リフトで、この標識とは関係がないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-071","examYear":"2023","examRound":"35","questionNumber":71,"category":"介護の基本","questionText":"介護保険施設における専門職の役割に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の栄養ケア・マネジメントは，薬剤師が行う。"},{"id":"2","text":"認知症（dementia）の診断と治療は，作業療法士が行う。"},{"id":"3","text":"利用者の療養上の世話又は診療の補助は，社会福祉士が行う。"},{"id":"4","text":"日常生活を営むのに必要な身体機能改善や機能訓練は，歯科衛生士が行う。"},{"id":"5","text":"施設サービス計画の作成は，介護支援専門員が行う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護保険施設では、介護支援専門員が、施設サービス計画を作成するんだ。1の栄養ケア・マネジメントは、管理栄養士、2の認知症の診断と治療は、医師、3の療養上の世話や診療の補助は、看護師、4の機能訓練は、理学療法士や作業療法士などが行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-072","examYear":"2023","examRound":"35","questionNumber":72,"category":"介護の基本","questionText":"介護の現場におけるチームアプローチ（team approach）に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"チームメンバーが得た情報は，メンバー間であっても秘密にする。"},{"id":"2","text":"チームメンバーの役割分担を明確にする。"},{"id":"3","text":"利用者を外してチームを構成する。"},{"id":"4","text":"医師がチームの方針を決定する。"},{"id":"5","text":"チームメンバーを家族が指名する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！チームアプローチでは、メンバーの役割分担を明確にして、それぞれの専門性を生かすことが大切なんだ。1は、情報は、メンバー間で共有する。3は、利用者もチームの一員。4は、方針は、チームで話し合って決める。5は、メンバーは、家族が指名するのではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-073","examYear":"2023","examRound":"35","questionNumber":73,"category":"介護の基本","questionText":"利用者の危険を回避するための介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"スプーンを拾おうとして前傾姿勢になった車いすの利用者を，目視で確認した。"},{"id":"2","text":"廊下をふらつきながら歩いていた利用者の横を，黙って通り過ぎた。"},{"id":"3","text":"食事介助をしていた利用者の姿勢が傾いてきたので，姿勢を直した。"},{"id":"4","text":"下肢筋力が低下している利用者が，靴下で歩いていたので，スリッパを履いても"},{"id":"5","text":"車いすの利用者が，フットサポートを下げたまま立ち上がろうとしたので，ま"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！食事介助中に、利用者の姿勢がかたむいてきたことに気づいて、その場ですぐに姿勢を直すのは、実際に起きている危険に対応した行動なんだ。1は、危ない姿勢を見ているだけで、行動していないよ。2は、ふらつく利用者を、そのまま放っておいている。4は、下肢筋力が弱い人に、スリッパを勧めるのは、かえって転倒しやすくなる。5は、対応が不十分で、危険がそのまま残ってしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-074","examYear":"2023","examRound":"35","questionNumber":74,"category":"コミュニケーション技術","questionText":"次のうち，閉じられた質問として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「この本は好きですか」"},{"id":"2","text":"「午後はどのように過ごしますか」"},{"id":"3","text":"「困っていることは何ですか」"},{"id":"4","text":"「どのような歌が好きですか」"},{"id":"5","text":"「なぜそう思いますか」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！閉じられた質問は、「はい」「いいえ」や、簡単な言葉で答えられる質問なんだ。「この本は好きですか」が、それにあたるよ。2、3、4、5は、自由に答えられる、開かれた質問なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-075","examYear":"2023","examRound":"35","questionNumber":75,"category":"コミュニケーション技術","questionText":"利用者の家族と信頼関係を形成するための留意点として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族の希望を優先する。"},{"id":"2","text":"話し合いの機会を丁寧にもつ。"},{"id":"3","text":"一度形成した信頼関係は，変わらずに継続すると考える。"},{"id":"4","text":"家族に対して，「こうすれば良い」と指示を出す。"},{"id":"5","text":"介護は全面的に介護福祉職に任せてもらう。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！家族との信頼関係は、話し合いの機会を丁寧にもって、気持ちや希望を、聴くことで築かれるんだ。1は、家族の希望を、無条件に優先するわけではない。3は、信頼関係は、日々の関わりで変わる。4は、指示は、押しつけになる。5は、家族の役割も、尊重するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-076","examYear":"2023","examRound":"35","questionNumber":76,"category":"コミュニケーション技術","questionText":"Ｃさん（75歳，男性）は，老人性難聴（presbycusis）があり，右耳は中等度難聴，左耳は高度難聴である。耳かけ型補聴器を両耳で使用して静かな場所で話せば，なんとか相手の話を聞き取ることができる。\nＣさんとの1対1のコミュニケーションの方法として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"正面で向き合って話しかける。"},{"id":"2","text":"高音域の声を使って話しかける。"},{"id":"3","text":"耳元で，できるだけ大きな声で話しかける。"},{"id":"4","text":"手話で会話をする。"},{"id":"5","text":"からだに触れてから話しかける。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｃさんは、補聴器を使って、静かな場所なら、聞き取れるんだね。正面で向き合って話すと、口の動きや表情も見えて、理解しやすくなるよ。2は、高い声は、聞き取りにくい。3は、大きな声は、耳元でも、不快になる。4は、手話は、使えるとは限らない。5は、触れることは、気づかせる方法だけど、会話の方法としては、正面が最も適切だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-077","examYear":"2023","examRound":"35","questionNumber":77,"category":"コミュニケーション技術","questionText":"Ｄさん（90歳，女性，要介護5）は，重度のアルツハイマー型認知症（dementia of the Alzheimerʼs type）である。介護福祉職は，Ｄさんに声かけをして会話をしているが，最近，自発的な発語が少なくなり，会話中に視線が合わないことも増えてきたことが気になっている。\nＤさんとのコミュニケーションをとるための介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"引き続き，言語を中心にコミュニケーションをとる。"},{"id":"2","text":"Ｄさんが緊張しているので，からだに触れないようにする。"},{"id":"3","text":"表情やしぐさを確認しながら，感情の理解に努める。"},{"id":"4","text":"視線が合わないときは，会話を控える。"},{"id":"5","text":"自発的な発語がないため，会話の機会を減らしていく。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！重度の認知症で、自発的な発語や視線が減っても、表情やしぐさから、感情を読み取って、理解に努めることが大切なんだ。1、5は、言語に頼りすぎたり、機会を減らしたりして、関わりが減ってしまう。2は、触れることも、大切な関わり。4は、視線が合わなくても、会話を控える必要はないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-078","examYear":"2023","examRound":"35","questionNumber":78,"category":"コミュニケーション技術","questionText":"介護実践の場で行われる，勤務交代時の申し送りの目的に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"翌月の介護福祉職の勤務表を検討する。"},{"id":"2","text":"利用者のレクリエーション活動を計画する。"},{"id":"3","text":"利用者の問題解決に向けた事例検討を行う。"},{"id":"4","text":"利用者へのケアの継続性を保つ。"},{"id":"5","text":"利用者とケアの方針を共有する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！申し送りは、勤務が交代しても、利用者のケアを継続できるように、情報を引き継ぐための時間なんだ。1、2、3、5は、申し送りの目的ではなく、別の会議や、活動の目的だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-079","examYear":"2023","examRound":"35","questionNumber":79,"category":"コミュニケーション技術","questionText":"Ｅさん（87歳，女性，要介護3）は，介護老人福祉施設に入所していて，認知症（dementia）がある。ある日，担当のＦ介護福祉職がＥさんの居室を訪問すると，Ｅさんは，イライラした様子で，「私の財布が盗まれた」と言ってベッドの周りをうろうろしていた。一緒に探すと，タンスの引き出しの奥から財布が見つかった。Ｆ介護福祉職は，Ｅさんのケアカンファレンス（care conference）に出席して，この出来事について情報共有することにした。\nＥさんの状況に関する報告として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「Ｅさんの認知機能が低下しました」"},{"id":"2","text":"「Ｅさんは，誰かに怒っていました」"},{"id":"3","text":"「Ｅさんには，もの盗られ妄想があります」"},{"id":"4","text":"「Ｅさんは，財布が見つかって，安心していると思います」"},{"id":"5","text":"「Ｅさんは，財布が盗まれたと言って，ベッドの周りをうろうろしていました」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！カンファレンスでは、推測や解釈をまじえず、事実をそのまま報告することが大切なんだ。「財布が盗まれたと言って、ベッドの周りをうろうろしていました」は、見たままの事実だよ。1、2、3、4は、解釈や、判断が入っているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-080","examYear":"2023","examRound":"35","questionNumber":80,"category":"生活支援技術","questionText":"Ｇさん（79歳，女性，要介護3）は，介護老人福祉施設に入所して，3週間が経過した。施設での生活には慣れてきているが，居室でテレビを見て過ごす時間が長くなった。ある時，Ｇさんが，「気分転換に台所を借りて，自分でおやつを作ってみたい」と介護福祉職に話した。\nＧさんのレクリエーション活動の計画作成にあたり，介護福祉職が留意すべきこととして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｇさんの居室で行うようにする。"},{"id":"2","text":"おやつのメニューは，介護福祉職が選ぶ。"},{"id":"3","text":"施設のレクリエーション財を優先する。"},{"id":"4","text":"集団で行うことを優先する。"},{"id":"5","text":"おやつ作りをきっかけに，施設生活に楽しみがもてるようにする。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｇさんは、居室でテレビを見て過ごす時間が長くなっているね。おやつ作りをきっかけに、施設生活に楽しみをもてるようにすることが、大切なんだ。1は、居室ではなく、台所を使う希望。2は、メニューは、本人が選ぶ。3、4は、Ｇさんの希望よりも、施設の都合を優先しているよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-081","examYear":"2023","examRound":"35","questionNumber":81,"category":"生活支援技術","questionText":"高齢者の安全な移動に配慮した階段の要件として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"手すりを設置している。"},{"id":"2","text":"階段の一段の高さは，25 cm 以上である。"},{"id":"3","text":"階段の足をのせる板の奥行は，15 cm 未満である。"},{"id":"4","text":"階段の照明は，足元の間接照明にする。"},{"id":"5","text":"毛の長いじゅうたんを敷く。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！高齢者が安全に階段を使うためには、手すりの設置が、基本の要件なんだ。2は、一段の高さは、低めにする。3は、足をのせる板の奥行は、広めにする。4は、階段の照明は、足元が見えるように、明るくする。5は、毛の長いじゅうたんは、つまずきやすいよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-082","examYear":"2023","examRound":"35","questionNumber":82,"category":"生活支援技術","questionText":"介護予防教室で介護福祉職が行う安定した歩行に関する助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「歩幅を狭くしましょう」"},{"id":"2","text":"「腕の振りを小さくしましょう」"},{"id":"3","text":"「足元を見ながら歩きましょう」"},{"id":"4","text":"「後ろ足のつま先で地面を蹴って踏み出しましょう」"},{"id":"5","text":"「つま先から足をつきましょう」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！安定した歩行のためには、後ろ足のつま先で地面を蹴って、前に踏み出すようにすると、推進力が生まれるんだ。1は、歩幅は、広めにする。2は、腕は、大きく振る。3は、足元ではなく、少し先を見る。5は、かかとから足をつくのが、基本だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-083","examYear":"2023","examRound":"35","questionNumber":83,"category":"生活支援技術","questionText":"Ｔ字杖を用いて歩行する左片麻痺の利用者が，20 cm 幅の溝をまたぐときの介護方法として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"杖は，左手に持ちかえてもらう。"},{"id":"2","text":"杖は，溝の手前に突いてもらう。"},{"id":"3","text":"溝は，右足からまたいでもらう。"},{"id":"4","text":"遠い方向を見てもらう。"},{"id":"5","text":"またいだ後は，両足をそろえてもらう。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！溝をまたいだ後は、両足をそろえてもらうと、次の一歩に備えて、姿勢が安定するんだ。1は、杖は、健側の右手に持ったままにする。2は、杖は、溝の向こう側に突く。3は、患側の左足から先にまたぐ。4は、遠くではなく、足元や溝をよく見て、距離をつかむことが大切だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-084","examYear":"2023","examRound":"35","questionNumber":84,"category":"生活支援技術","questionText":"総義歯の取扱いに関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"上顎から先に外す。"},{"id":"2","text":"毎食後に洗う。"},{"id":"3","text":"スポンジブラシで洗う。"},{"id":"4","text":"熱湯につけてから洗う。"},{"id":"5","text":"乾燥させて保管する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！総義歯は、毎食後に、義歯ブラシと流水で洗って、清潔を保つんだ。1は、外すときは、下顎から外す場合もあるなど、順序は手順による。3は、義歯ブラシで洗う。4は、熱湯は、変形の原因になる。5は、乾燥させず、水につけて保管するよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-085","examYear":"2023","examRound":"35","questionNumber":85,"category":"生活支援技術","questionText":"Ｈさん（82歳，男性，要介護2）は，一人暮らしで，週1回，訪問介護（ホームヘルプサービス）を利用している。訪問時に，「足の爪が伸びているので，切ってほしい」と依頼された。爪を切ろうとしたところ，両足とも親指の爪が伸びて両端が皮膚に食い込んで赤くなっていて，触ると熱感があった。\n親指の状態を確認した訪問介護員（ホームヘルパー）の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"親指に絆創膏を巻く。"},{"id":"2","text":"Ｈさんの家にある軟膏を親指に塗る。"},{"id":"3","text":"蒸しタオルで爪を軟らかくしてから切る。"},{"id":"4","text":"爪が伸びている部分に爪やすりをかける。"},{"id":"5","text":"爪は切らずに，親指の状態をサービス提供責任者に報告する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！爪が皮膚に食い込んで、赤くなり、触ると熱感があるのは、炎症が起きている可能性があるんだ。介護福祉職は、爪を切らずに、サービス提供責任者に報告して、医療職につなげるのが適切だよ。1、2は、勝手な処置、3、4は、悪化させるおそれがあるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-086","examYear":"2023","examRound":"35","questionNumber":86,"category":"生活支援技術","questionText":"左片麻痺の利用者が，前開きの上着をベッド上で臥床したまま交換するときの介護の基本に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職は利用者の左側に立つ。"},{"id":"2","text":"新しい上着は利用者の右側に置く。"},{"id":"3","text":"脱ぐときは，着ている上着の左上肢の肩口を広げておく。"},{"id":"4","text":"左側の袖を脱ぎ，脱いだ上着は丸めて，からだの下に入れる。"},{"id":"5","text":"利用者を左側臥位にし，脱いだ上着を引き出す。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！左片麻痺の人の上着を、臥位のまま脱がせるときは、脱ぐ側の肩口を広げておくと、脱がせやすくなるんだ。1は、介護福祉職は、脱がせやすい側に立つ。2は、新しい上着は、患側（左側）に置くことが多い。4は、脱ぐのは、健側から先。5は、健側を下にして、脱いだ上着を引き出すよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-087","examYear":"2023","examRound":"35","questionNumber":87,"category":"生活支援技術","questionText":"利用者が食事中にむせ込んだときの介護として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"上を向いてもらう。"},{"id":"2","text":"お茶を飲んでもらう。"},{"id":"3","text":"深呼吸をしてもらう。"},{"id":"4","text":"口の中のものを飲み込んでもらう。"},{"id":"5","text":"しっかりと咳を続けてもらう。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！利用者が食事中にむせ込んだときは、しっかりと咳を続けてもらい、気管に入ったものを、外に出すのが基本なんだ。1は、上を向くと、誤嚥しやすい。2は、お茶を飲むと、さらにむせる。3は、深呼吸は、吸い込んでしまう。4は、飲み込ませると、誤嚥につながるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-088","examYear":"2023","examRound":"35","questionNumber":88,"category":"生活支援技術","questionText":"テーブルで食事の介護を行うときの留意点に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"車いすで食事をするときは，足をフットサポートから下ろして床につける。"},{"id":"2","text":"片麻痺があるときは，患側の上肢を膝の上にのせる。"},{"id":"3","text":"スプーンを使うときは，下顎を上げた姿勢にして食べ物を口に入れる。"},{"id":"4","text":"利用者に声をかけるときは，食べ物を口に入れてから行う。"},{"id":"5","text":"食事をしているときは，大きな音でテレビをつけておく。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！車いすで食事をするときは、足をフットサポートから下ろして、床につけると、姿勢が安定するんだ。2は、患側の上肢は、テーブルの上にのせる。3は、下顎を引いた姿勢にして、食べ物を口に入れる。4は、声をかけてから、口に入れる。5は、大きな音は、食事に集中できないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-089","examYear":"2023","examRound":"35","questionNumber":89,"category":"生活支援技術","questionText":"逆流性食道炎（reflux esophagitis）の症状がある利用者への助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"脂肪を多く含む食品を食べるように勧める。"},{"id":"2","text":"酸味の強い果物を食べるように勧める。"},{"id":"3","text":"1日の食事は回数を分けて少量ずつ食べるように勧める。"},{"id":"4","text":"食事のときは，腹圧をかけるような前かがみの姿勢をとるように勧める。"},{"id":"5","text":"食後すぐに仰臥位（背臥位）をとるように勧める。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！逆流性食道炎の症状がある人は、1日の食事を、回数を分けて、少量ずつ食べると、胃への負担が減って、逆流しにくくなるんだ。1は、脂肪の多い食品は、胃酸が増えて、悪化する。2は、酸味の強い果物は、刺激になる。4は、前かがみは、腹圧がかかって、逆流しやすい。5は、食後すぐの仰臥位は、逆流しやすいよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-090","examYear":"2023","examRound":"35","questionNumber":90,"category":"生活支援技術","questionText":"ベッド上で臥床している利用者の洗髪の基本に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者のからだ全体をベッドの端に移動する。"},{"id":"2","text":"利用者の両下肢は，まっすぐに伸ばした状態にする。"},{"id":"3","text":"洗うときは，頭頂部から生え際に向かって洗う。"},{"id":"4","text":"シャンプー後は，タオルで泡を拭き取ってからすすぐ。"},{"id":"5","text":"ドライヤーの温風は，頭皮に直接当たるようにする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！シャンプー後、タオルで泡を拭き取ってから、少ない湯ですすぐと、すすぎ残しを防ぎながら、使う湯の量も抑えられるんだ。1は、体全体ではなく、上半身を端に寄せる程度にする。2は、両膝を軽く曲げて安定させる。3は、生え際から頭頂部に向かって洗う。5は、ドライヤーは、頭皮に直接当てないようにするよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-091","examYear":"2023","examRound":"35","questionNumber":91,"category":"生活支援技術","questionText":"目の周囲の清拭の方法を図に示す。矢印は拭く方向を表している。\n次のＡ〜Ｅのうち，基本的な清拭の方法として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ａ"},{"id":"2","text":"Ｂ"},{"id":"3","text":"Ｃ"},{"id":"4","text":"Ｄ"},{"id":"5","text":"Ｅ"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！目の清拭は、目頭（鼻側、涙の出口がある側）から、目尻（耳側）に向かって、一方向に拭くのが基本なんだ。図のＡは、その向きに合っているよ。汚れを目頭側へ押し戻さないように、気をつけるんだね。Ｂ〜Ｅは、往復して拭いたり、向きがそろっていなかったりして、基本の方法とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-092","examYear":"2023","examRound":"35","questionNumber":92,"category":"生活支援技術","questionText":"Ｊさん（85歳，女性，要介護2）は，アルツハイマー型認知症（dementia of the Alzheimerʼs type）である。時間をかければ一人で洗身，洗髪もできるが，ズボンの上に下着を着る行為がみられたため，訪問介護（ホームヘルプサービス）を利用することになった。\nＪさんの入浴時における訪問介護員（ホームヘルパー）の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"脱いだ衣服は，着る衣服の隣に並べて置く。"},{"id":"2","text":"洗身と洗髪は訪問介護員（ホームヘルパー）が行う。"},{"id":"3","text":"入浴中の利用者に声をかけることは控える。"},{"id":"4","text":"衣服の着る順番に応じて声をかける。"},{"id":"5","text":"ズボンの着脱は訪問介護員（ホームヘルパー）が行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｊさんは、下着とズボンの着る順番を、間違えることがあるので、着る順番に応じて、声をかけると、自分で着られるよ。1は、衣服を並べると、混乱することもある。2、5は、できることまで、代わりにやってしまう。3は、入浴中の声かけは、必要だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-093","examYear":"2023","examRound":"35","questionNumber":93,"category":"生活支援技術","questionText":"胃・結腸反射を利用して，生理的排便を促すための介護福祉職の支援として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"歩行を促す。"},{"id":"2","text":"起床後に冷水を飲んでもらう。"},{"id":"3","text":"腹部のマッサージをする。"},{"id":"4","text":"便座に誘導する。"},{"id":"5","text":"離床する時間を増やす。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！胃・結腸反射は、朝起きてすぐに冷たい水を飲むと、胃が刺激されて、大腸の動きが活発になり、便意が起こる反射なんだ。起床後の冷水は、この反射を直接利用した支援だよ。1の歩行、3の腹部マッサージ、5の離床時間を増やすことも、排便を助けるけれど、胃・結腸反射を利用した支援ではないんだ。4は、反射が起きたあとの対応だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-094","examYear":"2023","examRound":"35","questionNumber":94,"category":"生活支援技術","questionText":"利用者の便失禁を改善するための介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"トイレの場所がわからない認知症（dementia）の人には，ポータブルトイレを設"},{"id":"2","text":"移動に時間がかかる人には，おむつを使用する。"},{"id":"3","text":"便意がはっきりしない人には，朝食後に時間を決めてトイレへ誘導する。"},{"id":"4","text":"下剤を内服している人には，下剤の内服を中止する。"},{"id":"5","text":"便失禁の回数が多い人には，食事の提供量を減らす。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！便意がはっきりしない人は、朝食後の胃・結腸反射を利用して、時間を決めてトイレへ誘導すると、便失禁を減らせるんだ。1は、トイレの場所がわからない人には、トイレの表示など、わかりやすくする。2は、おむつは、自立を妨げる。4は、下剤は、医師の指示に従う。5は、食事を減らすのは、不適切だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-095","examYear":"2023","examRound":"35","questionNumber":95,"category":"生活支援技術","questionText":"女性利用者のおむつ交換をするときに行う陰部洗浄の基本に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"湯温は，介護福祉職の手のひらで確認する。"},{"id":"2","text":"おむつを交換するたびに，石鹸を使って洗う。"},{"id":"3","text":"タオルで汚れをこすり取るように洗う。"},{"id":"4","text":"尿道口から洗い，最後に肛門部を洗う。"},{"id":"5","text":"洗浄後は，蒸しタオルで水分を拭き取る。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！女性の陰部洗浄では、尿道口から、膣、肛門へと、清潔な部分から汚れた部分の順に洗って、尿路感染症を防ぐんだ。1は、湯温は、前腕内側で確認する。2は、毎回石けんは、必要ない。3は、こすらず、やさしく洗う。5は、洗浄後は、乾いたタオルで、水分を押さえ拭きするよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-096","examYear":"2023","examRound":"35","questionNumber":96,"category":"生活支援技術","questionText":"Ｋさん（76歳，女性，要介護2）は，介護老人保健施設に入所している。日頃から，「排泄は最期まで他人の世話にならない」と言い，自分でトイレに行き排泄している。先日，趣味活動に参加しているときにトイレに間に合わず失禁した。その後，トイレの近くで過ごすことが多くなり，趣味活動に参加することが少なくなった。Ｋさんを観察すると，1日の水分摂取量，排尿量は変わりないが，日中の排尿回数が増えていることがわかった。\nＫさんへの介護福祉職の最初の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"日中は水分摂取を控えるように伝える。"},{"id":"2","text":"抗不安薬の処方ができないか看護師に相談する。"},{"id":"3","text":"トイレに行く姿を見かけたら，同行する。"},{"id":"4","text":"排泄について不安に感じていることがないかを聞く。"},{"id":"5","text":"積極的に趣味活動に参加するように勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｋさんは、失禁がきっかけで、トイレの近くで過ごして、趣味活動にも参加しなくなったんだね。まずは、排泄について不安に感じていることがないかを聞いて、気持ちを受け止めるのが、最初の対応だよ。1は、水分を控えるのは、危険。2は、薬の相談は、まだ早い。3は、羞恥心に配慮せず、同行してしまう。5は、参加を促すだけでは、不安が解決しないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-097","examYear":"2023","examRound":"35","questionNumber":97,"category":"生活支援技術","questionText":"ノロウイルス（Norovirus）による感染症の予防のための介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食品は，中心部温度50℃で1分間加熱する。"},{"id":"2","text":"嘔吐物は，乾燥後に処理をする。"},{"id":"3","text":"マスクと手袋を着用して，嘔吐物を処理する。"},{"id":"4","text":"手すりの消毒は，エタノール消毒液を使用する。"},{"id":"5","text":"嘔吐物のついたシーツは，洗濯機で水洗いする。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ノロウイルスの嘔吐物を処理するときは、マスクと手袋を着用して、感染を防ぐんだ。1は、食品は、中心部を85〜90℃で90秒以上加熱する。2は、嘔吐物は、乾燥すると、ウイルスが舞うので、乾燥する前に処理する。4は、アルコールは、効果が弱く、次亜塩素酸ナトリウムを使う。5は、洗濯の前に、消毒が必要だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-098","examYear":"2023","examRound":"35","questionNumber":98,"category":"生活支援技術","questionText":"弱視で物の区別がつきにくい人の調理と買い物の支援に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"買い物は，ガイドヘルパーに任せるように勧める。"},{"id":"2","text":"財布は，貨幣や紙幣を同じ場所に収納できるものを勧める。"},{"id":"3","text":"包丁は，調理台の手前に置くように勧める。"},{"id":"4","text":"まな板は，食材と同じ色にするように勧める。"},{"id":"5","text":"よく使う調理器具は，いつも同じ場所に収納するように勧める。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！弱視の人には、よく使う調理器具を、いつも同じ場所に収納すると、探しやすくて、安全に調理できるんだ。1は、ガイドヘルパーに任せきりにしない。2は、貨幣と紙幣は、別々に分けて入れる。3は、包丁は、手前に置くと危険。4は、まな板は、食材と反対の色にして、見やすくするよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-099","examYear":"2023","examRound":"35","questionNumber":99,"category":"生活支援技術","questionText":"次の記述のうち，関節リウマチ（rheumatoid arthritis）のある人が，少ない負担で家事をするための介護福祉職の助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"部屋の掃除をするときは，早朝に行うように勧める。"},{"id":"2","text":"食器を洗うときは，水を使うように勧める。"},{"id":"3","text":"テーブルを拭くときは，手掌基部を使うように勧める。"},{"id":"4","text":"瓶のふたを開けるときは，指先を使うように勧める。"},{"id":"5","text":"洗濯かごを運ぶときは，片手で持つように勧める。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！関節リウマチの人は、関節に負担をかけないように、手のひらの付け根（手掌基部）を使って、テーブルを拭くのがよいんだ。1は、朝は、こわばりが強いので、避ける。2は、水ではなく、ぬるま湯を使う。4は、指先ではなく、手のひら全体を使う。5は、片手ではなく、両手で持つか、台車を使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-100","examYear":"2023","examRound":"35","questionNumber":100,"category":"生活支援技術","questionText":"睡眠の環境を整える介護に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"マットレスは，腰が深く沈む柔らかさのものにする。"},{"id":"2","text":"枕は，頸部が前屈する高さにする。"},{"id":"3","text":"寝床内の温度を20℃に調整する。"},{"id":"4","text":"臭気がこもらないように，寝室の換気をする。"},{"id":"5","text":"睡眠状態を観察できるように，寝室のドアは開けておく。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！寝室に臭気がこもらないように、換気をして、空気を入れ替えると、快適に眠れるんだ。1は、柔らかすぎると、腰が沈んで、寝返りが打ちにくい。2は、頸部が前屈しない高さにする。3は、寝床内の温度は、33℃前後が目安。5は、ドアは、必要に応じて、静かに確認するけれど、開けておく必要はないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-101","examYear":"2023","examRound":"35","questionNumber":101,"category":"生活支援技術","questionText":"利用者の入眠に向けた介護福祉職の助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「足をお湯につけて温めてから寝ましょう」"},{"id":"2","text":"「寝室の照明を，昼光色の蛍光灯に変えましょう」"},{"id":"3","text":"「布団に入ってから，短く浅い呼吸を繰り返しましょう」"},{"id":"4","text":"「入眠への習慣は控えましょう」"},{"id":"5","text":"「寝る前に，汗をかく運動をしましょう」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！足をお湯につけて温める足浴は、血行がよくなって、体がリラックスするので、入眠を助けるんだ。2は、昼光色は、覚醒を促す。3は、深くゆっくりした呼吸のほうが、リラックスできる。4は、入眠の習慣は、大切にする。5は、寝る直前の運動は、目が覚めてしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-102","examYear":"2023","examRound":"35","questionNumber":102,"category":"生活支援技術","questionText":"終末期で終日臥床している利用者に対する介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"入浴時は，肩までお湯につかるように勧める。"},{"id":"2","text":"息苦しさを訴えたときは，半座位にする。"},{"id":"3","text":"終日，窓を閉めたままにする。"},{"id":"4","text":"会話をしないように勧める。"},{"id":"5","text":"排便時は，息を止めて腹に力を入れるように勧める。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！終末期の人が、息苦しさを訴えたときは、半座位にすると、呼吸が楽になるんだ。1は、肩まで湯につかると、心臓に負担がかかる。3は、窓を閉めたままにせず、換気をする。4は、会話は、本人の希望に合わせる。5は、息を止めて力を入れるのは、負担が大きいよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-103","examYear":"2023","examRound":"35","questionNumber":103,"category":"生活支援技術","questionText":"介護老人福祉施設に入所している利用者の看取りにおける，介護福祉職による家族への支援として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の介護は，介護福祉職が最期まで行い，家族には控えてもらう。"},{"id":"2","text":"利用者の反応がないときには，声をかけることを控えるように伝える。"},{"id":"3","text":"利用者の死後は，毎日電話をして，家族の状況を確認する。"},{"id":"4","text":"利用者の死後は，気分を切り替えるように家族を励ます。"},{"id":"5","text":"家族が悔いが残ると言ったときは，話を聴く。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！家族が、「悔いが残る」と話したときは、否定や励ましではなく、まず話を聴いて、気持ちを受け止めることが、大切なんだ。1は、家族も一緒に、介護に関わってもらう。2は、反応がなくても、声かけは続ける。3は、毎日の電話は、負担になる。4は、励ますだけでは、悲嘆に寄り添えないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-104","examYear":"2023","examRound":"35","questionNumber":104,"category":"生活支援技術","questionText":"利用者の障害特性に適した福祉用具の選択に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"言語機能障害の利用者には，ストッキングエイドの使用を勧める。"},{"id":"2","text":"全盲の利用者には，音声ガイド付き電磁調理器の使用を勧める。"},{"id":"3","text":"聴覚障害の利用者には，床置き式手すりの使用を勧める。"},{"id":"4","text":"右片麻痺の利用者には，交互型歩行器の使用を勧める。"},{"id":"5","text":"肘関節拘縮の利用者には，座位時に体圧分散クッションの使用を勧める。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！全盲の人には、音声ガイド付きの電磁調理器が、火を使わずに、安全に調理でき、操作も音で確認できるので、適しているんだ。1のストッキングエイドは、靴下を履く用具。3の床置き式手すりは、立ち座りを支える用具。4の交互型歩行器は、両手が使える人向け。5の体圧分散クッションは、褥瘡予防の用具だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-105","examYear":"2023","examRound":"35","questionNumber":105,"category":"生活支援技術","questionText":"福祉用具等を安全に使用するための方法として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"車いすをたたむときは，ブレーキをかけてから行う。"},{"id":"2","text":"入浴用介助ベルトは，利用者の腰部を真上に持ち上げて使用する。"},{"id":"3","text":"差し込み便器は，端座位で使用する。"},{"id":"4","text":"移動用リフトで吊り上げるときは，利用者のからだから手を離して行う。"},{"id":"5","text":"簡易スロープは，埋め込み工事をして使用する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！車いすをたたむときは、事故を防ぐために、ブレーキをかけてから行うんだ。2は、入浴用介助ベルトは、腰を、斜め前方向に引き上げる。3は、差し込み便器は、臥位で使う。4は、移動用リフトで吊り上げるときは、利用者から目を離さず、体に触れて確認する。5は、簡易スロープは、工事なしで置いて使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-106","examYear":"2023","examRound":"35","questionNumber":106,"category":"介護過程","questionText":"介護過程を展開する目的として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"業務効率を優先する。"},{"id":"2","text":"医師と連携する。"},{"id":"3","text":"ケアプランを作成する。"},{"id":"4","text":"画一的な介護を実現する。"},{"id":"5","text":"根拠のある介護を実践する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護過程を展開する目的は、利用者一人ひとりに合った、根拠のある介護を実践することなんだ。1は、業務効率を優先しない。2は、連携は、手段の一つ。3は、ケアプランは、介護支援専門員が作る。4は、画一的ではなく、個別的な介護をめざすよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-107","examYear":"2023","examRound":"35","questionNumber":107,"category":"介護過程","questionText":"次のうち，介護過程を展開した結果を評価する項目として，最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"実施に要した日数"},{"id":"2","text":"情報収集に要した時間"},{"id":"3","text":"評価に要した時間"},{"id":"4","text":"介護福祉職チームの満足度"},{"id":"5","text":"短期目標の達成度"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護過程を評価するときは、短期目標が、どのくらい達成できたかが、最も優先すべき項目なんだ。1、2、3の日数や時間、4のチームの満足度は、利用者の状態の変化を評価するものではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-108","examYear":"2023","examRound":"35","questionNumber":108,"category":"介護過程","questionText":"次の記述のうち，居宅サービス計画と訪問介護計画の関係として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"訪問介護計画を根拠に，居宅サービス計画を作成する。"},{"id":"2","text":"居宅サービス計画の目標が変更されても，訪問介護計画は見直しをせず継続する。"},{"id":"3","text":"居宅サービス計画と同じ内容を，訪問介護計画に転記する。"},{"id":"4","text":"居宅サービス計画の方針に沿って，訪問介護計画を作成する。"},{"id":"5","text":"訪問介護計画の終了後に，居宅サービス計画を作成する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！訪問介護計画は、居宅サービス計画の方針に沿って、作成するんだ。1は、順序が逆。2は、目標が変更されたら、見直す。3は、同じ内容の転記ではなく、具体的に作る。5は、居宅サービス計画は、先に作成されるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-109","examYear":"2023","examRound":"35","questionNumber":109,"category":"介護過程","questionText":"次の事例を読んで，問題109，問題110について答えなさい。\n〔事例〕\nＬさん（76歳，女性，要介護1）は，自宅で娘と暮らしている。軽度の認知症（dementia）と診断されたが，身体機能に問題はなく，友人との外出を楽しんでいる。ある日，外食の後，自宅近くで保護されたとき，「ここはどこなの」と言った。その後，自宅から出ようとしなくなった。心配した娘が本人と相談して，小規模多機能型居宅介護を利用することになった。利用開始時に，Ｌさんの短期目標を，「外出を楽しめる」と設定した。2週間が過ぎた頃，Ｌさんから，近くのスーパーへの買い物ツアーに参加したいと申し出があった。当日，他の利用者や介護福祉職と笑顔で買い物をする様子が見られた。買い物が終わり，歩いて戻り始めると，笑顔が消え，急に立ち止まった。介護福祉職が声をかけると，「ここはどこなの。どこに行くの」と不安そうに言った。\nＬさんが急に立ち止まった行動の解釈として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"買い物ツアー時間の延長の要求"},{"id":"2","text":"自分のいる場所がわからない不安"},{"id":"3","text":"休憩したいという訴え"},{"id":"4","text":"店での介護福祉職の支援に対する不満"},{"id":"5","text":"一人で帰りたいという訴え"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｌさんは、歩いて戻る途中で、笑顔が消えて、「ここはどこなの。どこに行くの」と、不安そうに話したよね。これは、自分のいる場所がわからなくなった、不安のあらわれと考えられるんだ。1、3、4、5は、Ｌさんの言葉や様子から、読み取れないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-110","examYear":"2023","examRound":"35","questionNumber":110,"category":"介護過程","questionText":"次の事例を読んで，問題109，問題110について答えなさい。\n〔事例〕\nＬさん（76歳，女性，要介護1）は，自宅で娘と暮らしている。軽度の認知症（dementia）と診断されたが，身体機能に問題はなく，友人との外出を楽しんでいる。ある日，外食の後，自宅近くで保護されたとき，「ここはどこなの」と言った。その後，自宅から出ようとしなくなった。心配した娘が本人と相談して，小規模多機能型居宅介護を利用することになった。利用開始時に，Ｌさんの短期目標を，「外出を楽しめる」と設定した。2週間が過ぎた頃，Ｌさんから，近くのスーパーへの買い物ツアーに参加したいと申し出があった。当日，他の利用者や介護福祉職と笑顔で買い物をする様子が見られた。買い物が終わり，歩いて戻り始めると，笑顔が消え，急に立ち止まった。介護福祉職が声をかけると，「ここはどこなの。どこに行くの」と不安そうに言った。\nＬさんの状況から，短期目標と支援内容を見直すためのカンファレンス（conference）が開かれた。\n担当する介護福祉職の提案として，最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"外出先から帰れなくなる不安への対応が必要である。"},{"id":"2","text":"表情がかたくなったときは帰り道を変更する。"},{"id":"3","text":"外出する意欲を持つ必要がある。"},{"id":"4","text":"歩くために身体機能の改善が必要である。"},{"id":"5","text":"事業所をなじみの生活空間にする。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｌさんは、外出先で、帰り道がわからなくなって、不安になったんだね。だから、外出先から帰れなくなる不安への対応が、最も優先すべき提案だよ。2は、帰り道を変えるだけでは、不安が解決しない。3は、意欲は、すでにある。4は、身体機能に問題はない。5は、外出の目標と、合わなくなるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-111","examYear":"2023","examRound":"35","questionNumber":111,"category":"介護過程","questionText":"次の事例を読んで，問題111，問題112について答えなさい。\n〔事例〕\nＭさん（35歳，男性，障害支援区分5）は，脳性麻痺（cerebral palsy）による四肢麻痺で筋緊張がある。日常生活動作は全般に介護が必要であり，電動車いすを使用している。これまで，本人と母親（70歳）の希望で，自宅で二人暮らしを続けてきた。Ｍさんは3年前から，重度訪問介護を利用している。軽度の知的障害があるが，自分の意思を介護者と母親に伝えることができる。相談支援専門員が作成したサービス等利用計画の総合目標は，「やりたいことに挑戦し，生活を充実させる」となっている。Ｍさん自身も，やりたいことを見つけたいと介護福祉職に話していたことから，次の個別支援会議で検討する予定になっていた。ある日，重度訪問介護の利用時，パラリンピックのテレビ中継を見ていたＭさんが，介護福祉職に，「ボール投げるの，おもしろそう」と話した。\n次のうち，Ｍさんの発言から，個別支援計画を立案するために，介護福祉職が把握すべき情報として，最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"競技で使われるボールの種類"},{"id":"2","text":"話を聞いた介護福祉職の感想"},{"id":"3","text":"競技に対するＭさんの意向"},{"id":"4","text":"母親のパラリンピックへの関心"},{"id":"5","text":"テレビ中継を見ていた時間"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｍさんは、テレビを見て、「ボール投げるの、おもしろそう」と話したんだね。個別支援計画を立てるうえで、最も優先すべきなのは、その競技に対する、Ｍさん本人の意向を、把握することだよ。1、2、4、5は、Ｍさんの意向とは、直接関係がない情報なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-112","examYear":"2023","examRound":"35","questionNumber":112,"category":"介護過程","questionText":"次の事例を読んで，問題111，問題112について答えなさい。\n〔事例〕\nＭさん（35歳，男性，障害支援区分5）は，脳性麻痺（cerebral palsy）による四肢麻痺で筋緊張がある。日常生活動作は全般に介護が必要であり，電動車いすを使用している。これまで，本人と母親（70歳）の希望で，自宅で二人暮らしを続けてきた。Ｍさんは3年前から，重度訪問介護を利用している。軽度の知的障害があるが，自分の意思を介護者と母親に伝えることができる。相談支援専門員が作成したサービス等利用計画の総合目標は，「やりたいことに挑戦し，生活を充実させる」となっている。Ｍさん自身も，やりたいことを見つけたいと介護福祉職に話していたことから，次の個別支援会議で検討する予定になっていた。ある日，重度訪問介護の利用時，パラリンピックのテレビ中継を見ていたＭさんが，介護福祉職に，「ボール投げるの，おもしろそう」と話した。\nいくつかのスポーツクラブを見学後，介護福祉職はＭさんから，「このスポーツクラブが近いから，入会前に体験したい」と伝えられた。\nＭさんへの介護福祉職の対応に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"筋緊張から回復する訓練を行うように伝える。"},{"id":"2","text":"母親が決めたスポーツクラブを選ぶように勧める。"},{"id":"3","text":"スポーツクラブにすぐに入会するように勧める。"},{"id":"4","text":"意思決定に必要な情報を提供する。"},{"id":"5","text":"相談支援専門員の許可を得るように勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｍさんは、軽度の知的障害があるけれど、自分の意思を伝えられるんだね。意思決定支援では、Ｍさんが自分で決められるように、必要な情報を、わかりやすく提供することが大切だよ。1は、機能回復訓練は、今の希望と合わない。2は、母親ではなく、本人が決める。3は、決めるのを急がせない。5は、許可を得る必要はないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-113","examYear":"2023","examRound":"35","questionNumber":113,"category":"介護過程","questionText":"介護福祉職が事例研究を行う目的として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"事業所の介護の理念の確認"},{"id":"2","text":"介護福祉職の能力を調べること"},{"id":"3","text":"介護過程から介護実践を振り返ること"},{"id":"4","text":"介護報酬の獲得"},{"id":"5","text":"介護福祉職自身の満足度の充足"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！事例研究の目的は、介護過程を振り返って、介護実践を客観的に分析し、今後の介護に生かすことなんだ。1は、理念の確認、2は、能力の評価、4は、報酬の獲得、5は、満足度の充足で、いずれも、事例研究の目的ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-114","examYear":"2023","examRound":"35","questionNumber":114,"category":"総合問題","questionText":"次の事例を読んで，問題114から問題116までについて答えなさい。\n〔事例〕\nＡさん（80歳，女性）は，自宅で一人暮らしをしている。同じ県内に住む娘が，月に一度Ａさんの自宅を訪れている。最近，Ａさんの物忘れが多くなってきたため，不安になった娘が，Ａさんと一緒に病院を受診したところ，医師から，脳の記憶をつかさどる部分が顕著に萎縮したアルツハイマー型認知症（dementia of the Alzheimerʼs type）であると診断された。Ａさんはこのまま自宅で暮らすことを希望し，介護保険の訪問介護（ホームヘルプサービス）を利用しながら一人暮らしを継続することになった。ある日，娘からサービス提供責任者に，今年はＡさんが一人で雪かきができるか不安であると相談があった。そこで，サービス提供責任者が，Ａさんと一緒に地区の民生委員に相談したところ，近所の人たちが雪かきをしてくれることになった。\n図は脳を模式的に示したものである。\nＡさんの脳に萎縮が顕著にみられる部位として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ａ"},{"id":"2","text":"Ｂ"},{"id":"3","text":"Ｃ"},{"id":"4","text":"Ｄ"},{"id":"5","text":"Ｅ"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！図のDは、側頭葉の内側にある、海馬（かいば）を指しているんだ。海馬は、新しい記憶をつくる働きをする部位で、アルツハイマー型認知症では、ここを中心に萎縮が目立つよ。Aは側頭葉の外側、Bは頭頂葉、Cは後頭葉、Eは延髄（脳幹）を指していて、それぞれ感覚や視覚、生命維持などをつかさどる部位なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-115","examYear":"2023","examRound":"35","questionNumber":115,"category":"総合問題","questionText":"次の事例を読んで，問題114から問題116までについて答えなさい。\n〔事例〕\nＡさん（80歳，女性）は，自宅で一人暮らしをしている。同じ県内に住む娘が，月に一度Ａさんの自宅を訪れている。最近，Ａさんの物忘れが多くなってきたため，不安になった娘が，Ａさんと一緒に病院を受診したところ，医師から，脳の記憶をつかさどる部分が顕著に萎縮したアルツハイマー型認知症（dementia of the Alzheimerʼs type）であると診断された。Ａさんはこのまま自宅で暮らすことを希望し，介護保険の訪問介護（ホームヘルプサービス）を利用しながら一人暮らしを継続することになった。ある日，娘からサービス提供責任者に，今年はＡさんが一人で雪かきができるか不安であると相談があった。そこで，サービス提供責任者が，Ａさんと一緒に地区の民生委員に相談したところ，近所の人たちが雪かきをしてくれることになった。\n地域包括ケアシステムにおいて，Ａさんの雪かきの課題への対応を示すものとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自助"},{"id":"2","text":"互助"},{"id":"3","text":"介助"},{"id":"4","text":"扶助"},{"id":"5","text":"公助"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！近所の人たちが、雪かきをしてくれるのは、地域の人同士の助け合いで、互助にあたるんだ。1の自助は、自分自身で行う努力、3の介助は、介護の言葉、4の扶助と、5の公助は、公的な支援だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-116","examYear":"2023","examRound":"35","questionNumber":116,"category":"総合問題","questionText":"次の事例を読んで，問題114から問題116までについて答えなさい。\n〔事例〕\nＡさん（80歳，女性）は，自宅で一人暮らしをしている。同じ県内に住む娘が，月に一度Ａさんの自宅を訪れている。最近，Ａさんの物忘れが多くなってきたため，不安になった娘が，Ａさんと一緒に病院を受診したところ，医師から，脳の記憶をつかさどる部分が顕著に萎縮したアルツハイマー型認知症（dementia of the Alzheimerʼs type）であると診断された。Ａさんはこのまま自宅で暮らすことを希望し，介護保険の訪問介護（ホームヘルプサービス）を利用しながら一人暮らしを継続することになった。ある日，娘からサービス提供責任者に，今年はＡさんが一人で雪かきができるか不安であると相談があった。そこで，サービス提供責任者が，Ａさんと一緒に地区の民生委員に相談したところ，近所の人たちが雪かきをしてくれることになった。\nある日，訪問介護員（ホームヘルパー）がＡさんの自宅を訪れ，一包化された薬の服薬状況を確認したところ，残薬があった。Ａさんに服薬状況を確認すると，薬を飲んだかどうか，わからなくなることがあるという返答があった。訪問介護員（ホームヘルパー）は，Ａさんとの会話から，日時に関する見当識に問題はないことを確認した。\nＡさんの薬の飲み忘れを防止するための対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"一包化を中止する。"},{"id":"2","text":"インフォーマルな社会資源の活用は避ける。"},{"id":"3","text":"お薬カレンダーの使用を提案する。"},{"id":"4","text":"一人では薬を服用しないように伝える。"},{"id":"5","text":"薬の飲み忘れに気がついたとき，2回分を服用するように伝える。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ａさんは、日時の見当識は保たれていて、薬を飲んだかどうかを、わからなくなることがあるんだね。お薬カレンダーを使うと、飲んだかどうかが、一目でわかって、飲み忘れを防げるよ。1は、一包化は、飲み間違いを防ぐ。2は、インフォーマルな資源も、活用する。4は、自立を妨げる。5は、2回分の服用は、危険だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-117","examYear":"2023","examRound":"35","questionNumber":117,"category":"総合問題","questionText":"次の事例を読んで，問題117から問題119までについて答えなさい。\n〔事例〕\nＢさん（75歳，男性，要介護3）は，1年前に脳梗塞（cerebral infarction）を発症し，右片麻痺がある。自宅では，家具や手すりにつかまって，なんとか自力歩行し，外出時は車いすを使用していた。うまく話すことができないこともあるが，他者の話を聞き取って理解することは，問題なくできていて，介護保険サービスを利用しながら，一人で暮らしていた。数か月前から着替えや入浴に介助が必要になり，在宅生活が難しくなったため，1週間前にＵ介護老人福祉施設に入所した。入所時の面談でＢさんは，自分の力で歩きたいという意思を示した。Ｕ介護老人福祉施設では，Ｃ介護福祉士をＢさんの担当者に選定した。Ｃ介護福祉士は，カンファレンス（conference）での意見に基づいて，Ｂさんが，四点杖を使用して，安全に施設内を歩行できることを短期目標とした介護計画を立案した。\n入所から2か月が経過した。Ｃ介護福祉士は，Ｂさんの四点杖歩行の様子を観察したところ，左立脚相と比べて，右立脚相が短いことが気になった。Ｂさんの短期目標を達成するために，理学療法士と相談して，転倒予防の観点から，見守り歩行をするときの介護福祉職の位置について，改めて周知することにした。\nＢさんの四点杖歩行を見守るときに介護福祉職が立つ位置として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｂさんの右側前方"},{"id":"2","text":"Ｂさんの右側後方"},{"id":"3","text":"Ｂさんの真後ろ"},{"id":"4","text":"Ｂさんの左側前方"},{"id":"5","text":"Ｂさんの左側後方"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！右片麻痺のあるＢさんの歩行を見守るときは、麻痺のある側（右側）の、後方に立って、転倒したときに、すぐに支えられるようにするんだ。右立脚相が短いことも、右側の不安定さを示しているよ。1、4は、前方で、支えにくい。3は、真後ろでは、麻痺側を支えにくい。5は、健側の左側は、優先度が低いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-118","examYear":"2023","examRound":"35","questionNumber":118,"category":"総合問題","questionText":"次の事例を読んで，問題117から問題119までについて答えなさい。\n〔事例〕\nＢさん（75歳，男性，要介護3）は，1年前に脳梗塞（cerebral infarction）を発症し，右片麻痺がある。自宅では，家具や手すりにつかまって，なんとか自力歩行し，外出時は車いすを使用していた。うまく話すことができないこともあるが，他者の話を聞き取って理解することは，問題なくできていて，介護保険サービスを利用しながら，一人で暮らしていた。数か月前から着替えや入浴に介助が必要になり，在宅生活が難しくなったため，1週間前にＵ介護老人福祉施設に入所した。入所時の面談でＢさんは，自分の力で歩きたいという意思を示した。Ｕ介護老人福祉施設では，Ｃ介護福祉士をＢさんの担当者に選定した。Ｃ介護福祉士は，カンファレンス（conference）での意見に基づいて，Ｂさんが，四点杖を使用して，安全に施設内を歩行できることを短期目標とした介護計画を立案した。\nＣ介護福祉士がＢさんとコミュニケーションをとるための方法に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"補聴器を使用する。"},{"id":"2","text":"五十音表を使用する。"},{"id":"3","text":"手話を使う。"},{"id":"4","text":"大きな声で話しかける。"},{"id":"5","text":"「はい」「いいえ」で回答できる質問を中心に用いる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｂさんは、うまく話せないことがあるけれど、聞き取って理解することは、できるんだね。だから、「はい」「いいえ」で答えられる質問を、中心に使うと、コミュニケーションがとりやすいよ。1、3は、聴覚の障害ではない。2は、五十音表は、負担が大きい。4は、大きな声は、必要ないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-119","examYear":"2023","examRound":"35","questionNumber":119,"category":"総合問題","questionText":"次の事例を読んで，問題117から問題119までについて答えなさい。\n〔事例〕\nＢさん（75歳，男性，要介護3）は，1年前に脳梗塞（cerebral infarction）を発症し，右片麻痺がある。自宅では，家具や手すりにつかまって，なんとか自力歩行し，外出時は車いすを使用していた。うまく話すことができないこともあるが，他者の話を聞き取って理解することは，問題なくできていて，介護保険サービスを利用しながら，一人で暮らしていた。数か月前から着替えや入浴に介助が必要になり，在宅生活が難しくなったため，1週間前にＵ介護老人福祉施設に入所した。入所時の面談でＢさんは，自分の力で歩きたいという意思を示した。Ｕ介護老人福祉施設では，Ｃ介護福祉士をＢさんの担当者に選定した。Ｃ介護福祉士は，カンファレンス（conference）での意見に基づいて，Ｂさんが，四点杖を使用して，安全に施設内を歩行できることを短期目標とした介護計画を立案した。\n入所から3か月後，Ｃ介護福祉士は，Ｂさんの四点杖歩行が安定してきたことを確認して介護計画を見直すことにした。Ｃ介護福祉士がＢさんに，今後の生活について確認したところ，居室から食堂まで，四点杖で一人で歩けるようになりたいと思っていることがわかった。\nＢさんの現在の希望に沿って介護計画を見直すときに，最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"生活場面の中で歩行する機会を増やす。"},{"id":"2","text":"評価日は設定しない。"},{"id":"3","text":"ほかの利用者と一緒に実施できる内容にする。"},{"id":"4","text":"他者との交流を目標にする。"},{"id":"5","text":"歩行練習を行う時間は，出勤している職員が決めるようにする。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｂさんは、居室から食堂まで、四点杖で、一人で歩けるようになりたいと希望しているよね。だから、生活場面の中で、歩行する機会を増やすことが、最も優先すべきなんだ。2は、評価日は、必ず設定する。3、4は、Ｂさんの希望とは、ちがう。5は、練習の時間は、本人と相談して決めるよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-120","examYear":"2023","examRound":"35","questionNumber":120,"category":"総合問題","questionText":"次の事例を読んで，問題120から問題122までについて答えなさい。\n〔事例〕\nＤさん（38歳，男性，障害支援区分3）は，1年前に脳梗塞（cerebral infarction）を発症し左片麻痺となった。後遺症として左同名半盲，失行もみられる。現在は週3回，居宅介護を利用しながら妻と二人で生活している。ある日，上着の袖に頭を入れようとしているＤさんに介護福祉職が声をかけると，「どうすればよいかわからない」と答えた。普段は妻がＤさんの着替えを手伝っている。食事はスプーンを使用して自分で食べるが，左側にある食べ物を残すことがある。Ｄさんは，「左側が見づらい。動いているものにもすぐに反応ができない」と話した。最近は，日常生活の中で，少しずつできることが増えてきた。Ｄさんは，「人と交流する機会を増やしたい。また，簡単な生産活動ができるようなところに行きたい」と介護福祉職に相談した。\nＤさんにみられた失行として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"構成失行"},{"id":"2","text":"観念失行"},{"id":"3","text":"着衣失行"},{"id":"4","text":"顔面失行"},{"id":"5","text":"観念運動失行"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｄさんは、上着の袖に頭を入れようとして、着方がわからなくなっているね。これは、着衣失行の症状なんだ。1の構成失行は、形を組み立てられない、2の観念失行は、道具の使い方がわからない、4の顔面失行は、顔の動きの命令に従えない、5の観念運動失行は、指示された動作ができない症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-121","examYear":"2023","examRound":"35","questionNumber":121,"category":"総合問題","questionText":"次の事例を読んで，問題120から問題122までについて答えなさい。\n〔事例〕\nＤさん（38歳，男性，障害支援区分3）は，1年前に脳梗塞（cerebral infarction）を発症し左片麻痺となった。後遺症として左同名半盲，失行もみられる。現在は週3回，居宅介護を利用しながら妻と二人で生活している。ある日，上着の袖に頭を入れようとしているＤさんに介護福祉職が声をかけると，「どうすればよいかわからない」と答えた。普段は妻がＤさんの着替えを手伝っている。食事はスプーンを使用して自分で食べるが，左側にある食べ物を残すことがある。Ｄさんは，「左側が見づらい。動いているものにもすぐに反応ができない」と話した。最近は，日常生活の中で，少しずつできることが増えてきた。Ｄさんは，「人と交流する機会を増やしたい。また，簡単な生産活動ができるようなところに行きたい」と介護福祉職に相談した。\nＤさんへの食事の支援に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食事の量を少なくする。"},{"id":"2","text":"テーブルを高くする。"},{"id":"3","text":"スプーンを持つ手を介助する。"},{"id":"4","text":"バネつき箸に替える。"},{"id":"5","text":"食事を本人から見て右寄りに配膳する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｄさんは、左同名半盲で、左側が見づらく、左側の食べ物を残すことがあるんだね。だから、食事を、本人から見て右寄りに配膳すると、見えやすくて、食べ残しを防げるよ。1、2、3、4は、Ｄさんの困りごとを、解決するものではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-122","examYear":"2023","examRound":"35","questionNumber":122,"category":"総合問題","questionText":"次の事例を読んで，問題120から問題122までについて答えなさい。\n〔事例〕\nＤさん（38歳，男性，障害支援区分3）は，1年前に脳梗塞（cerebral infarction）を発症し左片麻痺となった。後遺症として左同名半盲，失行もみられる。現在は週3回，居宅介護を利用しながら妻と二人で生活している。ある日，上着の袖に頭を入れようとしているＤさんに介護福祉職が声をかけると，「どうすればよいかわからない」と答えた。普段は妻がＤさんの着替えを手伝っている。食事はスプーンを使用して自分で食べるが，左側にある食べ物を残すことがある。Ｄさんは，「左側が見づらい。動いているものにもすぐに反応ができない」と話した。最近は，日常生活の中で，少しずつできることが増えてきた。Ｄさんは，「人と交流する機会を増やしたい。また，簡単な生産活動ができるようなところに行きたい」と介護福祉職に相談した。\n介護福祉職は，Ｄさんに生産活動ができるサービスの利用を提案したいと考えている。\n次のうち，Ｄさんの発言内容に合う障害福祉サービスとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"就労継続支援Ａ型での活動"},{"id":"2","text":"地域活動支援センターの利用"},{"id":"3","text":"療養介護"},{"id":"4","text":"就労定着支援"},{"id":"5","text":"相談支援事業の利用"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｄさんは、人と交流する機会を増やして、簡単な生産活動ができるところに行きたいと話しているね。地域活動支援センターは、創作的活動や、生産活動の機会を提供して、交流を促進するので、ぴったりなんだ。1は、雇用契約を結ぶ、働く場。3は、医療と介護が必要な人向け。4は、就職後の定着の支援。5は、相談が中心で、活動の場ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-123","examYear":"2023","examRound":"35","questionNumber":123,"category":"総合問題","questionText":"次の事例を読んで，問題123から問題125までについて答えなさい。\n〔事例〕\nＥさん（35歳，男性）は，自閉症スペクトラム障害（autism spectrum disorder）があり，Ｖ障害者支援施設の生活介護と施設入所支援を利用している。Ｅさんは，毎日のスケジュールを決め，規則や時間を守ってプログラムに参加しているが，周りの人や物事に関心が向かず，予定外の行動や集団行動はとりづらい。コミュニケーションは，話すよりも絵や文字を示したほうが伝わりやすい。Ｅさんが利用するＶ障害者支援施設では，就労継続支援事業も行っている。災害が起こったときに様々な配慮が必要な利用者がいるため，施設として防災対策に力を入れている。また，通所している利用者も多いので，Ｖ障害者支援施設は市の福祉避難所として指定を受けている。\nＥさんのストレングス（strength）に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"行動力があり，すぐに動く。"},{"id":"2","text":"自分で決めたことを継続する。"},{"id":"3","text":"新しいことを思いつく。"},{"id":"4","text":"コミュニケーション力が高い。"},{"id":"5","text":"いろいろなことに興味がもてる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｅさんは、自分で決めたスケジュールを、規則や時間を守って、継続できる強みがあるんだ。1、3、5は、周りの人や物事に関心が向かず、予定外の行動はとりづらいという記述と、合わないよ。4は、話すより、絵や文字のほうが、伝わりやすいので、コミュニケーション力が高いとは、いえないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-124","examYear":"2023","examRound":"35","questionNumber":124,"category":"総合問題","questionText":"次の事例を読んで，問題123から問題125までについて答えなさい。\n〔事例〕\nＥさん（35歳，男性）は，自閉症スペクトラム障害（autism spectrum disorder）があり，Ｖ障害者支援施設の生活介護と施設入所支援を利用している。Ｅさんは，毎日のスケジュールを決め，規則や時間を守ってプログラムに参加しているが，周りの人や物事に関心が向かず，予定外の行動や集団行動はとりづらい。コミュニケーションは，話すよりも絵や文字を示したほうが伝わりやすい。Ｅさんが利用するＶ障害者支援施設では，就労継続支援事業も行っている。災害が起こったときに様々な配慮が必要な利用者がいるため，施設として防災対策に力を入れている。また，通所している利用者も多いので，Ｖ障害者支援施設は市の福祉避難所として指定を受けている。\nＶ障害者支援施設では定期的に災害に備えた避難訓練を行っている。\nＥさんの特性を考慮して実施する避難訓練に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"災害時に使用する意思伝達のイラストを用意する。"},{"id":"2","text":"避難生活を想定して，食事等の日課を集団で行えるようにする。"},{"id":"3","text":"予告せずに避難訓練を行う。"},{"id":"4","text":"Ｅさんの避難訓練は単独で行う。"},{"id":"5","text":"避難を援助する人によってＥさんへの対応を変える。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｅさんは、話すよりも、絵や文字を示したほうが、伝わりやすいんだね。だから、災害時に使う、意思伝達のイラストを用意しておくと、避難の場面でも、伝わりやすくなるよ。2は、集団行動が苦手。3は、予告なしは、混乱する。4は、単独ではなく、みんなと参加する。5は、対応を変えると、混乱するので、統一するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2023-35-125","examYear":"2023","examRound":"35","questionNumber":125,"category":"総合問題","questionText":"次の事例を読んで，問題123から問題125までについて答えなさい。\n〔事例〕\nＥさん（35歳，男性）は，自閉症スペクトラム障害（autism spectrum disorder）があり，Ｖ障害者支援施設の生活介護と施設入所支援を利用している。Ｅさんは，毎日のスケジュールを決め，規則や時間を守ってプログラムに参加しているが，周りの人や物事に関心が向かず，予定外の行動や集団行動はとりづらい。コミュニケーションは，話すよりも絵や文字を示したほうが伝わりやすい。Ｅさんが利用するＶ障害者支援施設では，就労継続支援事業も行っている。災害が起こったときに様々な配慮が必要な利用者がいるため，施設として防災対策に力を入れている。また，通所している利用者も多いので，Ｖ障害者支援施設は市の福祉避難所として指定を受けている。\nＶ障害者支援施設が，災害発生に備えて取り組む活動として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"事前に受け入れ対象者を確認しておく。"},{"id":"2","text":"災害派遣医療チーム（ＤＭＡＴ）と支援人員確保契約を結ぶ。"},{"id":"3","text":"職員の役割分担は，状況に応じてその場で決める。"},{"id":"4","text":"要配慮者のサービス等利用計画を作成する。"},{"id":"5","text":"要配慮者に自分で避難するように促す。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！福祉避難所に指定されている施設は、災害が起こる前に、受け入れ対象者を、確認しておくことが、大切な備えなんだ。2は、ＤＭＡＴは、災害急性期の医療チーム。3は、職員の役割分担は、あらかじめ決めておく。4は、サービス等利用計画は、相談支援専門員が作成する。5は、要配慮者は、自分で避難するのが難しいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第35回（令和4年度）介護福祉士国家試験; 問題: https://drive.google.com/file/d/1UPmhp_s2TKj8kZAWzg-ULmjrK0EhJhPL/view; 正答: https://crie-hukushi.com/info/11780/","keywords":[],"needsLegalReview":true},{"id":"2022-34-001","examYear":"2022","examRound":"34","questionNumber":1,"category":"人間の尊厳と自立","questionText":"著書『ケアの本質－生きることの意味』の中で，「一人の人格をケアするとは， 最も深い意味で，その人が 成長 すること，自己実現することをたすけることである」と述べた人物として，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"神谷美恵子"},{"id":"2","text":"糸賀一雄"},{"id":"3","text":"フローレンス・ナイチンゲール（Nightingale, F.）"},{"id":"4","text":"ミルトン・メイヤロフ（Mayeroff, M.）"},{"id":"5","text":"ベンクト・ニィリエ（Nirje, B.）"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！『ケアの本質』を書いたのは、アメリカの哲学者ミルトン・メイヤロフなんだ。ケアは、その人が成長し、自己実現することを助けることだと述べているよ。1の神谷美恵子は『生きがいについて』、2の糸賀一雄は「この子らを世の光に」、3のナイチンゲールは近代看護の創始者、5のニィリエはノーマライゼーションの原理を示した人物だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-002","examYear":"2022","examRound":"34","questionNumber":2,"category":"人間の尊厳と自立","questionText":"Ａさん（80 歳，女性，要介護 1）は， 筋力や理解力の低下がみられ，訪問介護（ホームヘルプサービス）を利用している。訪問介護員（ホームヘルパー）がいない時間帯は，同居している長男（53 歳，無職）に頼って生活をしている。 長男 はＡさんの年金で生計を立てていて，ほとんど 外出 しないで家にいる。ある時，Ａさんは訪問介護員（ホームヘルパー）に，「 長男は暴力 がひどくてね。この 間も殴られて，とても怖かった。 長男 には言わないでね。あとで何かわからないから」と話した。訪問介護員（ホームヘルパー）は，Ａさんのからだに複数のあざがあることを確認した。訪問介護員（ホームヘルパー）の対応に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"長男の虐待を疑い，上司に報告し，市町村に通報する。"},{"id":"2","text":"長男 の仕事が見つかるようにハローワークを 紹介 する。"},{"id":"3","text":"Ａさんの気持ちを大切にして何もしない。"},{"id":"4","text":"すぐに 長男 を別室に呼び，事実を確認する。"},{"id":"5","text":"長男の暴力 に気づいたかを近所の人に確認する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ａさんのからだには、複数のあざがあって、長男の暴力を訴えているよね。虐待が疑われるので、上司に報告して、市町村に通報するのが適切なんだ。2は、根本の解決にならない。3は、放置してしまう。4は、Ａさんが危険になることがある。5は、近所の人への確認で、個人情報が広がるおそれがあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-003","examYear":"2022","examRound":"34","questionNumber":3,"category":"人間関係とコミュニケーション","questionText":"介護福祉職はＢさんから，「認知症（dementia）の母の介護がなぜかうまくいかない。深夜に徘徊するので，心身共に疲れてきた」と相談された。介護福祉職は，「落ち込んでいてはダメですよ。元気を出して頑張ってください」とＢさんに言った。後日，介護福祉職はＢさんに対する自身の発言を振り返り，不適切だったと反省した。介護福祉職はＢさんに対してどのような返答をすればよかったのか， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"「お母さんに施設へ 入所 してもらうことを検討してはどうですか」"},{"id":"2","text":"「 私も疲れているので，よくわかります」"},{"id":"3","text":"「認知症（dementia）の方を介護しているご家族は，皆さん疲れていますよ」"},{"id":"4","text":"「近所の人に助けてもらえるように， 私から言っておきます」"},{"id":"5","text":"「お母さんのために頑張ってきたんですね」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｂさんは、認知症の母の介護で、心身ともに疲れているんだね。「お母さんのために頑張ってきたんですね」と、これまでの努力をねぎらって、気持ちを受け止めるのがよいよ。1は、施設入所を急ぐ提案。2は、自分の話にすり替えている。3は、一般論で、Ｂさんの気持ちに向き合っていない。4は、本人の同意なく動くことになるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-004","examYear":"2022","examRound":"34","questionNumber":4,"category":"人間関係とコミュニケーション","questionText":"利用者とのコミュニケーション場面で，介護福祉職が 行う自己開示の目的として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"ジョハリの窓（Johari Window）の「開放された部分（open area）」を狭に 行う。"},{"id":"2","text":"利用者との信頼関係を形成するために 行う。"},{"id":"3","text":"利用者が自分自身の 情報 を開示するために 行う。"},{"id":"4","text":"利用者との信頼関係を評価するために 行う。"},{"id":"5","text":"自己を深く分析し，客観的に理解するために 行う。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！自己開示は、自分の考えや経験を、相手に話すことで、信頼関係を築くために行うんだ。1は、開放された部分（自分も他人も知っている部分）を広げるための行動だから、「狭める」は誤り。3は、利用者に自己開示を促すのが目的ではない。4は、評価が目的ではない。5は、自己覚知の説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-005","examYear":"2022","examRound":"34","questionNumber":5,"category":"社会の理解","questionText":"2016 年（平成 28 年）に閣議決定された，「ニッポン一億総活躍プラン」にある「地域共生社会の実現」に関する記述として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"日本型福祉社会の創造"},{"id":"2","text":"我が事・丸ごとの地域づくり"},{"id":"3","text":"健康で文化的な最低限度の生活の保障"},{"id":"4","text":"社会保障と税の一体改革"},{"id":"5","text":"皆保険・皆年金体制の実現"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！2016年の「ニッポン一億総活躍プラン」では、地域共生社会の実現のために、「我が事・丸ごと」の地域づくりが示されたんだ。住民が、自分の課題として捉えて、支え合う地域をめざす考え方だよ。1は日本型福祉社会、3は生存権、4は社会保障・税一体改革、5は1961年の皆保険・皆年金体制で、別の政策だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-006","examYear":"2022","examRound":"34","questionNumber":6,"category":"社会の理解","questionText":"2019 年（平成 31 年，令和元年）の日本の世帯に関する次の記述のうち，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"平均世帯人員は， 3 人を超えている。"},{"id":"2","text":"世帯数で 最も多いのは， 2人世帯である。"},{"id":"3","text":"単独世帯で 最も多いのは，高齢者の単独世帯である。"},{"id":"4","text":"母子世帯数と父子世帯数を合算すると，高齢者世帯数を超える。"},{"id":"5","text":"全国の世帯総数は， 7 千万を超えている。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！2019年の国民生活基礎調査では、世帯人員別にみると、2人世帯がいちばん多いんだ。1は、平均世帯人員は2.39人で、3人を超えていない。3は、単独世帯の内訳の説明としては、適切ではない。4は、母子世帯と父子世帯の合計は、高齢者世帯より、はるかに少ない。5は、世帯総数は約5,178万で、7千万は超えていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-007","examYear":"2022","examRound":"34","questionNumber":7,"category":"社会の理解","questionText":"2015 年（平成 27 年）以降の日本の社会福祉を取り巻く 環境 に関する次記述のうち，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"人口は，増加傾向にある。"},{"id":"2","text":"共働 き世帯数は，減少傾向にある。"},{"id":"3","text":"非正規雇用労働者数は，減少傾向にある。"},{"id":"4","text":"高齢世代を支える現役世代（生産年齢人口）は，減少傾向にある。"},{"id":"5","text":"日本の国民負担率は，ＯＥＣＤ加盟国の中では上位にある。（注） ＯＥＣＤとは，経済協力開発機構（Organisation for Economic Co-operationand Development）のことで，2020 年（令和2年）現在 38 か国が加盟している。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！2015年以降の日本では、少子高齢化が進んで、高齢世代を支える現役世代（生産年齢人口）は、減少傾向にあるんだ。1は、人口は減少している。2は、共働き世帯は増えている。3は、非正規雇用労働者数は、増加傾向にある。5は、国民負担率は、OECD加盟国の中では、上位ではなく、中位くらいだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-008","examYear":"2022","examRound":"34","questionNumber":8,"category":"社会の理解","questionText":"次のうち，2020 年（令和2年）の社会福祉法等の改正に関する記述として，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"市町村による地域福祉計画の策定"},{"id":"2","text":"入所施設の重点的な拡充"},{"id":"3","text":"医療・介護のデータ基盤の整備の推進"},{"id":"4","text":"市町村直営の介護サービス事業の整備拡充"},{"id":"5","text":"ロボット等の機械の活用から人によるケアへの転換（注） 2020 年（令和2年）の社会福祉法等の改正とは，「地域共生社会の実現のための社会福祉法等の一部を改正する法律（令和2年法律第 52 号）」をいう。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！2020年の社会福祉法等の改正では、医療・介護のデータ基盤の整備の推進が盛り込まれたんだ。1は、地域福祉計画の策定は、以前からある。2は、入所施設より、地域を重視する流れ。4は、市町村の直営サービスの拡充は、改正の内容ではない。5は、ロボットなどの活用は、むしろ推進される方向だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-009","examYear":"2022","examRound":"34","questionNumber":9,"category":"社会の理解","questionText":"Ｃさん（78 歳，男性，要支援 1）は，公的年金（月額 19 万円）で公営住宅の3 階で一人暮らしをしている。妻と死別後も通所型サービスを利用し，自炊を楽しみながら生活している。最近，膝の具合がよくないこともあり，階段の上り下りが負担になってきた。そこで，転居について，通所型サービスのＤ介護福祉士に相談をした。次のうち，Ｄ介護福祉士がＣさんに紹介する住まいの場として，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"認知症対応型共同生活介護（認知症高齢者グループホーム）"},{"id":"2","text":"介護付有料老人ホーム"},{"id":"3","text":"軽費老人ホームＡ型"},{"id":"4","text":"サービス付き高齢者向け 住宅"},{"id":"5","text":"養護老人ホーム"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｃさんは、要支援1で、公営住宅の階段の上り下りが負担になり、自炊を楽しみながら、一人暮らしを続けたいんだね。バリアフリーで、安否確認や生活相談のサービスがある、サービス付き高齢者向け住宅が、ぴったりだよ。1と2は、認知症や介護が必要な人向けで、Ｃさんの状態には、介護度が合わない。3の軽費老人ホームＡ型は、食事の提供があり、自炊を楽しみたい希望と合わない。5は、環境的、経済的に困窮している人向けだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-010","examYear":"2022","examRound":"34","questionNumber":10,"category":"社会の理解","questionText":"介護保険制度の保険給付の財源構成として，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"保険料"},{"id":"2","text":"公費"},{"id":"3","text":"公費，保険料，現役世代からの支援金"},{"id":"4","text":"公費，第一号保険料"},{"id":"5","text":"公費，第一号保険料，第二号保険料"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護保険の保険給付の財源は、公費（税金）と、第1号被保険者の保険料、第2号被保険者の保険料でまかなわれているんだ。公費が半分、保険料が半分だよ。ほかの選択肢は、財源の構成としては、不十分なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-011","examYear":"2022","examRound":"34","questionNumber":11,"category":"社会の理解","questionText":"「2016 年（平成 28 年）生活のしづらさなどに関する調査（全国在宅障害児・者等実態調査）」（厚生労働省）における身体障害，知的障害，精神障害の近年の状況 に関する次の記述のうち，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"最も人数の多い 障害 は，知的障害である。"},{"id":"2","text":"施設入所者の割合が 最も高い 障害 は，身体障害である。"},{"id":"3","text":"在宅の身体障害者のうち，65 歳以上の割合は 7 割を超えている。"},{"id":"4","text":"在宅の知的障害者の数は，減少傾向にある。"},{"id":"5","text":"精神障害者の 8 割は，精神障害者保健福祉手帳を所持している。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！2016年の調査では、在宅の身体障害者のうち、65歳以上の割合は、7割を超えているんだ。1は、最も人数が多いのは、身体障害者。2は、施設入所者の割合が高いのは、知的障害者。4は、在宅の知的障害者の数は、増加傾向。5は、精神障害者保健福祉手帳の所持者は、そこまで多くないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-012","examYear":"2022","examRound":"34","questionNumber":12,"category":"社会の理解","questionText":"Ｅさん（30 歳，女性，知的障害，障害支援区分 2）は，現在， 日中 は特例子会社で 働き，共同生活援助（グループホーム）で生活している。今後，一人暮らしをしたいと思っているが，初めてなので不安もある。次のうち，Ｅさんが安心して一人暮らしをするために利用するサービスとして，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"行動援護"},{"id":"2","text":"同行援護"},{"id":"3","text":"自立訓練（機能訓練）"},{"id":"4","text":"自立生活援助"},{"id":"5","text":"就労継続支援"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！自立生活援助は、グループホームなどから、一人暮らしに移行した人が、安心して暮らせるように、定期的な訪問や、相談、助言を行うサービスなんだ。1の行動援護は、外出時の支援。2の同行援護は、視覚障害のある人の外出支援。3は、身体機能の訓練。5は、働く場の提供で、一人暮らしの不安には応えられないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-013","examYear":"2022","examRound":"34","questionNumber":13,"category":"社会の理解","questionText":"重度訪問介護に関する次の記述のうち，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"外出時における移動中の介護も含まれる。"},{"id":"2","text":"知的障害者は 対象 にならない。"},{"id":"3","text":"利用者が医療機関に 入院 した場合，医療機関で支援することはできない。"},{"id":"4","text":"訪問看護の利用者は 対象 にならない。"},{"id":"5","text":"障害 が視覚障害のみの場合でも利用できる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！重度訪問介護は、重度の障害のある人に、自宅での介護のほか、外出時の移動中の介護も、あわせて行うんだ。2は、知的障害や精神障害で、常に介護が必要な人も対象。3は、入院中も、一部の重度訪問介護が、利用できる。4は、訪問看護と併用できる。5は、視覚障害のみでは、対象にならないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-014","examYear":"2022","examRound":"34","questionNumber":14,"category":"社会の理解","questionText":"「成年後見関係事件の概況（令和2年1月～12月）」（最高裁判所事務総局家庭局）における，成年後見人等として活動している人が最も多い職種として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"行政書士"},{"id":"2","text":"司法書士"},{"id":"3","text":"社会保険労務士"},{"id":"4","text":"精神保健福祉士"},{"id":"5","text":"税理士"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！令和2年の成年後見関係事件の概況では、成年後見人等として活動している人は、司法書士が最も多く、次いで弁護士、社会福祉士の順なんだ。行政書士、社会保険労務士、精神保健福祉士、税理士は、ほかの選択肢だけど、司法書士より少ないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-015","examYear":"2022","examRound":"34","questionNumber":15,"category":"社会の理解","questionText":"保健所に関する次の記述のうち，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"保健所の設置は，医療法によって定められている。"},{"id":"2","text":"保健所は，全ての市町村に設置が義務づけられている。"},{"id":"3","text":"保健所は，医療法人によって運営されている。"},{"id":"4","text":"保健所の 所長 は，保健師でなければならない。"},{"id":"5","text":"保健所は，結核（tuberculosis）などの感染症の予防や対策を 行う。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！保健所は、結核などの感染症の予防や、対策を行う、地域の保健の拠点なんだ。1は、保健所の設置は、地域保健法で定められている。2は、設置主体は、都道府県、政令指定都市、中核市などで、全市町村ではない。3は、運営主体は、地方公共団体。4は、所長は、医師であることが原則だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-016","examYear":"2022","examRound":"34","questionNumber":16,"category":"社会の理解","questionText":"生活保護制度に関する次の記述のうち， 最も適切なものを 1 つ選い。","choices":[{"id":"1","text":"生活保護の給付方法には，金銭給付と現物給付がある。"},{"id":"2","text":"生活保護の申請は，民生委員が 行う。"},{"id":"3","text":"生活保護法は，日本国憲法第 13 条にある幸福追求権の実現を目的としている。"},{"id":"4","text":"生活保護を担当する 職員 は，社会福祉士の資格が必要である。"},{"id":"5","text":"生活保護の費用は，国が全額を負担する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！生活保護の給付方法には、金銭給付と、現物給付があるんだ。2は、申請は、本人や家族などが行う。3は、生活保護法は、日本国憲法第25条の、生存権の実現を目的としている。4は、担当職員は、社会福祉主事の任用資格が必要。5は、費用は、国が4分の3を負担するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-017","examYear":"2022","examRound":"34","questionNumber":17,"category":"介護の基本","questionText":"Ｆさん（66 歳，戸籍上の性別は男性，要介護 3）は，性同一性障害であることを理由に施設利用を避けてきた。最近，数年前の脳卒中（stroke）の後遺症がひどくなり，一人暮らしが 難しくなってきた。Ｆさんは，担当の訪問介護員（ホームヘルパー）に施設入所について，「性同一性障害でも施設に受け入でしょうか」と相談した。訪問介護員（ホームヘルパー）の応答として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"「居室の 表札 は，通称名ではなく戸籍上の名前になります」"},{"id":"2","text":"「多床室になる場合がありますよ」"},{"id":"3","text":"「施設での生活で心配なことは何ですか」"},{"id":"4","text":"「トイレや 入浴 については問題がありますね」"},{"id":"5","text":"「同性による介護が原則です」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｆさんは、性同一性障害があって、施設に受け入れてもらえるかを、不安に思っているんだね。「施設での生活で心配なことは何ですか」と、不安な気持ちを聞いて、受け止めるのが、最もよい応答だよ。1、2、4、5は、決めつけたり、不安をあおったりしてしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-018","examYear":"2022","examRound":"34","questionNumber":18,"category":"介護の基本","questionText":"利用者主体の 考えに基づいた介護福祉職の対応に関する次の記述のうち，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"1人で衣服を選ぶことが 難しい利用者には，毎日の衣服を自分で選声かけをする。"},{"id":"2","text":"食べこぼしが多い利用者には，こぼさないように全介助する。"},{"id":"3","text":"認知症（dementia）の利用者には，排泄の感覚があっても，定時に排泄の介護を行う。"},{"id":"4","text":"転倒しやすい利用者には，事故防止のため立ち上がらないように声をかける。"},{"id":"5","text":"入浴が自立している利用者も，危険を避けるため個別浴ではなく集団での 入浴とする。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！利用者主体の介護では、利用者ができることを、生かして支援するんだ。衣服を選ぶのが難しい人にも、声かけをして、自分で選んでもらうのがよいよ。2は、全介助にすると、できることを奪う。3は、排泄の感覚があるなら、その意思を尊重する。4は、立ち上がらないように制限する。5は、集団浴を強制する対応だね。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-019","examYear":"2022","examRound":"34","questionNumber":19,"category":"介護の基本","questionText":"利用者の自立支援に関する次の記述のうち， 最も適切なものを 1 つ選なさい。","choices":[{"id":"1","text":"利用者の最期の迎え方を決めるのは，家族である。"},{"id":"2","text":"利用者が話しやすいように， 愛称 で呼ぶ。"},{"id":"3","text":"利用者が自分でできないことは，できるまで見守る。"},{"id":"4","text":"利用者の生活のスケジュールを決めるのは，介護福祉職である。"},{"id":"5","text":"利用者の意見や希望を取り入れて介護を 提供 する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！自立支援では、利用者の意見や希望を取り入れて、介護を提供することが大切なんだ。1は、最期の迎え方は、本人の意思が大切。2は、愛称は、本人の同意がないと、失礼になる。3は、できないことは、必要な支援をする。4は、生活のスケジュールは、本人の希望を大切にするよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-020","examYear":"2022","examRound":"34","questionNumber":20,"category":"介護の基本","questionText":"Ｇさん（70 歳，男性，要介護 2）は，パーキンソン病（Parkinson disease）と診断されていて，外出するときは車いすを使用している。歩行が不安定なため，週2回通所リハビリテーションを利用している。Ｇさんは，1年前に妻が亡くなり，息子と二人暮らしである。Ｇさんは社交的な性格で地域住民との交流を望んでいるが，自宅周辺は坂道や段差が多くて移動が難しく，交流ができていない。Ｇさんの状況をＩＣＦ（International Classification of Functioning Disability and Health：国際生活機能分類）で考えた場合，参加制約の原因になっている環境因子として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"パーキンソン 病（Parkinson disease）"},{"id":"2","text":"不安定な歩行"},{"id":"3","text":"息子と二人暮らし"},{"id":"4","text":"自宅周辺の坂道や段差"},{"id":"5","text":"車いす"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ＩＣＦの環境因子は、物的環境、人的環境、社会的環境などのことなんだ。Ｇさんが、地域住民との交流ができないのは、自宅周辺の坂道や段差という、物的環境が、参加を妨げているからだよ。1は健康状態、2は心身機能、3は人的環境の一部だけど、直接の原因ではなく、5は、車いすは、福祉用具として、参加を助けるものだね。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-021","examYear":"2022","examRound":"34","questionNumber":21,"category":"介護の基本","questionText":"Ｈさん（75 歳，女性，要介護 2）は，孫（17 歳，男性，高校生）と自宅で二人暮らしをしている。Ｈさんは関節疾患（joint disease）があり，通所リハビリテーションの利用を開始した。介護福祉職が送迎時に孫から，「祖母は，日常生活が 難しくなり，自分が食事を作るなどの機会が増え，家事や 勉強 への不安がある」と相談された。介護福祉職の孫への対応として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"「今までお世話になったのですから，今度はＨさんを支えてください」"},{"id":"2","text":"「家事が大変なら，Ｈさんに介護老人福祉施設の 入所 を勧めましょう」"},{"id":"3","text":"「高校の先生や介護支援専門員（ケアマネジャー）に相談していきましょう」"},{"id":"4","text":"「家でもリハビリテーションを一緒にしてください」"},{"id":"5","text":"「近所の人に家事を手伝ってもらってください」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｈさんの孫は、家事や勉強への不安を抱えているんだね。高校の先生や、介護支援専門員に相談していくことを勧めると、専門職を含めた、周囲の支援につなげられるよ。1は、お世話になったからと、孫に負担を負わせる。2は、決めつけている。4は、負担が増える。5は、近所の人に頼むのは、孫の不安に応えないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-022","examYear":"2022","examRound":"34","questionNumber":22,"category":"介護の基本","questionText":"介護保険制度のサービス担当者会議に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"会議の招集は介護支援専門員（ケアマネジャー）の職務である。"},{"id":"2","text":"利用者の自宅で開催することが義務づけられている。"},{"id":"3","text":"月1回以上の頻度で開催することが義務づけられている。"},{"id":"4","text":"サービス提供者の実践力の向上 を目的とする。"},{"id":"5","text":"利用者の氏名は匿名化される。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！サービス担当者会議の招集は、介護支援専門員（ケアマネジャー）の職務なんだ。2は、会議は、利用者の自宅で行うと決まっていない。3は、月1回以上の開催が、義務づけられているわけではない。4は、目的は、ケアプランの内容を検討して、サービスの調整を行うこと。5は、利用者の氏名は、匿名化しないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-023","examYear":"2022","examRound":"34","questionNumber":23,"category":"介護の基本","questionText":"社会資源に関する次の記述のうち，フォーマルサービスに該当するものとして，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"一人暮らしの高齢者への見守りを 行う地域住民"},{"id":"2","text":"買物を手伝ってくれる家族"},{"id":"3","text":"ゴミ拾いのボランティア活動を 行う学生サークル"},{"id":"4","text":"友人や知人と 行う相互扶助の活動"},{"id":"5","text":"介護の相談を受ける地域包括支援センター"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！フォーマルサービスは、法律や制度にもとづいて、公的な機関などが行うサービスなんだ。地域包括支援センターは、その代表例だよ。1、2、3、4は、地域住民、家族、学生サークル、友人や知人による、制度に基づかない、インフォーマルなサポートだね。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-024","examYear":"2022","examRound":"34","questionNumber":24,"category":"介護の基本","questionText":"介護福祉士の職業倫理に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"介護が必要な人を 対象 にしているため，地域住民との連携は不要である。"},{"id":"2","text":"全ての人々が質の高い介護を受けることができるように，後継者を育成する。"},{"id":"3","text":"利用者のためによいと 考えた介護を画一的に実践する。"},{"id":"4","text":"利用者に関する 情報 は，業務以外では 公表 してよい。"},{"id":"5","text":"利用者の価値観よりも，介護福祉士の価値観を優先する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護福祉士の職業倫理では、すべての人が質の高い介護を受けられるように、後継者を育成することが、求められているんだ。1は、地域住民との連携も、大切。3は、画一的ではなく、個別的な介護を行う。4は、利用者の情報は、業務以外で公表してはダメ。5は、介護福祉士の価値観よりも、利用者の価値観を尊重するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-025","examYear":"2022","examRound":"34","questionNumber":25,"category":"介護の基本","questionText":"施設における利用者の個人情報の安全管理対策として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"介護福祉職が個人所有するスマートフォンの居室への持込みは制限しない。"},{"id":"2","text":"不要な個人情報を破棄する場合は，万が一に備えて復元できるようにしておく。"},{"id":"3","text":"利用者からの照会に速やかに応じるために，整理用のインデックス（index）は使用しない。"},{"id":"4","text":"個人情報に関する苦情対応体制について，施設の掲示板等で利用者に周知徹底する。"},{"id":"5","text":"個人情報の盗難を防ぐために， 職員の休憩室に監視カメラを設置する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！個人情報の安全管理では、苦情の対応体制を、掲示板などで、利用者に周知することが大切なんだ。1は、スマートフォンの持ち込みは、制限が必要。2は、破棄するときは、復元できないようにする。3は、インデックスは、整理のために使ってもよい。5は、休憩室に監視カメラをつけるのは、職員のプライバシーに配慮が必要だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-026","examYear":"2022","examRound":"34","questionNumber":26,"category":"介護の基本","questionText":"訪問介護員（ホームヘルパー）が，利用者や家族からハラスメント（harassment）を受けたときの対応に関する次の記述のうち， 最も適切なものを 1つ選びなさい。","choices":[{"id":"1","text":"利用者に後ろから 急に抱きつかれたが，黙って耐えた。"},{"id":"2","text":"利用者から 暴力 を受けたので，「やめてください」と伝え，上司に相談した。"},{"id":"3","text":"利用者が繰り返す性的な 話を，苦痛だが笑顔で聞いた。"},{"id":"4","text":"家族から暴言を受けたが，担当なのでそのまま利用者宅に通った。"},{"id":"5","text":"家族からサービス外のことを頼まれて， 断ったら怒鳴られたので実施した。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！利用者から暴力を受けたときは、「やめてください」と、はっきり伝えて、上司に相談するのが、適切な対応なんだ。1、3、4、5は、ハラスメントを我慢したり、受け入れたりしていて、自分を守る行動になっていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-027","examYear":"2022","examRound":"34","questionNumber":27,"category":"コミュニケーション技術","questionText":"介護福祉職が利用者とコミュニケーションをとるときの基本的な態度として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"上半身を少し利用者のほうへ 傾けた姿勢で 話を聞く。"},{"id":"2","text":"利用者の 正面 に立って話し続ける。"},{"id":"3","text":"腕を組んで 話を聞く。"},{"id":"4","text":"利用者の目を見つめ続ける。"},{"id":"5","text":"緊張感が伝わるように，背筋を伸ばす。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！コミュニケーションでは、上半身を少し利用者のほうへ傾けて、話を聞くと、関心があることが伝わるんだ。2は、正面は、圧迫感がある。3は、腕を組むと、拒否的に見える。4は、見つめ続けると、緊張させる。5は、緊張感が伝わらないよう、リラックスした姿勢がよいよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-028","examYear":"2022","examRound":"34","questionNumber":28,"category":"コミュニケーション技術","questionText":"介護 福 祉 職 に よ る ア サ ー テ ィ ブ・ コ ミ ュ ニ ケ ー シ ョ ン（assertivecommunication）として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"利用者の 要求 は，何も言わずにそのまま受け入れる。"},{"id":"2","text":"利用者から苦情を言われたときは，沈黙して我慢する。"},{"id":"3","text":"利用者を説得して介護福祉職の都合に合わせてもらう。"},{"id":"4","text":"介護福祉職の提案に 従うことが利用者の利益になると伝える。"},{"id":"5","text":"利用者の思いを 尊重 しながら，介護福祉職の意見を 率直 に伝える。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！アサーティブ・コミュニケーションは、相手の思いを尊重しながら、自分の意見も、率直に伝える方法なんだ。1、2は、自分を抑える、非主張的な方法。3、4は、相手に押しつける、攻撃的な方法だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-029","examYear":"2022","examRound":"34","questionNumber":29,"category":"コミュニケーション技術","questionText":"次の事例を読んで，問題 29，問題 30 について答えなさい。〔事例〕Ｊさん（75 歳，男性）は先天性の全盲である。これまで自宅で自立した生活をしてきたが，最近，心身機能の 衰えを感じて，有料老人ホームに 入居 した。施設での生活にまだ慣れていないので，移動は介護福祉職に誘導してもらっている。ある日，介護福祉職がＪさんを自室まで誘導したときに，「いつも手伝ってもらってすみません。なかなか場所を覚えられなくて。 私か」と話してきた。\nＪさんの発言への介護福祉職の共感的理解を示す対応として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"Ｊさんの発言にうなずく。"},{"id":"2","text":"Ｊさんの発言のあと沈黙する。"},{"id":"3","text":"Ｊさんの 話の内容を 短くまとめて伝える。"},{"id":"4","text":"Ｊさんの立場に立って 感情 を推し測り，言葉で 表現 して伝える。"},{"id":"5","text":"Ｊさんの気持ちが前向きになるように，励ましの言葉を伝える。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！共感的理解を示すには、相手の立場に立って、感情を推し測り、それを言葉にして伝えることが大切なんだ。1のうなずきや、2の沈黙は、傾聴の姿勢。3は、要約。5は、励ましで、Ｊさんの気持ちを、受け止めていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-030","examYear":"2022","examRound":"34","questionNumber":30,"category":"コミュニケーション技術","questionText":"次の事例を読んで，問題 29，問題 30 について答えなさい。〔事例〕Ｊさん（75 歳，男性）は先天性の全盲である。これまで自宅で自立した生活をしてきたが，最近，心身機能の 衰えを感じて，有料老人ホームに 入居 した。施設での生活にまだ慣れていないので，移動は介護福祉職に誘導してもらっている。ある日，介護福祉職がＪさんを自室まで誘導したときに，「いつも手伝ってもらってすみません。なかなか場所を覚えられなくて。 私か」と話してきた。\nＪさんの不安な気持ちを軽くするための介護福祉職の対応として， 最適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"いきなり声をかけると 驚くので，肩にふれてから挨拶をする。"},{"id":"2","text":"誘導時の声かけは歩行の 妨げになるので，最小限にする。"},{"id":"3","text":"角を曲がるときには，「こちらに」と方向を伝える。"},{"id":"4","text":"トイレや 食堂 などを，一緒に歩きながら確認する。"},{"id":"5","text":"食堂 の座席は，Ｊさんの好きなところに座るように伝える。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｊさんの不安を軽くするには、トイレや食堂などを、一緒に歩きながら確認して、場所を覚えやすくすることが、効果的なんだ。1、3は、誘導時の基本的な配慮だけど、場所を覚えることにつながらない。2は、声かけを減らすと、不安が増える。5は、席を自由にすると、場所がわかりにくくなるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-031","examYear":"2022","examRound":"34","questionNumber":31,"category":"コミュニケーション技術","questionText":"次の事例を読んで，問題 31，問題 32 について答えなさい。〔事例〕Ｋさん（83 歳，女性，要介護 3）は，10 年前の脳出血（cerebral hemorrhage）による後遺症で高次脳機能障害（higher brain dysfunction）がある。 感情 のコントロールが 難しく，興奮すると大声をあげて怒りだす。現在は，訪問介護（ホームヘルプサービス）を利用しながら，自宅で 長男（60 歳）と二人暮らしをしている。長男 は，会社を 3 年前に早期退職し，Ｋさんの介護に専念してきた。顔色が悪く，介護による疲労を 訴えているが，「介護を続けて，母を自宅で看取りたい」と強く希望している。別居している長女 は， 長男の様子を心配して，「母親の施設入所の手続きを進めたい」という意向を示している。\n訪問介護員（ホームヘルパー）が，興奮しているときのＫさんとコミュニケーションをとるための方法として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"興奮している理由を詳しく聞く。"},{"id":"2","text":"興奮することはよくないと説明する。"},{"id":"3","text":"冷静になるように説得する。"},{"id":"4","text":"事前に作成しておいた日課表に沿って活動してもらう。"},{"id":"5","text":"場所を移動して話題を変える。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！高次脳機能障害があるＫさんが、興奮したときは、場所を移動して、話題を変えると、気持ちが落ち着きやすいんだ。1は、理由を聞くと、さらに興奮することがある。2、3は、説得や指摘は、逆効果。4は、日課表に沿うだけでは、興奮している状態に対応できないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-032","examYear":"2022","examRound":"34","questionNumber":32,"category":"コミュニケーション技術","questionText":"次の事例を読んで，問題 31，問題 32 について答えなさい。〔事例〕Ｋさん（83 歳，女性，要介護 3）は，10 年前の脳出血（cerebral hemorrhage）による後遺症で高次脳機能障害（higher brain dysfunction）がある。 感情 のコントロールが 難しく，興奮すると大声をあげて怒りだす。現在は，訪問介護（ホームヘルプサービス）を利用しながら，自宅で 長男（60 歳）と二人暮らしをしている。長男 は，会社を 3 年前に早期退職し，Ｋさんの介護に専念してきた。顔色が悪く，介護による疲労を 訴えているが，「介護を続けて，母を自宅で看取りたい」と強く希望している。別居している長女 は， 長男の様子を心配して，「母親の施設入所の手続きを進めたい」という意向を示している。\n長男 に対する訪問介護員（ホームヘルパー）の対応として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"長男自身の意向を変える必要はないと励ます。"},{"id":"2","text":"Ｋさん本人の意向が不明なため， 長男 の希望は通らないと伝える。"},{"id":"3","text":"これまでの介護をねぎらい，自宅での看取りを希望する理由を尋ねる。"},{"id":"4","text":"自宅での生活を継続するのは限界だと説明する。"},{"id":"5","text":"長女 の言うように，施設入所の手続きを進めることが正しいと伝える。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！長男は、疲労をためながら、母を自宅で看取りたいと強く希望しているんだね。これまでの介護をねぎらって、自宅で看取りたい理由を尋ねると、思いを理解できるよ。1は、疲労を無視している。2、4、5は、長男の希望を、否定したり、決めつけたりしているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-033","examYear":"2022","examRound":"34","questionNumber":33,"category":"コミュニケーション技術","questionText":"利用者の家族から苦情があったときの上司への報告に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"苦情の内容について，時間をかけて詳しく口頭で報告した。"},{"id":"2","text":"すぐに口頭で概要を報告してから，文書を作成して報告した。"},{"id":"3","text":"結論を伝えることを重視して，「いつもの苦情です」とすぐに報告した。"},{"id":"4","text":"上司が 忙しそうだったので， 同僚 に伝えた。"},{"id":"5","text":"自分の気持ちが落ち着いてから，翌日に報告した。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！苦情があったときは、まず、口頭で概要をすぐに報告して、そのあと、文書で詳しく報告するのが、適切なんだ。1は、時間がかかりすぎる。3は、情報が不足する。4は、上司に直接報告する。5は、報告が遅れるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-034","examYear":"2022","examRound":"34","questionNumber":34,"category":"コミュニケーション技術","questionText":"利用者の自宅で 行うケアカンファレンス（care conference）に関する次記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"検討する内容は，インフォーマルなサポートに限定する。"},{"id":"2","text":"介護福祉職の 行った介護に対する批判を 中心 に進める。"},{"id":"3","text":"利用者本人の参加を 促し，利用者の意向をケア方針に反映させる。"},{"id":"4","text":"意見が分かれたときは，多数決で決定する。"},{"id":"5","text":"対立を避けるために，他の専門職の意見には反論しない。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ケアカンファレンスでは、利用者本人の参加を促して、利用者の意向をケア方針に反映させることが大切なんだ。1は、検討内容を、インフォーマルなサポートに限定しない。2は、批判ではなく、建設的な話し合いを行う。4は、多数決ではなく、合意をめざす。5は、専門職どうしで、意見を出し合うんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-035","examYear":"2022","examRound":"34","questionNumber":35,"category":"生活支援技術","questionText":"老化に 伴う機能低下のある高齢者の住まいに関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"寝室はトイレに近い場所が望ましい。"},{"id":"2","text":"寝室は玄関と別の階にする。"},{"id":"3","text":"夜間の騒音レベルは 80 dB 以下になるようにする。"},{"id":"4","text":"ベッドは 照明 の真下に配置する。"},{"id":"5","text":"壁紙と手すりは 同色 にするのが望ましい。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！高齢者の住まいでは、寝室をトイレに近い場所にすると、夜間の移動が楽で、転倒の危険も減るんだ。2は、寝室は、玄関と同じ階が安全。3は、夜間の騒音は、40dB以下が望ましい。4は、ベッドの真下に照明は、まぶしい。5は、壁紙と手すりは、見つけやすいよう、色を変えるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-036","examYear":"2022","examRound":"34","questionNumber":36,"category":"生活支援技術","questionText":"Ｌさん（25 歳，男性）は，第7 胸髄節（Th7）を 損傷 したが，現在， 状態は安定していて， 車いすを利用すれば 1人で日常生活ができるようになった。図はＬさんの自宅の浴室であり，必要な手すりは既に設置されている。Ｌさんが 1人で浴槽に入るための福祉用具として， 最も適切なものを 1 つ選なさい。","choices":[{"id":"1","text":"段差解消機"},{"id":"2","text":"ストレッチャー"},{"id":"3","text":"すべり止"},{"id":"4","text":"四点歩行器"},{"id":"5","text":"移乗台"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！第7胸髄（Th7）の損傷でも、上肢の機能は保たれていて、車いすを使えば一人で生活できるんだね。浴槽に一人で入るためには、車いすから、浴槽に移るための移乗台が、最も適切だよ。1の段差解消機は、玄関などの高低差、2のストレッチャーは、臥位での移動、3のすべり止めは、転倒予防、4の四点歩行器は、歩行の用具だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-037","examYear":"2022","examRound":"34","questionNumber":37,"category":"生活支援技術","questionText":"耳の清潔に関する介護福祉職の対応として， 最も適切なものを 1 つ選なさい。","choices":[{"id":"1","text":"耳垢の 状態 を観察した。"},{"id":"2","text":"綿棒を外耳道の入口から 3 cm 程度挿入した。"},{"id":"3","text":"耳介を上前方に軽く引きながら，耳垢を除去した。"},{"id":"4","text":"蒸しタオルで耳垢塞栓を柔らかくして除去した。"},{"id":"5","text":"耳かきを使用して，耳垢を毎日除去した。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！耳の清潔のケアでは、まず、耳垢の状態を観察するんだ。2は、綿棒は、1cm程度までにする。3は、耳介は、後上方に引きながら、耳垢を除去する。4は、耳垢塞栓は、無理に取らず、医療職に相談する。5は、耳かきの毎日の使用は、傷をつけるおそれがあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-038","examYear":"2022","examRound":"34","questionNumber":38,"category":"生活支援技術","questionText":"歯ブラシを使用した口腔ケアに関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"歯ブラシの毛は硬いものを勧める。"},{"id":"2","text":"強い 力で磨く。"},{"id":"3","text":"歯と歯肉の境目のブラッシングは避ける。"},{"id":"4","text":"歯ブラシを小刻みに動かしながら磨く。"},{"id":"5","text":"使用後の歯ブラシは，柄の部分を上にしてコップに入れて保管する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！歯ブラシは、小刻みに動かしながら磨くと、汚れが落ちやすくて、歯や歯肉を傷めにくいんだ。1は、毛は、やわらかめのものを勧める。2は、強い力は、歯肉を傷つける。3は、歯と歯肉の境目も、丁寧に磨く。5は、使用後は、毛の部分を上にして、乾燥させて保管するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-039","examYear":"2022","examRound":"34","questionNumber":39,"category":"生活支援技術","questionText":"Ｍさん（84 歳，男性）は，10 年前に脳伷塞（cerebral infarction）で右片麻痺になり，右上肢の 屈曲 拘 縮 がある。今までは自分で洋服を着ていたが， 1 週間ほど前から左肩関節の周囲に軽い痛みを感じるようになり，上着の 着脱 の介護が必要になった。Ｍさんへの上着の 着脱 の介護に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"服を脱ぐときは，右上肢から脱ぐ。"},{"id":"2","text":"右手首に袖を通すときは，介護福祉職の指先に 力を入れて手首をつかむ。"},{"id":"3","text":"右肘関節を伸展するときは，素早く動かす。"},{"id":"4","text":"右肘に袖を通すときは，前腕を下から支える。"},{"id":"5","text":"衣類を準備するときは，かぶり式のものを選択する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！右上肢に屈曲拘縮があるＭさんの、右肘に袖を通すときは、前腕を下から支えて、関節に無理な力がかからないようにするんだ。1は、脱ぐときは、健側（左）から先に脱ぐ。2は、指先に力を入れて、つかまない。3は、関節は、ゆっくり動かす。5は、かぶり式は、着脱が難しいよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-040","examYear":"2022","examRound":"34","questionNumber":40,"category":"生活支援技術","questionText":"経管栄養を 行っている利用者への口腔ケアに関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"スポンジブラシは水を 大量 に含ませて使用する。"},{"id":"2","text":"上顎部は，口腔の奥から手前に向かって清拭する。"},{"id":"3","text":"栄養剤注入後すぐに実施する。"},{"id":"4","text":"口腔内を乾燥させて 終了 する。"},{"id":"5","text":"空腹時の口腔ケアは避ける。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！経管栄養をしている人の口腔ケアでは、上顎部は、口腔の奥から手前に向かって、清拭するんだ。汚れが奥に落ちないようにするためだよ。1は、スポンジブラシは、水を絞って使う。3は、注入直後は、嘔吐の危険がある。4は、乾燥させないように、保湿する。5は、空腹時でも、口腔ケアは必要だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-041","examYear":"2022","examRound":"34","questionNumber":41,"category":"生活支援技術","questionText":"スライディングボードを用いた，ベッドから 車いすへの移乗の介護に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"アームサポートが固定された 車いすを準備する。"},{"id":"2","text":"ベッドから 車いすへの移乗時には，ベッドを 車いすの座面より少し高くする。"},{"id":"3","text":"ベッドと 車いすの 間を大きくあけ，スライディングボードを設置する。"},{"id":"4","text":"スライディングボード 上では，臀部を素早く移動させる。"},{"id":"5","text":"車いすに座位を安定させ，からだを 傾けずにスライディングボードを抜く。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！スライディングボードで、ベッドから車いすへ移るときは、ベッドを、車いすの座面より少し高くして、傾斜を使って、滑らせるんだ。1は、アームサポートが、取り外せる（跳ね上げられる）車いすを使う。3は、ベッドと車いすの間は、できるだけ狭くする。4は、ゆっくり移動する。5は、体を少し傾けて、ボードを抜くよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-042","examYear":"2022","examRound":"34","questionNumber":42,"category":"生活支援技術","questionText":"利用者を仰臥位（背臥位）から側臥位へ体位変換するとき，トルクの原理を応用した介護方法として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"利用者とベッドの接地面を広くする。"},{"id":"2","text":"利用者の下肢を交差させる。"},{"id":"3","text":"利用者の膝を立てる。"},{"id":"4","text":"滑りやすいシートを利用者の下に敷く。"},{"id":"5","text":"利用者に近づく。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！トルクの原理は、回転の力を利用する考え方で、膝を立てると、てこのように、体を回転させやすくなるんだ。1は、接地面を狭くすると、動かしやすい。2は、下肢を交差させるのは、別の方法。4は、摩擦を減らす方法。5は、重心に近づく、ボディメカニクスの方法だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-043","examYear":"2022","examRound":"34","questionNumber":43,"category":"生活支援技術","questionText":"視覚障害のある利用者の 外出 に同行するときの支援に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"トイレを使用するときは，トイレ内の 情報を提供 する。"},{"id":"2","text":"階段を上るときは，利用者の手首を握って誘導する。"},{"id":"3","text":"狭い場所を歩くときは，利用者の後ろに立って誘導する。"},{"id":"4","text":"タクシーに乗るときは，支援者が先に乗って誘導する。"},{"id":"5","text":"駅ではエレベーターよりエスカレーターの使用を勧める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！視覚障害のある人の外出に同行するときは、トイレの中の様子など、必要な情報を伝えるのが大切なんだ。2は、手首ではなく、支援者の肘の上あたりを、持ってもらう。3は、狭い場所では、前に立って誘導する。4は、タクシーは、利用者が先に乗る。5は、エスカレーターより、エレベーターを勧めるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-044","examYear":"2022","examRound":"34","questionNumber":44,"category":"生活支援技術","questionText":"Ａさん（78 歳，男性，要介護 2）は，脳梗塞（cerebral infarction）の後遺症で嚥下障害がある。自宅で妻と二人暮らしで，訪問介護（ホームヘルプサービス）を週1回利用している。訪問時，妻から，「飲み込みの難しいときがある。上手に食べさせるにはどうしたらよいか」と相談があった。訪問介護員（ホームヘルパー）の助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食事のときは，いすに浅く座るように勧める。"},{"id":"2","text":"会話をしながら食事をするように勧める。"},{"id":"3","text":"食事の後に嚥下体操をするように勧める。"},{"id":"4","text":"肉，野菜， 魚などは軟らかく調理するように勧める。"},{"id":"5","text":"おかずを細かく刻むように勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！嚥下障害がある人の食事では、肉、野菜、魚などを、軟らかく調理すると、飲み込みやすくなるんだ。1は、いすには、深く座る。2は、会話しながら食べると、むせやすい。3は、嚥下体操は、食事の前に行う。5は、細かく刻むと、まとまりにくく、誤嚥しやすいことがあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-045","examYear":"2022","examRound":"34","questionNumber":45,"category":"生活支援技術","questionText":"慢性腎不全（chronic renal failure）の利用者の食材や調理方法として，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"エネルギーの高い植物油を控える。"},{"id":"2","text":"レモンや香辛料を利用し，塩分を控えた味付けにする。"},{"id":"3","text":"肉や 魚を多めにする。"},{"id":"4","text":"砂糖を控えた味付けにする。"},{"id":"5","text":"野菜は生でサラダにする。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！慢性腎不全の人は、塩分の制限が必要なので、レモンや香辛料を利用して、塩分を控えた味付けにするとよいんだ。1は、エネルギーを確保するため、植物油は使う。3は、たんぱく質は制限する。4は、砂糖は、エネルギー源として使える。5は、生野菜は、カリウムが多いので、ゆでこぼすのがよいよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-046","examYear":"2022","examRound":"34","questionNumber":46,"category":"生活支援技術","questionText":"利用者の食事支援に関して，介護福祉職が連携する職種 として， 最適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"スプーンや箸がうまく使えないときは，食事動作の訓練を言語聴覚士に依頼する。"},{"id":"2","text":"咀嚼障害があるときは，義歯の 調整 を作業療法士に依頼する。"},{"id":"3","text":"座位の保持が困難なときは，体幹訓練を理学療法士に依頼する。"},{"id":"4","text":"摂食 ・嚥下障害があるときは，嚥下訓練を義肢装具士に依頼する。"},{"id":"5","text":"食べ残しが目立つときは，献立や調理方法の変更を社会福祉士に依頼する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！座位の保持が困難な人の、体幹訓練は、理学療法士に依頼するのが適切なんだ。1は、食事動作の訓練は、作業療法士。2は、義歯の調整は、歯科医師や歯科衛生士。4は、嚥下訓練は、言語聴覚士。5は、献立や調理方法の変更は、管理栄養士だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-047","examYear":"2022","examRound":"34","questionNumber":47,"category":"生活支援技術","questionText":"入浴 の介護に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"着替えの衣服は，介護福祉職が選択する。"},{"id":"2","text":"空腹時の 入浴 は控える。"},{"id":"3","text":"入浴前の水分摂取は控える。"},{"id":"4","text":"食後1時間以内に 入浴 する。"},{"id":"5","text":"入浴 直 前 の浴槽の湯は，45℃で保温する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！空腹時の入浴は、低血糖を起こすおそれがあるので、避けるのがよいんだ。1は、着替えの衣服は、利用者が選ぶ。3は、入浴前は、水分をとる。4は、食後1時間以内は、消化に負担がかかる。5は、浴槽の湯は、41℃前後が適温だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-048","examYear":"2022","examRound":"34","questionNumber":48,"category":"生活支援技術","questionText":"シャワー浴の介護に関する次の記述のうち， 最も適切なものを 1 つ選なさい。","choices":[{"id":"1","text":"シャワーの湯温は，介護福祉職よりも先に利用者が確認する。"},{"id":"2","text":"からだ全体にシャワーをかけるときは，上肢から先に 行う。"},{"id":"3","text":"利用者が寒さを 訴えたときは，熱いシャワーをかける。"},{"id":"4","text":"利用者が陰部を洗うときは，介護福祉職は背部に立って見守る。"},{"id":"5","text":"脱衣室に移動してから，からだの水分を拭きとる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！利用者が自分で陰部を洗うときは、プライバシーに配慮して、介護福祉職は背部に立ち、安全を見守るのが適切なんだ。1は、湯温は、まず介護福祉職が確認してから、利用者にも確認してもらうのが基本だよ。2は、シャワーは下肢から先にかける。3は、寒いときも、熱すぎない適温にする。5は、脱衣室に移動する前に、浴室内で水分を拭き取るんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-049","examYear":"2022","examRound":"34","questionNumber":49,"category":"生活支援技術","questionText":"左片麻痺のある利用者が，浴槽内から一部介助で立ち上がる方法として，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"利用者の 左膝 を立てて， 左の 踵を臀部に引き寄せてもらう。"},{"id":"2","text":"浴槽の底面に両手を置いてもらう。"},{"id":"3","text":"右手で手すりをつかんで前傾姿勢をとり，臀部を浮かしてもらう。"},{"id":"4","text":"利用者の両腋窩に手を入れて支える。"},{"id":"5","text":"素早く立ち上がるように 促す。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！左片麻痺の人が、浴槽から立ち上がるときは、右手（健側）で手すりをつかんで、前傾姿勢をとり、臀部を浮かしてもらうんだ。1は、麻痺のある足を、勝手に動かさない。2は、両手を底面に置くと、立てない。4は、腋窩を支えると、肩を痛める。5は、素早く立つと、ふらつくよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-050","examYear":"2022","examRound":"34","questionNumber":50,"category":"生活支援技術","questionText":"入浴関連用具の使用方法に関する次の記述のうち， 最も適切なものを 1つ選びなさい。","choices":[{"id":"1","text":"シャワー 用車 いすは，段差に注意して移動する。"},{"id":"2","text":"入浴 の移乗台は，浴槽よりも高く設定する。"},{"id":"3","text":"浴槽設置式リフトは，臥位の 状態 で使用する。"},{"id":"4","text":"入浴用介助ベルトは，利用者の胸部に 装着 する。"},{"id":"5","text":"ストレッチャーで機械浴槽に入るときは，ストレッチャーのベルトを外す。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！シャワー用車いすは、浴室や脱衣室の段差に、注意して移動するんだ。2は、移乗台は、浴槽の縁と、同じくらいの高さにする。3は、浴槽設置式リフトは、座位の状態で使う。4は、入浴用介助ベルトは、腰に装着する。5は、機械浴槽では、ストレッチャーのベルトで、体を固定するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-051","examYear":"2022","examRound":"34","questionNumber":51,"category":"生活支援技術","questionText":"便秘の傾向がある高齢者に自然排便を 促すための介護として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"朝食 を抜くように勧める。"},{"id":"2","text":"油を控えるように勧める。"},{"id":"3","text":"散歩をするように勧める。"},{"id":"4","text":"腰部を冷やすように勧める。"},{"id":"5","text":"就寝前にトイレに座るように勧める。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！散歩などの適度な運動は、腸の動きを促して、自然な排便につながるんだ。1は、朝食を抜くと、胃・結腸反射が起こらない。2は、油分は、腸を滑らかにする。4は、腰部を冷やすのではなく、温める。5は、就寝前ではなく、朝食後に、トイレに座るのがよいよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-052","examYear":"2022","examRound":"34","questionNumber":52,"category":"生活支援技術","questionText":"認知機能の低下による機能性尿失禁で，夜間，トイレではない場所で排尿してしまう利用者への対応として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"日中，足上げ運動をする。"},{"id":"2","text":"ズボンのゴムひもを緩いものに変える。"},{"id":"3","text":"膀胱訓練を 行う。"},{"id":"4","text":"排泄してしまう場所に入れないようにする。"},{"id":"5","text":"トイレの 照明 をつけて，ドアを開けておく。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！認知機能の低下で、夜間、トイレの場所がわからないときは、トイレの照明をつけて、ドアを開けておくと、場所がわかりやすくなるんだ。1は、足上げ運動は、関係ない。2は、ゆるいゴムは、ずり落ちやすい。3は、膀胱訓練は、機能性尿失禁には向かない。4は、入れなくすると、別の場所で排泄するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-053","examYear":"2022","examRound":"34","questionNumber":53,"category":"生活支援技術","questionText":"次の記述のうち，排泄物で汚れた衣類をタンスに隠してしまう認知症（dementia）の利用者への対応として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"タンスの中に汚れた衣類を入れられる場所を確保する。"},{"id":"2","text":"「汚れた衣類は入れないように」とタンスに貼紙をする。"},{"id":"3","text":"トイレに行くときには，同行して近くで監視する。"},{"id":"4","text":"つなぎ服を勧める。"},{"id":"5","text":"隠すところを見たら，毎回注意する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！排泄物で汚れた衣類を隠すのは、恥ずかしさや、汚れを見られたくない気持ちがあるからなんだね。タンスの中に、汚れた衣類を入れられる場所を確保すると、本人の気持ちを尊重しつつ、対応できるよ。2、5は、注意して、責めることになる。3は、監視は、羞恥心を傷つける。4は、つなぎ服は、本人の尊厳を損ねるおそれがあるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-054","examYear":"2022","examRound":"34","questionNumber":54,"category":"生活支援技術","questionText":"次亜塩素酸ナトリウムを主成分とする衣類用漂白剤に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"全ての白物の 漂白 に使用できる。"},{"id":"2","text":"色柄物の 漂白 に適している。"},{"id":"3","text":"熱湯で薄めて用いる。"},{"id":"4","text":"手指の 消毒 に適している。"},{"id":"5","text":"衣類の除菌効果がある。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！次亜塩素酸ナトリウムを主成分とする漂白剤は、衣類の除菌効果があるんだ。1は、すべての白物に使えるわけではない（絹、ウール、ナイロンなどは不可）。2は、色柄物は、色が落ちるので、使えない。3は、熱湯ではなく、水で薄める。4は、手指の消毒には、使わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-055","examYear":"2022","examRound":"34","questionNumber":55,"category":"生活支援技術","questionText":"次の記述のうち，ズボンの裾上げの縫い目が 表から目立たない手縫いの方法として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"なみ縫"},{"id":"2","text":"半返し縫"},{"id":"3","text":"本返し縫"},{"id":"4","text":"コの字縫い（コの字とじ）"},{"id":"5","text":"まつり縫"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！ズボンの裾上げで、表から縫い目が目立たない手縫いの方法は、まつり縫いなんだ。裏側で、すくうように縫うから、表に糸が出にくいよ。1のなみ縫いは、基本の縫い方、2の半返し縫いと、3の本返し縫いは、丈夫に縫う方法、4のコの字縫いは、ぬいしろを閉じるときに使う方法だね。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-056","examYear":"2022","examRound":"34","questionNumber":56,"category":"生活支援技術","questionText":"心地よい睡眠環境を整備するためのベッドメイキングに関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"シーツを外すときは，汚れた面を外側に丸めながら外す。"},{"id":"2","text":"しわを作らないために，シーツの角を対角線の方向に伸ばして 整える。"},{"id":"3","text":"袋状の枕カバーの端を入れ込んで使用するときは，布の折り込み側が上るように置く。"},{"id":"4","text":"掛け毛布はゆるみを作らずにシーツの足元に押し込む。"},{"id":"5","text":"動かしたベッド 上の利用者の物品は，使いやすいように位置を変えておく。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ベッドメイキングでは、シーツの角を、対角線の方向に伸ばして、しわのないように整えるんだ。1は、シーツを外すときは、汚れた面を、内側に丸める。4は、掛け毛布は、足元に、ゆとりをもたせる。5は、動かした物品は、元の位置に戻すよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-057","examYear":"2022","examRound":"34","questionNumber":57,"category":"生活支援技術","questionText":"夜勤のある施設職員が 良質 な睡眠をとるための生活習慣に関する次記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"夜勤に入る前には仮眠をとらない。"},{"id":"2","text":"寝る前にスマートフォンでメールをチェックする。"},{"id":"3","text":"朝食と夕食 の開始時間を日によって変える。"},{"id":"4","text":"夜勤後の帰宅時にはサングラス（sunglasses）をかけるなど，日光を避する。"},{"id":"5","text":"休日 に寝だめをする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！夜勤後、朝の強い日光を浴びると、体内時計が乱れて、眠りにくくなるんだ。だから、帰宅時にサングラスをかけて、日光を避けるのが、効果的だよ。1は、夜勤前は、仮眠をとるとよい。2は、寝る前のスマートフォンは、眠りを妨げる。3は、食事時間は、決まった時間にする。5は、寝だめは、リズムを乱すよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-058","examYear":"2022","examRound":"34","questionNumber":58,"category":"生活支援技術","questionText":"Ｂさん（102 歳，女性）は，介護老人福祉施設に入所している。高齢による身体機能の 衰えがあり，機能低下の状態が長く続いていた。 1 週間前から経口摂取が困難になった。 1 日の大半は目を閉じ，臥床状態が続いている。医師から，「老衰により死期が近い」と診断され，家族は施設で看取りたいと希望している。死が極めて近い 状態にあるＢさんの看取りに必要な情報 として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"体重の減少"},{"id":"2","text":"夜間の睡眠時間"},{"id":"3","text":"延命治療の意思"},{"id":"4","text":"嚥下可能な食形態"},{"id":"5","text":"呼吸の 状態"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！死が極めて近い状態のＢさんの看取りでは、呼吸の状態が、いちばん重要な情報なんだ。呼吸の変化は、死が近づくサインになるよ。1、2、4は、日常の観察で、看取りの直前に必要な情報としては、優先度が低い。3の延命治療の意思は、もっと早い段階で確認しておくことだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-059","examYear":"2022","examRound":"34","questionNumber":59,"category":"生活支援技術","questionText":"介護老人福祉施設における終末期の利用者の家族支援に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"緊急連絡先を 1 つにすることを提案する。"},{"id":"2","text":"面会を控えるように伝える。"},{"id":"3","text":"死に至る過程で 生じる身体的変化を説明する。"},{"id":"4","text":"死後の衣服は浴衣がよいと提案する。"},{"id":"5","text":"亡くなる 瞬間 に立ち会うことが一番重要だと伝える。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！終末期の家族には、死に至る過程で生じる、身体的な変化を、事前に説明すると、心の準備ができて、不安が和らぐんだ。1は、緊急連絡先は、複数にしておくとよい。2は、面会は、控えずに勧める。4は、衣服は、本人や家族の希望を聞く。5は、立ち会いを強調するのは、家族の負担になるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-060","examYear":"2022","examRound":"34","questionNumber":60,"category":"生活支援技術","questionText":"死亡後の介護に関する次の記述のうち， 最も適切なものを 1 つ選い。","choices":[{"id":"1","text":"死後硬直がみられてから実施する。"},{"id":"2","text":"生前と同じように利用者に声をかけながら介護を 行う。"},{"id":"3","text":"義歯を外す。"},{"id":"4","text":"髭剃り後はクリーム塗布を控える。"},{"id":"5","text":"両手を組むために手首を包帯でしばる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！死亡後の介護でも、生前と同じように、声をかけながら、丁寧に行うんだ。1は、死後硬直が始まる前に、体を整える。3は、義歯は、装着したままがよい。4は、髭剃りのあとは、クリームを塗る。5は、手首を包帯でしばると、跡が残るので、しないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-061","examYear":"2022","examRound":"34","questionNumber":61,"category":"介護過程","questionText":"介護福祉職が介護過程を展開する意義に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"チームアプローチ（team approach）による介護を 提供 することができる。"},{"id":"2","text":"直感的な判断をもとに介護を 考えることができる。"},{"id":"3","text":"今までの生活から切り離した介護を 提供 する。"},{"id":"4","text":"介護福祉職が生活を管理するための介護を 考えることができる。"},{"id":"5","text":"介護福祉職が実施したい介護を 提供 する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！介護過程を展開する意義は、根拠にもとづいた介護を、チームアプローチによって、提供できることなんだ。2は、直感ではなく、根拠にもとづく。3は、今までの生活とつなげる。4、5は、介護福祉職の都合ではなく、利用者主体で考えるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-062","examYear":"2022","examRound":"34","questionNumber":62,"category":"介護過程","questionText":"介護過程における 情報 収 集 に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"利用者の日常生活の困難な部分を 中心に収集 する。"},{"id":"2","text":"利用者との会話は 解釈 して記載する。"},{"id":"3","text":"他の専門職が記載した記録は直接的な情報 として 扱う。"},{"id":"4","text":"利用者の生活に対する思いを大切にしながら 収集 する。"},{"id":"5","text":"情報 収 集 はモニタリング（monitoring）を実施してから 行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！情報収集では、利用者の生活に対する思いを大切にしながら、収集するんだ。1は、困難な部分だけでなく、できることや、強みも集める。2は、会話は、解釈せず、そのまま記載する。3は、他職種の記録は、間接的な情報。5は、モニタリングの前に、情報収集を行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-063","examYear":"2022","examRound":"34","questionNumber":63,"category":"介護過程","questionText":"介護過程における生活課題に関する次の記述のうち， 最も適切なものを1 つ選びなさい。","choices":[{"id":"1","text":"効率的な支援を 提供 するために解決するべきこと。"},{"id":"2","text":"利用者が家族の望む生活を送るために解決するべきこと。"},{"id":"3","text":"介護福祉職が実践困難な課題のこと。"},{"id":"4","text":"利用者の生活を改善するために思いついたこと。"},{"id":"5","text":"利用者が望む生活を実現するために解決するべきこと。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！生活課題は、利用者が望む生活を実現するために、解決するべきことなんだ。1は、効率のためではない。2は、家族が望む生活ではなく、利用者が望む生活。3は、実践困難かどうかで決めない。4は、思いつきではなく、アセスメントにもとづくよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-064","examYear":"2022","examRound":"34","questionNumber":64,"category":"介護過程","questionText":"介護過程における 目標 の設定に関する次の記述のうち，適切なものを 1つ選びなさい。","choices":[{"id":"1","text":"長期目標の期間は， 1 か月程度に設定する。"},{"id":"2","text":"長期目標は，短期目標ごとに設定する。"},{"id":"3","text":"短期目標は，生活全般の課題が解決した 状態を表現 する。"},{"id":"4","text":"短期目標は， 抽象 的 な内容で 表現 する。"},{"id":"5","text":"短期目標は，長期目標の達成につながるように設定する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！短期目標は、長期目標の達成につながるように、設定するんだ。1は、長期目標の期間は、半年から1年程度。2は、長期目標は、短期目標ごとに設定するわけではない。3は、短期目標は、具体的な生活課題の解決を示す。4は、抽象的ではなく、具体的に表現するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-065","examYear":"2022","examRound":"34","questionNumber":65,"category":"介護過程","questionText":"介護計画における介護内容に関する次の記述のうち， 最も適切なものを1 つ選びなさい。","choices":[{"id":"1","text":"利用者の 能力 よりも介護の効率を重視して決める。"},{"id":"2","text":"業務の都合に応じて介護できるように，時間の設定は 省略 する。"},{"id":"3","text":"介護するときの注意点についても記載する。"},{"id":"4","text":"利用者の意思よりも介護福祉職の 考えを優先して決める。"},{"id":"5","text":"介護福祉職だけが理解できる 表現 にする。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！介護計画の介護内容には、介護するときの注意点も、記載しておくと、だれが行っても、安全に介護できるんだ。1は、効率より、利用者の能力を生かす。2は、時間の設定も必要。4は、利用者の意思を優先する。5は、だれが読んでもわかる表現にするよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-066","examYear":"2022","examRound":"34","questionNumber":66,"category":"介護過程","questionText":"Ｃさん（84 歳，女性，要介護 3）は， 2 か月前に自宅で倒れた。 脳出 血（cerebral hemorrhage）と診断され，後遺症で左片麻痺になった。Ｃさんは自宅での生活を希望している。 長男 からは，「トイレが自分でできるようになってから自宅に戻ってほしい」との要望があった。そのため， 病院 から，リハビリテーションを目的に介護老人保健施設に 入所 した。入所時，Ｃさんは，「孫と一緒に過ごしたいから，リハビリテーションを頑張りたい」と笑顔で話した。Ｃさんは，自力での歩行は困難だが，施設内では健側を使って 車いすで移動することができる。また，手すりにつかまれば自分で立ち上がれるが，上半身が後ろに 傾くため，移乗には介護が必要な 状態 である。入所時に介護福祉職が 行うアセスメント（assessment）に関する次の記述のうち，最も優先すべきものを 1 つ選びなさい。","choices":[{"id":"1","text":"自力で歩行ができるのかを確認する。"},{"id":"2","text":"排泄に関連した動作について確認する。"},{"id":"3","text":"孫と面会する頻度について希望を聞く。"},{"id":"4","text":"リクライニング 車いすの活用について尋ねる。"},{"id":"5","text":"住宅 改 修 に必要な資金があるのかを確認する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｃさんは、長男から、トイレが自分でできるようになってから、自宅に戻ってほしいと要望されていて、本人も、リハビリを頑張りたいと話しているね。アセスメントでは、排泄に関連した動作を、最優先で確認するよ。1は、歩行は、困難と示されている。3、4、5は、優先度が低いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-067","examYear":"2022","examRound":"34","questionNumber":67,"category":"介護過程","questionText":"次の事例を読んで，問題 67，問題 68 について答えなさい。〔事例〕Ｄさん（73 歳，女性，要介護 2）は，認知症対応型共同生活介護（認知症高齢者グループホーム）に 入居 した。入居後，本人の同意のもとに短期目標を，「食事の準備に参加する」と設定し， 順調に経過していた。ある日，Ｄさんが 夕食 の準備に来なかった。翌日，担当する介護福祉職が居室を訪ねて理由を聞くと，「盛り付けの見た目が・・・」と小声で言った。当日のＤさんの記録を見ると，「お茶を配ると席に座ったが，すぐに立ち上がり，料理を皿に盛り付けるＥさんの手元を見ていた」「配膳された料理を見て，ため息いた」とあった。その後，食事の準備には参加していないが，早く来て様子を見る。また，食事中は談笑 し，食事も 完食 している。以上のことから再アセスメントを 行うことになった。\nＤさんの再アセスメントに関する次の記述のうち， 最も適切なものを 1つ選びなさい。","choices":[{"id":"1","text":"お茶を配る 能力 について分析する。"},{"id":"2","text":"ため息の意味を料理の味が悪いと 解釈 する。"},{"id":"3","text":"早く来て様子を見ている理由を分析する。"},{"id":"4","text":"安心して食事ができているかを分析する。"},{"id":"5","text":"Ｅさんに料理の盛り付けを学びたいと 解釈 する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｄさんは、食事の準備には参加していないけれど、早く来て様子を見ているね。その理由を分析して、Ｄさんの気持ちを、理解することが大切だよ。1は、お茶を配る能力は、問題ではない。2、5は、決めつけた解釈。4は、食事は、完食しているので、安心して食べられているのは、明らかだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-068","examYear":"2022","examRound":"34","questionNumber":68,"category":"介護過程","questionText":"次の事例を読んで，問題 67，問題 68 について答えなさい。〔事例〕Ｄさん（73 歳，女性，要介護 2）は，認知症対応型共同生活介護（認知症高齢者グループホーム）に 入居 した。入居後，本人の同意のもとに短期目標を，「食事の準備に参加する」と設定し， 順調に経過していた。ある日，Ｄさんが 夕食 の準備に来なかった。翌日，担当する介護福祉職が居室を訪ねて理由を聞くと，「盛り付けの見た目が・・・」と小声で言った。当日のＤさんの記録を見ると，「お茶を配ると席に座ったが，すぐに立ち上がり，料理を皿に盛り付けるＥさんの手元を見ていた」「配膳された料理を見て，ため息いた」とあった。その後，食事の準備には参加していないが，早く来て様子を見る。また，食事中は談笑 し，食事も 完食 している。以上のことから再アセスメントを 行うことになった。\nカンファレンス（conference）が開かれ，Ｄさんの支援について検討することになった。Ｄさんを担当する介護福祉職が提案する内容として， 最も優先すべきものを 1 つ選びなさい。","choices":[{"id":"1","text":"食器の満足度を調べること。"},{"id":"2","text":"昼食時だけでも計画を継続すること。"},{"id":"3","text":"居室での食事に変更すること。"},{"id":"4","text":"食事の準備の役割を見直すこと。"},{"id":"5","text":"食事以外の短期目標を設定すること。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｄさんは、盛り付けの見た目が気になって、参加をやめたんだね。食事の準備の役割を見直して、Ｄさんが安心して参加できるようにすることが、最も優先するべき提案だよ。1、5は、原因ではない。2は、短期目標を、そのまま継続しても、解決しない。3は、居室での食事は、閉じこもりにつながるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-069","examYear":"2022","examRound":"34","questionNumber":69,"category":"発達と老化の理解","questionText":"愛着行動に関する次の記述のうち，ストレンジ・シチュエーション法おける安定型の愛着行動として，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"養育者がいないと不安な様子になり，再会すると安心して 再び遊び始める。"},{"id":"2","text":"養育者がいないと不安な様子になり，再会すると接近して怒りを示す。"},{"id":"3","text":"養育者がいないと不安な様子になり，再会すると関心を示さずに遊んでいる。"},{"id":"4","text":"養育者がいなくても不安な様子にならず，再会すると関心を示さずに遊んでいる。"},{"id":"5","text":"養育者がいなくても不安な様子にならず，再会すると 喜んで遊び続ける。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ストレンジ・シチュエーション法の安定型は、養育者がいなくなると不安になるけれど、再会すると、安心して、再び遊び始めるんだ。2は、アンビヴァレント型、3、4は、回避型の特徴。5は、不安にならない反応で、安定型とは、ちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-070","examYear":"2022","examRound":"34","questionNumber":70,"category":"発達と老化の理解","questionText":"乳幼児期の言語発達に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"生後 6 か月ごろに初語を発するようになる。"},{"id":"2","text":"1 歳ごろに喃語を発するようになる。"},{"id":"3","text":"1 歳半ごろに語彙爆発が起きる。"},{"id":"4","text":"2 歳半ごろに一語文を話すようになる。"},{"id":"5","text":"3 歳ごろに二語文を話すようになる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！乳幼児期の言語発達では、1歳半ごろに、急に言葉が増える、語彙爆発が起こるんだ。1は、初語は、1歳ごろ。2は、喃語は、生後6か月ごろから。4は、一語文は、1歳ごろ。5は、二語文は、2歳ごろだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-071","examYear":"2022","examRound":"34","questionNumber":71,"category":"発達と老化の理解","questionText":"2019 年（平成 31 年，令和元年）における，我が国の 寿命 と死因に関次の記述のうち，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"健康寿命は，平均寿命よりも長い。"},{"id":"2","text":"人口全体の死因順位では，老衰が悪性新生物より上位である。"},{"id":"3","text":"人口全体の死因で 最も多いのは，脳血管障害（cerebrovascular disorder）である。"},{"id":"4","text":"平均寿命は，男女とも 75 歳未満である。"},{"id":"5","text":"90 歳女性の平均余命は， 5 年以上である。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！2019年の、90歳女性の平均余命は、約6年で、5年以上だよ。1は、健康寿命は、平均寿命より短い。2は、死因順位は、悪性新生物が、老衰より上位。3は、最も多い死因は、悪性新生物。4は、平均寿命は、男女とも、80歳を超えているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-072","examYear":"2022","examRound":"34","questionNumber":72,"category":"発達と老化の理解","questionText":"Ａさん（87 歳，女性，要介護 3）は， 2 週間前に介護老人福祉施設に 入所した。Ａさんにはパーキンソン 病（Parkinson disease）があり，入所後に転倒したことがあった。介護職員は頻繁に，「危ないから 車いすに座っていてくださいね」と声をかけていた。Ａさんは徐々に自分でできることも介護職員に依存し，着替えも手伝ってほしいと 訴えるようになった。Ａさんに 生じている適応（防衛）機制として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"投影"},{"id":"2","text":"退行"},{"id":"3","text":"攻撃"},{"id":"4","text":"抑圧"},{"id":"5","text":"昇華"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ａさんは、転倒後に、「危ないから車いすに座っていて」と言われ続けて、自分でできることも、介護職員に頼るようになったんだね。これは、以前の未熟な段階に戻って、依存する、退行という適応機制だよ。1の投影は、自分の感情を他人のものと思うこと、3の攻撃は、怒りを向けること、4の抑圧は、意識から追い出すこと、5の昇華は、社会に認められる形に変えることだね。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-073","examYear":"2022","examRound":"34","questionNumber":73,"category":"発達と老化の理解","questionText":"記憶に関する次の記述のうち，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"エピソード記憶は，短期記憶に分類される。"},{"id":"2","text":"意味記憶は，言葉の意味などに関する記憶である。"},{"id":"3","text":"手続き記憶は，過去の出来事に関する記憶である。"},{"id":"4","text":"エピソード記憶は，老化に 影響 されにくい。"},{"id":"5","text":"意味記憶は，老化に 影響 されやすい。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！意味記憶は、言葉の意味や知識など、一般的な情報の記憶なんだ。1は、エピソード記憶は、長期記憶に分類される。3は、手続き記憶は、体で覚えた動作の記憶。4は、エピソード記憶は、老化の影響を受けやすい。5は、意味記憶は、老化の影響を受けにくいよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-074","examYear":"2022","examRound":"34","questionNumber":74,"category":"発達と老化の理解","questionText":"老化に 伴う感覚機能や認知機能の変化に関する次の記述のうち， 最適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"大きな声で話しかけられても，かえって聞こえにくいことがある。"},{"id":"2","text":"会話をしながら運転するほうが，安全に運転できるようになる。"},{"id":"3","text":"白と黄色よりも，白と赤の区別がつきにくくなる。"},{"id":"4","text":"低い声よりも，高い声のほうが聞き取りやすくなる。"},{"id":"5","text":"薄暗い部屋のほうが，細かい作業をしやすくなる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！老化に伴う聴覚の変化で、大きな声で話しかけられても、かえって聞こえにくいことがあるんだ（補充現象）。2は、会話しながらの運転は、注意が散る。3は、白と黄色のほうが、区別しにくくなる。4は、高い声のほうが、聞き取りにくくなる。5は、薄暗い部屋では、細かい作業がしにくいよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-075","examYear":"2022","examRound":"34","questionNumber":75,"category":"発達と老化の理解","questionText":"高齢者の睡眠に関する次の記述のうち，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"午前中の遅い時間まで眠ることが多い。"},{"id":"2","text":"刺激を与えても起きないような深い睡眠が多い。"},{"id":"3","text":"睡眠障害を自覚することは少ない。"},{"id":"4","text":"不眠の原因の 1 つはメラトニン（melatonin）の 減少 である。"},{"id":"5","text":"高齢者の睡眠時無呼吸症候群（sleep apnea syndrome）の発生頻度は，若年者よりも低い。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！高齢者は、睡眠に関係するメラトニンが減るので、不眠の原因の1つになるんだ。1は、早朝に目が覚めやすい。2は、浅い睡眠が多い。3は、睡眠障害を自覚することは、多い。5は、睡眠時無呼吸症候群は、高齢者に多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-076","examYear":"2022","examRound":"34","questionNumber":76,"category":"発達と老化の理解","questionText":"高齢者の肺炎（pneumonia）に関する次の記述のうち， 最も適切なものを1 つ選びなさい。","choices":[{"id":"1","text":"意識障害になることはない。"},{"id":"2","text":"体温が 37.5℃未満であれば肺炎（pneumonia）ではない。"},{"id":"3","text":"頻呼吸になることは，まれである。"},{"id":"4","text":"誤嚥による肺炎（pneumonia）を起こしやすい。"},{"id":"5","text":"咳・痰などを 伴うことは，まれである。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！高齢者は、飲み込む力が低下して、誤嚥による肺炎（誤嚥性肺炎）を起こしやすいんだ。1は、意識障害になることもある。2は、高齢者は、発熱しにくく、体温が低くても、肺炎のことがある。3は、頻呼吸になることも多い。5は、咳や痰を伴うことが多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-077","examYear":"2022","examRound":"34","questionNumber":77,"category":"認知症の理解","questionText":"認知症ケアにおける「ひもときシート」に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"「ひもときシート」では，最初に分析的理解を 行う。"},{"id":"2","text":"認知症（dementia）の人の言動を介護者側の視点でとらえる。"},{"id":"3","text":"言動の背景要因を分析して認知症（dementia）の人を理解するためのツールである。"},{"id":"4","text":"評価的理解では，潜在的なニーズを重視する。"},{"id":"5","text":"共感的理解では， 8 つの要因で言動を分析する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！「ひもときシート」は、認知症の人の言動の背景要因を、分析して、その人を理解するためのツールなんだ。1は、最初に評価的理解を行う。2は、本人の視点でとらえる。4は、評価的理解ではなく、共感的理解で、潜在的なニーズを重視する。5は、分析的理解で、8つの要因で言動を分析するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-078","examYear":"2022","examRound":"34","questionNumber":78,"category":"認知症の理解","questionText":"レビー小体型認知症（dementia with Lewy bodies）の幻視の 特徴 に関る次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"幻視の内容はあいまいではっきりしない。"},{"id":"2","text":"睡眠中でも幻視が 生じる。"},{"id":"3","text":"本人は説明されても幻視という認識ができない。"},{"id":"4","text":"薄暗い部屋を明るくすると幻視が消えることがある。"},{"id":"5","text":"抗精神病薬による治療が 行われることが多い。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！レビー小体型認知症の幻視は、薄暗い部屋で見えやすく、明るくすると、消えることがあるんだ。1は、幻視の内容は、具体的でありありとしている。2は、睡眠中ではなく、起きているときに生じる。3は、説明で、幻視と認識できることもある。5は、抗精神病薬は、副作用が出やすいので、慎重に使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-079","examYear":"2022","examRound":"34","questionNumber":79,"category":"認知症の理解","questionText":"軽度認知障害（mild cognitive impairment）に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"本人や家族から記憶低下の訴えがあることが多い。"},{"id":"2","text":"診断された人の約半数がその後1年の間に認知症（dementia）になる。"},{"id":"3","text":"ＣＤＲ（Clinical Dementia Rating）のスコアが 2 である。"},{"id":"4","text":"日常生活能力が低下している。"},{"id":"5","text":"治療には，主に抗認知症薬が用いられる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！軽度認知障害（ＭＣＩ）では、本人や家族から、記憶低下の訴えがあることが多いんだ。ただし、日常生活能力は、おおむね保たれているよ。3のＣＤＲのスコアは、0.5、4は、日常生活能力は、保たれている、5は、抗認知症薬は、主な治療ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-080","examYear":"2022","examRound":"34","questionNumber":80,"category":"認知症の理解","questionText":"若年性認知症（dementia with early onset）に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"75 歳未満に 発症 する認知症（dementia）である。"},{"id":"2","text":"高齢者の認知症（dementia）よりも進行は緩やかである。"},{"id":"3","text":"早期発見・早期対応しやすい。"},{"id":"4","text":"原因で 最も多いのはレビー小体型認知症（dementia with Lewy bodies）である。"},{"id":"5","text":"不安や抑うつを 伴うことが多い。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！若年性認知症では、不安や抑うつを伴うことが多いんだ。1は、65歳未満で発症する認知症。2は、進行が速いことが多い。3は、早期発見が遅れやすい。4は、原因で最も多いのは、血管性認知症だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-081","examYear":"2022","examRound":"34","questionNumber":81,"category":"認知症の理解","questionText":"認知症（dementia）の行動・心理症状（ＢＰＳＤ）に対する抗精神病薬を用いた薬物療法でよくみられる副作用として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"歩幅が広くなる。"},{"id":"2","text":"誤嚥のリスクが高くなる。"},{"id":"3","text":"過剰に活動的になる。"},{"id":"4","text":"筋肉の 緊張 が緩む。"},{"id":"5","text":"怒りっぽくなる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！抗精神病薬の副作用には、筋肉が硬くなったり、飲み込みが悪くなったりして、誤嚥のリスクが高くなることがあるんだ。1は、歩幅は、狭くなる。3は、活動性は、低下する。4は、筋緊張は、高まる（錐体外路症状）。5は、怒りっぽさが治まる作用だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-082","examYear":"2022","examRound":"34","questionNumber":82,"category":"認知症の理解","questionText":"軽度の認知症（dementia）の人に，日付，季節，天気，場所などの 情報 をふだんの会話の中で伝えて認識してもらう認知症ケアとして，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"ライフレビュー（life review）"},{"id":"2","text":"リアリティ・オリエンテーション（reality orientation）"},{"id":"3","text":"バリデーション（validation）"},{"id":"4","text":"アクティビティ・ケア（activity care）"},{"id":"5","text":"タッチング（touching）"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！日付や季節、天気、場所などの情報を、ふだんの会話の中で伝えて、認識してもらうケアは、リアリティ・オリエンテーション（現実見当識訓練）なんだ。1のライフレビューは、人生の振り返り、3のバリデーションは、感情に寄り添う方法、4のアクティビティ・ケアは、活動を通したケア、5のタッチングは、触れる方法だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-083","examYear":"2022","examRound":"34","questionNumber":83,"category":"認知症の理解","questionText":"Ｂさん（86 歳，女性）は，中等度のアルツハイマー型認知症（dementia ofthe Alzheimerʼs type）である。短期入所生活介護（ショートステイ）の利用を始日の翌朝，両手に便が付着した 状態 でベッドに座っていた。Ｂさんへの声かけとして，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"「臭いからきれいにします」"},{"id":"2","text":"「 汚い便が手についています」"},{"id":"3","text":"「ここはトイレではありません」"},{"id":"4","text":"「手を洗いましょう」"},{"id":"5","text":"「こんなに汚れて困ります」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｂさんは、便が手についていて、恥ずかしさや不安を感じているかもしれないね。「手を洗いましょう」と、穏やかに声をかけて、自尊心を傷つけずに、対応するのがよいよ。1、2、3、5は、否定的な言い方で、Ｂさんを傷つけてしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-084","examYear":"2022","examRound":"34","questionNumber":84,"category":"認知症の理解","questionText":"Ｃさん（80 歳，女性）は 夫（85 歳）と二人暮らしである。 1 年ほど前から記憶障 害 があり，最近，アルツハイマー型認知症（dementia of the Alzheimerʼstype）と診断された。探し物が増え，財布や保険証を見つけられないと，「泥棒が入った，警察に連絡して」と 訴えるようになった。「泥棒なんて入っていない」と警察を呼ばずにいると，Ｃさんがますます興奮するので， 夫は対応に困っている。夫から相談を受けた介護福祉職の助言として， 最も適切なものを 1 つ選い。","choices":[{"id":"1","text":"「主治医に興奮を抑える 薬の相談をしてみてはどうですか」"},{"id":"2","text":"「施設入所を検討してはどうですか」"},{"id":"3","text":"「Ｃさんと一緒に探してみてはどうですか」"},{"id":"4","text":"「Ｃさんの希望通り，警察に通報してはどうですか」"},{"id":"5","text":"「Ｃさんに認知症（dementia）であることを説明してはどうですか」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｃさんは、探し物が見つからなくて、「泥棒が入った」と訴えているね。一緒に探すことで、Ｃさんの不安を受け止め、落ち着いてもらえるよ。1は、薬は、まず対応を工夫してから。2は、施設入所は、まだ早い。4は、警察に通報するのは、適切ではない。5は、説明しても、理解できず、傷つけることがあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-085","examYear":"2022","examRound":"34","questionNumber":85,"category":"認知症の理解","questionText":"認知症（dementia）の人に配慮した施設の生活環境として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"いつも安心感をもってもらえるように接する。"},{"id":"2","text":"私物は本人の見えないところに片付ける。"},{"id":"3","text":"毎日新しい生活体験をしてもらう。"},{"id":"4","text":"壁の色と同系色の表示を使用する。"},{"id":"5","text":"日中は1人で過ごしてもらう。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！認知症の人には、いつも安心感をもってもらえるように、接することが大切なんだ。2は、私物は、見えるところに置く。3は、毎日新しい体験は、混乱させる。4は、壁と同系色の表示は、見えにくい。5は、日中は、交流や活動の機会をつくるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-086","examYear":"2022","examRound":"34","questionNumber":86,"category":"認知症の理解","questionText":"認知症初期集中支援チームに関する次の記述のうち， 最も適切なものを1 つ選びなさい。","choices":[{"id":"1","text":"自宅ではない場所で家族から生活の様子を聞く。"},{"id":"2","text":"チーム員には医師が含まれる。"},{"id":"3","text":"初回の訪問時にアセスメント（assessment）は不要である。"},{"id":"4","text":"介護福祉士は，認知症初期集中支援チーム員研修を受講しなくてもチームに参加できる。"},{"id":"5","text":"認知症疾患医療センター受診後に，チームが対応方法を決定する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！認知症初期集中支援チームには、専門医（医師）が含まれるんだ。1は、自宅で、本人や家族から、生活の様子を聞く。3は、初回訪問で、アセスメントを行う。4は、チーム員研修の受講が必要。5は、チームは、受診の前後にかかわらず、早期に対応するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-087","examYear":"2022","examRound":"34","questionNumber":87,"category":"障害の理解","questionText":"障害者の法的定義に関する次の記述のうち，正しいものを 1 つ選い。","choices":[{"id":"1","text":"身体障害者福祉法における身体障害者は，身体障害者手帳の交付を受けた 18歳以上のものをいう。"},{"id":"2","text":"知的障害者は，知的障害者福祉法に定義されている。"},{"id":"3","text":"「精神保健福祉法」における精神障害者には，知的障害者が含まれていない。"},{"id":"4","text":"障害者基本法において発達障害者は，精神障害者に含まれていない。"},{"id":"5","text":"障害児は，障害者基本法に定義されている。（注）「精神保健福祉法」とは，「精神保健及び精神障害者福祉に関する法律」のことである。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！身体障害者福祉法では、身体障害者は、身体障害者手帳の交付を受けた、18歳以上の人と定義されているんだ。2は、知的障害者福祉法には、知的障害の定義が、置かれていない。3は、精神保健福祉法の精神障害者には、知的障害者も含まれる。4は、障害者基本法では、発達障害者も、精神障害者に含まれる。5は、障害児の定義は、児童福祉法にあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-088","examYear":"2022","examRound":"34","questionNumber":88,"category":"障害の理解","questionText":"半側空間無視に関する次の記述のうち， 最も適切なものを 1 つ選い。","choices":[{"id":"1","text":"食事のとき，認識できない片側に食べ残しがみられる。"},{"id":"2","text":"半盲に対するものと介護方法は同じである。"},{"id":"3","text":"失行の 1 つである。"},{"id":"4","text":"本人は半側空間無視に気づいている。"},{"id":"5","text":"認識できない片側へ向かってまっすぐに歩ける。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！半側空間無視では、認識できない片側の食べ物を、残してしまうことがあるんだ。2は、半盲とは、原因も介護方法も、異なる。3は、失行ではなく、注意の障害。4は、本人が気づいていないことが多い。5は、無視している側には、まっすぐ歩きにくいよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-089","examYear":"2022","examRound":"34","questionNumber":89,"category":"障害の理解","questionText":"Ｄさん（35 歳，男性）は重度の知的障害があり，地元の施設入所支援を利用している。Ｄさんの友人Ｅさんは，以前に同じ施設入所支援を利用していて，現在は共同生活援助（グループホーム）で暮らしている。Ｄさんは，共同生活援助（グループホーム）で生活するＥさんの様子を見て，その生活に関心をもったようである。施設の 職員 は，Ｄさんの共同生活援助（グループホーム）での生活は，適切な援助を受ければ可能であると 考えている。一方，Ｄさんの母親は，親亡き後不安から施設入所支援を継続させたいと思っている。介護福祉職が現時点で 行うＤさんへの意思決定支援として， 最も適切なものを1 つ選びなさい。","choices":[{"id":"1","text":"母親の意思を，本人に伝える。"},{"id":"2","text":"共同生活援助（グループホーム）の生活について話し合う。"},{"id":"3","text":"介護福祉職の 考えを，本人に伝える。"},{"id":"4","text":"具体的な選択肢を用意し，選んでもらう。"},{"id":"5","text":"地域生活のリスクについて説明する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｄさんは、グループホームでの生活に、関心をもち始めているけれど、母親は、施設入所の継続を望んでいるんだね。まずは、Ｄさんと、グループホームでの生活について、話し合うことが、意思決定支援として、現時点で最も適切だよ。1、3は、周囲の意見を、押しつけることになる。4は、まだ、話し合いの前の段階。5は、リスクだけを伝えて、意欲を奪うんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-090","examYear":"2022","examRound":"34","questionNumber":90,"category":"障害の理解","questionText":"筋萎縮性側索硬化症（amyotrophic lateral sclerosis：ＡＬＳ）では 出現 しにくい 症状 として，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"四肢の運動障害"},{"id":"2","text":"構音障害"},{"id":"3","text":"嚥下障害"},{"id":"4","text":"感覚障害"},{"id":"5","text":"呼吸障害"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ＡＬＳは、運動神経が障害される病気で、感覚障害は、出現しにくいんだ。1の四肢の運動障害、2の構音障害、3の嚥下障害、5の呼吸障害は、進行とともに、みられる症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-091","examYear":"2022","examRound":"34","questionNumber":91,"category":"障害の理解","questionText":"Ｆさん（21 歳，男性）は，交通事故による頸髄損傷（cervical cord injury）で重度の四肢麻痺になった。最近はリハビリテーションに取り組まず，周囲の人感情 をぶつけ強くあたるようになった。介護福祉職の対応に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"歩けるようになるために， 諦めずに機能訓練をするように支援する。"},{"id":"2","text":"トラブルが起きないように，Ｆさんには近寄らないようにする。"},{"id":"3","text":"生活態度を 改めるように，Ｆさんに厳しく注意する。"},{"id":"4","text":"自分でできることに目を向けられるように，Ｆさんを支援する。"},{"id":"5","text":"障害 が重いので，Ｆさんのできることも手伝うようにする。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！頸髄損傷になったＦさんは、リハビリに取り組まず、周囲に強くあたるようになっているね。自分でできることに、目を向けられるように支援すると、気持ちが前向きになるよ。1は、歩けるようになるのは、困難。2は、避けると、孤立する。3は、厳しく注意しても、解決しない。5は、できることまで手伝うと、自立を妨げるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-092","examYear":"2022","examRound":"34","questionNumber":92,"category":"障害の理解","questionText":"Ｇさんはパーキンソン 病（Parkinson disease）と診断され，薬物療法が開始されている。立位で 重心が傾き，歩行中に停止することや向きを変が困難である。Ｇさんのこの 症状を表現 するものとして， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"安静時振戦"},{"id":"2","text":"筋固縮"},{"id":"3","text":"無動"},{"id":"4","text":"寡動"},{"id":"5","text":"姿勢保持障害"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！パーキンソン病で、立位で重心が傾いて、歩行中に止まったり、向きを変えたりするのが難しくなるのは、姿勢保持障害の症状なんだ。1の安静時振戦は、じっとしているときの震え、2の筋固縮は、筋肉がこわばる、3の無動と、4の寡動は、動きが少なく、遅くなる症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-093","examYear":"2022","examRound":"34","questionNumber":93,"category":"障害の理解","questionText":"障害者への理解を深めるために有効なアセスメントツールの 1 つであるエコマップが 表すものとして， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"家族との関係"},{"id":"2","text":"社会との相関関係"},{"id":"3","text":"認知機能"},{"id":"4","text":"機能の自立度"},{"id":"5","text":"日常生活動作"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！エコマップは、利用者と、家族、友人、地域、社会資源などとの、社会との相関関係を、図で表したものなんだ。1の家族との関係を表すのは、ジェノグラム。3、4、5は、認知機能や、自立度、ＡＤＬを評価するツールで、エコマップとは、ちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-094","examYear":"2022","examRound":"34","questionNumber":94,"category":"障害の理解","questionText":"「障害者総合支援法」で定める協議会に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"当事者・家族以外の専門家で構成する。"},{"id":"2","text":"療育手帳を交付する。"},{"id":"3","text":"相談支援専門員を配置しなければならない。"},{"id":"4","text":"国が設置する。"},{"id":"5","text":"地域の 実情 に応じた支援体制の整備について協議を 行う。（注）「障害者総合支援法」とは，「障害者の日常生活及び社会生活を総合的に支援するための法律」のことである。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！協議会は、地域の実情に応じた支援体制の整備について、協議を行う場なんだ。1は、当事者や家族も、参加する。2は、療育手帳の交付は、都道府県知事などが行う。3は、相談支援専門員の配置義務は、ない。4は、国ではなく、地方公共団体が設置するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-095","examYear":"2022","examRound":"34","questionNumber":95,"category":"障害の理解","questionText":"障害者が障害福祉サービスを利用するために相談支援専門員が作成する計画として，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"地域福祉計画"},{"id":"2","text":"個別支援計画"},{"id":"3","text":"サービス等利用計画"},{"id":"4","text":"障害福祉計画"},{"id":"5","text":"介護サービス計画"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！障害福祉サービスを利用するために、相談支援専門員が作成するのは、サービス等利用計画なんだ。1は、市町村が策定する。2は、サービス管理責任者が作成する。4は、市町村などが策定する。5は、介護支援専門員が作成する介護保険の計画だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-096","examYear":"2022","examRound":"34","questionNumber":96,"category":"障害の理解","questionText":"Ｈさん（45 歳，男性）は，脳梗塞（cerebral infarction）を発症して半年間入院した。退院してからは，障害者支援施設に入所して自立訓練を受けている。2か月ほど過ぎたが，右片麻痺と言語障害が残っている。妻のＪさん（35 歳）はパート勤務で，小学3年生の子どもがいて，将来が見えずに不安な気持ちである。家族に対する介護福祉職の支援として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族の不安な気持ちに寄り添い，今の課題を一緒に整理し 考えていく。"},{"id":"2","text":"Ｊさんの気持ちを最優先して方向性を決める。"},{"id":"3","text":"訓練の様子を伝えるために，頻繁にＪさんに施設に来てもらう。"},{"id":"4","text":"家族が困っているので専門職主導で方向性を決める。"},{"id":"5","text":"レスパイトケアを勧める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｈさんの妻のＪさんは、将来が見えずに、不安な気持ちなんだね。家族の不安な気持ちに寄り添って、今の課題を、一緒に整理して、考えていくことが、大切な支援だよ。2、4は、家族や専門職が、一方的に決める。3は、頻繁に来てもらうのは、負担になる。5は、レスパイトケアは、今の相談の目的とは、合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-097","examYear":"2022","examRound":"34","questionNumber":97,"category":"こころとからだのしくみ","questionText":"Ｋさん（83 歳，女性，要介護 1）は， 3 年前にアルツハイマー型認知症（dementia of the Alzheimerʼs type）と診断された。一人暮らしで訪問介護（ホームヘルプサービス）を利用している。金銭管理は困難であり， 長男が行っている。最近，認知症（dementia）の 症状 がさらに進み，訪問介護員（ホームヘルパー）がＫさんの自宅を訪問すると，「 通帳を長男 の嫁が持っていってしまった」と繰返し 訴えるようになった。考えられるＫさんの 症状 として，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"もの盗られ妄想"},{"id":"2","text":"心気妄想"},{"id":"3","text":"貧困妄想"},{"id":"4","text":"罪業妄想"},{"id":"5","text":"嫉妬妄想"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｋさんが、「通帳を長男の嫁が持っていってしまった」と繰り返し訴えるのは、身近な人が盗んだと思い込む、もの盗られ妄想なんだ。2は、病気だと思い込む、3は、お金がなくなると思い込む、4は、罪を犯したと思い込む、5は、配偶者の浮気を疑う妄想だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-098","examYear":"2022","examRound":"34","questionNumber":98,"category":"こころとからだのしくみ","questionText":"Ｌさん（87 歳，男性，要介護 1）は，冷房が嫌いで，部屋にエアコンはない。ある夏の日の午後，訪問介護員（ホームヘルパー）が訪問すると，厚手の布団を掛けて眠っていた。布団を取ると 大量 の発汗があり，体温を測定すると 38.5℃であった。朝から水分しか摂取していないという。前から不眠があり，この 5 日間便秘が続いていたが， 食欲 はあったとのことである。次のうち，体温が 上昇 した原因として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"布団"},{"id":"2","text":"発汗"},{"id":"3","text":"空腹"},{"id":"4","text":"不眠"},{"id":"5","text":"便秘"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｌさんは、夏の午後に、厚手の布団をかけて眠っていて、大量に汗をかき、体温が38.5℃だったんだね。厚い布団で熱がこもり、うつ熱が起こって、体温が上昇したと考えられるよ。2は、発汗は、体温を下げる反応。3、4、5は、体温の上昇の原因としては、関係が薄いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-099","examYear":"2022","examRound":"34","questionNumber":99,"category":"こころとからだのしくみ","questionText":"老化に 伴う視覚機能の変化に関する次の記述のうち，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"水晶体が茶色になる。"},{"id":"2","text":"遠くのものが見えやすくなる。"},{"id":"3","text":"明暗に 順応 する時間が長くなる。"},{"id":"4","text":"ピントの 調節 が速くなる。"},{"id":"5","text":"涙の 量が増える。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！老化に伴って、明るさに目が慣れる、明暗順応の時間が、長くなるんだ。1は、水晶体は、黄色く濁る。2は、近くのものが見えにくくなる（老眼）。4は、ピント調節は、遅くなる。5は、涙の量は、減るよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-100","examYear":"2022","examRound":"34","questionNumber":100,"category":"こころとからだのしくみ","questionText":"言葉の発音が不明瞭になる原因として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"唾液の分泌が増加すること"},{"id":"2","text":"舌運動が活発化すること"},{"id":"3","text":"口角が上がること"},{"id":"4","text":"調整 された義歯を使用すること"},{"id":"5","text":"口唇が閉じにくくなること"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！口唇が閉じにくくなると、パ行やマ行などの、唇を使う音が、はっきり出せなくなって、言葉の発音が不明瞭になるんだ。1は、唾液の分泌が増えても、発音は、不明瞭にならない。2は、舌の動きが活発なら、発音しやすい。4は、調整された義歯は、発音を助ける。3の口角の動きも、発音には関わるけれど、唇の閉鎖が、より直接的な原因だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-101","examYear":"2022","examRound":"34","questionNumber":101,"category":"こころとからだのしくみ","questionText":"骨に関する次の記述のうち，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"骨にはたんぱく質が含まれている。"},{"id":"2","text":"骨のカルシウム（Ca）は老化に 伴い増える。"},{"id":"3","text":"骨は負荷がかかるほうが弱くなる。"},{"id":"4","text":"骨は骨芽細胞によって壊される。"},{"id":"5","text":"骨のカルシウム（Ca）はビタミンＡ（vitamin A）によって 吸収 が促進される。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！骨には、コラーゲンなどの、たんぱく質が含まれているんだ。2は、骨のカルシウムは、老化に伴って、減る。3は、骨は、適度な負荷がかかると、強くなる。4は、骨は、破骨細胞によって壊される。5は、カルシウムの吸収を促進するのは、ビタミンＤだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-102","examYear":"2022","examRound":"34","questionNumber":102,"category":"こころとからだのしくみ","questionText":"介護者が効率的かつ安全に介護を 行うためのボディメカニクスの原則に関する次の記述のうち，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"支持基底面を広くする。"},{"id":"2","text":"利用者の 重心 を遠ざける。"},{"id":"3","text":"腰がねじれた姿勢をとる。"},{"id":"4","text":"重心 を高くする。"},{"id":"5","text":"移動時の摩擦面を大きくする。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ボディメカニクスでは、支持基底面を広くすると、安定して、安全に介護できるんだ。2は、利用者の重心は、近づける。3は、腰をねじらない。4は、重心は、低くする。5は、摩擦面は、小さくするんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-103","examYear":"2022","examRound":"34","questionNumber":103,"category":"こころとからだのしくみ","questionText":"次のうち，三大栄養素に該当する成分として，正しいものを 1 つ選い。","choices":[{"id":"1","text":"水分"},{"id":"2","text":"炭水化物"},{"id":"3","text":"ビタミン（vitamin）"},{"id":"4","text":"ナトリウム（Na）"},{"id":"5","text":"カルシウム（Ca）"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！三大栄養素は、炭水化物、たんぱく質、脂質の3つなんだ。1の水分、3のビタミン、4のナトリウム、5のカルシウムは、三大栄養素には、含まれないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-104","examYear":"2022","examRound":"34","questionNumber":104,"category":"こころとからだのしくみ","questionText":"コントロール不良の 糖尿 病（diabetes mellitus）で高血糖時にみられる症状 として，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"振戦"},{"id":"2","text":"発汗"},{"id":"3","text":"口渇"},{"id":"4","text":"乏尿"},{"id":"5","text":"動悸"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！コントロール不良の糖尿病で、高血糖のときは、血液の浸透圧が高くなって、口の渇き（口渇）が出るんだ。1の振戦、2の発汗、5の動悸は、低血糖のときの症状だよ。4は、高血糖のときは、乏尿ではなく、多尿になるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-105","examYear":"2022","examRound":"34","questionNumber":105,"category":"こころとからだのしくみ","questionText":"Ｍさん（85 歳，男性）は，通所介護（デイサービス）での 入浴 を楽ていて，いつも時間をかけて湯につかっている。ある時，介護福祉職が，「そろそろあがりましょうか」と声をかけると，浴槽から 急に立ち上た。Ｍさんがふらついた原因として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"体温の 上昇"},{"id":"2","text":"呼吸数の増加"},{"id":"3","text":"心拍数の増加"},{"id":"4","text":"動脈血酸素飽和度の低下"},{"id":"5","text":"血圧の低下"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！長く湯につかっていて、急に立ち上がると、血圧が下がって、ふらつく、起立性低血圧が起こることがあるんだ。1、2、3は、湯につかっていると起こる変化だけど、ふらつきの直接の原因ではない。4は、酸素飽和度の低下は、ふつうは起こらないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-106","examYear":"2022","examRound":"34","questionNumber":106,"category":"こころとからだのしくみ","questionText":"次のうち，ブリストル便性状スケールの普通便に該当するものとして，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"水様便"},{"id":"2","text":"硬い便"},{"id":"3","text":"泥状便"},{"id":"4","text":"コロコロ便"},{"id":"5","text":"やや軟らかい便"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！ブリストル便性状スケールは、便の形や硬さを、7段階に分けたもので、普通便は、やや軟らかい、なめらかな便に分類されるんだ。1の水様便と、3の泥状便は、下痢に近い便、2の硬い便と、4のコロコロ便は、便秘の便だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-107","examYear":"2022","examRound":"34","questionNumber":107,"category":"こころとからだのしくみ","questionText":"Ａさん（65 歳，女性）は，最近， 熟睡 できないと 訴えている。Ａさんの日常生活は，毎日6時に起床し，午前中は家事を 行い，14 時から 20 分の昼寝をし，16 時から 30 分の散歩をしている。食事は 朝食 7時， 昼食 12 時，夕食 18時にとり， 朝食 のときはコーヒーを 1 杯飲む。21 時に好きな音楽を聞きながら，夜食を満腹になる程度に食べ，21 時30 分に 就寝 している。Ａさんの 訴えに対して，日常生活で改善する必要があるものとして， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"朝食 のコーヒー"},{"id":"2","text":"昼寝"},{"id":"3","text":"散歩"},{"id":"4","text":"音楽を聞"},{"id":"5","text":"就寝前の夜食"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ａさんは、21時に、満腹になるまで夜食を食べているね。就寝前の夜食は、消化のために、眠りを浅くするので、改善が必要なんだ。1は、朝のコーヒー1杯なら、問題ない。2は、20分の昼寝は、適度。3は、散歩は、よい習慣。4は、音楽を聞くのは、リラックスに役立つよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-108","examYear":"2022","examRound":"34","questionNumber":108,"category":"こころとからだのしくみ","questionText":"Ｂさん（76 歳，女性）は，病気はなく散歩が日課である。肺がん（lungcancer）の 夫を長年介護し，数か月前に自宅で看取った。その体験から，死期の迫った段階では延命を目的とした治療は受けずに，自然な最期を迎えたいと願いる。Ｂさんが希望する死を表す用語として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"脳死"},{"id":"2","text":"突然死"},{"id":"3","text":"尊厳死"},{"id":"4","text":"積極的安楽死"},{"id":"5","text":"心臓死"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！死期が迫った段階で、延命を目的とした治療を受けずに、自然な最期を迎えたいと願うのは、尊厳死の考え方なんだ。1の脳死は、脳の機能が失われた状態、2の突然死は、予期せぬ死、4の積極的安楽死は、薬物などで、死期を早めること、5の心臓死は、心臓が止まる死のことだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-109","examYear":"2022","examRound":"34","questionNumber":109,"category":"医療的ケア","questionText":"社会福祉士及び介護福祉士法で規定されている介護福祉士が実施できる経管栄養の行為として，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"栄養剤の種類の変更"},{"id":"2","text":"栄養剤の注入速度の決定"},{"id":"3","text":"経鼻経管栄養チューブの胃内への留置"},{"id":"4","text":"栄養剤の 注入"},{"id":"5","text":"胃ろうカテーテルの定期交換"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！介護福祉士が、一定の条件のもとで実施できる経管栄養の行為は、栄養剤の注入なんだ。1の栄養剤の種類の変更や、2の注入速度の決定は、医師の指示にもとづく。3のチューブの留置や、5のカテーテルの定期交換は、医師や看護師が行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-110","examYear":"2022","examRound":"34","questionNumber":110,"category":"医療的ケア","questionText":"気管カニューレ内部の喀痰吸引で，指示された吸引時間よりも長た場合，吸引後に注意すべき項目として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"体温"},{"id":"2","text":"血糖値"},{"id":"3","text":"動脈血酸素飽和度"},{"id":"4","text":"痰の色"},{"id":"5","text":"唾液の 量"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！気管カニューレ内部の吸引を、指示された時間より長くしてしまうと、酸素不足になるおそれがあるんだ。だから、吸引後は、動脈血酸素飽和度を、注意して確認するよ。1の体温、2の血糖値、4の痰の色、5の唾液の量は、優先度が低いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-111","examYear":"2022","examRound":"34","questionNumber":111,"category":"医療的ケア","questionText":"呼吸器官の換気とガス交換に関する次の記述のうち， 最も適切なものを1 つ選びなさい。","choices":[{"id":"1","text":"換気とは，体外から二酸化炭素を取り込み，体外に酸素を 排出 する 働きをいう。"},{"id":"2","text":"呼吸運動は，主として大胸筋によって 行われる。"},{"id":"3","text":"1 回に吸い込める空気の 量は，年齢とともに増加する。"},{"id":"4","text":"ガス交換は，肺胞内の空気と血液の 間で 行われる。"},{"id":"5","text":"筋萎縮性側索硬化症（amyotrophic lateral sclerosis：ＡＬＳ）では，主にガス交換の 働きが低下する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ガス交換は、肺胞内の空気と、血液の間で、酸素と二酸化炭素を、交換することなんだ。1は、換気は、酸素を取り込み、二酸化炭素を排出する働き。2は、呼吸運動は、主に横隔膜や、肋間筋で行われる。3は、1回に吸い込める空気の量は、年齢とともに、減少する。5は、ＡＬＳでは、呼吸筋が弱り、換気の働きが低下するよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-112","examYear":"2022","examRound":"34","questionNumber":112,"category":"医療的ケア","questionText":"経管栄養で用いる半固形タイプの栄養剤の 特徴 に関する次の記述のうち，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"経鼻経管栄養法に適している。"},{"id":"2","text":"液状 タイプと同じ粘稠度である。"},{"id":"3","text":"食道 への 逆流 を改善することが期待できる。"},{"id":"4","text":"仰臥位（背臥位）で 注入 する。"},{"id":"5","text":"注入時間は， 液状 タイプより長い。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！半固形タイプの栄養剤は、とろみがあって、胃の中でとどまりやすいから、食道への逆流を、改善することが期待できるんだ。1は、胃ろうに適している。2は、液状より、粘稠度が高い。4は、上半身を起こして注入する。5は、液状より、注入時間が短いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-113","examYear":"2022","examRound":"34","questionNumber":113,"category":"医療的ケア","questionText":"経管栄養で，栄養剤の注入後に白湯を経管栄養チューブに 注入 する理由として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"チューブ内を 消毒 する。"},{"id":"2","text":"チューブ内の栄養剤を洗い流す。"},{"id":"3","text":"水分を補給する。"},{"id":"4","text":"胃内を 温める。"},{"id":"5","text":"栄養剤の濃度を調節する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！栄養剤の注入後に、白湯を注入するのは、チューブ内の栄養剤を洗い流して、詰まりや、細菌の繁殖を防ぐためなんだ。1は、消毒が目的ではない。3は、水分補給は、別の目的。4、5は、白湯の主な目的ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-114","examYear":"2022","examRound":"34","questionNumber":114,"category":"総合問題","questionText":"次の事例を読んで，問題 114 から問題 116 までについて答えなさい。〔事例〕Ｃさん（83 歳，女性）は，一人暮らしで，近所に買い物に行く以外はテレビを見過ごしている。近県に息子がいるが，仕事が 忙しく，会いに来かった。ある日，息子が久しぶりに訪問すると，部屋の中がごみや衣類などで散た。病院を受診するとＣさんはアルツハイマー型認知症（dementia of the Alzheimerʼstype）と診断され，要介護 1 と認定された。Ｃさんは，時々，電気湯沸しポットの使い方がわからなくなって湯が出り，お茶を入れる 順番 がわからずに混乱する様子が見られた。心配した息子は，介護保険サービスを利用することにした。後日，介護支援専門員（ケアマネジャー）が訪問し，介護保険サービスの利用についてＣさんや息子と話合った。週2 回，訪問介護（ホームヘルプサービス）を利用することになり，介護支援専門員（ケアマネジャー）は，「自宅で，衛生的な生活ができる」をケアプランの長期目標とした。Ｃさんを担当する訪問介護員（ホームヘルパー）は，サービス提供責任者と共に訪問介護計画書を作成することになった。次の記述の中で，短期目標として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"掃除機を利用して， 1人で掃除をすることができるようになる。"},{"id":"2","text":"電気湯沸しポットを使い，1人でお茶を入れることができるようになる。"},{"id":"3","text":"Ｃさんの残存機能に着目して支援する。"},{"id":"4","text":"週2回，息子にＣさんの自宅を訪問してもらう。"},{"id":"5","text":"訪問介護員（ホームヘルパー）と一緒に掃除をすることができるようになる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！長期目標は、「自宅で、衛生的な生活ができる」だったね。短期目標は、この長期目標につながる、具体的な内容にするんだ。訪問介護員と一緒に掃除をすることができるようになる、が最も適切だよ。1は、Ｃさんの現在の状態では、一人での掃除は、難しい。2は、掃除とは別の課題。3、4は、目標ではなく、支援の内容だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-115","examYear":"2022","examRound":"34","questionNumber":115,"category":"総合問題","questionText":"次の事例を読んで，問題 114 から問題 116 までについて答えなさい。〔事例〕Ｃさん（83 歳，女性）は，一人暮らしで，近所に買い物に行く以外はテレビを見過ごしている。近県に息子がいるが，仕事が 忙しく，会いに来かった。ある日，息子が久しぶりに訪問すると，部屋の中がごみや衣類などで散た。病院を受診するとＣさんはアルツハイマー型認知症（dementia of the Alzheimerʼstype）と診断され，要介護 1 と認定された。Ｃさんは，時々，電気湯沸しポットの使い方がわからなくなって湯が出り，お茶を入れる 順番 がわからずに混乱する様子が見られた。心配した息子は，介護保険サービスを利用することにした。後日，介護支援専門員（ケアマネジャー）が訪問し，介護保険サービスの利用についてＣさんや息子と話合った。週2 回，訪問介護（ホームヘルプサービス）を利用することになり，介護支援専門員（ケアマネジャー）は，「自宅で，衛生的な生活ができる」をケアプランの長期目標とした。Ｃさんは，たびたび息子に電気湯沸しポットが壊れていると 訴になった。Ｃさんのこのような 状態 に該当するものとして，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"空間認知障害"},{"id":"2","text":"視覚認知障害"},{"id":"3","text":"遂行機能障害"},{"id":"4","text":"失認"},{"id":"5","text":"観念運動失行"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｃさんは、電気湯沸しポットの使い方がわからず、お茶を入れる順番も、わからなくなって、混乱していたんだね。これは、手順を考えて、順序立てて行う、遂行機能障害にあたるよ。1は、空間の認識、2は、視覚的な情報の認識、4は、見えるものの意味がわからない、5は、指示された動作ができない症状で、事例の状態とは、ちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-116","examYear":"2022","examRound":"34","questionNumber":116,"category":"総合問題","questionText":"次の事例を読んで，問題 114 から問題 116 までについて答えなさい。〔事例〕Ｃさん（83 歳，女性）は，一人暮らしで，近所に買い物に行く以外はテレビを見過ごしている。近県に息子がいるが，仕事が 忙しく，会いに来かった。ある日，息子が久しぶりに訪問すると，部屋の中がごみや衣類などで散た。病院を受診するとＣさんはアルツハイマー型認知症（dementia of the Alzheimerʼstype）と診断され，要介護 1 と認定された。Ｃさんは，時々，電気湯沸しポットの使い方がわからなくなって湯が出り，お茶を入れる 順番 がわからずに混乱する様子が見られた。心配した息子は，介護保険サービスを利用することにした。後日，介護支援専門員（ケアマネジャー）が訪問し，介護保険サービスの利用についてＣさんや息子と話合った。週2 回，訪問介護（ホームヘルプサービス）を利用することになり，介護支援専門員（ケアマネジャー）は，「自宅で，衛生的な生活ができる」をケアプランの長期目標とした。Ｃさんの家に訪問介護員（ホームヘルパー）が通い始めて数か月が経過した頃，Ｃさんの息子から訪問介護員（ホームヘルパー）に以下の希望が挙げられた。介護保険で対応可能な支援として，適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"Ｃさんと息子が出かけている 間に洗濯物を取り込む。"},{"id":"2","text":"Ｃさんの処方薬を 薬局 で受け取る。"},{"id":"3","text":"地域のお祭りにＣさんと一緒に行く。"},{"id":"4","text":"Ｃさんの部屋の壁紙を張り替える。"},{"id":"5","text":"訪ねて来た親戚にお茶を入れる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護保険の訪問介護では、生活援助として、薬の受け取りなど、日常生活に必要な支援が認められているんだ。1は、利用者が不在の間の洗濯物の取り込みは、対象外。3は、お祭りへの同行は、日常生活の援助の範囲外。4は、壁紙の張り替えは、専門業者の仕事。5は、来客へのお茶出しは、利用者以外への支援で、対象外だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-117","examYear":"2022","examRound":"34","questionNumber":117,"category":"総合問題","questionText":"次の事例を読んで，問題 117 から問題 119 までについて答えなさい。〔事例〕Ｄさん（70 歳，男性）は，19 歳のときに統合失調症（schizophrenia）を 発症 し，入退院を繰り返しながら両親 と一緒に生活してきた。 両親 が亡きっかけとして不安に襲われ，妄想や 幻聴の症状 が強く 現れるようになった。そのため，兄に付き添われて精神科病院を受診し，医療保護入院となった。現在は， 入院 から 3 年が経過し， 陽性 症 状 はほとんどなく， 病棟で日中 はレクリエーションに参加するなど落ち着いて生活している。\nＤさんが 3 年前に 入院 した医療保護入院の制度に関する次の記述のうち，正しいものを 1 つ選びなさい。","choices":[{"id":"1","text":"Ｄさんの同意による 入院"},{"id":"2","text":"精神保健指定医 2 名以上の診察の結果が， 入院 させなければ自傷他害の恐あると一致した場合の 入院"},{"id":"3","text":"精神保健指定医 1 名が診察し， 入院 させなければ自傷他害の恐れがあると判断した場合，72 時間以内に制限した 入院"},{"id":"4","text":"精神保健指定医 1 名が診察し，Ｄさんの同意が得られず，家族等 1 名の同意がある 入院"},{"id":"5","text":"精神保健指定医 1 名が診察し，Ｄさんの同意が得られず，さらに家族等の同意が得られないため 72 時間以内に制限した 入院"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！医療保護入院は、精神保健指定医が診察して、入院が必要と判断し、本人の同意が得られなくても、家族等の同意があれば、入院できる制度なんだ。1は、本人の同意による任意入院。2は、措置入院（指定医2名以上）。3は、応急入院、5は、応急入院の説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-118","examYear":"2022","examRound":"34","questionNumber":118,"category":"総合問題","questionText":"次の事例を読んで，問題 117 から問題 119 までについて答えなさい。〔事例〕Ｄさん（70 歳，男性）は，19 歳のときに統合失調症（schizophrenia）を 発症 し，入退院を繰り返しながら両親 と一緒に生活してきた。 両親 が亡きっかけとして不安に襲われ，妄想や 幻聴の症状 が強く 現れるようになった。そのため，兄に付き添われて精神科病院を受診し，医療保護入院となった。現在は， 入院 から 3 年が経過し， 陽性 症 状 はほとんどなく， 病棟で日中 はレクリエーションに参加するなど落ち着いて生活している。\n1年前からＤさんの退院について検討が 行われてきた。Ｄさんは退院後の生活に対する不安があり，「帰る家がない」，「顔見知りの患者や 職員 がいるのでここを離れたくない」と退院には 消極 的 であった。しかし，Ｄさんと仲のよい患者が，退院し施設入所したことをきっかけに退院を 考えるようになった。Ｄさんは，整容，入浴，排泄，食事，移動は見守りがあればできる。また，介護福祉職の助言を受ければ，日用品などを買うことはできる。 経済 状 況 は， 障害基礎年金 2 級と生活保護を 受給 している。要介護認定を受けたところ，要介護 1と認定された。Ｄさんの退院先の候補になる施設として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"養護老人ホーム"},{"id":"2","text":"老人福祉センター"},{"id":"3","text":"更生施設"},{"id":"4","text":"地域生活定着支援センター"},{"id":"5","text":"介護老人福祉施設"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｄさんは、70歳で、統合失調症があり、要介護1で、障害基礎年金と生活保護を受けているんだね。環境上、経済的理由で、自宅での生活が難しい高齢者が入所する、養護老人ホームが、退院先の候補として最も適切だよ。2の老人福祉センターは、通う施設、3の更生施設は、保護施設だけれど、生活訓練が目的、4は、刑事施設を出た人の支援、5は、要介護3以上が原則だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-119","examYear":"2022","examRound":"34","questionNumber":119,"category":"総合問題","questionText":"次の事例を読んで，問題 117 から問題 119 までについて答えなさい。〔事例〕Ｄさん（70 歳，男性）は，19 歳のときに統合失調症（schizophrenia）を 発症 し，入退院を繰り返しながら両親 と一緒に生活してきた。 両親 が亡きっかけとして不安に襲われ，妄想や 幻聴の症状 が強く 現れるようになった。そのため，兄に付き添われて精神科病院を受診し，医療保護入院となった。現在は， 入院 から 3 年が経過し， 陽性 症 状 はほとんどなく， 病棟で日中 はレクリエーションに参加するなど落ち着いて生活している。\nＤさんは施設への入所が決まり，うれしそうに退院の準備をするようになった。ある夜， 1人で荷物の整理をしていたときに転んでしまい，顔を強打して大きなあざができた。後遺症はないことがわかったが，Ｄさんは自信をなくし，介護福祉職に，「これでは施設も自分を受け入れてくれないだろう」と言い，「施設入所がうれしくて早く準備がしたかった」と話した。そばに寄り添い，Ｄさんの 話を聴き終えた介護福祉職が，「施設入所がうれしくて，早く準備をしたかったのですね」と言うと，Ｄさんは，「退院を 諦ど，自分にも暮らせる場所があると思った」とやりたいことや夢を語り出した。介護福祉職が 行ったコミュニケーション技術として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"あいづち"},{"id":"2","text":"言い換"},{"id":"3","text":"要約"},{"id":"4","text":"繰り返"},{"id":"5","text":"閉じられた質問29（"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！介護福祉職は、Ｄさんの、「施設入所がうれしくて、早く準備をしたかった」という言葉を、そのまま繰り返して、気持ちを受け止めているよね。これが、繰り返しの技術なんだ。すると、Ｄさんは、やりたいことや夢を、語り出したよ。1はあいづち、2は言い換え、3は要約、5は閉じられた質問で、ここでの対応とは、ちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-120","examYear":"2022","examRound":"34","questionNumber":120,"category":"総合問題","questionText":"次の事例を読んで，問題 120 から問題 122 までについて答えなさい。〔事例〕Ｅ さ ん（35 歳， 男性）は， 1 年前に筋萎縮性側索硬化症（amyotrophic lateralsclerosis：ＡＬＳ）と診断された。当初の 症状 としては，ろれつが回らず，食べ物の飲み込みが悪くなり， 体重の減少 がみられた。その後，Ｅさんの 症状 は進行し，同居している両親から介護を受けて生活をしていたが， 両親の介護負担が大きくなったため，障害福祉サービスを利用することになった。障害支援区分の認定を受けたところ，障害支援区分 3 になった。Ｅさんは訪問介護員（ホームヘルパー）から食事や 入浴 の介護を受けて自宅で生活をしている。\nＥさんが病院を受診するきっかけになった 症状 に該当するものとして，最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"対麻痺"},{"id":"2","text":"単麻痺"},{"id":"3","text":"球麻痺"},{"id":"4","text":"安静時振戦"},{"id":"5","text":"間欠性跛行"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ＡＬＳの初期症状の、ろれつが回らない、飲み込みが悪いのは、延髄の運動神経が障害される、球麻痺の症状なんだ。1の対麻痺は、両下肢の麻痺、2の単麻痺は、片方の手足の麻痺、4の安静時振戦は、パーキンソン病、5の間欠性跛行は、脊柱管狭窄症の症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-121","examYear":"2022","examRound":"34","questionNumber":121,"category":"総合問題","questionText":"次の事例を読んで，問題 120 から問題 122 までについて答えなさい。〔事例〕Ｅ さ ん（35 歳， 男性）は， 1 年前に筋萎縮性側索硬化症（amyotrophic lateralsclerosis：ＡＬＳ）と診断された。当初の 症状 としては，ろれつが回らず，食べ物の飲み込みが悪くなり， 体重の減少 がみられた。その後，Ｅさんの 症状 は進行し，同居している両親から介護を受けて生活をしていたが， 両親の介護負担が大きくなったため，障害福祉サービスを利用することになった。障害支援区分の認定を受けたところ，障害支援区分 3 になった。Ｅさんは訪問介護員（ホームヘルパー）から食事や 入浴 の介護を受けて自宅で生活をしている。\nある日，Ｅさんの自宅を訪問した訪問介護員（ホームヘルパー）は，Ｅさんの 両親 から，「これまでＥは 話をするのが 難しく，筆談で意思を聞いてきたが，ペンを持つのが 難しくなってきた」と聞いた。確かにＥさんは，発話や字を書とは困難な様子だが，目はよく動いている。次のうち，今後，Ｅさんが家族とコミュニケーションをとるときに使きる道具として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"ホワイトボード"},{"id":"2","text":"絵や写真"},{"id":"3","text":"透明文字盤"},{"id":"4","text":"拡声器"},{"id":"5","text":"補聴器"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｅさんは、話すことも、字を書くことも難しいけれど、目はよく動いているんだね。透明文字盤なら、目の動きで、文字を伝えられるから、コミュニケーションの道具として、最も適切だよ。1のホワイトボードは、書く動作が必要、2の絵や写真は、細かい意思を伝えられない、4の拡声器と、5の補聴器は、聴覚の道具で、Ｅさんの困りごとには、合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-122","examYear":"2022","examRound":"34","questionNumber":122,"category":"総合問題","questionText":"次の事例を読んで，問題 120 から問題 122 までについて答えなさい。〔事例〕Ｅ さ ん（35 歳， 男性）は， 1 年前に筋萎縮性側索硬化症（amyotrophic lateralsclerosis：ＡＬＳ）と診断された。当初の 症状 としては，ろれつが回らず，食べ物の飲み込みが悪くなり， 体重の減少 がみられた。その後，Ｅさんの 症状 は進行し，同居している両親から介護を受けて生活をしていたが， 両親の介護負担が大きくなったため，障害福祉サービスを利用することになった。障害支援区分の認定を受けたところ，障害支援区分 3 になった。Ｅさんは訪問介護員（ホームヘルパー）から食事や 入浴 の介護を受けて自宅で生活をしている。\n3年後，Ｅさんの 症状 はさらに進行し，障害支援区分 6 になった。Ｅさんはこれまでどおり，自宅での生活を希望し，Ｅさんの 両親 は障害福祉サービスを利用しながら最期まで自宅でＥさんの介護を 行うことを希望している。Ｅさんと 両親 の希望の実現に向けて，現在の 状態 からＥさんが利用するサービスとして， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"育成医療"},{"id":"2","text":"就労定着支援"},{"id":"3","text":"共同生活援助（グループホーム）"},{"id":"4","text":"行動援護"},{"id":"5","text":"重度訪問介護"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害支援区分6になったＥさんが、自宅での生活を続けるには、重度訪問介護が、最も適切なんだ。重度の肢体不自由がある人に、長時間の見守りや、介護を提供できるよ。1の育成医療は、子どもの医療、2の就労定着支援は、働く人の支援、3のグループホームは、自宅での生活の希望に合わない、4の行動援護は、知的障害や精神障害向けだよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":false},{"id":"2022-34-123","examYear":"2022","examRound":"34","questionNumber":123,"category":"総合問題","questionText":"次の事例を読んで，問題 123 から問題 125 までについて答えなさい。〔事例〕Ｆさん（50 歳，女性，障害支援区分 5）は，アテトーゼ型（athetosis）の脳性麻痺（cerebral palsy）による四肢・体幹機能障害がある。居宅介護を利用し， 入浴 の支援を受けながら母親（79 歳）と暮らしていた。Ｆさんは障害基礎年金 1 級を 受給 していて，Ｆさん名義の貯蓄がある。金銭管理は母親が 行っていた。Ｆさんは， 3 年前に誤嚥性肺炎（aspiration pneumonia）で 入院 したことがある。言語障害があり，慣れた人でないと言葉が聞き取りにくい。自宅では 車いすに乗り，足で床を蹴って移動し，屋外は母親が 車いすを押していた。Ｆさんは自宅内の移動以外の日常生活については，母親から全面的に介護を受けて生活していた。最近，日中活動の場と短期入所（ショートステイ）の利用について，市の障害福祉課に相談するようになった。ところが，母親が持病の心疾患（heart disease）で亡くなり，市の障害福祉課がＦさんと当面の生活について検討することになった。Ｆさんは 1人で生活することは 難しいと思い，施設入所を希望している。\nＦさんの脳性麻痺（cerebral palsy）の 特徴 に関する次の記述のうち， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"強い筋緊張から，四肢の突っ張りが強い。"},{"id":"2","text":"不随意運動が 生じて，運動コントロールが困難になる。"},{"id":"3","text":"文字の読みの不正確さがあり，読んだ内容を理解しにくい。"},{"id":"4","text":"動作は緩慢で， 表情 が乏しくなる。"},{"id":"5","text":"着衣失行が 生じる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！アテトーゼ型の脳性麻痺は、意思とは関係なく体が動く、不随意運動が起きて、運動のコントロールが、難しくなるのが特徴なんだ。1は、痙直型の特徴、3は、学習障害（読字障害）、4は、パーキンソン病、5は、高次脳機能障害（失行）の症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-124","examYear":"2022","examRound":"34","questionNumber":124,"category":"総合問題","questionText":"次の事例を読んで，問題 123 から問題 125 までについて答えなさい。〔事例〕Ｆさん（50 歳，女性，障害支援区分 5）は，アテトーゼ型（athetosis）の脳性麻痺（cerebral palsy）による四肢・体幹機能障害がある。居宅介護を利用し， 入浴 の支援を受けながら母親（79 歳）と暮らしていた。Ｆさんは障害基礎年金 1 級を 受給 していて，Ｆさん名義の貯蓄がある。金銭管理は母親が 行っていた。Ｆさんは， 3 年前に誤嚥性肺炎（aspiration pneumonia）で 入院 したことがある。言語障害があり，慣れた人でないと言葉が聞き取りにくい。自宅では 車いすに乗り，足で床を蹴って移動し，屋外は母親が 車いすを押していた。Ｆさんは自宅内の移動以外の日常生活については，母親から全面的に介護を受けて生活していた。最近，日中活動の場と短期入所（ショートステイ）の利用について，市の障害福祉課に相談するようになった。ところが，母親が持病の心疾患（heart disease）で亡くなり，市の障害福祉課がＦさんと当面の生活について検討することになった。Ｆさんは 1人で生活することは 難しいと思い，施設入所を希望している。\nＦさんは，障害者支援施設に入所 できることになり，アセスメント（assessment）が 行われた。相談支援専門員は，Ｆさんの希望をもとに，これまでの 生活 状 況 と身体の様子等から，もう少し本人にできることがあるのではないかと 考え，「障害者支援施設で施設入所支援と生活介護を利用しながら， 将来の生活を 考える」という方針を立てた。また，長期目標を，「自分に適した介護を受けながら，様々な生活経験を積む」とした。Ｆさんの短期目標として， 最も適切なものを 1 つ選びなさい。","choices":[{"id":"1","text":"入浴時に自分でからだを洗えるようになる。"},{"id":"2","text":"毎日字を書く 練習を行い，筆談で会話ができるようになる。"},{"id":"3","text":"施設内は， 車いす介助を受けながら安全に移動する。"},{"id":"4","text":"経管栄養で食事がとれるようになる。"},{"id":"5","text":"日中活動として 外出 や興味のあるグループ活動に参加する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！長期目標は、「自分に適した介護を受けながら、様々な生活経験を積む」だね。日中活動として、外出や、興味のあるグループ活動に参加することが、生活経験を積む、短期目標として最も適切だよ。1、2は、Ｆさんの障害の状態から、現実的ではない。3は、現状維持で、経験を積む目標ではない。4は、経管栄養は、必要な状態ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2022-34-125","examYear":"2022","examRound":"34","questionNumber":125,"category":"総合問題","questionText":"次の事例を読んで，問題 123 から問題 125 までについて答えなさい。〔事例〕Ｆさん（50 歳，女性，障害支援区分 5）は，アテトーゼ型（athetosis）の脳性麻痺（cerebral palsy）による四肢・体幹機能障害がある。居宅介護を利用し， 入浴 の支援を受けながら母親（79 歳）と暮らしていた。Ｆさんは障害基礎年金 1 級を 受給 していて，Ｆさん名義の貯蓄がある。金銭管理は母親が 行っていた。Ｆさんは， 3 年前に誤嚥性肺炎（aspiration pneumonia）で 入院 したことがある。言語障害があり，慣れた人でないと言葉が聞き取りにくい。自宅では 車いすに乗り，足で床を蹴って移動し，屋外は母親が 車いすを押していた。Ｆさんは自宅内の移動以外の日常生活については，母親から全面的に介護を受けて生活していた。最近，日中活動の場と短期入所（ショートステイ）の利用について，市の障害福祉課に相談するようになった。ところが，母親が持病の心疾患（heart disease）で亡くなり，市の障害福祉課がＦさんと当面の生活について検討することになった。Ｆさんは 1人で生活することは 難しいと思い，施設入所を希望している。\n入所 してから 3 か月が経ち，支援の見直しが 行われた。Ｆさんは施設生活にも慣れ，相談できる人も増えている。また，「自分でお小遣いを使えるようになりたい」と言い，外出時に必要なお金を介護福祉職と一緒に 考えるようになった。 将来 の地域生活を 考えて，社会福祉協議会の金銭管理に切替えることが検討された。Ｆさんが活用できる社会福祉協議会が 行う金銭管理として， 最も適切なものを1 つ選びなさい。","choices":[{"id":"1","text":"日常生活自立支援事業"},{"id":"2","text":"生活福祉資金"},{"id":"3","text":"自立訓練"},{"id":"4","text":"生活困窮者家計改善支援事業"},{"id":"5","text":"自発的活動支援事業"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！日常生活自立支援事業は、社会福祉協議会が行っていて、判断能力が十分でない人などの、日常的な金銭管理を、支援するんだ。Ｆさんの、お小遣いを使えるようになりたいという希望に、ぴったりだよ。2の生活福祉資金は、貸付制度、3の自立訓練は、障害福祉サービス、4の家計改善支援事業は、生活困窮者向け、5の自発的活動支援事業は、障害者の地域活動を支援する事業だよ。","source":"公益財団法人 社会福祉振興・試験センター 第34回（令和3年度）介護福祉士国家試験; 問題: ユーザー提供PDF; 正答: https://www.mhlw.go.jp/content/12004000/000917101.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-001","examYear":"2021","examRound":"33","questionNumber":1,"category":"人間の尊厳と自立","questionText":"人権や福祉の考え方に影響を与えた人物に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"リッチモンド（Richmond, M.）は、『ソーシャル・ケース・ワークとは何か』をまとめ、現在の社会福祉、介護福祉に影響を及ぼした。"},{"id":"2","text":"フロイト（Freud, S.）がまとめた『種の起源』の考え方は、後の「優生思想」につながった。"},{"id":"3","text":"マルサス（Malthus, T.）は、人間の無意識の研究を行って、『精神分析学入門』をまとめた。"},{"id":"4","text":"ヘレン・ケラー（Keller, H.）は、『看護覚え書』の中で「療養上の世話」を看護の役割として示した。"},{"id":"5","text":"ダーウィン（Darwin, C.）は、『人口論』の中で貧困原因を個人の人格の問題とした。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！リッチモンドは、『ソーシャル・ケース・ワークとは何か』をまとめて、ケースワークの基礎を築き、社会福祉や介護福祉にも影響を与えた人物なんだ。2は、フロイトではなく、ダーウィンが『種の起源』を著したよ。3は、マルサスではなく、フロイトが精神分析学を築いた。4は、ヘレン・ケラーではなく、ナイチンゲールが『看護覚え書』を書いた。5は、ダーウィンではなく、マルサスが『人口論』を著したんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-002","examYear":"2021","examRound":"33","questionNumber":2,"category":"人間の尊厳と自立","questionText":"自宅で生活しているＡさん（87歳、男性、要介護3）は、7年前に脳梗塞（cerebral infarction）で左片麻痺（ひだりかたまひ）となり、訪問介護（ホームヘルプサービス）を利用していた。Ａさんは食べることを楽しみにしていたが、最近、食事中にむせることが多くなり、誤嚥（ごえん）を繰り返していた。誤嚥（ごえん）による緊急搬送の後、医師は妻に、「今後も自宅で生活を続けるならば、胃ろうを勧める」と話した。妻は仕方がないと諦めていたが、別に暮らしている長男は胃ろうの造設について納得していなかった。長男が実家を訪れるたびに、Ａさんの今後の生活をめぐって口論が繰り返されていた。妻は訪問介護員（ホームヘルパー）にどうしたらよいか相談した。介護福祉職の職業倫理に基づく対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「医療的なことについては発言できません」"},{"id":"2","text":"「医師の判断なら、それに従うのが良いと思います」"},{"id":"3","text":"「Ａさん自身は、どのようにお考えなのでしょうか」"},{"id":"4","text":"「息子さんの気持ちより、一緒に暮らす奥さんの気持ちが優先されますよ」"},{"id":"5","text":"「息子さんと一緒に、医師の話を聞きに行ってみてください」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！胃ろうをめぐって家族の意見が分かれているけれど、いちばん大切なのは、Ａさん自身の思いなんだ。まず、本人の考えを確認する視点が、介護福祉職の職業倫理にかなっているよ。1は発言を避けているだけ、2は医師任せ、4は妻の気持ちを優先していて、5は話を聞きに行くだけで、本人の意思を確認する視点が抜けているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-003","examYear":"2021","examRound":"33","questionNumber":3,"category":"人間関係とコミュニケーション","questionText":"人間関係における役割葛藤の例として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"就労継続支援Ｂ型の利用者が、生活支援員の期待に応えようとして作業態度をまねる。"},{"id":"2","text":"家族介護者が、仕事と介護の両立への期待に応えられるかどうか悩む。"},{"id":"3","text":"通所介護（デイサービス）の利用者が、レクリエーションを楽しんでいる利用者の役を演じる。"},{"id":"4","text":"就労移行支援の利用者が、採用面接の模擬訓練中にふざけて冗談を言ってしまう。"},{"id":"5","text":"高齢者が、家事を行う家族に代わり、孫の遊び相手の役割を担う。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！役割葛藤は、一人の人が持つ複数の役割（この場合は、仕事をする人と介護をする人）の間で、板挟みになって悩むことなんだ。1、3は、他人の役割をまねたり演じたりする役割演技。4は、役割から外れた行動。5は、新しい役割を引き受けることで、葛藤とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-004","examYear":"2021","examRound":"33","questionNumber":4,"category":"人間関係とコミュニケーション","questionText":"Ｂさん（80歳、男性）は、訪問介護（ホームヘルプサービス）を利用しながら自宅で一人暮らしをしている。最近、自宅で転倒してから、一人で生活をしていくことに不安を持つこともある。訪問介護員（ホームヘルパー）がＢさんに、「お一人での生活は大丈夫ですか。何か困っていることはありませんか」と尋ねたところ、Ｂさんは、「大丈夫」と不安そうな表情で答えた。Ｂさんが伝えようとしたメッセージに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"言語メッセージと同じ内容を非言語メッセージで強調している。"},{"id":"2","text":"言語で伝えた内容を非言語メッセージで補強している。"},{"id":"3","text":"言語の代わりに非言語だけを用いてメッセージを伝えている。"},{"id":"4","text":"言語メッセージと矛盾する内容を非言語メッセージで伝えている。"},{"id":"5","text":"非言語メッセージを用いて言葉の流れを調整している。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｂさんは、「大丈夫」という言葉（言語メッセージ）と、不安そうな表情（非言語メッセージ）が、食い違っているよね。言葉と裏腹な気持ちが、表情に表れている状態なんだ。1は同じ内容を強調、2は補強、3は非言語だけ、5は言葉の流れの調整で、この場面の説明としては合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-005","examYear":"2021","examRound":"33","questionNumber":5,"category":"社会の理解","questionText":"家族の変容に関する2015年（平成27年）以降の動向として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"1世帯当たりの人数は、全国平均で3.5人を超えている。"},{"id":"2","text":"核家族の中で、「ひとり親と未婚の子」の世帯が増加している。"},{"id":"3","text":"50歳時の未婚割合は、男性よりも女性のほうが高い。"},{"id":"4","text":"65歳以上の人がいる世帯では、単独世帯が最も多い。"},{"id":"5","text":"結婚して20年以上の夫婦の離婚は、減少している。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！2015年以降、核家族の中でも、ひとり親と未婚の子どもの世帯が増えているんだ。1は、1世帯あたりの人数は2.5人程度で、3.5人には届かない。3は、未婚割合は男性のほうが高い。4は、65歳以上のいる世帯で最も多いのは夫婦のみの世帯。5は、熟年離婚は増加傾向にあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-006","examYear":"2021","examRound":"33","questionNumber":6,"category":"社会の理解","questionText":"次のうち、セルフヘルプグループ（self-help group）に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"町内会"},{"id":"2","text":"学生自治会"},{"id":"3","text":"患者会"},{"id":"4","text":"専門職団体"},{"id":"5","text":"ボランティア団体"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！セルフヘルプグループは、同じ病気や悩みを持つ当事者が、体験を語り合い、支え合う集まりで、患者会がその代表例なんだ。1の町内会、2の学生自治会、5のボランティア団体は、当事者の集まりではない。4の専門職団体は、専門家の集まりで、当事者組織ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-007","examYear":"2021","examRound":"33","questionNumber":7,"category":"社会の理解","questionText":"次のうち、福祉三法に続いて制定され、福祉六法に含まれるようになった法律として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"社会福祉法"},{"id":"2","text":"地域保健法"},{"id":"3","text":"介護保険法"},{"id":"4","text":"老人福祉法"},{"id":"5","text":"障害者基本法"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！福祉三法（生活保護法、児童福祉法、身体障害者福祉法）に続いて、老人福祉法、知的障害者福祉法、母子福祉法が加わり、福祉六法になったんだ。1の社会福祉法、2の地域保健法、3の介護保険法、5の障害者基本法は、六法には含まれないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-008","examYear":"2021","examRound":"33","questionNumber":8,"category":"社会の理解","questionText":"2017年度（平成29年度）の社会保障給付費に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"国の一般会計当初予算は、社会保障給付費を上回っている。"},{"id":"2","text":"介護対策の給付費は、全体の30％を超えている。"},{"id":"3","text":"年金関係の給付費は、全体の40％を超えている。"},{"id":"4","text":"医療関係の給付費は、前年度より減少している。"},{"id":"5","text":"福祉その他の給付費は、前年度より減少している。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！2017年度の社会保障給付費で、年金関係の給付は、全体の約45%を占めていて、40%を超えているんだ。1は、一般会計当初予算は、社会保障給付費を下回る。2は、介護対策は10%に満たない。4は、医療関係は増加傾向。5は、福祉その他も増加傾向にあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-009","examYear":"2021","examRound":"33","questionNumber":9,"category":"社会の理解","questionText":"介護保険法の保険者として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"社会保険診療報酬支払基金"},{"id":"2","text":"市町村及び特別区"},{"id":"3","text":"国民健康保険団体連合会"},{"id":"4","text":"厚生労働省"},{"id":"5","text":"日本年金機構"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護保険制度の保険者は、市町村及び特別区なんだ。1の支払基金は診療報酬の審査支払、3の国保連は介護給付費の審査支払、4の厚生労働省は制度を管轄する国、5の日本年金機構は年金の運営を担っていて、保険者ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-010","examYear":"2021","examRound":"33","questionNumber":10,"category":"社会の理解","questionText":"介護保険制度の利用に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"要介護認定は、介護保険被保険者証の交付の前に行う。"},{"id":"2","text":"要介護認定には、主治医の意見書は不要である。"},{"id":"3","text":"要介護認定の審査・判定は、市町村の委託を受けた医療機関が行う。"},{"id":"4","text":"居宅サービス計画の作成は、原則として要介護認定の後に行う。"},{"id":"5","text":"要介護者の施設サービス計画の作成は、地域包括支援センターが行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！居宅サービス計画（ケアプラン）は、要介護認定を受けたあとに作成するのが原則なんだ。1は、認定は被保険者証の交付後に行われる。2は、主治医の意見書が必要。3は、審査・判定は市町村の介護認定審査会が行う。5は、施設サービス計画は施設の介護支援専門員が作成するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-011","examYear":"2021","examRound":"33","questionNumber":11,"category":"社会の理解","questionText":"Ｃさん（75歳、男性、要支援2）は、訪問介護（ホームヘルプサービス）を利用して一人暮らしをしていた。最近、脳梗塞（cerebral infarction）を起こして入院した。入院中に認知症（dementia）と診断された。退院時の要介護度は2で、自宅での生活継続に不安があったため、Ｕグループホームに入居することになった。Ｕグループホームの介護支援専門員（ケアマネジャー）が行うこととして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"訪問介護（ホームヘルプサービス）を継続して受けるために、Ｃさんを担当していた地域包括支援センターに連絡する。"},{"id":"2","text":"Ｕグループホームに入居するときに、認知症対応型共同生活介護計画を作成する。"},{"id":"3","text":"地域の居宅介護支援事業所に、Ｃさんのケアプランを作成するように依頼する。"},{"id":"4","text":"認知症対応型共同生活介護計画の作成をするときに、認知症（dementia）があるＣさんへの説明と同意を省略する。"},{"id":"5","text":"日中の活動を充実するために、地域の通所介護（デイサービス）の利用をケアプランに入れる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！グループホームに入居すると、そこの計画作成担当者が、認知症対応型共同生活介護計画を作るんだ。1は、地域包括支援センターへの連絡は不要。3は、グループホームの計画は、居宅介護支援事業所ではなく施設内で作成する。4は、説明と同意は省略できない。5は、通所介護は入居中は原則利用できないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-012","examYear":"2021","examRound":"33","questionNumber":12,"category":"社会の理解","questionText":"ノーマライゼーション（normalization）を説明する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"福祉、保健、医療などのサービスを総合的に利用できるように計画すること。"},{"id":"2","text":"家族、近隣、ボランティアなどによる支援のネットワークのこと。"},{"id":"3","text":"利用者自身が問題を解決していく力を獲得していくこと。"},{"id":"4","text":"障害があっても地域社会の一員として生活が送れるように条件整備をすること。"},{"id":"5","text":"利用者の心身の状態やニーズを把握すること。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ノーマライゼーションは、障害があっても、地域社会の一員として、普通の生活を送れるように、条件を整える考え方なんだ。1はケアマネジメント、2はソーシャルサポートネットワーク、3はエンパワメント、5はアセスメントの説明で、ノーマライゼーションとはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-013","examYear":"2021","examRound":"33","questionNumber":13,"category":"社会の理解","questionText":"Ｄさん（64歳、女性、障害支援区分4、身体障害者手帳2級）は、「障害者総合支援法」の居宅介護を利用して生活している。この居宅介護事業所は共生型サービスの対象となっている。Ｄさんは65歳になった後のサービスについて心配になり、担当の居宅介護職員に、「65歳になっても今利用しているサービスは使えるのか」と尋ねてきた。居宅介護事業所の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｄさんは障害者なので介護保険サービスを利用することはないと伝える。"},{"id":"2","text":"障害者の場合は75歳になると介護保険サービスに移行すると伝える。"},{"id":"3","text":"現在利用しているサービスを継続して利用することができると伝える。"},{"id":"4","text":"継続して利用できるかどうか65歳になった後で検討すると伝える。"},{"id":"5","text":"介護予防のための通所介護（デイサービス）を利用することになると伝える。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！共生型サービスの対象になっている事業所なら、65歳を過ぎても、障害福祉のサービスを、引き続き利用できることがあるんだ。1、2、5は、事実とちがう説明で、Ｄさんを不安にさせてしまう。4は、今答えられる質問に答えず、先送りにしているよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-014","examYear":"2021","examRound":"33","questionNumber":14,"category":"社会の理解","questionText":"「障害者総合支援法」の障害者の定義に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"18歳以上の者である。"},{"id":"2","text":"65歳未満の者である。"},{"id":"3","text":"難病患者は除外されている。"},{"id":"4","text":"発達障害者は除外されている。"},{"id":"5","text":"精神作用物質による依存症の者は除外されている。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！「障害者総合支援法」で、障害者は、18歳以上の身体障害者、知的障害者、精神障害者（発達障害者を含む）、難病等のある人と定義されているんだ。18歳未満は、障害児として別に定義されるよ。2は年齢の上限はない。3は難病患者も対象。4は発達障害者も含まれる。5は依存症の人も除外されないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-015","examYear":"2021","examRound":"33","questionNumber":15,"category":"社会の理解","questionText":"「障害者総合支援法」のサービスを利用するための障害支援区分を判定する組織として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"身体障害者更生相談所"},{"id":"2","text":"協議会"},{"id":"3","text":"基幹相談支援センター"},{"id":"4","text":"居宅介護事業所"},{"id":"5","text":"市町村審査会"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害支援区分は、市町村に置かれる市町村審査会が、判定するんだ。1の身体障害者更生相談所は、身体障害者の専門的な相談、2の協議会は、地域の関係者の連携、3の基幹相談支援センターは、相談支援の中核、4の居宅介護事業所は、サービスを提供する事業所で、区分の判定は行わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-016","examYear":"2021","examRound":"33","questionNumber":16,"category":"社会の理解","questionText":"「高齢者虐待防止法」に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"養護者及び養介護施設従事者等が行う行為が対象である。"},{"id":"2","text":"虐待の類型は、身体的虐待、心理的虐待、経済的虐待の三つである。"},{"id":"3","text":"虐待を発見した場合は、施設長に通報しなければならない。"},{"id":"4","text":"立ち入り調査を行うときは、警察官の同行が義務づけられている。"},{"id":"5","text":"通報には、虐待の事実確認が必要である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！高齢者虐待防止法は、家庭で介護する養護者と、施設などで働く養介護施設従事者等による虐待を、対象としているんだ。2は、虐待の類型は5つ。3は、通報先は市町村。4は、警察官の同行は必須ではない。5は、事実確認がなくても、疑いの段階で通報できるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-017","examYear":"2021","examRound":"33","questionNumber":17,"category":"介護の基本","questionText":"「2016年（平成28年）国民生活基礎調査」（厚生労働省）における、同居の主な介護者の悩みやストレスの原因として、最も多いものを1つ選びなさい。","choices":[{"id":"1","text":"家族の病気や介護"},{"id":"2","text":"自分の病気や介護"},{"id":"3","text":"家族との人間関係"},{"id":"4","text":"収入・家計・借金等"},{"id":"5","text":"自由にできる時間がない"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！2016年の国民生活基礎調査で、同居の主な介護者の悩みやストレスの原因として、最も多かったのは、家族の病気や介護なんだ。2の自分の病気、3の家族関係、4の収入、5の自由な時間の不足も上位にあるけれど、いちばん多いのは1だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-018","examYear":"2021","examRound":"33","questionNumber":18,"category":"介護の基本","questionText":"「価値のある社会的役割の獲得」を目指すソーシャルロール・バロリゼーション（Social Role Valorization）を提唱した人物として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"バンク－ミケルセン（Bank-Mikkelsen, N.）"},{"id":"2","text":"ヴォルフェンスベルガー（Wolfensberger, W.）"},{"id":"3","text":"メイヤロフ（Mayeroff, M.）"},{"id":"4","text":"キットウッド（Kitwood, T.）"},{"id":"5","text":"ニィリエ（Nirje, B.）"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！ヴォルフェンスベルガーは、障害のある人が、価値のある社会的役割を得られるようにする、ソーシャルロール・バロリゼーションを提唱したんだ。1のバンク-ミケルセンと5のニィリエは、ノーマライゼーションの理念を広めた人物。3のメイヤロフは『ケアの本質』、4のキットウッドは、パーソン・センタード・ケアの提唱者だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-019","examYear":"2021","examRound":"33","questionNumber":19,"category":"介護の基本","questionText":"ＩＣＦ（International Classification of Functioning, Disability and Health：国際生活機能分類）における環境因子を表す記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"アルツハイマー型認知症（dementia of the Alzheimerʼs type）である。"},{"id":"2","text":"糖尿病（diabetes mellitus）があるため服薬をしている。"},{"id":"3","text":"医者嫌いである。"},{"id":"4","text":"町内会の会長を務めていた。"},{"id":"5","text":"娘が近隣に住み、毎日訪問している。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！環境因子は、その人を取り巻く、物的・人的・社会的な環境のことなんだ。娘が近くに住んで、毎日訪問してくれるのは、人的環境にあたるよ。1のアルツハイマー型認知症や2の糖尿病は健康状態、3の医者嫌いは個人因子、4の町内会長は活動・参加の経歴にあたるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-020","examYear":"2021","examRound":"33","questionNumber":20,"category":"介護の基本","questionText":"利用者の自立生活支援・重度化防止のための見守り的援助に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ごみの分別がわからない利用者だったので、その場でごみを分別した。"},{"id":"2","text":"利用者の自宅の冷蔵庫の中が片づいていないので、整理整頓した。"},{"id":"3","text":"トイレ誘導した利用者の尿パッドを、本人に配慮して無言で取り替えた。"},{"id":"4","text":"服薬時に、薬を飲むように促して、そばで確認した。"},{"id":"5","text":"利用者が居間でテレビを見ているそばで、洗濯物を畳んだ。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！見守り的援助は、本人ができることを、声かけや確認で見守りながら、自分でしてもらう援助なんだ。1、2、5は、本人の代わりに行ってしまっている。3は、無言で取り替えると、本人の意思を確認していないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-021","examYear":"2021","examRound":"33","questionNumber":21,"category":"介護の基本","questionText":"高齢者のリハビリテーションに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"機能訓練は、1回の量を少なくして複数回に分けて行う。"},{"id":"2","text":"基本的な動作を行う訓練は、物理療法である。"},{"id":"3","text":"関節障害のある人の筋力訓練は、関節を積極的に動かすことが効果的である。"},{"id":"4","text":"パーキンソン病（Parkinson disease）の人の訓練では、体幹をひねることは避ける。"},{"id":"5","text":"関節リウマチ（rheumatoid arthritis）の人の訓練は、朝に行うことが効果的である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！高齢者は、体力や集中力が続きにくいことがあるので、1回の訓練量を少なくして、複数回に分けて行うのがよいんだ。2は、基本動作の訓練は運動療法。3は、関節障害がある人は無理に動かさない。4は、パーキンソン病の人にも体幹のひねりを取り入れる。5は、関節リウマチの人は朝はこわばりが強く訓練は避けるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-022","examYear":"2021","examRound":"33","questionNumber":22,"category":"介護の基本","questionText":"施設利用者の多様な生活に配慮した介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"夜型の生活習慣がある人に、施設の就寝時刻に合わせてもらった。"},{"id":"2","text":"化粧を毎日していた人に、シーツが汚れるため、化粧をやめてもらった。"},{"id":"3","text":"本に囲まれた生活をしてきた人に、散乱している本を捨ててもらった。"},{"id":"4","text":"自宅で畳に布団を敷いて寝ていた人に、ベッドで寝てもらった。"},{"id":"5","text":"自宅で夜間に入浴をしていた人に、夕食後に入浴してもらった。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！自宅での生活習慣を、施設でも可能な範囲で生かして、夕食後の入浴という形で、近い時間帯に対応するのがよいんだ。1は、夜型の生活習慣を、無理に施設に合わせている。2は化粧をやめさせる。3は大切な本を捨てさせる。4は布団の習慣を変えさせていて、いずれも本人の生活を尊重していないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-023","examYear":"2021","examRound":"33","questionNumber":23,"category":"介護の基本","questionText":"介護医療院に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"入所できるのは要介護3以上である。"},{"id":"2","text":"介護医療院の開設は市町村から許可を受けなければならない。"},{"id":"3","text":"入所者のためのレクリエーション行事を行うように努める。"},{"id":"4","text":"入所者一人当たりの床面積は、介護老人福祉施設と同じ基準である。"},{"id":"5","text":"サービス管理責任者を1名以上置かなければならない。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！介護医療院は、長期の療養が必要な人の、生活の場でもあるから、レクリエーション行事を行うよう努めることになっているんだ。1は、要介護度の制限はない。2は、開設の許可は都道府県知事など。4は、床面積の基準は異なる。5は、サービス管理責任者ではなく、医師や看護師などの配置が定められているよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-024","examYear":"2021","examRound":"33","questionNumber":24,"category":"介護の基本","questionText":"Ｅさん（女性、82歳、要介護1）は、夫（80歳）と二人暮らしである。膝の痛みがあるが、夫の介助があれば外出は可能である。最近Ｅさん宅は、玄関、トイレ、浴室に手すりを設置している。Ｅさんは料理が趣味で、近所のスーパーで食材を自分で選び、購入し、食事の用意をしたいと思っている。こうした中、Ｅさん宅で介護支援専門員（ケアマネジャー）が関係職種を招集してサービス担当者会議を開くことになった。Ｅさんの思いに添ったサービスの提案として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"訪問介護員（ホームヘルパー）による調理の生活援助の利用"},{"id":"2","text":"介護支援専門員（ケアマネジャー）の手配による配食サービスの利用"},{"id":"3","text":"社会福祉協議会の生活支援員による日常生活自立支援事業の活用"},{"id":"4","text":"福祉用具専門相談員の助言による四輪歩行車の利用"},{"id":"5","text":"通所介護（デイサービス）の職員による入浴サービスの利用"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｅさんは、膝の痛みがあっても、夫の介助があれば外出できて、自分で食材を選んで買物をしたいと思っているんだね。四輪歩行車があれば、膝の負担を減らしながら、自分で買物に行く力を支えられるよ。1、2、5は、Ｅさんの「自分でやりたい」思いを代わりに行ってしまう。3は金銭管理の支援で目的がちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-025","examYear":"2021","examRound":"33","questionNumber":25,"category":"介護の基本","questionText":"介護施設におけるプライバシーの保護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ユニット型施設は個室化が推進されているため、各居室で食事をしてもらった。"},{"id":"2","text":"個々の利用者の生活歴の情報を、ルールに従って介護職員間で共有した。"},{"id":"3","text":"個人情報記録のファイルを、閲覧しやすいように机の上に置いたままにした。"},{"id":"4","text":"着衣失行があるため、トイレのドアを開けたままで排泄（はいせつ）の介護を行った。"},{"id":"5","text":"家庭内の出来事や会話の内容は、情報に含まれないため記録しなかった。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！生活歴などの個人情報は、決められたルールに沿って、必要な範囲で、介護職員間で共有することが大切なんだ。1は、個室化と食事の場所は別の話。3は、ファイルの放置は情報漏えいのリスク。4は、ドアを開けたままの排泄介護は、羞恥心を傷つける。5は、家庭内の出来事も、大切な情報として記録するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-026","examYear":"2021","examRound":"33","questionNumber":26,"category":"介護の基本","questionText":"ハインリッヒ（Heinrich, H.）の法則に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"機能障害、能力障害、社会的不利という障害をとらえるための分類である。"},{"id":"2","text":"人間の自己実現に向けた欲求を5つの階層で示したものである。"},{"id":"3","text":"一つの重大事故の背景には、多くの軽微な事故とヒヤリハットが存在する。"},{"id":"4","text":"患者が余命を知らされてから死を受容するまでの心理的プロセスである。"},{"id":"5","text":"生活課題を抱えた人の支援をする上で必要な7つの原則である。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ハインリッヒの法則は、1つの重大事故の背景に、29の軽微な事故と、300のヒヤリハットが存在するという考え方なんだ。1はICF、2はマズローの欲求階層説、4はキューブラー・ロスの死の受容プロセス、5はバイステックの7原則の説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-027","examYear":"2021","examRound":"33","questionNumber":27,"category":"コミュニケーション技術","questionText":"介護福祉職が利用者と信頼関係を形成するためのコミュニケーション技術として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の意見に賛成できなくても同意する。"},{"id":"2","text":"「○○ちゃん」と親しみを込めてお互いを呼び合う。"},{"id":"3","text":"介護福祉職からは質問をせずに受け身の姿勢で聞く。"},{"id":"4","text":"介護福祉職の価値判断に従ってもらう。"},{"id":"5","text":"介護福祉職自身の感情の動きも意識しながら関わる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！自分自身の感情の動きに気づきながら関わる、自己覚知は、利用者との信頼関係を築くために、大切な姿勢なんだ。1は意見に同意するふり、2はなれなれしい呼び方、3は受け身すぎる、4は価値観を押しつけることで、信頼関係づくりには、ふさわしくないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-028","examYear":"2021","examRound":"33","questionNumber":28,"category":"コミュニケーション技術","questionText":"（事例）Ｆさん（85歳、女性）は、中等度の認知症（dementia）がある。同居していた娘の支援を受けて生活してきたが、症状が進行してきたために、介護老人福祉施設への入所が決まった。入所当日、介護福祉職はＦさんの付き添いで来た娘に初めて会った。介護福祉職が、「はじめまして。よろしくお願いします」と挨拶をすると、娘は少し緊張した様子で、「お願いします」とだけ答えた。娘は、介護福祉職の問いかけに応えるまで時間がかかり、また、あまり多くを語ることはなかった。持参した荷物の整理を終えて帰宅するとき、娘が寂しそうに、「これから離れて暮らすんですね」とつぶやいた。\n初対面の娘と関係を構築するために介護福祉職がとる対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"友人のような口調で話す。"},{"id":"2","text":"相手のペースに合わせて、表情を確認しながら話す。"},{"id":"3","text":"会話が途切れないように積極的に話す。"},{"id":"4","text":"密接距離を確保してから話す。"},{"id":"5","text":"スキンシップを用いながら話す。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！娘は緊張していて、答えるまで時間がかかる様子があるよね。相手のペースに合わせて、表情を確かめながら話すことが、関係づくりの第一歩なんだ。1はなれなれしい、3は急かしている、4は距離が近すぎる、5はいきなりの接触で、緊張している人には合わないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-029","examYear":"2021","examRound":"33","questionNumber":29,"category":"コミュニケーション技術","questionText":"帰宅するときの娘の発言に対する、介護福祉職の共感的な言葉かけとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「心配しなくても大丈夫ですよ」"},{"id":"2","text":"「私も寂しい気持ちは一緒です」"},{"id":"3","text":"「元気を出して、お母さんの前では明るく笑顔でいましょう」"},{"id":"4","text":"「お母さんに毎日会いに来てください」"},{"id":"5","text":"「お母さんと離れて暮らすと寂しくなりますね」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！娘の「これから離れて暮らすんですね」という寂しさに、そのまま寄り添って、気持ちを言葉にして返すのが、共感的な対応なんだ。1は安心させようとするだけ、2は自分の話にすり替え、3は励まし、4はお願いで、娘の気持ちをそのまま受け止めていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-030","examYear":"2021","examRound":"33","questionNumber":30,"category":"コミュニケーション技術","questionText":"Ｇさん（55歳、男性）は父親と二人で暮らしている。父親は週2回通所介護（デイサービス）を利用している。Ｇさんは、父親が夜に何度も起きるために睡眠不足となり、仕事でミスが続き退職を決意した。ある日、Ｇさんが介護福祉職に、「今後の生活が不安だ。通所介護（デイサービス）の利用をやめたいと考えている」と話した。Ｇさんが、「利用をやめたい」と言った背景にある理由を知るためのコミュニケーションとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"開かれた質問をする。"},{"id":"2","text":"「はい」「いいえ」で答えられる質問をする。"},{"id":"3","text":"介護福祉職のペースに合わせて話してもらう。"},{"id":"4","text":"事実と異なることは、訂正しながら聞く。"},{"id":"5","text":"相手が話したくないことは、推測して判断する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！「なぜ、やめたいと思ったのですか」のような、開かれた質問をすると、Ｇさんが自由に理由を話せて、背景にある事情を知る手がかりになるんだ。2は、はい・いいえで終わってしまう。3、4、5は、本人の言葉を十分に聴く姿勢になっていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-031","examYear":"2021","examRound":"33","questionNumber":31,"category":"コミュニケーション技術","questionText":"利用者と家族の意向が対立する場面で、介護福祉職が両者の意向を調整するときの留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"両者が話し合いを始めるまで発言しない。"},{"id":"2","text":"利用者に従うように家族を説得する。"},{"id":"3","text":"利用者と家族のそれぞれの意見を聞く。"},{"id":"4","text":"家族の介護負担の軽減を目的にして調整する。"},{"id":"5","text":"他職種には相談せずに解決する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！意見が対立しているときは、まず、利用者と家族、それぞれの思いを、丁寧に聴くことが、調整の基本なんだ。1は発言しないだけでは進まない。2は家族に無理に従わせる。4は家族の負担軽減だけを目的にする。5は他職種と連携せずに一人で解決しようとしているよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-032","examYear":"2021","examRound":"33","questionNumber":32,"category":"コミュニケーション技術","questionText":"運動性失語症（motor aphasia）のある人とコミュニケーションを図るときの留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"絵や写真を使って反応を引き出す。"},{"id":"2","text":"大きな声で1音ずつ区切って話す。"},{"id":"3","text":"手話を使うようにする。"},{"id":"4","text":"五十音表でひらがなを指してもらう。"},{"id":"5","text":"閉ざされた質問は控える。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！運動性失語症は、言葉を理解する力は保たれているけれど、話すことが難しい障害なんだ。絵や写真を使うと、うなずきや指さしで、反応を引き出しやすいよ。2、3、4は、話すことや新しい手段の習得を求めていて負担が大きい。5は、閉ざされた質問のほうが、答えやすいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-033","examYear":"2021","examRound":"33","questionNumber":33,"category":"コミュニケーション技術","questionText":"介護記録を書くときの留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"数日後に書く。"},{"id":"2","text":"客観的事実と主観的情報は区別せずに書く。"},{"id":"3","text":"ほかから得た情報は情報源も書く。"},{"id":"4","text":"利用者の気持ちだけを推測して書く。"},{"id":"5","text":"介護福祉職の意見を中心に書く。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ほかの職員や家族から得た情報を記録するときは、誰から聞いた情報かという情報源も、書いておくことが大切なんだ。1は、記録はできるだけ早く書く。2は、客観的事実と主観的情報は分けて書く。4は、気持ちの推測だけでなく事実も書く。5は、意見ではなく事実を中心に書くよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-034","examYear":"2021","examRound":"33","questionNumber":34,"category":"コミュニケーション技術","questionText":"報告者と聞き手の理解の相違をなくすための聞き手の留意点として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"受け身の姿勢で聞く。"},{"id":"2","text":"腕組みをしながら聞く。"},{"id":"3","text":"同調しながら聞く。"},{"id":"4","text":"不明な点を確認しながら聞く。"},{"id":"5","text":"ほかの業務をしながら聞く。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！話がわかりにくいところは、そのままにせず、確認しながら聞くと、報告者との理解のずれを防げるんだ。1は受け身ではずれに気づけない。2は腕組みは話しにくい印象を与える。3は同調するだけでは正確に理解できない。5はほかの業務をしながらでは集中して聞けないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-035","examYear":"2021","examRound":"33","questionNumber":35,"category":"生活支援技術","questionText":"次の記述のうち、古い住宅で暮らす高齢者が、ヒートショックを防ぐために必要な環境整備の方法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"居室の室温を低くする。"},{"id":"2","text":"脱衣室の照明を明るくする。"},{"id":"3","text":"トイレに床置き式の小型のパネルヒーターを置く。"},{"id":"4","text":"入浴直前に浴槽の湯温を60℃にし、蒸気を立てる。"},{"id":"5","text":"24時間換気システムを導入する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ヒートショックは、温度差が急に生じることで、血圧が大きく変動する現象なんだ。トイレに小型のヒーターを置いて、居室との温度差を減らすことが、予防になるよ。1は居室を寒くすると温度差が広がる。2は脱衣室も暖める必要がある。4は熱すぎる湯や蒸気は危険。5は換気だけでは温度差は防げないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-036","examYear":"2021","examRound":"33","questionNumber":36,"category":"生活支援技術","questionText":"高齢者にとって安全で使いやすい扉の工夫として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"トイレの扉は内開きにする。"},{"id":"2","text":"開き戸は杖（つえ）の使用者が移動しやすい。"},{"id":"3","text":"引き戸は開閉の速度が速くなる。"},{"id":"4","text":"アコーディオンドアは気密性が高い。"},{"id":"5","text":"引き戸の取っ手は棒型にする。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！引き戸の取っ手を、棒型（レバー型）にすると、握らなくても、手や腕を引っかけて開閉できて、使いやすいんだ。1は内開きだと中で倒れたとき開けにくい。2は開き戸は杖の使用者には開閉しにくい。3は引き戸はゆっくり開閉できる。4はアコーディオンドアは気密性が低いよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-037","examYear":"2021","examRound":"33","questionNumber":37,"category":"生活支援技術","questionText":"下肢の筋力が低下して、つまずきやすくなった高齢者に適した靴として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"靴底の溝が浅い靴"},{"id":"2","text":"靴底が薄く硬い靴"},{"id":"3","text":"足の指が固定される靴"},{"id":"4","text":"足背をしっかり覆う靴"},{"id":"5","text":"重い靴"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！足の甲（足背）をしっかり覆う靴は、足にフィットして、脱げにくく、つまずきにくいんだ。1の溝が浅い靴は滑りやすい。2の薄く硬い靴底はクッション性がなく感覚も伝わりにくい。3は指が固定されると踏ん張りにくい。5の重い靴は足を引きずりやすくなるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-038","examYear":"2021","examRound":"33","questionNumber":38,"category":"生活支援技術","questionText":"介護が必要な利用者の口腔（こうくう）ケアに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"うがいができる場合には、ブラッシング前にうがいをする。"},{"id":"2","text":"歯磨きは、頭部を後屈させて行う。"},{"id":"3","text":"部分床義歯のクラスプ部分は、流水で軽く洗う。"},{"id":"4","text":"全部の歯がない利用者には、硬い毛の歯ブラシを使用する。"},{"id":"5","text":"舌の清拭（せいしき）は、手前から奥に向かって行う。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ブラッシングの前にうがいをすると、口の中の食べかすが取れて、磨きやすくなるんだ。2は頭部を後屈すると誤嚥しやすい。3はクラスプ部分はブラシでしっかり磨く。4は歯がない人には粘膜用の柔らかいブラシを使う。5は舌の清拭は奥から手前に向かって行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-039","examYear":"2021","examRound":"33","questionNumber":39,"category":"生活支援技術","questionText":"口腔内（こうくうない）が乾燥している人への助言に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"苦味の強い食べ物を勧める。"},{"id":"2","text":"臥床時（がしょうじ）は仰臥位（ぎょうがい）（背臥位：はいがい）で枕を使用しないように勧める。"},{"id":"3","text":"水分は控えるように勧める。"},{"id":"4","text":"唾液腺マッサージをするように勧める。"},{"id":"5","text":"ジェルタイプの保湿剤は、前回塗った上に重ねて塗るように勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！唾液腺マッサージをすると、唾液の分泌が促されて、口の中の乾燥がやわらぐんだ。1は苦味の強い食べ物は刺激が強すぎる。2は枕を使わないと口が開いて余計に乾燥する。3は水分は適度にとる。5は保湿剤は古いものをふき取ってから新しく塗るよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-040","examYear":"2021","examRound":"33","questionNumber":40,"category":"生活支援技術","questionText":"介護福祉職が利用者を仰臥位（ぎょうがい）（背臥位）（はいがい）から側臥位（そくがい）へ体位変換するとき、図に示された力点の部位として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ＡとＣ"},{"id":"2","text":"ＡとＤ"},{"id":"3","text":"ＢとＣ"},{"id":"4","text":"ＢとＤ"},{"id":"5","text":"ＢとＥ"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！この問題は、体位変換のときに力を加える部位（力点）を、図から選ぶ問題なんだ。トルクの原理を使った体位変換では、肩や骨盤など、体をひねる力点に手を当てるのが基本だよ。図のＡとＣの組み合わせが、その力点にあたるとされているんだ。図が手元にあれば、あわせて確認してみてね。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-041","examYear":"2021","examRound":"33","questionNumber":41,"category":"生活支援技術","questionText":"標準型車いすを用いた移動の介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"急な上り坂は、すばやく進む。"},{"id":"2","text":"急な下り坂は、前向きで進む。"},{"id":"3","text":"踏切を渡るときは、前輪を上げて駆動輪でレールを越えて進む。"},{"id":"4","text":"段差を上がるときは、前輪を上げて進み駆動輪が段差に接する前に前輪を下ろす。"},{"id":"5","text":"砂利道では、駆動輪を持ち上げて進む。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！踏切のレールの溝は、キャスター（前輪）が引っかかりやすいから、前輪を上げて、駆動輪（後輪）でレールを越えるように進むんだ。1は上り坂はゆっくり進む。2は下り坂は後ろ向きで進む。4は段差は駆動輪が段差に十分乗ってから前輪を下ろす。5は砂利道は前輪を上げて進むよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-042","examYear":"2021","examRound":"33","questionNumber":42,"category":"生活支援技術","questionText":"Ｈさん（35歳、男性）は6か月前、高所作業中に転落し、第6胸髄節（Th6）を損傷した。リハビリテーション後、車いすを利用すれば日常生活を送ることができる状態になっている。Ｈさんの身体機能に応じた車いすの特徴として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ヘッドサポートを装着している。"},{"id":"2","text":"ハンドリムがないタイヤを装着している。"},{"id":"3","text":"レバーが長いブレーキを装着している。"},{"id":"4","text":"片手で駆動できるハンドリムを装着している。"},{"id":"5","text":"腰部までのバックサポートを装着している。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！第6胸髄節を損傷したＨさんは、体幹の一部が使えて、上肢の機能も保たれているから、腰部までの低いバックサポートで、体幹の動きを生かしやすくするんだ。1のヘッドサポートや2、3、4は、もっと重度の障害がある人向けの工夫だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-043","examYear":"2021","examRound":"33","questionNumber":43,"category":"生活支援技術","questionText":"Ｊさん（80歳、女性、要介護3）は、介護老人福祉施設に入所している。食事の後、Ｊさんから、「最近、飲み込みにくくなって時間がかかる」と相談された。受診の結果、加齢による機能低下が疑われると診断された。次の記述のうち、Ｊさんが食事をするときの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"リクライニングのいすを用意する。"},{"id":"2","text":"栄養価の高い食事を準備する。"},{"id":"3","text":"食前に嚥下体操（えんげたいそう）を勧める。"},{"id":"4","text":"自力で全量を摂取できるように促す。"},{"id":"5","text":"細かく刻んだ食事を提供する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！食事の前に、嚥下体操をすると、飲み込みに関わる筋肉がほぐれて、安全に食べやすくなるんだ。1はリクライニングは状態によって使うが、まず体操が優先。2は栄養価だけでは飲み込みにくさは解決しない。4は無理に自力摂取を促す。5は刻み食はかえってまとまりにくくむせやすいことがあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-044","examYear":"2021","examRound":"33","questionNumber":44,"category":"生活支援技術","questionText":"慢性閉塞性肺疾患（まんせいへいそくせいはいしっかん）（chronic obstructive pulmonary disease）のある利用者の食事に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"繊維質の多い芋類を食事に取り入れる。"},{"id":"2","text":"炭酸飲料で水分補給をする。"},{"id":"3","text":"たんぱく質の多い食事は控える。"},{"id":"4","text":"高カロリーの食事は控える。"},{"id":"5","text":"1回の食事量を減らし、回数を増やす。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！COPDの人は、おなかが張ると、横隔膜が圧迫されて、呼吸が苦しくなりやすいんだ。1回の量を減らして回数を増やすと、呼吸の負担を抑えられるよ。1は芋類はガスがたまりやすい。2は炭酸飲料もお腹が張る。3はたんぱく質はしっかりとる。4はエネルギーは確保する必要があるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-045","examYear":"2021","examRound":"33","questionNumber":45,"category":"生活支援技術","questionText":"入浴の身体への作用を踏まえた介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"浮力作用があるため、食後すぐの入浴は避ける。"},{"id":"2","text":"浮力作用があるため、入浴中に関節運動を促す。"},{"id":"3","text":"静水圧作用があるため、入浴後に水分補給をする。"},{"id":"4","text":"静水圧作用があるため、入浴前にトイレに誘導する。"},{"id":"5","text":"温熱作用があるため、お湯につかる時間を短くする。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！お湯の中では、浮力で体が軽くなるから、関節を動かしやすくなるんだ。だから、入浴中に関節運動を促すのがよいよ。1の食後すぐの入浴を避けるのは消化への影響。3、4は、静水圧作用と水分補給やトイレ誘導は直接の関係が薄い。5は、温熱作用で長すぎる入浴は避けるという説明が近いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-046","examYear":"2021","examRound":"33","questionNumber":46,"category":"生活支援技術","questionText":"四肢麻痺（ししまひ）の利用者の手浴に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"仰臥位（ぎょうがい）（背臥位）（はいがい）で行う。"},{"id":"2","text":"手指は、30分以上お湯に浸す。"},{"id":"3","text":"手関節を支えながら洗う。"},{"id":"4","text":"指間は、強く洗う。"},{"id":"5","text":"指間は、自然乾燥させる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！四肢麻痺がある人の手浴では、手関節を支えながら洗うと、負担をかけずに、安全に洗えるんだ。1は仰臥位より座位や手を浮かせやすい姿勢がよい。2は30分以上の浸水は皮膚がふやけすぎる。4は指の間は優しく洗う。5は指の間はしっかり拭き取って乾燥させるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-047","examYear":"2021","examRound":"33","questionNumber":47,"category":"生活支援技術","questionText":"利用者の状態に応じた清潔の介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"乾燥性皮膚疾患がある場合、弱アルカリ性の石鹸（せっけん）で洗う。"},{"id":"2","text":"人工透析をしている場合、柔らかいタオルでからだを洗う。"},{"id":"3","text":"褥瘡（じょくそう）がある場合、石鹸（せっけん）をつけた指で褥瘡部（じょくそうぶ）をこすって洗う。"},{"id":"4","text":"糖尿病性神経障害（diabetic neuropathy）がある場合、足の指の間はナイロンたわしで洗う。"},{"id":"5","text":"浮腫のある部位は、タオルを強く押し当てて洗う。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！人工透析をしている人は、皮膚が乾燥しやすく、傷つきやすいから、柔らかいタオルで、優しく洗うんだ。1は乾燥性皮膚疾患には弱酸性の石鹸がよい。3は褥瘡部はこすらない。4は糖尿病性神経障害ではナイロンたわしは避ける。5は浮腫のある部位は優しく押さえるように洗うよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-048","examYear":"2021","examRound":"33","questionNumber":48,"category":"生活支援技術","questionText":"Ｋさん（72歳、女性、要介護2）は、脳梗塞（cerebral infarction）で入院したが回復し、自宅への退院に向けてリハビリテーションに取り組んでいる。トイレへは手すりを使って移動し、トイレ動作は自立している。退院後も自宅のトイレでの排泄（はいせつ）を希望している。Ｋさんが自宅のトイレで排泄（はいせつ）を実現するために必要な情報として、最も優先されるものを1つ選びなさい。","choices":[{"id":"1","text":"便意・尿意の有無"},{"id":"2","text":"飲食の状況"},{"id":"3","text":"衣服の着脱の様子"},{"id":"4","text":"家族介護者の有無"},{"id":"5","text":"トイレまでの通路の状況"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｋさんは、病院ではトイレ動作が自立しているけれど、自宅のトイレまでの通路が、車いすや杖で安全に通れるかは、まだわかっていないんだ。だから、トイレまでの通路の状況を確認することが、最も優先されるよ。1、2、3は、すでに問題ないとわかっている。4は排泄の実現に直接必要な情報ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-049","examYear":"2021","examRound":"33","questionNumber":49,"category":"生活支援技術","questionText":"自己導尿を行っている利用者に対する介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"座位が不安定な場合は、体を支える。"},{"id":"2","text":"利用者が自己導尿を行っている間は、そばで見守る。"},{"id":"3","text":"利用者と一緒にカテーテルを持ち、挿入する。"},{"id":"4","text":"再利用のカテーテルは水道水で洗い、乾燥させる。"},{"id":"5","text":"尿の観察は利用者自身で行うように伝える。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！自己導尿は、本人が自分で行うのが基本で、介護福祉職は、座位が不安定なときに、体を支えるなど、安全のための手伝いをするんだ。2は常にそばで見守る必要はない。3は挿入は医療行為にあたる。4はカテーテルの洗浄は指示された方法で行う。5は尿の観察は必要なら一緒に確認するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-050","examYear":"2021","examRound":"33","questionNumber":50,"category":"生活支援技術","questionText":"下肢筋力の低下により立位に一部介助が必要な車いすの利用者が、トイレで排泄（はいせつ）をするときの介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"便座の高さは、利用者の膝よりも低くなるように調整する。"},{"id":"2","text":"便座に移乗する前に、車いすのバックサポートに寄りかかってもらう。"},{"id":"3","text":"車いすから便座に移乗するときは、利用者の上腕を支える。"},{"id":"4","text":"利用者が便座に移乗したら、座位が安定していることを確認する。"},{"id":"5","text":"立ち上がる前に、下着とズボンを下腿部（かたいぶ）まで下げておく。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！移乗が終わったら、まず座位が安定しているかを確認することが、安全のために大切なんだ。1は便座は車いすの座面と同じくらいの高さがよい。2はバックサポートに寄りかかると前傾姿勢が取りにくい。3は上腕ではなく体幹や腰を支える。5は座ってから下着とズボンを下げるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-051","examYear":"2021","examRound":"33","questionNumber":51,"category":"生活支援技術","questionText":"図の洗濯表示の記号の意味として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"液温は30℃以上とし、洗濯機で洗濯ができる。"},{"id":"2","text":"液温は30℃以上とし、洗濯機で弱い洗濯ができる。"},{"id":"3","text":"液温は30℃以上とし、洗濯機で非常に弱い洗濯ができる。"},{"id":"4","text":"液温は30℃を上限とし、洗濯機で弱い洗濯ができる。"},{"id":"5","text":"液温は30℃を上限とし、洗濯機で非常に弱い洗濯ができる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！この記号は、桶に波線が1本入った洗濯表示で、液温は30℃を上限として、洗濯機で弱い洗濯ができることを表しているんだ。波線の数や、下線の有無で、洗い方の強さが変わるので、洗濯表示の意味は、セットで覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-052","examYear":"2021","examRound":"33","questionNumber":52,"category":"生活支援技術","questionText":"衣服についたバターのしみを取るための処理方法に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"水で洗い流す。"},{"id":"2","text":"しみに洗剤を浸み込ませて、布の上に置いて叩く。"},{"id":"3","text":"乾かした後、ブラッシングする。"},{"id":"4","text":"氷で冷やしてもむ。"},{"id":"5","text":"歯磨き粉をつけてもむ。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！バターなどの油性のしみは、洗剤をしみ込ませて、下に布を当てて、上から叩くと、しみが下の布に移って、落ちやすくなるんだ。1は水だけでは油分は落ちない。3は乾かすとしみが定着してしまう。4は氷で冷やすのはチョコレートなどのしみに向く方法。5は歯磨き粉は適さないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-053","examYear":"2021","examRound":"33","questionNumber":53,"category":"生活支援技術","questionText":"食中毒の予防に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"鮮魚や精肉は、買物の最初に購入する。"},{"id":"2","text":"冷蔵庫の食品は、隙間なく詰める。"},{"id":"3","text":"作って保存しておく食品は、広く浅い容器に入れてすばやく冷ます。"},{"id":"4","text":"再加熱するときは、中心部温度が60℃で1分間行う。"},{"id":"5","text":"使い終わった器具は、微温湯をかけて消毒する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！作り置きの食品は、広く浅い容器に入れて、早く冷ますと、菌が増えやすい温度帯を、短い時間で通過できるんだ。1は鮮魚や精肉は買物の最後に買う。2は冷蔵庫は詰めすぎず冷気の通り道をつくる。4は再加熱は中心部温度75℃で1分以上。5は器具の消毒は熱湯や消毒剤を使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-054","examYear":"2021","examRound":"33","questionNumber":54,"category":"生活支援技術","questionText":"喘息（ぜんそく）のある利用者の自宅の掃除に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"掃除機をかける前に吸着率の高いモップで床を拭く。"},{"id":"2","text":"掃除は低い所から高い所へ進める。"},{"id":"3","text":"拭き掃除は往復拭きをする。"},{"id":"4","text":"掃除機の吸い込み口はすばやく動かす。"},{"id":"5","text":"掃除は部屋の出入口から奥へ向かって進める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！掃除機をかける前に、モップで軽くほこりを拭き取っておくと、掃除機で舞い上がるほこりを減らせて、喘息のある人にやさしいんだ。2は高い所から低い所へ進める。3は往復拭きだとほこりを再び広げやすい。4は吸い込み口はゆっくり動かす。5は奥から出入口に向かって進めるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-055","examYear":"2021","examRound":"33","questionNumber":55,"category":"生活支援技術","questionText":"ベッドに比べて畳の部屋に布団を敷いて寝る場合の利点について、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"布団に湿気がこもらない。"},{"id":"2","text":"立ち上がりの動作がしやすい。"},{"id":"3","text":"介護者の負担が少ない。"},{"id":"4","text":"床からの音や振動が伝わりにくい。"},{"id":"5","text":"転落の不安がない。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！布団は、床に直接敷くから、ベッドのように高さがなく、寝ている間に転落する不安がないんだ。1は、布団は湿気がこもりやすい。2は、低い位置からの立ち上がりは、むしろ大変になりやすい。3は、上げ下ろしがあるぶん介護者の負担は増える。4は、床に近いぶん、音や振動は伝わりやすいよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-056","examYear":"2021","examRound":"33","questionNumber":56,"category":"生活支援技術","questionText":"睡眠の環境を整える介護として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"寝具を選ぶときは、保湿性を最優先する。"},{"id":"2","text":"湯たんぽを使用するときは、皮膚に直接触れないようにする。"},{"id":"3","text":"寝室の温度は、1年を通して15℃前後が望ましい。"},{"id":"4","text":"枕は、顎が頸部（けいぶ）につくぐらいの高さにする。"},{"id":"5","text":"就寝中の電気毛布は、スイッチを切る必要がない。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！湯たんぽは、タオルなどで包んで、皮膚に直接触れないようにしないと、低温やけどの原因になるんだ。1は保湿性より吸湿性や通気性を優先する。3は寝室の温度は季節に応じて調整する。4は枕は頸部が前屈しすぎない高さにする。5は電気毛布は眠る前にスイッチを切るのが基本だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-057","examYear":"2021","examRound":"33","questionNumber":57,"category":"生活支援技術","questionText":"Ｌさん（78歳、男性）は、脳梗塞後遺症による右片麻痺（みぎかたまひ）がある。妻の介護疲れで、3日前から介護老人保健施設の短期入所療養介護（ショートステイ）を利用している。入所以降、Ｌさんは日中もベッドで横になっていることが多かったため、介護福祉職がＬさんに話を聞くと、「夜、眠れなくて困っている」と訴えた。介護福祉職のＬさんへの対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"施設の起床時間や消灯時間をわかりやすく伝える。"},{"id":"2","text":"眠ろうとする意志が大切だと説明する。"},{"id":"3","text":"自宅での睡眠の状況について詳しく尋ねる。"},{"id":"4","text":"日中の睡眠の必要性を伝える。"},{"id":"5","text":"睡眠薬の服用について提案する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｌさんが眠れない理由を知るために、まずは自宅での睡眠の状況を、詳しく聞くことが大切なんだ。1は時刻を伝えるだけでは解決にならない。2は意志の問題にしてしまう。4は日中の睡眠を勧めると夜さらに眠れなくなる。5は睡眠薬の提案は医療職の判断が必要で、まず状況を聞くのが先だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-058","examYear":"2021","examRound":"33","questionNumber":58,"category":"生活支援技術","questionText":"「人生の最終段階における医療・ケアの決定プロセスに関するガイドライン」（2018年（平成30年）改訂（厚生労働省））において、アドバンス・ケア・プランニング（ＡＣＰ）が重要視されている。このアドバンス・ケア・プランニング（ＡＣＰ）を踏まえた、人生の最終段階を迎えようとする人への介護福祉職の言葉かけとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「生活上の悩みごとは、近くの地域包括支援センターに相談できます」"},{"id":"2","text":"「今後の医療とケアについては、家族が代わりに決めるので安心です」"},{"id":"3","text":"「今後の生活について、家族や医療・介護職員と一緒に、その都度話し合っていきましょう」"},{"id":"4","text":"「口から食べることができなくなったら、介護職員に相談してください」"},{"id":"5","text":"「意思を伝えられなくなったら、成年後見制度を利用しましょう」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！アドバンス・ケア・プランニングは、本人の意思を大切にしながら、家族や医療・介護職員と、繰り返し話し合っていくプロセスなんだ。1は相談先の紹介だけ。2は本人ではなく家族が決めるとしている。4は状況が変わってからの相談を待つだけ。5は成年後見制度は財産管理などが中心だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-059","examYear":"2021","examRound":"33","questionNumber":59,"category":"生活支援技術","questionText":"死期が近づいたときの介護に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食事量が減少したときは、高カロリーの食事を用意する。"},{"id":"2","text":"チアノーゼ（cyanosis）が出現したときは、冷罨法（れいあんぽう）を行う。"},{"id":"3","text":"全身倦怠感（ぜんしんけんたいかん）が強いときは、全身清拭（ぜんしんせいしき）から部分清拭（ぶぶんせいしき）に切り替える。"},{"id":"4","text":"傾眠傾向があるときは、話しかけないようにする。"},{"id":"5","text":"口腔内乾燥（こうくうないかんそう）があるときは、アイスマッサージを行う。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！倦怠感が強いときは、体への負担を減らすために、全身の清拭から、必要な部分だけを拭く、部分清拭に切り替えるんだ。1は食欲が落ちているときに高カロリー食を勧めても負担になる。2はチアノーゼには保温が基本。4は傾眠のときも声はかけ続ける。5は口腔内乾燥には保湿ケアが基本だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-060","examYear":"2021","examRound":"33","questionNumber":60,"category":"生活支援技術","questionText":"高齢者施設で利用者の死後に行うデスカンファレンス（death conference）に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ボランティアに参加を求める。"},{"id":"2","text":"ケアを振り返り、悲しみを共有する。"},{"id":"3","text":"利用者の死亡直後に行う。"},{"id":"4","text":"個人の責任や反省点を追及する。"},{"id":"5","text":"自分の感情は抑える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！デスカンファレンスは、亡くなった利用者のケアを、チームで振り返り、悲しみやそれぞれの思いを、共有する場なんだ。1は参加はスタッフが中心。3は直後に急いで行う必要はない。4は責任追及の場ではない。5は感情を抑えるのではなく表現し合うことも大切だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-061","examYear":"2021","examRound":"33","questionNumber":61,"category":"介護過程","questionText":"介護過程の目的に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の健康状態の改善"},{"id":"2","text":"介護福祉職の介護観の変容"},{"id":"3","text":"他職種との役割の分化"},{"id":"4","text":"家族の介護負担の軽減"},{"id":"5","text":"利用者の生活の質の向上"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護過程を展開する目的は、根拠のある介護によって、利用者の生活の質（QOL）を高めることなんだ。1の健康状態の改善だけが目的ではなく、2、3、4は、介護福祉職や他職種、家族の視点であって、利用者を中心にした目的ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-062","examYear":"2021","examRound":"33","questionNumber":62,"category":"介護過程","questionText":"介護福祉職の情報収集に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"五感を活用した観察を通して情報を集める。"},{"id":"2","text":"一つの場面に限定して得られる情報を集める。"},{"id":"3","text":"初対面のときから踏み込んで情報を集める。"},{"id":"4","text":"興味のある個人情報を集める。"},{"id":"5","text":"実践したい支援に沿った情報を集める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！情報収集では、視覚、聴覚、嗅覚など、五感を使った観察から、幅広く情報を集めることが大切なんだ。2は場面を限定すると情報が偏る。3は初対面から踏み込みすぎると信頼関係を損なう。4は興味本位で集めない。5は実践したい支援に偏らず客観的に集めるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-063","examYear":"2021","examRound":"33","questionNumber":63,"category":"介護過程","questionText":"次の記述のうち、介護過程の展開におけるアセスメント（assessment）の説明として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"支援内容を説明して同意を得ること。"},{"id":"2","text":"具体的な支援計画を検討すること。"},{"id":"3","text":"達成できる目標を設定すること。"},{"id":"4","text":"支援の経過を評価すること。"},{"id":"5","text":"利用者の生活課題を明確にすること。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！アセスメントは、集めた情報を整理・分析して、利用者の生活課題を明確にする段階なんだ。1は実施の説明と同意、2は計画の立案、3は目標設定、4は評価の説明で、アセスメントとは別の段階のことだよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-064","examYear":"2021","examRound":"33","questionNumber":64,"category":"介護過程","questionText":"短期目標の設定に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職の視点で目標を設定する。"},{"id":"2","text":"多様な解釈ができる言葉を用いて設定する。"},{"id":"3","text":"実現可能な目標を段階的に設定する。"},{"id":"4","text":"長期目標とは切り離して設定する。"},{"id":"5","text":"最終的に実現したい生活像を設定する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！短期目標は、長期目標に向けて、達成できそうな内容を、段階的に設定するんだ。1は介護福祉職ではなく利用者の視点で立てる。2は解釈がわかれない具体的な言葉を使う。4は長期目標とつながるように設定する。5は最終的な生活像は長期目標にあたるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-065","examYear":"2021","examRound":"33","questionNumber":65,"category":"介護過程","questionText":"（事例）Ｍさん（78歳、女性、要介護2）は、認知症対応型共同生活介護（グループホーム）に入居している。楽しみは、お風呂に入って肩までつかることである。身体機能に問題はない。短期目標を、「見守りのもと、一人で入浴する（3か月）」と設定し、順調に経過していた。1か月が過ぎた頃、朝の申し送りで、「Ｍさんが昨日浴室を出ようとしたときに足を滑らせたが、転倒はしなかった。念のため受診したが問題はなかった」と報告があった。その日の夕方、介護福祉職が入浴に誘うと、「行きたくない」と強い口調で断った。それから1週間入浴していないことを心配した介護福祉職が居室を訪ねて、安全に入浴できるように浴室内を整えたことを伝えた。しかし、Ｍさんは、「怖いから」と小声で言った。\nＭさんの再アセスメントに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"順調に経過していたときの状況を分析する。"},{"id":"2","text":"「怖いから」という思いを解釈する。"},{"id":"3","text":"入浴を断られた介護福祉職の思いを理解する。"},{"id":"4","text":"入浴時間の変更を検討する必要があると判断する。"},{"id":"5","text":"入浴を面倒に思っていると判断する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｍさんは、小声で「怖いから」と言っているよね。この言葉の背景にある思いを、丁寧に解釈することが、再アセスメントの中心になるんだ。1はすでに順調だった過去の状況で今の分析にはならない。3は介護福祉職側の思い。4は時間の変更だけでは解決にならない。5は決めつけているよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-066","examYear":"2021","examRound":"33","questionNumber":66,"category":"介護過程","questionText":"再アセスメントによって見直した支援の方向性として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"湯船につかる自信を取り戻す支援"},{"id":"2","text":"浴室内の移動の不安を取り除く支援"},{"id":"3","text":"浴室まで安全に移動できる支援"},{"id":"4","text":"足浴で満足感を得ることができる支援"},{"id":"5","text":"身体機能を改善する支援"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｍさんは、浴室を出ようとしたときに足を滑らせた経験から、浴室内の移動に、怖さを感じていると考えられるんだ。だから、浴室内の移動の不安を取り除く支援が適切だよ。1は湯船には問題を感じていない。3は浴室内が課題。4は目的がずれる。5は身体機能自体に問題はないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-067","examYear":"2021","examRound":"33","questionNumber":67,"category":"介護過程","questionText":"（事例）Ａさん（80歳、女性、要介護3）は、パーキンソン病（Parkinson disease）と診断されている。診断後も家業を手伝いながら、地域の活動に参加していた。半年前からパーキンソン病（Parkinson disease）が悪化し、動作は不安定となったが、「家族に迷惑をかけたくない」と、できることは自分で取り組んでいた。また、主となる介護者である娘に服薬を管理してもらいながら、通所介護（デイサービス）を週3回利用し、なじみの友人と話すことを楽しみにしていた。最近、通所介護（デイサービス）の職員から娘に、昼食時にむせることが多く食事を残していること、午後になると、「レクリエーションには参加したくない」と落ち着かない様子になることが報告された。\n介護福祉職がＡさんについて、主観的に記録したものを1つ選びなさい。","choices":[{"id":"1","text":"パーキンソン病（Parkinson disease）と診断されている。"},{"id":"2","text":"帰宅願望から、レクリエーションの参加を拒否した。"},{"id":"3","text":"「家族に迷惑をかけたくない」と話し、できることは自分で行っていた。"},{"id":"4","text":"週3回、通所介護（デイサービス）を利用している。"},{"id":"5","text":"昼食時にむせることが多く、食事を残していることを娘に報告した。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！「帰宅願望から」というのは、介護福祉職の解釈（推測）であって、実際に見た事実ではないから、主観的な記録なんだ。1、4は診断や利用状況という客観的事実。3はＡさんの発言をそのまま書いた事実。5はむせや食事量、報告した事実で、これらは客観的な記録だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-068","examYear":"2021","examRound":"33","questionNumber":68,"category":"介護過程","questionText":"その後、娘が腰痛を発症し、Ａさんは短期入所生活介護（ショートステイ）を利用することになった。次の記述のうち、短期入所生活介護（ショートステイ）におけるＡさんの生活課題として、最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"食事を安全に摂取できること。"},{"id":"2","text":"服薬の管理ができること。"},{"id":"3","text":"通所介護（デイサービス）の利用を再開できること。"},{"id":"4","text":"なじみの友人ができること。"},{"id":"5","text":"地域の活動に参加できること。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ａさんは、昼食時にむせて、食事を残すことが増えているよね。誤嚥は命に関わることもあるから、食事を安全に摂取できることが、最も優先すべき生活課題なんだ。2、3、4、5も大切だけど、安全な食事に比べると、優先度は下がるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-069","examYear":"2021","examRound":"33","questionNumber":69,"category":"発達と老化の理解","questionText":"Ａさん（小学4年生、男性）は、思いやりがあり友人も多い。図画工作や音楽が得意で落ち着いて熱心に取り組むが、苦手な科目がある。特に国語の授業のノートを見ると、黒板を書き写そうとしているが、文字の大きさもふぞろいで、一部の漢字で左右が入れ替わっているなどの誤りが多く見られ、途中で諦めた様子である。親子関係や家庭生活、身体機能、就学時健康診断などには問題がない。Ａさんに当てはまる状態として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自閉症スペクトラム障害（autism spectrum disorder）"},{"id":"2","text":"愛着障害"},{"id":"3","text":"注意欠陥多動性障害"},{"id":"4","text":"学習障害"},{"id":"5","text":"知的障害"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ａさんは、知的な遅れはなく、家庭環境や身体機能にも問題がないのに、文字を書き写すことに、特有の困難があるよね。これは、読む・書く・計算するなど、特定の学習に困難がある、学習障害の特徴なんだ。1、2、3、5とは、症状のあらわれ方がちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-070","examYear":"2021","examRound":"33","questionNumber":70,"category":"発達と老化の理解","questionText":"医療や福祉の法律での年齢に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"35歳の人は、老人福祉施設に入所できる。"},{"id":"2","text":"50歳の人は、介護保険の第一号被保険者である。"},{"id":"3","text":"60歳の人は、医療保険の前期高齢者である。"},{"id":"4","text":"70歳の人は、介護保険の第二号被保険者である。"},{"id":"5","text":"75歳の人は、後期高齢者医療の被保険者である。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！後期高齢者医療制度は、原則75歳以上の人が、被保険者になるんだ。1は老人福祉施設の入所は原則65歳以上。2は介護保険の第1号被保険者は65歳以上。3は前期高齢者は65歳以上75歳未満。4は介護保険の第2号被保険者は40歳以上65歳未満だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-071","examYear":"2021","examRound":"33","questionNumber":71,"category":"発達と老化の理解","questionText":"高齢期の喪失体験と悲嘆に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"喪失体験とは、加齢に伴う身体機能の低下のことである。"},{"id":"2","text":"悲嘆過程とは、病的な心のプロセスのことである。"},{"id":"3","text":"死別後の悲嘆からの回復には、喪失に対する心理的対処だけでなく生活の立て直しへの対処も必要である。"},{"id":"4","text":"ボウルビィ（Bowlby, J.）によれば、悲嘆過程には順序性はない。"},{"id":"5","text":"身近な人との死別後に生じる病的悲嘆への支援では、亡くなった人への愛着をほかに向けることを目標にする。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！死別後の悲嘆からの回復には、悲しみに向き合う心理的な対処と、日常生活を立て直す対処の、両方が必要なんだ。1は喪失体験は身体機能の低下だけでなく人や役割の喪失も含む。2は悲嘆は自然な反応。4はボウルビィは順序性があるとした。5は愛着を完全に断つことは目標にしないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-072","examYear":"2021","examRound":"33","questionNumber":72,"category":"発達と老化の理解","questionText":"加齢による味覚の変化に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"味蕾（みらい）の数に年齢による違いはない。"},{"id":"2","text":"服用する薬剤で味覚が変化することはない。"},{"id":"3","text":"唾液が増加して味覚が敏感になる。"},{"id":"4","text":"濃い味を好むようになる。"},{"id":"5","text":"口腔（こうくう）ケアは関係ない。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！加齢によって、味覚を感じる力（特に塩味）が鈍くなるので、濃い味を好むようになるんだ。1は味蕾の数は加齢で減少する。2は薬の副作用で味覚が変化することがある。3は唾液は減少しやすい。5は口腔ケアの状態も味覚に影響するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-073","examYear":"2021","examRound":"33","questionNumber":73,"category":"発達と老化の理解","questionText":"意欲が低下した高齢者の動機づけに関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高い目標を他者が掲げると、動機づけが強まる。"},{"id":"2","text":"本人が具体的に何をすべきかがわかると、動機づけが強まる。"},{"id":"3","text":"本人にとって興味がある目標を掲げると、動機づけが弱まる。"},{"id":"4","text":"小さな目標の達成を積み重ねていくと、動機づけが弱まる。"},{"id":"5","text":"本人が自分にもできそうだと思う目標を掲げると、動機づけが弱まる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！何をすればよいかが具体的にわかると、見通しが立って、やる気が出やすいんだ。1は他者が高い目標を掲げると負担に感じやすい。3は興味がある目標なら動機づけは強まる。4は小さな達成の積み重ねは動機づけを強める。5はできそうだと思える目標は動機づけを強めるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-074","examYear":"2021","examRound":"33","questionNumber":74,"category":"発達と老化の理解","questionText":"高齢者の便秘に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"大腸がん（colorectal cancer）は、器質性便秘の原因になる。"},{"id":"2","text":"弛緩性便秘（しかんせいべんぴ）はまれである。"},{"id":"3","text":"けいれん性便秘では、大きく柔らかい便がでる。"},{"id":"4","text":"直腸性便秘は、便が直腸に送られてこないために起こる。"},{"id":"5","text":"薬剤で、便秘になることはまれである。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！大腸がんなどで腸が狭くなると、便が通りにくくなる、器質性便秘が起こるんだ。2は弛緩性便秘は高齢者に多い。3はけいれん性便秘はコロコロした硬い便が出やすい。4は直腸性便秘は便が直腸まで来てもうまく排出できない状態。5は薬剤による便秘はよくみられるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-075","examYear":"2021","examRound":"33","questionNumber":75,"category":"発達と老化の理解","questionText":"高齢者の転倒に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"介護が必要になる原因は、転倒による骨折（fracture）が最も多い。"},{"id":"2","text":"服用する薬剤と転倒は、関連がある。"},{"id":"3","text":"転倒による骨折（fracture）の部位は、足首が最も多い。"},{"id":"4","text":"転倒の場所は、屋内では浴室が最も多い。"},{"id":"5","text":"過去に転倒したことがあると、再度の転倒の危険性は低くなる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！睡眠薬や降圧薬などは、ふらつきを起こしやすく、転倒と関連があるんだ。1は介護が必要になる原因の1位は認知症で、骨折・転倒は上位だけど1位ではない。3は骨折の部位は大腿骨近位部が多い。4は屋内では居室での転倒が多い。5は過去に転倒した人は再度の転倒リスクが高いよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-076","examYear":"2021","examRound":"33","questionNumber":76,"category":"発達と老化の理解","questionText":"高齢者の糖尿病（diabetes mellitus）に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"アミラーゼ（amylase）の作用不足が原因である。"},{"id":"2","text":"ヘモグロビンＡ1ｃ（HbA1c）の目標値は、若年者に比べて低めが推奨される。"},{"id":"3","text":"若年者に比べて高血糖の持続による口渇感が強い。"},{"id":"4","text":"運動療法は避けたほうがよい。"},{"id":"5","text":"若年者に比べて低血糖の自覚症状に乏しい。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！高齢者は、低血糖になっても、冷や汗や動悸などの症状に、気づきにくいことが多いんだ。1は糖尿病はインスリンの作用不足が原因。2は高齢者のHbA1c目標値は若年者より高めに設定されることが多い。3は口渇感は感じにくくなる。4は運動療法は状態に応じて行うほうがよいよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-077","examYear":"2021","examRound":"33","questionNumber":77,"category":"認知症の理解","questionText":"うつ病（depression）による仮性認知症（pseudodementia）と比べて認知症（dementia）に特徴的な事柄として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"判断障害がみられることが多い。"},{"id":"2","text":"不眠を訴えることが多い。"},{"id":"3","text":"誇張して訴えることが多い。"},{"id":"4","text":"希死念慮がみられることが多い。"},{"id":"5","text":"抗うつ薬が効果的であることが多い。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！認知症は、判断力そのものが低下する、判断障害がみられることが多いんだ。仮性認知症（うつ病）では、2の不眠、3の誇張した訴え、4の希死念慮が目立ちやすく、5は抗うつ薬が効果的なのは、うつ病（仮性認知症）のほうだよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-078","examYear":"2021","examRound":"33","questionNumber":78,"category":"認知症の理解","questionText":"日本における認知症（dementia）の原因のうち、アルツハイマー型認知症（dementia of the Alzheimerʼs type）の次に多い疾患として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"血管性認知症（vascular dementia）"},{"id":"2","text":"前頭側頭型認知症（frontotemporal dementia）"},{"id":"3","text":"混合型認知症（mixed type dementia）"},{"id":"4","text":"レビー小体型認知症（dementia with Lewy bodies）"},{"id":"5","text":"アルコール性認知症（alcoholic dementia）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！日本での認知症の原因は、アルツハイマー型が最も多く、その次に多いのが、血管性認知症なんだ。2の前頭側頭型、3の混合型、4のレビー小体型、5のアルコール性は、血管性より少ないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-079","examYear":"2021","examRound":"33","questionNumber":79,"category":"認知症の理解","questionText":"日本での認知症（dementia）に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"アルツハイマー型認知症（dementia of the Alzheimerʼs type）以外の認知症（dementia）の患者数が増加している。"},{"id":"2","text":"アルツハイマー型認知症（dementia of the Alzheimerʼs type）の有病率は、男性より女性が高い。"},{"id":"3","text":"年齢が若いほど、認知症発症のリスクが高い。"},{"id":"4","text":"生活習慣病（life-style related disease）と認知症発症には関連がない。"},{"id":"5","text":"運動は認知症予防に無効である。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！アルツハイマー型認知症は、女性のほうが、男性より、有病率が高いとされているんだ。1はアルツハイマー型以外の患者数が特に増加しているとはいえない。3は年齢が高いほど発症リスクが高い。4は生活習慣病は認知症のリスクと関連がある。5は運動は予防に有効とされているよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-080","examYear":"2021","examRound":"33","questionNumber":80,"category":"認知症の理解","questionText":"認知症初期集中支援チームに関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"認知症（dementia）の人は病院への入院や施設への入所をするべきであるという考えに基づいている。"},{"id":"2","text":"既に認知症（dementia）の診断を受けている人への支援は含まれない。"},{"id":"3","text":"家族への支援は含まれない。"},{"id":"4","text":"支援期間は2～3年である。"},{"id":"5","text":"チーム員会議を開催してケア方針を決定する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！チームは、専門職が集まって、チーム員会議を開き、ケアの方針を検討・決定するんだ。1は入院・入所を前提とはしない。2はすでに診断を受けている人も対象になることがある。3は家族への支援も含まれる。4は支援期間はおおむね最大6か月とされているよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-081","examYear":"2021","examRound":"33","questionNumber":81,"category":"認知症の理解","questionText":"クロイツフェルト・ヤコブ病（Creutzfeldt-Jakob disease）に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"有病率は1万人に1人である。"},{"id":"2","text":"プリオン病である。"},{"id":"3","text":"認知症（dementia）の症状は緩やかに進行する場合が多い。"},{"id":"4","text":"致死率は低い。"},{"id":"5","text":"不随意運動は伴わない。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！クロイツフェルト・ヤコブ病は、プリオンという異常なたんぱく質が原因で起こる、プリオン病なんだ。1は有病率は100万人に1人程度とまれ。3は急速に進行することが多い。4は致死率は高い。5はミオクローヌスという不随意運動がみられることが多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-082","examYear":"2021","examRound":"33","questionNumber":82,"category":"認知症の理解","questionText":"レビー小体型認知症（dementia with Lewy bodies）に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"脳梗塞（cerebral infarction）が原因である。"},{"id":"2","text":"初発症状は記憶障害である。"},{"id":"3","text":"けいれんがみられる。"},{"id":"4","text":"人格変化がみられる。"},{"id":"5","text":"誤嚥性肺炎（ごえんせいはいえん）（aspiration pneumonia）の合併が多い。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！レビー小体型認知症は、パーキンソン症状で、飲み込む力が落ちやすく、誤嚥性肺炎を合併しやすいんだ。1は原因は脳梗塞ではない。2は初発症状は幻視やパーキンソン症状のことが多い。3はけいれんは特徴的な症状ではない。4は人格変化は前頭側頭型認知症で目立つよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-083","examYear":"2021","examRound":"33","questionNumber":83,"category":"認知症の理解","questionText":"Ｂさん（80歳、女性、要介護2）は、1年前にアルツハイマー型認知症（dementia of the Alzheimerʼs type）の診断を受け、服薬を継続している。同居の息子は日中不在のため、週に3回、訪問介護（ホームヘルプサービス）を利用し、訪問介護員（ホームヘルパー）と共に活発に会話や家事をしていた。不眠を強く訴えることが増えたため、1週間前に病院を受診したときに息子が主治医に相談した。その後、午前中うとうとしていることが多くなり、飲水時にむせることがあった。歩くとき、ふらつくようになったが、麻痺（まひ）はみられない。バイタルサイン（vital signs）に変化はなく、食欲・水分摂取量も保たれている。訪問介護員（ホームヘルパー）のＢさんと息子への言葉かけとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「日中は横になって過ごしたほうがよいでしょう」"},{"id":"2","text":"「歩行機能を保つためにリハビリを始めませんか」"},{"id":"3","text":"「嚥下障害（えんげしょうがい）が起きてますね」"},{"id":"4","text":"「処方薬が変更されていませんか」"},{"id":"5","text":"「認知症（dementia）が進行したのでしょう」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！不眠を相談してから、うとうとが増え、むせやふらつきが出てきたのは、薬の副作用の可能性があるんだ。だから、処方薬が変更されていないかを、確認するのがよいよ。1は日中横になるのを勧めると逆効果になりかねない。2、3、5は、まだ原因を確かめる前の決めつけた対応なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-084","examYear":"2021","examRound":"33","questionNumber":84,"category":"認知症の理解","questionText":"認知症（dementia）の原因疾患を鑑別するときに、慢性硬膜下血腫（chronic subdural hematoma）の診断に有用な検査として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"血液検査"},{"id":"2","text":"脳血流検査"},{"id":"3","text":"頭部ＣＴ検査"},{"id":"4","text":"脳波検査"},{"id":"5","text":"認知機能検査"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！慢性硬膜下血腫は、頭部CT検査で、血腫（血の塊）を、画像として確認できるんだ。1の血液検査、4の脳波検査、5の認知機能検査では、血腫そのものは確認できない。2の脳血流検査より、CT検査のほうが、血腫の診断には適しているよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-085","examYear":"2021","examRound":"33","questionNumber":85,"category":"認知症の理解","questionText":"認知症（dementia）に伴う注意障害に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"周囲から物音が聞こえてくると、食事を中断したままになる。"},{"id":"2","text":"毎日、同じ時間に同じ行動をする。"},{"id":"3","text":"旅行の計画を立てることが難しい。"},{"id":"4","text":"話そうとすることを言い間違える。"},{"id":"5","text":"介護職員から説明を受けたことを覚えていない。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！注意障害は、1つのことに注意を向け続けることが難しくなる障害なんだ。物音に気を取られて、食事に戻れなくなるのは、その例だよ。2は決まった行動を繰り返す常同行動。3は遂行機能障害。4は失語症の症状。5は記憶障害の症状で、注意障害とはちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-086","examYear":"2021","examRound":"33","questionNumber":86,"category":"認知症の理解","questionText":"Ｃさん（87歳、男性、要介護5）は、重度のアルツハイマー型認知症（dementia of the Alzheimerʼs type）である。現在、介護老人福祉施設に入所しているが終末期の状態にある。できる限り経口摂取を続けてきたが、誤嚥性肺炎（ごえんせいはいえん）（aspiration pneumonia）を繰り返し、経口摂取が困難となった。臥床状態（がしょうじょうたい）が続き、声かけに対する反応も少なくなっている。医師から、「死が極めて近い状態である」と伝えられた。施設で看取（みと）ることになっているＣさんへの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"離床している時間をつくる。"},{"id":"2","text":"会話によって本人の希望を聞く。"},{"id":"3","text":"事前指示書を作成する。"},{"id":"4","text":"苦痛があるかないか、状態を観察する。"},{"id":"5","text":"本人の好きな食事を用意する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！死が極めて近い状態では、本人が言葉で伝えられないことも多いから、苦痛の有無を、表情やしぐさから観察することが、最も大切なんだ。1は離床は体への負担が大きい。2、3は会話や指示書の作成はこの段階では難しい。5は経口摂取が困難な状態で食事の用意は現実的でないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-087","examYear":"2021","examRound":"33","questionNumber":87,"category":"障害の理解","questionText":"ＩＣＦ（International Classification of Functioning, Disability and Health：国際生活機能分類）の社会モデルに基づく障害のとらえ方に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"個人の問題としてとらえる。"},{"id":"2","text":"病気・外傷から直接的に生じる。"},{"id":"3","text":"さまざまな環境との相互作用によって生じる。"},{"id":"4","text":"治療してできるだけ回復させることを目的とする。"},{"id":"5","text":"医療などによる援助を必要とする。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！社会モデルは、障害は、個人の心身の状態だけでなく、社会や環境とのかかわりの中で生じると考えるんだ。1、2、4、5は、障害を個人の問題としてとらえる、医学モデルの考え方に近いよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-088","examYear":"2021","examRound":"33","questionNumber":88,"category":"障害の理解","questionText":"リハビリテーションに関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"語源は、「再び適したものにすること」である。"},{"id":"2","text":"ニィリエ（Nirje, B.）によって定義された。"},{"id":"3","text":"医療の領域に限定されている。"},{"id":"4","text":"自立生活運動とは関係がない。"},{"id":"5","text":"機能回復訓練は社会的リハビリテーションである。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！リハビリテーションの語源は、ラテン語で「再び（re）適した状態にする（habilis）」という意味なんだ。2はニィリエはノーマライゼーションの理念を広めた人物。3は医療だけでなく教育や職業なども含む。4は自立生活運動とも関係が深い。5は機能回復訓練は医学的リハビリテーションにあたるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-089","examYear":"2021","examRound":"33","questionNumber":89,"category":"障害の理解","questionText":"「Nothing about us without us（私たち抜きに私たちのことを決めるな）」の考え方のもとに、障害者が作成の段階から関わり、その意見が反映されて成立したものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"優生保護法"},{"id":"2","text":"国際障害者年"},{"id":"3","text":"知的障害者福祉法"},{"id":"4","text":"身体障害者福祉法"},{"id":"5","text":"障害者の権利に関する条約"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！「私たち抜きに私たちのことを決めるな」は、障害者権利条約の策定のときに、障害当事者が参加して、意見を反映させた合言葉なんだ。1の優生保護法、2の国際障害者年、3の知的障害者福祉法、4の身体障害者福祉法は、当事者参加を前提に作られたものではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-090","examYear":"2021","examRound":"33","questionNumber":90,"category":"障害の理解","questionText":"Ｄさん（31歳、男性）は、脊髄損傷（spinal cord injury）による対麻痺（ついまひ）で、リハビリテーションのため入院中である。車いすでの日常生活動作（Activities of Daily Living：ＡＤＬ）は自立したが、退院後自宅で生活するときに、褥瘡（じょくそう）が生じないか心配している。Ｄさんの褥瘡（じょくそう）が発生しやすい部位として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"頭部"},{"id":"2","text":"上腕部"},{"id":"3","text":"背部"},{"id":"4","text":"腹部"},{"id":"5","text":"坐骨結節部（ざこつけっせつぶ）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！対麻痺の人は、車いすで座っている時間が長いから、座ったときに体重がかかる、坐骨結節部に、褥瘡ができやすいんだ。1の頭部、2の上腕部、3の背部、4の腹部は、座っているときに、特に圧迫されやすい部位ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-091","examYear":"2021","examRound":"33","questionNumber":91,"category":"障害の理解","questionText":"脊髄の完全損傷で、プッシュアップが可能となる最上位のレベルとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"頸髄（けいずい）（Ｃ1～Ｃ3）"},{"id":"2","text":"頸髄（けいずい）（Ｃ7）"},{"id":"3","text":"胸髄"},{"id":"4","text":"腰髄"},{"id":"5","text":"仙髄"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！プッシュアップ（腕で体を持ち上げる動作）には、上腕三頭筋の力が必要で、これは第7頸髄（C7）まで機能が残っていると、可能になるんだ。1のC1〜C3では上肢もほとんど動かせない。3、4、5は上肢の機能は保たれるが、最上位のレベルとしてはC7が正解なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-092","examYear":"2021","examRound":"33","questionNumber":92,"category":"障害の理解","questionText":"筋ジストロフィー（muscular dystrophy）の病態について、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"網膜が変性する。"},{"id":"2","text":"運動神経が変性する。"},{"id":"3","text":"自己免疫が原因である。"},{"id":"4","text":"中脳の黒質が病変部位となる。"},{"id":"5","text":"筋線維に変性が生じる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！筋ジストロフィーは、遺伝子の異常によって、筋肉の線維（筋線維）が、少しずつ壊れていく病気なんだ。1の網膜の変性、2の運動神経の変性、3の自己免疫、4の中脳の黒質の病変は、それぞれ別の病気の特徴だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-093","examYear":"2021","examRound":"33","questionNumber":93,"category":"障害の理解","questionText":"「障害者虐待防止法」の心理的虐待に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"身体に外傷が生じるおそれのある暴行を加えること。"},{"id":"2","text":"わいせつな行為をすること。"},{"id":"3","text":"著しい暴言、または著しく拒絶的な対応を行うこと。"},{"id":"4","text":"衰弱させるような著しい減食、または長時間の放置を行うこと。"},{"id":"5","text":"財産を不当に処分すること。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！著しい暴言や、無視するような拒絶的な対応は、心のダメージを与える、心理的虐待にあたるんだ。1は身体的虐待、2は性的虐待、4は放棄・放置（ネグレクト）、5は経済的虐待の説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-094","examYear":"2021","examRound":"33","questionNumber":94,"category":"障害の理解","questionText":"心臓機能障害のある人に関する記述として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"塩分の制限は必要としない。"},{"id":"2","text":"呼吸困難や息切れなどの症状がみられることが多い。"},{"id":"3","text":"日常生活で外出を避けるべきである。"},{"id":"4","text":"ペースメーカーの装着者は、身体障害者手帳の交付対象から除外される。"},{"id":"5","text":"精神的なストレスの影響は少ない。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！心臓機能障害があると、心臓のポンプの働きが弱くなって、呼吸困難や息切れが、起こりやすいんだ。1は塩分の制限が必要。3は無理のない範囲で外出や活動は続ける。4はペースメーカーの装着者も手帳の対象になる。5は精神的なストレスも症状に影響するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-095","examYear":"2021","examRound":"33","questionNumber":95,"category":"障害の理解","questionText":"発達障害のＥさん（5歳、男性）の母親（28歳）は、Ｅさんのことを一生懸命に理解しようと頑張っている。しかし、うまくいかないことも多く、子育てに自信をなくし、どうしたらよいのかわからずに一人で悩んでいる様子が見られる。母親への支援に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"現状を受け入れるように説得する。"},{"id":"2","text":"一時的な息抜きのために、レスパイトケアを紹介する。"},{"id":"3","text":"同じ立場にあるペアレント・メンターを紹介する。"},{"id":"4","text":"Ｅさんへの発達支援を強化するように勧める。"},{"id":"5","text":"介護支援専門員（ケアマネジャー）を紹介する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！同じように発達障害のある子どもを育てた経験のある、ペアレント・メンターに出会うと、共感してもらえて、気持ちが楽になるんだ。1は説得は気持ちを追い詰める。2はレスパイトケアも助けになるが悩みそのものへの支援ではない。4は母親の悩みに応えていない。5はケアマネジャーは対象がちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-096","examYear":"2021","examRound":"33","questionNumber":96,"category":"障害の理解","questionText":"「2016年（平成28年）生活のしづらさなどに関する調査（全国在宅障害児・者等実態調査）」（厚生労働省）における身体障害者手帳所持者の日常的な情報入手手段として、最も割合が高いものを1つ選びなさい。","choices":[{"id":"1","text":"家族・友人・介助者"},{"id":"2","text":"パソコン"},{"id":"3","text":"携帯電話"},{"id":"4","text":"テレビ"},{"id":"5","text":"ラジオ"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！身体障害者手帳を持つ人の、日常的な情報入手手段として、最も割合が高いのは、テレビなんだ。1の家族・友人・介助者、2のパソコン、3の携帯電話、5のラジオも使われているけれど、テレビの利用率が、最も高いんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-097","examYear":"2021","examRound":"33","questionNumber":97,"category":"こころとからだのしくみ","questionText":"心的外傷後ストレス障害（posttraumatic stress disorder：ＰＴＳＤ）に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"原因となった体験が繰り返し思い起こされる。"},{"id":"2","text":"1か月以内で症状は治まる。"},{"id":"3","text":"小さな出来事が原因となる。"},{"id":"4","text":"被害妄想を生じる。"},{"id":"5","text":"気分が高ぶる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！PTSDでは、つらい体験が、フラッシュバックのように、繰り返し思い出されるのが、特徴的な症状なんだ。2は症状は1か月以上続く。3は命に関わるような大きな出来事が原因になる。4は被害妄想は中心症状ではない。5は気分が高ぶるというより不安や恐怖が強くなるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-098","examYear":"2021","examRound":"33","questionNumber":98,"category":"こころとからだのしくみ","questionText":"健康な人の体温に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高齢者の体温は小児より高い。"},{"id":"2","text":"早朝の体温が最も高い。"},{"id":"3","text":"腋窩温（えきかおん）は口腔温（こうくうおん）より高い。"},{"id":"4","text":"体温調節中枢は視床下部にある。"},{"id":"5","text":"環境の影響を受けない。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！体温を一定に保つ調節中枢は、脳の視床下部にあるんだ。1は高齢者の体温は小児より低め。2は体温が最も高いのは午後（夕方）ごろ。3は口腔温のほうが腋窩温より高い。5は体温は環境の影響を受けるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-099","examYear":"2021","examRound":"33","questionNumber":99,"category":"こころとからだのしくみ","questionText":"義歯を使用したときの影響として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"唾液分泌量が増加する。"},{"id":"2","text":"話す言葉が明瞭になる。"},{"id":"3","text":"舌の動きが悪くなる。"},{"id":"4","text":"口のまわりのしわが増える。"},{"id":"5","text":"味覚が低下する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！義歯を使うと、歯や口の形が補われて、発音がしやすくなり、話す言葉が明瞭になるんだ。1は唾液分泌量が増えるとは限らない。3は舌の動きはむしろ助けられる。4は口のまわりのしわは義歯によって減ることが多い。5は味覚が低下するとは限らないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-100","examYear":"2021","examRound":"33","questionNumber":100,"category":"こころとからだのしくみ","questionText":"1週間の安静臥床（あんせいがしょう）で筋力は何％程度低下するか、次のうちから最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"1％"},{"id":"2","text":"5％"},{"id":"3","text":"15％"},{"id":"4","text":"30％"},{"id":"5","text":"50％"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！1週間、体を動かさずに寝たきりでいると、筋力は、1日あたり約1〜3%ずつ低下して、1週間でおよそ15%程度、低下するといわれているんだ。安静は、思った以上に、体に大きな影響を与えるんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-101","examYear":"2021","examRound":"33","questionNumber":101,"category":"こころとからだのしくみ","questionText":"栄養素の働きに関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"たんぱく質は、最大のエネルギー源となる。"},{"id":"2","text":"ビタミンＤ（vitamin D）は、糖質をエネルギーに変える。"},{"id":"3","text":"カリウム（Ｋ）は、骨の形成に関わる。"},{"id":"4","text":"ビタミンＢ1（vitamin B1）は、カルシウム（Ca）の吸収に関わる。"},{"id":"5","text":"ナトリウム（Na）は、血圧の調節に関わる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！ナトリウムは、体内の水分量や、血圧の調節に関わっているんだ。1は最大のエネルギー源は炭水化物や脂質。2は糖質をエネルギーに変えるのは主にビタミンB1。3は骨の形成に関わるのはカルシウムやビタミンD。4はカルシウムの吸収を助けるのはビタミンDだよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-102","examYear":"2021","examRound":"33","questionNumber":102,"category":"こころとからだのしくみ","questionText":"Ｆさん（80歳、女性）は、普段の食事は自立している。日常生活では眼鏡がないと不自由である。ある日、いつもより食事に時間がかかっていた。介護福祉職が確認したところ、Ｆさんは、「眼鏡が壊れて使えなくなってしまった」と答えた。食事をとるプロセスで、Ｆさんが最も影響を受ける段階として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"先行期"},{"id":"2","text":"準備期"},{"id":"3","text":"口腔期（こうくうき）"},{"id":"4","text":"咽頭期"},{"id":"5","text":"食道期"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！先行期は、食べ物を目で見て、何か、どんな量かを認識する段階なんだ。眼鏡が壊れて見えにくいと、食べ物の認識に時間がかかって、食事全体に時間がかかるよ。2の準備期は口に入れて噛む、3の口腔期は舌で送る、4の咽頭期は飲み込む、5の食道期は食道を通る段階だね。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-103","examYear":"2021","examRound":"33","questionNumber":103,"category":"こころとからだのしくみ","questionText":"入浴（中温浴、38～41℃）の効果に関する次の記述のうち、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"脳が興奮する。"},{"id":"2","text":"筋肉が収縮する。"},{"id":"3","text":"血圧が上昇する。"},{"id":"4","text":"腎臓の働きを促進する。"},{"id":"5","text":"腸の動きを抑制する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！中温浴（38〜41℃）では、静水圧の作用で、血液の循環がよくなり、腎臓の働きも促進されるんだ。1は中温浴では脳はリラックスする。2は筋肉は弛緩する。3は血圧は大きくは上昇しない。5は腸の動きは促進されるよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-104","examYear":"2021","examRound":"33","questionNumber":104,"category":"こころとからだのしくみ","questionText":"Ｇさん（83歳、女性）は、認知機能は正常で、日常生活は杖歩行（つえほこう）で自立し外出もしていた。最近、外出が減ったため理由を尋ねたところ、咳（せき）やくしゃみで尿が漏れることが多いため外出を控えていると言った。Ｇさんの尿失禁として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"機能性尿失禁"},{"id":"2","text":"腹圧性尿失禁"},{"id":"3","text":"溢流性尿失禁（いつりゅうせいにょうしっきん）"},{"id":"4","text":"反射性尿失禁"},{"id":"5","text":"切迫性尿失禁"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！咳やくしゃみのように、おなかに力が入ったときに、尿が漏れるのは、腹圧性尿失禁の特徴なんだ。1の機能性尿失禁は認知や運動機能の問題。3の溢流性尿失禁は少しずつあふれ出る。4の反射性尿失禁は脊髄損傷などでみられる。5の切迫性尿失禁は急に強い尿意を感じて漏れるものだよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-105","examYear":"2021","examRound":"33","questionNumber":105,"category":"こころとからだのしくみ","questionText":"次のうち、便秘の原因として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"炎症性腸疾患（inflammatory bowel disease）"},{"id":"2","text":"経管栄養"},{"id":"3","text":"消化管切除"},{"id":"4","text":"感染性腸炎（infectious enteritis）"},{"id":"5","text":"長期臥床（ちょうきがしょう）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！長期間、寝たきりの状態が続くと、腸の動きが弱くなり、便秘になりやすいんだ。1の炎症性腸疾患や3の消化管切除、4の感染性腸炎は下痢を起こしやすい。2の経管栄養は便秘にも下痢にもなりうるけれど、長期臥床のほうが便秘の原因として、より代表的だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-106","examYear":"2021","examRound":"33","questionNumber":106,"category":"こころとからだのしくみ","questionText":"高齢者の睡眠の特徴に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"熟睡感が増加する。"},{"id":"2","text":"深睡眠が増加する。"},{"id":"3","text":"夜間の睡眠時間が増加する。"},{"id":"4","text":"睡眠周期が不規則になる。"},{"id":"5","text":"入眠までの時間が短縮する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！高齢になると、睡眠のリズム（周期）が乱れやすく、不規則になるんだ。1は熟睡感は減少する。2は深い眠り（深睡眠）は減少する。3は夜間の睡眠時間は短くなる。5は寝つくまでの時間は長くなることが多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-107","examYear":"2021","examRound":"33","questionNumber":107,"category":"こころとからだのしくみ","questionText":"睡眠に関する次の記述のうち、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"レム睡眠のときに夢を見る。"},{"id":"2","text":"レム睡眠から入眠は始まる。"},{"id":"3","text":"ノンレム睡眠では筋緊張が消失する。"},{"id":"4","text":"ノンレム睡眠では速い眼球運動がみられる。"},{"id":"5","text":"高齢者ではレム睡眠の時間が増加する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！レム睡眠は、眼球が素早く動く浅い眠りで、このときに夢を見ることが多いんだ。2は入眠はノンレム睡眠から始まる。3は筋緊張が消失するのはレム睡眠。4は速い眼球運動がみられるのはレム睡眠。5は高齢者ではレム睡眠の時間は減少するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-108","examYear":"2021","examRound":"33","questionNumber":108,"category":"こころとからだのしくみ","questionText":"死斑（しはん）が出現し始める時間として、正しいものを1つ選びなさい。","choices":[{"id":"1","text":"死後5分以内"},{"id":"2","text":"死後20～30分"},{"id":"3","text":"死後3時間"},{"id":"4","text":"死後8～12時間"},{"id":"5","text":"死後48時間"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！死斑は、血液が重力で体の下側に集まってできる、死後変化のひとつで、死後20〜30分ごろから、出現し始めるんだ。時間がたつほど、はっきりしていくよ。死後の身体の変化は、時間の経過とセットで、覚えておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-109","examYear":"2021","examRound":"33","questionNumber":109,"category":"医療的ケア","questionText":"介護福祉職が経管栄養を実施するときに、注入量を指示する者として、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"医師"},{"id":"2","text":"看護師"},{"id":"3","text":"訪問看護事業所の管理者"},{"id":"4","text":"訪問介護事業所の管理者"},{"id":"5","text":"介護支援専門員（ケアマネジャー）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！経管栄養の注入量は、医師が指示するものなんだ。介護福祉職は、医師の指示にもとづいて、実施するよ。2の看護師、3、4の管理者、5の介護支援専門員は、注入量を指示する立場ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-110","examYear":"2021","examRound":"33","questionNumber":110,"category":"医療的ケア","questionText":"気管粘膜のせん毛運動に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"痰（たん）の粘度が高いほうが動きがよい。"},{"id":"2","text":"空気中の異物をとらえる運動である。"},{"id":"3","text":"反射的に咳（せき）を誘発する。"},{"id":"4","text":"気管内部が乾燥しているほうが動きがよい。"},{"id":"5","text":"痰（たん）を口腔（こうくう）の方へ移動させる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！気管の内側にある線毛（せん毛）は、絶えず動いて、痰やほこりを、口のほうへ送り出す働きをしているんだ。1は粘度が低いほうが動きがよい。2は異物をとらえるのは粘液の役目。3は咳を直接誘発するのが主な役割ではない。4は内部は適度に湿っているほうが動きがよいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-111","examYear":"2021","examRound":"33","questionNumber":111,"category":"医療的ケア","questionText":"介護福祉職が実施する喀痰吸引（かくたんきゅういん）で、口腔内（こうくうない）と気管カニューレ内部の吸引に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"気管カニューレ内部の吸引では、カニューレの内径の3分の2程度の太さの吸引チューブを使用する。"},{"id":"2","text":"気管カニューレ内部の吸引では、滅菌された洗浄水を使用する。"},{"id":"3","text":"気管カニューレ内部の吸引では、頸部（けいぶ）を前屈した姿勢にして行う。"},{"id":"4","text":"吸引時間は、口腔内（こうくうない）より気管カニューレ内部のほうを長くする。"},{"id":"5","text":"吸引圧は、口腔内（こうくうない）より気管カニューレ内部のほうを高くする。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！気管カニューレの内部は、体の中の清潔な部分に近いから、滅菌された洗浄水を使うんだ。1は内径の2分の1程度の太さのチューブを使う。3は頸部は少し後屈させる。4は吸引時間はどちらも短くする。5は吸引圧は気管カニューレ内部のほうを低めにするよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-112","examYear":"2021","examRound":"33","questionNumber":112,"category":"医療的ケア","questionText":"Ｈさん（80歳、男性）は嚥下機能（えんげきのう）の低下があり、胃ろうを1か月前に造設して、自宅に退院した。現在、胃ろう周囲の皮膚のトラブルはなく、1日3回の経管栄養は妻と介護福祉職が分担して行っている。経管栄養を始めてから下肢の筋力が低下して、妻の介助を受けながらトイレへは歩いて行っている。最近、「便が硬くて出にくい」との訴えがある。Ｈさんに対して介護福祉職が行う日常生活支援に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"入浴時は、胃ろう部を湯につけないように注意する。"},{"id":"2","text":"排泄時は、胃ろう部を圧迫するように促す。"},{"id":"3","text":"排便は、ベッド上で行うように勧める。"},{"id":"4","text":"経管栄養を行っていないときの歩行運動を勧める。"},{"id":"5","text":"栄養剤の注入量を増やすように促す。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！便が硬くて出にくいＨさんには、歩行などの運動を勧めると、腸の動きが活発になって、排便を促す助けになるんだ。1は胃ろう部は入浴で湯につけても問題ない。2は圧迫は避ける。3はベッド上ではなくトイレでの排便が望ましい。5は注入量を勝手に増やしてはいけないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-113","examYear":"2021","examRound":"33","questionNumber":113,"category":"医療的ケア","questionText":"経管栄養の実施に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"経管栄養の準備は、石鹸（せっけん）と流水で丁寧に手を洗ってから行う。"},{"id":"2","text":"栄養剤は、消費期限の新しいものから使用する。"},{"id":"3","text":"胃ろうや腸ろう周囲の皮膚は、注入開始前にアルコール消毒を行う。"},{"id":"4","text":"カテーテルチップシリンジは、1回使用したら廃棄する。"},{"id":"5","text":"口腔（こうくう）ケアは、数日に1回行う。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！経管栄養は、感染を防ぐために、石鹸と流水で、しっかり手を洗ってから、準備を始めるんだ。2は消費期限の古いものから使う。3は周囲の皮膚は消毒ではなく石鹸とぬるま湯で洗う。4はシリンジは指示された方法で洗浄して繰り返し使うこともある。5は口腔ケアはこまめに行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-114","examYear":"2021","examRound":"33","questionNumber":114,"category":"総合問題","questionText":"（事例）Ｊさん（83歳、女性）は一人暮らしである。人と付き合うのが苦手で、近所付き合いもあまりなく、一人で静かに生活していた。80歳を過ぎた頃から右膝に痛みが出て、変形性膝関節症（へんけいせいしつかんせつしょう）（knee osteoarthritis）と診断されたが、近くのスーパーへの買物や、近所の散歩には出かけていた。1か月ほど前から膝の痛みが悪化し、散歩にも行かなくなった。食事量が減って痩せてきてしまい、一日中、座ってテレビを見て過ごしている。\n現在のＪさんに心配される病態として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"フレイル（frailty）"},{"id":"2","text":"不定愁訴"},{"id":"3","text":"寛解"},{"id":"4","text":"不穏"},{"id":"5","text":"せん妄（delirium）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｊさんは、痛みで外出が減り、食事量が減って痩せて、一日中座って過ごすようになっているね。これは、心身の活力が低下する、フレイルの状態なんだ。2の不定愁訴は、はっきりしない体調不良の訴え、3の寛解は病気が落ち着いた状態、4の不穏、5のせん妄は、事例の様子とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-115","examYear":"2021","examRound":"33","questionNumber":115,"category":"総合問題","questionText":"Ｊさんは、食事量は回復したが、膝に痛みがあり、家の中ではつかまり歩きをしていた。要介護認定を受けたところ要支援2と判定され、家の近くの第一号通所事業（通所型サービス）を利用することになった。通所初日、車で迎えに行くと、Ｊさんは、「心配だからやっぱり行くのはやめようかしら」と介護福祉職に言い、玄関の前からなかなか動かなかった。このときの介護福祉職の言葉かけとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「急ぎましょう。すぐに車に乗ってください」"},{"id":"2","text":"「心配なようですから、お休みにしましょう」"},{"id":"3","text":"「歩けないようでしたら、車いすを用意しましょうか」"},{"id":"4","text":"「初めてだから心配ですね。私もそばにいるので一緒に行きませんか」"},{"id":"5","text":"「Ｊさんが行かないと、皆さん困ってしまいますよ」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｊさんの不安な気持ちを受け止めて、一緒にいるから大丈夫だと伝えると、安心して一歩を踏み出しやすいんだ。1は急かしている。2は不安に負けて後押ししない。3は歩けないと決めつけている。5は周りを気にさせてプレッシャーを与えてしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-116","examYear":"2021","examRound":"33","questionNumber":116,"category":"総合問題","questionText":"その後、Ｊさんは少しずつ回復し、膝の痛みもなく、家の中では何もつかまらずに歩くことができている。一人で散歩に出ようという意欲も出てきた。Ｊさんは、介護福祉職にもっと安定して歩けるように練習をしていきたいことや、外出するときは膝の負担を減らすために杖（つえ）を使用したいと思っていることを話した。Ｊさんに合った、杖（つえ）を使った歩き方として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"杖（つえ）（左手で持つ）を出す→右足を出す→左足を出す"},{"id":"2","text":"杖（つえ）（右手で持つ）を出す→左足を出す→右足を出す"},{"id":"3","text":"杖（つえ）（左手で持つ）と右足を出す→左足を出す"},{"id":"4","text":"杖（つえ）（右手で持つ）と左足を出す→右足を出す"},{"id":"5","text":"杖（つえ）（左手で持つ）と左足を出す→右足を出す"}],"correctChoice":"1,2,3,4,5","correctChoices":["1","2","3","4","5"],"explanation":"この問題は、選択肢に正しい組合せがなく、「問題として成立していない」と公式に扱われていて、正答はないんだ（採点対象外だよ）。杖を使った3動作歩行の基本は、「杖→患側の足→健側の足」の順で、杖は健側（つえの反対側の手）で持つこと。この基本だけ、押さえておこうね。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-117","examYear":"2021","examRound":"33","questionNumber":117,"category":"総合問題","questionText":"（事例）Ｋさん（80歳、女性）は夫が亡くなった後、自宅で一人暮らしをしていた。ある日、一人娘のＬさんが訪ねると、ごみが散乱しており、冷蔵庫の中には古くなった食材がたくさん入っていた。変化に驚いたＬさんはＫさんと病院を受診したところ、認知症（dementia）と診断された。Ｌさんは、Ｋさんに家庭的な雰囲気の中で生活をしてほしいと考えた。その結果、Ｋさんは認知症対応型共同生活介護（グループホーム）を利用することになった。入居して1週間が経過し、Ｋさんと関わったＭ介護福祉職は、Ｋさんは短期記憶の低下により、最近の出来事については話すことは難しいが、自分が学校に通っていた頃の話や、子どもの頃に歌っていた歌については生き生きと話すことを確認した。\nＭ介護福祉職は、Ｋさんが今持っている認知能力を活用して、ほかの利用者と交流する機会を作りたいと考え、Ｋさんとほかの利用者に参加してもらう活動を企画することにした。Ｍ介護福祉職が企画した活動の手法として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"リアリティ・オリエンテーション（reality orientation）"},{"id":"2","text":"ピアカウンセリング（peer counseling）"},{"id":"3","text":"スーパービジョン（supervision）"},{"id":"4","text":"回想法"},{"id":"5","text":"社会生活技能訓練"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｋさんは、学生時代や子どもの頃の歌については、生き生きと話せるんだね。昔の思い出を語り合う、回想法をいかした活動が、その力を生かせるよ。1のリアリティ・オリエンテーション、2のピアカウンセリング、3のスーパービジョン、5の社会生活技能訓練は、ここでの企画とはちがうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-118","examYear":"2021","examRound":"33","questionNumber":118,"category":"総合問題","questionText":"ある日、Ｍ介護福祉職がＫさんの入浴介護を行っていたところ、手のひらや指の間に赤い丘疹（きゅうしん）を確認した。Ｍ介護福祉職がＫさんに、「かゆくないですか」と聞くと、「かゆい」と答えた。そのため、病院を受診したところ、角化型疥癬（かくかがたかいせん）（hyperkeratotic scabies）と診断された。Ｋさんへの介護福祉職の対応として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"入浴後の洗濯物は、ビニール袋に入れて運ぶ。"},{"id":"2","text":"マスクを着けてもらう。"},{"id":"3","text":"個室に隔離する必要はない。"},{"id":"4","text":"介護は素手で行う。"},{"id":"5","text":"ほかの利用者よりも先に入浴してもらう。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！角化型疥癬は、感染力がとても強いから、洗濯物は、ビニール袋に入れて運び、ほかの物に広げないようにするんだ。2はマスクより手袋やガウンの着用が重要。3は個室での隔離が必要。4は素手ではなく手袋を着けて介護する。5はほかの利用者よりあとに入浴するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-119","examYear":"2021","examRound":"33","questionNumber":119,"category":"総合問題","questionText":"認知症対応型共同生活介護（グループホーム）を利用するＫさんの要介護度に変更があった場合に影響があるものとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護保険料"},{"id":"2","text":"認知症対応型共同生活介護費"},{"id":"3","text":"介護サービスの利用者負担割合"},{"id":"4","text":"食費"},{"id":"5","text":"居住費"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！グループホームの介護報酬（認知症対応型共同生活介護費）は、要介護度に応じて、金額が変わるんだ。1の介護保険料、4の食費、5の居住費は、要介護度が変わっても基本的に変わらない。3の利用者負担割合は、所得によって決まり、要介護度では変わらないよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-120","examYear":"2021","examRound":"33","questionNumber":120,"category":"総合問題","questionText":"（事例）Ａさん（10歳、男性）は、自閉症スペクトラム障害（autism spectrum disorder）であり、多動で発語は少ない。毎日のように道路に飛び出してしまったり、高い所に登ったりするなど、危険の判断ができない。また、感情の起伏が激しく、パニックになると止めても壁に頭を打ちつけ、気持ちが高ぶると騒ぎ出す。お金の使い方がわからないため好きなものをたくさん買おうとする。現在は、特別支援学校に通っており、普段の介護は母親が一人で担っている。\nＡさんのこのような状態に該当するものとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"注意障害"},{"id":"2","text":"遂行機能障害"},{"id":"3","text":"強度行動障害"},{"id":"4","text":"記憶障害"},{"id":"5","text":"気分障害"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！自傷行為やパニック、危険の判断ができないなど、激しい行動が頻繁にみられる状態は、強度行動障害にあたるんだ。1の注意障害、2の遂行機能障害、4の記憶障害は、高次脳機能障害の症状。5の気分障害は、うつ病などの病気で、Ａさんの状態とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-121","examYear":"2021","examRound":"33","questionNumber":121,"category":"総合問題","questionText":"Ａさんの将来を考え、家族以外の支援者と行動できるようにすることを目標に障害福祉サービスを利用することになった。介護福祉職と一緒に散歩に行き、外出時のルールを覚えたり、移動中の危険回避などの支援を受けている。Ａさんが利用しているサービスとして、適切なものを1つ選びなさい。","choices":[{"id":"1","text":"同行援護"},{"id":"2","text":"自立生活援助"},{"id":"3","text":"自立訓練"},{"id":"4","text":"生活介護"},{"id":"5","text":"行動援護"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！行動援護は、知的障害や精神障害があって、行動するときに危険を回避することが難しい人の、外出時の支援を行うサービスなんだ。1の同行援護は視覚障害のある人向け。2の自立生活援助は一人暮らしの人向け。3の自立訓練は生活能力の訓練。4の生活介護は日中活動の場だよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-122","examYear":"2021","examRound":"33","questionNumber":122,"category":"総合問題","questionText":"Ａさんのサービス利用開始から6か月が経ち、支援の見直しをすることになった。Ａさんの現状は、散歩では周囲を気にせず走り出すなど、まだ危険認知ができていない。介護福祉職はルールを守ることや周りに注意するように声かけをするが、注意されるとイライラし、パニックになることがある。一方で、スーパーではお菓子のパッケージを見て、硬貨を出し、長時間その場から動こうとしない。介護福祉職は、Ａさんがお菓子とお金に注目している様子から、その力を引き出す支援を特別支援学校に提案した。介護福祉職が特別支援学校に提案した支援の背景となる考え方として、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"エンパワメント（empowerment）"},{"id":"2","text":"アドボカシー（advocacy）"},{"id":"3","text":"ピアサポート（peer support）"},{"id":"4","text":"ノーマライゼーション（normalization）"},{"id":"5","text":"インクルージョン（inclusion）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ａさんが、お菓子とお金に注目している様子から、その力を引き出そうとするのは、本人の強みや可能性を生かす、エンパワメントの考え方にもとづいているんだ。2のアドボカシーは代弁、3のピアサポートは支え合い、4のノーマライゼーションは普通の生活、5のインクルージョンは包摂で、ちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-123","examYear":"2021","examRound":"33","questionNumber":123,"category":"総合問題","questionText":"（事例）Ｂさん（45歳、女性）はアパートで一人暮らしをしていた。家族や親戚との付き合いはなかったが、趣味も多く、充実した生活を送っていた。ある日、車で買物に行く途中、交通事故を起こし、Ｕ病院に救急搬送され手術を受けた。手術の数日後、医師から、頸髄損傷（けいずいそんしょう）（cervical cord injury）があり、第5頸髄節（だいけいずいせつ）まで機能残存するための手術をしたこと、今後の治療方針、リハビリテーションによって今後の生活がどこまで可能になるかについて、丁寧に説明を受けた。\nＢさんの今後の生活に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自力歩行ができる。"},{"id":"2","text":"自走式標準型車いすを自分で操作して、一人で外出することができる。"},{"id":"3","text":"自発呼吸が困難になり、人工呼吸器が必要な生活になる。"},{"id":"4","text":"電動車いすを自分で操作することが可能になる。"},{"id":"5","text":"指を使った細かい作業が可能になる。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！第5頸髄節まで機能が残っていると、肘を曲げる力は保たれていて、電動車いすのジョイスティックなどを、自分で操作できるようになることが多いんだ。1は下肢の麻痺で歩行は難しい。2は自走式車いすの操作は上肢の力が足りず難しい。3は呼吸筋は保たれることが多い。5は指の細かい動きは難しいことが多いんだ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":false},{"id":"2021-33-124","examYear":"2021","examRound":"33","questionNumber":124,"category":"総合問題","questionText":"Ｂさんは、入院当初は落ち込んでいたが、徐々に表情が明るくなり、Ｕ病院でのリハビリテーションにも積極的に取り組むようになった。現在はＶリハビリテーション病院に転院して、退院後の生活に向けて身体障害者手帳を取得し、準備を進めている。Ｂさんは、以前のようなアパートでの一人暮らしはすぐには難しいと考え、障害者支援施設への入所を考えている。障害者支援施設に入所するために、Ｂさんがこの時期に行う手続きとして、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"居宅サービス計画を作成するために、介護支援専門員（ケアマネジャー）に相談する。"},{"id":"2","text":"要介護認定を受けるために、市町村の窓口に申請する。"},{"id":"3","text":"施設サービス計画を作成するために、介護支援専門員（ケアマネジャー）に相談する。"},{"id":"4","text":"サービス等利用計画を作成するために、相談支援専門員に相談する。"},{"id":"5","text":"障害支援区分の認定を受けるために、市町村の窓口に申請する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害者支援施設に入所するには、まず、市町村の窓口で、障害支援区分の認定を申請することが必要なんだ。1、3は介護保険の計画で、Ｂさんは45歳なので対象外。2は要介護認定も介護保険の手続き。4のサービス等利用計画の相談は、区分認定のあとに行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2021-33-125","examYear":"2021","examRound":"33","questionNumber":125,"category":"総合問題","questionText":"その後、Ｂさんは希望どおり障害者支援施設に入所した。入所した施設では、Ｃ介護福祉職がＢさんの担当になった。Ｃ介護福祉職は、Ｂさんから、「日常生活で、もっと自分でできることを増やし、いずれは地域で生活したい」と言われた。そこでＣ介護福祉職は、施設内の他職種と連携して支援を行う必要があると考えた。Ｃ介護福祉職が連携する他職種とその業務内容に関する次の記述のうち、最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"工作などの作業を行いながら身体機能の回復を図るために、看護師と連携する。"},{"id":"2","text":"運動機能の維持・改善を図るために、理学療法士と連携する。"},{"id":"3","text":"趣味活動を増やすことを目的に、管理栄養士と連携する。"},{"id":"4","text":"活用できる地域のインフォーマルサービスを検討するために、義肢装具士と連携する。"},{"id":"5","text":"栄養状態の面から健康増進を図るために、社会福祉士と連携する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！運動機能の維持や改善を目指すときは、理学療法士と連携するのが適切なんだ。1は身体機能の回復は作業療法士や理学療法士の役割。3は趣味活動は作業療法士など。4はインフォーマルサービスの検討は相談支援専門員や社会福祉士。5は栄養状態は管理栄養士と連携するよ。","source":"公益財団法人 社会福祉振興・試験センター 第33回（令和2年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/; 問116の不成立取扱い: https://www.mhlw.go.jp/content/12004000/000757038.pdf","keywords":[],"needsLegalReview":true},{"id":"2020-32-001","examYear":"2020","examRound":"32","questionNumber":1,"category":"人間の尊厳と自立","questionText":"Ａさん（78歳，女性，要介護3）は，訪問介護（ホームヘルプサービス）を利用している。72歳から人工透析を受けている。透析を始めた頃から死を意識するようになり，延命治療を選択する意思決定の計画書を作成していた。しかし，最近では，最期の時を自宅で静かに過ごしたいと思い，以前の計画のままでよいか気持ちに迷いが出てきたので，訪問介護（ホームヘルプサービス）のサービス提供責任者に相談した。サービス提供責任者の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「この計画書は，医療職が作成するものですよ」"},{"id":"2","text":"「一度作成した計画書は，個人の意向で変更するのは難しいですよ」"},{"id":"3","text":"「意思確認のための話合いは，何度でもできますよ」"},{"id":"4","text":"「そんなに心配なら，特別養護老人ホームに入所できますよ」"},{"id":"5","text":"「この計画書は，在宅ではなく病院での治療を想定したものですよ」"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！人生の最終段階の医療・ケアの計画は、一度決めたら終わりではなく、気持ちの変化に合わせて、何度でも話し合って見直せるものなんだ。1は、本人や家族の思いを聞く介護職の役割を否定している。2は、変更できないと決めつけている。4は、施設入所を急かしている。5は、事実とちがう説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-002","examYear":"2020","examRound":"32","questionNumber":2,"category":"人間の尊厳と自立","questionText":"利用者の意思を代弁することを表す用語として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"インフォームドコンセント（informed consent）"},{"id":"2","text":"ストレングス（strength）"},{"id":"3","text":"パターナリズム（paternalism）"},{"id":"4","text":"エンパワメント（empowerment）"},{"id":"5","text":"アドボカシー（advocacy）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！アドボカシーは、自分の意思をうまく伝えられない人に代わって、その人の思いを代弁し、権利を守る活動のことなんだ。1のインフォームドコンセントは説明と同意、2のストレングスは強み、3のパターナリズムは温情的な干渉、4のエンパワメントは力を引き出すことで、代弁とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-003","examYear":"2020","examRound":"32","questionNumber":3,"category":"人間関係とコミュニケーション","questionText":"他者とのコミュニケーションを通した自己覚知として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自己の弱みより強みを重視する。"},{"id":"2","text":"自己の感情の動きとその背景を洞察する。"},{"id":"3","text":"自己の行動を主観的に分析する。"},{"id":"4","text":"自己の私生活を打ち明ける。"},{"id":"5","text":"自己の価値観を他者に合わせる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！自己覚知は、自分の感情がどう動くか、その背景に何があるかを、深く見つめることなんだ。1は強みだけを重視、3は主観的な分析、4は私生活を話すこと、5は自分を他者に合わせることで、自己覚知の説明としては、ふさわしくないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-004","examYear":"2020","examRound":"32","questionNumber":4,"category":"人間関係とコミュニケーション","questionText":"高齢者とのコミュニケーションにおける配慮として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"相手と視線が合わせられる位置で話す。"},{"id":"2","text":"相手には座ってもらい，自分は立ったまま話す。"},{"id":"3","text":"初対面のときから相手と密着した距離で話す。"},{"id":"4","text":"相手の表情があまり見えない薄暗い場所で話す。"},{"id":"5","text":"たくさんの人がいる，にぎやかな場所で話す。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！高齢者と話すときは、相手と視線の高さを合わせられる位置で話すと、安心して会話できるんだ。2は立ったままだと威圧感を与える。3は初対面から密着すると不快に感じる。4は表情が見えないと不安になる。5はにぎやかな場所は聞き取りにくいよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-005","examYear":"2020","examRound":"32","questionNumber":5,"category":"社会の理解","questionText":"地域包括ケアシステムでの自助・互助・共助・公助に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自助は，公的扶助を利用して，自ら生活を維持することをいう。"},{"id":"2","text":"互助は，社会保険のように制度化された相互扶助をいう。"},{"id":"3","text":"共助は，社会保障制度に含まれない。"},{"id":"4","text":"共助は，近隣住民同士の支え合いをいう。"},{"id":"5","text":"公助は，自助・互助・共助では対応できない生活困窮等に対応する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！公助は、自助・互助・共助では対応できない、生活困窮などに対応する、生活保護などの公的な支援のことなんだ。1は、自助は自分自身の力で生活すること。2は、互助ではなく共助の説明。3は、共助（社会保険など）は社会保障制度に含まれる。4は、共助ではなく互助の説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-006","examYear":"2020","examRound":"32","questionNumber":6,"category":"社会の理解","questionText":"「働き方改革」の考え方に関する記述として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"長時間労働は日本社会の特質で，時間外労働の限度の設定は困難である。"},{"id":"2","text":"有給休暇の取得よりも，働くことが優先される。"},{"id":"3","text":"働く人々のニーズに応じた，多様な働き方を選択できる社会の実現を図る。"},{"id":"4","text":"正規雇用労働者と非正規雇用労働者の待遇の格差が存在することは，当然である。"},{"id":"5","text":"「働き方改革」は，中小企業は対象でない。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！働き方改革は、働く人々のニーズに応じて、多様な働き方を選べる社会の実現をめざしているんだ。1は時間外労働の上限が設定された。2は有給休暇の取得も推進される。4は待遇の格差の是正がめざされている。5は中小企業も対象に含まれるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-007","examYear":"2020","examRound":"32","questionNumber":7,"category":"社会の理解","questionText":"Ｂさん（80歳，女性，要介護1）は，身寄りがなく一人暮らしをしている。老齢基礎年金で暮らしてきたが，貯金が少なくなり，生活が苦しくなってきた。このため2万円の家賃支払いも困難になり，通所介護事業所のＣ生活相談員に，費用がかかる通所介護（デイサービス）の利用をやめたいと言ってきた。Ｃ生活相談員の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護支援専門員（ケアマネジャー）に，通所介護（デイサービス）の利用中止を依頼する。"},{"id":"2","text":"介護支援専門員（ケアマネジャー）に，サービス担当者会議で利用中止の検討を依頼する。"},{"id":"3","text":"福祉事務所に相談するように助言する。"},{"id":"4","text":"これまでどおりの利用を説得する。"},{"id":"5","text":"無料で利用できる地域の通所型サービスを探す。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｂさんは、年金だけでは生活が苦しくなっているので、生活保護などの相談ができる、福祉事務所を紹介するのがよいんだ。1、2は、サービスをやめる方向で進めてしまう。4は、経済的な問題を解決せずに説得している。5は、根本的な生活の困窮への対応にならないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-008","examYear":"2020","examRound":"32","questionNumber":8,"category":"社会の理解","questionText":"2015年度（平成27年度）以降の社会保障の財政に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"後期高齢者医療制度の財源で最も割合が大きいものは，後期高齢者の保険料である。"},{"id":"2","text":"社会保障給付費の財源では，税の占める割合が最も大きい。"},{"id":"3","text":"生活保護費の財源内訳は，社会保険料と税である。"},{"id":"4","text":"国の一般会計予算に占める社会保障関係費の割合は，30％を超えている。"},{"id":"5","text":"社会保障給付費の給付額では，医療費の構成割合が最も大きい。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！国の一般会計予算に占める社会保障関係費の割合は、30%を超えていて、大きな割合を占めているんだ。1は、後期高齢者医療の財源で最も大きいのは公費。2は、税より社会保険料の割合が大きい。3は、生活保護費は全額公費。5は、給付額で最も大きいのは年金だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-009","examYear":"2020","examRound":"32","questionNumber":9,"category":"社会の理解","questionText":"介護保険制度の被保険者に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"加入は任意である。"},{"id":"2","text":"第一号被保険者は，65歳以上の者である。"},{"id":"3","text":"第二号被保険者は，20歳以上65歳未満の医療保険加入者である。"},{"id":"4","text":"第一号被保険者の保険料は，都道府県が徴収する。"},{"id":"5","text":"第二号被保険者の保険料は，国が徴収する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護保険の第一号被保険者は、65歳以上の者なんだ。1は40歳以上は加入が義務。3は第二号被保険者は40歳以上65歳未満の医療保険加入者。4は第一号の保険料は市町村が徴収する。5は第二号の保険料は医療保険者が徴収するよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-010","examYear":"2020","examRound":"32","questionNumber":10,"category":"社会の理解","questionText":"介護予防・日常生活支援総合事業に含まれる事業として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族介護支援事業"},{"id":"2","text":"予防給付"},{"id":"3","text":"介護給付"},{"id":"4","text":"権利擁護事業"},{"id":"5","text":"第一号訪問事業（訪問型サービス）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護予防・日常生活支援総合事業には、第一号訪問事業（訪問型サービス）などが含まれるんだ。1の家族介護支援事業と4の権利擁護事業は、包括的支援事業に含まれる。2の予防給付と3の介護給付は、総合事業とは別の、介護保険の保険給付だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-011","examYear":"2020","examRound":"32","questionNumber":11,"category":"社会の理解","questionText":"障害福祉計画に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"厚生労働大臣は基本的な指針を定めなければならない。"},{"id":"2","text":"都道府県による策定は努力義務である。"},{"id":"3","text":"市町村による策定は努力義務である。"},{"id":"4","text":"障害児福祉計画とは計画期間が異なっている。"},{"id":"5","text":"文化芸術活動・スポーツの振興についての目標設定をしなければならない。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！障害福祉計画では、厚生労働大臣が、基本的な指針を定めなければならないと定められているんだ。2は都道府県の策定は義務。3は市町村の策定も義務。4は障害児福祉計画も同じ期間で一体的に策定される。5は目標設定は努力義務だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-012","examYear":"2020","examRound":"32","questionNumber":12,"category":"社会の理解","questionText":"Ｄさん（60歳，女性）は，交通事故で下肢に障害が生じた。現在，入院中のＤさんは退院後，在宅での生活を続けるために，「障害者総合支援法」の障害福祉サービス（居宅介護）の利用を希望している。Ｄさんが障害福祉サービス（居宅介護）を利用するための最初の手続きとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"地域包括支援センターに相談する。"},{"id":"2","text":"医師の診断書を居住する市町村に提出する。"},{"id":"3","text":"障害福祉サービス（居宅介護）を提供している事業所と契約する。"},{"id":"4","text":"居住する市町村の審査会に，障害福祉サービス（居宅介護）の利用を申し出る。"},{"id":"5","text":"居住する市町村の担当窓口に，障害福祉サービス（居宅介護）の支給申請をする。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！障害福祉サービスを利用するための最初の手続きは、居住する市町村の窓口に、支給申請をすることなんだ。1は市町村の障害福祉の窓口が担当。2は診断書の提出だけでは申請にならない。3は支給決定の前に契約はできない。4は審査会は区分の審査を行う場だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-013","examYear":"2020","examRound":"32","questionNumber":13,"category":"社会の理解","questionText":"2018年度（平成30年度）に創設された共生型サービスの対象となるサービスとして，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"訪問看護"},{"id":"2","text":"共同生活援助（グループホーム）"},{"id":"3","text":"同行援護"},{"id":"4","text":"通所介護（デイサービス）"},{"id":"5","text":"通所リハビリテーション"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！共生型サービスは、高齢者と障害者が同じ事業所で、サービスを受けられる仕組みで、通所介護（デイサービス）が対象になっているんだ。1の訪問看護、2のグループホーム、3の同行援護、5の通所リハビリテーションは、共生型サービスの対象には含まれないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-014","examYear":"2020","examRound":"32","questionNumber":14,"category":"社会の理解","questionText":"自閉症（autism）のＥさん（22歳，男性，障害支援区分5）は，就労支援施設に通所している。こだわりが強く，毎月購入している雑誌を処分するとパニックになってしまう。「障害者虐待防止法」の視点を踏まえて，Ｅさんの気持ちが安定するように，施設の介護福祉職がＥさんにかける言葉として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「決まりですから捨てますよ」"},{"id":"2","text":"「読みたい雑誌はとっておきましょう」"},{"id":"3","text":"「古紙として再生利用しますからね」"},{"id":"4","text":"「Ｅさんにこの雑誌をあげるわけにはいかないんですよ」"},{"id":"5","text":"「次の新しい雑誌がきますよ」"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｅさんのこだわりを否定せず、「読みたい雑誌はとっておきましょう」と伝えると、気持ちが安定しやすいんだ。1、3、4は、雑誌を処分する前提で、Ｅさんの不安を強めてしまう。5は、雑誌が変わることへの不安には、答えられていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-015","examYear":"2020","examRound":"32","questionNumber":15,"category":"社会の理解","questionText":"成年後見制度に関する次の記述のうち，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「2018年（平成30年）の全国統計」によれば，補助，保佐，後見のうち，最も多い申立ては後見である。"},{"id":"2","text":"「2018年（平成30年）の全国統計」によれば，親族後見人が7割を占めている。"},{"id":"3","text":"成年後見人は，施設入所の契約だけでなく介護も行う。"},{"id":"4","text":"任意後見制度では，候補者の中から家庭裁判所が成年後見人を選任する。"},{"id":"5","text":"成年後見制度利用支援事業では，成年後見人への報酬は支払えない。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！2018年の統計では、補助・保佐・後見のうち、最も多い申立ては、後見だったんだ。2は親族後見人の割合は当時2割程度。3は成年後見人は契約などの法律行為が中心で介護そのものは行わない。4は任意後見は本人が事前に選ぶ。5は報酬の助成が行われることもあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-016","examYear":"2020","examRound":"32","questionNumber":16,"category":"社会の理解","questionText":"生活保護法における補足性の原理の説明として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"国の責任において保護を行う。"},{"id":"2","text":"全ての国民に無差別平等な保護を行う。"},{"id":"3","text":"健康で文化的な生活を維持できる保護を行う。"},{"id":"4","text":"資産・能力等を活用した上で保護を行う。"},{"id":"5","text":"個人または世帯の必要に応じて保護を行う。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！補足性の原理は、資産や能力、他の制度などを、活用したうえで、それでも足りない部分を、生活保護で補うという考え方なんだ。1は国家責任の原理、2は無差別平等の原理、3は最低生活保障の原理、5は必要即応の原則の説明だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-017","examYear":"2020","examRound":"32","questionNumber":17,"category":"介護の基本","questionText":"Ｆさん（72歳，女性，要介護2）は，中等度の認知症（dementia）があり，自宅で夫と生活している。ある日，訪問介護員（ホームヘルパー）が訪問すると，夫が散乱したコーヒー豆を片づけていた。Ｆさんは，「わからなくなっちゃった」と言っていた。訪問介護員（ホームヘルパー）が夫に事情を聞くと，「今も日課でコーヒーを豆から挽いて入れてくれるんだが，最近は失敗することが多くなって，失敗すると自信を失ってしまうしね。でも，毎朝，『コーヒーを入れなくちゃ』と言うんだ」と寂しそうに話した。訪問介護員（ホームヘルパー）の夫への助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「そばにいて，Ｆさんと一緒にコーヒーを入れてはどうですか」"},{"id":"2","text":"「Ｆさんと一緒に，喫茶店にコーヒーを飲みに行ってはどうですか」"},{"id":"3","text":"「おいしいコーヒーを買ってきて二人で飲んではどうですか」"},{"id":"4","text":"「私がＦさんからコーヒーの入れ方を教えてもらいましょうか」"},{"id":"5","text":"「新しいコーヒーメーカーを買ってはどうですか」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｆさんは、毎朝コーヒーを入れる日課を続けたいと思っているんだね。そばで見守りながら、一緒にコーヒーを入れることで、Ｆさんの役割を残しつつ、失敗の不安を減らせるよ。2、3は、日課そのものをやめさせてしまう。4は、役割を奪う。5は、新しい機器で混乱させかねないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-018","examYear":"2020","examRound":"32","questionNumber":18,"category":"介護の基本","questionText":"Ｇさん（80歳，女性，要介護3）は，脳卒中（stroke）の後遺症により左片麻痺があり，からだを思うようにコントロールができず，ふらつきが見られる。以前は，2週間に一度は美容院で長い髪をセットしてもらい，俳句教室に行くのを楽しみにしていた。病気になってからは落ち込むことが増え，介護が必要になったため，介護老人福祉施設に入所した。ノーマライゼーション（normalization）の考え方を踏まえた，Ｇさんへの生活支援として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"洗髪しやすいように，長い髪のカットを勧める。"},{"id":"2","text":"共同生活のため，夕食は施設の時間に合わせてもらう。"},{"id":"3","text":"落ち込んでいるため，居室での生活を中心に過ごしてもらう。"},{"id":"4","text":"おしゃれをして，施設の俳句クラブに参加するように勧める。"},{"id":"5","text":"転倒予防のため，車いすを使用してもらう。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ノーマライゼーションは、障害や病気があっても、これまでの生活を続けられるようにする考え方なんだ。おしゃれをして、好きだった俳句クラブに参加するのは、その人らしい生活の継続だよ。1は好きな長い髪を切らせる、2、3、5は、本人の楽しみや自由を制限しているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-019","examYear":"2020","examRound":"32","questionNumber":19,"category":"介護の基本","questionText":"ＩＣＦ（International Classification of Functioning，Disability and Health：国際生活機能分類）の視点に基づく環境因子と心身機能の関連を表す記述として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"電気スタンドをつけて，読書を楽しむ。"},{"id":"2","text":"車いすを使用して，美術館に行く。"},{"id":"3","text":"聴力が低下すると，コミュニケーションがうまくとれない。"},{"id":"4","text":"ストレスが溜まると，活力が低下する。"},{"id":"5","text":"床面の性状が柔らかいと，バランスを崩す。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！床面が柔らかいと、足元が不安定になって、バランスを崩しやすいよね。これは、環境因子（床の性状）が、心身機能（バランス）に影響する例なんだ。1、2は活動の例、3、4は心身機能そのものの説明で、環境因子との関連を表す記述としては、5が最も適切だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-020","examYear":"2020","examRound":"32","questionNumber":20,"category":"介護の基本","questionText":"Ｈさん（80歳，女性，要介護1）は，アルツハイマー型認知症（dementia of the Alzheimerʼs type）である。20年前に夫が亡くなった後は，ずっと一人暮らしをしている。これまでの生活を続けていきたいので，訪問介護（ホームヘルプサービス）を利用することにした。訪問介護員（ホームヘルパー）のＨさんへの対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"Ｈさんの意向を確認して，今までどおり畳で布団の使用を継続した。"},{"id":"2","text":"入浴後，手ぬぐいで体を拭いていたが，バスタオルに変更した。"},{"id":"3","text":"訪問介護員（ホームヘルパー）の判断で，食事の前にエプロンをつけた。"},{"id":"4","text":"整理整頓のために，壁に立てかけてあった掃除機を押し入れに片づけた。"},{"id":"5","text":"Ｈさんの気持ちを切り替えるために，家具の配置を換えた。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｈさんは、これまでの生活を続けたいと思っているんだね。本人の意向を確認して、畳に布団という、これまでの生活習慣を続けるのがよいよ。2、3、4、5は、Ｈさんの意向を確認せずに、介護福祉職の判断で、生活のやり方を変えてしまっているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-021","examYear":"2020","examRound":"32","questionNumber":21,"category":"介護の基本","questionText":"「平成30年版高齢社会白書」（内閣府）で示された65歳以上の者の家庭内事故の発生割合が最も高い場所（屋内）として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"階段"},{"id":"2","text":"台所・食堂"},{"id":"3","text":"風呂場"},{"id":"4","text":"トイレ"},{"id":"5","text":"居室"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！平成30年版高齢社会白書では、65歳以上の家庭内事故は、居室で最も多く発生しているとされているんだ。長い時間を過ごす場所だからこそ、事故も起こりやすいんだね。1の階段、2の台所・食堂、3の風呂場、4のトイレでも事故は起こるけれど、割合が最も高いのは、居室なんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-022","examYear":"2020","examRound":"32","questionNumber":22,"category":"介護の基本","questionText":"認知症対応型共同生活介護（グループホーム）での介護に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"テレビのニュースを見て，新しい出来事を覚えてもらう。"},{"id":"2","text":"利用者それぞれの要求には応えられないので，同じ日課で過ごしてもらう。"},{"id":"3","text":"利用者の，現在よりも過去の身体的・精神的状態の把握が優先される。"},{"id":"4","text":"利用者の，なじみのある人や店との関係は継続していく。"},{"id":"5","text":"環境に慣れるまでは，車いすでの移動を勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！グループホームでは、利用者が、なじみのある人や店との関係を、できるだけ続けていけるように支援するんだ。1は覚えることを強いる、2は個別のニーズに応えない、3は過去の把握を優先しすぎる、5は不必要に行動を制限していて、その人らしい生活の継続にはならないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-023","examYear":"2020","examRound":"32","questionNumber":23,"category":"介護の基本","questionText":"訪問介護事業所のサービス提供責任者の役割に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の生活課題に沿って，居宅サービス計画書を作成する。"},{"id":"2","text":"具体的な援助目標及び援助内容を記載した訪問介護計画書を作成する。"},{"id":"3","text":"利用者の要望に応じて，他の事業所との利用調整を行う。"},{"id":"4","text":"判断能力が十分でない人に対して，日常的な金銭管理を行う。"},{"id":"5","text":"居宅サービス事業者を招集して，サービス担当者会議を開催する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！サービス提供責任者は、具体的な援助目標や内容を記載した、訪問介護計画書を作成する役割なんだ。1の居宅サービス計画書は介護支援専門員、3の利用調整も介護支援専門員、4の金銭管理は日常生活自立支援事業、5の会議の招集は介護支援専門員の役割だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-024","examYear":"2020","examRound":"32","questionNumber":24,"category":"介護の基本","questionText":"介護の実践における多職種連携に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"医師が多職種連携の中心となる介護実践のことである。"},{"id":"2","text":"民生委員やボランティアは，多職種連携のチームから除かれる。"},{"id":"3","text":"医療と介護の連携とは，利用者の体調不良時に医療機関を受診させることを指す。"},{"id":"4","text":"要介護度の改善を優先して，多職種連携によるケアプランを作成する。"},{"id":"5","text":"利用者のケアの方向性に関する情報を共有して，課題の解決に取り組む。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！多職種連携は、利用者のケアの方向性に関する情報を、専門職どうしで共有して、課題の解決に取り組むことなんだ。1は医師中心という考え方が偏っている。2は民生委員やボランティアもチームの一員になりうる。3は連携の範囲を狭めすぎている。4は要介護度の改善だけを優先しないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-025","examYear":"2020","examRound":"32","questionNumber":25,"category":"介護の基本","questionText":"介護福祉職の倫理に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護の技術が伴わなくても，利用者の要望を最優先に実施した。"},{"id":"2","text":"利用者が求めた医行為は，実施が可能である。"},{"id":"3","text":"個人情報の取扱いについて，利用者に説明して同意を得た。"},{"id":"4","text":"暴力をふるう利用者を自室から出られないようにした。"},{"id":"5","text":"業務が忙しかったので，施設の廊下で職員同士の打合せを行った。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！個人情報を扱うときは、利用者に説明して、同意を得ることが、基本の倫理なんだ。1は、技術が伴わない要望をそのまま実施するのは危険。2は、医行為は資格の範囲外。4は、自室に閉じ込めるのは身体拘束にあたる。5は、廊下での打合せは、情報が漏れる心配があるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-026","examYear":"2020","examRound":"32","questionNumber":26,"category":"介護の基本","questionText":"高齢者介護施設で，ＭＲＳＡ（メチシリン耐性黄色ブドウ球菌）の保菌者が確認されたときの対応に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"入所者全員の保菌の有無を調べる。"},{"id":"2","text":"接触感染予防策を実施する。"},{"id":"3","text":"保菌者のレクリエーションへの参加を制限する。"},{"id":"4","text":"保菌者は最初に入浴する。"},{"id":"5","text":"通常用いられる消毒薬は無効である。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！MRSAの保菌者には、手袋やエプロンを使うなど、接触感染予防策を実施することが、基本の対応なんだ。1は全員の検査は必須ではない。3はレクリエーションへの参加を制限する必要はない。4は入浴の順番だけでは不十分。5は通常の消毒薬でも十分効果があるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-027","examYear":"2020","examRound":"32","questionNumber":27,"category":"コミュニケーション技術","questionText":"直面化の技法に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の感情と行動の矛盾点を指摘する。"},{"id":"2","text":"うなずきやあいづちを用いて，利用者の話を促す。"},{"id":"3","text":"利用者が話した内容を，整理して伝える。"},{"id":"4","text":"利用者が話した内容を，別の言葉を使って簡潔に返す。"},{"id":"5","text":"「はい」や「いいえ」だけで答えられる質問をする。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！直面化は、利用者の言っていることと、行動が食い違っている点を、指摘して、気づきを促す技法なんだ。2は傾聴、3は要約、4は言い換え、5は閉じられた質問の説明で、直面化とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-028","examYear":"2020","examRound":"32","questionNumber":28,"category":"コミュニケーション技術","questionText":"意欲が低下した人とのコミュニケーションの基本として，最も優先すべきものを1つ選びなさい。","choices":[{"id":"1","text":"考え方を変えるように促す。"},{"id":"2","text":"早く元気を出すように励ます。"},{"id":"3","text":"意欲が自然に回復するまで待つ。"},{"id":"4","text":"意欲低下の背景を考える。"},{"id":"5","text":"自己決定してもらうのは避ける。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！意欲が低下している人には、まず、なぜ意欲が下がっているのか、その背景を考えることが、最も大切なんだ。1は考え方の変更を強いる、2は励ますだけ、3は何もしない、5は自己決定の機会を奪っていて、背景を理解する姿勢が欠けているよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-029","examYear":"2020","examRound":"32","questionNumber":29,"category":"コミュニケーション技術","questionText":"構音障害のある利用者とのコミュニケーションに関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"閉じられた質問の活用を控える。"},{"id":"2","text":"聞き取れないところは，再度言ってもらう。"},{"id":"3","text":"はっきりと発音するように促す。"},{"id":"4","text":"耳元で大きな声で話しかける。"},{"id":"5","text":"筆談の活用を控える。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！構音障害のある人の話が聞き取れないときは、もう一度言ってもらうことで、正確に理解しやすくなるんだ。1は閉じられた質問はむしろ答えやすい。3ははっきり発音するよう促すのは負担になる。4は大声は失礼にあたることも。5は筆談も有効な手段だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-030","examYear":"2020","examRound":"32","questionNumber":30,"category":"コミュニケーション技術","questionText":"視覚障害者とのコミュニケーションに関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"挨拶するときは後ろから声をかける。"},{"id":"2","text":"話しかけることは最小限にとどめる。"},{"id":"3","text":"聴覚，触覚，嗅覚を活用する。"},{"id":"4","text":"声の強弱などの準言語の活用は控える。"},{"id":"5","text":"方向を示すときは「あちら」「そちら」と表現する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！視覚障害者とのコミュニケーションでは、聴覚、触覚、嗅覚など、視覚以外の感覚を活用するとよいんだ。1は後ろからの声かけは驚かせる。2は話しかけはむしろ大切な情報源。4は準言語も気持ちを伝える手段になる。5は「あちら」より時計の文字盤で示す表現がよいよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-031","examYear":"2020","examRound":"32","questionNumber":31,"category":"コミュニケーション技術","questionText":"（事例）Ｊさん（20歳，男性）は，中度の知的障害を伴う自閉症（autism）があり，2か月前から就労継続支援Ｂ型事業所を利用している。Ｊさんは，日常生活に関することは自分の感情を伝えることができるが，他者の感情を読み取ることや抽象的な言葉の理解は苦手である。また，社会的な善悪に照らして自分の言動を判断することが難しい。ある日，事業所で作業中にＪさんが興奮して他の利用者を叩いた。介護福祉職は二人を引き離し，Ｊさんを個室に連れて行って対応した。作業終了後，同居している家族にＪさんの出来事を伝えた。家族はＪさんに，「どうしてそんなことをするの。いつもだめなことばかりして」とイライラした口調で叱った。\nＪさんを個室に連れて行ったときの，介護福祉職のＪさんに対する最初の言葉かけとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「人を叩くのは許されません」"},{"id":"2","text":"「相手の気持ちを想像しましょう」"},{"id":"3","text":"「自分のしたことを反省しましょう」"},{"id":"4","text":"「ここで話をしましょう」"},{"id":"5","text":"「なぜ叩いてしまったのですか」"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！興奮しているＪさんには、まず「ここで話をしましょう」と、落ち着いて話せる場をつくることが、最初の声かけとして適切なんだ。1、3、5は、いきなり責めたり、理由や反省を求めたりしていて、まだ受け止める準備ができていないんだ。2は抽象的な言葉の理解が苦手なＪさんには難しいよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-032","examYear":"2020","examRound":"32","questionNumber":32,"category":"コミュニケーション技術","questionText":"Ｊさんを叱った家族への介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"叱ることは正しいと支持する。"},{"id":"2","text":"家族の対応は間違っていると否定する。"},{"id":"3","text":"Ｊさんへのこれまでの対応や思いを聴く。"},{"id":"4","text":"家族の対応には介入せずに黙認する。"},{"id":"5","text":"介護福祉職の指示どおりに対応するように伝える。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！家族が叱った背景には、これまでの苦労や思いがあるかもしれないよね。まずは、Ｊさんへのこれまでの対応や思いを、聴くことが大切なんだ。1は家族の叱り方を肯定、2は否定するだけ、4は何もしない、5は指示に従わせるだけで、家族の気持ちに寄り添っていないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-033","examYear":"2020","examRound":"32","questionNumber":33,"category":"コミュニケーション技術","questionText":"（事例）Ｋさん（80歳，男性）は，中等度の認知症（dementia）があり，認知症対応型共同生活介護（グループホーム）に入居中である。16時頃，ＫさんがＬ介護福祉職に，「仕事は終わりました。家に帰ります」と伝えてきた。その後，Ｌ介護福祉職がＫさんの居室を訪問すると，Ｋさんは，「早く家に帰らなくては…」と言いながらタンスから衣類を取り出していた。\nＬ介護福祉職が居室を訪問したときに，最初にとる対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"衣類をタンスへ戻すように促す。"},{"id":"2","text":"居室から出ないようにお願いする。"},{"id":"3","text":"ここに入居したことを覚えていないのかと質問する。"},{"id":"4","text":"ここは仕事場ではないことを説明する。"},{"id":"5","text":"挨拶しながら表情や行動を観察する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｋさんの様子を見て、まずは挨拶をしながら、表情や行動を観察することが、最初の対応として大切なんだ。1、2、4は、Ｋさんの気持ちを確かめずに、行動を止めたり、決めつけたりしている。3は、覚えていないのかと問い詰めていて、Ｋさんを傷つけてしまうかもしれないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-034","examYear":"2020","examRound":"32","questionNumber":34,"category":"コミュニケーション技術","questionText":"客観的事実を表す介護記録として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"16時頃，「仕事は終わりました。家に帰ります」という発言があった。"},{"id":"2","text":"自宅のことが心配になって「家に帰る」という発言があった。"},{"id":"3","text":"不安時に無断外出が心配されるため，様子の観察が必要と考える。"},{"id":"4","text":"認知症（dementia）が悪化し，ここがどこなのかを理解していないようだ。"},{"id":"5","text":"帰宅願望があったが，特に問題はなかった。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！「16時頃、『仕事は終わりました。家に帰ります』という発言があった」は、実際に見聞きしたことをそのまま書いた、客観的事実なんだ。2、3、4、5は、「心配になって」「必要と考える」「理解していないようだ」など、介護福祉職の解釈や推測が入っているよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-035","examYear":"2020","examRound":"32","questionNumber":35,"category":"生活支援技術","questionText":"一戸建ての住宅に暮らす利用者の地震対策に関する訪問介護員（ホームヘルパー）の助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家具には，キャスターをつける。"},{"id":"2","text":"書棚の上部には，重い物を収納する。"},{"id":"3","text":"食器棚は，ガラス扉を外す。"},{"id":"4","text":"外への避難経路は，玄関の1方向とする。"},{"id":"5","text":"非常時に持ち出す物は，リュックサックにまとめておく。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！非常時にすぐ持ち出せるように、必要な物をリュックサックにまとめておくと、両手が空いて、安全に避難できるんだ。1は家具にキャスターをつけると地震で動きやすくなり危険。2は重い物は下に収納する。3はガラス扉は外すより飛散防止フィルムを貼る。4は避難経路は複数用意するよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-036","examYear":"2020","examRound":"32","questionNumber":36,"category":"生活支援技術","questionText":"介護保険の給付対象となる住宅改修を利用してトイレを改修するとき，介護福祉職が助言する内容として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"開き戸は，自動ドアに変更できる。"},{"id":"2","text":"和式便器の上に，腰掛け便座を設置できる。"},{"id":"3","text":"滑りにくい床材に変更できる。"},{"id":"4","text":"取り外しが可能な手すりを設置できる。"},{"id":"5","text":"現在使用している洋式便器に，洗浄機能を付加できる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！介護保険の住宅改修には、滑りにくい床材への変更が含まれているんだ。1は自動ドアへの変更は対象外。2は腰掛け便座は特定福祉用具販売の対象。4は手すりは工事を伴う固定式が対象。5は洗浄機能の付加は対象外だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-037","examYear":"2020","examRound":"32","questionNumber":37,"category":"生活支援技術","questionText":"ユニバーサルデザイン（universal design）の7原則に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"高齢者が優先的に使用できる。"},{"id":"2","text":"使い方を統一する。"},{"id":"3","text":"情報伝達の手段は一つにする。"},{"id":"4","text":"使用するためには訓練が必要である。"},{"id":"5","text":"誰にでも使える大きさと広さが確保されている。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！ユニバーサルデザインの7原則には、誰にでも使える、十分な大きさと広さが確保されていることが含まれるんだ。1は高齢者だけでなくすべての人が使えることをめざす。2、3は多様な使い方や複数の情報伝達手段を認める。4は直感的にわかりやすく訓練が不要なことが原則だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-038","examYear":"2020","examRound":"32","questionNumber":38,"category":"生活支援技術","questionText":"次の記述のうち，高次脳機能障害（higher brain dysfunction）による着衣失行のある人に対する着衣の介護として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"着替えができない理由を本人に確認する。"},{"id":"2","text":"左右がわかるように衣類に印をつける。"},{"id":"3","text":"着衣の前に全ての手順を口頭で指示する。"},{"id":"4","text":"衣服を畳んで渡す。"},{"id":"5","text":"着衣の方法を毎回変えるように勧める。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！着衣失行がある人には、衣類の左右がわかるように、印をつけると、迷わずに着られるようになるんだ。1は本人も理由がわからないことが多い。3は一度にすべて説明すると混乱する。4は畳んで渡しても着方の理解を助けない。5は方法を変えると、さらに混乱してしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-039","examYear":"2020","examRound":"32","questionNumber":39,"category":"生活支援技術","questionText":"更衣のための介護に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"手指の細かな動作が難しい利用者に，マグネット式のボタンを勧める。"},{"id":"2","text":"認知症（dementia）のある利用者に，ボタンエイドの使用を勧める。"},{"id":"3","text":"下肢の筋力低下のある利用者に，立位で更衣をするように勧める。"},{"id":"4","text":"視覚障害のある利用者に，ソックスエイドの使用を勧める。"},{"id":"5","text":"片麻痺のある利用者に，袖ぐりの小さい上衣を勧める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！手指の細かな動作が難しい人には、磁石で留められる、マグネット式のボタンが使いやすいんだ。2はボタンエイドはむしろ手先の器用さが必要。3は下肢筋力が低下している人は座位で更衣をする。4はソックスエイドはかがめない人向け。5は片麻痺の人には袖ぐりの大きい上衣がよいよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-040","examYear":"2020","examRound":"32","questionNumber":40,"category":"生活支援技術","questionText":"介護老人保健施設の利用者の身じたくに関する専門職の役割として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護支援専門員（ケアマネジャー）は，洗面時の関節可動域の制限を改善する。"},{"id":"2","text":"支援相談員は，着脱に使用する福祉用具を選定する。"},{"id":"3","text":"栄養士は，破損した義歯を修復する。"},{"id":"4","text":"看護師は，糖尿病（diabetes mellitus）に伴う管理が必要な利用者の爪切りを行う。"},{"id":"5","text":"理学療法士は，身体状況に合わせて衣類を作り直す。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！糖尿病で足のケアに注意が必要な利用者の爪切りは、傷や感染のリスクを考えて、看護師が行うんだ。1は関節可動域の改善は介護支援専門員の仕事ではない。2は福祉用具の選定は福祉用具専門相談員などの役割。3は義歯の修復は歯科医師。5は衣類の仕立て直しは理学療法士の仕事ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-041","examYear":"2020","examRound":"32","questionNumber":41,"category":"生活支援技術","questionText":"次の記述のうち，ベッドから車いすへの移乗介護で最初に行うこととして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"移乗の目的を説明して同意を得る。"},{"id":"2","text":"移乗の方法を説明する。"},{"id":"3","text":"衣服を着替えてもらう。"},{"id":"4","text":"車いすを介護しやすい位置に調整する。"},{"id":"5","text":"ベッドの高さを調節する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！移乗の介護では、まず、これから何をするかを説明して、利用者の同意を得ることが、最初のステップなんだ。2〜5は、同意を得たあとに行う、準備や具体的な手順だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-042","examYear":"2020","examRound":"32","questionNumber":42,"category":"生活支援技術","questionText":"立位をとり静止している利用者の重心線が，点Ｘから点Ｙに移動したときに考えられるふらつきとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"左前方へのふらつき"},{"id":"2","text":"右前方へのふらつき"},{"id":"3","text":"左後方へのふらつき"},{"id":"4","text":"後方へのふらつき"},{"id":"5","text":"右後方へのふらつき"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！図を見ると、点Ｙは、両足の間にあった点Ｘより、右足の爪先側（前方）かつ外側（右）に、ずれているよね。体の重心が、支えている両足の範囲から、右前方へはみ出すと、体はその方向へ倒れ込むように、ふらつくんだ。だから、右前方へのふらつきが、正解になるんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-043","examYear":"2020","examRound":"32","questionNumber":43,"category":"生活支援技術","questionText":"右片麻痺の利用者が，手すりを利用して階段を昇降するときの介護に関する次の記述のうち，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"手すりが利用者の右側になるように声をかける。"},{"id":"2","text":"階段を昇るとき，利用者の左後方に立つ。"},{"id":"3","text":"階段を昇るとき，右足から出すように声をかける。"},{"id":"4","text":"階段を降りるとき，利用者の右前方に立つ。"},{"id":"5","text":"階段を降りるとき，左足から出すように声をかける。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！右片麻痺の人が階段を降りるときは、介護者は、利用者の右前方（患側の前）に立って、支えられるようにするんだ。1は手すりは健側（左側）になるように。2は昇るときは利用者の後方（患側寄り）に立つ。3は昇るときは健側の左足から出す。5は降りるときも患側の右足から先に出すよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-044","examYear":"2020","examRound":"32","questionNumber":44,"category":"生活支援技術","questionText":"Ｍさん（78歳，女性）は，体格指数（ＢＭＩ）は18.7である。病気や食事制限はない。この1年間で体重が2kg減少し，「最近，歩くのが遅くなり，疲れやすくなった」と言っている。Ｍさんに普段の食生活を尋ねたところ，お茶漬けやうどんで済ますことが多いと答えた。介護福祉職が食事バランスガイドを用いて摂取を勧める区分として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"主食"},{"id":"2","text":"副菜"},{"id":"3","text":"主菜"},{"id":"4","text":"牛乳・乳製品"},{"id":"5","text":"果物"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！お茶漬けやうどんが多い食生活は、炭水化物に偏っていて、たんぱく質（主菜）が不足しがちなんだ。体重減少や疲れやすさも、たんぱく質不足のサインかもしれないよ。1の主食はすでに足りていて、2の副菜、4の牛乳・乳製品、5の果物より、主菜の不足が、いちばん心配されるんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-045","examYear":"2020","examRound":"32","questionNumber":45,"category":"生活支援技術","questionText":"いすに座って食事をする利用者の姿勢を確保する介護として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"顎を上げてもらう。"},{"id":"2","text":"テーブルは，肘がつき腕が自由に動かせるものを用意する。"},{"id":"3","text":"テーブルと体の間を30cm離す。"},{"id":"4","text":"体幹を後方に傾けてもらう。"},{"id":"5","text":"いすに浅く座ってもらう。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！肘がついて、腕を自由に動かせる高さのテーブルがあると、食事の動作がしやすくなるんだ。1は顎を上げると誤嚥しやすい。3は体から離れすぎると食べ物に手が届きにくい。4は体幹を後ろに傾けると誤嚥しやすい。5は浅く座ると姿勢が不安定になるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-046","examYear":"2020","examRound":"32","questionNumber":46,"category":"生活支援技術","questionText":"高齢者の食生活に関する助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"骨粗鬆症（osteoporosis）の予防として，ビタミンＤ（vitamin D）の摂取を勧める。"},{"id":"2","text":"高血圧症（hypertension）の予防として，果物の摂取を控える。"},{"id":"3","text":"便秘の予防として，水分摂取を控える。"},{"id":"4","text":"ドライマウス（dry mouth）の予防として，柔らかい食物を勧める。"},{"id":"5","text":"逆流性食道炎（reflux esophagitis）の予防として，食後すぐに横になる。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ビタミンＤは、カルシウムの吸収を助けて、骨を強くするので、骨粗鬆症の予防に、摂取を勧めるとよいんだ。2は果物はカリウムを含み血圧を下げる助けになる。3は便秘予防には水分をしっかりとる。4はドライマウスにはよく噛んで唾液を出す工夫がよい。5は食後すぐの仰臥位は逆流性食道炎を悪化させるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-047","examYear":"2020","examRound":"32","questionNumber":47,"category":"生活支援技術","questionText":"左半側空間無視のある利用者の食事介護として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の左側にトレー（tray）を置く。"},{"id":"2","text":"トレー（tray）の右側に印をつける。"},{"id":"3","text":"クロックポジションに従って配膳する。"},{"id":"4","text":"食べる様子を観察して適宜食器の位置を変える。"},{"id":"5","text":"利用者の右側にあるテレビをつけておく。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！左半側空間無視がある人は、見え方や食べ残しの様子が、そのときによって変わることもあるから、食べる様子を観察して、食器の位置を、そのつど調整するのがよいんだ。1は左側は認識しにくい。2はトレーの右側の印は気づきやすい位置。3のクロックポジションだけでは不十分。5は右側のテレビは気が散るよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-048","examYear":"2020","examRound":"32","questionNumber":48,"category":"生活支援技術","questionText":"清拭の介護として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"目のまわりは目尻から目頭に向かって拭く。"},{"id":"2","text":"背部は患側を下にして拭く。"},{"id":"3","text":"腹部は臍部から恥骨部に向かって拭く。"},{"id":"4","text":"両下肢は末梢から中枢に向かって拭く。"},{"id":"5","text":"皮膚についた水分は最後にまとめて拭く。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！両下肢の清拭は、末梢（足先）から中枢（付け根）に向かって拭くと、血液やリンパの流れに沿っていて、心地よいんだ。1は目のまわりは目頭から目尻へ拭く。2は背部は健側を下にして拭く。3は腹部は臍部を中心に「の」の字を描くように拭く。5は水分はそのつど拭き取るよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-049","examYear":"2020","examRound":"32","questionNumber":49,"category":"生活支援技術","questionText":"利用者の状態に応じた入浴の介護として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"血液透析を受けている人は，透析直後に入浴する。"},{"id":"2","text":"胃ろうを造設している人は，入浴を控える。"},{"id":"3","text":"心臓機能障害がある人は，半身浴にする。"},{"id":"4","text":"酸素療法を行っている人は，鼻カニューレを外して入浴する。"},{"id":"5","text":"回腸ストーマを造設している人は，食後1時間以内に入浴する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！心臓機能障害がある人は、肩までつかる全身浴だと、水圧で心臓に負担がかかるので、胸の下までの半身浴にするんだ。1は透析直後は体調が変化しやすく避ける。2は胃ろうがあっても入浴はできる。4は酸素療法中はカニューレをつけたまま入浴する。5は食後1時間以内の入浴は消化に負担がかかるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-050","examYear":"2020","examRound":"32","questionNumber":50,"category":"生活支援技術","questionText":"右片麻痺のある利用者が，ベッドサイドでポータブルトイレを使用するときの設置場所として，最も適切なものを1つ選びなさい。（図：Ａ〜Ｅの位置）","choices":[{"id":"1","text":"Ａ"},{"id":"2","text":"Ｂ"},{"id":"3","text":"Ｃ"},{"id":"4","text":"Ｄ"},{"id":"5","text":"Ｅ"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！図のＢは、右片麻痺のある利用者の、健側（左側）にあたる位置で、しかも、起き上がったときの腰の高さに合わせた場所なんだ。健側に置くと、力の入る手足を使って、安全に移乗できるよ。Ａ・Ｅは頭側で、体を大きく回さないと届かない。Ｃは足元すぎて動線に合わない。Ｄは患側にあたるから、力が入りにくいんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-051","examYear":"2020","examRound":"32","questionNumber":51,"category":"生活支援技術","questionText":"膀胱留置カテーテルを使用している利用者への介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"水分摂取を控えてもらう。"},{"id":"2","text":"カテーテルが折れていないことを確認する。"},{"id":"3","text":"採尿バッグは膀胱と同じ高さに置く。"},{"id":"4","text":"尿漏れが見られたらカテーテルを抜去する。"},{"id":"5","text":"尿量の確認は看護師に依頼する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！膀胱留置カテーテルを使う人には、チューブが折れて、尿の流れが妨げられていないかを、確認することが大切なんだ。1は水分は十分にとる。3は採尿バッグは逆流を防ぐため膀胱より低い位置に置く。4は尿漏れがあっても勝手に抜いてはいけない。5は尿量の確認は介護福祉職も行えるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-052","examYear":"2020","examRound":"32","questionNumber":52,"category":"生活支援技術","questionText":"解熱を目的にした坐薬（座薬）の挿入に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"挿入時は仰臥位（背臥位）で膝を伸ばす。"},{"id":"2","text":"挿入時は腹式呼吸を促す。"},{"id":"3","text":"坐薬（座薬）はとがっていない方から挿入する。"},{"id":"4","text":"挿入後は坐薬（座薬）が排出されないことを確認する。"},{"id":"5","text":"衣服を整えてから手袋を外す。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！坐薬を挿入したあとは、体内にとどまって、きちんと効果を発揮できるように、排出されていないかを確認するんだ。1は膝を軽く曲げた側臥位で行う。2は口呼吸を促して腹圧を抜く。3はとがった方から挿入する。5は坐薬が出ていないか確認してから手袋を外すよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-053","examYear":"2020","examRound":"32","questionNumber":53,"category":"生活支援技術","questionText":"肉入りのカレーを常温で保存し，翌日，加熱調理したときの食中毒の原因菌として，最も注意しなければならないものを1つ選びなさい。","choices":[{"id":"1","text":"ウエルシュ菌"},{"id":"2","text":"カンピロバクター"},{"id":"3","text":"サルモネラ菌"},{"id":"4","text":"腸炎ビブリオ"},{"id":"5","text":"黄色ブドウ球菌"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ウエルシュ菌は、酸素の少ない環境（大量に作ったカレーなどの中）で増えやすく、常温で保存すると、繁殖してしまうんだ。加熱しても、芽胞という殻が生き残ることがあるので、要注意だよ。2〜5の菌も食中毒の原因になるけれど、大鍋で作り置きしたカレーでは、ウエルシュ菌に特に注意が必要なんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-054","examYear":"2020","examRound":"32","questionNumber":54,"category":"生活支援技術","questionText":"ノロウイルス（Norovirus）に感染した人の嘔吐物のついた衣服の処理に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"嘔吐物を拭き取ったペーパータオルはごみ箱に捨てる。"},{"id":"2","text":"汚染された部分にアルコールを噴霧する。"},{"id":"3","text":"汚染された部分を強くもみ洗いする。"},{"id":"4","text":"嘔吐物を取り除いた後，次亜塩素酸ナトリウム溶液につける。"},{"id":"5","text":"40℃の湯で洗濯する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！ノロウイルスがついた衣服は、嘔吐物を取り除いたあと、次亜塩素酸ナトリウム溶液に、しっかりつけて消毒するんだ。1はペーパータオルはビニール袋に密閉して捨てる。2はアルコールはノロウイルスに効果が弱い。3はもみ洗いはウイルスを飛び散らせる。5は40℃では死滅しないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-055","examYear":"2020","examRound":"32","questionNumber":55,"category":"生活支援技術","questionText":"Ａさん（85歳，女性，要介護1）は，認知症（dementia）があり判断能力が不十分である。一人暮らしで，介護保険サービスを利用している。訪問介護員（ホームヘルパー）が訪問したときに，物品売買契約書を見つけた。Ａさんは，「昨日，訪問販売の業者が来た」「契約書については覚えていない」と話した。訪問介護員（ホームヘルパー）から連絡を受けたサービス提供責任者が，迅速にクーリング・オフの手続きを相談する相手として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"行政書士"},{"id":"2","text":"消費生活センター"},{"id":"3","text":"家庭裁判所"},{"id":"4","text":"保健所"},{"id":"5","text":"相談支援事業所"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！訪問販売などの契約トラブルで、クーリング・オフの手続きを相談するのは、消費生活センターなんだ。1の行政書士は書類作成の専門家。3の家庭裁判所は成年後見などを扱う。4の保健所は健康や衛生の相談窓口。5の相談支援事業所は障害福祉の相談窓口だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-056","examYear":"2020","examRound":"32","questionNumber":56,"category":"生活支援技術","questionText":"眠れないと訴える高齢者に介護福祉職が行う助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"起床時に日光を浴びるように勧める。"},{"id":"2","text":"日中，長い昼寝をするように勧める。"},{"id":"3","text":"夕食後2時間以内に就寝するように勧める。"},{"id":"4","text":"寝る前に緑茶を飲むように勧める。"},{"id":"5","text":"決まった就床時刻を守るように勧める。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！朝、日光を浴びると、体内時計が整って、夜に自然な眠気が訪れやすくなるんだ。2は長い昼寝は夜の睡眠を妨げる。3は就寝直前の食事は消化に負担がかかる。4は緑茶にはカフェインが含まれ覚醒作用がある。5は就床時刻より起床時刻を一定にするほうが効果的だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-057","examYear":"2020","examRound":"32","questionNumber":57,"category":"生活支援技術","questionText":"施設における安眠を促すための環境に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"湿度は20％以下に設定する。"},{"id":"2","text":"寝衣は，体に密着した形のものを選ぶ。"},{"id":"3","text":"冷暖房の風が，体に直接当たるようにする。"},{"id":"4","text":"夜間の照明は，部屋全体がはっきり見える明るさにする。"},{"id":"5","text":"介護福祉職同士の会話が響かないようにする。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！夜間、職員同士の会話の声が響かないようにすると、利用者の眠りを妨げずにすむんだ。1は湿度は40〜60%程度が快適。2は寝衣は体を締めつけないゆったりしたものがよい。3は冷暖房の風は直接当たらないようにする。4は夜間の照明は常夜灯程度の明るさにするよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-058","examYear":"2020","examRound":"32","questionNumber":58,"category":"生活支援技術","questionText":"睡眠薬を服用している高齢者への介護福祉職の対応として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"アルコールと一緒に服用してもらった。"},{"id":"2","text":"服用後，1時間は起きているように伝えた。"},{"id":"3","text":"日中，ふらつきがみられたので医師に伝えた。"},{"id":"4","text":"通常の量では眠れないと言われたので，追加して飲むように伝えた。"},{"id":"5","text":"体調に合わせて服薬時間を変更した。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！日中にふらつきがみられたときは、副作用の可能性があるので、医師に伝えることが大切なんだ。1はアルコールと一緒の服用は作用が強くなり危険。2は服用後はすぐに休んでもらう。4は量を勝手に増やしてはいけない。5は服薬時間の変更も医師や薬剤師に相談してから行うよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-059","examYear":"2020","examRound":"32","questionNumber":59,"category":"生活支援技術","questionText":"Ｂさん（83歳，女性）は，介護老人福祉施設に入所している。終末期で，「最期はこの施設で迎えたい」という本人の希望があり，家族もそれを望んでいる。昨日から死前喘鳴が出現し，医師から，「あと数日でしょう」と言われた。「呼吸が苦しそうだ」と言っている家族への介護として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「自然な経過なので体位の工夫をして一緒に見守りましょう」"},{"id":"2","text":"「Ｂさんに意識はないので心配いらないですよ」"},{"id":"3","text":"「痰の吸引をすると楽になるので準備しますね」"},{"id":"4","text":"「Ｂさんを励ましてください」"},{"id":"5","text":"「すぐに救急車を呼びましょう」"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！死前喘鳴は、終末期に自然にみられる経過のひとつなんだ。体位を工夫しながら、家族と一緒に見守っていくことを伝えると、家族の不安をやわらげられるよ。2はＢさんの意識の有無を断定しすぎている。3はこの段階での吸引はかえって負担になることがある。4は励ましは適切でない。5は救急車は本人と家族の希望に反するんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-060","examYear":"2020","examRound":"32","questionNumber":60,"category":"生活支援技術","questionText":"高齢者施設において介護福祉職が行う死亡後の介護について，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ペースメーカーを取り除く。"},{"id":"2","text":"口が閉じない場合は紐で顎を固定する。"},{"id":"3","text":"衣服は着衣がしやすい服を選ぶ。"},{"id":"4","text":"全身清拭には水を使用する。"},{"id":"5","text":"家族に，死亡後の介護を一緒に行うかどうかを確認する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！死亡後の介護は、家族の気持ちに寄り添って、一緒に行うかどうかを確認することが、大切な配慮なんだ。1はペースメーカーは医師が対応する。2は紐で固定すると跡が残る。3は衣服は本人や家族の希望を優先する。4は清拭はぬるま湯を使うよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-061","examYear":"2020","examRound":"32","questionNumber":61,"category":"介護過程","questionText":"介護過程の目的に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"利用者の価値観を変える。"},{"id":"2","text":"利用者の療養上の世話をする。"},{"id":"3","text":"利用者の経済的負担を軽減する。"},{"id":"4","text":"利用者の望んでいる，よりよい生活を実現する。"},{"id":"5","text":"利用者の生活習慣を改善する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！介護過程の目的は、利用者が望んでいる、よりよい生活を実現することなんだ。1は価値観を変えることが目的ではない。2は療養上の世話は看護師の業務。3は経済的負担の軽減は直接の目的ではない。5は生活習慣の改善を強制するものでもないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-062","examYear":"2020","examRound":"32","questionNumber":62,"category":"介護過程","questionText":"介護計画の作成に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"抽出されたニーズを踏まえて目標を設定する。"},{"id":"2","text":"内容が明確であれば支援方法の記載は省略する。"},{"id":"3","text":"支援方法は「～させる」と使役文で記載する。"},{"id":"4","text":"利用者の正しい理解を促すために専門用語を用いる。"},{"id":"5","text":"計画の見直しの時期は決めない。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！介護計画は、アセスメントで抽出された、利用者のニーズを踏まえて、目標を設定するんだ。2は支援方法も具体的に記載する。3は使役文ではなく利用者を主語にした表現にする。4は専門用語は避けわかりやすく書く。5は見直しの時期はあらかじめ決めるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-063","examYear":"2020","examRound":"32","questionNumber":63,"category":"介護過程","questionText":"介護計画の実施に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職の価値観に沿って実施する。"},{"id":"2","text":"実施した状況は客観的に記録する。"},{"id":"3","text":"計画の内容は実施の直前に家族に伝える。"},{"id":"4","text":"他職種への経過報告は目標の達成後に行う。"},{"id":"5","text":"利用者の満足度よりも目標の達成を優先する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護計画を実施したら、その状況を、客観的に記録することが大切なんだ。1は介護福祉職の価値観ではなく利用者を中心に実施する。3は計画の内容は実施前に家族にも伝えておく。4は経過報告は達成後だけでなく途中でも行う。5は利用者の満足度も目標達成と同じく大切にするよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-064","examYear":"2020","examRound":"32","questionNumber":64,"category":"介護過程","questionText":"（事例）Ｃさん（75歳，男性，要介護1）は，脳梗塞（cerebral infarction）を発症した。2か月前から在宅復帰を目的として介護老人保健施設に入所している。次女は遠方から時々面会に来ているが，長女とは音信不通の状態が続いている。Ｃさんは現在，右片麻痺で歩行には杖を使用している。担当の理学療法士から，「レクリエーションには積極的に参加するなど意欲はあるが，歩行状態が思うように改善しないと悩んでいた」との報告があった。その後，歩行訓練やレクリエーションに参加しなくなり，居室のベッドで寝て過ごすことが多くなった。また，時々尿失禁をするようになった。Ｃさんは，「自宅に帰りたいのに，このまま車いすになったらどうしよう」と担当の介護福祉職に打ち明けた。\nＣさんの介護過程の展開に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"長女から入所前の情報を収集する。"},{"id":"2","text":"現状を再アセスメントし，生活課題を抽出する。"},{"id":"3","text":"自宅に戻った後の介護計画を立案する。"},{"id":"4","text":"尿失禁に対応する介護計画の実施を優先する。"},{"id":"5","text":"介護計画の最終的な評価は理学療法士が担当する。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｃさんの様子が変わってきたので、まず、現状を改めてアセスメントし直して、生活課題を明確にすることが、最初に行うべきことなんだ。1は長女とは音信不通で情報を得にくい。3、4は再アセスメントの前の段階。5は評価は介護福祉職を中心にチームで行うものだよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-065","examYear":"2020","examRound":"32","questionNumber":65,"category":"介護過程","questionText":"次の記述のうち，Ｃさんの短期目標として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"車いすの使用方法を理解する。"},{"id":"2","text":"居室のベッドで安静に過ごす。"},{"id":"3","text":"次女との同居を実現する。"},{"id":"4","text":"今まで以上に，意欲的に歩行訓練に取り組む。"},{"id":"5","text":"居室を出てレクリエーションに参加する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｃさんは、歩行訓練やレクリエーションに参加しなくなって、居室にこもりがちになっているんだね。居室を出て、レクリエーションに参加することは、今のＣさんにとって、無理なく取り組める、短期目標として適切だよ。1、2、3、4は、Ｃさんの今の状態や意向からは、飛躍していたり、後ろ向きだったりするんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-066","examYear":"2020","examRound":"32","questionNumber":66,"category":"介護過程","questionText":"（事例）Ｄさん（77歳，男性，要介護2）は，妻と二人で暮らしている。定年まで，高校の体育の教師で野球部の監督をしていた。起居動作に問題はないが，認知症（dementia）と診断されたため，現在，通所介護（デイサービス）を週3回利用している。通所介護（デイサービス）では，短期目標を「役割を持ち意欲的に生活する（3か月）」と設定し，体操を指導する役割をお願いしていた。実施1か月が経過した頃，テレビで高校野球を見たＤさんは暗い表情で，「生徒を全国大会に連れて行けなかったのは私の責任だ」と嘆いていた。この日は，担当の介護福祉職が体操の指導をお願いしても，「今すぐ行かなければ」と断った。\nＤさんが体操の指導を断った理由の解釈として，最も可能性が高いものを1つ選びなさい。","choices":[{"id":"1","text":"介護福祉職に依頼されたため。"},{"id":"2","text":"妻に会いに自宅に帰りたいため。"},{"id":"3","text":"高校野球のことが気になっているため。"},{"id":"4","text":"立ち上がり動作が不安定なため。"},{"id":"5","text":"体育の授業を行うため。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｄさんは、テレビで高校野球を見て、「生徒を全国大会に連れて行けなかった」と話していたよね。高校野球のことが気になって、心が乱れていると考えられるんだ。1、2、5は事例の様子からは読み取れない。4は立ち上がりの不安定さについての記述は事例にはないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-067","examYear":"2020","examRound":"32","questionNumber":67,"category":"介護過程","questionText":"その後も体操の指導を継続していたＤさんは，参加者から体操の順番が違うと指摘されて指導の意欲を失い，一人でいることが多くなった。しかし，体操の時間になると遠くからその様子を眺めていた。Ｄさんが今後も現在の役割を継続するために，優先して取り組むべき課題として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"体操に対する関心を取り戻すこと。"},{"id":"2","text":"体操の内容を変更すること。"},{"id":"3","text":"体操を指導する自信を回復すること。"},{"id":"4","text":"体操の正しい順番を学び直すこと。"},{"id":"5","text":"指摘した参加者に謝ること。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｄさんは、順番の間違いを指摘されて、指導の意欲を失ったけれど、体操の時間になると、遠くから様子を眺めているよね。これは、まだ体操への関心は残っているけれど、指導する自信を失っている状態なんだ。だから、体操を指導する自信を回復することが、優先すべき課題だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-068","examYear":"2020","examRound":"32","questionNumber":68,"category":"介護過程","questionText":"Ｅさん（70歳，女性，要介護1）は，夫，長男と共に農業をしていた。半年前に脳梗塞（cerebral infarction）で左片麻痺になった。現在は介護老人保健施設に入所し，リハビリテーションに取り組んでいる。介護福祉職が居室を訪れたとき，Ｅさんが，「料理は苦手なの」「そろそろ夏野菜の収穫の時期ね。収穫は楽しいし，採れたての野菜を近所に配るとみんな喜ぶのよ」と言った。その後，「夫には家事に専念しなさいと言われているから…」とうつむいて言った。介護福祉職は介護福祉職間のカンファレンス（conference）でＥさんの思いを共有した。Ｅさんの思いとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"農業に関わっていきたい。"},{"id":"2","text":"家事に専念したい。"},{"id":"3","text":"後継者の育成に関わりたい。"},{"id":"4","text":"家でのんびりしたい。"},{"id":"5","text":"料理の自信をつけたい。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｅさんは、農業の収穫の楽しさや、近所に配る喜びを、生き生きと話しているよね。一方、「家事に専念しなさい」と言われているという発言は、うつむいて、遠慮がちに話しているんだ。だから、Ｅさんの本当の思いは、農業に関わっていきたいということだと考えられるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-069","examYear":"2020","examRound":"32","questionNumber":69,"category":"発達と老化の理解","questionText":"Ａちゃん（1歳3か月）は，父親に抱かれて散歩中である。前方から父親の友人がやってきて，父親がにこやかに友人と話をしていると，Ａちゃんは父親にしがみつき，父親の顔と父親の友人の顔を交互に見ている。しばらくすると，Ａちゃんは緊張が解けた様子で，友人が立ち去るときには少し笑顔を見せた。Ａちゃんの様子を説明する用語として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"3か月微笑"},{"id":"2","text":"社会的参照"},{"id":"3","text":"クーイング"},{"id":"4","text":"自己中心性"},{"id":"5","text":"二項関係"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ａちゃんは、見知らぬ状況で、父親の表情を見て、安心できるかどうかを確かめているよね。これは、周囲の人の表情から、状況の意味を読み取る、社会的参照なんだ。1の3か月微笑は生後3か月ごろの反応、3のクーイングは乳児の発声、4の自己中心性は幼児期の特徴、5の二項関係は自分と対象だけの関係だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-070","examYear":"2020","examRound":"32","questionNumber":70,"category":"発達と老化の理解","questionText":"高齢者の年齢規定に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"高年齢者等の雇用の安定等に関する法律では，高年齢者を75歳以上としている。"},{"id":"2","text":"「高齢者虐待防止法」では，高齢者を65歳以上としている。"},{"id":"3","text":"高齢者の医療の確保に関する法律では，後期高齢者を65歳以上としている。"},{"id":"4","text":"道路交通法では，免許証の更新の特例がある高齢運転者を60歳以上としている。"},{"id":"5","text":"老人福祉法では，高齢者を55歳以上としている。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！高齢者虐待防止法では、高齢者を65歳以上の者と定めているんだ。1は高年齢者雇用安定法の高年齢者は55歳以上が目安。3は後期高齢者医療は75歳以上。4は更新の特例がある高齢運転者は70歳以上。5は老人福祉法は明確な年齢の定義はないけれど65歳が目安とされているよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-071","examYear":"2020","examRound":"32","questionNumber":71,"category":"発達と老化の理解","questionText":"加齢に伴う嚥下機能（えんげきのう）の低下の原因に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"舌骨の位置の上昇"},{"id":"2","text":"咽頭の位置の上昇"},{"id":"3","text":"舌骨上筋の増大"},{"id":"4","text":"喉頭挙上の不足"},{"id":"5","text":"咳嗽反射（がいそうはんしゃ）の増強"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！加齢によって、飲み込むときに喉頭（のどぼとけ）が十分に持ち上がらなくなる、喉頭挙上の不足が起こりやすく、これが嚥下機能の低下の原因になるんだ。1は舌骨の位置は下降する。2は咽頭の位置も下降する。3は舌骨上筋は筋力が低下する。5は咳嗽反射は加齢で弱まるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-072","examYear":"2020","examRound":"32","questionNumber":72,"category":"発達と老化の理解","questionText":"老年期の記憶と注意機能に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自分の若い頃の記憶では，40歳代の頃の出来事をよく覚えている。"},{"id":"2","text":"数字の逆唱課題で答えられる数字の個数は，加齢による影響を受けない。"},{"id":"3","text":"複数のことを同時に行う能力は，加齢によって低下する。"},{"id":"4","text":"騒がしい場所での作業効率は，若年者より高齢者が高い。"},{"id":"5","text":"エピソード記憶は，加齢による影響を受けない。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！複数のことを同時に行う、注意の分配能力は、加齢によって低下しやすいんだ。1は若い頃の記憶では青年期の出来事のほうがよく覚えていることが多い。2は逆唱課題の成績は加齢の影響を受ける。4は騒がしい場所では高齢者のほうが作業効率が下がりやすい。5はエピソード記憶は加齢の影響を受けやすいよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-073","examYear":"2020","examRound":"32","questionNumber":73,"category":"発達と老化の理解","questionText":"高齢者において，心不全（heart failure）が進行したときに現れる症状に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"安静にすることで速やかに息切れが治まる。"},{"id":"2","text":"運動によって呼吸苦が軽減する。"},{"id":"3","text":"チアノーゼ（cyanosis）が生じる。"},{"id":"4","text":"呼吸苦は，座位より仰臥位（背臥位）の方が軽減する。"},{"id":"5","text":"下肢に限局した浮腫が生じる。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！心不全が進行すると、血液中の酸素が不足して、唇や指先が青紫色になる、チアノーゼが生じることがあるんだ。1は安静にしても息切れはすぐには治まらない。2は運動で呼吸苦は悪化する。4は仰臥位のほうが呼吸苦は強くなる。5は浮腫は下肢だけでなく全身に広がることもあるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-074","examYear":"2020","examRound":"32","questionNumber":74,"category":"発達と老化の理解","questionText":"Ｂさん（82歳，男性）は脳卒中（stroke）による右片麻痺がある。ほとんどベッド上の生活で，排泄もおむつを使用している。一週間前から咳と鼻汁があり，37.2℃の微熱で，元気がなく，いつもよりも動きが少なかった。食欲も低下して食事を残すようになっていた。今日，おむつの交換をしたときに仙骨部の皮膚が赤くなり一部に水疱ができていた。Ｂさんの皮膚の状態とその対応に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"圧迫によって血流が悪くなったためである。"},{"id":"2","text":"仙骨部にこうしたことが起こるのは，まれである。"},{"id":"3","text":"食事量の低下とは無関係である。"},{"id":"4","text":"体位変換は，できるだけ避ける。"},{"id":"5","text":"おむつの交換は，できるだけ控える。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ベッド上での生活が長く、仙骨部に体重がかかり続けたことで、血流が悪くなり、褥瘡ができたと考えられるんだ。2は仙骨部は褥瘡の好発部位。3は食欲低下による低栄養も褥瘡の要因になる。4は褥瘡を防ぐためにこまめな体位変換が必要。5はおむつ交換を控えると悪化するよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-075","examYear":"2020","examRound":"32","questionNumber":75,"category":"発達と老化の理解","questionText":"次のうち，高齢者の栄養状態を良好に維持するための対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"歯科健康診査を受ける。"},{"id":"2","text":"複数の薬剤を併用する。"},{"id":"3","text":"外出を控える。"},{"id":"4","text":"一人で食事をする。"},{"id":"5","text":"たんぱく質を制限する。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！歯科健康診査を受けて、口の中の状態を整えると、しっかり噛んで食べられて、栄養状態を良好に保つ助けになるんだ。2は薬の飲み合わせは食欲不振の原因になることもある。3は外出を控えると活動量が減り食欲にも影響する。4は一人での食事は食欲が落ちやすい。5はたんぱく質はしっかりとる必要があるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-076","examYear":"2020","examRound":"32","questionNumber":76,"category":"発達と老化の理解","questionText":"糖尿病（diabetes mellitus）のある高齢者（要介護1）が転倒して，骨折（fracture）した。入院治療後に再び自宅療養を続けるための専門職の役割として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"看護師は，糖尿病（diabetes mellitus）の薬の処方箋を交付する。"},{"id":"2","text":"理学療法士は，糖尿病（diabetes mellitus）の食事メニューを考える。"},{"id":"3","text":"管理栄養士は，自宅で料理ができるような作業訓練をする。"},{"id":"4","text":"訪問介護員（ホームヘルパー）は，居宅サービス計画を立案する。"},{"id":"5","text":"介護支援専門員（ケアマネジャー）は，訪問リハビリテーションの利用を提案する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！介護支援専門員は、自宅での療養を支えるために、訪問リハビリテーションの利用を、ケアプランに提案できるんだ。1は薬の処方箋の交付は医師の役割。2は食事メニューは管理栄養士の役割。3は作業訓練は作業療法士の役割。4は居宅サービス計画の立案は介護支援専門員の役割だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-077","examYear":"2020","examRound":"32","questionNumber":77,"category":"認知症の理解","questionText":"2012年（平成24年）の認知症高齢者数と2025年（平成37年）の認知症高齢者数に関する推計値（「平成29年版高齢社会白書」（内閣府））の組合せとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"162万人　約400万人"},{"id":"2","text":"262万人　約500万人"},{"id":"3","text":"362万人　約600万人"},{"id":"4","text":"462万人　約700万人"},{"id":"5","text":"562万人　約800万人"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！平成29年版高齢社会白書では、2012年の認知症高齢者数は約462万人、2025年には約700万人に増えると推計されているんだ。高齢化が進むにつれて、認知症の人の数も、大きく増えていくと見込まれているんだよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-078","examYear":"2020","examRound":"32","questionNumber":78,"category":"認知症の理解","questionText":"認知症（dementia）の行動・心理症状（ＢＰＳＤ）に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"トイレの水を流すことができない。"},{"id":"2","text":"物事の計画を立てることができない。"},{"id":"3","text":"言葉を発することができない。"},{"id":"4","text":"親しい人がわからない。"},{"id":"5","text":"昼夜逆転が生じる。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！昼夜逆転は、夜眠れずに日中に眠くなるなど、生活リズムが崩れる、行動・心理症状（ＢＰＳＤ）のひとつなんだ。1のトイレの水を流せない、2の計画が立てられない、3の言葉が出ない、4の親しい人がわからないは、記憶や実行機能などの障害である、中核症状にあたるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-079","examYear":"2020","examRound":"32","questionNumber":79,"category":"認知症の理解","questionText":"高齢者のせん妄（delirium）の特徴として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"薬剤によって生じることがある。"},{"id":"2","text":"症状の変動は少ない。"},{"id":"3","text":"意識レベルは清明であることが多い。"},{"id":"4","text":"徐々に悪化する場合が多い。"},{"id":"5","text":"幻覚を伴うことは少ない。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！せん妄は、薬の副作用や、脱水、感染などが、きっかけになって、急に起こることがあるんだ。2は症状は日によって時間帯によって変動しやすい。3は意識レベルは低下していることが多い。4は急に発症する。5は幻覚を伴うことが多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-080","examYear":"2020","examRound":"32","questionNumber":80,"category":"認知症の理解","questionText":"認知症（dementia）の初期症状に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"血管性認知症（vascular dementia）では，幻視が認められる。"},{"id":"2","text":"正常圧水頭症（normal pressure hydrocephalus）では，歩行障害が認められる。"},{"id":"3","text":"前頭側頭型認知症（frontotemporal dementia）では，エピソード記憶の障害が認められる。"},{"id":"4","text":"アルツハイマー型認知症（dementia of the Alzheimerʼs type）では，失禁が認められる。"},{"id":"5","text":"レビー小体型認知症（dementia with Lewy bodies）では，もの盗られ妄想が認められる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！正常圧水頭症では、初期から、すり足で小刻みに歩く、歩行障害がみられるんだ。1は幻視が特徴的なのはレビー小体型認知症。3は前頭側頭型認知症ではエピソード記憶より人格や行動の変化が目立つ。4は失禁はアルツハイマー型では進行してから現れやすい。5はもの盗られ妄想はアルツハイマー型に多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-081","examYear":"2020","examRound":"32","questionNumber":81,"category":"認知症の理解","questionText":"認知症（dementia）の発症リスクを低減させる行動に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"抗認知症薬を服用する。"},{"id":"2","text":"睡眠時間を減らす。"},{"id":"3","text":"集団での交流活動に参加する。"},{"id":"4","text":"運動の機会を減らす。"},{"id":"5","text":"飽和脂肪酸を多く含む食事を心がける。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！人との交流を保つ集団活動への参加は、認知症の発症リスクを下げるとされているんだ。1は抗認知症薬は治療薬で予防のためのものではない。2は睡眠不足はリスクを高める。4は運動の機会を減らすとリスクが高まる。5は飽和脂肪酸の多い食事もリスクを高めるとされているよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-082","examYear":"2020","examRound":"32","questionNumber":82,"category":"認知症の理解","questionText":"抗認知症薬に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"若年性アルツハイマー型認知症（dementia of the Alzheimerʼs type with early onset）には効果がない。"},{"id":"2","text":"高度のアルツハイマー型認知症（dementia of the Alzheimerʼs type）には効果がない。"},{"id":"3","text":"レビー小体型認知症（dementia with Lewy bodies）には効果がない。"},{"id":"4","text":"症状の進行を完全に止めることはできない。"},{"id":"5","text":"複数の抗認知症薬の併用は認められていない。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！抗認知症薬は、症状の進行を、緩やかにすることはできても、完全に止めることはできないんだ。1は若年性にも使われる。2は高度の状態にも使われる薬がある。3はレビー小体型にも使われる薬がある。5は複数の薬を組み合わせて使うことも認められているよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-083","examYear":"2020","examRound":"32","questionNumber":83,"category":"認知症の理解","questionText":"前頭側頭型認知症（frontotemporal dementia）の症状のある人への介護福祉職の対応として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"周回がある場合は，ＧＰＳ追跡機で居場所を確認する。"},{"id":"2","text":"甘い食べ物へのこだわりに対しては，甘い物を制限する。"},{"id":"3","text":"常同行動がある場合は，本人と周囲の人が納得できる生活習慣を確立する。"},{"id":"4","text":"脱抑制がある場合は，抗認知症薬の服薬介護をする。"},{"id":"5","text":"施設内で職員に暴力をふるったときは，警察に連絡する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！常同行動（同じ行動を繰り返すこと）がある場合は、無理にやめさせず、本人も周囲も納得できる、生活習慣として確立していくのがよいんだ。1はＧＰＳだけでは根本的な対応にならない。2はこだわりを制限すると興奮につながることがある。4は抗認知症薬は脱抑制の治療薬ではない。5は警察への連絡は最初の対応としては適切でないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-084","examYear":"2020","examRound":"32","questionNumber":84,"category":"認知症の理解","questionText":"Ｃさん（78歳，男性，要介護2）は，4年前にアルツハイマー型認知症（dementia of the Alzheimerʼs type）と診断を受け，通所介護（デイサービス）を週1回利用している。以前からパソコンで日記をつけていたが，最近はパソコンの操作に迷い，イライラして怒りっぽくなったと娘から相談を受けた。介護福祉職が娘に対して最初に行う助言の内容として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"パソコンの処分"},{"id":"2","text":"パソコンの使い方の手助け"},{"id":"3","text":"日記帳の購入"},{"id":"4","text":"薬物治療について主治医に相談"},{"id":"5","text":"施設入所について介護支援専門員（ケアマネジャー）に相談"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！パソコン操作に迷ってイライラしているＣさんには、まず、パソコンの使い方を手助けして、続けられるようにすることが、最初の助言として適切なんだ。1、3は日記という楽しみをやめさせてしまう。4、5はいきなり治療や施設入所を検討するのは早すぎるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-085","examYear":"2020","examRound":"32","questionNumber":85,"category":"認知症の理解","questionText":"認知症対応型共同生活介護（グループホーム）で生活している軽度のアルツハイマー型認知症（dementia of the Alzheimerʼs type）のＤさんは，大腿骨の頸部を骨折（fracture）して入院することになった。認知症対応型共同生活介護（グループホーム）の介護福祉職が果たす役割として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"理学療法士に，リハビリテーションの指示をしても理解できないと伝える。"},{"id":"2","text":"介護支援専門員（ケアマネジャー）に，地域ケア会議の開催を依頼する。"},{"id":"3","text":"医師に，夜間は騒ぐ可能性があるので睡眠薬の処方を依頼する。"},{"id":"4","text":"看護師に，日常生活の状況を伝える。"},{"id":"5","text":"保佐人に，治療方法の決定を依頼する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！グループホームの介護福祉職は、Ｄさんの日頃の生活の様子を、入院先の看護師に伝えて、入院中もその人らしいケアを続けてもらえるようにするんだ。1は決めつけている。2、3、5は、それぞれの専門職の判断を、介護福祉職が代わりに決めてしまっているよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-086","examYear":"2020","examRound":"32","questionNumber":86,"category":"認知症の理解","questionText":"Ｅさん（75歳，男性）は，1年ほど前に趣味であった車の運転をやめてから，やる気が起こらなくなり自宅に閉じこもりがちになった。そのため，家族の勧めで介護予防教室に参加するようになった。最近，Ｅさんは怒りっぽく，また，直前の出来事を覚えていないことが増え，心配した家族が介護福祉職に相談した。相談を受けた介護福祉職の助言として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「認知症（dementia）でしょう」"},{"id":"2","text":"「趣味の車の運転を再開するといいでしょう」"},{"id":"3","text":"「老人クラブに参加するといいでしょう」"},{"id":"4","text":"「音楽を流して気分転換するといいでしょう」"},{"id":"5","text":"「かかりつけ医に診てもらうといいでしょう」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！怒りっぽさや、直前の出来事を忘れるという変化は、病気が背景にあるかもしれないから、まずは、かかりつけ医に診てもらうことを勧めるのがよいんだ。1は介護福祉職が診断するのは資格の範囲外。2、3、4は原因を確かめる前の対応で優先度が低いよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-087","examYear":"2020","examRound":"32","questionNumber":87,"category":"障害の理解","questionText":"ＩＣＩＤＨ（International Classification of Impairments，Disabilities and Handicaps：国際障害分類）における能力障害として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"日常生活動作（Activities of Daily Living：ＡＤＬ）の障害"},{"id":"2","text":"運動麻痺"},{"id":"3","text":"失語"},{"id":"4","text":"職場復帰困難"},{"id":"5","text":"経済的不利益"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！ICIDHの能力障害は、歩く、食べるなどの、日常生活動作（ADL）が、できなくなることなんだ。2の運動麻痺と3の失語は機能・形態障害。4の職場復帰困難と5の経済的不利益は社会的不利にあたるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-088","examYear":"2020","examRound":"32","questionNumber":88,"category":"障害の理解","questionText":"「障害者差別解消法」に関する次の記述のうち，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"法の対象者は，身体障害者手帳を持っている人である。"},{"id":"2","text":"合理的配慮とは，全ての障害者に同じ配慮をすることである。"},{"id":"3","text":"共生社会の実現を目指している。"},{"id":"4","text":"障害者は，合理的配慮の提供に努めなければならない。"},{"id":"5","text":"障害者差別解消支援地域協議会は，民間事業者で組織される。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！障害者差別解消法は、障害のある人もない人も、共に暮らせる、共生社会の実現を目指しているんだ。1は手帳の有無にかかわらず対象。2は合理的配慮は一人ひとりの状況に応じて行う。4は合理的配慮は事業者側の努力義務・義務。5は協議会には行政機関なども参加するよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-089","examYear":"2020","examRound":"32","questionNumber":89,"category":"障害の理解","questionText":"痙直型（けいちょくがた）や不随意運動型（アテトーゼ型（athetosis））などの分類がある疾患として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"筋ジストロフィー（muscular dystrophy）"},{"id":"2","text":"脊髄小脳変性症（spinocerebellar degeneration）"},{"id":"3","text":"脳血管疾患（cerebrovascular disease）"},{"id":"4","text":"脳性麻痺（cerebral palsy）"},{"id":"5","text":"脊髄損傷（spinal cord injury）"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！脳性麻痺には、筋肉がこわばる痙直型や、体が勝手に動く不随意運動型（アテトーゼ型）など、いくつかのタイプがあるんだ。1の筋ジストロフィー、2の脊髄小脳変性症、3の脳血管疾患、5の脊髄損傷は、こうした型による分類はしないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-090","examYear":"2020","examRound":"32","questionNumber":90,"category":"障害の理解","questionText":"内因性精神障害に分類される疾患として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"脳腫瘍（brain tumor）"},{"id":"2","text":"アルコール依存症（alcohol dependence）"},{"id":"3","text":"パニック障害（panic disorder）"},{"id":"4","text":"認知症（dementia）"},{"id":"5","text":"統合失調症（schizophrenia）"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！統合失調症は、原因がはっきりしない、内因性精神障害に分類されるんだ。1の脳腫瘍は器質性、2のアルコール依存症は外因性（物質による）、3のパニック障害は心因性、4の認知症は器質性の精神障害に分類されるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-091","examYear":"2020","examRound":"32","questionNumber":91,"category":"障害の理解","questionText":"Ｆさん（26歳）は重度の知的障害があり，施設入所支援を利用している。次のうち，Ｆさんが地域移行するときの社会資源として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ケアハウス"},{"id":"2","text":"共同生活援助（グループホーム）"},{"id":"3","text":"自立支援医療"},{"id":"4","text":"精神科病院"},{"id":"5","text":"同行援護"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！施設から地域での生活に移るときは、共同生活援助（グループホーム）が、支援を受けながら、地域で暮らすための、代表的な社会資源になるんだ。1のケアハウスは主に高齢者向け。3の自立支援医療は医療費の助成。4の精神科病院は地域移行の目的地としてはふさわしくない。5の同行援護は視覚障害のある人向けだよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-092","examYear":"2020","examRound":"32","questionNumber":92,"category":"障害の理解","questionText":"自閉症スペクトラム障害（autism spectrum disorder）の特性として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"読み書きの障害"},{"id":"2","text":"社会性の障害"},{"id":"3","text":"注意の障害"},{"id":"4","text":"行為障害"},{"id":"5","text":"運動障害"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！自閉症スペクトラム障害の特性は、他者とのかかわりが苦手な、社会性の障害と、こだわりの強さなんだ。1の読み書きの障害は学習障害、3の注意の障害と4の行為障害はADHD、5の運動障害は別の障害の特徴だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-093","examYear":"2020","examRound":"32","questionNumber":93,"category":"障害の理解","questionText":"筋萎縮性側索硬化症（amyotrophic lateral sclerosis：ＡＬＳ）に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"免疫疾患である。"},{"id":"2","text":"振戦や筋固縮が主な症状である。"},{"id":"3","text":"視力や聴力は保たれる。"},{"id":"4","text":"運動失調が現れる。"},{"id":"5","text":"全身の臓器に炎症を起こす。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ALSは、運動神経が障害される病気で、視力や聴力などの感覚機能は、保たれることが多いんだ。1は免疫疾患ではない。2は振戦や筋固縮はパーキンソン病の症状。4は運動失調は小脳の病気の症状。5は全身の臓器の炎症を起こす病気ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-094","examYear":"2020","examRound":"32","questionNumber":94,"category":"障害の理解","questionText":"Ｇさん（56歳，男性）は，糖尿病性網膜症（diabetic retinopathy）に伴う眼底出血を繰り返して，治療を受けていた。医師から失明は避けられないと説明を受けた。その後，Ｇさんは周囲に怒りをぶつけたり，壁に頭を打ちつけたりという行動がみられるようになった。このときのＧさんの障害受容の状況として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ショックではあるが，不安はそれほど強くない。"},{"id":"2","text":"自分には障害はないと否認する。"},{"id":"3","text":"前向きに自己努力を図ろうとする。"},{"id":"4","text":"否認ができずに混乱する。"},{"id":"5","text":"新しい価値観や役割を見いだす。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｇさんは、失明を告げられて、怒りをぶつけたり、自分を傷つけたりしているよね。これは、現実を受け入れられずに、混乱している状態なんだ。1はショック期、2は否認期、3は解決への努力期、5は受容期の様子で、Ｇさんの今の状態は、否認ができずに混乱している段階だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-095","examYear":"2020","examRound":"32","questionNumber":95,"category":"障害の理解","questionText":"パーキンソン病（Parkinson disease）のＨさんは，最近，立位時の前傾姿勢が強くなり，歩行時の方向転換が不安定になり始めた。日常生活動作には介助を必要としない。Ｈさんのホーエン・ヤール重症度分類として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ステージⅠ"},{"id":"2","text":"ステージⅡ"},{"id":"3","text":"ステージⅢ"},{"id":"4","text":"ステージⅣ"},{"id":"5","text":"ステージⅤ"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！ホーエン・ヤール重症度分類のステージⅢは、姿勢反射障害（方向転換の不安定さなど）が現れるけれど、日常生活動作は、自立している段階なんだ。ステージⅠ、Ⅱは症状が軽く姿勢反射障害はまだない。Ⅳは介助が必要、Ⅴは車いすやベッドでの生活になる段階だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-096","examYear":"2020","examRound":"32","questionNumber":96,"category":"障害の理解","questionText":"制度化された地域の社会資源として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"家族会が行う悩み相談"},{"id":"2","text":"近隣の住民からの善意の声かけ"},{"id":"3","text":"同居家族が行う身の回りの介護"},{"id":"4","text":"コンビニエンスストアによる見守り"},{"id":"5","text":"民生委員が行う相談・援助"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！民生委員は、法律にもとづいて委嘱される、制度化された、地域の相談・援助の担い手なんだ。1の家族会、2の近隣住民、3の同居家族、4のコンビニの見守りは、善意やインフォーマルな関わりで、制度化された社会資源とはちがうよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-097","examYear":"2020","examRound":"32","questionNumber":97,"category":"こころとからだのしくみ","questionText":"マズロー（Maslow,A.）の欲求階層説の所属・愛情欲求に相当するものとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"生命を脅かされないこと"},{"id":"2","text":"他者からの賞賛"},{"id":"3","text":"自分の遺伝子の継続"},{"id":"4","text":"好意がある他者との良好な関係"},{"id":"5","text":"自分自身の向上"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！所属・愛情欲求は、家族や友人など、好意がある他者と、良好な関係を築きたいという欲求なんだ。1は安全欲求、2と5は承認欲求や自己実現欲求に近く、3は種の保存にかかわる本能的な欲求で、マズローの階層とは別の話だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-098","examYear":"2020","examRound":"32","questionNumber":98,"category":"こころとからだのしくみ","questionText":"皮膚の痛みの感覚を受け取る大脳の機能局在の部位として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"頭頂葉"},{"id":"2","text":"前頭葉"},{"id":"3","text":"側頭葉"},{"id":"4","text":"後頭葉"},{"id":"5","text":"大脳辺縁系"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！皮膚の痛みなどの感覚（体性感覚）を受け取るのは、頭頂葉にある体性感覚野なんだ。2の前頭葉は思考や運動、3の側頭葉は聴覚や記憶、4の後頭葉は視覚、5の大脳辺縁系は感情や本能に関わる部位だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-099","examYear":"2020","examRound":"32","questionNumber":99,"category":"こころとからだのしくみ","questionText":"爪や指の変化と，そこから推測される疾患・病態との組合せとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"爪の白濁　　チアノーゼ（cyanosis）"},{"id":"2","text":"巻き爪　　心疾患"},{"id":"3","text":"さじ状爪　　鉄欠乏性貧血（iron deficiency anemia）"},{"id":"4","text":"ばち状指　　栄養障害"},{"id":"5","text":"青紫色の爪　　爪白癬（つめはくせん）"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！さじ状爪（爪がスプーンのようにへこむ状態）は、鉄欠乏性貧血でみられることが多いんだ。1の爪の白濁は貧血や肝疾患など、2の巻き爪は爪の切り方や靴の影響、4のばち状指は呼吸器や心臓の病気、5の青紫色の爪はチアノーゼでみられるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-100","examYear":"2020","examRound":"32","questionNumber":100,"category":"こころとからだのしくみ","questionText":"口臭に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"歯がない場合に起こりやすい。"},{"id":"2","text":"唾液量が多いと生じる。"},{"id":"3","text":"ウイルス感染の原因となることがある。"},{"id":"4","text":"食事量が増加した場合に起こりやすい。"},{"id":"5","text":"他者との交流を避ける原因となることがある。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！口臭を気にして、人と話すのをためらってしまい、交流を避ける原因になることがあるんだ。1は歯がなくても口の中が清潔なら口臭は少ない。2は唾液が少ないほうが口臭は生じやすい。3はウイルスではなく細菌が原因。4は食事量が減ると口臭が強まることが多いよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-101","examYear":"2020","examRound":"32","questionNumber":101,"category":"こころとからだのしくみ","questionText":"高齢者の大腿骨頸部骨折（femoral neck fracture）に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"転落によって生じることが最も多い。"},{"id":"2","text":"骨折（fracture）の直後は無症状である。"},{"id":"3","text":"リハビリテーションを早期に開始する。"},{"id":"4","text":"保存的治療を行う。"},{"id":"5","text":"予後は良好である。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！大腿骨頸部骨折は、寝たきりを防ぐために、できるだけ早くリハビリテーションを始めることが、大切なんだ。1は転落より転倒で多く起こる。2は直後から強い痛みが出る。4は多くは手術による治療が選ばれる。5は寝たきりにつながりやすく予後は必ずしも良好ではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-102","examYear":"2020","examRound":"32","questionNumber":102,"category":"こころとからだのしくみ","questionText":"摂食・嚥下（えんげ）のプロセスに関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"先行期は，唾液分泌が増加する。"},{"id":"2","text":"準備期は，嚥下性無呼吸がみられる。"},{"id":"3","text":"口腔期（こうくうき）は，喉頭が閉鎖する。"},{"id":"4","text":"咽頭期は，食塊を形成する。"},{"id":"5","text":"食道期は，随意的な運動である。"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！先行期は、食べ物を見て、「食べよう」と意識する段階で、このとき、唾液の分泌も増えるんだ。2は嚥下性無呼吸は咽頭期にみられる。3は喉頭が閉鎖するのは咽頭期。4は食塊を形成するのは口腔期（準備期）。5は食道期は不随意（反射的）な運動だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-103","examYear":"2020","examRound":"32","questionNumber":103,"category":"こころとからだのしくみ","questionText":"Ｊさん（80歳，男性）は，アルツハイマー型認知症（dementia of the Alzheimerʼs type）と診断され，半年前から認知症対応型共同生活介護（グループホーム）に入居している。最近，Ｊさんは，トイレに行きたいと言ってグループホーム内を歩き回った後に，失禁するようになった。Ｊさんの排泄の状態として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"反射性尿失禁"},{"id":"2","text":"心因性頻尿"},{"id":"3","text":"溢流性尿失禁（いつりゅうせいにょうしっきん）"},{"id":"4","text":"機能性尿失禁"},{"id":"5","text":"腹圧性尿失禁"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｊさんは、トイレに行きたいと思って歩き回るけれど、トイレの場所がわからなくなり、間に合わずに失禁してしまうんだね。これは、認知機能の低下による、機能性尿失禁なんだ。1の反射性尿失禁は脊髄損傷など、2の心因性頻尿は精神的な要因、3の溢流性尿失禁は尿が少しずつあふれる、5の腹圧性尿失禁は力が入ったときの漏れだよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-104","examYear":"2020","examRound":"32","questionNumber":104,"category":"こころとからだのしくみ","questionText":"正常な尿に関する次の記述のうち，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"1日に約1gのたんぱく質が排出される。"},{"id":"2","text":"1日に約10gのブドウ糖が排出される。"},{"id":"3","text":"排尿直後はアンモニア臭がする。"},{"id":"4","text":"排尿直後はアルカリ性である。"},{"id":"5","text":"排尿直後は淡黄色で透明である。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！正常な尿は、排尿直後は、淡い黄色で、透明なんだ。1は正常ならたんぱく質はほとんど出ない。2は正常ならブドウ糖もほとんど出ない。3はアンモニア臭がするのは時間がたって分解が進んだとき。4は排尿直後の尿は弱酸性だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-105","examYear":"2020","examRound":"32","questionNumber":105,"category":"こころとからだのしくみ","questionText":"弛緩性便秘（しかんせいべんぴ）の原因に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"食物繊維の摂取不足"},{"id":"2","text":"排便を我慢する習慣"},{"id":"3","text":"腹圧の低下"},{"id":"4","text":"大腸のけいれん"},{"id":"5","text":"がん（cancer）による通過障害"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！弛緩性便秘は、腸の動きが弱くなって起こる便秘で、食物繊維の摂取不足が、主な原因のひとつなんだ。2は直腸性便秘の原因。3は腹圧の低下も弛緩性便秘に関わるけれど食物繊維不足のほうがより直接的な原因とされるよ。4はけいれん性便秘の原因、5は器質性便秘の原因だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-106","examYear":"2020","examRound":"32","questionNumber":106,"category":"こころとからだのしくみ","questionText":"抗ヒスタミン薬の睡眠への影響として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"就寝後，短時間で覚醒する。"},{"id":"2","text":"夜間に十分睡眠をとっても，日中に強い眠気がある。"},{"id":"3","text":"睡眠中に足が痛がゆくなる。"},{"id":"4","text":"睡眠中に無呼吸が生じる。"},{"id":"5","text":"夢の中の行動が，そのまま現実の行動として現れる。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！抗ヒスタミン薬は、眠気を引き起こす作用があって、夜間に十分眠っても、日中に強い眠気が残ることがあるんだ。1の短時間での覚醒、3の足の痛がゆさ、4の無呼吸、5の夢の中の行動が現実に出るのは、それぞれ別の睡眠障害の特徴だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-107","examYear":"2020","examRound":"32","questionNumber":107,"category":"こころとからだのしくみ","questionText":"終末期に自分が望むケアをあらかじめ書面に示しておくことを表す用語として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"ターミナルケア（terminal care）"},{"id":"2","text":"インフォームドコンセント（informed consent）"},{"id":"3","text":"リビングウィル（living will）"},{"id":"4","text":"デスカンファレンス（death conference）"},{"id":"5","text":"グリーフケア（grief care）"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！リビングウィルは、終末期に自分がどんなケアを望むかを、あらかじめ書面に示しておくことなんだ。1のターミナルケアは終末期の医療・介護、2のインフォームドコンセントは説明と同意、4のデスカンファレンスは死後の振り返り、5のグリーフケアは遺族への支援だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-108","examYear":"2020","examRound":"32","questionNumber":108,"category":"こころとからだのしくみ","questionText":"死亡直前にみられる身体の変化として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"関節の強直"},{"id":"2","text":"角膜の混濁"},{"id":"3","text":"皮膚の死斑（しはん）"},{"id":"4","text":"下顎呼吸の出現"},{"id":"5","text":"筋肉の硬直"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！死亡が近づくと、顎を動かして呼吸をする、下顎呼吸が現れることがあるんだ。1の関節の強直、3の死斑、5の筋肉の硬直は、死亡後にみられる変化。2の角膜の混濁も、死亡後、時間がたってから起こる変化だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-109","examYear":"2020","examRound":"32","questionNumber":109,"category":"医療的ケア","questionText":"介護福祉士が医師の指示の下で行う喀痰吸引（かくたんきゅういん）の範囲として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"咽頭の手前まで"},{"id":"2","text":"咽頭まで"},{"id":"3","text":"喉頭まで"},{"id":"4","text":"気管の手前まで"},{"id":"5","text":"気管分岐部まで"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！介護福祉士が行える喀痰吸引は、口腔内・鼻腔内では、咽頭の手前までと、範囲が決められているんだ。咽頭より奥は、誤って気道を傷つけるリスクが高いから、看護師などが行うよ。2〜5は、咽頭より奥まで含んでいて、介護福祉士が行える範囲を超えているんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-110","examYear":"2020","examRound":"32","questionNumber":110,"category":"医療的ケア","questionText":"2011年（平成23年）の社会福祉士及び介護福祉士法の改正に基づいて，介護福祉士による実施が可能になった喀痰吸引等（かくたんきゅういんとう）の制度に関する次の記述のうち，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"喀痰吸引（かくたんきゅういん）や経管栄養は，医行為から除外された。"},{"id":"2","text":"喀痰吸引等（かくたんきゅういんとう）を行うためには，実地研修を修了する必要がある。"},{"id":"3","text":"介護福祉士は，病院で喀痰吸引（かくたんきゅういん）を実施できる。"},{"id":"4","text":"介護福祉士は，この制度の基本研修の講師ができる。"},{"id":"5","text":"実施できる行為の一つとして，インスリン注射がある。"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！介護福祉士が喀痰吸引等を行うには、基本研修に加えて、実地研修を修了する必要があるんだ。1は喀痰吸引や経管栄養は医行為として扱われたまま一定の条件で実施が認められた。3は病院ではなく施設や在宅が主な対象。4は講師になるには別の要件がある。5はインスリン注射は対象に含まれないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-111","examYear":"2020","examRound":"32","questionNumber":111,"category":"医療的ケア","questionText":"Ｋさん（76歳）は，日頃から痰がからむことがあり，介護福祉士が喀痰吸引を行っている。鼻腔内吸引を実施したところ，吸引物に血液が少量混じっていた。Ｋさんは，「痰は取り切れたようだ」と言っており，呼吸は落ち着いている。このときの介護福祉士の対応に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"出血していそうなところに吸引チューブをとどめる。"},{"id":"2","text":"吸引圧を弱くして再度吸引をする。"},{"id":"3","text":"血液の混じりがなくなるまで繰り返し吸引をする。"},{"id":"4","text":"鼻腔と口腔の中を観察する。"},{"id":"5","text":"鼻腔内を消毒する。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！吸引物に血液が混じっていたら、まず、鼻腔と口腔の中を観察して、出血の状態を確認することが大切なんだ。1は出血部位にチューブをとどめると傷を広げる。2、3は繰り返す吸引は粘膜をさらに傷つける。5は消毒は介護福祉士が判断して行うことではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-112","examYear":"2020","examRound":"32","questionNumber":112,"category":"医療的ケア","questionText":"口腔内・鼻腔内の喀痰吸引に必要な物品の管理に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"吸引チューブの保管方法のうち，乾燥法では，浸漬法に比べて短時間で細菌が死滅する。"},{"id":"2","text":"浸漬法で用いる消毒液は，72時間を目安に交換する。"},{"id":"3","text":"吸引チューブの洗浄には，アルコール消毒液を用いる。"},{"id":"4","text":"吸引チューブの洗浄水は，24時間を目安に交換する。"},{"id":"5","text":"吸引物は，吸引びんの70～80％になる前に廃棄する。"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！吸引物は、吸引びんの70〜80%になる前に、廃棄することになっているんだ。いっぱいになるまで使うと、吸引器の故障や、逆流の原因になるよ。1は浸漬法のほうが乾燥法より時間がかかる。2は浸漬法の消毒液は24時間を目安に交換。3は洗浄には水道水を使う。4は洗浄水も24時間を目安に交換するよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-113","examYear":"2020","examRound":"32","questionNumber":113,"category":"医療的ケア","questionText":"経管栄養の実施時に，冷蔵庫に保管していた栄養剤を指示どおりの温度にせずにそのまま注入したときに起こる状態として，最も可能性の高いものを1つ選びなさい。","choices":[{"id":"1","text":"呼吸困難"},{"id":"2","text":"胃ろう周囲のびらん"},{"id":"3","text":"下痢"},{"id":"4","text":"褥瘡（じょくそう）"},{"id":"5","text":"低血糖"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！冷たいままの栄養剤を注入すると、腸が刺激されて、下痢を起こしやすいんだ。1の呼吸困難、2の胃ろう周囲のびらん、4の褥瘡、5の低血糖は、温度の管理不足が、直接の原因になるものではないよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-114","examYear":"2020","examRound":"32","questionNumber":114,"category":"総合問題","questionText":"（事例）Ｌさん（78歳，女性）は一人暮らしをしている。「もったいない」が口癖で，物を大切にし，食べ物を残さないようにして生活している。半年前，脳の細い血管が詰まっていることがわかり，入院して治療を受けた。左半身にしびれがあり，右膝の変形性関節症（osteoarthritis）で痛みもあったために，介護保険の申請をしたところ，要介護1になった。家事はできるだけ自分でしたいという希望から，週に2回，訪問介護（ホームヘルプサービス）を利用して，掃除と調理を訪問介護員（ホームヘルパー）と一緒にしている。\nＬさんが入院するきっかけになった脳の疾患として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"ラクナ梗塞（lacunar infarction）"},{"id":"2","text":"くも膜下出血（subarachnoid hemorrhage）"},{"id":"3","text":"慢性硬膜下血腫（chronic subdural hematoma）"},{"id":"4","text":"正常圧水頭症（normal pressure hydrocephalus）"},{"id":"5","text":"高次脳機能障害（higher brain dysfunction）"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！Ｌさんは、脳の「細い血管」が詰まったと説明を受けているよね。細い血管が詰まって、小さな範囲の脳梗塞が起こる病気は、ラクナ梗塞なんだ。2のくも膜下出血、3の慢性硬膜下血腫、4の正常圧水頭症は、血管の詰まりとはちがう病態。5の高次脳機能障害は病名ではなく後遺症の総称だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-115","examYear":"2020","examRound":"32","questionNumber":115,"category":"総合問題","questionText":"ある日，Ｌさんと一緒に調理していた訪問介護員（ホームヘルパー）は，賞味期限が2日前に切れた缶詰を見つけた。Ｌさんに対して訪問介護員（ホームヘルパー）がとる行動として，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"黙って処分する。"},{"id":"2","text":"食べてはいけないと伝える。"},{"id":"3","text":"食べやすいように，缶のふたを開けておく。"},{"id":"4","text":"食べ方を相談する。"},{"id":"5","text":"保存容器に移して保管するように勧める。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！賞味期限が少し切れているだけの缶詰は、すぐに食べられなくなるとは限らないから、Ｌさんと一緒に、食べ方を相談するのがよいんだ。「もったいない」というＬさんの大切にしている価値観も、尊重できるよ。1は無断で処分している。2は決めつけている。3、5は安全性を確かめずに食べる方向に進めてしまうんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-116","examYear":"2020","examRound":"32","questionNumber":116,"category":"総合問題","questionText":"介護保険の申請をしてから半年がたち，更新申請の時期になった。この半年でＬさんは，訪問介護員（ホームヘルパー）が来ない日もいすに座って調理をするなど，回復してきている。更新申請の結果，Ｌさんは要支援1になった。次のうち，Ｌさんの介護予防サービス・支援計画書を作成する者として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"訪問介護事業所の訪問介護員（ホームヘルパー）"},{"id":"2","text":"生活支援体制整備事業の生活支援コーディネーター"},{"id":"3","text":"地域包括支援センターの主任介護支援専門員"},{"id":"4","text":"訪問介護事業所のサービス提供責任者"},{"id":"5","text":"生活介護のサービス管理責任者"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！要支援になった人の介護予防サービス・支援計画書は、地域包括支援センターの主任介護支援専門員（保健師など）が作成するんだ。1のホームヘルパーと4のサービス提供責任者は訪問介護の実施者。2の生活支援コーディネーターは地域資源の調整役。5のサービス管理責任者は障害福祉サービスの職種だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-117","examYear":"2020","examRound":"32","questionNumber":117,"category":"総合問題","questionText":"（事例）Ｍさん（80歳，男性）は，2年前にアルツハイマー型認知症（dementia of the Alzheimerʼs type）と診断された。Ｍさんは自宅で暮らし続けることを希望して，介護保険サービスを利用しながら妻と二人で生活していた。その後，Ｍさんの症状が進行して妻の介護負担が大きくなったため，Ｍさんは，Ｕ社会福祉法人が運営する介護老人福祉施設に入所することになった。Ｍさんの入所当日，担当のＡ介護福祉職は，生活相談員が作成した生活歴や家族構成などの基本情報の記録を事前に確認した上で，Ｍさんと関わった。\n次のうち，Ａ介護福祉職が確認した記録として，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"施設サービス計画書"},{"id":"2","text":"インシデント報告書"},{"id":"3","text":"エコマップ"},{"id":"4","text":"プロセスレコード"},{"id":"5","text":"フェイスシート"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！生活歴や家族構成などの基本情報をまとめた記録は、フェイスシートと呼ばれるんだ。1の施設サービス計画書は支援の計画、2のインシデント報告書はヒヤリハットの記録、3のエコマップは人や機関との関係図、4のプロセスレコードはコミュニケーションの記録で、それぞれちがう記録だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-118","examYear":"2020","examRound":"32","questionNumber":118,"category":"総合問題","questionText":"入所当日の昼食後，Ａ介護福祉職はＭさんに歯ブラシと歯磨き粉を渡して，歯磨きを促した。しかし，Ｍさんは歯ブラシと歯磨き粉を持ったまま，不安そうな顔で歯を磨こうとしなかった。このときのＭさんの症状に該当するものとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"幻視"},{"id":"2","text":"失行"},{"id":"3","text":"振戦"},{"id":"4","text":"脱抑制"},{"id":"5","text":"常同行動"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！道具（歯ブラシと歯磨き粉）は持っているのに、それをどう使えばよいかわからず、戸惑っているのは、失行（道具をうまく使えない症状）の特徴なんだ。1の幻視、3の振戦、4の脱抑制、5の常同行動は、Ｍさんのこの場面の様子とは、ちがう症状だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-119","examYear":"2020","examRound":"32","questionNumber":119,"category":"総合問題","questionText":"面会に訪れた妻はＡ介護福祉職に，「最初は夫を施設に入れて申し訳ない気持ちもあったが，元気そうな夫を見て，今はこの施設を利用してよかったと思っている」と話した。Ａ介護福祉職は妻の発言を受けて，介護サービスをもっと気軽に利用してもらうための取り組みが必要であると考えた。そこで，Ａ介護福祉職は施設職員と検討した。その結果，地域の家族介護者を対象に，介護に関する情報提供や交流を図る場を無料で提供することを，独自の事業として継続的に行うことを法人として決定した上で，必要な手続きを行うこととした。Ｕ社会福祉法人が行うこととした事業に該当するものとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"公益事業"},{"id":"2","text":"日常生活自立支援事業"},{"id":"3","text":"相談支援事業"},{"id":"4","text":"自立相談支援事業"},{"id":"5","text":"地域生活支援事業"}],"correctChoice":"1","correctChoices":["1"],"explanation":"正解は1だよ！社会福祉法人は、本来の介護サービス（社会福祉事業）のほかに、地域のために、無料または低額で行う、公益事業を実施できるんだ。2の日常生活自立支援事業は社会福祉協議会、3の相談支援事業や5の地域生活支援事業は障害福祉の事業、4の自立相談支援事業は生活困窮者支援の事業だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-120","examYear":"2020","examRound":"32","questionNumber":120,"category":"総合問題","questionText":"（事例）Ｂさん（22歳，男性）は，19歳の時に統合失調症（schizophrenia）を発症し，精神保健指定医の診察の結果，入院の必要があると診断された。Ｂさん自身からは入院の同意が得られず，父親の同意で精神科病院に入院した。その後，数回の入退院を繰り返した後，21歳から居宅介護を週1回，訪問看護を月2回，デイケアを週3回利用しながら一人暮らしをしている。居宅介護では，料理や掃除，買物などの介護福祉職の支援を受けているが，Ｂさんも調子の良いときは一緒に行っている。訪問看護では，Ｂさんは，服薬を忘れることがあるため，看護師と一緒に薬の飲み忘れがないかを確認している。また，デイケアでは，運動と園芸のグループに参加している。\nＢさんが19歳で精神科病院に入院したときの入院形態として，正しいものを1つ選びなさい。","choices":[{"id":"1","text":"任意入院"},{"id":"2","text":"医療保護入院"},{"id":"3","text":"応急入院"},{"id":"4","text":"措置入院"},{"id":"5","text":"緊急措置入院"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！Ｂさんは、精神保健指定医が入院の必要を認めたけれど、本人の同意は得られず、家族（父親）の同意で入院したよね。これは、医療保護入院にあたるんだ。1の任意入院は本人の同意、3の応急入院と5の緊急措置入院は家族の同意が得られない緊急時、4の措置入院は都道府県知事などの決定によるものだよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-121","examYear":"2020","examRound":"32","questionNumber":121,"category":"総合問題","questionText":"Ｂさんは，居宅介護のＣ介護福祉職にはデイケアや生活のことについて安心して話すようになってきた。ある日，Ｃ介護福祉職が掃除をしていて，薬が2週間分内服されていないことを見つけた。また，Ｂさんは，「Ｃさんにだけ話します。みんなが私の悪口を言って，電波を飛ばして監視しています」とおびえながら話した。話を聞いたＣ介護福祉職のＢさんに対する最初の言葉かけとして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"「今すぐ薬を飲んでください」"},{"id":"2","text":"「悪口の内容を詳しく教えてください」"},{"id":"3","text":"「薬を飲んでいないからですよ」"},{"id":"4","text":"「医師に話しておきますね」"},{"id":"5","text":"「それは不安ですね」"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｂさんは、監視されているという、不安な気持ちを、おびえながら話しているよね。まずは、「それは不安ですね」と、Ｂさんの気持ちをそのまま受け止める言葉かけがよいんだ。1、3は否定や指摘でＢさんを追い詰める。2は妄想の内容を深掘りしてしまう。4はＢさんの気持ちに向き合わず話をそらしているよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":false},{"id":"2020-32-122","examYear":"2020","examRound":"32","questionNumber":122,"category":"総合問題","questionText":"Ｂさんは，Ｃ介護福祉職と話したことをきっかけに，定期的に服薬できるようになり，以前と同じ支援を受けながら一人暮らしを続けている。最近は，デイケアで就労を目指すグループ活動に自ら参加するようになった。Ｂさんは，「就労に挑戦してみたい」という気持ちはあるが，就労経験のある他のメンバーの失敗談を聞くと，「自信がない」とも言っている。Ｂさんへの支援に関する次の記述のうち，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"自分で料理と掃除ができるようになることが優先であると話す。"},{"id":"2","text":"服薬ができなかったことを取り上げ，治療に専念するように話す。"},{"id":"3","text":"無理せず，今の生活を維持することが大切であると話す。"},{"id":"4","text":"長所を一緒に探し，どのような仕事が向いているのかを考えようと話す。"},{"id":"5","text":"他のメンバーの失敗原因を考え，失敗しない対策をしようと話す。"}],"correctChoice":"4","correctChoices":["4"],"explanation":"正解は4だよ！Ｂさんは、就労に挑戦したい気持ちと、自信のなさの両方を抱えているよね。長所を一緒に探して、向いている仕事を考えることは、Ｂさんの気持ちを尊重しながら、前向きに支える対応なんだ。1、2、3はＢさんの希望を後回しにしている。5は失敗を意識させすぎて不安を強めてしまうよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-123","examYear":"2020","examRound":"32","questionNumber":123,"category":"総合問題","questionText":"（事例）Ｄさん（59歳，女性）は30年前に関節リウマチ（rheumatoid arthritis）を発症して，現在，障害者支援施設に入所している。Ｄさんは，朝は手の動きが悪く痛みがあるが，午後，痛みが少ないときは関節を動かす運動を行っている。足の痛みで歩くのが難しく車いすを使用しているが，最近は手の痛みが強くなり，自分で操作することが難しい。また，食欲がなく，この1か月間で体重が2kg減っている。夜中に目が覚めてしまうこともある。\nＤさんの朝の症状の原因として，最も可能性が高いものを1つ選びなさい。","choices":[{"id":"1","text":"睡眠不足"},{"id":"2","text":"低栄養"},{"id":"3","text":"平衡感覚の低下"},{"id":"4","text":"筋力低下"},{"id":"5","text":"関節の炎症"}],"correctChoice":"5","correctChoices":["5"],"explanation":"正解は5だよ！Ｄさんは、朝、手の動きが悪く、痛みがあるよね。これは、関節リウマチの特徴である、朝のこわばりや、関節の炎症によるものなんだ。1の睡眠不足、2の低栄養、3の平衡感覚の低下、4の筋力低下は、朝に症状が強く出る理由としては、関節の炎症ほど直接的ではないんだ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-124","examYear":"2020","examRound":"32","questionNumber":124,"category":"総合問題","questionText":"使っていた車いすを自分で操作することが困難になったＤさんが，「障害者総合支援法」で電動車いすを購入するときに利用できるものとして，適切なものを1つ選びなさい。","choices":[{"id":"1","text":"介護給付費"},{"id":"2","text":"補装具費"},{"id":"3","text":"自立支援医療費"},{"id":"4","text":"訓練等給付費"},{"id":"5","text":"相談支援給付費"}],"correctChoice":"2","correctChoices":["2"],"explanation":"正解は2だよ！電動車いすは、体の一部として長く使う、補装具にあたるから、補装具費の支給を利用して購入するんだ。1の介護給付費は介護サービスの費用、3の自立支援医療費は医療費の助成、4の訓練等給付費は訓練系のサービス費用、5の相談支援給付費は相談支援の費用だよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true},{"id":"2020-32-125","examYear":"2020","examRound":"32","questionNumber":125,"category":"総合問題","questionText":"Ｄさんは，「ここ数日，朝だけでなく1日中，何もしないのに手足の痛みが強くなってきた」と訴えている。日常生活で，Ｄさんが当面留意すべきこととして，最も適切なものを1つ選びなさい。","choices":[{"id":"1","text":"前あきの衣類より，かぶりの衣類を選ぶ。"},{"id":"2","text":"ベッドのマットレスは，柔らかいものを使用する。"},{"id":"3","text":"関節を動かす運動を控える。"},{"id":"4","text":"できるだけ低いいすを使う。"},{"id":"5","text":"頸部(けいぶ)が屈曲位になるように，高めの枕を使用する。"}],"correctChoice":"3","correctChoices":["3"],"explanation":"正解は3だよ！Ｄさんは、関節の炎症が、1日中強くなってきているね。こういうときは、関節を安静にして、負担をかけないよう、動かす運動を控えるのが、当面の対応なんだ。1はかぶりの衣類は腕を大きく動かす必要があり負担が大きい。2は柔らかいマットレスは起き上がりに負担がかかる。4は低いいすは立ち座りで関節に負担がかかる。5は頸部を強く曲げる高い枕は負担になるよ。","source":"公益財団法人 社会福祉振興・試験センター 第32回（令和元年度）介護福祉士国家試験; 問題: ユーザー提供CSV; 正答: https://www.sssc.or.jp/kaigo/past_exam/","keywords":[],"needsLegalReview":true}] satisfies Question[];
